    check_s3_iob_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s3_iob_write == m_iob_write
    );

// q must be 0 whenever reset is asserted (active-low).
    check_reset_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (q == 6'b0)
    );

// On a falling edge of reset, q is 0 at this clock sample.
    check_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(reset) |-> (q == 6'b0)
    );

// On a rising edge of reset, q is 0 at this clock sample.
    check_zero_on_reset_rise_sample: assert property (
        @(posedge clk) $rose(reset) |-> (q == 6'b0)
    );

// With reset high in consecutive cycles, q equals last cycle's d.
    check_capture_d_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (q == $past(d))
    );

// First clock after reset release captures the d value from the release cycle.
    check_first_cycle_after_release_captures_d: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> ##1 (q == $past(d))
    );

// If d held constant over the last two cycles (no reset), q does not change.
    check_stability_when_d_unchanged: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset,2) && $past(reset) && ($past(d) == $past(d,2))) |-> (q == $past(q))
    );

// If q changes (no reset), the change was caused by a change in d in the prior cycle.
    check_q_change_requires_d_change: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset,2) && $past(reset) && (q != $past(q))) |-> ($past(d) != $past(d,2))
    );

// When reset is high, next cycle's q equals this cycle's d (if reset stays high).
    check_next_cycle_captures_d_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) reset |-> ##1 (q == $past(d))
    );

// r0 is XOR of r1 and r2.
    check_r0_xor: assert property (
        @(posedge clk) r0 == (r1 ^ r2)
    );

// When both r1 and r2 are LOW, outputs are LOW.
    check_both_low_behavior: assert property (
        @(posedge clk) (r1 == 1'b0 && r2 == 1'b0) |-> (r0 == 1'b0 && a0 == 1'b0)
    );

// When only r1 is HIGH, r0 is HIGH and a0 passes a1.
    check_r1_only_behavior: assert property (
        @(posedge clk) (r1 == 1'b1 && r2 == 1'b0) |-> (r0 == 1'b1 && a0 == a1)
    );

// When only r2 is HIGH, r0 is HIGH and a0 passes a2.
    check_r2_only_behavior: assert property (
        @(posedge clk) (r1 == 1'b0 && r2 == 1'b1) |-> (r0 == 1'b1 && a0 == a2)
    );

// When both r1 and r2 are HIGH, outputs are LOW.
    check_both_high_behavior: assert property (
        @(posedge clk) (r1 == 1'b1 && r2 == 1'b1) |-> (r0 == 1'b0 && a0 == 1'b0)
    );

// If r0 is LOW, a0 must be LOW.
    check_r0_low_implies_a0_low: assert property (
        @(posedge clk) (r0 == 1'b0) |-> (a0 == 1'b0)
    );

// a0 can be HIGH only when exactly one request is HIGH.
    check_a0_high_only_if_one_req: assert property (
        @(posedge clk) (a0 == 1'b1) |-> (r1 ^ r2)
    );

// On r1 rising when r2 is LOW, r0 is HIGH and a0 passes a1.
    check_rise_r1_when_r2_low: assert property (
        @(posedge clk) ($rose(r1) && (r2 == 1'b0)) |-> (r0 == 1'b1 && a0 == a1)
    );

// On r2 rising when r1 is LOW, r0 is HIGH and a0 passes a2.
    check_rise_r2_when_r1_low: assert property (
        @(posedge clk) ($rose(r2) && (r1 == 1'b0)) |-> (r0 == 1'b1 && a0 == a2)
    );

// On r1 falling when r2 is HIGH, r0 is HIGH and a0 passes a2.
    check_fall_r1_when_r2_high: assert property (
        @(posedge clk) ($fell(r1) && (r2 == 1'b1)) |-> (r0 == 1'b1 && a0 == a2)
    );

// Q must change every cycle (never holds its value).
    check_q_always_changes: assert property (
        @(posedge clk) 1'b1 |=> $changed(Q)
    );

// The magnitude of the step each cycle is exactly 1 (mod 16).
    check_delta_one: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) || (Q == $past(Q) - 4'd1) )
    );

// Exactly one of +1 or -1 delta holds each cycle.
    check_delta_exclusive: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) != (Q == $past(Q) - 4'd1) )
    );

// LSB toggles every cycle due to +/-1 operation.
    check_lsb_toggle: assert property (
        @(posedge clk) 1'b1 |=> ( Q[0] != $past(Q[0]) )
    );

///// Functional correctness /////
    // When S==0, C must equal A + B (4-bit wrap).
    check_add_mode_correct: assert property (
        @(posedge clk) (S == 1'b0) |-> (C == (A + B))
    );

// When S==1, C must equal A - B (4-bit wrap).
    check_sub_mode_correct: assert property (
        @(posedge clk) (S == 1'b1) |-> (C == (A - B))
    );

///// X-propagation /////
    // If A,B,S are all known (no X/Z), then C must be known.
    check_known_output_with_known_inputs: assert property (
        @(posedge clk) (!$isunknown({A,B,S})) |-> (!$isunknown(C))
    );

///// Algebraic identities (direct consequences of + and -) /////
    // In add mode, adding zero B passes A through.
    check_add_zero_B_passthru: assert property (
        @(posedge clk) (S == 1'b0 && B == 4'h0) |-> (C == A)
    );

// In add mode, adding zero A passes B through.
    check_add_zero_A_passthru: assert property (
        @(posedge clk) (S == 1'b0 && A == 4'h0) |-> (C == B)
    );

// In sub mode, subtracting zero B passes A through.
    check_sub_zero_B_passthru: assert property (
        @(posedge clk) (S == 1'b1 && B == 4'h0) |-> (C == A)
    );

// In sub mode, subtracting equal operands yields zero.
    check_sub_equal_inputs_zero: assert property (
        @(posedge clk) (S == 1'b1 && A == B) |-> (C == 4'h0)
    );

// No clock/reset in DUT; combinational. Assertions sample on external clk with no reset gating.
    // Behavior: EQ iff A==B, GT iff A>B, LT iff A<B; exactly one output is HIGH.

    // Outputs EQ and GT are mutually exclusive.
    check_mutex_eq_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

// Outputs EQ and LT are mutually exclusive.
    check_mutex_eq_lt: assert property (
        @(posedge clk) !(EQ && LT)
    );

// Outputs GT and LT are mutually exclusive.
    check_mutex_gt_lt: assert property (
        @(posedge clk) !(GT && LT)
    );

// At least one of EQ/GT/LT must be HIGH.
    check_not_all_zero: assert property (
        @(posedge clk) (EQ || GT || LT)
    );

// When A equals B, outputs reflect equality.
    check_map_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// When A is greater than B, outputs reflect greater-than.
    check_map_greater: assert property (
        @(posedge clk) (A > B) |-> (!EQ && GT && !LT)
    );

// When A is less than B, outputs reflect less-than.
    check_map_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT && LT)
    );

// If EQ is HIGH, inputs must be equal.
    check_eq_implies_relation: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// If GT is HIGH, A must be greater than B.
    check_gt_implies_relation: assert property (
        @(posedge clk) GT |-> (A > B)
    );

// If LT is HIGH, A must be less than B.
    check_lt_implies_relation: assert property (
        @(posedge clk) LT |-> (A < B)
    );

// On a clock where reset=1, q must be 0 on the next clock.
    check_reset_to_zero_next: assert property (
        @(posedge clk) reset |=> (q == 4'd0)
    );

// While reset is held high across clocks, q stays 0.
    check_reset_held_forces_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'd0)
    );

// X equals A0 when S=0, else A1 (functional equivalence).
    check_mux_truth_table: assert property (
        @(posedge clk) X == ((S == 1'b0) ? A0 : A1)
    );

// When S=0 and A0 changes (others stable), X must equal A0.
    check_selected_change_reflected_S0: assert property (
        @(posedge clk) (S == 1'b0) && $changed(A0) && $stable(A1) && $stable(S) |-> (X == A0)
    );

// When S=1 and A1 changes (others stable), X must equal A1.
    check_selected_change_reflected_S1: assert property (
        @(posedge clk) (S == 1'b1) && $changed(A1) && $stable(A0) && $stable(S) |-> (X == A1)
    );

// On S rising edge, X must equal A1.
    check_select_rise_routes_A1: assert property (
        @(posedge clk) $rose(S) |-> (X == A1)
    );

// On S falling edge, X must equal A0.
    check_select_fall_routes_A0: assert property (
        @(posedge clk) $fell(S) |-> (X == A0)
    );

// If A0 equals A1, X must equal that value regardless of S.
    check_equal_inputs_drive_x: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

///// Functional equivalence to RTL /////
    // SUM equals the 16-bit truncated result of A + B + CIN.
    check_sum_matches_add: assert property (
        @(posedge CLK) SUM == (A + B + CIN)
    );

///// Basic pass-through scenarios /////
    // With B==0 and CIN==0, SUM passes A and COUT stays zero.
    check_pass_through_a: assert property (
        @(posedge CLK) (B == 16'h0000) && (CIN == 1'b0) |-> (SUM == A) && (COUT == 1'b0)
    );

// With A==0 and CIN==0, SUM passes B and COUT stays zero.
    check_pass_through_b: assert property (
        @(posedge CLK) (A == 16'h0000) && (CIN == 1'b0) |-> (SUM == B) && (COUT == 1'b0)
    );

// With A==0 and B==0, SUM equals CIN and COUT stays zero.
    check_only_cin: assert property (
        @(posedge CLK) (A == 16'h0000) && (B == 16'h0000) |-> (SUM == {15'b0, CIN}) && (COUT == 1'b0)
    );

///// Bit-level consequence /////
    // LSB of SUM equals parity of LSBs and CIN for 16-bit addition.
    check_sum_bit0_parity: assert property (
        @(posedge CLK) SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

///// Commutativity reflection /////
    // The computed SUM is commutative in A and B.
    check_sum_commutative: assert property (
        @(posedge CLK) (A + B + CIN) == (B + A + CIN)
    );

///// Block-generate definitions /////
    // bg[0] equals g[3] | p[3]&g[2] | p[3]&p[2]&g[1] | p[3]&p[2]&p[1]&g[0]
    check_bg0_definition: assert property (
        @(posedge clk) bg[0] == ( g[3]
                               | (p[3] & g[2])
                               | (p[3] & p[2] & g[1])
                               | (p[3] & p[2] & p[1] & g[0]) )
    );

// bg[1] equals g[7] | p[7]&g[6] | p[7]&p[6]&g[5] | p[7]&p[6]&p[5]&g[4]
    check_bg1_definition: assert property (
        @(posedge clk) bg[1] == ( g[7]
                               | (p[7] & g[6])
                               | (p[7] & p[6] & g[5])
                               | (p[7] & p[6] & p[5] & g[4]) )
    );

///// Block-propagate definitions /////
    // bp[0] equals p[3]&p[2]&p[1]&p[0]
    check_bp0_definition: assert property (
        @(posedge clk) bp[0] == (p[3] & p[2] & p[1] & p[0])
    );

// bp[1] equals p[7]&p[6]&p[5]&p[4]
    check_bp1_definition: assert property (
        @(posedge clk) bp[1] == (p[7] & p[6] & p[5] & p[4])
    );

// bp[2] equals p[11]&p[10]&p[9]&p[8]
    check_bp2_definition: assert property (
        @(posedge clk) bp[2] == (p[11] & p[10] & p[9] & p[8])
    );

// bp[3] equals p[15]&p[14]&p[13]&p[12]
    check_bp3_definition: assert property (
        @(posedge clk) bp[3] == (p[15] & p[14] & p[13] & p[12])
    );

///// Necessary conditions for block-generate /////
    // If bg[0] is 1, at least one g in [3:0] is 1.
    check_bg0_implies_some_g: assert property (
        @(posedge clk) bg[0] |-> (g[3] || g[2] || g[1] || g[0])
    );

// If bg[1] is 1, at least one g in [7:4] is 1.
    check_bg1_implies_some_g: assert property (
        @(posedge clk) bg[1] |-> (g[7] || g[6] || g[5] || g[4])
    );

// If bg[2] is 1, at least one g in [11:8] is 1.
    check_bg2_implies_some_g: assert property (
        @(posedge clk) bg[2] |-> (g[11] || g[10] || g[9] || g[8])
    );

// If bg[3] is 1, at least one g in [15:12] is 1.
    check_bg3_implies_some_g: assert property (
        @(posedge clk) bg[3] |-> (g[15] || g[14] || g[13] || g[12])
    );

// Load updates data_out with data_in on next cycle.
    check_load_updates_data_out: assert property (
        @(posedge clk) disable iff (reset) (past_valid && load) |=> (data_out == $past(data_in))
    );

// Load has priority over any shift signals.
    check_load_priority_over_shifts: assert property (
        @(posedge clk) disable iff (reset) (past_valid && load && (shift_left || shift_right)) |=> (data_out == $past(data_in))
    );

// Shift-left updates data_out with left-shifted previous value, LSB filled with 0.
    check_shift_left_updates: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out == { $past(data_out[14:0]), 1'b0 })
    );

// Shift-left inserts 0 into bit 0.
    check_shift_left_inserts_zero_lsb: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out[0] == 1'b0)
    );

// Shift-left moves bits [14:0] into [15:1].
    check_shift_left_moves_upper_bits: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out[15:1] == $past(data_out[14:0]))
    );

// Shift-right updates data_out with right-shifted previous value, MSB filled with 0.
    check_shift_right_updates: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out == { 1'b0, $past(data_out[15:1]) })
    );

// Shift-right inserts 0 into bit 15.
    check_shift_right_inserts_zero_msb: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out[15] == 1'b0)
    );

// Shift-right moves bits [15:1] into [14:0].
    check_shift_right_moves_lower_bits: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out[14:0] == $past(data_out[15:1]))
    );

// When both shifts are asserted (no load), left shift takes priority.
    check_shift_conflict_left_wins: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left && shift_right) |=> (data_out == { $past(data_out[14:0]), 1'b0 })
    );

// With no operation requested, data_out holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && !shift_right) |=> (data_out == $past(data_out))
    );

///// Gate-level correctness /////
    // not_B1_N is the inversion of B1_N.
    check_not_B1N_inversion: assert property (
        @(posedge CLK) not_B1_N == ~B1_N
    );

// and0_out is A1 AND A2.
    check_and0_function: assert property (
        @(posedge CLK) and0_out == (A1 & A2)
    );

// and1_out is not_B1_N AND and0_out.
    check_and1_function: assert property (
        @(posedge CLK) and1_out == (not_B1_N & and0_out)
    );

// or0_out is A1 OR A2.
    check_or0_function: assert property (
        @(posedge CLK) or0_out == (A1 | A2)
    );

// nand0_out_Y is NAND of and1_out and or0_out.
    check_nand0_function: assert property (
        @(posedge CLK) nand0_out_Y == ~(and1_out & or0_out)
    );

// Y is a buffered version of nand0_out_Y.
    check_buf_to_Y: assert property (
        @(posedge CLK) Y == nand0_out_Y
    );

///// Functional equivalence and implications on top-level ports /////
    // Y equals (B1_N | ~A1 | ~A2) (simplified function).
    check_simplified_function: assert property (
        @(posedge CLK) Y == (B1_N | ~A1 | ~A2)
    );

// When sel==000, out equals in0.
    check_mux_sel_000: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b000) |-> (out == in0)
    );

// When sel==001, out equals in1.
    check_mux_sel_001: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b001) |-> (out == in1)
    );

// When sel==010, out equals in2.
    check_mux_sel_010: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b010) |-> (out == in2)
    );

// When sel==011, out equals in3.
    check_mux_sel_011: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b011) |-> (out == in3)
    );

// When sel==100, out equals in4.
    check_mux_sel_100: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b100) |-> (out == in4)
    );

// For sel 101/110/111, out is 0.
    check_mux_invalid_sel_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel inside {3'b101,3'b110,3'b111}) |-> (out == 1'b0)
    );

// Out equals the RTL conditional chain.
    check_mux_function_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn)
            out == ((sel == 3'b000) ? in0 :
                    (sel == 3'b001) ? in1 :
                    (sel == 3'b010) ? in2 :
                    (sel == 3'b011) ? in3 :
                    (sel == 3'b100) ? in4 :
                    1'b0)
    );

///// Reset behavior /////
    // During reset, registers and outputs are driven to zero.
    reset_clears_state_and_output: assert property (
        @(posedge clk) reset |-> (reg1 == 8'd0) && (reg2 == 8'd0) && (diff == 8'd0) && (q == 8'd0)
    );

///// Reset behavior /////
    // On any clock where rst is HIGH, count must be 0.
    check_reset_sets_zero: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

///// Up/Down counting /////
    // With rst LOW and up_down HIGH, next count = current + 1 (mod 16).
    check_increment_on_up: assert property (
        @(posedge clk) disable iff (rst) up_down |-> ##1 (count == ($past(count) + 4'b0001))
    );

// With rst LOW and up_down LOW, next count = current - 1 (mod 16).
    check_decrement_on_down: assert property (
        @(posedge clk) disable iff (rst) !up_down |-> ##1 (count == ($past(count) - 4'b0001))
    );

// Increment wrap: at 0xF with up_down HIGH, next count wraps to 0x0.
    check_wrap_inc_from_max: assert property (
        @(posedge clk) disable iff (rst) (up_down && (count == 4'hF)) |-> ##1 (count == 4'h0)
    );

// Decrement wrap: at 0x0 with up_down LOW, next count wraps to 0xF.
    check_wrap_dec_from_min: assert property (
        @(posedge clk) disable iff (rst) (!up_down && (count == 4'h0)) |-> ##1 (count == 4'hF)
    );

// Y equals A when no shift selected (B==00).
    check_no_shift_mapping: assert property (
        @(posedge clk) (B == 2'b00) |-> (Y == A)
    );

// Y equals A shifted left by 1 with zero-fill when B==01.
    check_shift_left1_mapping: assert property (
        @(posedge clk) (B == 2'b01) |-> (Y == {A[2:0], 1'b0})
    );

// Y equals A shifted right by 1 with zero-fill when B==10.
    check_shift_right1_mapping: assert property (
        @(posedge clk) (B == 2'b10) |-> (Y == {1'b0, A[3:1]})
    );

// Y equals A shifted right by 2 with zero-fill when B==11.
    check_shift_right2_mapping: assert property (
        @(posedge clk) (B == 2'b11) |-> (Y == {2'b00, A[3:2]})
    );

// For left shift by 1, LSB is zero-filled.
    check_shift_left1_zero_lsb: assert property (
        @(posedge clk) (B == 2'b01) |-> (Y[0] == 1'b0)
    );

// For right shift by 1, MSB is zero-filled.
    check_shift_right1_zero_msb: assert property (
        @(posedge clk) (B == 2'b10) |-> (Y[3] == 1'b0)
    );

// For right shift by 2, two MSBs are zero-filled.
    check_shift_right2_zero_msbs: assert property (
        @(posedge clk) (B == 2'b11) |-> (Y[3:2] == 2'b00)
    );

// For left shift by 1, upper bits map from A[2:0].
    check_shift_left1_upper_map: assert property (
        @(posedge clk) (B == 2'b01) |-> (Y[3:1] == A[2:0])
    );

// For right shift by 1, lower bits map from A[3:1].
    check_shift_right1_lower_map: assert property (
        @(posedge clk) (B == 2'b10) |-> (Y[2:0] == A[3:1])
    );

// For right shift by 2, lower two bits map from A[3:2].
    check_shift_right2_lower_map: assert property (
        @(posedge clk) (B == 2'b11) |-> (Y[1:0] == A[3:2])
    );

///// Functional correctness (combinational, sampled on clk) /////
    // Outputs equal zero-extended 4-bit sum per LRM sizing of A+B+Cin.
    check_sum_zero_extended: assert property (
        @(posedge clk) disable iff (1'b0) {Cout, S} == (A + B + Cin)
    );

// S equals 4-bit sum of A, B, and Cin.
    check_sum_low4: assert property (
        @(posedge clk) disable iff (1'b0) S == (A + B + Cin)
    );

// All-zero inputs produce all-zero outputs.
    check_all_zero_input: assert property (
        @(posedge clk) disable iff (1'b0) (A == 4'b0 && B == 4'b0 && Cin == 1'b0) |-> ({Cout, S} == 5'b0)
    );

// Adding zero to B with Cin=0 yields S=A and Cout=0.
    check_identity_B0_C0: assert property (
        @(posedge clk) disable iff (1'b0) (B == 4'b0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero to A with Cin=0 yields S=B and Cout=0.
    check_identity_A0_C0: assert property (
        @(posedge clk) disable iff (1'b0) (A == 4'b0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

// LSB of S is XOR of input LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ Cin)
    );

///// Exact decode checks for instructions without Xs /////
    // For 000000, outputs must match 10'b0100_100_010.
    decode_rtype: assert property (
        @(posedge clk) (instru == INSTR_RTYPE) |-> ({Saltoincond,RegDest,FuenteALU,MemaReg,EscrReg,LeerMem,EscrMem,SaltoCond,ALUOp} == 10'b0100_100_010)
    );

// For 100011, outputs must match 10'b00_1111_0000.
    decode_lw: assert property (
        @(posedge clk) (instru == INSTR_LW) |-> ({Saltoincond,RegDest,FuenteALU,MemaReg,EscrReg,LeerMem,EscrMem,SaltoCond,ALUOp} == 10'b00_1111_0000)
    );

// For 111111, outputs must match 10'b00_1010_0000.
    decode_111111: assert property (
        @(posedge clk) (instru == INSTR_111111) |-> ({Saltoincond,RegDest,FuenteALU,MemaReg,EscrReg,LeerMem,EscrMem,SaltoCond,ALUOp} == 10'b00_1010_0000)
    );

// For 111110, outputs must match 10'b00_0000_0101.
    decode_111110: assert property (
        @(posedge clk) (instru == INSTR_111110) |-> ({Saltoincond,RegDest,FuenteALU,MemaReg,EscrReg,LeerMem,EscrMem,SaltoCond,ALUOp} == 10'b00_0000_0101)
    );

///// Partial decode checks for instructions with Xs /////
    // For 101011, only defined bits: FUENTEALU=1, ESCRMEM=1, ALUOp=00, SALTOCOND=0, ESCRREG=0, LEERMEM=0, SALTOINCOND=0.
    decode_sw_defined_bits: assert property (
        @(posedge clk) (instru == INSTR_SW) |-> (FuenteALU == 1'b1) && (EscrMem == 1'b1) && (ALUOp == 2'b00) &&
                                           (SaltoCond == 1'b0) && (EscrReg == 1'b0) && (LeerMem == 1'b0) &&
                                           (Saltoincond == 1'b0)
    );

// For 000100, only defined bits: FUENTEALU=0, SALTOCOND=1, ALUOp=01, ESCRREG=0, LEERMEM=0, ESCRMEM=0, SALTOINCOND=0.
    decode_beq_defined_bits: assert property (
        @(posedge clk) (instru == INSTR_BEQ) |-> (FuenteALU == 1'b0) && (SaltoCond == 1'b1) && (ALUOp == 2'b01) &&
                                         (EscrReg == 1'b0) && (LeerMem == 1'b0) && (EscrMem == 1'b0) &&
                                         (Saltoincond == 1'b0)
    );

///// Default decode for all other instructions /////
    // For instructions not listed, outputs must match default 10'b00_1010_0000.
    decode_default_others: assert property (
        @(posedge clk)
        (instru != INSTR_RTYPE) && (instru != INSTR_LW) && (instru != INSTR_SW) &&
        (instru != INSTR_BEQ) && (instru != INSTR_111110) && (instru != INSTR_111111)
        |-> ({Saltoincond,RegDest,FuenteALU,MemaReg,EscrReg,LeerMem,EscrMem,SaltoCond,ALUOp} == 10'b00_1010_0000)
    );

///// Global invariants derived from the decode /////
    // Saltoincond is always 0 for all decodes.
    invariant_saltoincond_zero: assert property (
        @(posedge clk) (Saltoincond == 1'b0)
    );

// If SaltoCond is 1, ALUOp must be 01 and FuenteALU must be 0.
    invariant_branch_flags: assert property (
        @(posedge clk) (SaltoCond == 1'b1) |-> (ALUOp == 2'b01) && (FuenteALU == 1'b0)
    );

// If ALUOp is 01, SaltoCond must be 1 and FuenteALU must be 0.
    invariant_aluop01_means_branch: assert property (
        @(posedge clk) (ALUOp == 2'b01) |-> (SaltoCond == 1'b1) && (FuenteALU == 1'b0)
    );

// If FuenteALU is 1, ALUOp must be 00.
    invariant_fuent_to_aluop: assert property (
        @(posedge clk) (FuenteALU == 1'b1) |-> (ALUOp == 2'b00)
    );

// If EscrMem is 1, then it's a store: FuenteALU=1, ALUOp=00, and no read/branch/regwrite.
    invariant_store_side_effects: assert property (
        @(posedge clk) (EscrMem == 1'b1) |-> (FuenteALU == 1'b1) && (ALUOp == 2'b00) &&
                                           (LeerMem == 1'b0) && (EscrReg == 1'b0) && (SaltoCond == 1'b0)
    );

// If LeerMem is 1, then it's a load: MemaReg=1, EscrReg=1, FuenteALU=1, ALUOp=00, and no store/branch.
    invariant_load_side_effects: assert property (
        @(posedge clk) (LeerMem == 1'b1) |-> (MemaReg == 1'b1) && (EscrReg == 1'b1) &&
                                          (EscrMem == 1'b0) && (SaltoCond == 1'b0) &&
                                          (FuenteALU == 1'b1) && (ALUOp == 2'b00)
    );

// If EscrReg is 1, then there is no branch or memory write.
    invariant_regwrite_no_branch_store: assert property (
        @(posedge clk) (EscrReg == 1'b1) |-> (SaltoCond == 1'b0) && (EscrMem == 1'b0)
    );

// If ALUOp is 10, it's R-type: RegDest=1, EscrReg=1, FUENTEALU=0, no mem or branch.
    invariant_aluop10_rtype: assert property (
        @(posedge clk) (ALUOp == 2'b10) |-> (RegDest == 1'b1) && (EscrReg == 1'b1) && (FuenteALU == 1'b0) &&
                                         (MemaReg == 1'b0) && (LeerMem == 1'b0) && (EscrMem == 1'b0) &&
                                         (SaltoCond == 1'b0)
    );

// When reset is asserted (low), count must be 0 at each clock edge.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst) |-> (count == 4'h0)
    );

// With reset deasserted in consecutive cycles, count increments by 1 each cycle (mod 16).
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (count == $past(count) + 4'd1)
    );

// When previous value was 15 and still enabled, next value wraps to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// Over two consecutive enabled cycles, count advances by 2 (mod 16).
    check_two_step_increment: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst,2) && $past(rst)) |-> (count == $past(count,2) + 4'd2)
    );

// On reset release ($rose), the next enabled cycle increments from the reset value.
    check_increment_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == $past(count) + 4'd1)
    );

// On reset assertion ($fell), count is driven to 0 at that clock edge.
    check_zero_on_reset_assertion: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'h0)
    );

// When enabled and not wrapping, next value cannot be 0.
    check_nonzero_when_not_wrapping: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) != 4'hF)) |-> (count != 4'h0)
    );

///// Functional equivalence /////
    // OUT implements (~SEL & A) | (SEL & B).
    check_functional_equation: assert property (
        @(posedge CLK) disable iff (1'b0) OUT == ((~SEL & A) | (SEL & B))
    );

// When SEL=0, OUT equals A.
    check_sel0_drives_A: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0) |-> (OUT == A)
    );

// When SEL=1, OUT equals B.
    check_sel1_drives_B: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1) |-> (OUT == B)
    );

// In functional mode, a rising wkup_event with clear deasserted sets wkup_out high.
    check_func_event_sets_one: assert property (
        @(posedge wkup_event) disable iff (wkup_clear)
            (scan_mode == 1'b0) |=> ##0 (wkup_out == 1'b1)
    );

// In functional mode, a rising wkup_event keeps wkup_out high if already high and not clearing.
    check_func_event_keeps_one: assert property (
        @(posedge wkup_event) disable iff (wkup_clear)
            (scan_mode == 1'b0 && wkup_out == 1'b1) |=> ##0 (wkup_out == 1'b1)
    );

// In functional mode, if wkup_out was low, a rising wkup_event with clear deasserted sets it high.
    check_func_event_sets_one_when_prev_zero: assert property (
        @(posedge wkup_event) disable iff (wkup_clear)
            (scan_mode == 1'b0 && $past(wkup_out) == 1'b0) |=> ##0 (wkup_out == 1'b1)
    );

// In functional mode, clear dominates if wkup_event and clear coincide.
    check_func_event_with_clear_dominates: assert property (
        @(posedge wkup_event) (scan_mode == 1'b0 && wkup_clear == 1'b1) |=> ##0 (wkup_out == 1'b0)
    );

///// Scan mode (scan_mode == 1) /////
    // In scan mode, a rising scan_rst drives wkup_out low.
    check_scan_rst_drives_zero: assert property (
        @(posedge scan_rst) (scan_mode == 1'b1) |=> ##0 (wkup_out == 1'b0)
    );

// In scan mode, reset dominates if scan_clk and scan_rst coincide.
    check_scan_clk_with_rst_dominates: assert property (
        @(posedge scan_clk) (scan_mode == 1'b1 && scan_rst == 1'b1) |=> ##0 (wkup_out == 1'b0)
    );

// Y is always the logical inversion of A at sample time.
    check_inversion_function: assert property (
        @(posedge CLK) (Y === ~A)
    );

// Y is never high-impedance (no tri-state drivers in DUT).
    check_Y_not_highz: assert property (
        @(posedge CLK) (Y !== 1'bz)
    );

// When A is 0, Y must be 1.
    check_A0_implies_Y1: assert property (
        @(posedge CLK) (A === 1'b0) |-> (Y === 1'b1)
    );

// When A is 1, Y must be 0.
    check_A1_implies_Y0: assert property (
        @(posedge CLK) (A === 1'b1) |-> (Y === 1'b0)
    );

///// Functional mapping /////
    // Out matches the RTL ternary selection of operations.
    check_functional_equivalence: assert property (
        @(posedge clk) out == ((op == 2'b00) ? (A + B) :
                               (op == 2'b01) ? (A - B) :
                               (op == 2'b10) ? (A & B) :
                                               (A | B))
    );

///// Operation selections /////
    // When op==00, out equals A+B (8-bit wraparound).
    check_add_selection: assert property (
        @(posedge clk) (op === 2'b00) |-> (out == (A + B))
    );

// When op==01, out equals A-B (8-bit wraparound).
    check_sub_selection: assert property (
        @(posedge clk) (op === 2'b01) |-> (out == (A - B))
    );

// When op==10, out equals A&B.
    check_and_selection: assert property (
        @(posedge clk) (op === 2'b10) |-> (out == (A & B))
    );

// When op==11, out equals A|B.
    check_or_selection: assert property (
        @(posedge clk) (op === 2'b11) |-> (out == (A | B))
    );

// For any op not 00/01/10 (including X/Z), out falls through to OR.
    check_default_fallthrough_to_or: assert property (
        @(posedge clk) ((op !== 2'b00) && (op !== 2'b01) && (op !== 2'b10)) |-> (out == (A | B))
    );

// Synchronous reset drives data_out to zero on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (data_out == '0)
    );

// While reset remains asserted, data_out is held at zero.
    check_hold_zero_during_continuous_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (data_out == '0)
    );

// On reset assertion edge, current output shows the previous cycle's input.
    check_prev_input_visible_on_reset_rise: assert property (
        @(posedge clk) $rose(reset) |-> (data_out == $past(data_in))
    );

///// Functional correctness per opcode /////
    // op=00: result equals 8-bit sum of a and b.
    check_add_result: assert property (
        @(posedge CLK) (op == 2'b00) |-> (result == ((a + b) & 8'hFF))
    );

// op=01: result equals 8-bit difference a - b.
    check_sub_result: assert property (
        @(posedge CLK) (op == 2'b01) |-> (result == ((a - b) & 8'hFF))
    );

///// Algebraic identities for corner cases /////
    // op=00 and b==0: result equals a.
    check_add_zero_b: assert property (
        @(posedge CLK) (op == 2'b00 && (b == 8'd0)) |-> (result == a)
    );

// op=01 and b==0: result equals a.
    check_sub_zero_b: assert property (
        @(posedge CLK) (op == 2'b01 && (b == 8'd0)) |-> (result == a)
    );

// op=01 and a==b: result is zero.
    check_sub_a_eq_b_zero: assert property (
        @(posedge CLK) (op == 2'b01 && (a == b)) |-> (result == 8'd0)
    );

// SUM must equal A ^ B ^ CI.
    check_sum_is_xor: assert property (
        @(posedge clk) disable iff (1'b0) SUM == (A ^ B ^ CI)
    );

// COUT_N must equal complement of majority (two-or-more ones).
    check_coutn_is_comp_majority: assert property (
        @(posedge clk) disable iff (1'b0) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

// Truth table: 000 -> SUM=0, COUT_N=1.
    truth_000: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b0 && B==1'b0 && CI==1'b0) |-> (SUM==1'b0 && COUT_N==1'b1)
    );

// Truth table: 001 -> SUM=1, COUT_N=1.
    truth_001: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b0 && B==1'b0 && CI==1'b1) |-> (SUM==1'b1 && COUT_N==1'b1)
    );

// Truth table: 011 -> SUM=0, COUT_N=0.
    truth_011: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b0 && B==1'b1 && CI==1'b1) |-> (SUM==1'b0 && COUT_N==1'b0)
    );

// Truth table: 111 -> SUM=1, COUT_N=0.
    truth_111: assert property (
        @(posedge clk) disable iff (1'b0) (A==1'b1 && B==1'b1 && CI==1'b1) |-> (SUM==1'b1 && COUT_N==1'b0)
    );

// When run_end_this and run_polarity=1, rise_lead and fall_trail hold their previous values.
    hold_unaffected_pospol: assert property (
        @(posedge clk) (run_end && select0 && select1 && run_polarity) |=> (rise_lead == $past(rise_lead)) && (fall_trail == $past(fall_trail))
    );

// When run_end_this and run_polarity=0, fall_lead and rise_trail hold their previous values.
    hold_unaffected_negpol: assert property (
        @(posedge clk) (run_end && select0 && select1 && ~run_polarity) |=> (fall_lead == $past(fall_lead)) && (rise_trail == $past(rise_trail))
    );

///// Gating when run_end_this is false /////
    // If run_end_this is false, all outputs hold their values on next cycle.
    hold_when_no_update: assert property (
        @(posedge clk) !(run_end && select0 && select1) |=> (fall_lead == $past(fall_lead)) && (fall_trail == $past(fall_trail)) &&
                                                           (rise_lead == $past(rise_lead)) && (rise_trail == $past(rise_trail))
    );

///// Counter behavior (sequential, posedge Clk) /////
    // On reset, Q is driven to 0 in the same cycle.
    reset_forces_zero: assert property (
        @(posedge Clk) Reset |-> (Q == 4'h0)
    );

// Reset has priority over Enable.
    reset_priority_over_enable: assert property (
        @(posedge Clk) Reset && Enable |-> (Q == 4'h0)
    );

// While reset is held across cycles, Q remains 0.
    reset_held_keeps_zero: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (Q == 4'h0 && $past(Q) == 4'h0)
    );

// Output equals binary XOR (binary >> 1) for all bits.
    check_functional_mapping: assert property (
        @(posedge clk) gray_code_output == (binary_input ^ (binary_input >> 1))
    );

// MSB of Gray equals MSB of Binary.
    check_msb_passthrough: assert property (
        @(posedge clk) gray_code_output[15] == binary_input[15]
    );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Output equals the 3-input OR of A, B, C.
    check_or_function: assert property (
        @(posedge clk) disable iff (1'b0) X == (A | B | C)
    );

// When all inputs are 0, X must be 0.
    check_all_zero_implies_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!A && !B && !C) |-> (X == 1'b0)
    );

// If any input is 1, X must be 1.
    check_any_one_implies_one: assert property (
        @(posedge clk) disable iff (1'b0) (A || B || C) |-> (X == 1'b1)
    );

// With B=0 and C=0, X equals A.
    check_pass_through_A_when_others_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!B && !C) |-> (X == A)
    );

// With A=0 and C=0, X equals B.
    check_pass_through_B_when_others_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!A && !C) |-> (X == B)
    );

// With A=0 and B=0, X equals C.
    check_pass_through_C_when_others_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!A && !B) |-> (X == C)
    );

///// Functional correctness /////
    // q equals logical OR of a and b.
    check_q_is_or: assert property (
        @(posedge CLK) q == (a | b)
    );

// When both inputs are 0, q must be 0.
    check_zero_zero_results_zero: assert property (
        @(posedge CLK) (a == 1'b0 && b == 1'b0) |-> (q == 1'b0)
    );

// When a is 0, q must equal b.
    check_a_zero_drives_b: assert property (
        @(posedge CLK) (a == 1'b0) |-> (q == b)
    );

// When a is 1, q must be 1.
    check_a_one_forces_one: assert property (
        @(posedge CLK) (a == 1'b1) |-> (q == 1'b1)
    );

// When a is 0 and b is 1, q must be 1.
    check_b_one_when_a_zero: assert property (
        @(posedge CLK) (a == 1'b0 && b == 1'b1) |-> (q == 1'b1)
    );

// If q is 1, then at least one input must be 1.
    check_q_one_implies_input_one: assert property (
        @(posedge CLK) (q == 1'b1) |-> (a == 1'b1 || b == 1'b1)
    );

// If q is 0, both inputs must be 0.
    check_q_zero_implies_both_zero: assert property (
        @(posedge CLK) (q == 1'b0) |-> (a == 1'b0 && b == 1'b0)
    );

// When a equals b, q must equal that common value.
    check_when_inputs_equal: assert property (
        @(posedge CLK) (a == b) |-> (q == a)
    );

// Upper nibble of out is always zero due to 4-bit addition result.
    check_out_upper_nibble_zero: assert property (
        @(posedge clk) disable iff (!reset) (out[7:4] == 4'b0000)
    );

// Lower nibble of out is always in the range 0..10 (count 0..9 plus selected 0/1).
    check_out_nibble_range: assert property (
        @(posedge clk) disable iff (!reset) (out[3:0] <= 4'd10)
    );

// While reset is asserted low, out equals the selected input (count forced to 0).
    check_out_during_reset_matches_enable: assert property (
        @(posedge clk) (!reset) |-> ((out[7:1] == 7'b0) && (out[0] == ((sel == 1'b0) ? a : b)))
    );

// When slowena is 0 and inputs are stable, out must hold.
    check_hold_when_slowena_low_inputs_stable: assert property (
        @(posedge clk) disable iff (!reset)
        ((slowena == 1'b0) && $stable(a) && $stable(b) && $stable(sel)) |=> $stable(out)
    );

// When slowena is 1, inputs stable, and not at 9+enable, out increments by 1.
    check_increment_no_wrap: assert property (
        @(posedge clk) disable iff (!reset)
        ((slowena == 1'b1) && $stable(a) && $stable(b) && $stable(sel) &&
         (out[3:0] != (4'd9 + ((sel == 1'b0) ? a : b)))) |=> (out[3:0] == $past(out[3:0]) + 4'd1)
    );

// When slowena is 1, inputs stable, and at 9+enable, out wraps to enable.
    check_wrap_to_enable: assert property (
        @(posedge clk) disable iff (!reset)
        ((slowena == 1'b1) && $stable(a) && $stable(b) && $stable(sel) &&
         (out[3:0] == (4'd9 + ((sel == 1'b0) ? a : b)))) |=> (out[3:0] == {3'b000, ((sel == 1'b0) ? a : b)})
    );

// With slowena 1 and inputs stable, out must change (either +1 or wrap).
    check_out_changes_when_slowena_high: assert property (
        @(posedge clk) disable iff (!reset)
        ((slowena == 1'b1) && $stable(a) && $stable(b) && $stable(sel)) |=> (out != $past(out))
    );

// If out is 10, the selected input must be 1 (only possible with enable=1 and count=9).
    check_out10_implies_enable1: assert property (
        @(posedge clk) disable iff (!reset)
        (out[3:0] == 4'd10) |-> (((sel == 1'b0) ? a : b) == 1'b1)
    );

// If out is 0, the selected input must be 0 (only possible with enable=0 and count=0).
    check_out0_implies_enable0: assert property (
        @(posedge clk) disable iff (!reset)
        (out[3:0] == 4'd0) |-> (((sel == 1'b0) ? a : b) == 1'b0)
    );

// If the selected input is 0, out cannot exceed 9.
    check_enable0_bounds_out: assert property (
        @(posedge clk) disable iff (!reset)
        (((sel == 1'b0) ? a : b) == 1'b0) |-> (out[3:0] <= 4'd9)
    );

// If the selected input is 1, out is at least 1.
    check_enable1_bounds_out: assert property (
        @(posedge clk) disable iff (!reset)
        (((sel == 1'b0) ? a : b) == 1'b1) |-> (out[3:0] >= 4'd1)
    );

// Output equals the bitwise OR of inputs.
    check_or_function: assert property (
        @(posedge clk) X == (A | B)
    );

// Output never has 1s where both inputs are 0.
    check_no_spurious_ones: assert property (
        @(posedge clk) (X & ~A & ~B) == 8'h00
    );

// All 1s present in inputs appear on the output.
    check_no_missing_ones: assert property (
        @(posedge clk) ((A | B) & ~X) == 8'h00
    );

// If A is zero, output equals B.
    check_zero_identity_A: assert property (
        @(posedge clk) (A == 8'h00) |-> (X == B)
    );

// If B is zero, output equals A.
    check_zero_identity_B: assert property (
        @(posedge clk) (B == 8'h00) |-> (X == A)
    );

// If both inputs are zero, output is zero.
    check_both_zero_yields_zero: assert property (
        @(posedge clk) ((A == 8'h00) && (B == 8'h00)) |-> (X == 8'h00)
    );

///// Functional equivalence /////
    // X equals the OR of A,B,C,D.
    check_or_function_eq: assert property (
        @(posedge CLK) X == (A | B | C | D)
    );

///// Internal net and buffer consistency /////
    // Internal OR output equals the OR of A,B,C,D.
    check_internal_or_net_function: assert property (
        @(posedge CLK) or0_out_X == (A | B | C | D)
    );

// Buffer is non-inverting: X equals internal OR output.
    check_buffer_non_inverting: assert property (
        @(posedge CLK) X == or0_out_X
    );

///// Basic truth-table implications /////
    // If all inputs are 0 then X must be 0.
    check_all_zero_drives_zero: assert property (
        @(posedge CLK) (~A & ~B & ~C & ~D) |-> (X == 1'b0)
    );

// If any input is 1 then X must be 1.
    check_any_one_drives_one: assert property (
        @(posedge CLK) (A | B | C | D) |-> (X == 1'b1)
    );

// If X is 0 then all inputs must be 0.
    check_zero_output_means_all_zero: assert property (
        @(posedge CLK) (X == 1'b0) |-> (~A & ~B & ~C & ~D)
    );

// If X is 1 then at least one input is 1.
    check_one_output_means_some_one: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A | B | C | D)
    );

///// Functional equivalence: Y = (~A) & B_N /////
    // Y equals (~A & B_N) at A rising edge.
    check_func_posedge_A: assert property (
        @(posedge A) Y == ((~A) & B_N)
    );

// Y equals (~A & B_N) at A falling edge.
    check_func_negedge_A: assert property (
        @(negedge A) Y == ((~A) & B_N)
    );

// Y equals (~A & B_N) at B_N rising edge.
    check_func_posedge_BN: assert property (
        @(posedge B_N) Y == ((~A) & B_N)
    );

// Y equals (~A & B_N) at B_N falling edge.
    check_func_negedge_BN: assert property (
        @(negedge B_N) Y == ((~A) & B_N)
    );

// If A is HIGH, Y must be LOW.
    check_A_high_forces_Y_low: assert property (
        @(posedge B_N) (A == 1'b1) |-> (Y == 1'b0)
    );

// If B_N is LOW, Y must be LOW.
    check_BN_low_forces_Y_low: assert property (
        @(posedge A) (B_N == 1'b0) |-> (Y == 1'b0)
    );

///// Directional effects on output with specific input edges /////
    // With B_N HIGH, Y equals NOT A (sampled on A edge).
    check_BN_high_implies_Y_eq_notA: assert property (
        @(posedge A) (B_N == 1'b1) |-> (Y == (~A))
    );

// Output is the bitwise OR of all inputs.
    check_or_function: assert property (
        @(posedge dclkin) data0out == (sdoin | scein | dclkin | oe)
    );

// If sdoin is HIGH, data0out must be HIGH.
    check_sdoin_drives_out_high: assert property (
        @(posedge dclkin) sdoin |-> data0out
    );

// If scein is HIGH, data0out must be HIGH.
    check_scein_drives_out_high: assert property (
        @(posedge dclkin) scein |-> data0out
    );

// If oe is HIGH, data0out must be HIGH.
    check_oe_drives_out_high: assert property (
        @(posedge dclkin) oe |-> data0out
    );

// Synchronous reset drives count and output_signal to 0 in the next cycle.
    check_reset_clears_both: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (output_signal == 4'd0)
    );

// With MSB=0 (and not sentinel), output holds its previous value next cycle.
    check_msb0_holds_output: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b0) && $past(!reset)) |=> (output_signal == $past(output_signal))
    );

// All 4 outputs equal the AND of the two inputs.
    check_out_matches_and_broadcast: assert property (
        @(posedge clk) disable iff (!rst_n) out == {4{in[0] & in[1]}}
    );

// All output bits are identical at all times.
    check_all_outs_equal: assert property (
        @(posedge clk) disable iff (!rst_n) (out[0] == out[1]) && (out[1] == out[2]) && (out[2] == out[3])
    );

// Outputs are all zero when any input is zero.
    check_out_zero_when_any_input_zero: assert property (
        @(posedge clk) disable iff (!rst_n) ((!in[0]) || (!in[1])) |-> (out == 4'b0000)
    );

// Outputs are all one when both inputs are one.
    check_out_one_when_both_inputs_one: assert property (
        @(posedge clk) disable iff (!rst_n) (in[0] && in[1]) |-> (out == 4'b1111)
    );

// A rising edge on any output implies both inputs are one.
    check_out_rise_implies_inputs_high: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(out[0]) |-> (in[0] && in[1])
    );

// A falling edge on any output implies at least one input is zero.
    check_out_fall_implies_any_input_low: assert property (
        @(posedge clk) disable iff (!rst_n) $fell(out[0]) |-> ((!in[0]) || (!in[1]))
    );

// Output bus can only be all-zeros or all-ones.
    check_out_is_const_bus: assert property (
        @(posedge clk) disable iff (!rst_n) (out == 4'b0000) || (out == 4'b1111)
    );

///// Functional equivalence checks /////
    // X equals A|B when A rises.
    check_func_eq_on_A_posedge: assert property (
        @(posedge A) X == (A | B)
    );

// X equals A|B when A falls.
    check_func_eq_on_A_negedge: assert property (
        @(negedge A) X == (A | B)
    );

// X equals A|B when B rises.
    check_func_eq_on_B_posedge: assert property (
        @(posedge B) X == (A | B)
    );

// X equals A|B when B falls.
    check_func_eq_on_B_negedge: assert property (
        @(negedge B) X == (A | B)
    );

// A falling with B high keeps X high.
    check_x_stays_high_on_a_fall_when_b_high: assert property (
        @(negedge A) (B == 1'b1) |-> (X == 1'b1)
    );

// B falling with A high keeps X high.
    check_x_stays_high_on_b_fall_when_a_high: assert property (
        @(negedge B) (A == 1'b1) |-> (X == 1'b1)
    );

// P equals A & ~n at each sample
    check_p_equals_a_and_notn: assert property (
        @(posedge C) P == (A & ~n)
    );

// When n is 1, P must be 0
    check_p_zero_when_n_high: assert property (
        @(posedge C) n |-> (P == 1'b0)
    );

// When n is 0, P equals A
    check_p_equals_a_when_n_low: assert property (
        @(posedge C) !n |-> (P == A)
    );

// When A is 0, P must be 0
    check_p_zero_when_a_low: assert property (
        @(posedge C) (A == 1'b0) |-> (P == 1'b0)
    );

// When A is 1 and n is 0, P must be 1
    check_p_one_when_a1_n0: assert property (
        @(posedge C) (A && !n) |-> (P == 1'b1)
    );

// P high implies A is 1 and n is 0
    check_p_high_implies_inputs: assert property (
        @(posedge C) (P == 1'b1) |-> (A && !n)
    );

// P low implies A is 0 or n is 1
    check_p_low_implies_inputs: assert property (
        @(posedge C) (P == 1'b0) |-> (!A || n)
    );

///// Functional next-state rules /////
    // Next out equals prior load ? prior in : prior out shifted in with 0 LSB.
    check_next_out_function: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(load) ? $past(in) : { $past(out[2:0]), 1'b0 }))
    );

// When load is 1, next out equals prior in.
    check_load_captures_in_next: assert property (
        @(posedge clk) load |=> (out == $past(in))
    );

// When load is 0, next out equals prior out shifted left with 0 inserted.
    check_no_load_shifts_next: assert property (
        @(posedge clk) !load |=> (out == { $past(out[2:0]), 1'b0 })
    );

// When load is 0, the next out[0] must be 0.
    check_lsb_zero_on_shift: assert property (
        @(posedge clk) !load |=> (out[0] == 1'b0)
    );

///// Valid signaling /////
    // Next valid equals prior load.
    check_valid_follows_prev_load: assert property (
        @(posedge clk) 1'b1 |=> (valid == $past(load))
    );

// When load is 1, next valid must be 1.
    check_load_sets_valid_next: assert property (
        @(posedge clk) load |=> (valid == 1'b1)
    );

///// Long no-load behavior /////
    // After 4 consecutive cycles of no load, out becomes 0.
    check_no_load_flushes_zero_after_four: assert property (
        @(posedge clk) (!load)[*4] |=> (out == 4'b0000)
    );

// X implements (~A_N) & B
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

// If A_N is HIGH, X must be LOW
    check_zero_when_A_N_high: assert property (
        @(posedge clk) A_N |-> (X == 1'b0)
    );

// If B is LOW, X must be LOW
    check_zero_when_B_low: assert property (
        @(posedge clk) !B |-> (X == 1'b0)
    );

// If A_N is LOW and B is HIGH, X must be HIGH
    check_one_when_A_N_low_and_B_high: assert property (
        @(posedge clk) (!A_N && B) |-> (X == 1'b1)
    );

// If X is HIGH, then A_N must be LOW and B must be HIGH
    check_inputs_when_X_high: assert property (
        @(posedge clk) X |-> (!A_N && B)
    );

// If X is LOW while B is HIGH, then A_N must be HIGH
    check_A_N_high_when_X_low_and_B_high: assert property (
        @(posedge clk) ((X == 1'b0) && B) |-> A_N
    );

// If X is LOW while A_N is LOW, then B must be LOW
    check_B_low_when_X_low_and_A_N_low: assert property (
        @(posedge clk) ((X == 1'b0) && !A_N) |-> !B
    );

///// Functional equivalence /////
    // out equals AND of the OR-reductions of a and b.
    check_out_eq_and_of_ors: assert property (
        @(posedge clk) disable iff (1'b0) out == ((a[1] | a[0]) & (b[1] | b[0]))
    );

// out equals the sum-of-products of all a/b bit pairs.
    check_out_eq_sum_of_products: assert property (
        @(posedge clk) disable iff (1'b0) out == ((a[1] & b[1]) | (a[1] & b[0]) | (a[0] & b[1]) | (a[0] & b[0]))
    );

///// Necessary conditions /////
    // If a is zero, out must be zero.
    check_a_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (a == 2'b00) |-> (out == 1'b0)
    );

// If b is zero, out must be zero.
    check_b_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (b == 2'b00) |-> (out == 1'b0)
    );

// If out is one, both a and b must be non-zero.
    check_out1_implies_nonzero_inputs: assert property (
        @(posedge clk) disable iff (1'b0) (out == 1'b1) |-> ((a != 2'b00) && (b != 2'b00))
    );

// If out is zero, at least one of a or b must be zero.
    check_out0_implies_one_zero: assert property (
        @(posedge clk) disable iff (1'b0) (out == 1'b0) |-> ((a == 2'b00) || (b == 2'b00))
    );

///// Sufficient conditions /////
    // If both a and b are non-zero, out must be one.
    check_nonzero_inputs_force_out1: assert property (
        @(posedge clk) disable iff (1'b0) ((a != 2'b00) && (b != 2'b00)) |-> (out == 1'b1)
    );

// If exactly one of a or b is zero, out must be zero.
    check_exactly_one_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (((a == 2'b00) ^ (b == 2'b00))) |-> (out == 1'b0)
    );

///// Reset behavior /////
    // Synchronous clear forces op low on the next cycle.
    reset_clears_op_next: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

///// Update and hold rules /////
    // With clr low, ce sets op high on the next cycle.
    ce_sets_op_high_next: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == 1'b1)
    );

// With clr low and ce low, op holds its value.
    hold_without_ce: assert property (
        @(posedge clk) disable iff (clr) !ce |=> (op == $past(op))
    );

// Once high and with clr low, op stays high.
    sticky_high_without_clr: assert property (
        @(posedge clk) disable iff (clr) (op == 1'b1) |=> (op == 1'b1)
    );

///// Reset behavior /////
    // While reset is asserted (low), count must be 0.
    reset_drives_zero: assert property (
        @(posedge clk) !reset |-> (count == 32'd0)
    );

// On reset deassertion edge, count is 0 in that cycle.
    zero_on_reset_release: assert property (
        @(posedge clk) $rose(reset) |-> (count == 32'd0)
    );

///// Counting behavior /////
    // When disabled, the counter holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
            (!count_en) |=> (count == $past(count))
    );

// When enabled, next value is +1 unless at max_count, then it wraps to 0.
    update_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (count_en) |=> (count == (($past(count) == $past(max_count)) ? 32'd0 : ($past(count) + 32'd1)))
    );

// Any change between cycles (out of reset) requires enable in the previous cycle.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && (count != $past(count))) |-> $past(count_en)
    );

// If enabled at all-ones and not equal to max_count, next value wraps to 0 via +1 overflow.
    overflow_wrap_to_zero: assert property (
        @(posedge clk) disable iff (!reset)
            (count_en && (count == 32'hFFFF_FFFF) && (count != max_count)) |=> (count == 32'd0)
    );

// If next value is 0 with enable high previously, cause is wrap-to-zero or max_count match.
    enabled_zero_next_cycle_has_cause: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && $past(count_en) && (count == 32'd0)) |-> (($past(count) == $past(max_count)) || ($past(count) == 32'hFFFF_FFFF))
    );

///// End-to-end 1-cycle pipeline from inputs to out /////
    // If sel==00 this cycle, out equals in0 from this cycle on the next cycle.
    check_out_pipeline_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |=> (out == $past(in0))
    );

// If sel==01 this cycle, out equals in1 from this cycle on the next cycle.
    check_out_pipeline_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |=> (out == $past(in1))
    );

// If sel==10 this cycle, out equals in2 from this cycle on the next cycle.
    check_out_pipeline_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |=> (out == $past(in2))
    );

// If sel==11 this cycle, out equals in3 from this cycle on the next cycle.
    check_out_pipeline_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |=> (out == $past(in3))
    );

// With DE=1 now, on the next edge Q equals the current D.
    check_capture_next_cycle_on_current_enable: assert property (
        @(posedge CLK) DE |-> ##1 (Q == $past(D))
    );

// Y equals (~(A|B)) & C_N & D_N when inputs are known.
    check_logic_equation: assert property (
        @(posedge clk) !$isunknown({A,B,C_N,D_N}) |-> (Y == ((~(A | B)) & C_N & D_N))
    );

// Y can be HIGH only when A=0, B=0, C_N=1, D_N=1.
    check_y_high_implies_inputs: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1) && (D_N == 1'b1))
    );

// A=1 forces Y=0.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// B=1 forces Y=0.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b0)
    );

// C_N=0 forces Y=0.
    check_cn_low_forces_y_low: assert property (
        @(posedge clk) (C_N == 1'b0) |-> (Y == 1'b0)
    );

// D_N=0 forces Y=0.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) (D_N == 1'b0) |-> (Y == 1'b0)
    );

// When A=0, B=0, C_N=1, and D_N=1, Y must be 1.
    check_all_conditions_drive_y_high: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1) && (D_N == 1'b1)) |-> (Y == 1'b1)
    );

// A rising edge drives Y low in the same cycle.
    check_rose_a_drives_y_low: assert property (
        @(posedge clk) $rose(A) |-> (Y == 1'b0)
    );

// B rising edge drives Y low in the same cycle.
    check_rose_b_drives_y_low: assert property (
        @(posedge clk) $rose(B) |-> (Y == 1'b0)
    );

// C_N falling edge drives Y low in the same cycle.
    check_fell_cn_drives_y_low: assert property (
        @(posedge clk) $fell(C_N) |-> (Y == 1'b0)
    );

// D_N falling edge drives Y low in the same cycle.
    check_fell_dn_drives_y_low: assert property (
        @(posedge clk) $fell(D_N) |-> (Y == 1'b0)
    );

// Clock: CLOCK (posedge). Reset: RESET (active-high, asynchronous).
    // Logic: Sequential register computing absolute difference; DIFF cleared to 0 on RESET.

    // DIFF must be 0 whenever RESET is asserted at the clock edge.
    reset_forces_zero: assert property (
        @(posedge CLOCK) RESET |-> (DIFF == 12'd0)
    );

///// Functional correctness /////
    // SUM must equal XOR of A, B, CI.
    check_sum_xor3: assert property (
        @(posedge CLK) SUM === (A ^ B ^ CI)
    );

// COUT must equal majority of A, B, CI.
    check_cout_majority: assert property (
        @(posedge CLK) COUT === ((A & B) | (A & CI) | (B & CI))
    );

///// Truth-table spot checks /////
    // When A=B=CI=0, SUM=0 and COUT=0.
    check_tt_all_zero: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b0 && CI==1'b0) |-> (SUM==1'b0 && COUT==1'b0)
    );

// When A=B=CI=1, SUM=1 and COUT=1.
    check_tt_all_one: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b1 && CI==1'b1) |-> (SUM==1'b1 && COUT==1'b1)
    );

// When only A=1, SUM=1 and COUT=0.
    check_tt_only_a: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b0 && CI==1'b0) |-> (SUM==1'b1 && COUT==1'b0)
    );

// When only B=1, SUM=1 and COUT=0.
    check_tt_only_b: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b1 && CI==1'b0) |-> (SUM==1'b1 && COUT==1'b0)
    );

// When only CI=1, SUM=1 and COUT=0.
    check_tt_only_ci: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b0 && CI==1'b1) |-> (SUM==1'b1 && COUT==1'b0)
    );

// When A=B=1 and CI=0, SUM=0 and COUT=1.
    check_tt_ab_two_ones: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b1 && CI==1'b0) |-> (SUM==1'b0 && COUT==1'b1)
    );

// When A=CI=1 and B=0, SUM=0 and COUT=1.
    check_tt_ac_two_ones: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b0 && CI==1'b1) |-> (SUM==1'b0 && COUT==1'b1)
    );

// When B=CI=1 and A=0, SUM=0 and COUT=1.
    check_tt_bc_two_ones: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b1 && CI==1'b1) |-> (SUM==1'b0 && COUT==1'b1)
    );

///// Derived consistency /////
    // COUT high implies at least two inputs are high.
    check_cout_implies_two_high: assert property (
        @(posedge CLK) COUT |-> ((A & B) | (A & CI) | (B & CI))
    );

// COUT low implies fewer than two inputs are high.
    check_cout_low_implies_lt2: assert property (
        @(posedge CLK) !COUT |-> ~((A & B) | (A & CI) | (B & CI))
    );

///// Reset behavior /////
  // While reset is asserted low, outputs are forced to 0/1.
  reset_level_forces_values: assert property (
    @(posedge CLK) !RST |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled falling edge of reset, outputs are 0/1.
  reset_fall_forces_values: assert property (
    @(posedge CLK) $fell(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled rising edge of reset, outputs are still at reset values before capture.
  reset_rise_holds_reset_values_before_capture: assert property (
    @(posedge CLK) $rose(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

///// Output relationship /////
  // QN is always the logical inverse of Q.
  complement_invariant: assert property (
    @(posedge CLK) QN == ~Q
  );

// Q and QN are never both HIGH.
  never_both_high: assert property (
    @(posedge CLK) !(Q && QN)
  );

// Q and QN are never both LOW.
  never_both_low: assert property (
    @(posedge CLK) !(~Q && ~QN)
  );

// A rise on Q implies a fall on QN in the same sample.
  q_rise_implies_qn_fall: assert property (
    @(posedge CLK) $rose(Q) |-> $fell(QN)
  );

// Analysis: No clock/reset in RTL; pure combinational. out=1 iff a<b; sub does not affect out.

    ///// Functional equivalence /////
    // out must reflect comparator result: out == (a < b).
    check_out_equals_less: assert property (
        @(posedge clk) out == (a < b)
    );

///// Case-specific behavior /////
    // When a < b, out is 1.
    check_out_one_when_less: assert property (
        @(posedge clk) (a < b) |-> (out == 1'b1)
    );

// When a >= b, out is 0.
    check_out_zero_when_ge: assert property (
        @(posedge clk) (a >= b) |-> (out == 1'b0)
    );

///// Functional definitions /////
    // X must equal A1 AND A2.
    check_x_and_def: assert property (
        @(posedge A1) X == (A1 & A2)
    );

// Y must equal A1 OR A2.
    check_y_or_def: assert property (
        @(posedge A1) Y == (A1 | A2)
    );

// Z must equal A1 XOR A2.
    check_z_xor_def: assert property (
        @(posedge A1) Z == (A1 ^ A2)
    );

// W must equal B1 AND VPWR.
    check_w_and_def: assert property (
        @(posedge B1) W == (B1 & VPWR)
    );

///// Output relationships implied by the logic /////
    // If X is 1, Y must be 1.
    check_x_implies_y: assert property (
        @(posedge A1) X |-> Y
    );

// If X is 1, Z must be 0.
    check_x_implies_not_z: assert property (
        @(posedge A1) X |-> (Z == 1'b0)
    );

// If Z is 1, X must be 0.
    check_z_implies_not_x: assert property (
        @(posedge A1) Z |-> (X == 1'b0)
    );

// If Z is 1, Y must be 1.
    check_z_implies_y: assert property (
        @(posedge A1) Z |-> Y
    );

// Y equals X OR Z (OR decomposition).
    check_y_equals_x_or_z: assert property (
        @(posedge A1) Y == (X | Z)
    );

// X and Z are mutually exclusive.
    check_x_and_z_disjoint: assert property (
        @(posedge A1) (X & Z) == 1'b0
    );

///// Power gating behavior for W /////
    // W can be 1 only if B1 is 1.
    check_w_requires_b1: assert property (
        @(posedge A1) W |-> B1
    );

// W can be 1 only if VPWR is 1.
    check_w_requires_vpwr: assert property (
        @(posedge A1) W |-> VPWR
    );

// If VPWR is 0 then W must be 0.
    check_vpwr_low_forces_w_low: assert property (
        @(posedge A1) (!VPWR) |-> (W == 1'b0)
    );

///// Sanity on specific input combinations /////
    // When A1 and A2 are both 1: X=1, Y=1, Z=0.
    check_both_one: assert property (
        @(posedge A1) (A1 & A2) |-> (X && Y && (Z == 1'b0))
    );

// When A1 and A2 differ: Z=1, Y=1, X=0.
    check_inputs_differ: assert property (
        @(posedge A1) (A1 ^ A2) |-> (Z && Y && (X == 1'b0))
    );

///// Enable gating /////
    // When disabled, out is zero.
    check_out_zero_when_en_low: assert property (
        @(posedge clk) !en |-> (out == 4'b0000)
    );

///// Output mapping with enable /////
    // When en and sel==00, out equals in0.
    check_out_matches_in0_when_en_sel00: assert property (
        @(posedge clk) (en && (sel == 2'b00)) |-> (out == in0)
    );

// When en and sel==01, out equals in1.
    check_out_matches_in1_when_en_sel01: assert property (
        @(posedge clk) (en && (sel == 2'b01)) |-> (out == in1)
    );

// When en and sel==10, out equals in2.
    check_out_matches_in2_when_en_sel10: assert property (
        @(posedge clk) (en && (sel == 2'b10)) |-> (out == in2)
    );

// When en and sel==11, out equals in3.
    check_out_matches_in3_when_en_sel11: assert property (
        @(posedge clk) (en && (sel == 2'b11)) |-> (out == in3)
    );

///// Basic output relations /////
    // C always mirrors S[0].
    check_c_mirrors_s0: assert property (
        @(posedge clk) C == S[0]
    );

// S equals one of the four priority-selected shift results.
    check_s_in_valid_set: assert property (
        @(posedge clk)
            (S == A) ||
            (S == {A[2:0], 1'b0}) ||
            (S == {A[1:0], 2'b0}) ||
            (S == {A[0], 3'b0})
    );

///// Priority selection by B /////
    // When B[2] is 1, S equals A and C equals A[0].
    check_b2_selects_a: assert property (
        @(posedge clk) B[2] |-> (S == A) && (C == A[0])
    );

// When B[1] is 1 and B[2] is 0, S is A<<1 and C is 0.
    check_b1_selects_shift1: assert property (
        @(posedge clk) (!B[2] && B[1]) |-> (S == {A[2:0], 1'b0}) && (C == 1'b0)
    );

// When only B[0] is 1 (and B[2:1]==0), S is A<<2 and C is 0.
    check_b0_selects_shift2: assert property (
        @(posedge clk) (!B[2] && !B[1] && B[0]) |-> (S == {A[1:0], 2'b0}) && (C == 1'b0)
    );

// When B is 3'b000, S is A<<3 and C is 0.
    check_b000_selects_shift3: assert property (
        @(posedge clk) (!B[2] && !B[1] && !B[0]) |-> (S == {A[0], 3'b0}) && (C == 1'b0)
    );

///// Bit-level consequences /////
    // When B[2] is 0, LSB of S is 0.
    check_s0_zero_when_b2_zero: assert property (
        @(posedge clk) (!B[2]) |-> (S[0] == 1'b0)
    );

// When selecting A<<1, S[3] equals A[2].
    check_msbit_mapping_b1: assert property (
        @(posedge clk) (!B[2] && B[1]) |-> (S[3] == A[2])
    );

// When selecting A<<2, S[3] equals A[1].
    check_msbit_mapping_b0: assert property (
        @(posedge clk) (!B[2] && !B[1] && B[0]) |-> (S[3] == A[1])
    );

// When selecting A<<3, S[3] equals A[0].
    check_msbit_mapping_b000: assert property (
        @(posedge clk) (!B[2] && !B[1] && !B[0]) |-> (S[3] == A[0])
    );

// X equals the bitwise AND of A, B, C, and D.
    check_and_equation: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// X can be HIGH only if all inputs are HIGH.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// All inputs HIGH implies X is HIGH.
    check_all_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// A LOW forces X LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (!X)
    );

// B LOW forces X LOW.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (!X)
    );

// C LOW forces X LOW.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (!X)
    );

// D LOW forces X LOW.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (!X)
    );

// X rising edge only when all inputs are HIGH.
    check_x_rise_requires_all_high: assert property (
        @(posedge clk) $rose(X) |-> (A && B && C && D)
    );

// X falling edge implies at least one input is LOW.
    check_x_fall_requires_any_low: assert property (
        @(posedge clk) $fell(X) |-> (!A || !B || !C || !D)
    );

///// Reset behavior /////
    // During reset, motor_speed is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (motor_speed == 8'd0)
    );

// While reset stays asserted across cycles, motor_speed remains zero.
    check_zero_while_reset_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (motor_speed == 8'd0)
    );

// On a falling edge of reset, output at this sample is zero (held from prior reset cycle).
    check_output_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(rst) |-> (motor_speed == 8'd0)
    );

// On a rising edge of reset, async reset clears output to zero by this sample.
    check_output_zero_on_reset_rise_sample: assert property (
        @(posedge clk) $rose(rst) |-> (motor_speed == 8'd0)
    );

// On reset HIGH, next cycle count is driven to 0.
  reset_clears_next: assert property (
    @(posedge clk) reset |=> (count == 4'd0)
  );

// If reset stays HIGH across cycles, count is 0 on the later cycle.
  reset_holds_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == 4'd0)
  );

///// Functional correctness /////
    // SUM equals XOR of inputs.
    check_sum_matches_xor: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

// COUT equals majority-of-three of inputs.
    check_cout_majority: assert property (
        @(posedge CLK) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// 2-bit result {COUT,SUM} equals arithmetic sum of inputs.
    check_addition_consistency: assert property (
        @(posedge CLK) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

///// Simplified cases derived from the equations /////
    // When B equals CI, SUM equals A.
    check_sum_equals_A_when_BeqCI: assert property (
        @(posedge CLK) (B == CI) |-> (SUM == A)
    );

// When A equals B, SUM equals CI.
    check_sum_equals_CI_when_AeqB: assert property (
        @(posedge CLK) (A == B) |-> (SUM == CI)
    );

// For inputs 000, outputs must be 00.
    check_truth_000: assert property (
        @(posedge CLK) (!A && !B && !CI) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

// For inputs 111, outputs must be 11.
    check_truth_111: assert property (
        @(posedge CLK) (A && B && CI) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

// X equals A OR NOT B_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A | ~B_N)
    );

// If A is 1, X must be 1.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// If B_N is 0, X must be 1.
    check_bn_low_forces_x_high: assert property (
        @(posedge clk) (~B_N) |-> X
    );

// If A is 0 and B_N is 1, X must be 0.
    check_a0_bn1_forces_x0: assert property (
        @(posedge clk) (!A && B_N) |-> (!X)
    );

// X is 0 only when A is 0 and B_N is 1.
    check_x0_only_when_a0_bn1: assert property (
        @(posedge clk) (!X) |-> (!A && B_N)
    );

// Truth-table corner: A=0, B_N=0 => X=1.
    check_tt_a0_bn0_x1: assert property (
        @(posedge clk) (!A && !B_N) |-> X
    );

// Truth-table corner: A=1, B_N=0 => X=1.
    check_tt_a1_bn0_x1: assert property (
        @(posedge clk) (A && !B_N) |-> X
    );

// Truth-table corner: A=1, B_N=1 => X=1.
    check_tt_a1_bn1_x1: assert property (
        @(posedge clk) (A && B_N) |-> X
    );

// Truth-table corner: A=0, B_N=1 => X=0.
    check_tt_a0_bn1_x0: assert property (
        @(posedge clk) (!A && B_N) |-> (!X)
    );

// strobe HIGH requires enable and strobe_in HIGH.
    strobe_requires_inputs: assert property (
        @(posedge clock) strobe |-> (enable && strobe_in)
    );

// enable LOW forces strobe LOW.
    enable_low_forces_strobe_low: assert property (
        @(posedge clock) (!enable) |-> (strobe == 1'b0)
    );

// strobe_in LOW forces strobe LOW.
    strobe_in_low_forces_strobe_low: assert property (
        @(posedge clock) (!strobe_in) |-> (strobe == 1'b0)
    );

///// Counter update behavior /////
    // On reset, counter clears to zero on next cycle.
    counter_clears_on_reset: assert property (
        @(posedge clock) reset |=> (counter == 8'd0)
    );

///// Mode-0 (magnitude code) behavior /////
    // When sel==00, out_mode0 encodes compare result: 00 if A==B, 01 if A>B, 10 if A<B.
    check_sel00_magnitude_encoding: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0 == ((A == B) ? 2'b00 : ((A > B) ? 2'b01 : 2'b10)))
    );

// When sel!=00, out_mode0 must be 00.
    check_sel_not00_out_zero: assert property (
        @(posedge valid) (sel != 2'b00) |-> (out_mode0 == 2'b00)
    );

// For sel==00, out_mode0[1] reflects (A<B).
    check_sel00_out_msb_is_less: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[1] == (A < B))
    );

// For sel==00, out_mode0[0] reflects (A>B).
    check_sel00_out_lsb_is_greater: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[0] == (A > B))
    );

///// Mode-1 (flag outputs) behavior /////
    // When sel==01, less_than reflects (A<B).
    check_sel01_less_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (less_than == (A < B))
    );

// When sel==01, equal_to reflects (A==B).
    check_sel01_equal_to_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (equal_to == (A == B))
    );

// When sel==01, greater_than reflects (A>B).
    check_sel01_greater_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (greater_than == (A > B))
    );

// When sel==01, exactly one of the three flags is HIGH.
    check_sel01_onehot_result: assert property (
        @(posedge valid) (sel == 2'b01) |-> $onehot({less_than, equal_to, greater_than})
    );

///// Output gating when not in mode-1 /////
    // When sel!=01, less_than must be 0.
    check_sel_not01_less_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (less_than == 1'b0)
    );

// When sel!=01, equal_to must be 0.
    check_sel_not01_equal_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (equal_to == 1'b0)
    );

// When sel!=01, greater_than must be 0.
    check_sel_not01_greater_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (greater_than == 1'b0)
    );

///// Combinational AND truth /////
    // X equals the AND of all inputs and rails.
    check_and_function_equality: assert property (
        @(posedge A) X == (A & B & C & D & VPWR & VGND & VPB & VNB)
    );

///// Dominance of 0 /////
    // If any input/rail is 0, X must be 0.
    check_zero_when_any_input_zero: assert property (
        @(posedge A) ((A==1'b0) || (B==1'b0) || (C==1'b0) || (D==1'b0) ||
                      (VPWR==1'b0) || (VGND==1'b0) || (VPB==1'b0) || (VNB==1'b0))
                      |-> (X==1'b0)
    );

///// All-ones drives X high /////
    // If all inputs/rails are 1, X must be 1.
    check_one_when_all_inputs_one: assert property (
        @(posedge A) (A && B && C && D && VPWR && VGND && VPB && VNB) |-> (X==1'b1)
    );

///// High output implies all inputs high /////
    // If X is 1, then all inputs/rails are 1.
    check_one_implies_all_inputs_one: assert property (
        @(posedge A) (X==1'b1) |-> (A && B && C && D && VPWR && VGND && VPB && VNB)
    );

// DFF: Q_D captures D on rising edge (checked at next rising edge).
  check_dff_capture: assert property (
    @(posedge CLK) 1'b1 |=> (Q_D === $past(D))
  );

// JKFF: J=0,K=0 -> hold previous value (checked at next falling edge).
  check_jkff_hold_00: assert property (
    @(negedge CLK) ({J,K} == 2'b00) |=> (Q_JK === $past(Q_JK))
  );

// JKFF: J=0,K=1 -> reset to 0 (checked at next falling edge).
  check_jkff_reset_01: assert property (
    @(negedge CLK) ({J,K} == 2'b01) |=> (Q_JK == 1'b0)
  );

// JKFF: J=1,K=0 -> set to 1 (checked at next falling edge).
  check_jkff_set_10: assert property (
    @(negedge CLK) ({J,K} == 2'b10) |=> (Q_JK == 1'b1)
  );

// JKFF: J=1,K=1 -> toggle (checked at next falling edge).
  check_jkff_toggle_11: assert property (
    @(negedge CLK) ({J,K} == 2'b11) |=> (Q_JK === ~$past(Q_JK))
  );

// TFF: when T=1, toggle on rising edge (checked at next rising edge).
  check_tff_toggle_when_T1: assert property (
    @(posedge CLK) (T == 1'b1) |=> (Q_T === ~$past(Q_T))
  );

// TFF: when T=0, hold on rising edge (checked at next rising edge).
  check_tff_hold_when_T0: assert property (
    @(posedge CLK) (T == 1'b0) |=> (Q_T === $past(Q_T))
  );

// SRFF: S=0,R=0 -> hold previous value (checked at next falling edge).
  check_srff_hold_00: assert property (
    @(negedge CLK) ({S,R} == 2'b00) |=> (Q_SR === $past(Q_SR))
  );

// SRFF: S=0,R=1 -> reset to 0 (checked at next falling edge).
  check_srff_reset_01: assert property (
    @(negedge CLK) ({S,R} == 2'b01) |=> (Q_SR == 1'b0)
  );

// SRFF: S=1,R=0 -> set to 1 (checked at next falling edge).
  check_srff_set_10: assert property (
    @(negedge CLK) ({S,R} == 2'b10) |=> (Q_SR == 1'b1)
  );

// Sum is bitwise XOR of a, b, and c.
    check_sum_is_xor3: assert property (
        @(posedge CLK) disable iff (1'b0) s == (a ^ b) ^ c
    );

// Carry-out equals (a & b) | (c & (a ^ b)).
    check_carry_function: assert property (
        @(posedge CLK) disable iff (1'b0) c_out == ((a & b) | (c & (a ^ b)))
    );

// Carry-out equals majority function (a&b)|(a&c)|(b&c).
    check_carry_majority_equiv: assert property (
        @(posedge CLK) disable iff (1'b0) c_out == ((a & b) | (a & c) | (b & c))
    );

// s OR c_out equals bitwise OR of inputs.
    check_sum_or_carry_matches_input_or: assert property (
        @(posedge CLK) disable iff (1'b0) (s | c_out) == (a | b | c)
    );

// s AND c_out equals bitwise AND of all three inputs.
    check_sum_and_carry_triplet_and: assert property (
        @(posedge CLK) disable iff (1'b0) (s & c_out) == (a & b & c)
    );

// When c is zero, sum reduces to a ^ b.
    check_sum_when_c_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b0000) |-> (s == (a ^ b))
    );

// When c is zero, carry reduces to a & b.
    check_carry_when_c_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b0000) |-> (c_out == (a & b))
    );

// When c is all ones, sum is bitwise NOT of (a ^ b).
    check_sum_when_c_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b1111) |-> (s == ~(a ^ b))
    );

// When c is all ones, carry is a | b.
    check_carry_when_c_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b1111) |-> (c_out == (a | b))
    );

// When a equals b, sum equals c.
    check_sum_when_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a == b) |-> (s == c)
    );

// When c equals a ^ b, sum is zero.
    check_sum_when_c_eq_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (c == (a ^ b)) |-> (s == 4'b0000)
    );

// When c equals a ^ b, carry is a | b.
    check_carry_when_c_eq_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (c == (a ^ b)) |-> (c_out == (a | b))
    );

///// Functional mapping /////
    // When sel==00, out equals d0.
    check_map_sel00_to_d0: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b00) |-> (out == d0)
    );

// When sel==01, out equals d1.
    check_map_sel01_to_d1: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b01) |-> (out == d1)
    );

// When sel==10, out equals d2.
    check_map_sel10_to_d2: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b10) |-> (out == d2)
    );

// When sel==11, out equals d3.
    check_map_sel11_to_d3: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b11) |-> (out == d3)
    );

// If m_axi_arready is HIGH, m_payload_o_reg holds its value into the next cycle.
    ready_high_payload_stable_next: assert property (
        @(posedge aclk) (m_axi_arready == 1'b1) |-> ##1 $stable(m_payload_o_reg)
    );

// Analysis: RTL has no clock/reset and is purely combinational (always @*); this module uses external CLK/RESETn only to clock/gate assertions.

    ///// General range /////
    // aluc must be within 0..14 as all assignments are in this range.
    check_aluc_range: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc <= 5'd14)
    );

///// Outer op decode (direct mappings) /////
    // When op == 000000, aluc must be 0.
    check_op_000000_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000000) |-> (aluc == 5'd0)
    );

// When op == 000001, aluc must be 1.
    check_op_000001_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000001) |-> (aluc == 5'd1)
    );

// When op == 000010, aluc must be 2.
    check_op_000010_aluc2: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000010) |-> (aluc == 5'd2)
    );

// When op == 000011, aluc must be 3.
    check_op_000011_aluc3: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000011) |-> (aluc == 5'd3)
    );

// When op == 000100, aluc must be 5.
    check_op_000100_aluc5: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000100) |-> (aluc == 5'd5)
    );

// When op == 000101, aluc must be 14.
    check_op_000101_aluc14: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000101) |-> (aluc == 5'd14)
    );

// When op == 001001, aluc must be 1.
    check_op_001001_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001001) |-> (aluc == 5'd1)
    );

// When op == 001010, aluc must be 13.
    check_op_001010_aluc13: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001010) |-> (aluc == 5'd13)
    );

// For any op not explicitly listed (and not 001000), aluc must be 0 (outer default).
    check_default_other_ops_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!(op inside {6'b001000,6'b000000,6'b000001,6'b000010,6'b000011,6'b000100,6'b000101,6'b001001,6'b001010})) |-> (aluc == 5'd0)
    );

///// Inner func decode when op == 001000 /////
    // func 100000 -> aluc 0
    check_op001000_func100000_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100000) |-> (aluc == 5'd0)
    );

// func 100010 -> aluc 1
    check_op001000_func100010_aluc1: assert property (
