    );

// F=0 for 01101
    check_map_01101_is_0: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b01101) |-> (F == 1'b0)
    );

// F=1 for 01111
    check_map_01111_is_1: assert property (
