// DQ2 IE and OE are complementary
    check_dq2_ie_oe_mutex: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_2_o_ie == ~io_pins_dq_2_o_oe)
    );

// DQ3 pin output value equals SPI DQ3 output
    check_dq3_oval_map: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_3_o_oval == io_spi_dq_3_o)
    );

// DQ3 output enable equals SPI DQ3 OE
    check_dq3_oe_map: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_3_o_oe == io_spi_dq_3_oe)
    );

// DQ3 input enable is complement of SPI DQ3 OE
    check_dq3_ie_compl: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_3_o_ie == ~io_spi_dq_3_oe)
    );

// DQ3 pull-up enable is constant 1
    check_dq3_pue_const: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_3_o_pue == 1'b1)
    );

// DQ3 drive strength is constant 0
    check_dq3_ds_const: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_3_o_ds == 1'b0)
    );

// DQ3 IE and OE are complementary
    check_dq3_ie_oe_mutex: assert property (
        @(posedge clock) disable iff (reset) (io_pins_dq_3_o_ie == ~io_pins_dq_3_o_oe)
    );

// CS0 pin output value equals SPI CS0
    check_cs0_oval_map: assert property (
        @(posedge clock) disable iff (reset) (io_pins_cs_0_o_oval == io_spi_cs_0)
    );

// CS0 output enable is constant 1
    check_cs0_oe_const: assert property (
        @(posedge clock) disable iff (reset) (io_pins_cs_0_o_oe == 1'b1)
    );

// CS0 input enable is constant 0
    check_cs0_ie_const: assert property (
        @(posedge clock) disable iff (reset) (io_pins_cs_0_o_ie == 1'b0)
    );

// CS0 pull-up enable is constant 0
    check_cs0_pue_const: assert property (
        @(posedge clock) disable iff (reset) (io_pins_cs_0_o_pue == 1'b0)
    );

// CS0 drive strength is constant 0
    check_cs0_ds_const: assert property (
        @(posedge clock) disable iff (reset) (io_pins_cs_0_o_ds == 1'b0)
    );

// No clock/reset in RTL; pure combinational mux. Assertions sampled on external CLK.

    // EN low forces Y to 0.
    en_low_forces_y_zero: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (Y == 1'b0)
    );

// With EN high and SEL==00, Y equals ABCD[0].
    sel_00_routes_bit0: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b00) |-> (Y == ABCD[0])
    );

// With EN high and SEL==01, Y equals ABCD[1].
    sel_01_routes_bit1: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b01) |-> (Y == ABCD[1])
    );

// With EN high and SEL==10, Y equals ABCD[2].
    sel_10_routes_bit2: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b10) |-> (Y == ABCD[2])
    );

// With EN high and SEL==11, Y equals ABCD[3].
    sel_11_routes_bit3: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b11) |-> (Y == ABCD[3])
    );

// With EN high and unknown SEL, Y drives X (default case).
    unknown_sel_drives_x_when_en: assert property (
        @(posedge CLK) (EN == 1'b1 && $isunknown(SEL)) |-> (Y === 1'bx)
    );

// Functional equivalence sampled on A rising edge.
    check_func_eq_on_A: assert property (
        @(posedge A) Y == ((~C) | (A & B))
    );

// Functional equivalence sampled on B rising edge.
    check_func_eq_on_B: assert property (
        @(posedge B) Y == ((~C) | (A & B))
    );

// Functional equivalence sampled on C rising edge.
    check_func_eq_on_C: assert property (
        @(posedge C) Y == ((~C) | (A & B))
    );

// When C is LOW, Y must be HIGH (sampled on A).
    check_c_low_y_high_on_A: assert property (
        @(posedge A) (C == 1'b0) |-> (Y == 1'b1)
    );

// When C is LOW, Y must be HIGH (sampled on B).
    check_c_low_y_high_on_B: assert property (
        @(posedge B) (C == 1'b0) |-> (Y == 1'b1)
    );

// When C is HIGH, Y equals A&B (sampled on A).
    check_c_high_y_eq_ab_on_A: assert property (
        @(posedge A) (C == 1'b1) |-> (Y == (A & B))
    );

// When C is HIGH, Y equals A&B (sampled on B).
    check_c_high_y_eq_ab_on_B: assert property (
        @(posedge B) (C == 1'b1) |-> (Y == (A & B))
    );

// If both A and B are HIGH, Y must be HIGH (any C) sampled on A.
    check_ab_both_high_y_high_on_A: assert property (
        @(posedge A) (A == 1'b1 && B == 1'b1) |-> (Y == 1'b1)
    );

// If both A and B are HIGH, Y must be HIGH (any C) sampled on B.
    check_ab_both_high_y_high_on_B: assert property (
        @(posedge B) (A == 1'b1 && B == 1'b1) |-> (Y == 1'b1)
    );

// If Y is LOW then C must be HIGH and at least one of A or B is LOW (sampled on A).
    check_y_low_implies_c_high_and_not_ab_on_A: assert property (
        @(posedge A) (Y == 1'b0) |-> ((C == 1'b1) && ((A == 1'b0) || (B == 1'b0)))
    );

// If Y is HIGH then either C is LOW or both A and B are HIGH (sampled on B).
    check_y_high_implies_c_low_or_ab_on_B: assert property (
        @(posedge B) (Y == 1'b1) |-> ((C == 1'b0) || (A & B))
    );

// Y implements a 2:1 mux: Y == (E ? A : B).
    check_mux_function: assert property (
        @(posedge CLK) Y == (E ? A : B)
    );

// When E=1, Y must equal A.
    check_select_a_when_e1: assert property (
        @(posedge CLK) (E == 1'b1) |-> (Y == A)
    );

// When E=0, Y must equal B.
    check_select_b_when_e0: assert property (
        @(posedge CLK) (E == 1'b0) |-> (Y == B)
    );

// If A and B are equal, Y must equal that value regardless of E.
    check_equal_inputs_passthrough: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

///// Decoder correctness /////
    // When disabled, all outputs must be 0.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) (en == 1'b0) |-> (out == 8'b00000000)
    );

// When enabled, output must be non-zero.
    check_out_nonzero_when_enabled: assert property (
        @(posedge clk) (en == 1'b1) |-> (out != 8'b00000000)
    );

// When enabled, output must be one-hot.
    check_onehot_when_enabled: assert property (
        @(posedge clk) (en == 1'b1) |-> $onehot(out)
    );

// When enabled and in==000, out must be 00000001.
    check_decode_case_0: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b000) |-> (out == 8'b00000001)
    );

// When enabled and in==001, out must be 00000010.
    check_decode_case_1: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b001) |-> (out == 8'b00000010)
    );

// When enabled and in==010, out must be 00000100.
    check_decode_case_2: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b010) |-> (out == 8'b00000100)
    );

// When enabled and in==011, out must be 00001000.
    check_decode_case_3: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b011) |-> (out == 8'b00001000)
    );

// When enabled and in==100, out must be 00010000.
    check_decode_case_4: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b100) |-> (out == 8'b00010000)
    );

// When enabled and in==101, out must be 00100000.
    check_decode_case_5: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b101) |-> (out == 8'b00100000)
    );

// When enabled and in==110, out must be 01000000.
    check_decode_case_6: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b110) |-> (out == 8'b01000000)
    );

// When enabled and in==111, out must be 10000000.
    check_decode_case_7: assert property (
        @(posedge clk) (en == 1'b1 && in == 3'b111) |-> (out == 8'b10000000)
    );

// If any output bit is high, enable must be high.
    check_out_high_implies_enabled: assert property (
        @(posedge clk) (|out) |-> (en == 1'b1)
    );

// When enabled, the bit at index 'in' must be high.
    check_selected_bit_high_when_enabled: assert property (
        @(posedge clk) (en == 1'b1) |-> (out[in] == 1'b1)
    );

// No clock/reset in DUT; purely combinational NAND network. Assertions sample at posedge CLK; no reset gating.

    ///// Functional equivalence to RTL equations /////
    // S[0] equals ~(~(A0 & B0) & Cin).
    check_s0_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[0] === ~( (~(A[0] & B[0])) & Cin )
    );

// S[1] equals ~(~(A1 & B1) & ~(B0 & Cin)).
    check_s1_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[1] === ~( (~(A[1] & B[1])) & ~(B[0] & Cin) )
    );

// S[2] equals ~(~(A2 & B2) & ~(B1 & ~(B0 & Cin))).
    check_s2_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[2] === ~( (~(A[2] & B[2])) & ~(B[1] & ~(B[0] & Cin)) )
    );

// S[3] equals ~(~(A3 & B3) & ~(B2 & ~(B1 & ~(B0 & Cin)))).
    check_s3_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        S[3] === ~( (~(A[3] & B[3])) & ~(B[2] & ~(B[1] & ~(B[0] & Cin))) )
    );

// Cout equals ~(B3 & ~(B2 & ~(B1 & ~(B0 & Cin)))).
    check_cout_matches_logic: assert property (
        @(posedge CLK) disable iff (1'b0)
        Cout === ~( B[3] & ~(B[2] & ~(B[1] & ~(B[0] & Cin))) )
    );

///// Simple corner case implied by the NAND structure /////
    // When B==0, S[3:1]==0, S[0]==~Cin, Cout==1.
    check_behavior_when_B_is_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (B === 4'b0000) |-> ((S[3:1] === 3'b000) && (S[0] === ~Cin) && (Cout === 1'b1))
    );

// Reset high drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

///// Counter behavior /////
    // Synchronous reset drives count to 0.
    check_reset_clears_to_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// DUT is pure combinational; assertions are clocked on CLK and gated by active-low RESETn.

    // EQ must reflect A == B.
    check_eq_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) (EQ == (A == B))
    );

// GT must reflect A > B.
    check_gt_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) (GT == (A > B))
    );

// LT must reflect A < B.
    check_lt_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) (LT == (A < B))
    );

// Exactly one of {EQ, GT, LT} must be HIGH.
    check_outputs_onehot: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot({EQ, GT, LT})
    );

// If EQ is HIGH, GT and LT must be LOW.
    check_eq_excludes_others: assert property (
        @(posedge CLK) disable iff (!RESETn) EQ |-> (!GT && !LT)
    );

// If GT is HIGH, EQ and LT must be LOW.
    check_gt_excludes_others: assert property (
        @(posedge CLK) disable iff (!RESETn) GT |-> (!EQ && !LT)
    );

// If LT is HIGH, EQ and GT must be LOW.
    check_lt_excludes_others: assert property (
        @(posedge CLK) disable iff (!RESETn) LT |-> (!EQ && !GT)
    );

// EQ must equal the negation of (GT or LT).
    check_eq_is_complement_of_gt_or_lt: assert property (
        @(posedge CLK) disable iff (!RESETn) (EQ == !(GT || LT))
    );

// On any clock where reset is high, out must be 0 on the next clock.
    reset_clears_out_next: assert property (
        @(posedge clk) reset |=> (out == 4'd0)
    );

// If reset was high on the previous clock, out must be 0 now.
    reset_prev_cycle_forces_zero_now: assert property (
        @(posedge clk) $past(reset) |-> (out == 4'd0)
    );

// If reset is high on two consecutive clocks, out must be 0 now.
    reset_held_keeps_out_zero_now: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (out == 4'd0)
    );

// Sanity: out is always within 4-bit range (0..15).
    out_width_range: assert property (
        @(posedge clk) (out inside {[4'd0:4'd15]})
    );

// Y equals (A & B) OR (!C).
    check_functional_equivalence: assert property (
        @(posedge CLK) Y == ((A & B) | (!C))
    );

// When C is LOW, Y must be HIGH.
    check_c_low_dominates: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

// When C is HIGH, Y equals A & B.
    check_c_high_matches_and: assert property (
        @(posedge CLK) (C == 1'b1) |-> (Y == (A & B))
    );

// If Y is LOW, then C is HIGH and at least one of A or B is LOW.
    check_y_zero_implies_c_high_and_not_ab: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (C == 1'b1) && ((A == 1'b0) || (B == 1'b0))
    );

// If Y and C are HIGH, then both A and B are HIGH.
    check_y_and_c_high_implies_both_inputs_high: assert property (
        @(posedge CLK) (Y == 1'b1) && (C == 1'b1) |-> (A == 1'b1) && (B == 1'b1)
    );

// If Y is HIGH while A is LOW, then C must be LOW.
    check_y_high_and_a_low_implies_c_low: assert property (
        @(posedge CLK) (Y == 1'b1) && (A == 1'b0) |-> (C == 1'b0)
    );

// If Y is HIGH while B is LOW, then C must be LOW.
    check_y_high_and_b_low_implies_c_low: assert property (
        @(posedge CLK) (Y == 1'b1) && (B == 1'b0) |-> (C == 1'b0)
    );

// A falling edge on C forces Y HIGH (due to !C term).
    check_c_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(C) |-> (Y == 1'b1)
    );

// With C HIGH, a rising A when B is HIGH sets Y HIGH.
    check_c_high_a_rise_with_b1_sets_y: assert property (
        @(posedge CLK) (C == 1'b1) && $rose(A) && (B == 1'b1) |-> (Y == 1'b1)
    );

// With C HIGH, a rising B when A is HIGH sets Y HIGH.
    check_c_high_b_rise_with_a1_sets_y: assert property (
        @(posedge CLK) (C == 1'b1) && $rose(B) && (A == 1'b1) |-> (Y == 1'b1)
    );

// With C HIGH, a falling A clears Y LOW.
    check_c_high_a_fall_clears_y: assert property (
        @(posedge CLK) (C == 1'b1) && $fell(A) |-> (Y == 1'b0)
    );

// With C HIGH, a falling B clears Y LOW.
    check_c_high_b_fall_clears_y: assert property (
        @(posedge CLK) (C == 1'b1) && $fell(B) |-> (Y == 1'b0)
    );

// On a write_0r rising edge, write_0a equals bitwise NOT of write_0r.
    check_write_ack_inverse_on_write_edge: assert property (
        @(posedge write_0r) write_0a == ~write_0r
    );

// On a write_0r rising edge, write_0r and write_0a are never both HIGH.
    check_write_req_ack_mutex: assert property (
        @(posedge write_0r) !(write_0r && write_0a)
    );

// On a write_0r rising edge, exactly one of {write_0r, write_0a} is HIGH.
    check_write_req_ack_onehot: assert property (
        @(posedge write_0r) $onehot({write_0r, write_0a})
    );

// read_0a is a combinational pass-through of read_0r.
    check_read_accept_passthrough: assert property (
        @(posedge write_0r) read_0a == read_0r
    );

///// Reset behavior /////
    // On clr assertion, op is cleared on the next clock.
    reset_clears_op_next: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

// clr has priority over ce when both are asserted.
    reset_overrides_ce: assert property (
        @(posedge clk) (clr && ce) |=> (op == 1'b0)
    );

// With ce high and a == b, next op is 1.
    update_one_on_eq: assert property (
        @(posedge clk) disable iff (clr) (ce && (a == b)) |=> (op == 1'b1)
    );

// With ce high and a != b, next op is 0.
    update_zero_on_neq: assert property (
        @(posedge clk) disable iff (clr) (ce && (a != b)) |=> (op == 1'b0)
    );

///// Hold behavior /////
    // With ce low, op holds its value unless reset occurs next cycle.
    hold_when_ce_low: assert property (
        @(posedge clk) disable iff (clr) (!ce) |=> (clr || $stable(op))
    );

// During reset, out is forced to 0 on each clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (out == 4'd0)
    );

// When previous value was 15 and enable was 1 (no reset), counter wraps to 0.
    check_wrap_from_max_with_enable: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && $past(enable) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );

// DUT has no clock/reset; pure combinational AND: X = A & B; assertions sampled on CLK.

    // X equals A & B every sampled cycle.
    check_functional_and: assert property (
        @(posedge CLK) X == (A & B)
    );

// If X is 1, both inputs must be 1.
    check_x_one_implies_inputs_one: assert property (
        @(posedge CLK) X |-> (A && B)
    );

// If both inputs are 1, X must be 1.
    check_inputs_one_implies_x_one: assert property (
        @(posedge CLK) (A && B) |-> X
    );

// If A is 0, X must be 0.
    check_a_zero_forces_x_zero: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == 1'b0)
    );

// If B is 0, X must be 0.
    check_b_zero_forces_x_zero: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == 1'b0)
    );

// X can only rise when both inputs are 1.
    check_x_rise_requires_both_one: assert property (
        @(posedge CLK) $rose(X) |-> (A && B)
    );

// X can only fall when at least one input is 0.
    check_x_fall_requires_any_zero: assert property (
        @(posedge CLK) $fell(X) |-> (!A || !B)
    );

// When A rises with B=1, X must be 1 that cycle.
    check_a_rise_with_b1_implies_x1: assert property (
        @(posedge CLK) $rose(A) && (B == 1'b1) |-> (X == 1'b1)
    );

// When A falls with B=1, X must be 0 that cycle.
    check_a_fall_with_b1_implies_x0: assert property (
        @(posedge CLK) $fell(A) && (B == 1'b1) |-> (X == 1'b0)
    );

// Combinational DUT with no reset; use clk only for sampling.

    // Output equals input every sampled cycle.
    check_out_equals_in: assert property (
        @(posedge clk) out == in
    );

// For in==00, out must be 00.
    check_case_00: assert property (
        @(posedge clk) (in == 2'b00) |-> (out == 2'b00)
    );

// For in==01, out must be 01.
    check_case_01: assert property (
        @(posedge clk) (in == 2'b01) |-> (out == 2'b01)
    );

// For in==10, out must be 10.
    check_case_10: assert property (
        @(posedge clk) (in == 2'b10) |-> (out == 2'b10)
    );

// For in==11, out must be 11.
    check_case_11: assert property (
        @(posedge clk) (in == 2'b11) |-> (out == 2'b11)
    );

// eq is 1 iff all bits of in1 and in2 are equal.
  check_eq_function: assert property (
    @(posedge CLK) eq == (in1 == in2)
  );

// gt is 1 iff there exists a bit where in1=1 and in2=0.
  check_gt_function: assert property (
    @(posedge CLK) gt == (|(in1 & ~in2))
  );

// lt is 1 iff there exists a bit where in2=1 and in1=0.
  check_lt_function: assert property (
    @(posedge CLK) lt == (|(in2 & ~in1))
  );

// eq implies neither gt nor lt is asserted.
  check_eq_blocks_gt_lt: assert property (
    @(posedge CLK) eq |-> (!gt && !lt)
  );

// If inputs differ, at least one of gt or lt must be asserted.
  check_ineq_implies_flag: assert property (
    @(posedge CLK) (in1 != in2) |-> (gt || lt)
  );

// If either gt or lt is asserted, inputs must differ.
  check_flag_implies_ineq: assert property (
    @(posedge CLK) (gt || lt) |-> (in1 != in2)
  );

// eq is the logical complement of (gt || lt).
  check_eq_complements_flags: assert property (
    @(posedge CLK) eq == !(gt || lt)
  );

///// Reset behavior /////
    // While reset is asserted, counter and toggle are 0 and clk_baud is LOW.
    reset_drive_low: assert property (
        @(posedge clk) !rst_n |-> (counter == 32'd0) && (toggle == 1'b0) && (clk_baud == 1'b0)
    );

// Y is always the logical inversion of A.
    check_complement_always: assert property (
        @(posedge CLK) (Y === ~A)
    );

// When A is 0, Y must be 1.
    check_y1_when_a0: assert property (
        @(posedge CLK) (A === 1'b0) |-> (Y === 1'b1)
    );

// When A is 1, Y must be 0.
    check_y0_when_a1: assert property (
        @(posedge CLK) (A === 1'b1) |-> (Y === 1'b0)
    );

// Known A implies known Y.
    check_known_y_when_known_a: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> (!$isunknown(Y))
    );

// Known Y implies known A.
    check_known_a_when_known_y: assert property (
        @(posedge CLK) (!$isunknown(Y)) |-> (!$isunknown(A))
    );

// When both are known, A and Y must differ.
    check_known_values_inequal: assert property (
        @(posedge CLK) (!($isunknown({A,Y}))) |-> (A != Y)
    );

// Clock: clk (posedge). Reset: none. Logic: FF with enable; q_bar is ~q.

    // q_bar is always the bitwise complement of q.
    check_qbar_complement: assert property (
        @(posedge clk) q_bar == ~q
    );

// During reset, id_pcplus4 drives 4.
    reset_id_pcplus4_value: assert property (
        @(posedge clk) rst |-> (id_pcplus4 == 32'd4)
    );

// During reset, id_instr drives 32'b100000.
    reset_id_instr_value: assert property (
        @(posedge clk) rst |-> (id_instr == 32'b100000)
    );

// During reset, id_pc drives 0.
    reset_id_pc_value: assert property (
        @(posedge clk) rst |-> (id_pc == 32'd0)
    );

// If stall or BJ in the previous cycle, id_instr flushes to 32'b100000.
    id_instr_flush_on_stall_or_BJ: assert property (
        @(posedge clk) disable iff (rst) $past(!rst && (stall | BJ)) |-> (id_instr == 32'b100000)
    );

// If reset is asserted on this clock, count is 0 on the next clock.
    check_sync_reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 3'd0)
    );

// While reset is held across consecutive cycles, count stays at 0.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 3'd0)
    );

// During reset (EN high) at a CLK edge, ENCLK must be low.
    check_sync_clear_when_en_high: assert property (
        @(posedge CLK) EN |-> (ENCLK == 1'b0)
    );

// ENCLK is known (not X/Z) on each CLK edge.
    check_enclk_known_on_clk: assert property (
        @(posedge CLK) !$isunknown(ENCLK)
    );

// Output equals the AND of all four inputs.
    check_y_is_and4: assert property (
        @(posedge clk) Y == (A & B & C & D)
    );

// Y can be 1 only if all inputs are 1.
    check_y_high_requires_all_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1))
    );

// A low forces Y low.
    check_a_zero_forces_y_zero: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b0)
    );

// B low forces Y low.
    check_b_zero_forces_y_zero: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

// C low forces Y low.
    check_c_zero_forces_y_zero: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b0)
    );

// D low forces Y low.
    check_d_zero_forces_y_zero: assert property (
        @(posedge clk) (D == 1'b0) |-> (Y == 1'b0)
    );

// All inputs high forces Y high.
    check_all_high_forces_y_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1)) |-> (Y == 1'b1)
    );

// sum expressed only with primary inputs.
    check_sum_inputs_only: assert property (
        @(posedge clk) sum == (((A | B) & C) ^ (A ^ B ^ C))
    );

// When A, B, and C are equal bitwise, sum is all zeros.
    check_sum_zero_when_all_equal: assert property (
        @(posedge clk) ((A == B) && (B == C)) |-> (sum == 4'b0000)
    );

// When C is all zeros, sum reduces to A XOR B.
    check_sum_when_C_zero: assert property (
        @(posedge clk) (C == 4'b0000) |-> (sum == (A ^ B))
    );

// When C is all ones, sum equals (A OR B) XOR NOT (A XOR B).
    check_sum_when_C_allones: assert property (
        @(posedge clk) (C == 4'hF) |-> (sum == ((A | B) ^ ~(A ^ B)))
    );

///// Combinational function correctness /////
    // Out equals NAND(a,b) OR (NAND(a,b) XOR c).
    check_func_via_gate_chain: assert property (
        @(posedge a) out == ((~(a & b)) | ((~(a & b)) ^ c))
    );

// Out equals (~a) | (~b) | c (simplified form).
    check_func_demorgan: assert property (
        @(posedge a) out == ((~a) | (~b) | c)
    );

///// Canonical input/output implications /////
    // If a is LOW then out is HIGH.
    check_out_high_when_a_low: assert property (
        @(posedge b) (!a) |-> (out == 1'b1)
    );

// If b is LOW then out is HIGH.
    check_out_high_when_b_low: assert property (
        @(posedge a) (!b) |-> (out == 1'b1)
    );

// If c is HIGH then out is HIGH.
    check_out_high_when_c_high: assert property (
        @(posedge a) (c) |-> (out == 1'b1)
    );

///// Corner cases and equivalences /////
    // Out is zero only when a=1,b=1,c=0.
    check_only_zero_on_110: assert property (
        @(posedge a) (out == 1'b0) |-> (a && b && !c)
    );

// When a=1 and b=1, out equals c.
    check_ab_high_out_equals_c: assert property (
        @(posedge a) (a && b) |-> (out == c)
    );

// When c=0, out equals ~(a & b).
    check_c_low_out_equals_nand: assert property (
        @(posedge a) (!c) |-> (out == ~(a & b))
    );

// When a=1 and c=0, out equals ~b.
    check_a_high_c_low_out_equals_notb: assert property (
        @(posedge a) (a && !c) |-> (out == ~b)
    );

// When b=1 and c=0, out equals ~a.
    check_b_high_c_low_out_equals_nota: assert property (
        @(posedge a) (b && !c) |-> (out == ~a)
    );

// If a=1,b=1,c=0 then out is 0 (explicit zero-case).
    check_110_implies_zero: assert property (
        @(posedge a) (a && b && !c) |-> (out == 1'b0)
    );

// Reset low forces count to 0 at every sampled clock
    check_reset_low_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 4'h0)
    );

// Load (active-low) captures data_in on next cycle
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && ($past(load) == 1'b0)) |-> (count == $past(data_in))
    );

// With no load and direction==1, count increments by 1
    check_increment_when_dir1: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && ($past(load) == 1'b1) && ($past(direction) == 1'b1)) |-> (count == $past(count) + 4'd1)
    );

// With no load and direction==0, count decrements by 1
    check_decrement_when_dir0: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && ($past(load) == 1'b1) && ($past(direction) == 1'b0)) |-> (count == $past(count) - 4'd1)
    );

// Wrap-around on increment from 0xF to 0x0
    check_increment_wrap_from_F_to_0: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && ($past(load) == 1'b1) && ($past(direction) == 1'b1) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// Wrap-around on decrement from 0x0 to 0xF
    check_decrement_wrap_from_0_to_F: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && ($past(load) == 1'b1) && ($past(direction) == 1'b0) && ($past(count) == 4'h0)) |-> (count == 4'hF)
    );

// No-load update matches direction (+1 if 1, -1 if 0)
    check_no_load_update_matches_direction: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && ($past(load) == 1'b1)) |-> (count == ($past(direction) ? ($past(count) + 4'd1) : ($past(count) - 4'd1)))
    );

// Full next-state function: load has priority over counting
    check_full_next_state_function: assert property (
        @(posedge clk) disable iff (!reset)
            $past(reset) |-> (count ==
                (($past(load) == 1'b0) ? $past(data_in)
                                       : ($past(direction) ? ($past(count) + 4'd1)
                                                           : ($past(count) - 4'd1))))
    );

// B must equal binary-to-Gray conversion: A ^ (A >> 1).
    check_gray_formula: assert property (
        @(posedge CLK) disable iff (1'b0) B == (A ^ (A >> 1))
    );

// When A==0000, B must be 0000.
    check_map_A_0000: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0000) |-> (B == 4'b0000)
    );

// When A==0001, B must be 0001.
    check_map_A_0001: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0001) |-> (B == 4'b0001)
    );

// When A==0010, B must be 0011.
    check_map_A_0010: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0010) |-> (B == 4'b0011)
    );

// When A==0011, B must be 0010.
    check_map_A_0011: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0011) |-> (B == 4'b0010)
    );

// When A==0100, B must be 0110.
    check_map_A_0100: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0100) |-> (B == 4'b0110)
    );

// When A==0101, B must be 0111.
    check_map_A_0101: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0101) |-> (B == 4'b0111)
    );

// When A==0110, B must be 0101.
    check_map_A_0110: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0110) |-> (B == 4'b0101)
    );

// When A==0111, B must be 0100.
    check_map_A_0111: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b0111) |-> (B == 4'b0100)
    );

// When A==1000, B must be 1100.
    check_map_A_1000: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1000) |-> (B == 4'b1100)
    );

// When A==1001, B must be 1101.
    check_map_A_1001: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1001) |-> (B == 4'b1101)
    );

// When A==1010, B must be 1111.
    check_map_A_1010: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1010) |-> (B == 4'b1111)
    );

// When A==1011, B must be 1110.
    check_map_A_1011: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1011) |-> (B == 4'b1110)
    );

// When A==1100, B must be 1010.
    check_map_A_1100: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1100) |-> (B == 4'b1010)
    );

// When A==1101, B must be 1011.
    check_map_A_1101: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1101) |-> (B == 4'b1011)
    );

// When A==1110, B must be 1001.
    check_map_A_1110: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1110) |-> (B == 4'b1001)
    );

// When A==1111, B must be 1000.
    check_map_A_1111: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 4'b1111) |-> (B == 4'b1000)
    );

// Combinational NAND3 cell; no clock/reset. Sample assertions on input posedges.

    // Y equals ~(A & B & C) when sampled on A rising edge.
    check_nand_truth_on_A: assert property (
        @(posedge A) Y == ~(A & B & C)
    );

// Y equals ~(A & B & C) when sampled on B rising edge.
    check_nand_truth_on_B: assert property (
        @(posedge B) Y == ~(A & B & C)
    );

// Y equals ~(A & B & C) when sampled on C rising edge.
    check_nand_truth_on_C: assert property (
        @(posedge C) Y == ~(A & B & C)
    );

// If all inputs are HIGH then Y must be LOW (sampled on A).
    check_all_high_implies_low_on_A: assert property (
        @(posedge A) (A && B && C) |-> (Y == 1'b0)
    );

// If all inputs are HIGH then Y must be LOW (sampled on B).
    check_all_high_implies_low_on_B: assert property (
        @(posedge B) (A && B && C) |-> (Y == 1'b0)
    );

// If all inputs are HIGH then Y must be LOW (sampled on C).
    check_all_high_implies_low_on_C: assert property (
        @(posedge C) (A && B && C) |-> (Y == 1'b0)
    );

// If any input is LOW then Y must be HIGH (sampled on A).
    check_any_low_implies_high_on_A: assert property (
        @(posedge A) ((!A) || (!B) || (!C)) |-> (Y == 1'b1)
    );

// If any input is LOW then Y must be HIGH (sampled on B).
    check_any_low_implies_high_on_B: assert property (
        @(posedge B) ((!A) || (!B) || (!C)) |-> (Y == 1'b1)
    );

// If any input is LOW then Y must be HIGH (sampled on C).
    check_any_low_implies_high_on_C: assert property (
        @(posedge C) ((!A) || (!B) || (!C)) |-> (Y == 1'b1)
    );

// Clock: clk (posedge). Reset: reset (active-high, asynchronous).
    // Logic: sequential with async reset; count=0 on reset, else count increments modulo 16.

    // While reset is HIGH at the clock edge, count must be 0.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// If reset is HIGH on two consecutive clock edges, count holds its value (remains 0).
    check_reset_held_stable: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == $past(count))
    );

// One cycle after reset falls at a clock edge, the counter advances to 1.
    check_first_count_after_reset_fall: assert property (
        @(posedge clk) $fell(reset) |=> (count == 4'd1)
    );

// Count is always within 4-bit range (sanity check).
    check_count_range: assert property (
        @(posedge clk) (count <= 4'd15)
    );

// Reset sets RTY_O, interrupt_o, and counter to 0 on the next cycle.
    reset_clears_outputs_and_counter: assert property (
        @(posedge CLK_I) RST_I |=> (RTY_O == 1'b0) && (interrupt_o == 1'b0) && (counter == 28'd0)
    );

// Y equals B1_N | (~A1 & ~A2).
    check_functional_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y == (B1_N | ((!A1) & (!A2)))
    );

// Y equals ~( (~B1_N) & (A1 | A2) ).
    check_demorgan_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ~( (~B1_N) & (A1 | A2) )
    );

// B1_N high forces Y high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) (B1_N == 1'b1) |-> (Y == 1'b1)
    );

// When B1_N is low, Y equals NOR(A1, A2).
    check_b1n_low_gives_nor: assert property (
        @(posedge CLK) disable iff (1'b0) (B1_N == 1'b0) |-> (Y == !(A1 || A2))
    );

// If B1_N is low and (A1 or A2) is high, Y must be low.
    check_enable_low_and_any_input_high_makes_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N == 1'b0) && ((A1 == 1'b1) || (A2 == 1'b1))) |-> (Y == 1'b0)
    );

// If both A1 and A2 are low, Y must be high.
    check_both_inputs_low_makes_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) ((!A1) && (!A2)) |-> (Y == 1'b1)
    );

// Y low implies B1_N is low and at least one of A1/A2 is high.
    check_y_low_characterization: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b0) |-> ((B1_N == 1'b0) && ((A1 == 1'b1) || (A2 == 1'b1)))
    );

// Y high implies B1_N is high or both A1 and A2 are low.
    check_y_high_characterization: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b1) |-> ((B1_N == 1'b1) || ((!A1) && (!A2)))
    );

// With B1_N low and both A1 and A2 high, Y must be low.
    check_b1n_low_and_both_high_makes_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N == 1'b0) && (A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

// Rising A1 under B1_N low forces Y low that cycle.
    check_a1_rise_under_b1n_low_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ($rose(A1) && (B1_N == 1'b0)) |-> (Y == 1'b0)
    );

// Rising A2 under B1_N low forces Y low that cycle.
    check_a2_rise_under_b1n_low_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ($rose(A2) && (B1_N == 1'b0)) |-> (Y == 1'b0)
    );

// Out equals in when vdd18=1, else zero.
    check_functional_mapping: assert property (
        @(posedge clk) out == (vdd18 ? in : 8'h00)
    );

// On vdd18 rising edge, out equals in.
    check_on_power_rise: assert property (
        @(posedge clk) $rose(vdd18) |-> (out == in)
    );

// On vdd18 falling edge, out is zero.
    check_on_power_fall: assert property (
        @(posedge clk) $fell(vdd18) |-> (out == 8'h00)
    );

// When vdd18=0 and in changes, out remains zero.
    check_ignore_input_when_power_low: assert property (
        @(posedge clk) (!vdd18 && $changed(in)) |-> (out == 8'h00)
    );

// When vdd18=1 and in changes, out equals in.
    check_follow_input_when_power_high: assert property (
        @(posedge clk) (vdd18 && $changed(in)) |-> (out == in)
    );

// Non-zero out implies vdd18 is high.
    check_nonzero_out_implies_power_high: assert property (
        @(posedge clk) (out != 8'h00) |-> vdd18
    );

// On any cycle with reset asserted, count is driven to 0.
    reset_drives_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

///// Reset behavior /////
    // While reset is asserted HIGH, the displayed value is 00.
    reset_drives_zero: assert property (
        @(posedge clk) reset |-> (data_MM == 8'h00)
    );

///// Output encoding rules /////
    // data_MM is always a valid 2-digit BCD value in the range 00..59.
    bcd_range_valid: assert property (
        @(posedge clk) disable iff (reset) is_valid_bcd_00_59(data_MM)
    );

///// Hold behavior /////
    // When en_count != 2, the value holds (no change next cycle).
    hold_when_count_disabled: assert property (
        @(posedge clk) disable iff (reset)
            (en_count != 4'd2) |=> (data_MM == $past(data_MM))
    );

// When enabled (en_count==2) but no direction requested, the value holds.
    hold_when_no_dir_enabled: assert property (
        @(posedge clk) disable iff (reset)
            (en_count == 4'd2) && !enUP && !enDOWN |=> (data_MM == $past(data_MM))
    );

// When writing, no read is asserted in the same cycle.
    check_no_read_when_write: assert property (
        @(posedge clk) disable iff (!reset_n)
            cpu_d_write |-> (cpu_d_read == 1'b0)
    );

// When not writing, address is zero.
    check_address_zero_when_not_write: assert property (
        @(posedge clk) disable iff (!reset_n)
            !cpu_d_write |-> (cpu_d_address == 25'd0)
    );

// When writing, address matches prior d_address.
    check_address_matches_when_write: assert property (
        @(posedge clk) disable iff (!reset_n)
            (cpu_d_write && $past(reset_n)) |-> (cpu_d_address == $past(d_address))
    );

// When writing, writedata matches prior E_st_data.
    check_writedata_matches_when_write: assert property (
        @(posedge clk) disable iff (!reset_n)
            (cpu_d_write && $past(reset_n)) |-> (cpu_d_writedata == $past(E_st_data))
    );

// If no read occurred last cycle, readdata is zero.
    check_readdata_zero_when_no_read: assert property (
        @(posedge clk) disable iff (!reset_n)
            ($past(reset_n) && !$past(d_read)) |-> (cpu_d_readdata == 32'd0)
    );

// Trace/control-related outputs are always zero when not in reset.
    check_dbrk_static_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
            (dbrk_goto0 == 1'b0) &&
            (dbrk_goto1 == 1'b0) &&
            (dbrk_traceme == 1'b0) &&
            (dbrk_traceoff == 1'b0) &&
            (dbrk_traceon == 1'b0) &&
            (dbrk_trigout == 1'b0)
    );

// Analysis: No clock or reset in DUT; purely combinational; X = A & B & C.

    // Functional equivalence sampled on A rising.
    check_func_on_A_edge: assert property (
        @(posedge A) X == (A & B & C)
    );

// Functional equivalence sampled on B rising.
    check_func_on_B_edge: assert property (
        @(posedge B) X == (A & B & C)
    );

// Functional equivalence sampled on C rising.
    check_func_on_C_edge: assert property (
        @(posedge C) X == (A & B & C)
    );

// Functional equivalence sampled on X rising.
    check_func_on_X_edge: assert property (
        @(posedge X) X == (A & B & C)
    );

// If X is HIGH, all inputs must be HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge X) X |-> (A && B && C)
    );

// When A=0, out equals the concatenation {A,B,C,D}.
    check_out_concat_when_a_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (out == {A, B, C, D})
    );

// When A=0, out[3] is 0.
    check_out_msb_zero_when_a_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (out[3] == 1'b0)
    );

// When A=0, out[2] mirrors B.
    check_out_bit2_matches_B_when_a_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (out[2] == B)
    );

// When A=0, out[1] mirrors C.
    check_out_bit1_matches_C_when_a_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (out[1] == C)
    );

// When A=0, out[0] mirrors D.
    check_out_bit0_matches_D_when_a_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (out[0] == D)
    );

// When A=1, out replicates (B&C&D) across all 4 bits.
    check_out_replication_when_a_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (out == {4{B & C & D}})
    );

// When A=1 and B=C=D=1, out is 4'hF.
    check_out_F_when_a_high_all_ones: assert property (
        @(posedge CLK) (A & B & C & D) |-> (out == 4'hF)
    );

// When A=1 and any of B,C,D is 0, out is 4'h0.
    check_out_zero_when_a_high_any_zero: assert property (
        @(posedge CLK) (A && !(B & C & D)) |-> (out == 4'h0)
    );

// When A=1, out[3] equals (B&C&D).
    check_out_msb_equals_and_when_a_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (out[3] == (B & C & D))
    );

// When A=1, out[0] equals (B&C&D).
    check_out_lsb_equals_and_when_a_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (out[0] == (B & C & D))
    );

// SET forces Q to 1 on the next clock.
    check_set_forces_one: assert property (
        @(posedge CLK) SET |=> (Q == 1'b1)
    );

// When both SET and SLEEP_B are high, SET has priority and Q becomes 1.
    check_set_overrides_sleep: assert property (
        @(posedge CLK) (SET && SLEEP_B) |=> (Q == 1'b1)
    );

// With SET low and SLEEP_B high, Q is cleared to 0.
    check_sleep_clears_when_no_set: assert property (
        @(posedge CLK) (!SET && SLEEP_B) |=> (Q == 1'b0)
    );

// With no controls and D=1, Q becomes 1 next cycle.
    check_d1_captured_when_no_controls: assert property (
        @(posedge CLK) (!SET && !SLEEP_B && (D == 1'b1)) |=> (Q == 1'b1)
    );

// With no controls and D=0, Q becomes 0 next cycle.
    check_d0_captured_when_no_controls: assert property (
        @(posedge CLK) (!SET && !SLEEP_B && (D == 1'b0)) |=> (Q == 1'b0)
    );

// Sum never exceeds 30 (15+15).
    check_output_range: assert property (
        @(posedge CLK) C <= 5'd30
    );

// Out follows the case selection: add, subtract, or zero.
    check_case_function: assert property (
        @(posedge clk) out == ((control == 2'b00) ? (a + b) :
                               (control == 2'b01) ? (a - b) :
                               4'b0000)
    );

// When control==00, out equals a + b.
    check_addition_selected: assert property (
        @(posedge clk) (control == 2'b00) |-> (out == (a + b))
    );

// When control==01, out equals a - b.
    check_subtraction_selected: assert property (
        @(posedge clk) (control == 2'b01) |-> (out == (a - b))
    );

// When control==10, out is zero.
    check_default_zero_10: assert property (
        @(posedge clk) (control == 2'b10) |-> (out == 4'b0000)
    );

// When control==11, out is zero.
    check_default_zero_11: assert property (
        @(posedge clk) (control == 2'b11) |-> (out == 4'b0000)
    );

// MSB of control high implies out is zero (covers 10 and 11).
    check_default_zero_msb: assert property (
        @(posedge clk) control[1] |-> (out == 4'b0000)
    );

// Clk: clk (posedge). Reset: rst (active-high, asynchronous). Sequential register with async reset and load-enable.

    // Reset asserted: Q becomes zero on the next sampled clock edge.
    check_reset_clears_q_next: assert property (
        @(posedge clk) rst |=> (Q == 12'b0)
    );

// While reset stays asserted across consecutive clocks, Q is zero each sampled cycle.
    check_reset_held_forces_zero_each_cycle: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (Q == 12'b0)
    );

// If reset and load are both high at a clock edge, Q is zero on the next sampled edge (reset dominates).
    check_reset_dominates_load_next: assert property (
        @(posedge clk) (rst && load) |=> (Q == 12'b0)
    );

// Immediately after a sampled reset deassertion, Q is still zero at that clock edge.
    check_q_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(rst) |-> (Q == 12'b0)
    );

// After a sampled reset, if no load occurs on the following clock, Q remains zero.
    check_zero_persists_after_reset_without_load: assert property (
        @(posedge clk) disable iff (rst) ($past(rst) && !load) |-> (Q == 12'b0)
    );

// On a sampled reset rising edge, Q becomes zero on the next sampled clock edge.
    check_q_zero_on_reset_rise_next: assert property (
        @(posedge clk) $rose(rst) |=> (Q == 12'b0)
    );

// Sum and overflow equal the 9-bit unsigned addition of a and b.
    check_sum_and_overflow_exact: assert property (
        @(posedge CLK) {overflow, sum} == ({1'b0, a} + {1'b0, b})
    );

// If overflow is 1, the wrapped sum is less than operand a.
    check_overflow_implies_sum_lt_a: assert property (
        @(posedge CLK) overflow |-> (sum < a)
    );

// If overflow is 1, the wrapped sum is less than operand b.
    check_overflow_implies_sum_lt_b: assert property (
        @(posedge CLK) overflow |-> (sum < b)
    );

// If no overflow, sum is greater than or equal to operand a.
    check_no_overflow_ge_a: assert property (
        @(posedge CLK) !overflow |-> (sum >= a)
    );

// If no overflow, sum is greater than or equal to operand b.
    check_no_overflow_ge_b: assert property (
        @(posedge CLK) !overflow |-> (sum >= b)
    );

// Adding zero on b passes a through and no overflow.
    check_add_zero_b: assert property (
        @(posedge CLK) (b == 8'h00) |-> (sum == a) && (overflow == 1'b0)
    );

// Adding zero on a passes b through and no overflow.
    check_add_zero_a: assert property (
        @(posedge CLK) (a == 8'h00) |-> (sum == b) && (overflow == 1'b0)
    );

// 0xFF + 0x01 wraps to 0x00 with overflow.
    check_ff_plus_one: assert property (
        @(posedge CLK) (a == 8'hFF && b == 8'h01) |-> (sum == 8'h00) && (overflow == 1'b1)
    );

// When a is 0xFF, sum equals b-1 (mod 256) and overflow when b != 0.
    check_ff_operand_a: assert property (
        @(posedge CLK) (a == 8'hFF) |-> (sum == (b - 8'h01)) && (overflow == (b != 8'h00))
    );

// When b is 0xFF, sum equals a-1 (mod 256) and overflow when a != 0.
    check_ff_operand_b: assert property (
        @(posedge CLK) (b == 8'hFF) |-> (sum == (a - 8'h01)) && (overflow == (a != 8'h00))
    );

// Clock: clk (posedge). Reset: reset_n (active-low, asynchronous). Sequential DFF with enable.

    // Reset low forces q to 0 on every clock edge while asserted.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset_n |-> (q == 1'b0)
    );

// First cycle after reset (prev reset low): if enable is 0, q must remain 0.
    check_post_reset_hold_zero_if_disabled: assert property (
        @(posedge clk) disable iff (!reset_n)
            ($past(!reset_n) && !enable) |-> (q == 1'b0)
    );

// Synchronous reset drives output_signal to zero on the next cycle.
    reset_clears_output_next: assert property (
        @(posedge clk) reset |=> (output_signal == 16'h0000)
    );

///// Reset behavior /////
    // During reset, muxreg and muxreg_valid are driven to zero.
    reset_drives_regs_zero: assert property (
        @(posedge clk) rst |-> (muxreg == '0) && (muxreg_valid == 1'b0)
    );

// Left shift definition: dir==0 makes out = in << shift.
    check_left_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b0) |-> (out == (in << shift))
    );

// Right shift definition: dir==1 makes out = in >> shift.
    check_right_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b1) |-> (out == (in >> shift))
    );

// Zero shift is identity regardless of dir.
    check_shift_zero_identity: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

// Zero input yields zero output for any dir/shift.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (in == 16'h0000) |-> (out == 16'h0000)
    );

// Left shift zero-fill: lower 'shift' bits of out are zero.
    check_left_zero_fill_lowbits: assert property (
        @(posedge CLK) (dir == 1'b0) |-> ((out & (((16'h0001 << shift) - 16'h0001))) == 16'h0000)
    );

// Right shift zero-fill: upper 'shift' bits of out are zero.
    check_right_zero_fill_highbits: assert property (
        @(posedge CLK) (dir == 1'b1) |-> ((out & (16'hFFFF << (16 - shift))) == 16'h0000)
    );

// Left shift by 15: out[14:0]==0 and out[15]==in[0].
    check_left_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd15)) |-> ((out[14:0] == 15'b0) && (out[15] == in[0]))
    );

// Right shift by 15: out[15:1]==0 and out[0]==in[15].
    check_right_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd15)) |-> ((out[15:1] == 15'b0) && (out[0] == in[15]))
    );

// Left shift by 1: LSB zero and remaining bits align with in.
    check_left_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd1)) |-> ((out[0] == 1'b0) && (out[15:1] == in[14:0]))
    );

// Right shift by 1: MSB zero and remaining bits align with in.
    check_right_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd1)) |-> ((out[15] == 1'b0) && (out[14:0] == in[15:1]))
    );

// On reset, next cycle drives count=0 and enable=0.
  reset_next_outputs_zero: assert property (
    @(posedge clk) reset |=> (count == 3'b000) && (enable == 1'b0)
  );

// From count=0, next is 1 and enable=0.
  next_from_0: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b000) |=> (count == 3'b001) && (enable == 1'b0)
  );

// From count=1, next is 2 and enable=0.
  next_from_1: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b001) |=> (count == 3'b010) && (enable == 1'b0)
  );

// From count=2, next is 3 and enable=0.
  next_from_2: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b010) |=> (count == 3'b011) && (enable == 1'b0)
  );

// From count=3, next is 4 and enable=0.
  next_from_3: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b011) |=> (count == 3'b100) && (enable == 1'b0)
  );

// From count=4, next is 5 and enable=0.
  next_from_4: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b100) |=> (count == 3'b101) && (enable == 1'b0)
  );

// From count=5, next is 0 and enable=1.
  next_from_5: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b101) |=> (count == 3'b000) && (enable == 1'b1)
  );

// From count=6, next is 7 and enable=0.
  next_from_6: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b110) |=> (count == 3'b111) && (enable == 1'b0)
  );

// From count=7, next is 0 and enable=0.
  next_from_7: assert property (
    @(posedge clk) disable iff (reset) (count == 3'b111) |=> (count == 3'b000) && (enable == 1'b0)
  );

///// Functional correctness for each op /////
    // When op==00, result is 8-bit a+b (wrap).
    check_add_correct: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == add8(a, b))
    );

// When op==01, result is 8-bit a-b (wrap).
    check_sub_correct: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == sub8(a, b))
    );

///// Simple algebraic identities per operation /////
    // Add: +0 is identity.
    check_add_identity_b0: assert property (
        @(posedge clk) (op == 2'b00) && (b == 8'h00) |-> (result == a)
    );

// Add: 0+ is identity.
    check_add_identity_a0: assert property (
        @(posedge clk) (op == 2'b00) && (a == 8'h00) |-> (result == b)
    );

// Sub: -0 is identity.
    check_sub_identity_b0: assert property (
        @(posedge clk) (op == 2'b01) && (b == 8'h00) |-> (result == a)
    );

// Sub: x-x = 0 (8-bit wrap).
    check_sub_self_zero: assert property (
        @(posedge clk) (op == 2'b01) && (a == b) |-> (result == 8'h00)
    );

// Analysis: no clock/reset in DUT; purely combinational; maps 4 encodings, else invalid.

    // data_in == 8'h01 maps to data_out == 4'h1 with valid == 1
    check_map_sym1: assert property (
        @(posedge CLK) (data_in == 8'h01) |-> ((data_out == 4'h1) && (valid == 1'b1))
    );

// data_in == 8'h02 maps to data_out == 4'h2 with valid == 1
    check_map_sym2: assert property (
        @(posedge CLK) (data_in == 8'h02) |-> ((data_out == 4'h2) && (valid == 1'b1))
    );

// data_in == 8'h04 maps to data_out == 4'h3 with valid == 1
    check_map_sym3: assert property (
        @(posedge CLK) (data_in == 8'h04) |-> ((data_out == 4'h3) && (valid == 1'b1))
    );

// data_in == 8'h08 maps to data_out == 4'h4 with valid == 1
    check_map_sym4: assert property (
        @(posedge CLK) (data_in == 8'h08) |-> ((data_out == 4'h4) && (valid == 1'b1))
    );

// For all other data_in values, data_out == 0 and valid == 0
    check_default_map: assert property (
        @(posedge CLK) !(data_in inside {8'h01,8'h02,8'h04,8'h08}) |-> ((data_out == 4'h0) && (valid == 1'b0))
    );

// valid == 1 occurs only for recognized inputs
    check_valid_high_implies_recognized: assert property (
        @(posedge CLK) (valid == 1'b1) |-> (data_in inside {8'h01,8'h02,8'h04,8'h08})
    );

// Recognized inputs always produce valid == 1
    check_recognized_implies_valid_high: assert property (
        @(posedge CLK) (data_in inside {8'h01,8'h02,8'h04,8'h08}) |-> (valid == 1'b1)
    );

// valid == 0 implies data_out == 0
    check_valid_low_implies_zero: assert property (
        @(posedge CLK) (valid == 1'b0) |-> (data_out == 4'h0)
    );

// data_out == 0 implies valid == 0
    check_zero_implies_valid_low: assert property (
        @(posedge CLK) (data_out == 4'h0) |-> (valid == 1'b0)
    );

// Non-zero data_out implies recognized input and valid == 1
    check_nonzero_out_implies_recognized_and_valid: assert property (
        @(posedge CLK) (data_out != 4'h0) |-> ((data_in inside {8'h01,8'h02,8'h04,8'h08}) && (valid == 1'b1))
    );

// valid == 1 implies data_out is one of 4'h1..4'h4
    check_valid_high_implies_known_code: assert property (
        @(posedge CLK) (valid == 1'b1) |-> (data_out inside {4'h1,4'h2,4'h3,4'h4})
    );

// EQ must reflect (A == B).
    check_eq_definition: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

// GT must reflect (A > B).
    check_gt_definition: assert property (
        @(posedge CLK) (GT === (A > B))
    );

// EQ and GT cannot be high at the same time.
    check_outputs_mutex: assert property (
        @(posedge CLK) !((EQ === 1'b1) && (GT === 1'b1))
    );

// When A == B, outputs must be EQ=1 and GT=0.
    check_equal_case_outputs: assert property (
        @(posedge CLK) (A == B) |-> ((EQ === 1'b1) && (GT === 1'b0))
    );

// When A > B, outputs must be GT=1 and EQ=0.
    check_greater_case_outputs: assert property (
        @(posedge CLK) (A > B) |-> ((GT === 1'b1) && (EQ === 1'b0))
    );

// When A < B, outputs must be EQ=0 and GT=0.
    check_less_case_outputs: assert property (
        @(posedge CLK) (A < B) |-> ((EQ === 1'b0) && (GT === 1'b0))
    );

// If EQ is asserted, inputs must be equal.
    check_eq_high_implies_inputs_equal: assert property (
        @(posedge CLK) (EQ === 1'b1) |-> (A == B)
    );

// If GT is asserted, A must be greater than B.
    check_gt_high_implies_a_greater: assert property (
        @(posedge CLK) (GT === 1'b1) |-> (A > B)
    );

// On any cycle with reset asserted, count must be 0 on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

// When not in reset, reaching max_value causes wrap to 0 on the next cycle.
    wrap_on_reaching_max: assert property (
        @(posedge clk) disable iff (reset) (count == max_value) |=> (count == 32'd0)
    );

// When not in reset and below max_value, next cycle increments unless reset arrives.
    increment_when_below_max: assert property (
        @(posedge clk) disable iff (reset) (count != max_value) |=> (reset || (count == $past(count) + 32'd1))
    );

// When not in reset and max_value==0 at 0, the counter holds at 0.
    hold_zero_when_max_zero: assert property (
        @(posedge clk) disable iff (reset) (count == 32'd0 && max_value == 32'd0) |=> (count == 32'd0)
    );

// Clock: clock (posedge). Reset: reset (active-high, async). Mixed logic: reg + combinational compares.

    ///// Register behavior /////
    // While reset is asserted, read_value_reg is held at 0.
    reset_clears_reg: assert property (
        @(posedge clock) reset |-> (read_value_reg == 4'b0000)
    );

// When enabled, next cycle read_value_reg updates from read_value.
    load_on_enable: assert property (
        @(posedge clock) disable iff (reset) read_value_reg_en |=> (read_value_reg == $past(read_value))
    );

// If enable stays LOW across two cycles, the register holds its value.
    hold_when_enable_stays_low: assert property (
        @(posedge clock) disable iff (reset) (!read_value_reg_en ##1 !read_value_reg_en) |-> (read_value_reg == $past(read_value_reg,1))
    );

///// LED definitions /////
    // led_fail is always the logical inverse of led_success.
    led_fail_is_invert_success: assert property (
        @(posedge clock) disable iff (reset) (led_fail == ~led_success)
    );

// led_success reflects write_value == read_value_reg.
    led_success_matches_compare: assert property (
        @(posedge clock) disable iff (reset) (led_success == (write_value == read_value_reg))
    );

// During reset (read_value_reg forced to 0), LEDs reflect compare against zero.
    leds_match_zero_during_reset: assert property (
        @(posedge clock) reset |-> (led_success == (write_value == 4'b0000)) && (led_fail == ~(write_value == 4'b0000))
    );

// Exactly one of the LEDs is HIGH (mutual exclusion and completeness).
    leds_one_hot: assert property (
        @(posedge clock) disable iff (reset) (led_success ^ led_fail)
    );

///// LED response to register update /////
    // After an enabled load, next-cycle led_success matches write_value vs prior-cycle read_value.
    led_success_updates_after_enable: assert property (
        @(posedge clock) disable iff (reset) read_value_reg_en |=> (led_success == (write_value == $past(read_value)))
    );

// If enable stays LOW and write_value is stable across two cycles, LEDs remain stable.
    leds_stable_when_inputs_stable: assert property (
        @(posedge clock) disable iff (reset)
            ((!read_value_reg_en && $stable(write_value)) ##1 (!read_value_reg_en && $stable(write_value)))
            |-> (led_success == $past(led_success,1)) && (led_fail == $past(led_fail,1))
    );

// Output equals logical AND of inputs.
    check_functional_and: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A & B & C)
    );

// X HIGH implies all inputs HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge CLK) disable iff (1'b0) X |-> (A && B && C)
    );

// All inputs HIGH implies X HIGH.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge CLK) disable iff (1'b0) (A && B && C) |-> X
    );

// !A forces X LOW.
    check_low_a_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!A) |-> (!X)
    );

// !B forces X LOW.
    check_low_b_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!B) |-> (!X)
    );

// !C forces X LOW.
    check_low_c_forces_x_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!C) |-> (!X)
    );

// With B&C HIGH, X equals A.
    check_bc_high_gates_a_to_x: assert property (
        @(posedge CLK) disable iff (1'b0) (B && C) |-> (X == A)
    );

// With A&C HIGH, X equals B.
    check_ac_high_gates_b_to_x: assert property (
        @(posedge CLK) disable iff (1'b0) (A && C) |-> (X == B)
    );

// With A&B HIGH, X equals C.
    check_ab_high_gates_c_to_x: assert property (
        @(posedge CLK) disable iff (1'b0) (A && B) |-> (X == C)
    );

// Clock: clk (posedge). Reset: rst (synchronous, active-high). Behavior: 4-bit up-counter with wrap at 15 to 0.

    // Reset drives count to 0 on the next cycle.
    check_reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// While reset is held across cycles, count is 0.
    check_hold_zero_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'h0)
    );

// Synchronous reset sets reg_0x1F to zero on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

// Reset has priority over writes (wenb low) and still drives zero next cycle.
    reset_overrides_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |=> (reg_0x1F == 8'h00)
    );

// When not in reset and wenb is LOW, capture in_data on the next cycle.
    write_captures_in_data: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |=> (reg_0x1F == $past(in_data))
    );

// When not in reset and wenb is HIGH, hold previous value on the next cycle.
    hold_on_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |=> (reg_0x1F == $past(reg_0x1F))
    );

// While reset remains asserted across cycles, the register is zero.
    reset_while_asserted_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_0x1F == 8'h00)
    );

// Even if in_data toggles, with wenb HIGH the register does not update.
    no_update_when_wenb_high_despite_data_change: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1 && $changed(in_data)) |=> (reg_0x1F == $past(reg_0x1F))
    );

// On a write with data different from the current value, the register must change next cycle.
    write_with_different_data_changes_reg: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0 && (in_data != reg_0x1F)) |=> (reg_0x1F != $past(reg_0x1F))
    );

///// Functional correctness of NAND3B (Y = ~(B & C & ~A_N)) /////

    // Combinational truth: Y equals ~(B & C & ~A_N).
    check_truth_function: assert property (
        @(posedge CLK) Y == ~(B & C & ~A_N)
    );

// Y is LOW only when B=1, C=1, and A_N=0.
    check_low_requires_all_inputs: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (B == 1'b1) && (C == 1'b1) && (A_N == 1'b0)
    );

// When B=1, C=1, and A_N=0, Y must be LOW.
    check_all_inputs_force_low: assert property (
        @(posedge CLK) ((B == 1'b1) && (C == 1'b1) && (A_N == 1'b0)) |-> (Y == 1'b0)
    );

// A_N=1 forces Y=1 (since ~A_N=0 makes the AND term 0).
    check_AN_high_forces_high: assert property (
        @(posedge CLK) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B=0 forces Y=1 (NAND with a 0 input is 1).
    check_B_low_forces_high: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );

// C=0 forces Y=1 (NAND with a 0 input is 1).
    check_C_low_forces_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

// With B=1 and C=1, Y equals A_N.
    check_BC_high_output_equals_AN: assert property (
        @(posedge CLK) ((B == 1'b1) && (C == 1'b1)) |-> (Y == A_N)
    );

// With A_N=0, Y equals ~(B & C).
    check_AN_low_output_equals_nand_BC: assert property (
        @(posedge CLK) (A_N == 1'b0) |-> (Y == ~(B & C))
    );

// When both enables are HIGH, q updates to d on the next cycle.
    check_load_on_both_enables: assert property (
        @(posedge clk) (enclk && en) |=> (q == $past(d))
    );

// When enclk is LOW, q holds its previous value.
    check_hold_when_enclk_low: assert property (
        @(posedge clk) (!enclk) |=> (q == $past(q))
    );

// When enclk is HIGH but en is LOW, q holds its previous value.
    check_hold_when_en_low_but_enclk_high: assert property (
        @(posedge clk) (enclk && !en) |=> (q == $past(q))
    );

// Even if en is HIGH, if enclk is LOW, q must hold.
    check_hold_when_en_high_enclk_low: assert property (
        @(posedge clk) (en && !enclk) |=> (q == $past(q))
    );

// If enabled and d equals current q, q must not change next cycle.
    check_no_toggle_when_enabled_and_equal_data: assert property (
        @(posedge clk) (enclk && en && (d == q)) |=> (q == $past(q))
    );

// If enabled and d differs from current q, q must change next cycle.
    check_toggle_when_enabled_and_data_differs: assert property (
        @(posedge clk) (enclk && en && (d != q)) |=> $changed(q)
    );

// parity_error equals the reduction XOR of data (handles X/Z via case equality).
    check_parity_equals_reduction: assert property (
        @(posedge CLK) disable iff (!RESETn) (parity_error === (^data))
    );

// Fully known data implies parity_error is known (no X/Z).
    check_known_data_implies_known_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!$isunknown(data)) |-> (!$isunknown(parity_error))
    );

// All-zero data has even parity -> parity_error is 0.
    check_zero_data_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'h00) |-> (parity_error == 1'b0)
    );

// All-ones (8'hFF) has even parity for 8 bits -> parity_error is 0.
    check_allones_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'hFF) |-> (parity_error == 1'b0)
    );

// Exactly one '1' in data (odd weight) -> parity_error is 1.
    check_onehot_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(data) |-> (parity_error == 1'b1)
    );

// Exactly one '0' in data (seven ones, odd) -> parity_error is 1.
    check_onecold_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(~data) |-> (parity_error == 1'b1)
    );

// When button is high and count<5, next count increments by 1.
  check_increment_on_button_lt5: assert property (
    @(posedge clk) (button && (count < 3'd5)) |-> ##1 (count == $past(count) + 3'd1)
  );

// When count is 5, next count becomes 0.
  check_wrap_to_zero_on_five: assert property (
    @(posedge clk) (count == 3'd5) |-> ##1 (count == 3'd0)
  );

// Otherwise (not increment condition and not 5), count holds.
  check_hold_when_no_increment_conditions: assert property (
    @(posedge clk) ((! (button && (count < 3'd5))) && (count != 3'd5)) |-> ##1 (count == $past(count))
  );

// If count is 4 and button is high, then 5 next and 0 the cycle after.
  check_two_cycle_4_button_to_0: assert property (
    @(posedge clk) (button && (count == 3'd4)) |-> ##1 (count == 3'd5) ##1 (count == 3'd0)
  );

// If count > 5, it must hold its value.
  check_stable_when_gt5: assert property (
    @(posedge clk) (count > 3'd5) |-> ##1 (count == $past(count))
  );

// If count changes to 0 from non-zero, previous count must have been 5.
  check_zero_must_follow_prev_five: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !((count == 3'd0) && ($past(count) != 3'd0)) || ($past(count) == 3'd5) )
  );

// If count increases by 1, previous cycle had button high and count<5.
  check_increment_requires_button_and_lt5: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !(count == $past(count) + 3'd1) || ($past(button) && ($past(count) < 3'd5)) )
  );

// Any decrement must be exactly 5 -> 0.
  check_only_decrement_is_5_to_0: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !(count < $past(count)) || ( ($past(count) == 3'd5) && (count == 3'd0) ) )
  );

// Count cannot be 5 in two consecutive cycles.
  check_no_two_consecutive_five: assert property (
    @(posedge clk) (count == 3'd5) |-> ##1 (count != 3'd5)
  );

// From prev <=5, next count cannot jump by more than +1.
  check_no_upskip_when_prev_le5: assert property (
    @(posedge clk) 1'b1 |-> ##1 ( !($past(count) <= 3'd5) || (count <= ($past(count) + 3'd1)) )
  );

// When SEL is 0, OUT must equal A.
    check_sel0_routes_A: assert property (
        @(posedge CLK) (SEL == 1'b0) |-> (OUT == A)
    );

// When SEL is 1, OUT must equal B.
    check_sel1_routes_B: assert property (
        @(posedge CLK) (SEL == 1'b1) |-> (OUT == B)
    );

// Output has at most one bit set or is all zero.
    check_onehot0_output: assert property (
        @(posedge CLK) $onehot0(mole16bit)
    );

// For positions 0..15, output equals 1 shifted left by mole_position.
    check_decode_when_valid_position: assert property (
        @(posedge CLK) (mole_position <= 5'd15) |-> (mole16bit == (16'h0001 << mole_position))
    );

// For positions 16..31, output is zero.
    check_zero_on_invalid_position: assert property (
        @(posedge CLK) (mole_position > 5'd15) |-> (mole16bit == 16'h0000)
    );

// Zero output implies position is outside 0..15.
    check_zero_means_invalid_position: assert property (
        @(posedge CLK) (mole16bit == 16'h0000) |-> (mole_position > 5'd15)
    );

// Non-zero output implies position is within 0..15.
    check_nonzero_means_valid_position: assert property (
        @(posedge CLK) (mole16bit != 16'h0000) |-> (mole_position <= 5'd15)
    );

// Non-zero output must match the 1<<mole_position encoding.
    check_nonzero_matches_shift: assert property (
        @(posedge CLK) (mole16bit != 16'h0000) |-> (mole16bit == (16'h0001 << mole_position))
    );

// Boundary: position 0 decodes to LSB set.
    check_pos0_maps_to_lsb: assert property (
        @(posedge CLK) (mole_position == 5'd0) |-> (mole16bit == 16'h0001)
    );

// Boundary: position 15 decodes to MSB set.
    check_pos15_maps_to_msb: assert property (
        @(posedge CLK) (mole_position == 5'd15) |-> (mole16bit == 16'h8000)
    );

// Clock: clk (posedge)
    // Reset: reset (active-high, synchronous)
    // Logic: sequential counter with wrap at 8'hFF

    // Reset drives count to 0 on the next cycle.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 8'h00)
    );

// If reset is held high across cycles, count is 0 in the held cycle.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 8'h00)
    );

// When not reset and not at max, next count increments by 1.
    count_increments_when_not_max: assert property (
        @(posedge clk) disable iff (reset) (count != 8'hFF) |=> (count == $past(count) + 8'h01)
    );

// When not reset and at max, next count wraps to 0.
    count_wraps_after_max: assert property (
        @(posedge clk) disable iff (reset) (count == 8'hFF) |=> (count == 8'h00)
    );

// Next-state is fully determined by current count when not in reset.
    next_state_deterministic: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == (($past(count) == 8'hFF) ? 8'h00 : ($past(count) + 8'h01)))
    );

// Pressure is passed through unchanged.
    check_pressure_passthrough: assert property (
        @(posedge CLK) disable iff (!RESETn)
            press_out == pressure
    );

// Humidity is passed through unchanged.
    check_humidity_passthrough: assert property (
        @(posedge CLK) disable iff (!RESETn)
            hum_out == humidity
    );

// After a sampled reset, Q must be 0 on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (Q == 4'b0000)
    );

// With load high (reset low), Q updates to data_in on the next clock.
    check_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(data_in))
    );

// After a sampled reset, if no load in the following cycle, Q remains 0 for one more cycle.
    check_zero_persists_one_more_cycle_without_load_after_reset: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && !load |=> (Q == 4'b0000)
    );

// Back-to-back loads pipeline data: second cycle reflects data_in of the first next cycle.
    check_back_to_back_loads_pipeline: assert property (
        @(posedge clk) disable iff (reset) load ##1 load |=> (Q == $past(data_in))
    );

// If previous cycle had reset and current load is high, Q is 0 in the current cycle (reset dominates).
    check_reset_dominates_load_current: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |-> (Q == 4'b0000)
    );

// If previous cycle had reset and current load is high, Q captures current data on the next clock.
    check_reset_then_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |=> (Q == $past(data_in))
    );

// Combinational 3:1 mux: when exactly one sel is HIGH, dout equals that input.

    // When sel0=1 and sel1=sel2=0, dout equals in0.
    select0_maps_to_in0: assert property (
        @(posedge CLK) (sel0 && !sel1 && !sel2) |-> (dout == in0)
    );

// When sel1=1 and sel0=sel2=0, dout equals in1.
    select1_maps_to_in1: assert property (
        @(posedge CLK) (sel1 && !sel0 && !sel2) |-> (dout == in1)
    );

// When sel2=1 and sel0=sel1=0, dout equals in2.
    select2_maps_to_in2: assert property (
        @(posedge CLK) (sel2 && !sel0 && !sel1) |-> (dout == in2)
    );

// Clock: clk (posedge). Reset: rst (active-high, asynchronous). Sequential up-counter.

    // q must be 0 whenever rst is high at a clock edge.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (q == 32'd0)
    );

// q is 0 on a rising edge of rst observed at a clock edge.
    check_zero_on_reset_rise: assert property (
        @(posedge clk) $rose(rst) |-> (q == 32'd0)
    );

// While rst stays high across cycles, q stays 0 and stable.
    check_zero_stable_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (q == 32'd0 && $past(q) == 32'd0)
    );

// Immediately following a cycle with rst high, q at the next edge is 0 or 1.
    check_next_cycle_after_reset_range: assert property (
        @(posedge clk) rst |=> (q inside {32'd0, 32'd1})
    );

// DUT is purely combinational (no reset); assertions sampled on external clk.

    // Grant0 equals req0 & atom0.
    check_grant0_logic: assert property (
        @(posedge clk) arb_src0_grant_a == (src0_arb_req_q && src0_arb_atom_q)
    );

// Grant1 equals req1 & atom1 & !atom0.
    check_grant1_logic: assert property (
        @(posedge clk) arb_src1_grant_a == (src1_arb_req_q && src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grant2 equals req2 & atom2 & !atom1 & !atom0.
    check_grant2_logic: assert property (
        @(posedge clk) arb_src2_grant_a == (src2_arb_req_q && src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grant3 equals req3 & atom3 & !atom2 & !atom1 & !atom0.
    check_grant3_logic: assert property (
        @(posedge clk) arb_src3_grant_a == (src3_arb_req_q && src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grant4 equals req4 & atom4 & !atom3..0.
    check_grant4_logic: assert property (
        @(posedge clk) arb_src4_grant_a == (src4_arb_req_q && src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grant5 equals req5 & atom5 & !atom4..0.
    check_grant5_logic: assert property (
        @(posedge clk) arb_src5_grant_a == (src5_arb_req_q && src5_arb_atom_q && !src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grant6 equals req6 & atom6 & !atom5..0.
    check_grant6_logic: assert property (
        @(posedge clk) arb_src6_grant_a == (src6_arb_req_q && src6_arb_atom_q && !src5_arb_atom_q && !src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grant7 equals req7 & atom7 & !atom6..0.
    check_grant7_logic: assert property (
        @(posedge clk) arb_src7_grant_a == (src7_arb_req_q && src7_arb_atom_q && !src6_arb_atom_q && !src5_arb_atom_q && !src4_arb_atom_q && !src3_arb_atom_q && !src2_arb_atom_q && !src1_arb_atom_q && !src0_arb_atom_q)
    );

// Grants are mutually exclusive (0 or 1 set).
    check_grant_mutex: assert property (
        @(posedge clk) $onehot0({arb_src7_grant_a,arb_src6_grant_a,arb_src5_grant_a,arb_src4_grant_a,arb_src3_grant_a,arb_src2_grant_a,arb_src1_grant_a,arb_src0_grant_a})
    );

// If no atoms are set, no grants are set.
    check_no_atom_no_grant: assert property (
        @(posedge clk)
            !(src0_arb_atom_q || src1_arb_atom_q || src2_arb_atom_q || src3_arb_atom_q ||
              src4_arb_atom_q || src5_arb_atom_q || src6_arb_atom_q || src7_arb_atom_q)
            |-> !(arb_src0_grant_a || arb_src1_grant_a || arb_src2_grant_a || arb_src3_grant_a ||
                  arb_src4_grant_a || arb_src5_grant_a || arb_src6_grant_a || arb_src7_grant_a)
    );

// DUT is purely combinational with no reset; use disable iff (1'b0).

    // Y equals A|B|D (absorbing (A&B&C) into A|B).
    check_y_function_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y === (A | B | D)
    );

// Y must be 1 whenever D is 1.
    check_y_high_if_d_high: assert property (
        @(posedge CLK) disable iff (1'b0) D |-> (Y === 1'b1)
    );

// Y must be 1 whenever A is 1.
    check_y_high_if_a_high: assert property (
        @(posedge CLK) disable iff (1'b0) A |-> (Y === 1'b1)
    );

// Y must be 1 whenever B is 1.
    check_y_high_if_b_high: assert property (
        @(posedge CLK) disable iff (1'b0) B |-> (Y === 1'b1)
    );

// With D==0, Y equals A|B.
    check_y_eq_a_or_b_when_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (D === 1'b0) |-> (Y === (A | B))
    );

// With A==0 and B==0, Y equals D.
    check_y_eq_d_when_a_b_low: assert property (
        @(posedge CLK) disable iff (1'b0) (A === 1'b0) && (B === 1'b0) |-> (Y === D)
    );

// With B==0 and D==0, Y equals A.
    check_y_eq_a_when_b_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (B === 1'b0) && (D === 1'b0) |-> (Y === A)
    );

// With A==0 and D==0, Y equals B.
    check_y_eq_b_when_a_d_low: assert property (
        @(posedge CLK) disable iff (1'b0) (A === 1'b0) && (D === 1'b0) |-> (Y === B)
    );

// Y rising requires at least one of A,B,D to be 1.
    check_y_rise_requires_input_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(Y) |-> (A || B || D)
    );

// Y falling requires A,B,D all 0.
    check_y_fall_requires_inputs_low: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(Y) |-> (!A && !B && !D)
    );

// SUM must equal A xor B xor CI.
    check_sum_logic: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

// COUT must equal majority of A,B,CI (carry-out).
    check_cout_logic: assert property (
        @(posedge CLK) COUT == ((A & B) | (B & CI) | (CI & A))
    );

// {COUT,SUM} equals the 2-bit addition of inputs.
    check_add_result_vector: assert property (
        @(posedge CLK) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// 000 inputs produce 00 outputs.
    truth_000: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0 && CI == 1'b0) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

// 111 inputs produce 11 outputs.
    truth_111: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1 && CI == 1'b1) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

// Exactly one input high yields SUM=1 and COUT=0.
    onehot_sum_only: assert property (
        @(posedge CLK) $onehot({A,B,CI}) |-> (SUM == 1'b1 && COUT == 1'b0)
    );

// Exactly two inputs high yields SUM=0 and COUT=1.
    two_ones_cout_only: assert property (
        @(posedge CLK) ((A & B & ~CI) | (A & CI & ~B) | (B & CI & ~A)) |-> (SUM == 1'b0 && COUT == 1'b1)
    );

// SUM=1 and COUT=1 implies all three inputs are 1.
    sum_and_cout_imply_three_ones: assert property (
        @(posedge CLK) (SUM == 1'b1 && COUT == 1'b1) |-> (A & B & CI)
    );

// a_greater reflects (A > B).
    check_a_greater_definition: assert property (
        @(posedge clk) a_greater == (A > B)
    );

// b_greater reflects (B > A).
    check_b_greater_definition: assert property (
        @(posedge clk) b_greater == (B > A)
    );

// equal reflects (A == B).
    check_equal_definition: assert property (
        @(posedge clk) equal == (A == B)
    );

// Exactly one of a_greater, b_greater, equal is HIGH.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({a_greater, b_greater, equal})
    );

// equal excludes both greater outputs.
    check_equal_excludes_greater: assert property (
        @(posedge clk) equal |-> (!a_greater && !b_greater)
    );

// a_greater excludes b_greater and equal.
    check_a_greater_excludes_others: assert property (
        @(posedge clk) a_greater |-> (!b_greater && !equal)
    );

// b_greater excludes a_greater and equal.
    check_b_greater_excludes_others: assert property (
        @(posedge clk) b_greater |-> (!a_greater && !equal)
    );

// (a_greater || b_greater) matches (A != B).
    check_neq_matches_any_greater: assert property (
        @(posedge clk) (a_greater || b_greater) == (A != B)
    );

// equal matches NOT (a_greater || b_greater).
    check_eq_matches_not_any_greater: assert property (
        @(posedge clk) equal == !(a_greater || b_greater)
    );

// Output equals the specified sum-of-products function.
    check_functional_equivalence: assert property (
        @(posedge clk) output_signal == ((input_1 & input_2) | (input_2 & input_3) | (input_3 & input_4))
    );

// If input_1 and input_2 are HIGH, output must be HIGH.
    check_pair12_implies_out: assert property (
        @(posedge clk) (input_1 & input_2) |-> output_signal
    );

// If input_2 and input_3 are HIGH, output must be HIGH.
    check_pair23_implies_out: assert property (
        @(posedge clk) (input_2 & input_3) |-> output_signal
    );

// If input_3 and input_4 are HIGH, output must be HIGH.
    check_pair34_implies_out: assert property (
        @(posedge clk) (input_3 & input_4) |-> output_signal
    );

// If output is HIGH, at least one adjacent pair must be HIGH.
    check_out_implies_has_pair: assert property (
        @(posedge clk) output_signal |-> ((input_1 & input_2) | (input_2 & input_3) | (input_3 & input_4))
    );

// If no adjacent pair is HIGH, output must be LOW.
    check_no_pair_implies_out0: assert property (
        @(posedge clk) ~((input_1 & input_2) | (input_2 & input_3) | (input_3 & input_4)) |-> !output_signal
    );

// With input_2 LOW, output reduces to input_3 & input_4.
    check_i2_zero_reduction: assert property (
        @(posedge clk) (input_2 == 1'b0) |-> (output_signal == (input_3 & input_4))
    );

// With input_3 LOW, output reduces to input_1 & input_2.
    check_i3_zero_reduction: assert property (
        @(posedge clk) (input_3 == 1'b0) |-> (output_signal == (input_1 & input_2))
    );

// With input_2 HIGH, output reduces to input_1 | input_3.
    check_i2_one_reduction: assert property (
        @(posedge clk) (input_2 == 1'b1) |-> (output_signal == (input_1 | input_3))
    );

// With input_3 HIGH, output reduces to input_2 | input_4.
    check_i3_one_reduction: assert property (
        @(posedge clk) (input_3 == 1'b1) |-> (output_signal == (input_2 | input_4))
    );

// With input_1 HIGH, output reduces to input_2 | (input_3 & input_4).
    check_i1_one_reduction: assert property (
        @(posedge clk) (input_1 == 1'b1) |-> (output_signal == (input_2 | (input_3 & input_4)))
    );

// With input_4 HIGH, output reduces to input_3 | (input_1 & input_2).
    check_i4_one_reduction: assert property (
        @(posedge clk) (input_4 == 1'b1) |-> (output_signal == (input_3 | (input_1 & input_2)))
    );

// With input_1 LOW, output reduces to input_3 & (input_2 | input_4).
    check_i1_zero_reduction: assert property (
        @(posedge clk) (input_1 == 1'b0) |-> (output_signal == (input_3 & (input_2 | input_4)))
    );

// With input_4 LOW, output reduces to input_2 & (input_1 | input_3).
    check_i4_zero_reduction: assert property (
        @(posedge clk) (input_4 == 1'b0) |-> (output_signal == (input_2 & (input_1 | input_3)))
    );

// Y equals the NOR of A and B.
    check_y_equals_nor: assert property (
        @(posedge clk) Y === ~(A | B)
    );

// If either input is 1, Y must be 0.
    check_any_input_one_forces_y_zero: assert property (
        @(posedge clk) ((A === 1'b1) || (B === 1'b1)) |-> (Y === 1'b0)
    );

// If both inputs are 0, Y must be 1.
    check_both_inputs_zero_gives_y_one: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Y === 1'b1)
    );

// If Y is 1, both inputs must be 0.
    check_y_one_implies_inputs_zero: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A === 1'b0) && (B === 1'b0))
    );

// If Y is 0, at least one input must be 1.
    check_y_zero_implies_some_input_one: assert property (
        @(posedge clk) (Y === 1'b0) |-> ((A === 1'b1) || (B === 1'b1))
    );

// Q_N is always the complement of Q.
    check_qn_is_complement: assert property (
        @(posedge CLK) (Q_N == ~Q)
    );

// S and R are never both asserted.
    check_sr_mutex: assert property (
        @(posedge CLK) !(S && R)
    );

// Exactly one of S or R asserted iff VPB & VNB is HIGH.
    check_sr_xor_matches_power: assert property (
        @(posedge CLK) ((S ^ R) == (VPB & VNB))
    );

// Reset high forces count to zero at the clock edge.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// With load asserted (no reset), next count captures data_in.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// With load deasserted and up_down=1 (no reset), next count increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// With load deasserted and up_down=0 (no reset), next count decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// RESULT equals add or subtract modulo 16 based on SUB.
    check_result_function: assert property (
        @(posedge CLK) RESULT == (SUB ? ((A - B) & 5'h0F) : ((A + B) & 5'h0F))
    );

// When SUB=0, RESULT is A+B modulo 16.
    check_add_when_sub0: assert property (
        @(posedge CLK) (SUB == 1'b0) |-> (RESULT == ((A + B) & 5'h0F))
    );

// When SUB=1, RESULT is A-B modulo 16.
    check_sub_when_sub1: assert property (
        @(posedge CLK) (SUB == 1'b1) |-> (RESULT == ((A - B) & 5'h0F))
    );

// With SUB=0 and B=0, RESULT equals A.
    check_add_identity_B_zero: assert property (
        @(posedge CLK) (SUB == 1'b0 && B == 4'h0) |-> (RESULT == A)
    );

// With SUB=0 and A=0, RESULT equals B.
    check_add_identity_A_zero: assert property (
        @(posedge CLK) (SUB == 1'b0 && A == 4'h0) |-> (RESULT == B)
    );

// With SUB=1 and B=0, RESULT equals A.
    check_sub_identity_B_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'h0) |-> (RESULT == A)
    );

// With SUB=1 and A=B, RESULT is zero.
    check_sub_self_subtract_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && A == B) |-> (RESULT == 4'h0)
    );

// With SUB=1 and A=0, RESULT equals (16 - B) modulo 16.
    check_sub_A_zero_twos_comp: assert property (
        @(posedge CLK) (SUB == 1'b1 && A == 4'h0) |-> (RESULT == ((5'd16 - B) & 5'h0F))
    );

// With SUB=0 and B=1, RESULT is A+1 modulo 16.
    check_add_increment_by_one: assert property (
        @(posedge CLK) (SUB == 1'b0 && B == 4'h1) |-> (RESULT == ((A + 4'h1) & 5'h0F))
    );

// With SUB=1 and B=1, RESULT is A-1 modulo 16.
    check_sub_decrement_by_one: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'h1) |-> (RESULT == ((A - 4'h1) & 5'h0F))
    );

// Analysis:
    // - Clock: CLK (posedge)
    // - Async set: SET_B active-low; drives Q=1 when low
    // - Logic: sequential (DFF with asynchronous set)
    // - Behavior: if SET_B==0 -> Q=1 asynchronously; else on posedge CLK -> Q captures D

    ///// Asynchronous set behavior /////
    // When SET_B is LOW, Q must be driven HIGH.
    check_async_set_dominates: assert property (
        @(posedge CLK) (SET_B == 1'b0) |-> (Q == 1'b1)
    );

// On the first clock after SET_B rises (release), Q captures D from the release edge.
    check_capture_after_set_release: assert property (
        @(posedge CLK) disable iff (!SET_B) $rose(SET_B) |-> ##1 (Q == $past(D,1))
    );

///// Sanity constraints derived from RTL /////
    // Q cannot be 0 while SET_B is LOW.
    check_Q_zero_implies_set_deasserted: assert property (
        @(posedge CLK) (Q == 1'b0) |-> (SET_B == 1'b1)
    );

///// Reset behavior /////
    // While reset is asserted (active-high), ENCLK must be 0.
    reset_clears_output: assert property (
        @(posedge CLK) reset |-> (ENCLK == 1'b0)
    );

///// Test enable gating /////
    // TE low forces ENCLK low.
    te_low_forces_zero: assert property (
        @(posedge CLK) disable iff (reset) (TE == 1'b0) |-> (ENCLK == 1'b0)
    );

// ENCLK high implies TE is high (gated path).
    enclk_high_requires_te: assert property (
        @(posedge CLK) disable iff (reset) (ENCLK == 1'b1) |-> (TE == 1'b1)
    );

// Any rise of ENCLK requires TE high in that cycle.
    enclk_rise_requires_te: assert property (
        @(posedge CLK) disable iff (reset) $rose(ENCLK) |-> (TE == 1'b1)
    );

///// Combinational relationships /////
    // m_axis_tvalid is exactly s_axis_tready AND s_axis_tvalid (same cycle).
    check_tvalid_definition: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tvalid == (s_axis_tready & s_axis_tvalid)
    );

// When s_axis_tvalid is LOW, m_axis_tvalid must be LOW.
    check_tvalid_low_when_s_valid_low: assert property (
        @(posedge aclk) disable iff (!aresetn) (!s_axis_tvalid) |-> (!m_axis_tvalid)
    );

// When s_axis_tready is LOW, m_axis_tvalid must be LOW.
    check_tvalid_low_when_not_ready: assert property (
        @(posedge aclk) disable iff (!aresetn) (!s_axis_tready) |-> (!m_axis_tvalid)
    );

// When s_axis_tready is HIGH, m_axis_tvalid mirrors s_axis_tvalid.
    check_valid_eq_when_ready: assert property (
        @(posedge aclk) disable iff (!aresetn) s_axis_tready |-> (m_axis_tvalid == s_axis_tvalid)
    );

// When s_axis_tvalid is HIGH, m_axis_tvalid mirrors s_axis_tready.
    check_valid_eq_when_s_valid: assert property (
        @(posedge aclk) disable iff (!aresetn) s_axis_tvalid |-> (m_axis_tvalid == s_axis_tready)
    );

// m_axis_tdata always passes through s_axis_tdata[15:0] (no latency).
    check_data_passthrough: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tdata == s_axis_tdata[15:0]
    );

// When m_axis_tvalid is HIGH, data must equal s_axis_tdata[15:0] in the same cycle.
    check_data_when_valid: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tvalid |-> (m_axis_tdata == s_axis_tdata[15:0])
    );

// If m_axis_tvalid is HIGH, both s_axis_tvalid and s_axis_tready must be HIGH.
    check_m_valid_implies_s_valid_and_ready: assert property (
        @(posedge aclk) disable iff (!aresetn) m_axis_tvalid |-> (s_axis_tvalid && s_axis_tready)
    );

///// Decoder output invariants /////
    // Outputs are always one-hot (exactly one HIGH).
    check_outputs_onehot: assert property (
        @(posedge A) $onehot(Y)
    );

// If Y0 is HIGH, all other outputs must be LOW.
    check_y0_mutex: assert property (
        @(posedge A) Y0 |-> !(Y1 || Y2 || Y3 || Y4 || Y5 || Y6 || Y7)
    );

// If Y1 is HIGH, all other outputs must be LOW.
    check_y1_mutex: assert property (
        @(posedge A) Y1 |-> !(Y0 || Y2 || Y3 || Y4 || Y5 || Y6 || Y7)
    );

// If Y2 is HIGH, all other outputs must be LOW.
    check_y2_mutex: assert property (
        @(posedge A) Y2 |-> !(Y0 || Y1 || Y3 || Y4 || Y5 || Y6 || Y7)
    );

// If Y3 is HIGH, all other outputs must be LOW.
    check_y3_mutex: assert property (
        @(posedge A) Y3 |-> !(Y0 || Y1 || Y2 || Y4 || Y5 || Y6 || Y7)
    );

// If Y4 is HIGH, all other outputs must be LOW.
    check_y4_mutex: assert property (
        @(posedge A) Y4 |-> !(Y0 || Y1 || Y2 || Y3 || Y5 || Y6 || Y7)
    );

// If Y5 is HIGH, all other outputs must be LOW.
    check_y5_mutex: assert property (
        @(posedge A) Y5 |-> !(Y0 || Y1 || Y2 || Y3 || Y4 || Y6 || Y7)
    );

// If Y6 is HIGH, all other outputs must be LOW.
    check_y6_mutex: assert property (
        @(posedge A) Y6 |-> !(Y0 || Y1 || Y2 || Y3 || Y4 || Y5 || Y7)
    );

// If Y7 is HIGH, all other outputs must be LOW.
    check_y7_mutex: assert property (
        @(posedge A) Y7 |-> !(Y0 || Y1 || Y2 || Y3 || Y4 || Y5 || Y6)
    );

///// Reset behavior /////
    // On any cycle with Reset HIGH, Q is 0 on the next cycle.
    reset_forces_zero_next: assert property (
        @(posedge Clk) Reset |=> (Q == 4'd0)
    );

// If Reset is held HIGH for consecutive cycles, Q must read 0.
    reset_hold_zero: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (Q == 4'd0)
    );

///// Enable/hold/increment rules /////
    // When disabled (and not in reset), Q holds its value into the next cycle.
    hold_when_disabled: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable) |=> (Q == $past(Q))
    );

// When enabled and Q != 15, Q increments by 1 next cycle.
    increment_when_enabled_no_overflow: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && (Q != 4'hF)) |=> (Q == $past(Q) + 4'd1)
    );

// When enabled and Q == 15, Q wraps to 0 next cycle.
    rollover_when_enabled_at_max: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && (Q == 4'hF)) |=> (Q == 4'd0)
    );

// With 16 consecutive enabled cycles (no reset), Q returns to its value 16 cycles earlier.
    wrap_after_16_enables: assert property (
        @(posedge Clk) disable iff (Reset) (Enable[*16]) |=> (Q == $past(Q, 16))
    );

// With two consecutive disabled cycles (no reset), Q matches its value two cycles earlier.
    hold_across_two_disabled_cycles: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable[*2]) |=> (Q == $past(Q, 2))
    );

// When load is HIGH, next Q equals current input_data.
    check_load_captures_input_data: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

// When load is LOW and up_down is HIGH, next Q increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == (($past(Q) + 1) & 4'hF))
    );

// When load is LOW and up_down is LOW, next Q decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == (($past(Q) - 1) & 4'hF))
    );

// Increment from 0xF wraps to 0x0 when not loading.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Decrement from 0x0 wraps to 0xF when not loading.
    check_wrap_decrement_from_min: assert property (
        @(posedge clk) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Two consecutive UP steps (no load) increment Q by 2 (mod 16).
    check_two_cycle_increment: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && up_down) |=> (Q == (($past(Q,2) + 2) & 4'hF))
    );

// Two consecutive DOWN steps (no load) decrement Q by 2 (mod 16).
    check_two_cycle_decrement: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && !up_down) |=> (Q == (($past(Q,2) - 2) & 4'hF))
    );

// UP followed by DOWN with no loads returns Q to original value after 2 cycles.
    check_up_then_down_cancels: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && !up_down) |=> (Q == $past(Q,2))
    );

// DOWN followed by UP with no loads returns Q to original value after 2 cycles.
    check_down_then_up_cancels: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && up_down) |=> (Q == $past(Q,2))
    );

// Two consecutive loads use the second cycle's input_data value.
    check_two_consecutive_loads_use_second_value: assert property (
        @(posedge clk) load ##1 load |=> (Q == $past(input_data,1))
    );

// Synchronous reset drives count to 0.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

// Outputs exactly match the comparator functions of inputs.
    check_functional_mapping: assert property (
        @(posedge clk) (out_eq == (in1 == in2)) && (out_gt == (in1 > in2)) && (out_lt == (in1 < in2))
    );

// Exactly one output is HIGH at any time (one-hot).
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({out_eq, out_gt, out_lt})
    );

// Outputs are never all zero.
    check_outputs_not_all_zero: assert property (
        @(posedge clk) (out_eq || out_gt || out_lt)
    );

// When inputs are equal, only out_eq is HIGH.
    check_eq_when_equal: assert property (
        @(posedge clk) (in1 == in2) |-> (out_eq && !out_gt && !out_lt)
    );

// When in1 > in2, only out_gt is HIGH.
    check_gt_when_greater: assert property (
        @(posedge clk) (in1 > in2) |-> (!out_eq && out_gt && !out_lt)
    );

// When in1 < in2, only out_lt is HIGH.
    check_lt_when_less: assert property (
        @(posedge clk) (in1 < in2) |-> (!out_eq && !out_gt && out_lt)
    );

// If out_eq is HIGH, inputs must be equal.
    check_eq_implies_equal: assert property (
        @(posedge clk) out_eq |-> (in1 == in2)
    );

// If out_gt is HIGH, in1 must be greater than in2.
    check_gt_implies_greater: assert property (
        @(posedge clk) out_gt |-> (in1 > in2)
    );

// If out_lt is HIGH, in1 must be less than in2.
    check_lt_implies_less: assert property (
        @(posedge clk) out_lt |-> (in1 < in2)
    );

// No two outputs can be HIGH simultaneously (mutual exclusion).
    check_mutex_pairs: assert property (
        @(posedge clk) !(out_eq && out_gt) && !(out_eq && out_lt) && !(out_gt && out_lt)
    );

// Bit 0 sum equals a0 ^ b0 ^ cin.
    check_sum0_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 2 sum equals a2 ^ b2 ^ carry1.
    check_sum2_xor_with_carry1: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            ((a[1] & b[1]) | (((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1])))
        )
    );

// Bit 3 sum equals a3 ^ b3 ^ carry2.
    check_sum3_xor_with_carry2: assert property (
        @(posedge clk) sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    ((a[1] & b[1]) | (((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) & (a[1] ^ b[1])))
                    & (a[2] ^ b[2])
                )
            )
        )
    );

// When a=0 and b=0, sum mirrors cin on bit0 and cout is 0.
    check_zero_inputs_behavior: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000)) |-> (sum == {3'b000, cin}) && (cout == 1'b0)
    );

// When a=15, b=15, cin=1, result is 31 (5'b11111).
    check_all_ones_plus_one: assert property (
        @(posedge clk) ((a == 4'hF) && (b == 4'hF) && (cin == 1'b1)) |-> ({cout, sum} == 5'b11111)
    );

// With a=0 and cin=0, output equals b and cout is 0.
    check_add_b_when_a_zero_cin0: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> (sum == b) && (cout == 1'b0)
    );

// With b=0 and cin=0, output equals a and cout is 0.
    check_add_a_when_b_zero_cin0: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> (sum == a) && (cout == 1'b0)
    );

// No clock/reset in RTL; purely combinational; assertions are clocked on clk.

    ///// Functional equivalence to RTL equations /////
    // bg[0] equals block-generate for bits [3:0].
    check_bg0_definition: assert property (
        @(posedge clk) bg[0] == ( g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) )
    );

// bg[1] equals block-generate for bits [7:4].
    check_bg1_definition: assert property (
        @(posedge clk) bg[1] == ( g[7] | (p[7] & g[6]) | (p[7] & p[6] & g[5]) | (p[7] & p[6] & p[5] & g[4]) )
    );

// bg[2] equals block-generate for bits [11:8].
    check_bg2_definition: assert property (
        @(posedge clk) bg[2] == ( g[11] | (p[11] & g[10]) | (p[11] & p[10] & g[9]) | (p[11] & p[10] & p[9] & g[8]) )
    );

// bg[3] equals block-generate for bits [15:12].
    check_bg3_definition: assert property (
        @(posedge clk) bg[3] == ( g[15] | (p[15] & g[14]) | (p[15] & p[14] & g[13]) | (p[15] & p[14] & p[13] & g[12]) )
    );

// bp[0] equals AND of p[3:0].
    check_bp0_definition: assert property (
        @(posedge clk) bp[0] == (p[3] & p[2] & p[1] & p[0])
    );

// bp[1] equals AND of p[7:4].
    check_bp1_definition: assert property (
        @(posedge clk) bp[1] == (p[7] & p[6] & p[5] & p[4])
    );

// bp[2] equals AND of p[11:8].
    check_bp2_definition: assert property (
        @(posedge clk) bp[2] == (p[11] & p[10] & p[9] & p[8])
    );

// bp[3] equals AND of p[15:12].
    check_bp3_definition: assert property (
        @(posedge clk) bp[3] == (p[15] & p[14] & p[13] & p[12])
    );

// Clock: clk; Reset: rst (active-high async). Sequential pipeline register with async reset. Pass-through of id_* to ex_* on each clk when rst==0.

    ///// Reset behavior /////
    // While reset is asserted, outputs hold their reset values.
    reset_values_all: assert property (
        @(posedge clk) rst |-> (ex_a == 32'b0) && (ex_b == 32'b0) && (ex_d2 == 32'b0) &&
                               (ex_td == 5'b0) && (ex_Aluc == 5'b0) &&
                               (ex_WREG == 1'b0) && (ex_WMEM == 1'b0) && (ex_LW == 1'b0) &&
                               (ex_instr == 32'b100000)
    );

///// Reset behavior /////
  // While reset is HIGH at a clock edge, count is 0.
  check_reset_forces_zero: assert property (
    @(posedge clk) reset |-> (count == 3'd0)
  );

///// Hold/update rules /////
  // When disabled, count holds its previous value.
  check_hold_when_disabled: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count))
  );

// When enabled and control=1, count increments by 1 (mod 8).
  check_increment_when_enabled: assert property (
    @(posedge clk) disable iff (reset) (enable && control) |=> (count == ($past(count) + 3'd1))
  );

// When enabled and control=0, count decrements by 1 (mod 8).
  check_decrement_when_enabled: assert property (
    @(posedge clk) disable iff (reset) (enable && !control) |=> (count == ($past(count) - 3'd1))
  );

// When enabled, count must change value next cycle.
  check_change_on_enable: assert property (
    @(posedge clk) disable iff (reset) (enable) |=> (count != $past(count))
  );

///// Sanity /////
  // Count is always within 3-bit range.
  check_count_range: assert property (
    @(posedge clk) (count <= 3'd7)
  );

// Reset drives count to zero on the same clock edge.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// While reset is held across consecutive cycles, count remains 0.
    count_zero_stable_when_reset_held: assert property (
        @(posedge clk) $past(rst) && rst |-> (count == 4'd0)
    );

// During reset (active-low), output G is 0.
    reset_output_zero: assert property (
        @(posedge clk) (!rst) |-> (G == 4'b0000)
    );

// G is a direct reflection of G_reg.
    check_output_driven_by_greg: assert property (
        @(posedge clk) disable iff (!rst) (G == G_reg)
    );

// B is sampled into B_reg each cycle (1-cycle latency).
    check_breg_captures_b: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (B_reg == $past(B))
    );

// G_reg computes Gray code from previous B_reg.
    check_greg_from_prev_breg: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (
            G_reg == { $past(B_reg[3]),
                       $past(B_reg[3]) ^ $past(B_reg[2]),
                       $past(B_reg[2]) ^ $past(B_reg[1]),
                       $past(B_reg[1]) ^ $past(B_reg[0]) }
        )
    );

// G equals Gray code of previous B (end-to-end 1-cycle latency).
    check_g_from_prev_b: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (
            G == { $past(B[3]),
                   $past(B[3]) ^ $past(B[2]),
                   $past(B[2]) ^ $past(B[1]),
                   $past(B[1]) ^ $past(B[0]) }
        )
    );

// On reset deassertion edge, outputs reflect zeros from previously reset state.
    check_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (B_reg == 4'b0000) && (G_reg == 4'b0000) && (G == 4'b0000)
    );

// If B is unchanged for two consecutive cycles, G is unchanged next cycle.
    check_g_stable_when_b_stable: assert property (
        @(posedge clk) disable iff (!rst) $past(rst,2) && ($past(B,1) == $past(B,2)) |-> (G == $past(G))
    );

// MSB of G equals previous cycle's MSB of B.
    check_g_msb_from_prev_b_msb: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (G[3] == $past(B[3]))
    );

// MSB of G_reg equals previous cycle's MSB of B_reg.
    check_greg_msb_from_prev_breg_msb: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (G_reg[3] == $past(B_reg[3]))
    );

// Clock: clk; Reset: rst (active-high async)

    // Reset drives Q to zero whenever rst is HIGH.
    registeradd_check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (Q == '0)
    );

// Clock: clk (posedge). No explicit reset. Mixed logic: sequential counter, combinational diffs with clear gating.

   // count_clk must be 0 when clear is 2'b10 or 2'b11.
   check_count_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (count_clk == 32'd0)
   );

// pos_diff_x must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffx_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == 16'd0)
   );

// pos_diff_y must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffy_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == 16'd0)
   );

// pos_diff_x equals pos11 - pos21 when clear is not 2'b10 or 2'b11.
   check_posdiffx_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == (pos11 - pos21))
   );

// pos_diff_y equals pos12 - pos22 when clear is not 2'b10 or 2'b11.
   check_posdiffy_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == (pos12 - pos22))
   );

// With two consecutive active cycles, count_clk increments by 1 each cycle.
   check_count_inc_on_two_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk) + 32'd1)
   );

// With three consecutive active cycles, count_clk increases by 2 over two cycles.
   check_count_inc_by_two_on_three_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk,2) + 32'd2)
   );

///// Reset behavior /////
  // While reset is asserted, outputs are held LOW.
  reset_outputs_low: assert property (
    @(posedge clk) rst |-> (nfl_num == 1'b0) && (inc_dec_b == 1'b0)
  );

// inc_dec_b is 1 if at least one previous input was 0.
  check_inc_dec_b_one_on_prev_not_both_high: assert property (
    @(posedge clk) disable iff (rst) ($past(!rst) && (inc_dec_b == 1'b1)) |-> !($past(cfg_err_cpl_timeout_n) && $past(decr_nfl))
  );

// When previous COUNT was not 15, next BTN edge increments by 1.
    check_inc_when_prev_not_15: assert property (
        @(posedge BTN) 1'b1 |=> ( ($past(COUNT) != 4'd15) |-> (COUNT == $past(COUNT) + 4'd1) )
    );

// When previous COUNT was 15, next BTN edge wraps to 0.
    check_wrap_when_prev_15: assert property (
        @(posedge BTN) 1'b1 |=> ( ($past(COUNT) == 4'd15) |-> (COUNT == 4'd0) )
    );

// COUNT must change on every BTN rising edge.
    check_count_changes_each_pulse: assert property (
        @(posedge BTN) 1'b1 |=> ( ($past(COUNT) == $past(COUNT)) |-> (COUNT != $past(COUNT)) )
    );

// After 16 BTN edges, COUNT repeats its value (mod-16 behavior).
    check_period_16: assert property (
        @(posedge BTN) 1'b1 |-> ##16 (COUNT == $past(COUNT,16))
    );

// X equals A || B || (C && !D)
    check_X_function: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A || B || (C && !D))
    );

// Y equals !A && (!B || (C && D))
    check_Y_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ((!A) && ((!B) || (C && D)))
    );

// When A is 1, X=1 and Y=0
    check_A_forces_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) A |-> (X == 1'b1) && (Y == 1'b0)
    );

// When A is 0, X equals B || (C && !D)
    check_notA_X_definition: assert property (
        @(posedge CLK) disable iff (1'b0) (!A) |-> (X == (B || (C && !D)))
    );

// When A is 0, Y equals !B || (C && D)
    check_notA_Y_definition: assert property (
        @(posedge CLK) disable iff (1'b0) (!A) |-> (Y == ((!B) || (C && D)))
    );

// When A=0 and B=1, X=1 and Y=(C && D)
    check_notA_B1: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && B) |-> (X == 1'b1) && (Y == (C && D))
    );

// When A=0 and B=0, X=(C && !D) and Y=1
    check_notA_B0: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B) |-> (X == (C && !D)) && (Y == 1'b1)
    );

// When A=0 and C=0, X=B and Y=!B
    check_notA_C0: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !C) |-> (X == B) && (Y == !B)
    );

// When A=0, C=1, D=0, X=1 and Y=!B
    check_notA_C1_D0: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && C && !D) |-> (X == 1'b1) && (Y == !B)
    );

// When A=0, C=1, D=1, X=B and Y=1
    check_notA_C1_D1: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && C && D) |-> (X == B) && (Y == 1'b1)
    );

// OUT equals absolute difference of A and B.
    check_abs_difference_function: assert property (
        @(posedge CLK) OUT == ((A >= B) ? (A - B) : (B - A))
    );

// When A >= B, OUT equals A - B.
    check_case_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (OUT == (A - B))
    );

// When A < B, OUT equals B - A.
    check_case_B_gt_A: assert property (
        @(posedge CLK) (A < B) |-> (OUT == (B - A))
    );

// Equal inputs produce zero output.
    check_equal_inputs_zero_out: assert property (
        @(posedge CLK) (A == B) |-> (OUT == 8'd0)
    );

// Zero output implies inputs are equal.
    check_zero_out_implies_equal: assert property (
        @(posedge CLK) (OUT == 8'd0) |-> (A == B)
    );

// If B is zero, OUT equals A.
    check_B_zero_out_eq_A: assert property (
        @(posedge CLK) (B == 8'd0) |-> (OUT == A)
    );

// If A is zero, OUT equals B.
    check_A_zero_out_eq_B: assert property (
        @(posedge CLK) (A == 8'd0) |-> (OUT == B)
    );

// Result never exceeds A when A >= B.
    check_out_le_max_when_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (OUT <= A)
    );

// Result never exceeds B when A < B.
    check_out_le_max_when_B_gt_A: assert property (
        @(posedge CLK) (A < B) |-> (OUT <= B)
    );

// Min plus OUT equals max.
    check_min_plus_out_equals_max: assert property (
        @(posedge CLK) ((A >= B) ? ((OUT + B) == A) : ((OUT + A) == B))
    );

// OUT equals one of the two directed differences.
    check_out_is_one_of_two_diffs: assert property (
        @(posedge CLK) (OUT == (A - B)) || (OUT == (B - A))
    );

// VDD matches RTL function (sampled on VPWR rising edge).
    check_vdd_def_vpwr: assert property (
        @(posedge VPWR) VDD === (((VPWR == 1'b1) && (VGND == 1'b0)) ? 1'b1 : 1'b0)
    );

// VDD matches RTL function (sampled on VGND rising edge).
    check_vdd_def_vgnd: assert property (
        @(posedge VGND) VDD === (((VPWR == 1'b1) && (VGND == 1'b0)) ? 1'b1 : 1'b0)
    );

// VSS matches RTL function (sampled on VPWR rising edge).
    check_vss_def_vpwr: assert property (
        @(posedge VPWR) VSS === (((VGND == 1'b1) && (VPWR == 1'b0)) ? 1'b1 : 1'b0)
    );

// VSS matches RTL function (sampled on VGND rising edge).
    check_vss_def_vgnd: assert property (
        @(posedge VGND) VSS === (((VGND == 1'b1) && (VPWR == 1'b0)) ? 1'b1 : 1'b0)
    );

// VDD_VSS matches RTL function (sampled on VPWR rising edge).
    check_vdd_vss_def_vpwr: assert property (
        @(posedge VPWR) VDD_VSS === (((VDD == 1'b1) && (VSS == 1'b1)) ? 1'b1 : 1'b0)
    );

// VDD_VSS matches RTL function (sampled on VGND rising edge).
    check_vdd_vss_def_vgnd: assert property (
        @(posedge VGND) VDD_VSS === (((VDD == 1'b1) && (VSS == 1'b1)) ? 1'b1 : 1'b0)
    );

// If VDD is HIGH then VSS must be LOW (sampled on VPWR rising edge).
    vdd_high_implies_vss_low_vpwr: assert property (
        @(posedge VPWR) (VDD === 1'b1) |-> (VSS === 1'b0)
    );

// If VDD is HIGH then VSS must be LOW (sampled on VGND rising edge).
    vdd_high_implies_vss_low_vgnd: assert property (
        @(posedge VGND) (VDD === 1'b1) |-> (VSS === 1'b0)
    );

// If VSS is HIGH then VDD must be LOW (sampled on VPWR rising edge).
    vss_high_implies_vdd_low_vpwr: assert property (
        @(posedge VPWR) (VSS === 1'b1) |-> (VDD === 1'b0)
    );

// If VSS is HIGH then VDD must be LOW (sampled on VGND rising edge).
    vss_high_implies_vdd_low_vgnd: assert property (
        @(posedge VGND) (VSS === 1'b1) |-> (VDD === 1'b0)
    );

// Y must equal selected input per S.
    check_mux_function: assert property (
        @(posedge clk) Y == (S ? B : A)
    );

// When S==0, Y equals A.
    check_select_zero_path: assert property (
        @(posedge clk) (S == 1'b0) |-> (Y == A)
    );

// When S==1, Y equals B.
    check_select_one_path: assert property (
        @(posedge clk) (S == 1'b1) |-> (Y == B)
    );

// With S held at 0 across cycles, a change on A is reflected on Y.
    check_follow_A_when_S0: assert property (
        @(posedge clk)
            (!$isunknown($past(S)) &&
             ($past(S) == 1'b0) && (S == 1'b0) &&
             !$isunknown($past(A)) && (A != $past(A))) |-> (Y == A)
    );

// With S held at 1 across cycles, a change on B is reflected on Y.
    check_follow_B_when_S1: assert property (
        @(posedge clk)
            (!$isunknown($past(S)) &&
             ($past(S) == 1'b1) && (S == 1'b1) &&
             !$isunknown($past(B)) && (B != $past(B))) |-> (Y == B)
    );

///// Functional mapping /////
    // When sel==00, out equals in[0].
    check_sel_00_routes_in0: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b00) |-> (out == in[0])
    );

// When sel==01, out equals in[1].
    check_sel_01_routes_in1: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b01) |-> (out == in[1])
    );

// When sel==10, out equals in[2].
    check_sel_10_routes_in2: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b10) |-> (out == in[2])
    );

// When sel==11, out equals in[3].
    check_sel_11_routes_in3: assert property (
        @(posedge CLK) disable iff (1'b0) (sel == 2'b11) |-> (out == in[3])
    );

// Out equals the bit of 'in' indexed by 'sel' at all times.
    check_out_matches_dynamic_index: assert property (
        @(posedge CLK) disable iff (1'b0) (out == in[sel])
    );

// Z must equal A & B & C every cycle.
    check_z_is_and_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) Z == (A & B & C)
    );

// When all inputs are HIGH, Z must be HIGH.
    check_all_high_implies_z_high: assert property (
        @(posedge clk) disable iff (1'b0) (A & B & C) |-> Z
    );

// If Z is HIGH, all inputs must be HIGH.
    check_z_high_implies_all_high: assert property (
        @(posedge clk) disable iff (1'b0) Z |-> (A & B & C)
    );

///// Reset behavior /////
    // While reset is asserted, clk_out must be 0.
    reset_drives_low: assert property (
        @(posedge clk_in) rst |-> (clk_out == 1'b0)
    );

// If reset is held high across cycles, clk_out stays at 0 and stable.
    reset_holds_low_stable: assert property (
        @(posedge clk_in) (rst && $past(rst)) |-> (clk_out == 1'b0) && $stable(clk_out)
    );

no_adjacent_toggles: assert property (
                    @(posedge clk_in) disable iff (rst)
                        $changed(clk_out) |-> ##1 !$changed(clk_out)
                );

// Analysis: no clock/reset in RTL; pure combinational cell: X = (A1 & A2) | B1 | C1.

    // X equals OR of B1, C1, and (A1 & A2).
    check_function_equation: assert property (
        @(posedge CLK) X == ((A1 & A2) | B1 | C1)
    );

// If B1 is HIGH, X must be HIGH.
    check_B1_forces_X: assert property (
        @(posedge CLK) B1 |-> X
    );

// If C1 is HIGH, X must be HIGH.
    check_C1_forces_X: assert property (
        @(posedge CLK) C1 |-> X
    );

// If both A1 and A2 are HIGH, X must be HIGH.
    check_A1A2_force_X: assert property (
        @(posedge CLK) (A1 & A2) |-> X
    );

// If X is LOW, then B1 and C1 are LOW and not(A1 & A2).
    check_X_low_implies_terms_low: assert property (
        @(posedge CLK) !X |-> (!B1 && !C1 && !(A1 & A2))
    );

// When B1 and C1 are LOW, X equals (A1 & A2).
    check_when_B1C1_low_X_equals_A1A2: assert property (
        @(posedge CLK) (!B1 && !C1) |-> (X == (A1 & A2))
    );

// When (A1 & A2) is LOW, X equals (B1 | C1).
    check_when_not_A1A2_X_equals_B1_or_C1: assert property (
        @(posedge CLK) (!(A1 & A2)) |-> (X == (B1 | C1))
    );

// If X is HIGH, at least one product term is HIGH.
    check_X_high_implies_some_term_high: assert property (
        @(posedge CLK) X |-> (B1 || C1 || (A1 & A2))
    );

// If all inputs are LOW, X must be LOW.
    check_all_inputs_low_implies_X_low: assert property (
        @(posedge CLK) (!A1 && !A2 && !B1 && !C1) |-> (!X)
    );

// When B1 is LOW, X equals ((A1 & A2) | C1).
    check_when_B1_low_X_equals_A1A2_or_C1: assert property (
        @(posedge CLK) (!B1) |-> (X == ((A1 & A2) | C1))
    );

// When C1 is LOW, X equals ((A1 & A2) | B1).
    check_when_C1_low_X_equals_A1A2_or_B1: assert property (
        @(posedge CLK) (!C1) |-> (X == ((A1 & A2) | B1))
    );

// Combinational 3->8 decoder; no reset in RTL; assertions sample on clk.

    // Output equals one-hot shift of input index.
    check_shift_equivalence: assert property (
        @(posedge clk) out == (8'b00000001 << in)
    );

// Output is exactly one-hot.
    check_onehot_out: assert property (
        @(posedge clk) $onehot(out)
    );

// When in==000, out==00000001.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b00000001)
    );

// When in==001, out==00000010.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b00000010)
    );

// When in==010, out==00000100.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b00000100)
    );

// When in==011, out==00001000.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b00001000)
    );

// When in==100, out==00010000.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b00010000)
    );

// When in==101, out==00100000.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b00100000)
    );

// When in==110, out==01000000.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b01000000)
    );

// When in==111, out==10000000.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b10000000)
    );

// On posedge C, R=1 clears Q on the next clock.
    check_sync_clear: assert property (
        @(posedge C) disable iff (1'b0) R |=> (Q == 1'b0)
    );

// On posedge C, with R=0 and P=1, Q is set to 1 on the next clock.
    check_sync_preset: assert property (
        @(posedge C) disable iff (1'b0) (!R && P) |=> (Q == 1'b1)
    );

// On posedge C, with R=0 and P=0, Q captures D on the next clock.
    check_data_capture: assert property (
        @(posedge C) disable iff (1'b0) (!R && !P) |=> (Q == $past(D))
    );

// If both R and P are 1, clear has priority and Q becomes 0 on the next clock.
    check_clear_priority_over_preset: assert property (
        @(posedge C) disable iff (1'b0) (R && P) |=> (Q == 1'b0)
    );

// With R=0,P=0 and D=1 at a clock, Q becomes 1 on the next clock.
    check_data1_capture: assert property (
        @(posedge C) disable iff (1'b0) (!R && !P && D) |=> (Q == 1'b1)
    );

// With R=0,P=0 and D=0 at a clock, Q becomes 0 on the next clock.
    check_data0_capture: assert property (
        @(posedge C) disable iff (1'b0) (!R && !P && !D) |=> (Q == 1'b0)
    );

// o equals selected input each cycle.
    check_mux_function: assert property (
        @(posedge CLK) o == (sel ? b : a)
    );

// When sel=0, output equals a.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (o == a)
    );

// When sel=1, output equals b.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (o == b)
    );

// On sel rising edge, output selects b.
    check_output_on_sel_rise: assert property (
        @(posedge CLK) $rose(sel) |-> (o == b)
    );

// On sel falling edge, output selects a.
    check_output_on_sel_fall: assert property (
        @(posedge CLK) $fell(sel) |-> (o == a)
    );

// If a changes while sel=0, output equals a.
    check_follow_a_when_sel0: assert property (
        @(posedge CLK) $changed(a) && (sel == 1'b0) |-> (o == a)
    );

// If b changes while sel=1, output equals b.
    check_follow_b_when_sel1: assert property (
        @(posedge CLK) $changed(b) && (sel == 1'b1) |-> (o == b)
    );

// If a==b, output equals that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge CLK) (a == b) |-> (o == a)
    );

///// Mux functional correctness /////
    // Out equals the selected input bit.
    check_mux_function: assert property (
        @(posedge clk) out == in[sel]
    );

// When sel==00, out equals in[0].
    check_sel00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// When sel==01, out equals in[1].
    check_sel01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// When sel==10, out equals in[2].
    check_sel10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// When sel==11, out equals in[3].
    check_sel11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// If sel is stable and the selected input changes, out updates to the new selected input.
    check_out_follows_selected_input: assert property (
        @(posedge clk) $stable(sel) && (in[sel] != $past(in[sel])) |-> (out == in[sel])
    );

// Output equals bitwise XNOR of inputs at all times.
    check_function_equivalence: assert property (
        @(posedge CLK) (Y === ~(A ^ B))
    );

// When inputs are known and equal, output must be 1.
    check_equal_known_implies_one: assert property (
        @(posedge CLK) (! $isunknown({A,B}) && (A == B)) |-> (Y == 1'b1)
    );

// When inputs are known and not equal, output must be 0.
    check_unequal_known_implies_zero: assert property (
        @(posedge CLK) (! $isunknown({A,B}) && (A != B)) |-> (Y == 1'b0)
    );

// When both inputs are known, output must be known (no X/Z).
    check_known_inputs_imply_known_output: assert property (
        @(posedge CLK) (! $isunknown({A,B})) |-> (! $isunknown(Y))
    );

// product1 equals button1 & ~coin
    check_product1_func_equiv: assert property (
        @(posedge CLK) product1 == (button1 & ~coin)
    );

// product2 equals button2 & ~coin
    check_product2_func_equiv: assert property (
        @(posedge CLK) product2 == (button2 & ~coin)
    );

// product3 equals button3 & ~coin
    check_product3_func_equiv: assert property (
        @(posedge CLK) product3 == (button3 & ~coin)
    );

// change equals coin
    check_change_equals_coin: assert property (
        @(posedge CLK) change == coin
    );

// If coin is HIGH, all product outputs must be LOW
    check_coin_high_blocks_products: assert property (
        @(posedge CLK) coin |-> !(product1 | product2 | product3)
    );

// If any button is pressed with coin LOW, at least one product is HIGH
    check_any_button_no_coin_causes_some_product: assert property (
        @(posedge CLK) (~coin & (button1 | button2 | button3)) |-> (product1 | product2 | product3)
    );

// product1 HIGH implies button1 is HIGH
    check_product1_implies_button1: assert property (
        @(posedge CLK) product1 |-> button1
    );

// product2 HIGH implies button2 is HIGH
    check_product2_implies_button2: assert property (
        @(posedge CLK) product2 |-> button2
    );

// product3 HIGH implies button3 is HIGH
    check_product3_implies_button3: assert property (
        @(posedge CLK) product3 |-> button3
    );

// Products and change are mutually exclusive
    check_change_and_products_mutex: assert property (
        @(posedge CLK) (product1 | product2 | product3) |-> !change
    );

// With EN high and SEL==10, q == C.
    check_en_high_sel_10_C: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b10)) |-> (q == C)
    );

// With EN high and SEL==11, q == D.
    check_en_high_sel_11_D: assert property (
        @(posedge clk) disable iff (1'b0) (EN && (SEL == 2'b11)) |-> (q == D)
    );

///// S-box mapping checks /////
    // addr 0x00 maps to 0xE.
    check_map_00: assert property (
        @(posedge clk) (addr == 6'h00) |-> (dout == 4'h0E)
    );

// addr 0x01 maps to 0x4.
    check_map_01: assert property (
        @(posedge clk) (addr == 6'h01) |-> (dout == 4'h04)
    );

// addr 0x02 maps to 0xD.
    check_map_02: assert property (
        @(posedge clk) (addr == 6'h02) |-> (dout == 4'h0D)
    );

// addr 0x03 maps to 0x1.
    check_map_03: assert property (
        @(posedge clk) (addr == 6'h03) |-> (dout == 4'h01)
    );

// addr 0x04 maps to 0x2.
    check_map_04: assert property (
        @(posedge clk) (addr == 6'h04) |-> (dout == 4'h02)
    );

// addr 0x05 maps to 0xF.
    check_map_05: assert property (
        @(posedge clk) (addr == 6'h05) |-> (dout == 4'h0F)
    );

// addr 0x06 maps to 0xB.
    check_map_06: assert property (
        @(posedge clk) (addr == 6'h06) |-> (dout == 4'h0B)
    );

// addr 0x07 maps to 0x8.
    check_map_07: assert property (
        @(posedge clk) (addr == 6'h07) |-> (dout == 4'h08)
    );

// addr 0x08 maps to 0x3.
    check_map_08: assert property (
        @(posedge clk) (addr == 6'h08) |-> (dout == 4'h03)
    );

// addr 0x09 maps to 0xA.
    check_map_09: assert property (
        @(posedge clk) (addr == 6'h09) |-> (dout == 4'h0A)
    );

// addr 0x0A maps to 0x6.
    check_map_0A: assert property (
        @(posedge clk) (addr == 6'h0A) |-> (dout == 4'h06)
    );

// addr 0x0B maps to 0xC.
    check_map_0B: assert property (
        @(posedge clk) (addr == 6'h0B) |-> (dout == 4'h0C)
    );

// addr 0x0C maps to 0x5.
    check_map_0C: assert property (
        @(posedge clk) (addr == 6'h0C) |-> (dout == 4'h05)
    );

// addr 0x0D maps to 0x9.
    check_map_0D: assert property (
        @(posedge clk) (addr == 6'h0D) |-> (dout == 4'h09)
    );

// addr 0x0E maps to 0x0.
    check_map_0E: assert property (
        @(posedge clk) (addr == 6'h0E) |-> (dout == 4'h00)
    );

// addr 0x0F maps to 0x7.
    check_map_0F: assert property (
        @(posedge clk) (addr == 6'h0F) |-> (dout == 4'h07)
    );

// All other addresses (0x10..0x3F) map to 0x0 (default).
    check_map_default: assert property (
        @(posedge clk) (addr >= 6'h10) |-> (dout == 4'h00)
    );

///// Reset behavior /////
    // While reset is asserted low, q must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst_l) |-> (q == 4'b0000)
    );

///// Data capture behavior /////
    // When not in reset for two cycles, q equals previous cycle's d.
    check_capture_prev_d: assert property (
        @(posedge clk) disable iff (!rst_l) $past(rst_l) |-> (q == $past(d))
    );

// On a reset deassertion, next cycle q reflects d from the deassertion cycle.
    check_after_release_next_matches_current_d: assert property (
        @(posedge clk) disable iff (!rst_l) $rose(rst_l) |-> ##1 (q == $past(d))
    );

// If d is unchanged across a cycle and not in reset previously, q equals d.
    check_q_equals_d_when_d_stable: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && (d == $past(d))) |-> (q == d)
    );

// If q differs from d (and wasn't in reset previously), d must have changed this cycle.
    check_q_ne_d_implies_d_changed: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && (q != d)) |-> (d != $past(d))
    );

check_q_bit_rise_implies_prev_d1: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $rose(q[i])) |-> ($past(d[i]) == 1'b1)
            );

// A fall on q[i] implies previous d[i] was 0 (no reset in prior cycle).
            check_q_bit_fall_implies_prev_d0: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $fell(q[i])) |-> ($past(d[i]) == 1'b0)
            );

check_q_bit_rise_implies_prev_d1: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $rose(q[i])) |-> ($past(d[i]) == 1'b1)
            );

// A fall on q[i] implies previous d[i] was 0 (no reset in prior cycle).
            check_q_bit_fall_implies_prev_d0: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $fell(q[i])) |-> ($past(d[i]) == 1'b0)
            );

check_q_bit_rise_implies_prev_d1: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $rose(q[i])) |-> ($past(d[i]) == 1'b1)
            );

// A fall on q[i] implies previous d[i] was 0 (no reset in prior cycle).
            check_q_bit_fall_implies_prev_d0: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $fell(q[i])) |-> ($past(d[i]) == 1'b0)
            );

check_q_bit_rise_implies_prev_d1: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $rose(q[i])) |-> ($past(d[i]) == 1'b1)
            );

// A fall on q[i] implies previous d[i] was 0 (no reset in prior cycle).
            check_q_bit_fall_implies_prev_d0: assert property (
                @(posedge clk) disable iff (!rst_l) ($past(rst_l) && $fell(q[i])) |-> ($past(d[i]) == 1'b0)
            );

// Analysis: No clock or reset in RTL; pure combinational always @*. Assertions are sampled on external CLK.
    // Analysis: Maps data_in 0-2->00, 3-5->01, 6-8->10, 9-11->11; 12-15 hit default->00.

    // 0..2 must map to 2'b00.
    map_0_to_2_is_00: assert property (
        @(posedge CLK) (data_in inside {4'd0,4'd1,4'd2}) |-> (data_out == 2'b00)
    );

// 3..5 must map to 2'b01.
    map_3_to_5_is_01: assert property (
        @(posedge CLK) (data_in inside {4'd3,4'd4,4'd5}) |-> (data_out == 2'b01)
    );

// 6..8 must map to 2'b10.
    map_6_to_8_is_10: assert property (
        @(posedge CLK) (data_in inside {4'd6,4'd7,4'd8}) |-> (data_out == 2'b10)
    );

// 9..11 must map to 2'b11.
    map_9_to_11_is_11: assert property (
        @(posedge CLK) (data_in inside {4'd9,4'd10,4'd11}) |-> (data_out == 2'b11)
    );

// 12..15 hit default and must map to 2'b00.
    map_12_to_15_default_is_00: assert property (
        @(posedge CLK) (data_in >= 4'd12) |-> (data_out == 2'b00)
    );

// If output is 2'b00, input must be 0..2 or 12..15.
    reverse_00_inputs: assert property (
        @(posedge CLK) (data_out == 2'b00) |-> (data_in inside {4'd0,4'd1,4'd2,4'd12,4'd13,4'd14,4'd15})
    );

// If output is 2'b01, input must be 3..5.
    reverse_01_inputs: assert property (
        @(posedge CLK) (data_out == 2'b01) |-> (data_in inside {4'd3,4'd4,4'd5})
    );

// If output is 2'b10, input must be 6..8.
    reverse_10_inputs: assert property (
        @(posedge CLK) (data_out == 2'b10) |-> (data_in inside {4'd6,4'd7,4'd8})
    );

// If output is 2'b11, input must be 9..11.
    reverse_11_inputs: assert property (
        @(posedge CLK) (data_out == 2'b11) |-> (data_in inside {4'd9,4'd10,4'd11})
    );

// AND opcode yields bitwise AND of operands.
    check_and_mapping: assert property (
        @(posedge clk) (logic_op_x == 2'b00) |-> (logic_result_x == (operand_0_x & operand_1_x))
    );

// OR opcode yields bitwise OR of operands.
    check_or_mapping: assert property (
        @(posedge clk) (logic_op_x == 2'b01) |-> (logic_result_x == (operand_0_x | operand_1_x))
    );

// XOR opcode yields bitwise XOR of operands.
    check_xor_mapping: assert property (
        @(posedge clk) (logic_op_x == 2'b10) |-> (logic_result_x == (operand_0_x ^ operand_1_x))
    );

// Default opcode (2'b11) yields zero.
    check_default_zero: assert property (
        @(posedge clk) (logic_op_x == 2'b11) |-> (logic_result_x == 32'h0000_0000)
    );

// AND absorbing element: if any operand is zero, result is zero.
    check_and_zero_absorbing: assert property (
        @(posedge clk) (logic_op_x == 2'b00 && ((operand_0_x == 32'h0000_0000) || (operand_1_x == 32'h0000_0000))) |-> (logic_result_x == 32'h0000_0000)
    );

// AND identity with all-ones on operand_0 passes operand_1.
    check_and_ones_identity_op0: assert property (
        @(posedge clk) (logic_op_x == 2'b00 && (operand_0_x == 32'hFFFF_FFFF)) |-> (logic_result_x == operand_1_x)
    );

// AND identity with all-ones on operand_1 passes operand_0.
    check_and_ones_identity_op1: assert property (
        @(posedge clk) (logic_op_x == 2'b00 && (operand_1_x == 32'hFFFF_FFFF)) |-> (logic_result_x == operand_0_x)
    );

// OR absorbing element: if any operand is all-ones, result is all-ones.
    check_or_ones_absorbing: assert property (
        @(posedge clk) (logic_op_x == 2'b01 && ((operand_0_x == 32'hFFFF_FFFF) || (operand_1_x == 32'hFFFF_FFFF))) |-> (logic_result_x == 32'hFFFF_FFFF)
    );

// XOR with equal operands yields zero.
    check_xor_equal_operands_zero: assert property (
        @(posedge clk) (logic_op_x == 2'b10 && (operand_0_x == operand_1_x)) |-> (logic_result_x == 32'h0000_0000)
    );

// Synchronous active-high reset clears shift_reg to zero in the cycle reset is 1.
    reset_clears_shift_reg: assert property (
        @(posedge clk) reset |-> (shift_reg == 3'b000)
    );

// If any and_input bit is 0, out must be 0.
    out_zero_when_any_input_zero: assert property (
        @(posedge clk) disable iff (reset) ((and_input[0] == 1'b0) || (and_input[1] == 1'b0)) |-> (out == 1'b0)
    );

// After a load, next-cycle out uses the loaded LSB.
    out_reflects_loaded_lsb: assert property (
        @(posedge clk) disable iff (reset) load |=> (out == (and_input[0] & and_input[1] & $past(load_data[0])))
    );

// Clock: C posedge. S: sync set (active-high). R: sync reset (active-high). Sequential flop.

    // S asserted at clock edge forces Q=1 on next clock.
    check_set_forces_one: assert property (
        @(posedge C) S |=> (Q == 1'b1)
    );

// R asserted without S forces Q=0 on next clock.
    check_reset_forces_zero_when_not_set: assert property (
        @(posedge C) (!S && R) |=> (Q == 1'b0)
    );

// When both S and R asserted, S has priority and Q=1 next clock.
    check_set_has_priority_over_reset: assert property (
        @(posedge C) (S && R) |=> (Q == 1'b1)
    );

// With neither S nor R, Q_next equals prior D.
    check_follows_d_when_no_sr: assert property (
        @(posedge C) disable iff (R) (!S && !R) |=> (Q == $past(D))
    );

// With neither S nor R and D==Q, Q holds its value.
    check_hold_when_no_sr_and_d_eq_q: assert property (
        @(posedge C) disable iff (R) (!S && !R && (D == Q)) |=> $stable(Q)
    );

// With neither S nor R and D!=Q, Q toggles to prior D.
    check_toggle_when_no_sr_and_d_neq_q: assert property (
        @(posedge C) disable iff (R) (!S && !R && (D != Q)) |=> (Q != $past(Q) && Q == $past(D))
    );

// Next-state equation: Q_next = (S ? 1 : (R ? 0 : D)).
    check_next_state_equation: assert property (
        @(posedge C) 1'b1 |=> (Q == ($past(S) ? 1'b1 : ($past(R) ? 1'b0 : $past(D))))
    );

// On a cycle with rst HIGH, next cycle count must be 0.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == '0)
    );

// While rst is held HIGH across consecutive cycles, count stays 0.
    reset_holds_zero: assert property (
        @(posedge clk) rst && $past(rst) |-> (count == '0)
    );

// Out equals (~Sel & A) | Sel (functional reduction of the RTL).
    check_out_eq_boolean_function: assert property (
        @(posedge clk) Out == ((~Sel & A) | Sel)
    );

// When Sel is LOW, Out equals A.
    check_out_eq_a_when_sel_low: assert property (
        @(posedge clk) (Sel == 1'b0) |-> (Out == A)
    );

// When Sel is HIGH, Out must be HIGH.
    check_out_high_when_sel_high: assert property (
        @(posedge clk) (Sel == 1'b1) |-> (Out == 1'b1)
    );

// If Out is LOW, both Sel and A are LOW.
    check_out_low_implies_sel_and_a_low: assert property (
        @(posedge clk) (Out == 1'b0) |-> ((Sel == 1'b0) && (A == 1'b0))
    );

// A rise with Sel LOW sets Out HIGH.
    check_a_rise_sets_out_when_sel_low: assert property (
        @(posedge clk) ((Sel == 1'b0) && $rose(A)) |-> (Out == 1'b1)
    );

// A fall with Sel LOW clears Out LOW.
    check_a_fall_clears_out_when_sel_low: assert property (
        @(posedge clk) ((Sel == 1'b0) && $fell(A)) |-> (Out == 1'b0)
    );

// Sel rising forces Out HIGH immediately.
    check_sel_rise_forces_out_high: assert property (
        @(posedge clk) $rose(Sel) |-> (Out == 1'b1)
    );

// Sel falling makes Out equal to A.
    check_sel_fall_makes_out_equal_a: assert property (
        @(posedge clk) $fell(Sel) |-> (Out == A)
    );

// Out can only rise if A or Sel is HIGH.
    check_out_rise_requires_a_or_sel_high: assert property (
        @(posedge clk) $rose(Out) |-> ((A == 1'b1) || (Sel == 1'b1))
    );

// Out can only fall if both A and Sel are LOW.
    check_out_fall_requires_a_and_sel_low: assert property (
        @(posedge clk) $fell(Out) |-> ((A == 1'b0) && (Sel == 1'b0))
    );

// Clock: clk; Reset: rst (active-high, async). Sequential logic with enable; toggle or load sampling_event.

    // Reset drives out low.
    check_reset_out_low: assert property (
        @(posedge clk) rst |-> (out == 1'b0)
    );

// When reset is asserted low at a clock edge, out must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset |-> (out == 4'h0)
    );

// On the sampled falling edge of reset, out must be zero.
    check_async_reset_on_fall: assert property (
        @(posedge clk) $fell(reset) |-> (out == 4'h0)
    );

// With reset high in consecutive cycles, out increments by 1 modulo 16.
    check_increment_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> out == (($past(out) + 4'd1) & 4'hF)
    );

// With reset high in consecutive cycles and previous out == 0xF, wrap to 0x0.
    check_wrap_from_F_to_0: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );

// Over two cycles with reset high, out advances by +2 modulo 16.
    check_two_cycle_increment: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset,2) && $past(reset,1)) |-> out == (($past(out,2) + 4'd2) & 4'hF)
    );

// On the sampled rising edge of reset (release), out is still zero at that cycle.
    check_out_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> (out == 4'h0)
    );

///// Reset behavior /////
    // When reset is asserted (low), q must be 0 at the sample.
    check_reset_forces_q0_now: assert property (
        @(posedge clk) !rst |-> (q == 1'b0)
    );

// If reset was low on the previous cycle, q is 0 now.
    check_prev_reset_keeps_q0: assert property (
        @(posedge clk) $past(!rst) |-> (q == 1'b0)
    );

///// Functional behavior (gated off during reset) /////
    // With reset deasserted, set=1 drives q to 1 on the next clock.
    check_set_drives_one_next: assert property (
        @(posedge clk) disable iff (!rst) set |=> (!rst || (q == 1'b1))
    );

// With reset deasserted and set=0, q captures d on the next clock.
    check_no_set_captures_d_next: assert property (
        @(posedge clk) disable iff (!rst) !set |=> (!rst || (q == $past(d)))
    );

// Set has priority over data when d=0 (q still becomes 1 next).
    check_set_overrides_data_when_d0: assert property (
        @(posedge clk) disable iff (!rst) (set && (d == 1'b0)) |=> (!rst || (q == 1'b1))
    );

// When set=0 and d=0, q becomes 0 on the next clock.
    check_no_set_d0_yields_q0: assert property (
        @(posedge clk) disable iff (!rst) (!set && (d == 1'b0)) |=> (!rst || (q == 1'b0))
    );

// When set=0 and d=1, q becomes 1 on the next clock.
    check_no_set_d1_yields_q1: assert property (
        @(posedge clk) disable iff (!rst) (!set && (d == 1'b1)) |=> (!rst || (q == 1'b1))
    );

// If set=0 and previous d equals previous q, q holds its value.
    check_hold_when_no_set_and_prev_d_eq_prev_q: assert property (
        @(posedge clk) disable iff (!rst) (!set && ($past(d) == $past(q))) |=> (!rst || (q == $past(q)))
    );

// Y is always the logical inversion of A.
    check_inversion_function: assert property (
        @(posedge clk) (Y == ~A)
    );

// When A is 0, Y is 1 in the same cycle.
    check_a0_y1: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

// When A is 1, Y is 0 in the same cycle.
    check_a1_y0: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// Y is never equal to A.
    check_never_equal: assert property (
        @(posedge clk) (Y != A)
    );

// Clock: clk posedge. Reset: rst active-high, async assert/sync release.
    // Logic: count is sequential; max is combinational decode of count==15.

    // While reset is asserted at the clock edge, count must be 0.
    check_count_zero_when_rst: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

// While reset is asserted at the clock edge, max must be 0.
    check_max_zero_when_rst: assert property (
        @(posedge clk) rst |-> (max == 1'b0)
    );

// max reflects count==15 combinationally.
    check_max_decodes_count: assert property (
        @(posedge clk) disable iff (rst) max == (count == 4'hF)
    );

// If count is 15 and en is 1 at a clock edge, next count wraps to 0.
    check_wrap_on_max_when_en: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 4'hF)) |=> (count == 4'h0)
    );

// If count is 15 and en is 1 at a clock edge, next max is 0.
    check_max_clears_after_wrap: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 4'hF)) |=> (max == 1'b0)
    );

// F implements F = C ^ D ^ (B & ~A)
    check_function_equivalence: assert property (
        @(posedge clk) F == ((C ^ D) ^ (B & ~A))
    );

// When B==0, F equals C ^ D
    check_B0_parity: assert property (
        @(posedge clk) (B == 1'b0) |-> (F == (C ^ D))
    );

// When A==1, F equals C ^ D
    check_A1_parity: assert property (
        @(posedge clk) (A == 1'b1) |-> (F == (C ^ D))
    );

// When A==0 and B==1, F equals ~(C ^ D)
    check_A0B1_inversion: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b1)) |-> (F == ~(C ^ D))
    );

// When A==0 and B==0, F equals C ^ D
    check_A0B0_parity: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (F == (C ^ D))
    );

// When C==D, F equals (B & ~A)
    check_C_eq_D_term: assert property (
        @(posedge clk) (C == D) |-> (F == (B & ~A))
    );

// When C!=D, F equals ~(B & ~A)
    check_C_ne_D_term: assert property (
        @(posedge clk) (C != D) |-> (F == ~(B & ~A))
    );

// Exact mapping: 4'b0000 -> F=0
    check_map_0000: assert property (
        @(posedge clk) ({A,B,C,D} == 4'b0000) |-> (F == 1'b0)
    );

// Exact mapping: 4'b0001 -> F=1
    check_map_0001: assert property (
        @(posedge clk) ({A,B,C,D} == 4'b0001) |-> (F == 1'b1)
    );

// Exact mapping: 4'b0010 -> F=1
    check_map_0010: assert property (
        @(posedge clk) ({A,B,C,D} == 4'b0010) |-> (F == 1'b1)
    );

// Exact mapping: 4'b1111 -> F=0
    check_map_1111: assert property (
        @(posedge clk) ({A,B,C,D} == 4'b1111) |-> (F == 1'b0)
    );

///// Reset behavior /////
    // While reset is LOW at a clock edge, count must be 0.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 2'b00)
    );

// On the first clock edge after reset rises, count becomes 1.
    check_first_count_after_reset_release: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && !$past(reset)) |-> (count == 2'b01)
    );

///// Counting behavior (when reset is HIGH on consecutive cycles) /////
    // Allowed transitions: 00->01, 01->10, 10->11, 11->00.
    check_allowed_transitions: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && reset) |-> (
                (($past(count) == 2'b00) && (count == 2'b01)) ||
                (($past(count) == 2'b01) && (count == 2'b10)) ||
                (($past(count) == 2'b10) && (count == 2'b11)) ||
                (($past(count) == 2'b11) && (count == 2'b00))
            )
    );

// LSB toggles every cycle when reset is HIGH on consecutive cycles.
    check_lsb_toggles: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && reset) |-> (count[0] != $past(count[0]))
    );

// MSB toggles when previous count was 01 or 11.
    check_msb_toggles_on_1_or_3: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && reset && ($past(count) inside {2'b01, 2'b11})) |-> (count[1] != $past(count[1]))
    );

// MSB holds when previous count was 00 or 10.
    check_msb_holds_on_0_or_2: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && reset && ($past(count) inside {2'b00, 2'b10})) |-> (count[1] == $past(count[1]))
    );

// Count changes every cycle when reset is HIGH on consecutive cycles.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && reset) |-> (count != $past(count))
    );

// Modulo-4 periodicity: after 4 cycles with reset HIGH, count repeats.
    check_modulo4_periodicity: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $past(reset,1) && $past(reset,2) && $past(reset,3) && $past(reset,4)) |-> (count == $past(count,4))
    );

// While reset remains asserted across cycles, count stays 0.
  check_reset_holds_zero: assert property (
    @(posedge clk) reset && $past(reset) |-> (count == 4'd0)
  );

// With enable=0 in the current cycle (and not in reset), next cycle holds the same value.
  check_hold_when_disabled_curr_to_next: assert property (
    @(posedge clk) disable iff (reset) !enable |-> ##1 (count == $past(count))
  );

// When SET_B is HIGH and RESET_B is LOW at the clock edge, Q is driven HIGH in that cycle.
    set_forces_one_when_no_reset: assert property (
        @(posedge CLK) disable iff (RESET_B) SET_B |-> (Q == 1'b1)
    );

// When both RESET_B and SET_B are LOW at the clock edge, Q equals D in that cycle.
    capture_d_when_no_controls: assert property (
        @(posedge CLK) disable iff (RESET_B || SET_B) 1'b1 |-> (Q == D)
    );

// If Q is LOW at the clock edge, then either RESET_B is HIGH or (RESET_B and SET_B are LOW and D is LOW).
    q_zero_implies_cause: assert property (
        @(posedge CLK) (Q == 1'b0) |-> (RESET_B || (!RESET_B && !SET_B && (D == 1'b0)))
    );

// Active-high synchronous reset drives outp to zero on the next cycle.
    reset_forces_zero_next: assert property (
        @(posedge clk) rst |=> (outp == '0)
    );

// When not in reset, outp captures inp with one-cycle latency.
    capture_input_next: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (outp == $past(inp))
    );

// On the cycle after reset deasserts, outp captures inp from the deasserting edge.
    capture_on_reset_release: assert property (
        @(posedge clk) $fell(rst) |=> (outp == $past(inp))
    );

// If reset is asserted on consecutive cycles, outp remains stable (stays zero).
    reset_stability: assert property (
        @(posedge clk) rst && $past(rst) |-> $stable(outp)
    );

// Out equals the OR of six 7-input AND columns (functional equivalence).
    check_out_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn) (out == sop)
    );

// OUT must be 1111110 whenever select is LOW.
    select_low_forces_off: assert property (
        @(posedge clk) disable iff (!reset_n) (select == 1'b0) |-> (OUT == 7'b1111110)
    );

// When select is HIGH and IN==0, OUT must be 0000001.
    map_digit_0: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd0)) |-> (OUT == 7'b0000001)
    );

// When select is HIGH and IN==1, OUT must be 1001111.
    map_digit_1: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd1)) |-> (OUT == 7'b1001111)
    );

// When select is HIGH and IN==2, OUT must be 0010010.
    map_digit_2: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd2)) |-> (OUT == 7'b0010010)
    );

// When select is HIGH and IN==3, OUT must be 0000110.
    map_digit_3: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd3)) |-> (OUT == 7'b0000110)
    );

// When select is HIGH and IN==4, OUT must be 1001100.
    map_digit_4: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd4)) |-> (OUT == 7'b1001100)
    );

// When select is HIGH and IN==5, OUT must be 0100100.
    map_digit_5: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd5)) |-> (OUT == 7'b0100100)
    );

// When select is HIGH and IN==6, OUT must be 0100000.
    map_digit_6: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd6)) |-> (OUT == 7'b0100000)
    );

// When select is HIGH and IN==7, OUT must be 0001111.
    map_digit_7: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd7)) |-> (OUT == 7'b0001111)
    );

// When select is HIGH and IN==8, OUT must be 0000000.
    map_digit_8: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd8)) |-> (OUT == 7'b0000000)
    );

// When select is HIGH and IN==9, OUT must be 0000100.
    map_digit_9: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd9)) |-> (OUT == 7'b0000100)
    );

// When select is HIGH and IN==10, OUT must be 0001000.
    map_digit_10: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd10)) |-> (OUT == 7'b0001000)
    );

// When select is HIGH and IN==11, OUT must be 0000000.
    map_digit_11: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd11)) |-> (OUT == 7'b0000000)
    );

// When select is HIGH and IN==12, OUT must be 0110001.
    map_digit_12: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd12)) |-> (OUT == 7'b0110001)
    );

// When select is HIGH and IN==13, OUT must be 0000001.
    map_digit_13: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd13)) |-> (OUT == 7'b0000001)
    );

// When select is HIGH and IN==14, OUT must be 0110000.
    map_digit_14: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd14)) |-> (OUT == 7'b0110000)
    );

// When select is HIGH and IN==15, OUT must be 0111000.
    map_digit_15: assert property (
        @(posedge clk) disable iff (!reset_n) (select && (IN == 4'd15)) |-> (OUT == 7'b0111000)
    );

// On reset, outputs go q=0, q_n=1.
    reset_forces_q0_qn1: assert property (
        @(posedge clk) reset |=> (q == 1'b0) && (q_n == 1'b1)
    );

// With set high (and reset low), outputs q=1, q_n=0.
    set_forces_q1_qn0: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1) && (q_n == 1'b0)
    );

// With no set, capture d and ~d from the previous cycle.
    data_captured_when_no_set: assert property (
        @(posedge clk) disable iff (reset) (!set) |=> (q == $past(d)) && (q_n == ~$past(d))
    );

// Reset wins over set when both high.
    reset_over_set_priority: assert property (
        @(posedge clk) (reset && set) |=> (q == 1'b0) && (q_n == 1'b1)
    );

// q_n is always ~q after update.
    complement_after_update: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q_n == ~q)
    );

// If no set and d rises, q rises next.
    capture_d_rise: assert property (
        @(posedge clk) disable iff (reset) (!set && $rose(d)) |=> (q == 1'b1) && (q_n == 1'b0)
    );

// If no set and d falls, q falls next.
    capture_d_fall: assert property (
        @(posedge clk) disable iff (reset) (!set && $fell(d)) |=> (q == 1'b0) && (q_n == 1'b1)
    );

// Analysis: Clock = CLK (posedge). No reset present. Sequential logic: Q<=D, QN<=~D on posedge.

    // Q equals D from the previous clock edge (one-cycle latency).
    check_q_follows_d_next: assert property (
        @(posedge CLK) 1'b1 |=> (Q == $past(D))
    );

// QN equals ~D from the previous clock edge (one-cycle latency).
    check_qn_follows_notd_next: assert property (
        @(posedge CLK) 1'b1 |=> (QN == ~($past(D)))
    );

// QN is the complement of Q (checked from the second edge onward).
    check_outputs_complement_next: assert property (
        @(posedge CLK) 1'b1 |=> (QN == ~Q)
    );

// Q and QN are never equal (checked from the second edge onward).
    check_outputs_mutex_next: assert property (
        @(posedge CLK) 1'b1 |=> (Q ^ QN)
    );

// If D rises at a clock, Q is 1 on the next clock.
    check_d_rise_sets_q_next: assert property (
        @(posedge CLK) $rose(D) |=> (Q == 1'b1)
    );

// If D falls at a clock, Q is 0 on the next clock.
    check_d_fall_clears_q_next: assert property (
        @(posedge CLK) $fell(D) |=> (Q == 1'b0)
    );

// If D is 1 at a clock, QN is 0 on the next clock.
    check_d1_drives_qn0_next: assert property (
        @(posedge CLK) (D == 1'b1) |=> (QN == 1'b0)
    );

// If D is 0 at a clock, QN is 1 on the next clock.
    check_d0_drives_qn1_next: assert property (
        @(posedge CLK) (D == 1'b0) |=> (QN == 1'b1)
    );

///// Reset behavior /////
    // When reset is asserted (active-low), COUNT is 0 in the same cycle.
    reset_level_forces_zero: assert property (
        @(posedge clk) (RST == 1'b0) |-> (COUNT == 4'b0000)
    );

// If reset was asserted in the previous cycle, COUNT is 0 now.
    reset_previous_cycle_low_forces_zero: assert property (
        @(posedge clk) ($past(RST) == 1'b0) |-> (COUNT == 4'b0000)
    );

// On a sampled falling edge of reset, COUNT is 0.
    reset_fall_sampled_forces_zero: assert property (
        @(posedge clk) $fell(RST) |-> (COUNT == 4'b0000)
    );

// On a sampled rising edge of reset (previous cycle in reset), COUNT is 0.
    reset_rise_sampled_shows_zero: assert property (
        @(posedge clk) $rose(RST) |-> (COUNT == 4'b0000)
    );

// Reset has priority over enable; if both active, COUNT is 0.
    reset_priority_over_enable: assert property (
        @(posedge clk) (RST == 1'b0 && EN == 1'b1) |-> (COUNT == 4'b0000)
    );

// COUNT must be known while reset is asserted.
    no_x_during_reset: assert property (
        @(posedge clk) (RST == 1'b0) |-> (!$isunknown(COUNT))
    );

// X implements the 2:1 mux function X = S ? A1 : A0.
    check_mux_function: assert property (
        @(posedge clk) X === (S ? A1 : A0)
    );

// When S is 0, X equals A0.
    check_select0_path: assert property (
        @(posedge clk) (S === 1'b0) |-> (X === A0)
    );

// When S is 1, X equals A1.
    check_select1_path: assert property (
        @(posedge clk) (S === 1'b1) |-> (X === A1)
    );

// If A0 equals A1, X must equal that common value.
    check_equal_inputs_dominance: assert property (
        @(posedge clk) (A0 === A1) |-> (X === A0)
    );

// Functional equivalence sampled on addr[2] edge: ce = addr[2] & ~Q & ~addr[1] & ~addr[0].
    check_function_on_addr2_edge: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            ce_expnd_i_5 == (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0])
    );

// Functional equivalence sampled on addr[3] edge (addr[3] is don't-care in RTL).
    check_function_on_addr3_edge: assert property (
        @(posedge bus2ip_addr_i_reg[3])
            ce_expnd_i_5 == (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0])
    );

// Functional equivalence sampled on addr[4] edge (addr[4] is don't-care in RTL).
    check_function_on_addr4_edge: assert property (
        @(posedge bus2ip_addr_i_reg[4])
            ce_expnd_i_5 == (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0])
    );

// If addr[2]==1, Q==0, and addr[1:0]==2'b00, output must be HIGH.
    check_unique_high_condition_sufficient: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            ((bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0]) |-> (ce_expnd_i_5 == 1'b1))
    );

// If output is HIGH, then addr[2]==1, Q==0, and addr[1:0]==2'b00 must hold.
    check_unique_high_condition_necessary: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            (ce_expnd_i_5 == 1'b1 |-> (bus2ip_addr_i_reg[2] && !Q && !bus2ip_addr_i_reg[1] && !bus2ip_addr_i_reg[0]))
    );

// With addr[2]==1, any disqualifier (Q or addr[1] or addr[0]) HIGH forces output LOW.
    check_disqualifiers_force_zero_on_addr2: assert property (
        @(posedge bus2ip_addr_i_reg[2])
            (((Q == 1'b1) || (bus2ip_addr_i_reg[1] == 1'b1) || (bus2ip_addr_i_reg[0] == 1'b1)) |-> (ce_expnd_i_5 == 1'b0))
    );

// When reset is HIGH at the clock edge, int_signal is driven to 0 in the same cycle.
    check_reset_sets_zero_now: assert property (
        @(posedge clk) rst |-> ##0 (int_signal == 1'b0)
    );

// If reset is HIGH in two consecutive samples, int_signal must read as 0 now.
    check_reset_held_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (int_signal == 1'b0)
    );

// Immediately after reset deasserts, sampled int_signal remains 0 from the prior cycle.
    check_post_reset_sample_zero: assert property (
        @(posedge clk) $fell(rst) |-> (int_signal == 1'b0)
    );

// If reset is HIGH now, int_signal is 0 on the next sampled cycle.
    check_reset_implies_next_zero: assert property (
        @(posedge clk) rst |=> (int_signal == 1'b0)
    );

// On a sampled rising edge of reset, int_signal is driven to 0 in the same cycle.
    check_reset_rise_sets_zero_now: assert property (
        @(posedge clk) $rose(rst) |-> ##0 (int_signal == 1'b0)
    );

// mod takes only values produced by the decode
    check_mod_value_set: assert property (
        @(posedge clk) disable iff (!rst_n)
        mod inside {8'h00,8'h01,8'h02,8'h03,8'h04,8'h05,8'h06,8'h07,8'h08,8'h09,8'h0a,8'h0b}
    );

// If addr[31:20]==0x000 then mod==0
    decode_000_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'h000) |-> (mod == 8'h00)
    );

// If addr[31:24]==0x10 then mod==1
    decode_10_to_1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:24] == 8'h10) |-> (mod == 8'h01)
    );

// If addr[31:20]==0xf00 then mod==2
    decode_f00_to_2: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf00) |-> (mod == 8'h02)
    );

// If addr[31:20]==0xf06 then mod==8
    decode_f06_to_8: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf06) |-> (mod == 8'h08)
    );

// If addr[31:20]==0xf07 then mod==10
    decode_f07_to_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf07) |-> (mod == 8'h0a)
    );

// If addr[31:20]==0xf08 then mod==11
    decode_f08_to_11: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf08) |-> (mod == 8'h0b)
    );

// If addr[31:20]==0xf0a then mod==9
    decode_f0a_to_9: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf0a) |-> (mod == 8'h09)
    );

// If no decode case matches, mod==0 (default)
    decode_default_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
        !(
            (addr[31:20] == 12'h000) ||
            (addr[31:24] == 8'h10)   ||
            (addr[31:20] inside {12'hf00,12'hf01,12'hf02,12'hf03,12'hf04,12'hf05,12'hf06,12'hf07,12'hf08,12'hf0a})
        ) |-> (mod == 8'h00)
    );

// If mod==1 then addr[31:24]==0x10
    mod1_implies_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h01) |-> (addr[31:24] == 8'h10)
    );

// If mod==10 then addr[31:20]==0xf07
    mod10_implies_f07: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h0a) |-> (addr[31:20] == 12'hf07)
    );

// If mod==11 then addr[31:20]==0xf08
    mod11_implies_f08: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h0b) |-> (addr[31:20] == 12'hf08)
    );

// If mod==9 then addr[31:20]==0xf0a
    mod9_implies_f0a: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h09) |-> (addr[31:20] == 12'hf0a)
    );

// eff_addr must equal the function of mod and addr
    check_eff_addr_function: assert property (
        @(posedge clk) disable iff (!rst_n)
        eff_addr == ((mod == 8'h01) ? {8'h00, addr[23:0]} : {12'h000, addr[19:0]})
    );

// When mod==1, eff_addr upper 8 bits are zero and low 24 mirror addr
    eff_addr_when_mod1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h01) |-> (eff_addr[31:24] == 8'h00) && (eff_addr[23:0] == addr[23:0])
    );

// When mod!=1, eff_addr upper 12 bits are zero and low 20 mirror addr
    eff_addr_when_not_mod1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod != 8'h01) |-> (eff_addr[31:20] == 12'h000) && (eff_addr[19:0] == addr[19:0])
    );

// Clock: clk (posedge). Reset: reset active-high synchronous.
  // Logic: mixed (sequential count, combinational next_count).
  // Behavior: modulo-4 up-counter 00->01->10->11->00.

  // On reset, count becomes 00 on the next cycle.
  reset_clears_count_next: assert property (
    @(posedge clk) reset |=> (count == 2'b00)
  );

// If reset held for consecutive cycles, count is 00 in the current cycle.
  reset_held_keeps_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == 2'b00)
  );

// From 00, next count is 01 when not in reset.
  step_from_00_to_01: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b00) |=> (count == 2'b01)
  );

// From 01, next count is 10 when not in reset.
  step_from_01_to_10: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b01) |=> (count == 2'b10)
  );

// From 10, next count is 11 when not in reset.
  step_from_10_to_11: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b10) |=> (count == 2'b11)
  );

// From 11, next count is 00 when not in reset.
  step_from_11_to_00: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b11) |=> (count == 2'b00)
  );

// Count changes every cycle when not in reset.
  count_changes_without_reset: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (count != $past(count))
  );

// After 4 cycles without reset, count returns to the same value.
  period_four_cycle: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> ##4 (count == $past(count,4))
  );

// X equals its defined boolean function.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == ((A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N)))
    );

// When B1_N is LOW, X equals A2.
    check_b1n_low_gives_a2: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == A2)
    );

// When B1_N is HIGH, X equals ~A1.
    check_b1n_high_gives_not_a1: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == (~A1))
    );

// When A1 is LOW, X equals (A2 | B1_N).
    check_a1_low_gives_a2_or_b1n: assert property (
        @(posedge CLK) (A1 == 1'b0) |-> (X == (A2 | B1_N))
    );

// When A1 is HIGH, X equals (A2 & ~B1_N).
    check_a1_high_gives_a2_and_not_b1n: assert property (
        @(posedge CLK) (A1 == 1'b1) |-> (X == (A2 & ~B1_N))
    );

// When A2 is LOW, X equals (~A1 & B1_N).
    check_a2_low_gives_not_a1_and_b1n: assert property (
        @(posedge CLK) (A2 == 1'b0) |-> (X == ((~A1) & B1_N))
    );

// When A2 is HIGH, X equals (~A1 | ~B1_N).
    check_a2_high_gives_not_a1_or_not_b1n: assert property (
        @(posedge CLK) (A2 == 1'b1) |-> (X == ((~A1) | (~B1_N)))
    );

// Corner: A1=0, A2=0, B1_N=0 => X=0.
    check_corner_all_zeroes: assert property (
        @(posedge CLK) (A1==1'b0 && A2==1'b0 && B1_N==1'b0) |-> (X==1'b0)
    );

// Corner: A1=1, A2=1, B1_N=0 => X=1.
    check_corner_a1a2_high_b1n_low: assert property (
        @(posedge CLK) (A1==1'b1 && A2==1'b1 && B1_N==1'b0) |-> (X==1'b1)
    );

// Corner: A1=1, A2=1, B1_N=1 => X=0.
    check_corner_a1a2_high_b1n_high: assert property (
        @(posedge CLK) (A1==1'b1 && A2==1'b1 && B1_N==1'b1) |-> (X==1'b0)
    );

// Output is zero-extended input_a plus 1.
    check_sum_functional: assert property (
        @(posedge clk) output_sum == ({1'b0, input_a} + 5'd1)
    );

// Lower 4 bits equal input_a + 1 modulo 16.
    check_lower_nibble_increment: assert property (
        @(posedge clk) output_sum[3:0] == (input_a + 4'd1)
    );

// Carry-out equals reduction AND of input_a (overflow on 0xF).
    check_carry_out_condition: assert property (
        @(posedge clk) output_sum[4] == (&input_a)
    );

// LSB toggles on +1 increment.
    check_bit0_toggle: assert property (
        @(posedge clk) output_sum[0] == ~input_a[0]
    );

// Bit1 equals a1 XOR a0 for +1 increment.
    check_bit1_logic: assert property (
        @(posedge clk) output_sum[1] == (input_a[1] ^ input_a[0])
    );

// Bit2 equals a2 XOR (a1 & a0) for +1 increment.
    check_bit2_logic: assert property (
        @(posedge clk) output_sum[2] == (input_a[2] ^ (input_a[1] & input_a[0]))
    );

// Bit3 equals a3 XOR (a2 & a1 & a0) for +1 increment.
    check_bit3_logic: assert property (
        @(posedge clk) output_sum[3] == (input_a[3] ^ (input_a[2] & input_a[1] & input_a[0]))
    );

// When input is 0xF, sum is 0x10.
    check_overflow_case: assert property (
        @(posedge clk) (input_a == 4'hF) |-> (output_sum == 5'h10)
    );

// When input is 0x0, sum is 0x01.
    check_zero_input_case: assert property (
        @(posedge clk) (input_a == 4'h0) |-> (output_sum == 5'h01)
    );

// Out equals selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) out == (sel ? in1 : in0)
    );

// When sel=0, out mirrors in0.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == in0)
    );

// When sel=1, out mirrors in1.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == in1)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b000
    map_sel_000: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b000) |-> (td_mode == 4'b0000)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b001
    map_sel_001: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b001) |-> (td_mode == 4'b1000)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b010
    map_sel_010: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b010) |-> (td_mode == 4'b0100)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b011
    map_sel_011: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b011) |-> (td_mode == 4'b1100)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b100
    map_sel_100: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b100) |-> (td_mode == 4'b0010)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b101
    map_sel_101: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b101) |-> (td_mode == 4'b1010)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b110
    map_sel_110: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b110) |-> (td_mode == 4'b0101)
    );

// td_mode mapping when ctrl_bits_for_mux == 3'b111
    map_sel_111: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b111) |-> (td_mode == 4'b1111)
    );

// td_mode can only be one of the enumerated decode values
    td_mode_range_check: assert property (
        @(posedge clk) td_mode inside {
            4'b0000, 4'b1000, 4'b0100, 4'b1100,
            4'b0010, 4'b1010, 4'b0101, 4'b1111
        }
    );

// Reset drives count to 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 8'd0)
    );

// When count equals max_count, next count wraps to 0.
    wrap_to_zero_at_max: assert property (
        @(posedge clk) disable iff (reset) (count == max_count) |=> (count == 8'd0)
    );

// When count is not max_count, next count increments by 1 (mod 256).
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset) (count != max_count) |=> (count == $past(count) + 8'd1)
    );

// Next-state equals 0 at max_count else equals previous+1.
    next_state_equation: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == (($past(count) == $past(max_count)) ? 8'd0 : ($past(count) + 8'd1)))
    );

// From 0 when max_count != 0, next count becomes 1.
    zero_then_one_when_max_nonzero: assert property (
        @(posedge clk) disable iff (reset) (count == 8'd0 && max_count != 8'd0) |=> (count == 8'd1)
    );

// Y equals the combinational function A_N | B_N | ~(C & D).
    check_functional_equivalence: assert property (
        @(posedge CLK) Y == (A_N | B_N | ~(C & D))
    );

// If Y is LOW, then A_N=0, B_N=0, and C&D=1 must hold.
    check_y_low_conditions: assert property (
        @(posedge CLK) (Y == 1'b0) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

// A_N HIGH forces Y HIGH.
    check_a_n_dominates: assert property (
        @(posedge CLK) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B_N HIGH forces Y HIGH.
    check_b_n_dominates: assert property (
        @(posedge CLK) (B_N == 1'b1) |-> (Y == 1'b1)
    );

// C LOW forces Y HIGH (since ~(C&D)=1).
    check_c_low_forces_y_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

// D LOW forces Y HIGH (since ~(C&D)=1).
    check_d_low_forces_y_high: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );

// With A_N=0 and B_N=0, Y reduces to ~(C & D).
    check_reduce_when_an_bn_low: assert property (
        @(posedge CLK) ((A_N == 1'b0) && (B_N == 1'b0)) |-> (Y == ~(C & D))
    );

// With C=1 and D=1, Y reduces to A_N | B_N.
    check_reduce_when_c_d_high: assert property (
        @(posedge CLK) ((C == 1'b1) && (D == 1'b1)) |-> (Y == (A_N | B_N))
    );

// While reset is asserted at a clock edge, count must be 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// If reset is held high across consecutive clocks, count is 0 at the current clock.
    reset_hold_zero_now: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (count == 4'd0)
    );

// If reset is held high across consecutive clocks, count was 0 at the previous clock.
    reset_hold_zero_prev: assert property (
        @(posedge clk) ($past(rst) && rst) |-> ($past(count) == 4'd0)
    );

// Out of reset, count value is always within 0..9.
    count_in_range: assert property (
        @(posedge clk) disable iff (rst) (count <= 4'd9)
    );

// Whenever count is 9 at a clock edge (out of reset), the next value is 0.
    wrap_from_9_to_0: assert property (
        @(posedge clk) disable iff (rst) (count == 4'd9) |=> (count == 4'd0)
    );

// If previous clock was in reset, the current count is 0.
    prev_reset_implies_zero_now: assert property (
        @(posedge clk) $past(rst) |-> (count == 4'd0)
    );

// Clock: CK (posedge). Reset: none. Logic: combinational 2:1 mux (E ? SE : CK).

    // ECK implements (E & SE) | (!E & CK).
    check_mux_equation: assert property (
        @(posedge CK) ECK == ((E & SE) | (!E & CK))
    );

// When E is 1, ECK follows SE.
    check_E_high_selects_SE: assert property (
        @(posedge CK) (E == 1'b1) |-> (ECK == SE)
    );

// When E is 0, ECK follows CK.
    check_E_low_selects_CK: assert property (
        @(posedge CK) (E == 1'b0) |-> (ECK == CK)
    );

// If SE equals CK, ECK equals that common value.
    check_equal_inputs_hold: assert property (
        @(posedge CK) (SE == CK) |-> (ECK == CK)
    );

// If ECK is 1, it must be driven by E&SE or !E&CK.
    check_eck_one_implication: assert property (
        @(posedge CK) (ECK == 1'b1) |-> ((E & SE) | (!E & CK))
    );

// If ECK is 0, it must be driven by E&!SE or !E&!CK.
    check_eck_zero_implication: assert property (
        @(posedge CK) (ECK == 1'b0) |-> ((E & !SE) | (!E & !CK))
    );

///// 5-to-1 mux functionality /////
    // When sel[2] is 1, dout must equal din5.
    route_when_sel2_high: assert property (
        @(posedge CLK) disable iff (1'b0) (din6[2] == 1'b1) |-> (dout == din5)
    );

// When sel == 3'b000, dout must equal din1.
    route_sel000_to_din1: assert property (
        @(posedge CLK) disable iff (1'b0) (din6 == 3'b000) |-> (dout == din1)
    );

// When sel == 3'b001, dout must equal din2.
    route_sel001_to_din2: assert property (
        @(posedge CLK) disable iff (1'b0) (din6 == 3'b001) |-> (dout == din2)
    );

// When sel == 3'b010, dout must equal din3.
    route_sel010_to_din3: assert property (
        @(posedge CLK) disable iff (1'b0) (din6 == 3'b010) |-> (dout == din3)
    );

// When sel == 3'b011, dout must equal din4.
    route_sel011_to_din4: assert property (
        @(posedge CLK) disable iff (1'b0) (din6 == 3'b011) |-> (dout == din4)
    );

// Direct equivalence to the nested-ternary mux structure.
    functional_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0)
            dout == (din6[2] ? din5
                   : (din6[1] ? (din6[0] ? din4 : din3)
                              : (din6[0] ? din2 : din1)))
    );

// dout always equals one of the five data inputs.
    dout_is_from_inputs: assert property (
        @(posedge CLK) disable iff (1'b0)
            (dout == din1) || (dout == din2) || (dout == din3) || (dout == din4) || (dout == din5)
    );

///// Functional mapping checks /////
    // For input <= 4, output equals (input - 1) truncated to 3 bits.
    check_low_range_function: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal <= 4'd4) |-> (output_signal == ((input_signal - 4'd1) & 3'b111))
    );

// For input > 4, output equals (input + 1) truncated to 3 bits.
    check_high_range_function: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal > 4'd4) |-> (output_signal == ((input_signal + 4'd1) & 3'b111))
    );

// For 1..4, decrement occurs without 3-bit wrap.
    check_decrement_no_wrap_1_to_4: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal inside {[4'd1:4'd4]}) |-> (output_signal == (input_signal - 4'd1))
    );

// For 5..6, increment occurs without 3-bit wrap.
    check_increment_no_wrap_5_to_6: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal inside {[4'd5:4'd6]}) |-> (output_signal == (input_signal + 4'd1))
    );

///// Corner cases /////
    // Input 0 maps to 7 (wrap due to subtraction).
    check_zero_maps_to_7: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal == 4'd0) |-> (output_signal == 3'd7)
    );

// Input 4 maps to 3 (no wrap).
    check_four_maps_to_3: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal == 4'd4) |-> (output_signal == 3'd3)
    );

// Input 7 maps to 0 (wrap on increment).
    check_seven_maps_to_0: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal == 4'd7) |-> (output_signal == 3'd0)
    );

// Input 8 maps to 1 (post-wrap increment).
    check_eight_maps_to_1: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal == 4'd8) |-> (output_signal == 3'd1)
    );

// Input 15 maps to 0 (wrap due to increment).
    check_fifteen_maps_to_0: assert property (
        @(posedge clk) disable iff (1'b0)
            (input_signal == 4'd15) |-> (output_signal == 3'd0)
    );

// Combinational 16:1 mux: data_o equals the selected input.

    // When select==0, output equals data_i00.
    check_mux_sel_0: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h0) |-> (data_o == data_i00)
    );

// When select==1, output equals data_i01.
    check_mux_sel_1: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h1) |-> (data_o == data_i01)
    );

// When select==2, output equals data_i02.
    check_mux_sel_2: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h2) |-> (data_o == data_i02)
    );

// When select==3, output equals data_i03.
    check_mux_sel_3: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h3) |-> (data_o == data_i03)
    );

// When select==4, output equals data_i04.
    check_mux_sel_4: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h4) |-> (data_o == data_i04)
    );

// When select==5, output equals data_i05.
    check_mux_sel_5: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h5) |-> (data_o == data_i05)
    );

// When select==6, output equals data_i06.
    check_mux_sel_6: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h6) |-> (data_o == data_i06)
    );

// When select==7, output equals data_i07.
    check_mux_sel_7: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h7) |-> (data_o == data_i07)
    );

// When select==8, output equals data_i08.
    check_mux_sel_8: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h8) |-> (data_o == data_i08)
    );

// When select==9, output equals data_i09.
    check_mux_sel_9: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'h9) |-> (data_o == data_i09)
    );

// When select==10, output equals data_i10.
    check_mux_sel_10: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hA) |-> (data_o == data_i10)
    );

// When select==11, output equals data_i11.
    check_mux_sel_11: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hB) |-> (data_o == data_i11)
    );

// When select==12, output equals data_i12.
    check_mux_sel_12: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hC) |-> (data_o == data_i12)
    );

// When select==13, output equals data_i13.
    check_mux_sel_13: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hD) |-> (data_o == data_i13)
    );

// When select==14, output equals data_i14.
    check_mux_sel_14: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hE) |-> (data_o == data_i14)
    );

// When select==15, output equals data_i15.
    check_mux_sel_15: assert property (
        @(posedge CLK) disable iff (!RESETn) (select == 4'hF) |-> (data_o == data_i15)
    );

// When s1s0==00, y equals x0.
    mux_sel_00: assert property (
        @(posedge CLK) (s1 == 1'b0 && s0 == 1'b0) |-> (y === x0)
    );

// When s1s0==01, y equals x1.
    mux_sel_01: assert property (
        @(posedge CLK) (s1 == 1'b0 && s0 == 1'b1) |-> (y === x1)
    );

// When s1s0==10, y equals x2.
    mux_sel_10: assert property (
        @(posedge CLK) (s1 == 1'b1 && s0 == 1'b0) |-> (y === x2)
    );

// When s1s0==11, y equals x3.
    mux_sel_11: assert property (
        @(posedge CLK) (s1 == 1'b1 && s0 == 1'b1) |-> (y === x3)
    );

// out_sum equals 8-bit addition of inputs.
    check_sum_matches_8b_add: assert property (
        @(posedge CLK) out_sum == (in_a + in_b)
    );

// Adding zero on B leaves A unchanged and carry zero.
    check_zero_b_identity: assert property (
        @(posedge CLK) (in_b == 8'h00) |-> (out_sum == in_a) && (out_carry == 1'b0)
    );

// Adding zero on A leaves B unchanged and carry zero.
    check_zero_a_identity: assert property (
        @(posedge CLK) (in_a == 8'h00) |-> (out_sum == in_b) && (out_carry == 1'b0)
    );

// Both inputs zero produce zero sum and zero carry.
    check_both_zero_result_zero: assert property (
        @(posedge CLK) (in_a == 8'h00 && in_b == 8'h00) |-> (out_sum == 8'h00) && (out_carry == 1'b0)
    );

///// Reset behavior /////
    // While reset is asserted low, Q must be 0.
    check_reset_low_forces_zero: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

// When reset falls (1->0), Q is 0 at this sample.
    check_reset_fall_clears_q: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

// If reset is low in consecutive cycles, Q remains 0 across them.
    check_reset_hold_zero: assert property (
        @(posedge CLK) (!$past(RESET_B) && !RESET_B) |-> ($past(Q) == 1'b0 && Q == 1'b0)
    );

// After reset deasserts (prev low, now high), next cycle Q equals D from deassert cycle.
    check_capture_after_reset_release: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!$past(RESET_B) && RESET_B) |=> (Q == $past(D))
    );

// Gray MSB equals binary MSB.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_out[3] == bin_in[3]
    );

// Gray[2] equals bin_in[3] XOR bin_in[2].
    check_gray_bit2_is_b3_xor_b2: assert property (
        @(posedge clk) gray_out[2] == (bin_in[3] ^ bin_in[2])
    );

// Gray[1] equals bin_in[2] XOR bin_in[1].
    check_gray_bit1_is_b2_xor_b1: assert property (
        @(posedge clk) gray_out[1] == (bin_in[2] ^ bin_in[1])
    );

// Gray[0] equals bin_in[1] XOR bin_in[0].
    check_gray_bit0_is_b1_xor_b0: assert property (
        @(posedge clk) gray_out[0] == (bin_in[1] ^ bin_in[0])
    );

// Vector mapping equals {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_vector_mapping: assert property (
        @(posedge clk) gray_out == {bin_in[3], (bin_in[3] ^ bin_in[2]), (bin_in[2] ^ bin_in[1]), (bin_in[1] ^ bin_in[0])}
    );

// Binary[3] recovered from Gray equals gray_out[3].
    check_bin3_from_gray: assert property (
        @(posedge clk) bin_in[3] == gray_out[3]
    );

// Binary[2] recovered as gray_out[3] XOR gray_out[2].
    check_bin2_from_gray: assert property (
        @(posedge clk) bin_in[2] == (gray_out[3] ^ gray_out[2])
    );

// Binary[1] recovered as gray_out[3] XOR gray_out[2] XOR gray_out[1].
    check_bin1_from_gray: assert property (
        @(posedge clk) bin_in[1] == (gray_out[3] ^ gray_out[2] ^ gray_out[1])
    );

// Binary[0] recovered as gray_out[3] XOR gray_out[2] XOR gray_out[1] XOR gray_out[0].
    check_bin0_from_gray: assert property (
        @(posedge clk) bin_in[0] == (gray_out[3] ^ gray_out[2] ^ gray_out[1] ^ gray_out[0])
    );

// Clock: mdio_mdc; Reset: none. Logic: combinational pass-through and AND on mdio_i.

    // phy0_mdc mirrors mdio_mdc.
    check_phy0_mdc_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdc == mdio_mdc)
    );

// phy1_mdc mirrors mdio_mdc.
    check_phy1_mdc_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdc == mdio_mdc)
    );

// phy0_mdio_t mirrors mdio_t.
    check_phy0_t_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdio_t == mdio_t)
    );

// phy1_mdio_t mirrors mdio_t.
    check_phy1_t_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdio_t == mdio_t)
    );

// phy0_mdio_o mirrors mdio_o.
    check_phy0_o_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdio_o == mdio_o)
    );

// phy1_mdio_o mirrors mdio_o.
    check_phy1_o_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdio_o == mdio_o)
    );

// mdio_i is the AND of phy0_mdio_i and phy1_mdio_i.
    check_mdio_i_and: assert property (
        @(posedge mdio_mdc) (mdio_i == (phy0_mdio_i & phy1_mdio_i))
    );

// The two PHY MDC outputs are identical.
    check_mdc_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdc == phy1_mdc)
    );

// The two PHY MDIO_t outputs are identical.
    check_t_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdio_t == phy1_mdio_t)
    );

// The two PHY MDIO_o outputs are identical.
    check_o_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdio_o == phy1_mdio_o)
    );

// If either PHY MDIO input is 0, mdio_i must be 0.
    check_mdio_i_zero_if_any_zero: assert property (
        @(posedge mdio_mdc) ((!phy0_mdio_i) || (!phy1_mdio_i)) |-> (mdio_i == 1'b0)
    );

// If both PHY MDIO inputs are 1, mdio_i must be 1.
    check_mdio_i_one_if_both_one: assert property (
        @(posedge mdio_mdc) (phy0_mdio_i && phy1_mdio_i) |-> (mdio_i == 1'b1)
    );

// qbar is always 0 due to logic structure.
    check_qbar_always_zero: assert property (
        @(posedge clk) qbar == 1'b0
    );

// When i0=0 and i1=0, qbar must be 0.
    check_qbar_zero_when_no_i0_i1: assert property (
        @(posedge clk) ((~i0) && (~i1)) |-> (qbar == 1'b0)
    );

// If q is 1 then qbar must be 0.
    check_qbar_zero_when_q_one: assert property (
        @(posedge clk) (q == 1'b1) |-> (qbar == 1'b0)
    );

// q and qbar are never both 1.
    check_q_qbar_never_both_one: assert property (
        @(posedge clk) !(q && qbar)
    );

// Output equals logical AND of inputs.
    check_and_function: assert property (
        @(posedge CLK) Y == (A & B)
    );

// If both inputs are HIGH, output is HIGH.
    check_inputs_high_implies_y_high: assert property (
        @(posedge CLK) (A && B) |-> (Y == 1'b1)
    );

// If A is LOW, output is LOW.
    check_a_low_forces_y_low: assert property (
        @(posedge CLK) (!A) |-> (Y == 1'b0)
    );

// If B is LOW, output is LOW.
    check_b_low_forces_y_low: assert property (
        @(posedge CLK) (!B) |-> (Y == 1'b0)
    );

// Output HIGH implies both inputs are HIGH.
    check_y_high_implies_inputs_high: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A && B)
    );

// Rising edge on output requires both inputs HIGH.
    check_y_rise_requires_inputs_high: assert property (
        @(posedge CLK) $rose(Y) |-> (A && B)
    );

// Falling edge on output implies at least one input LOW.
    check_y_fall_implies_input_low: assert property (
        @(posedge CLK) $fell(Y) |-> ((!A) || (!B))
    );

// When A > B, OUT must be 01.
    check_gt_sets_code: assert property (
        @(posedge CLK) (A > B) |-> (OUT == 2'b01)
    );

// When A < B, OUT must be 10.
    check_lt_sets_code: assert property (
        @(posedge CLK) (A < B) |-> (OUT == 2'b10)
    );

// When A == B, OUT must be 11.
    check_eq_sets_code: assert property (
        @(posedge CLK) (A == B) |-> (OUT == 2'b11)
    );

// OUT must never be 00.
    check_out_never_00: assert property (
        @(posedge CLK) (OUT != 2'b00)
    );

// If OUT is 01, then A > B.
    check_code_implies_gt: assert property (
        @(posedge CLK) (OUT == 2'b01) |-> (A > B)
    );

// If OUT is 10, then A < B.
    check_code_implies_lt: assert property (
        @(posedge CLK) (OUT == 2'b10) |-> (A < B)
    );

// If OUT is 11, then A == B.
    check_code_implies_eq: assert property (
        @(posedge CLK) (OUT == 2'b11) |-> (A == B)
    );

// On clkin rising edge, clkout equals bitwise inversion of clkin.
    check_inversion_on_posedge: assert property (
        @(posedge clkin) clkout === ~clkin
    );

// On clkin falling edge, clkout equals bitwise inversion of clkin.
    check_inversion_on_negedge: assert property (
        @(negedge clkin) clkout === ~clkin
    );

// Combinational RTL with no reset/clock; assertions sample on 'clk'.

    // When dir==0, out equals right-path expression.
    check_dir0_function: assert property (
        @(posedge clk) (dir == 1'b0) |-> (out == ({in[1:0], 2'b00} >> shift))
    );

// When dir==1, out equals left-path expression.
    check_dir1_function: assert property (
        @(posedge clk) (dir == 1'b1) |-> (out == ({2'b00, in[3:2]} << shift))
    );

// dir==0, shift==0 maps low 2 bits to out[3:2], zeros in out[1:0].
    map_dir0_s0: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd0) |-> (out[3:2] == in[1:0] && out[1:0] == 2'b00)
    );

// dir==0, shift==1 maps low 2 bits to out[2:1], zeros at out[3] and out[0].
    map_dir0_s1: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd1) |-> (out[3] == 1'b0 && out[2:1] == in[1:0] && out[0] == 1'b0)
    );

// dir==0, shift==2 maps low 2 bits to out[1:0], zeros in out[3:2].
    map_dir0_s2: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd2) |-> (out[3:2] == 2'b00 && out[1:0] == in[1:0])
    );

// dir==0, shift==3 maps in[1] to out[0], zeros in out[3:1].
    map_dir0_s3: assert property (
        @(posedge clk) (dir == 1'b0 && shift == 2'd3) |-> (out[3:1] == 3'b000 && out[0] == in[1])
    );

// dir==1, shift==0 maps high 2 bits to out[1:0], zeros in out[3:2].
    map_dir1_s0: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd0) |-> (out[3:2] == 2'b00 && out[1:0] == in[3:2])
    );

// dir==1, shift==1 maps high 2 bits to out[2:1], zeros at out[3] and out[0].
    map_dir1_s1: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd1) |-> (out[3] == 1'b0 && out[2:1] == in[3:2] && out[0] == 1'b0)
    );

// dir==1, shift==2 maps high 2 bits to out[3:2], zeros in out[1:0].
    map_dir1_s2: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd2) |-> (out[3:2] == in[3:2] && out[1:0] == 2'b00)
    );

// dir==1, shift==3 maps in[2] to out[3], zeros in out[2:0].
    map_dir1_s3: assert property (
        @(posedge clk) (dir == 1'b1 && shift == 2'd3) |-> (out[3] == in[2] && out[2:0] == 3'b000)
    );

// Output equals logical OR of inputs each cycle.
    check_or_function: assert property (
        @(posedge CLK) X == (A | B)
    );

// When both inputs are 0, output must be 0.
    check_zero_zero_low: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0) |-> (X == 1'b0)
    );

// If output is 1, at least one input must be 1.
    check_x_high_requires_input_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1))
    );

// If A is 1, output must be 1.
    check_a_high_implies_x_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

// If B is 1, output must be 1.
    check_b_high_implies_x_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

// When B is 0, output follows A.
    check_follow_a_when_b_zero: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == A)
    );

// When A is 0, output follows B.
    check_follow_b_when_a_zero: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == B)
    );

// overflow reflects out == 4'hF.
    check_overflow_definition: assert property (
        @(posedge clk) disable iff (reset) overflow == (out == 4'hF)
    );

// Y must equal the coded 4:1 mux equation.
    check_mux_equation: assert property (
        @(posedge CLK) Y == ((~S1 & ~S0 & A) | (~S1 & S0 & B) | (S1 & ~S0 & C) | (S1 & S0 & D))
    );

// When S1S0==00, Y equals A.
    check_sel_00_maps_to_A: assert property (
        @(posedge CLK) (!S1 && !S0) |-> (Y == A)
    );

// When S1S0==01, Y equals B.
    check_sel_01_maps_to_B: assert property (
        @(posedge CLK) (!S1 && S0) |-> (Y == B)
    );

// When S1S0==10, Y equals C.
    check_sel_10_maps_to_C: assert property (
        @(posedge CLK) (S1 && !S0) |-> (Y == C)
    );

// When S1S0==11, Y equals D.
    check_sel_11_maps_to_D: assert property (
        @(posedge CLK) (S1 && S0) |-> (Y == D)
    );

// rd follows wd unless w&&a[2], then rd is 0.
    check_rd_function: assert property (
        @(posedge c) rd == ((w && a[2]) ? 32'd0 : wd)
    );

// uart is 1 unless w&&a[2], then uart mirrors c.
    check_uart_function: assert property (
        @(posedge c) uart == ((w && a[2]) ? c : 1'b1)
    );

// In non-UART mode (!(w&&a[2])) rd=wd and uart=1.
    check_non_uart_mode_outputs: assert property (
        @(posedge c) !(w && a[2]) |-> ((rd == wd) && (uart == 1'b1))
    );

// In UART mode (w&&a[2]) rd=0 and uart=c.
    check_uart_mode_outputs: assert property (
        @(posedge c) (w && a[2]) |-> ((rd == 32'd0) && (uart == c))
    );

// If uart is 0, then w&&a[2] must hold and c must be 0.
    check_uart_low_implies_mode_and_c_low: assert property (
        @(posedge c) (uart == 1'b0) |-> ((w && a[2]) && (c == 1'b0))
    );

// If rd is 0, it is due to UART mode or wd being 0.
    check_rd_zero_origin: assert property (
        @(posedge c) (rd == 32'd0) |-> ((w && a[2]) || (wd == 32'd0))
    );

// When w is HIGH and a[2] is LOW, rd=wd and uart=1.
    check_w_high_a2_low_outputs: assert property (
        @(posedge c) (w && !a[2]) |-> ((rd == wd) && (uart == 1'b1))
    );

// When w is LOW, rd=wd and uart=1.
    check_w_low_outputs: assert property (
        @(posedge c) (!w) |-> ((rd == wd) && (uart == 1'b1))
    );

// Y equals ~(B1 | (A1 & A2 & A3)) sampled on A1 rising.
    function_equivalence_on_a1: assert property (
        @(posedge A1) (Y == ~(B1 | (A1 & A2 & A3)))
    );

// Y equals ~(B1 | (A1 & A2 & A3)) sampled on A2 rising.
    function_equivalence_on_a2: assert property (
        @(posedge A2) (Y == ~(B1 | (A1 & A2 & A3)))
    );

// Y equals ~(B1 | (A1 & A2 & A3)) sampled on A3 rising.
    function_equivalence_on_a3: assert property (
        @(posedge A3) (Y == ~(B1 | (A1 & A2 & A3)))
    );

// Y equals ~(B1 | (A1 & A2 & A3)) sampled on B1 rising.
    function_equivalence_on_b1: assert property (
        @(posedge B1) (Y == ~(B1 | (A1 & A2 & A3)))
    );

// Y equals ~(B1 | (A1 & A2 & A3)) sampled on Y rising.
    function_equivalence_on_y: assert property (
        @(posedge Y) (Y == ~(B1 | (A1 & A2 & A3)))
    );

// When all A's are HIGH, Y must be LOW (sampled on A1 rising).
    all_a_high_forces_y_low_on_a1: assert property (
        @(posedge A1) ((A1 & A2 & A3) |-> (Y == 1'b0))
    );

// When all A's are HIGH, Y must be LOW (sampled on A2 rising).
    all_a_high_forces_y_low_on_a2: assert property (
        @(posedge A2) ((A1 & A2 & A3) |-> (Y == 1'b0))
    );

// When all A's are HIGH, Y must be LOW (sampled on A3 rising).
    all_a_high_forces_y_low_on_a3: assert property (
        @(posedge A3) ((A1 & A2 & A3) |-> (Y == 1'b0))
    );

// Output equals XOR of inputs each cycle.
    check_xor_function: assert property (
        @(posedge clk) out == (a ^ b)
    );

// When inputs are equal, output is 0.
    check_out_zero_when_inputs_equal: assert property (
        @(posedge clk) (a == b) |-> (out == 1'b0)
    );

// When inputs differ, output is 1.
    check_out_one_when_inputs_differ: assert property (
        @(posedge clk) (a != b) |-> (out == 1'b1)
    );

// Truth table: a=0,b=0 => out=0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out == 1'b0)
    );

// Truth table: a=1,b=0 => out=1.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out == 1'b1)
    );

// Truth table: a=0,b=1 => out=1.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out == 1'b1)
    );

// Truth table: a=1,b=1 => out=0.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b0)
    );

// C must equal bitwise XOR of A and B every cycle.
    check_vector_xor: assert property (
        @(posedge clk) C == (A ^ B)
    );

// Change in C equals XOR of changes in A and B (delta identity).
    check_delta_identity: assert property (
        @(posedge clk) 1'b1 |=> ((C ^ $past(C)) == ((A ^ $past(A)) ^ (B ^ $past(B))))
    );

// If both inputs are stable, output must be stable too.
    check_stable_if_inputs_stable: assert property (
        @(posedge clk) 1'b1 |=> (($stable(A) && $stable(B)) |-> $stable(C))
    );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// C[i] must equal A[i] ^ B[i] each cycle.
            check_bit_xor: assert property (
                @(posedge clk) C[i] == (A[i] ^ B[i])
            );

// Combinational module; no reset in RTL. clk is a sampling clock for SVA.
    // out1 is the AND of in1..in9 via the internal and*_out chain.

    // and0 implements in1 & in2.
    check_and0_func: assert property (
        @(posedge clk) and0_out == (in1 & in2)
    );

// and1 implements in3 & in4.
    check_and1_func: assert property (
        @(posedge clk) and1_out == (in3 & in4)
    );

// and2 implements in5 & in6.
    check_and2_func: assert property (
        @(posedge clk) and2_out == (in5 & in6)
    );

// and3 implements in7 & in8.
    check_and3_func: assert property (
        @(posedge clk) and3_out == (in7 & in8)
    );

// and4 combines and0_out & and1_out.
    check_and4_func: assert property (
        @(posedge clk) and4_out == (and0_out & and1_out)
    );

// and5 combines and2_out & and3_out.
    check_and5_func: assert property (
        @(posedge clk) and5_out == (and2_out & and3_out)
    );

// and6 combines and4_out & and5_out.
    check_and6_func: assert property (
        @(posedge clk) and6_out == (and4_out & and5_out)
    );

// and7 combines and6_out & in9.
    check_and7_func: assert property (
        @(posedge clk) and7_out == (and6_out & in9)
    );

// buf drives out1 from and7_out.
    check_buf_func: assert property (
        @(posedge clk) out1 == and7_out
    );

// out1 equals the AND of all nine inputs.
    check_out1_all_inputs_and: assert property (
        @(posedge clk) out1 == (in1 & in2 & in3 & in4 & in5 & in6 & in7 & in8 & in9)
    );

///// Reset behavior /////
    // During active-low reset, address registers hold their reset values.
    reset_defaults: assert property (
        @(posedge clk) !reset_b |-> (address_port_0 == 8'h00) && (address_port_1 == 8'h01) && (address_port_2 == 8'h02) && (address_port_3 == 8'h03)
    );

///// Read mux /////
    // mem_addr==2'b00 maps mem_rdata to address_port_0.
    readmux_sel0: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b00) |-> (mem_rdata == address_port_0)
    );

// mem_addr==2'b01 maps mem_rdata to address_port_1.
    readmux_sel1: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b01) |-> (mem_rdata == address_port_1)
    );

// mem_addr==2'b10 maps mem_rdata to address_port_2.
    readmux_sel2: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b10) |-> (mem_rdata == address_port_2)
    );

// mem_addr==2'b11 maps mem_rdata to address_port_3.
    readmux_sel3: assert property (
        @(posedge clk) disable iff (!reset_b) (mem_addr == 2'b11) |-> (mem_rdata == address_port_3)
    );

///// Write behavior /////
    // Write to addr 0 updates address_port_0 by next cycle unless immediately rewritten next cycle.
    write_addr0_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b00)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b00)) ? 1'b1 : (address_port_0 == $past(mem_wdata)) )
    );

// Write to addr 1 updates address_port_1 by next cycle unless immediately rewritten next cycle.
    write_addr1_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b01)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b01)) ? 1'b1 : (address_port_1 == $past(mem_wdata)) )
    );

// Write to addr 2 updates address_port_2 by next cycle unless immediately rewritten next cycle.
    write_addr2_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b10)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b10)) ? 1'b1 : (address_port_2 == $past(mem_wdata)) )
    );

// Write to addr 3 updates address_port_3 by next cycle unless immediately rewritten next cycle.
    write_addr3_updates_selected: assert property (
        @(posedge clk) disable iff (!reset_b)
            ($past(reset_b) && mem_en && mem_rd_wr && (mem_addr == 2'b11)) |=> 
                ( (mem_en && mem_rd_wr && (mem_addr == 2'b11)) ? 1'b1 : (address_port_3 == $past(mem_wdata)) )
    );

// If b is zero, both outputs are driven to 0.
    check_b_zero_outputs_zero: assert property (
        @(posedge clk) (b == 8'd0) |-> (result == 8'd0) && (wresult == 8'd0)
    );

// If a is zero and b is non-zero, both outputs are 0xFF.
    check_a_zero_b_nonzero_outputs_ff: assert property (
        @(posedge clk) (a == 8'd0) && (b != 8'd0) |-> (result == 8'hFF) && (wresult == 8'hFF)
    );

// Reset drives data_out and encrypted_data to zero.
  reset_clears_regs: assert property (
    @(posedge clk) reset |-> (data_out == 8'h00) && (encrypted_data == 8'h00)
  );

// With enable=0, data_out passes through data_in on the next cycle.
  en0_bypass_data_out: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (data_out == $past(data_in))
  );

// Back-to-back enable cycles propagate the first cycle's XOR to data_out two cycles later.
  back_to_back_enable_pipeline: assert property (
    @(posedge clk) disable iff (reset) (enable ##1 enable) |=> (data_out == $past(data_in ^ key, 2))
  );

///// Reset behavior /////
  // On a clock edge while reset is HIGH, state/counters are in reset values.
  reset_state_counters: assert property (
    @(posedge clk) reset |-> (state == GREEN) && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );

// On a clock edge while reset is HIGH, outputs reflect GREEN.
  reset_outputs_green: assert property (
    @(posedge clk) reset |-> (green_led == 1'b1) && (yellow_led == 1'b0) && (red_led == 1'b0)
  );

// Exactly one LED is ON at a time.
  leds_onehot: assert property (
    @(posedge clk) disable iff (reset) $onehot({green_led, yellow_led, red_led})
  );

// Sum equals 4-bit truncated A+B+C_in.
    check_sum_lower4: assert property (
        @(posedge CLK) S == (A + B + C_in)
    );

// Bit0 of sum is XOR of A0, B0, and C_in.
    check_bit0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ C_in)
    );

// Bit1 of sum uses carry from bit0.
    check_bit1_xor_with_c0: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ ((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in)))
    );

// Bit2 of sum uses carry from bit1 (which depends on bit0).
    check_bit2_xor_with_c1: assert property (
        @(posedge CLK) S[2] == (
            A[2] ^ B[2] ^
            ( (A[1]&B[1]) |
              (A[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) |
              (B[1]&((A[0]&B[0]) | (A[0]&C_in) | (B[0]&C_in))) )
        )
    );

// Adding zero operand and zero carry returns the other operand (B zero).
    check_add_zero_identity_Bzero: assert property (
        @(posedge CLK) (B == 4'b0000 && C_in == 1'b0) |-> (S == A && C_out == 1'b0)
    );

// Adding zero operand and zero carry returns the other operand (A zero).
    check_add_zero_identity_Azero: assert property (
        @(posedge CLK) (A == 4'b0000 && C_in == 1'b0) |-> (S == B && C_out == 1'b0)
    );

// All zeros in yields all zeros out.
    check_all_zero_pass_through: assert property (
        @(posedge CLK) (A == 4'b0000 && B == 4'b0000 && C_in == 1'b0) |-> (S == 4'b0000 && C_out == 1'b0)
    );

// Reset low must force count to zero at the clock edge.
    check_reset_low_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

// On a sampled falling edge of reset, count is zero.
    check_fall_of_reset_drives_zero: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'b0000)
    );

// On a sampled rising edge of reset, count becomes one.
    check_rise_of_reset_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0001)
    );

// On a sampled rising edge of reset, previous cycle's count was zero.
    check_prev_zero_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> ($past(count) == 4'b0000)
    );

// When not in reset, count is always within 4-bit range.
    check_count_range_when_active: assert property (
        @(posedge clk) disable iff (~rst) (count inside {[4'h0:4'hF]})
    );

///// Combinational relation /////
    // Q_N is always the bitwise complement of Q.
    check_qn_complement: assert property (
        @(posedge CLK) Q_N == ~Q
    );

// Active-low SET_B forces Q to 1 on the next cycle.
    check_set_forces_one: assert property (
        @(posedge CLK) (SET_B == 1'b0) |=> (Q == 1'b1)
    );

// Active-low SCD forces Q to 0 on the next cycle when SET_B is not active.
    check_clear_forces_zero: assert property (
        @(posedge CLK) (SET_B != 1'b0 && SCD == 1'b0) |=> (Q == 1'b0)
    );

// When both SET_B and SCD are low, set has priority and Q becomes 1.
    check_set_overrides_clear: assert property (
        @(posedge CLK) (SET_B == 1'b0 && SCD == 1'b0) |=> (Q == 1'b1)
    );

// Analysis: No clock/reset in RTL; purely combinational always @(*); out = en ? selected in : 4'b0000.

    // en low forces out to zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) disable iff (1'b0) (!en) |-> (out == 4'b0000)
    );

// When en=1 and sel==00, out equals in0.
    check_sel_00_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b00)) |-> (out == in0)
    );

// When en=1 and sel==01, out equals in1.
    check_sel_01_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b01)) |-> (out == in1)
    );

// When en=1 and sel==10, out equals in2.
    check_sel_10_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b10)) |-> (out == in2)
    );

// When en=1 and sel==11, out equals in3.
    check_sel_11_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b11)) |-> (out == in3)
    );

// Functional equivalence to the mux with enable.
    check_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
            out == (en ? (sel == 2'b00 ? in0 :
                          sel == 2'b01 ? in1 :
                          sel == 2'b10 ? in2 : in3)
                      : 4'b0000)
    );

// During reset, outputs select in0 and anodo pattern 1110.
    reset_outputs_select0: assert property (
        @(posedge clk) rst |-> (anodo == 4'b1110) && (catodo == in0)
    );

// anodo is always one of the four valid active-low one-hot patterns.
    anodo_valid_values: assert property (
        @(posedge clk) disable iff (rst) anodo inside {4'b1110, 4'b1101, 4'b1011, 4'b0111}
    );

// When anodo selects digit0, catodo equals in0.
    map_sel0_cat_from_in0: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b1110) |-> (catodo == in0)
    );

// When anodo selects digit1, catodo equals in1.
    map_sel1_cat_from_in1: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b1101) |-> (catodo == in1)
    );

// When anodo selects digit2, catodo equals in2.
    map_sel2_cat_from_in2: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b1011) |-> (catodo == in2)
    );

// When anodo selects digit3, catodo equals in3.
    map_sel3_cat_from_in3: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b0111) |-> (catodo == in3)
    );

// Exactly one anodo bit is active (low).
    anodo_onehot_active_low: assert property (
        @(posedge clk) disable iff (rst) $onehot(~anodo)
    );

// catodo always equals one of the four input buses.
    catodo_matches_some_input: assert property (
        @(posedge clk) disable iff (rst) (catodo == in0) || (catodo == in1) || (catodo == in2) || (catodo == in3)
    );

// If anodo selects digit1 and both anodo and in1 are stable, catodo is stable.
    stable_catodo_when_sel1_stable: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b1101 && $stable(anodo) && $stable(in1)) |-> $stable(catodo)
    );

// If anodo selects digit2 and both anodo and in2 are stable, catodo is stable.
    stable_catodo_when_sel2_stable: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b1011 && $stable(anodo) && $stable(in2)) |-> $stable(catodo)
    );

// If anodo selects digit3 and both anodo and in3 are stable, catodo is stable.
    stable_catodo_when_sel3_stable: assert property (
        @(posedge clk) disable iff (rst) (anodo == 4'b0111 && $stable(anodo) && $stable(in3)) |-> $stable(catodo)
    );

// Reset drives count to zero in the same cycle.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 8'h00)
    );

// When sel==00, output equals data_in[0].
  check_sel_00_map: assert property (
    @(posedge clk) (sel == 2'b00) |-> (data_out == data_in[0])
  );

// When sel==01, output equals data_in[1].
  check_sel_01_map: assert property (
    @(posedge clk) (sel == 2'b01) |-> (data_out == data_in[1])
  );

// When sel==10, output equals data_in[2].
  check_sel_10_map: assert property (
    @(posedge clk) (sel == 2'b10) |-> (data_out == data_in[2])
  );

// When sel==11, output equals data_in[3].
  check_sel_11_map: assert property (
    @(posedge clk) (sel == 2'b11) |-> (data_out == data_in[3])
  );

// If sel is unknown (X/Z), default branch drives 0.
  check_default_on_unknown_sel: assert property (
    @(posedge clk) $isunknown(sel) |-> (data_out == 1'b0)
  );

// Functional equivalence of mux select expression.
  check_functional_equivalence: assert property (
    @(posedge clk) data_out ==
      (sel[1] ? (sel[0] ? data_in[3] : data_in[2])
              : (sel[0] ? data_in[1] : data_in[0]))
  );

// Reset low drives q=0, q_bar=1 on next cycle.
    check_reset_forces_outputs: assert property (
        @(posedge clk) (reset == 1'b0) |=> (q == 1'b0 && q_bar == 1'b1)
    );

// Set low (with reset high) drives q=1, q_bar=0 on next cycle.
    check_set_forces_outputs: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            (set == 1'b0) |=> (q == 1'b1 && q_bar == 1'b0)
    );

// With reset and set both high, capture d into q and ~d into q_bar on next cycle.
    check_data_capture: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            (set == 1'b1) |=> (q == $past(d) && q_bar == ~$past(d))
    );

// If set is held low with reset high across consecutive cycles, outputs stay q=1, q_bar=0.
    check_hold_under_set: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) == 1'b1 && reset == 1'b1 && $past(set) == 1'b0 && set == 1'b0) |-> (q == 1'b1 && q_bar == 1'b0)
    );

// If both reset and set remain high across cycles, outputs reflect prior d each cycle.
    check_hold_under_normal: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) == 1'b1 && reset == 1'b1 && $past(set) == 1'b1 && set == 1'b1) |-> (q == $past(d) && q_bar == ~$past(d))
    );

// Reset has priority over set when both are low.
    check_reset_priority_over_set: assert property (
        @(posedge clk) (reset == 1'b0 && set == 1'b0) |=> (q == 1'b0 && q_bar == 1'b1)
    );

// In normal mode, if d differs from previous q, q toggles next cycle.
    check_data_change_causes_q_toggle: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            (set == 1'b1 && d != $past(q)) |=> (q != $past(q))
    );

// In normal mode, if d equals previous q, q holds next cycle.
    check_data_same_keeps_q: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            (set == 1'b1 && d == $past(q)) |=> (q == $past(q))
    );

// Z equals the logical AND of A, B, C, and D.
    check_z_equals_and4: assert property (
        @(posedge CLK) Z == (A & B & C & D)
    );

// When all inputs are HIGH, Z must be HIGH.
    check_all_high_implies_z_high: assert property (
        @(posedge CLK) (A && B && C && D) |-> Z
    );

// If any input is LOW, Z must be LOW.
    check_any_low_implies_z_low: assert property (
        @(posedge CLK) (!A || !B || !C || !D) |-> !Z
    );

// Z can only rise when all inputs are HIGH.
    check_z_rise_requires_all_high: assert property (
        @(posedge CLK) $rose(Z) |-> (A && B && C && D)
    );

// Z can only fall when at least one input is LOW.
    check_z_fall_requires_any_low: assert property (
        @(posedge CLK) $fell(Z) |-> (!A || !B || !C || !D)
    );

// X equals A^B^C when A rises.
    check_parity_posA: assert property (
        @(posedge A) X == (A ^ B ^ C)
    );

// X equals A^B^C when A falls.
    check_parity_negA: assert property (
        @(negedge A) X == (A ^ B ^ C)
    );

// X equals A^B^C when B rises.
    check_parity_posB: assert property (
        @(posedge B) X == (A ^ B ^ C)
    );

// X equals A^B^C when B falls.
    check_parity_negB: assert property (
        @(negedge B) X == (A ^ B ^ C)
    );

// X equals A^B^C when C rises.
    check_parity_posC: assert property (
        @(posedge C) X == (A ^ B ^ C)
    );

// X equals A^B^C when C falls.
    check_parity_negC: assert property (
        @(negedge C) X == (A ^ B ^ C)
    );

// X equals A^B^C when X rises.
    check_parity_posX: assert property (
        @(posedge X) X == (A ^ B ^ C)
    );

// X equals A^B^C when X falls.
    check_parity_negX: assert property (
        @(negedge X) X == (A ^ B ^ C)
    );

// gray[0] must equal binary[0] XOR binary[1].
    check_gray0_is_b0_xor_b1: assert property (
        @(posedge clk) gray[0] == (binary[0] ^ binary[1])
    );

// gray[1] must equal binary[1] XOR binary[2].
    check_gray1_is_b1_xor_b2: assert property (
        @(posedge clk) gray[1] == (binary[1] ^ binary[2])
    );

// Vector equivalence for gray encoding.
    check_gray_vector_equiv: assert property (
        @(posedge clk) gray == {binary[1] ^ binary[2], binary[0] ^ binary[1]}
    );

// Parity relation implied by definitions: gray[0]^gray[1] == binary[0]^binary[2].
    check_parity_relation: assert property (
        @(posedge clk) (gray[0] ^ gray[1]) == (binary[0] ^ binary[2])
    );

// Reset drives outputs to known values.
    reset_values: assert property (
        @(posedge clk) reset |-> (data_out == 32'd0) && (ecc_out == 7'd0) && (tag_out == 1'b0) &&
                                 (valid_out == 1'b0) && (control_tag_out == 1'b0) &&
                                 (error_out == 1'b0) && (dequeue_out == 1'b0) &&
                                 (por_req_out == 1'b1)
    );

// On D0 rising, S must equal the mux function.
    check_mux_on_d0_rise: assert property (
        @(posedge D0) S == (ctrl ? D1 : D0)
    );

// On D0 falling, S must equal the mux function.
    check_mux_on_d0_fall: assert property (
        @(posedge !D0) S == (ctrl ? D1 : D0)
    );

// On D1 rising, S must equal the mux function.
    check_mux_on_d1_rise: assert property (
        @(posedge D1) S == (ctrl ? D1 : D0)
    );

// On D1 falling, S must equal the mux function.
    check_mux_on_d1_fall: assert property (
        @(posedge !D1) S == (ctrl ? D1 : D0)
    );

// On S rising, S must equal the mux function.
    check_mux_on_s_rise: assert property (
        @(posedge S) S == (ctrl ? D1 : D0)
    );

// On S falling, S must equal the mux function.
    check_mux_on_s_fall: assert property (
        @(posedge !S) S == (ctrl ? D1 : D0)
    );

///// Counter behavior /////
    // On a reset cycle, count becomes 0 on the next clock.
    reset_clears_count_next: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// While reset is held for multiple cycles, count stays 0.
    count_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'h0)
    );

// Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// Combinational 3-input NAND with buffer: Y = ~(A & B & C). No clock/reset in RTL; use external CLK/RESETn.

    // Y matches 3-input NAND truth function.
    check_nand_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ~(A & B & C)
    );

// If A is 0, Y must be 1.
    check_y_high_when_A0: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == 1'b0) |-> (Y == 1'b1)
    );

// If B is 0, Y must be 1.
    check_y_high_when_B0: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 1'b0) |-> (Y == 1'b1)
    );

// If C is 0, Y must be 1.
    check_y_high_when_C0: assert property (
        @(posedge CLK) disable iff (!RESETn) (C == 1'b0) |-> (Y == 1'b1)
    );

// If all inputs are 1, Y must be 0.
    check_y_low_when_all1: assert property (
        @(posedge CLK) disable iff (!RESETn) (A && B && C) |-> (Y == 1'b0)
    );

// Y can be 0 only when all inputs are 1.
    check_y_zero_only_if_all1: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> (A && B && C)
    );

// A falling edge on Y implies all inputs are 1 this cycle.
    check_y_fall_implies_all1: assert property (
        @(posedge CLK) disable iff (!RESETn) $fell(Y) |-> (A && B && C)
    );

// A rising edge on Y implies at least one input is 0 this cycle.
    check_y_rise_implies_any0: assert property (
        @(posedge CLK) disable iff (!RESETn) $rose(Y) |-> ((A == 1'b0) || (B == 1'b0) || (C == 1'b0))
    );

// Reset drives q and carry LOW when rst is HIGH at the clock edge.
  check_reset_outputs: assert property (
    @(posedge clk) rst |-> (q == 4'b0000) && (carry == 1'b0)
  );

// No spurious carry when last q was mid-range (1..14).
  check_no_carry_midrange: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && ($past(q) != 4'd0) && ($past(q) != 4'hF))
      |-> (carry == 1'b0)
  );

// Y implements a 2:1 mux selecting B1 when C1=1 else A2.
    check_y_mux_function: assert property (
        @(posedge clk) Y == (C1 ? B1 : A2)
    );

// Output is 0 when any input is 1.
    check_any_high_forces_y0: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 === 1'b1) || (p2 === 1'b1) || (p3 === 1'b1) || (p4 === 1'b1) || (p5 === 1'b1)) |-> (y === 1'b0)
    );

// Output is 1 when all inputs are 0.
    check_all_low_forces_y1: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 === 1'b0) && (p2 === 1'b0) && (p3 === 1'b0) && (p4 === 1'b0) && (p5 === 1'b0)) |-> (y === 1'b1)
    );

// If y is 0, at least one input must be 1.
    check_y0_implies_some_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (y === 1'b0) |-> ((p1 === 1'b1) || (p2 === 1'b1) || (p3 === 1'b1) || (p4 === 1'b1) || (p5 === 1'b1))
    );

// If y is 1, no input is 1.
    check_y1_implies_no_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (y === 1'b1) |-> ((p1 !== 1'b1) && (p2 !== 1'b1) && (p3 !== 1'b1) && (p4 !== 1'b1) && (p5 !== 1'b1))
    );

// If no input is 1 (including X/Z), output is 1.
    check_no_known_highs_forces_y1: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 !== 1'b1) && (p2 !== 1'b1) && (p3 !== 1'b1) && (p4 !== 1'b1) && (p5 !== 1'b1)) |-> (y === 1'b1)
    );

// y is always a known 0 or 1.
    check_y_is_binary: assert property (
        @(posedge CLK) disable iff (1'b0)
        (y === 1'b0) || (y === 1'b1)
    );

// A falling y requires at least one input to be 1.
    check_y_fall_requires_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        $fell(y) |-> ((p1 === 1'b1) || (p2 === 1'b1) || (p3 === 1'b1) || (p4 === 1'b1) || (p5 === 1'b1))
    );

// A rising y requires no input to be 1.
    check_y_rise_requires_no_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        $rose(y) |-> ((p1 !== 1'b1) && (p2 !== 1'b1) && (p3 !== 1'b1) && (p4 !== 1'b1) && (p5 !== 1'b1))
    );

// With all inputs known 0/1, y equals logical NOR of inputs.
    check_boolean_equivalence_when_inputs_known: assert property (
        @(posedge CLK) disable iff (1'b0)
        ((p1 === 1'b0 || p1 === 1'b1) &&
         (p2 === 1'b0 || p2 === 1'b1) &&
         (p3 === 1'b0 || p3 === 1'b1) &&
         (p4 === 1'b0 || p4 === 1'b1) &&
         (p5 === 1'b0 || p5 === 1'b1)) |-> (y === !(p1 || p2 || p3 || p4 || p5))
    );

// Full 5-bit sum must equal zero-extended A+B+Cin.
    check_sum_matches_arithmetic: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0, Cin})
    );

// Bit0 sum is XOR of A[0], B[0], and Cin.
    check_sum_bit0_xor: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit1 sum equals XOR with carry from bit0.
    check_sum_bit1_xor_with_c1: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (A[1] ^ B[1] ^ ( (A[0] & B[0]) | (Cin & (A[0] ^ B[0])) ))
    );

// Bit2 sum equals XOR with carry from bit1.
    check_sum_bit2_xor_with_c2: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (A[2] ^ B[2] ^ (
                    (A[1] & B[1]) |
                    ( ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]) )
                ))
    );

// Bit3 sum equals XOR with carry from bit2.
    check_sum_bit3_xor_with_c3: assert property (
        @(posedge clk) disable iff (1'b0)
        S[3] == (A[3] ^ B[3] ^ (
                    (A[2] & B[2]) |
                    ( ( (A[1] & B[1]) |
                        ( ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]) )
                      ) & (A[2] ^ B[2]) )
                ))
    );

// Carry-out equals ripple-carry chain through all bits.
    check_cout_matches_ripple: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == (
            (A[3] & B[3]) |
            ( (
                (A[2] & B[2]) |
                ( ( (A[1] & B[1]) |
                    ( ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]) )
                  ) & (A[2] ^ B[2]) )
              ) & (A[3] ^ B[3]) )
        )
    );

// 0 + 0 + 0 -> S=0, Cout=0.
    check_zero_plus_zero_no_carry: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b0)) |-> ((S == 4'b0000) && (Cout == 1'b0))
    );

// 0 + 0 + 1 -> S=1, Cout=0.
    check_zero_plus_zero_with_cin: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'b0000) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0001) && (Cout == 1'b0))
    );

// A + ~A + 0 -> S=4'hF, Cout=0.
    check_complement_no_cin_saturates: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B == ~A) && (Cin == 1'b0)) |-> ((S == 4'hF) && (Cout == 1'b0))
    );

// A + ~A + 1 -> S=0, Cout=1.
    check_complement_with_cin_wraps: assert property (
        @(posedge clk) disable iff (1'b0)
        ((B == ~A) && (Cin == 1'b1)) |-> ((S == 4'h0) && (Cout == 1'b1))
    );

// When sel=1, out equals in1.
    check_sel1_routes_in1: assert property (
        @(posedge clk) sel |-> (out == in1)
    );

// When sel=0, out equals in0.
    check_sel0_routes_in0: assert property (
        @(posedge clk) !sel |-> (out == in0)
    );

// If inputs are equal, out equals that value regardless of sel.
    check_equal_inputs_bypass: assert property (
        @(posedge clk) (in0 == in1) |-> (out == in0)
    );

// If inputs differ and out equals in0, sel must be 0.
    check_out_eq_in0_implies_sel0: assert property (
        @(posedge clk) (in0 != in1) && (out == in0) |-> (!sel)
    );

// If inputs differ and out equals in1, sel must be 1.
    check_out_eq_in1_implies_sel1: assert property (
        @(posedge clk) (in0 != in1) && (out == in1) |-> (sel)
    );

// Y must be the inverse of A when A rises.
    check_inversion_at_A_rise: assert property (
        @(posedge A) (Y === ~A)
    );

// Y must be the inverse of A when A falls.
    check_inversion_at_A_fall: assert property (
        @(negedge A) (Y === ~A)
    );

// A must be the inverse of Y when Y rises.
    check_input_inverse_at_Y_rise: assert property (
        @(posedge Y) (A === ~Y)
    );

// A must be the inverse of Y when Y falls.
    check_input_inverse_at_Y_fall: assert property (
        @(negedge Y) (A === ~Y)
    );

// out pulses are single-cycle.
    check_out_single_cycle: assert property (
        @(posedge clk) disable iff (reset) out |=> !out
    );

// There are at least three low cycles of out between pulses.
    check_out_min_gap_3: assert property (
        @(posedge clk) disable iff (reset) out |=> !out[*3]
    );

// If WAIT is 0, wait_random must be 0 when active.
    wait_random_low_when_WAIT_low: assert property (
        @(posedge clk) disable iff (!nreset) (WAIT == 1'b0) |-> (wait_random == 1'b0)
    );

// Y matches the boolean function encoded in the RTL.
    check_function_equivalence: assert property (
        @(posedge VPWR) Y == ((A1 && A2) || ((!A1) && (!A2) && (!B1_N)))
    );

// When both A1 and A2 are HIGH, Y is HIGH.
    check_both_high_sets_y: assert property (
        @(posedge VPWR) (A1 && A2) |-> (Y == 1'b1)
    );

// When exactly one of A1/A2 is HIGH, Y is LOW.
    check_one_hot_clears_y: assert property (
        @(posedge VPWR) (A1 ^ A2) |-> (Y == 1'b0)
    );

// When both A1 and A2 are LOW and B1_N is LOW, Y is HIGH.
    check_both_low_b1n_low_sets_y: assert property (
        @(posedge VPWR) (!A1 && !A2 && !B1_N) |-> (Y == 1'b1)
    );

// When both A1 and A2 are LOW and B1_N is HIGH, Y is LOW.
    check_both_low_b1n_high_clears_y: assert property (
        @(posedge VPWR) (!A1 && !A2 && B1_N) |-> (Y == 1'b0)
    );

// With B1_N HIGH, Y equals A1 AND A2.
    check_b1n_high_reduces_to_and: assert property (
        @(posedge VPWR) (B1_N == 1'b1) |-> (Y == (A1 && A2))
    );

// With B1_N LOW, Y equals XNOR of A1 and A2.
    check_b1n_low_reduces_to_xnor: assert property (
        @(posedge VPWR) (B1_N == 1'b0) |-> (Y == ~(A1 ^ A2))
    );

// Y can be HIGH only for the allowed input combinations.
    check_y_high_implies_valid_inputs: assert property (
        @(posedge VPWR) (Y == 1'b1) |-> ((A1 && A2) || (!A1 && !A2 && !B1_N))
    );

///// Reset behavior /////
    // While reset is asserted low, count and overflow are held at 0.
    reset_outputs_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 2'b00) && (overflow == 1'b0)
    );

///// State transitions /////
    // From 00, next is 01 with no overflow.
    trans_00_to_01: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b00) |=> ((count == 2'b01) && (overflow == 1'b0))
    );

// From 01, next is 10 with no overflow.
    trans_01_to_10: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b01) |=> ((count == 2'b10) && (overflow == 1'b0))
    );

// From 10, next is 11 with no overflow.
    trans_10_to_11: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b10) |=> ((count == 2'b11) && (overflow == 1'b0))
    );

// From 11, next is 00 and overflow asserted.
    trans_11_to_00_overflow: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b11) |=> ((count == 2'b00) && (overflow == 1'b1))
    );

///// Overflow semantics /////
    // Overflow high implies current count is 00.
    overflow_implies_zero: assert property (
        @(posedge clk) disable iff (!rst) overflow |-> (count == 2'b00)
    );

// When count is nonzero, overflow must be 0.
    no_overflow_when_count_nonzero: assert property (
        @(posedge clk) disable iff (!rst) (count != 2'b00) |-> (overflow == 1'b0)
    );

// Overflow is a single-cycle pulse.
    overflow_single_cycle: assert property (
        @(posedge clk) disable iff (!rst) overflow |=> !overflow
    );

///// Reset release /////
    // On reset deassertion, hold 00/0 then increment to 01/0.
    post_reset_first_step: assert property (
        @(posedge clk) $rose(rst) |-> ((count == 2'b00) && (overflow == 1'b0)) ##1 ((count == 2'b01) && (overflow == 1'b0))
    );

///// Multi-step progression /////
    // After wrap (11->00/overflow), next step is 01 with overflow low.
    wrap_two_step_progress: assert property (
        @(posedge clk) disable iff (!rst) (count == 2'b11) |=> ((count == 2'b00) && (overflow == 1'b1)) ##1 ((count == 2'b01) && (overflow == 1'b0))
    );

// On A rising edge, output must be inversion of A.
    check_Y_eq_notA_on_A_rise: assert property (
        @(posedge A) (Y === ~A)
    );

// On A falling edge, output must be inversion of A.
    check_Y_eq_notA_on_A_fall: assert property (
        @(negedge A) (Y === ~A)
    );

// On Y rising edge, input must be inversion of Y.
    check_A_eq_notY_on_Y_rise: assert property (
        @(posedge Y) (A === ~Y)
    );

// On Y falling edge, input must be inversion of Y.
    check_A_eq_notY_on_Y_fall: assert property (
        @(negedge Y) (A === ~Y)
    );

// When disabled, output must be all zeros.
    check_disabled_forces_zero: assert property (
        @(posedge clk) !enable |-> (decoder_out == 16'h0000)
    );

// When enabled, output must equal 1 << binary_in.
    check_enabled_exact_decode: assert property (
        @(posedge clk) enable |-> (decoder_out == (16'h0001 << binary_in))
    );

// When enabled, output must be strictly one-hot.
    check_onehot_when_enabled: assert property (
        @(posedge clk) enable |-> $onehot(decoder_out)
    );

// Output is always zero or one-hot.
    check_onehot0_always: assert property (
        @(posedge clk) $onehot0(decoder_out)
    );

// OR-reduction of output equals enable.
    check_or_reduce_matches_enable: assert property (
        @(posedge clk) ((|decoder_out) == enable)
    );

// Non-zero output implies enable is HIGH.
    check_nonzero_implies_enabled: assert property (
        @(posedge clk) (decoder_out != 16'h0000) |-> enable
    );

// When enabled, the selected bit by binary_in must be HIGH.
    check_selected_bit_high_when_enabled: assert property (
        @(posedge clk) enable |-> decoder_out[binary_in]
    );

// When enabled, no bits other than the selected one may be set.
    check_no_other_bits_set_when_enabled: assert property (
        @(posedge clk) enable |-> ((decoder_out & ~(16'h0001 << binary_in)) == 16'h0000)
    );

// On reset, next cycle count is zero.
    reset_sets_zero: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// Reset has priority over load when both are high.
    reset_overrides_load: assert property (
        @(posedge clk) (reset && load) |=> (count == 4'd0)
    );

// When load is high (and not in reset), count loads data on the next cycle.
    load_updates_count: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data))
    );

///// Gating with enable /////
    // With enable LOW, data_reg holds its value.
    check_data_reg_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) !enable |=> $stable(data_reg)
    );

// With enable LOW, out holds its value.
    check_out_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) !enable |=> $stable(out)
    );

///// Load behavior /////
    // With enable HIGH, data_reg captures data_in.
    check_data_reg_load_on_enable: assert property (
        @(posedge clk) disable iff (!reset) enable |=> (data_reg == $past(data_in))
    );

///// Muxing behavior for out /////
    // With enable HIGH and sel==1, out captures previous data_reg[0].
    check_out_update_sel1: assert property (
        @(posedge clk) disable iff (!reset) (enable && sel) |=> (out == $past(data_reg[0]))
    );

// With enable HIGH and sel==0, out captures previous data_reg[2].
    check_out_update_sel0: assert property (
        @(posedge clk) disable iff (!reset) (enable && !sel) |=> (out == $past(data_reg[2]))
    );

///// Combinational relations /////
    // sel_inv is always the bitwise inversion of sel.
    check_sel_inv_complement: assert property (
        @(posedge clk) disable iff (!reset) (sel_inv == ~sel)
    );

///// Combinational clock-gating behavior, sampled on CLK posedge /////
    // When enabled and TE low, ENCLK must equal CLK.
    check_pass_through_when_enabled: assert property (
        @(posedge CLK) (EN && !TE) |-> (ENCLK == CLK)
    );

// EN low forces ENCLK low.
    check_en_low_forces_zero: assert property (
        @(posedge CLK) (!EN) |-> (ENCLK == 1'b0)
    );

// TE high forces ENCLK low.
    check_te_high_forces_zero: assert property (
        @(posedge CLK) (TE) |-> (ENCLK == 1'b0)
    );

// ENCLK high implies EN is high.
    check_enclk_high_implies_en: assert property (
        @(posedge CLK) (ENCLK == 1'b1) |-> (EN == 1'b1)
    );

// ENCLK high implies TE is low.
    check_enclk_high_implies_te_low: assert property (
        @(posedge CLK) (ENCLK == 1'b1) |-> (!TE)
    );

// Falling EN forces ENCLK low in the same cycle.
    check_en_fall_clears_enclk: assert property (
        @(posedge CLK) $fell(EN) |-> (ENCLK == 1'b0)
    );

// Rising TE forces ENCLK low in the same cycle.
    check_te_rise_clears_enclk: assert property (
        @(posedge CLK) $rose(TE) |-> (ENCLK == 1'b0)
    );

// If gating is off (EN low or TE high), ENCLK must be low.
    check_gating_off_forces_zero: assert property (
        @(posedge CLK) ((!EN) || TE) |-> (ENCLK == 1'b0)
    );

// X equals A ^ B ^ C when sampled on A rising edge.
    check_x_equals_xor_on_A: assert property (
        @(posedge A) X == (A ^ B ^ C)
    );

// X equals A ^ B ^ C when sampled on B rising edge.
    check_x_equals_xor_on_B: assert property (
        @(posedge B) X == (A ^ B ^ C)
    );

// X equals A ^ B ^ C when sampled on C rising edge.
    check_x_equals_xor_on_C: assert property (
        @(posedge C) X == (A ^ B ^ C)
    );

// If C is 0, output reduces to A ^ B.
    check_c_zero_reduces_to_ab: assert property (
        @(posedge C) (C == 1'b0) |-> (X == (A ^ B))
    );

// If C is 1, output is inversion of A ^ B.
    check_c_one_inverts_ab: assert property (
        @(posedge C) (C == 1'b1) |-> (X == ~(A ^ B))
    );

// Parity relation: X ^ C equals A ^ B.
    check_x_xor_c_equals_a_xor_b: assert property (
        @(posedge C) (X ^ C) == (A ^ B)
    );

// If A equals B, X must equal C.
    check_when_AeqB_then_XeqC: assert property (
        @(posedge A) (A == B) |-> (X == C)
    );

// If A equals C, X must equal B.
    check_when_AeqC_then_XeqB: assert property (
        @(posedge A) (A == C) |-> (X == B)
    );

// If B equals C, X must equal A.
    check_when_BeqC_then_XeqA: assert property (
        @(posedge B) (B == C) |-> (X == A)
    );

///// Combinational mapping invariants from registered IR /////
    // hi16 upper 16 pack must equal {opcode, reg1, reg2}.
    map_hi16_fields: assert property (
        @(posedge clk) {opcode, reg1, reg2} == hi16[31:16]
    );

// hi16 low 16 must be zero.
    hi16_low_zero: assert property (
        @(posedge clk) hi16[15:0] == 16'h0000
    );

// zx16 upper 16 must be zero.
    zx16_upper_zero: assert property (
        @(posedge clk) zx16[31:16] == 16'h0000
    );

// reg3 must match zx16[15:11].
    reg3_matches_zx16_slice: assert property (
        @(posedge clk) reg3 == zx16[15:11]
    );

// sx16 lower 16 equals zx16 lower 16 (both are ir[15:0]).
    sx16_low_matches_zx16_low: assert property (
        @(posedge clk) sx16[15:0] == zx16[15:0]
    );

// sx16 sign extension driven by bit 15 of immediate.
    sx16_sign_extend_from_bit15: assert property (
        @(posedge clk) sx16[31:16] == {16{zx16[15]}}
    );

// sx16s2 low two bits must be zero.
    sx16s2_low_two_zero: assert property (
        @(posedge clk) sx16s2[1:0] == 2'b00
    );

// sx16s2 middle [17:2] echoes immediate bits.
    sx16s2_mid_matches_lowimm: assert property (
        @(posedge clk) sx16s2[17:2] == zx16[15:0]
    );

// sx16s2 sign extension driven by bit 15 of immediate.
    sx16s2_sign_extend_from_bit15: assert property (
        @(posedge clk) sx16s2[31:18] == {14{zx16[15]}}
    );

// sx26s2 low two bits must be zero.
    sx26s2_low_two_zero: assert property (
        @(posedge clk) sx26s2[1:0] == 2'b00
    );

// sx26s2 sign extension driven by bit 25 (available in hi16[25]).
    sx26s2_sign_extend_from_bit25: assert property (
        @(posedge clk) sx26s2[31:28] == {4{hi16[25]}}
    );

// sx26s2 middle [27:2] equals concatenation of fields {ir[25:16], ir[15:11], ir[10:0]}.
    sx26s2_middle_matches_26imm: assert property (
        @(posedge clk) sx26s2[27:2] == {hi16[25:16], reg3, zx16[10:0]}
    );

///// Register write behavior on ir_we /////
    // On write, next-cycle {opcode,reg1,reg2} equals past instr[31:16].
    update_fields_on_ir_we: assert property (
        @(posedge clk) ir_we |=> {opcode, reg1, reg2} == $past(instr[31:16])
    );

// On write, next-cycle reg3 equals past instr[15:11].
    update_reg3_on_ir_we: assert property (
        @(posedge clk) ir_we |=> reg3 == $past(instr[15:11])
    );

// On write, next-cycle zx16 equals zero-extended past instr[15:0].
    update_zx16_on_ir_we: assert property (
        @(posedge clk) ir_we |=> zx16 == {16'h0000, $past(instr[15:0])}
    );

// On write, next-cycle hi16 equals {past instr[31:16], 16'h0000}.
    update_hi16_on_ir_we: assert property (
        @(posedge clk) ir_we |=> hi16 == {$past(instr[31:16]), 16'h0000}
    );

// On write, next-cycle sx16 equals sign-extended past instr[15:0].
    update_sx16_on_ir_we: assert property (
        @(posedge clk) ir_we |=> sx16 == {{16{$past(instr[15])}}, $past(instr[15:0])}
    );

// On write, next-cycle sx16s2 equals sign-extended then <<2 of past instr[15:0].
    update_sx16s2_on_ir_we: assert property (
        @(posedge clk) ir_we |=> sx16s2 == {{14{$past(instr[15])}}, $past(instr[15:0]), 2'b00}
    );

// On write, next-cycle sx26s2 equals sign-extended then <<2 of past instr[25:0].
    update_sx26s2_on_ir_we: assert property (
        @(posedge clk) ir_we |=> sx26s2 == {{4{$past(instr[25])}}, $past(instr[25:0]), 2'b00}
    );

// out1 lower 16 bits equal in1 & in2.
    check_out1_lower_and: assert property (
        @(posedge CLK) out1[15:0] == (in1 & in2)
    );

// out1 upper 16 bits are zero.
    check_out1_upper_zero: assert property (
        @(posedge CLK) out1[31:16] == 16'h0000
    );

// out2 lower 16 bits equal in1 | in2.
    check_out2_lower_or: assert property (
        @(posedge CLK) out2[15:0] == (in1 | in2)
    );

// out2 upper 16 bits are zero.
    check_out2_upper_zero: assert property (
        @(posedge CLK) out2[31:16] == 16'h0000
    );

// AND result is subset of OR result on lower bits.
    check_and_subset_or_lower: assert property (
        @(posedge CLK) (out1[15:0] & ~out2[15:0]) == 16'h0000
    );

// (out1 | out2) equals out2.
    check_or_absorption: assert property (
        @(posedge CLK) (out1 | out2) == out2
    );

// (out1 & out2) equals out1.
    check_and_absorption: assert property (
        @(posedge CLK) (out1 & out2) == out1
    );

// (out1 ^ out2) lower equals in1 ^ in2.
    check_xor_identity_lower: assert property (
        @(posedge CLK) (out1[15:0] ^ out2[15:0]) == (in1 ^ in2)
    );

///// Functional mapping /////
    // flash_sector equals the combinational mapping function of sector.
    check_mapping_function_equivalence: assert property (
        @(posedge CLK)
        flash_sector == (
            (sector == 3'd1) ? SECTOR1_MAP :
            (sector == 3'd2) ? SECTOR2_MAP :
            (sector == 3'd3) ? SECTOR3_MAP :
            (sector == 3'd4) ? SECTOR4_MAP :
            (sector == 3'd5) ? SECTOR5_MAP :
            3'b000
        )
    );

// Sector 1 maps to SECTOR1_MAP.
    check_map_sector1: assert property (
        @(posedge CLK) (sector == 3'd1) |-> (flash_sector == SECTOR1_MAP)
    );

// Sector 2 maps to SECTOR2_MAP.
    check_map_sector2: assert property (
        @(posedge CLK) (sector == 3'd2) |-> (flash_sector == SECTOR2_MAP)
    );

// Sector 3 maps to SECTOR3_MAP.
    check_map_sector3: assert property (
        @(posedge CLK) (sector == 3'd3) |-> (flash_sector == SECTOR3_MAP)
    );

// Sector 4 maps to SECTOR4_MAP.
    check_map_sector4: assert property (
        @(posedge CLK) (sector == 3'd4) |-> (flash_sector == SECTOR4_MAP)
    );

// Sector 5 maps to SECTOR5_MAP.
    check_map_sector5: assert property (
        @(posedge CLK) (sector == 3'd5) |-> (flash_sector == SECTOR5_MAP)
    );

// Invalid sector 0 maps to 3'b000.
    check_invalid_sector_0: assert property (
        @(posedge CLK) (sector == 3'd0) |-> (flash_sector == 3'b000)
    );

// Invalid sector 6 maps to 3'b000.
    check_invalid_sector_6: assert property (
        @(posedge CLK) (sector == 3'd6) |-> (flash_sector == 3'b000)
    );

// Invalid sector 7 maps to 3'b000.
    check_invalid_sector_7: assert property (
        @(posedge CLK) (sector == 3'd7) |-> (flash_sector == 3'b000)
    );

// flash_sector is always one of the defined map values or 3'b000.
    check_output_membership: assert property (
        @(posedge CLK) flash_sector inside {SECTOR1_MAP, SECTOR2_MAP, SECTOR3_MAP, SECTOR4_MAP, SECTOR5_MAP, 3'b000}
    );

// Count is cleared to 0 whenever rst_n is LOW (synchronous reset).
    reset_clears_count: assert property (
        @(posedge clk) !rst_n |-> (count == 16'h0000)
    );

// While reset remains asserted across cycles, count stays 0.
    check_hold_zero_while_in_reset: assert property (
        @(posedge clk) ($past(!rst_n) && !rst_n) |-> (count == 16'h0000)
    );

// g_out equals p & g_prec[1] & ~g.
    check_functional_equivalence: assert property (
        @(posedge CLK) g_out == (p & g_prec[1] & ~g)
    );

// If g_out is 1 then p must be 1.
    check_g_out_implies_p: assert property (
        @(posedge CLK) g_out |-> p
    );

// If g_out is 1 then g_prec[1] must be 1.
    check_g_out_implies_gprec1: assert property (
        @(posedge CLK) g_out |-> g_prec[1]
    );

// If g_out is 1 then g must be 0.
    check_g_out_implies_not_g: assert property (
        @(posedge CLK) g_out |-> !g
    );

// When p=1, g_prec[1]=1, and g=0, g_out must be 1.
    check_one_if_all_true: assert property (
        @(posedge CLK) (p && g_prec[1] && !g) |-> (g_out == 1'b1)
    );

// On p rising with g_prec[1]=1 and g=0, g_out is 1.
    check_g_out_on_p_rise: assert property (
        @(posedge CLK) ($rose(p) && g_prec[1] && !g) |-> (g_out == 1'b1)
    );

// On g_prec[1] rising with p=1 and g=0, g_out is 1.
    check_g_out_on_gprec1_rise: assert property (
        @(posedge CLK) ($rose(g_prec[1]) && p && !g) |-> (g_out == 1'b1)
    );

// On g rising with p=1 and g_prec[1]=1, g_out is 0.
    check_g_out_on_g_rise: assert property (
        @(posedge CLK) ($rose(g) && p && g_prec[1]) |-> (g_out == 1'b0)
    );

// On g falling with p=1 and g_prec[1]=1, g_out is 1.
    check_g_out_on_g_fall: assert property (
        @(posedge CLK) ($fell(g) && p && g_prec[1]) |-> (g_out == 1'b1)
    );

// On g_prec[1] falling, g_out is 0.
    check_g_out_on_gprec1_fall: assert property (
        @(posedge CLK) $fell(g_prec[1]) |-> (g_out == 1'b0)
    );

///// Combinational equivalence /////
    // p_out equals p_prec AND p.
    check_p_out_equation: assert property (
        @(posedge CLK) p_out == (p_prec & p)
    );

// g_out_BAR equals NOT((g_prec AND p) OR g).
    check_g_out_BAR_equation: assert property (
        @(posedge CLK) g_out_BAR == ~((g_prec & p) | g)
    );

///// Derived implications from logic /////
    // If p is LOW then p_out must be LOW.
    check_p_out_low_if_p_low: assert property (
        @(posedge CLK) (!p) |-> (p_out == 1'b0)
    );

// If p_prec is LOW then p_out must be LOW.
    check_p_out_low_if_p_prec_low: assert property (
        @(posedge CLK) (!p_prec) |-> (p_out == 1'b0)
    );

// If both p and p_prec are HIGH then p_out must be HIGH.
    check_p_out_high_if_both_high: assert property (
        @(posedge CLK) (p && p_prec) |-> (p_out == 1'b1)
    );

// If p_out is HIGH then both p and p_prec are HIGH.
    check_p_out_implies_inputs_high: assert property (
        @(posedge CLK) p_out |-> (p && p_prec)
    );

// If g is HIGH then g_out_BAR must be LOW.
    check_g_out_bar_low_if_g_high: assert property (
        @(posedge CLK) g |-> (g_out_BAR == 1'b0)
    );

// If g_prec AND p are HIGH then g_out_BAR must be LOW.
    check_g_out_bar_low_if_gprec_and_p: assert property (
        @(posedge CLK) (g_prec && p) |-> (g_out_BAR == 1'b0)
    );

// If g is LOW and (g_prec AND p) is LOW then g_out_BAR must be HIGH.
    check_g_out_bar_high_if_both_low: assert property (
        @(posedge CLK) (!g && !(g_prec && p)) |-> (g_out_BAR == 1'b1)
    );

// If g_out_BAR is HIGH then g is LOW and (g_prec AND p) is LOW.
    check_g_out_bar_high_implies_inputs_low: assert property (
        @(posedge CLK) g_out_BAR |-> (!g && !(g_prec && p))
    );

// While reset is asserted, outputs are driven to zero.
  reset_drives_zero: assert property (
    @(posedge clk) rst |-> (count == 4'h0) && (max_reached == 1'b0)
  );

// Flag can only rise when previous count was 15.
  flag_rise_only_on_wrap: assert property (
    @(posedge clk) disable iff (rst)
      $rose(max_reached) |-> ($past(count) == 4'hF)
  );

// When flag is 1, count is 0 in the same cycle.
  flag_implies_zero_count: assert property (
    @(posedge clk) disable iff (rst)
      max_reached |-> (count == 4'h0)
  );

// If count is non-zero, flag must be 0.
  nonzero_count_implies_flag_zero: assert property (
    @(posedge clk) disable iff (rst)
      (count != 4'h0) |-> (max_reached == 1'b0)
  );

// If current count is 15, next cycle wraps to 0 and flag is 1.
  present_max_wraps_next: assert property (
    @(posedge clk) disable iff (rst)
      (count == 4'hF) |-> ##1 (count == 4'h0) && (max_reached == 1'b1)
  );

// Reset drives count to zero on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// If reset is held across consecutive cycles, count is zero in the later cycle.
    reset_held_forces_zero: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (count == 4'b0000)
    );

// With enable LOW (and no reset), count holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count))
    );

// With enable HIGH and direction LOW, count increments by 1 with wrap at 4'hF->4'h0.
    increment_with_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !direction) |=> (
            ($past(count) == 4'hF) ? (count == 4'h0) : (count == $past(count) + 4'd1)
        )
    );

// With enable HIGH and direction HIGH, count decrements by 1 with wrap at 4'h0->4'hF.
    decrement_with_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (enable && direction) |=> (
            ($past(count) == 4'h0) ? (count == 4'hF) : (count == $past(count) - 4'd1)
        )
    );

// When enable is HIGH (and no reset), count must change on the next cycle.
    enabled_changes_count: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count != $past(count))
    );

// Y is always the bitwise inversion of in.
    check_inversion_value: assert property (
        @(posedge clk) (Y === ~in)
    );

// When in is 0, Y must be 1.
    check_in_low_y_high: assert property (
        @(posedge clk) (in == 1'b0) |-> (Y == 1'b1)
    );

// When in is 1, Y must be 0.
    check_in_high_y_low: assert property (
        @(posedge clk) (in == 1'b1) |-> (Y == 1'b0)
    );

// If divisor is 0, remainder must be 0.
  check_div_by_zero_zero: assert property (
    @(posedge clk) disable iff (!reset_n) (divisor == 32'd0) |-> (remainder == 32'd0)
  );

///// Bit[1]/[2]/[3] select behavior on sel[0] edges /////
    // When sel[0] rises, out[1] takes in1[1].
    out1_follows_in1_on_sel0_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(sel[0]) |-> (out[1] == in1[1])
    );

// When sel[0] falls, out[1] takes in0[1].
    out1_follows_in0_on_sel0_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(sel[0]) |-> (out[1] == in0[1])
    );

// When sel[0] rises, out[2] takes in3[2].
    out2_follows_in3_on_sel0_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(sel[0]) |-> (out[2] == in3[2])
    );

// When sel[0] falls, out[2] takes in2[2].
    out2_follows_in2_on_sel0_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(sel[0]) |-> (out[2] == in2[2])
    );

// When sel[0] rises, out[3] takes in1[3].
    out3_follows_in1_on_sel0_rise: assert property (
        @(posedge clk) disable iff (1'b0) $rose(sel[0]) |-> (out[3] == in1[3])
    );

// When sel[0] falls, out[3] takes in0[3].
    out3_follows_in0_on_sel0_fall: assert property (
        @(posedge clk) disable iff (1'b0) $fell(sel[0]) |-> (out[3] == in0[3])
    );

// Functional equivalence: Y = ~(~B1_N | (A1 & A2)).
    check_eq_nor_form: assert property (
        @(posedge CLK) Y == ~( (~B1_N) | (A1 & A2) )
    );

// Functional equivalence (DeMorgan): Y = B1_N & (~A1 | ~A2).
    check_eq_demorgan_form: assert property (
        @(posedge CLK) Y == (B1_N & ((~A1) | (~A2)))
    );

// B1_N LOW forces Y LOW.
    check_b1n_low_forces_y_low: assert property (
        @(posedge CLK) (!B1_N) |-> (Y == 1'b0)
    );

// A1&A2 HIGH forces Y LOW.
    check_and_high_forces_y_low: assert property (
        @(posedge CLK) (A1 && A2) |-> (Y == 1'b0)
    );

// When no AND (A1==0 or A2==0), Y passes B1_N.
    check_passthrough_when_no_and: assert property (
        @(posedge CLK) (!(A1 && A2)) |-> (Y == B1_N)
    );

// If B1_N HIGH and no AND, Y must be HIGH.
    check_high_condition: assert property (
        @(posedge CLK) (B1_N && !(A1 && A2)) |-> (Y == 1'b1)
    );

// Y HIGH implies B1_N HIGH and no AND.
    check_y_high_implies_inputs: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (B1_N && (!A1 || !A2))
    );

// Y LOW implies B1_N LOW or A1&A2 HIGH.
    check_y_low_implies_inputs: assert property (
        @(posedge CLK) (Y == 1'b0) |-> ((!B1_N) || (A1 && A2))
    );

// If B1_N HIGH and Y LOW, then A1&A2 must be HIGH.
    check_b1n_high_y_low_implies_and: assert property (
        @(posedge CLK) (B1_N && (Y == 1'b0)) |-> (A1 && A2)
    );

// Y rising edge only when B1_N HIGH and no AND.
    check_y_rise_condition: assert property (
        @(posedge CLK) $rose(Y) |-> (B1_N && (!A1 || !A2))
    );

// Y falling edge only when B1_N LOW or A1&A2 HIGH.
    check_y_fall_condition: assert property (
        @(posedge CLK) $fell(Y) |-> ((!B1_N) || (A1 && A2))
    );

// Clock: clk (posedge). No reset in RTL.
    // Mixed logic: combinational sel propagation; sequential update of Y on clk.

    // When sel==00, next-cycle Y equals current A.
    y_updates_on_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |=> (Y == $past(A))
    );

// When sel==01, next-cycle Y equals current B.
    y_updates_on_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |=> (Y == $past(B))
    );

// When sel==10, next-cycle Y equals current C.
    y_updates_on_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |=> (Y == $past(C))
    );

// When sel==11, next-cycle Y equals current D.
    y_updates_on_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |=> (Y == $past(D))
    );

// C equals bitwise AND of A and B.
    check_and_functional: assert property (
        @(posedge CLK) disable iff (1'b0) (C == (A & B))
    );

// No C bit can be 1 unless both A and B bits are 1.
    check_no_spurious_ones: assert property (
        @(posedge CLK) disable iff (1'b0) ((C & (~A | ~B)) == 16'h0000)
    );

// All (A & B) 1-bits must appear in C (no missing ones).
    check_no_missing_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (((A & B) & ~C) == 16'h0000)
    );

// If A is all zeros, C is all zeros.
    check_zero_when_A_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 16'h0000) |-> (C == 16'h0000)
    );

// If B is all zeros, C is all zeros.
    check_zero_when_B_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 16'h0000) |-> (C == 16'h0000)
    );

// If A is all ones, C passes B unchanged.
    check_pass_through_when_A_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 16'hFFFF) |-> (C == B)
    );

// If B is all ones, C passes A unchanged.
    check_pass_through_when_B_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 16'hFFFF) |-> (C == A)
    );

// Falling edge on ECK implies at least one input is LOW.
    check_eck_fall_implies_some_low: assert property (
        @(posedge CK) $fell(ECK) |-> ((!E) || (!SE) || (!CK))
    );

///// Mouse channel wiring /////
  // ps2_clk_rx_1 mirrors ps2_mouse_clk_I.
  check_mouse_clk_rx_maps_mouse_clk_I: assert property (
    @(posedge ps2_mouse_clk_I) ps2_clk_rx_1 === ps2_mouse_clk_I
  );

// ps2_d_rx_1 mirrors ps2_mouse_data_I.
  check_mouse_data_rx_maps_mouse_data_I: assert property (
    @(posedge ps2_mouse_clk_I) ps2_d_rx_1 === ps2_mouse_data_I
  );

// ps2_mouse_clk_O is tied LOW.
  check_mouse_clk_o_is_zero: assert property (
    @(posedge ps2_mouse_clk_I) ps2_mouse_clk_O === 1'b0
  );

// ps2_mouse_data_O is tied LOW.
  check_mouse_data_o_is_zero: assert property (
    @(posedge ps2_mouse_clk_I) ps2_mouse_data_O === 1'b0
  );

// ps2_mouse_clk_T is inverse of ps2_clk_tx_1.
  check_mouse_clk_t_is_inv_tx1: assert property (
    @(posedge ps2_mouse_clk_I) ps2_mouse_clk_T === ~ps2_clk_tx_1
  );

// ps2_mouse_data_T is inverse of ps2_d_tx_1.
  check_mouse_data_t_is_inv_tx1: assert property (
    @(posedge ps2_mouse_clk_I) ps2_mouse_data_T === ~ps2_d_tx_1
  );

///// Keyboard channel wiring /////
  // ps2_clk_rx_2 mirrors ps2_keyb_clk_I.
  check_keyb_clk_rx_maps_keyb_clk_I: assert property (
    @(posedge ps2_keyb_clk_I) ps2_clk_rx_2 === ps2_keyb_clk_I
  );

// ps2_d_rx_2 mirrors ps2_keyb_data_I.
  check_keyb_data_rx_maps_keyb_data_I: assert property (
    @(posedge ps2_keyb_clk_I) ps2_d_rx_2 === ps2_keyb_data_I
  );

// ps2_keyb_clk_O is tied LOW.
  check_keyb_clk_o_is_zero: assert property (
    @(posedge ps2_keyb_clk_I) ps2_keyb_clk_O === 1'b0
  );

// ps2_keyb_data_O is tied LOW.
  check_keyb_data_o_is_zero: assert property (
    @(posedge ps2_keyb_clk_I) ps2_keyb_data_O === 1'b0
  );

// ps2_keyb_clk_T is inverse of ps2_clk_tx_2.
  check_keyb_clk_t_is_inv_tx2: assert property (
    @(posedge ps2_keyb_clk_I) ps2_keyb_clk_T === ~ps2_clk_tx_2
  );

// ps2_keyb_data_T is inverse of ps2_d_tx_2.
  check_keyb_data_t_is_inv_tx2: assert property (
    @(posedge ps2_keyb_clk_I) ps2_keyb_data_T === ~ps2_d_tx_2
  );

///// Synchronous clock gate behavior (no reset present) /////
    // If EN and TE are both HIGH, next-cycle ENCLK must be 0.
    check_next_low_when_EN_and_TE: assert property (
        @(posedge CLK) (EN && TE) |=> (ENCLK == 1'b0)
    );

// If EN and TE are not both HIGH, next-cycle ENCLK must be 1.
    check_next_high_when_not_both_high: assert property (
        @(posedge CLK) !(EN && TE) |=> (ENCLK == 1'b1)
    );

// If EN is LOW, next-cycle ENCLK must be 1.
    check_next_high_when_EN_low: assert property (
        @(posedge CLK) (EN == 1'b0) |=> (ENCLK == 1'b1)
    );

// If TE is LOW, next-cycle ENCLK must be 1.
    check_next_high_when_TE_low: assert property (
        @(posedge CLK) (TE == 1'b0) |=> (ENCLK == 1'b1)
    );

// If EN and TE stay HIGH for two cycles, ENCLK remains 0 on the following cycle.
    check_persistent_low_when_both_high: assert property (
        @(posedge CLK) (EN && TE) ##1 (EN && TE) |=> (ENCLK == 1'b0)
    );

// If either EN or TE is LOW for two cycles, ENCLK remains 1 on the following cycle.
    check_persistent_high_when_not_both_high: assert property (
        @(posedge CLK) (!(EN && TE)) ##1 (!(EN && TE)) |=> (ENCLK == 1'b1)
    );

// Clock: C; Active-high reset-like control: R; Combinational: Q = (R?0 : S?1 : D)

    // Reset forces Q to 0 regardless of S or D.
    check_reset_forces_zero: assert property (
        @(posedge C) R |-> (Q == 1'b0)
    );

// When not reset, Q implements priority set/through function (S over D).
    check_function_when_not_reset: assert property (
        @(posedge C) disable iff (R) (Q == (S ? 1'b1 : D))
    );

// When not reset and S is high, Q must be 1 independent of D.
    check_set_when_not_reset: assert property (
        @(posedge C) disable iff (R) S |-> (Q == 1'b1)
    );

// When not reset and S is low, Q must equal D.
    check_pass_through_when_not_reset: assert property (
        @(posedge C) disable iff (R) (!S) |-> (Q == D)
    );

// If both R and S are high, R has priority and Q is 0.
    check_priority_R_over_S: assert property (
        @(posedge C) (R && S) |-> (Q == 1'b0)
    );

// Clock: clk posedge. No reset.
    // Sequential: data updates on en; holds when en==0.
    // Behavior: ROM mapping for addr 0..15; default assigns X.

    // Data holds its value when en is LOW.
    hold_when_en_low: assert property (
        @(posedge clk) !en |=> $stable(data)
    );

// When en is HIGH and addr==0, next data is 0010.
    map_addr_0: assert property (
        @(posedge clk) en && (addr == 5'b00000) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==1, next data is 0010.
    map_addr_1: assert property (
        @(posedge clk) en && (addr == 5'b00001) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==2, next data is 1110.
    map_addr_2: assert property (
        @(posedge clk) en && (addr == 5'b00010) |=> (data == 4'b1110)
    );

// When en is HIGH and addr==3, next data is 0010.
    map_addr_3: assert property (
        @(posedge clk) en && (addr == 5'b00011) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==4, next data is 0100.
    map_addr_4: assert property (
        @(posedge clk) en && (addr == 5'b00100) |=> (data == 4'b0100)
    );

// When en is HIGH and addr==5, next data is 1010.
    map_addr_5: assert property (
        @(posedge clk) en && (addr == 5'b00101) |=> (data == 4'b1010)
    );

// When en is HIGH and addr==6, next data is 1100.
    map_addr_6: assert property (
        @(posedge clk) en && (addr == 5'b00110) |=> (data == 4'b1100)
    );

// When en is HIGH and addr==7, next data is 0000.
    map_addr_7: assert property (
        @(posedge clk) en && (addr == 5'b00111) |=> (data == 4'b0000)
    );

// When en is HIGH and addr==8, next data is 1010.
    map_addr_8: assert property (
        @(posedge clk) en && (addr == 5'b01000) |=> (data == 4'b1010)
    );

// When en is HIGH and addr==9, next data is 0010.
    map_addr_9: assert property (
        @(posedge clk) en && (addr == 5'b01001) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==10, next data is 1110.
    map_addr_10: assert property (
        @(posedge clk) en && (addr == 5'b01010) |=> (data == 4'b1110)
    );

// When en is HIGH and addr==11, next data is 0010.
    map_addr_11: assert property (
        @(posedge clk) en && (addr == 5'b01011) |=> (data == 4'b0010)
    );

// When en is HIGH and addr==12, next data is 0100.
    map_addr_12: assert property (
        @(posedge clk) en && (addr == 5'b01100) |=> (data == 4'b0100)
    );

// When en is HIGH and addr==13, next data is 1010.
    map_addr_13: assert property (
        @(posedge clk) en && (addr == 5'b01101) |=> (data == 4'b1010)
    );

// When en is HIGH and addr==14, next data is 1100.
    map_addr_14: assert property (
        @(posedge clk) en && (addr == 5'b01110) |=> (data == 4'b1100)
    );

// When en is HIGH and addr==15, next data is 0000.
    map_addr_15: assert property (
        @(posedge clk) en && (addr == 5'b01111) |=> (data == 4'b0000)
    );

// For en HIGH and addr in 0..15, next data is not X/Z.
    nonx_when_valid_addr: assert property (
        @(posedge clk) en && (addr[4] == 1'b0) |=> !$isunknown(data)
    );

// When load is non-zero, next count equals zero-extended load value.
    check_load_priority_value: assert property (
        @(posedge clk) (load != 4'd0) |=> (count == {4'b0000, $past(load)})
    );

// When no load and up_down==1, next count increments by 1.
    check_increment_on_up: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b1) |=> (count == $past(count) + 8'd1)
    );

// When no load and up_down==0, next count decrements by 1.
    check_decrement_on_down: assert property (
        @(posedge clk) (load == 4'd0 && up_down == 1'b0) |=> (count == $past(count) - 8'd1)
    );

// On load, upper nibble of next count is zero.
    check_load_upper_nibble_zero: assert property (
        @(posedge clk) (load != 4'd0) |=> (count[7:4] == 4'b0000)
    );

// On load, lower nibble of next count matches load.
    check_load_lower_nibble_matches: assert property (
        @(posedge clk) (load != 4'd0) |=> (count[3:0] == $past(load))
    );

// With no load, next value changes by exactly +/-1 based on up_down.
    check_step_by_one_when_no_load: assert property (
        @(posedge clk) (load == 4'd0) |=> (count == $past(count) + ($past(up_down) ? 8'd1 : 8'hFF))
    );

// Clock: sel_b1 (posedge). No reset.
    // Logic: mixed (sequential shift_reg on sel_b1; outputs are combinational).
    // Behavior: out_vec = { (sel_b2 ? in_vec2[1:0] : in_vec1[1:0]), 1'b1 }; even_parity = 1.

    // even_parity output is constant HIGH.
    check_even_parity_const_high: assert property (
        @(posedge sel_b1) even_parity == 1'b1
    );

// out_vec LSB is always 1.
    check_out_lsb_is_one: assert property (
        @(posedge sel_b1) out_vec[0] == 1'b1
    );

// Upper two bits of out_vec follow the selected input's [1:0].
    check_out_upper_bits_mux_function: assert property (
        @(posedge sel_b1) out_vec[2:1] == (sel_b2 ? in_vec2[1:0] : in_vec1[1:0])
    );

// When sel_b2 is HIGH, out_vec[2:1] equals in_vec2[1:0].
    check_sel_high_path_upper_bits: assert property (
        @(posedge sel_b1) sel_b2 |-> (out_vec[2:1] == in_vec2[1:0])
    );

// When sel_b2 is LOW, out_vec[2:1] equals in_vec1[1:0].
    check_sel_low_path_upper_bits: assert property (
        @(posedge sel_b1) !sel_b2 |-> (out_vec[2:1] == in_vec1[1:0])
    );

// Full out_vec equals concat of selected [1:0] with trailing 1.
    check_out_vec_full_concat: assert property (
        @(posedge sel_b1) out_vec == { (sel_b2 ? in_vec2[1:0] : in_vec1[1:0]), 1'b1 }
    );

///// Reset behavior /////
  // When reset is asserted at a clock edge, count must be 0.
  reset_forces_zero: assert property (
    @(posedge clk) reset |-> (count == 3'd0)
  );

// While reset stays asserted across cycles, count remains 0.
  reset_holds_zero: assert property (
    @(posedge clk) ($past(reset) && reset) |-> (count == 3'd0)
  );

// If previous cycle was up mode at 7, wrap to 0.
  count_up_wrap: assert property (
    @(posedge clk) disable iff (reset)
      ($past(!reset) && $past(up_down) && ($past(count) == 3'd7)) |-> (count == 3'd0)
  );

///// Structural equivalence to instantiated gates /////
    // AB equals A XOR B.
    check_ab_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) AB == (A ^ B)
    );

// CD equals C XOR D.
    check_cd_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) CD == (C ^ D)
    );

// ABCD equals AB XOR CD.
    check_abcd_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) ABCD == (AB ^ CD)
    );

// X is assigned directly from ABCD.
    check_output_assign: assert property (
        @(posedge CLK) disable iff (!RESETn) X == ABCD
    );

///// Functional parity property /////
    // X equals the XOR of A, B, C, and D.
    check_x_equals_xor4: assert property (
        @(posedge CLK) disable iff (!RESETn) X == ((A ^ B) ^ (C ^ D))
    );

// When C==0, output equals A+B (4-bit wraparound).
    compute_add_correct: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == (A + B))
    );

// When C==1, output equals A-B (4-bit wraparound).
    compute_sub_correct: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (A - B))
    );

// If both inputs are zero, output is zero (both modes).
    zero_when_both_zero: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0)) |-> (out == 4'd0)
    );

// In subtraction mode and A==B, output is zero.
    sub_equal_zero: assert property (
        @(posedge clk) (C == 1'b1 && (A == B)) |-> (out == 4'd0)
    );

// In addition mode with B==0, output passes A.
    add_passthrough_b_zero: assert property (
        @(posedge clk) (C == 1'b0 && (B == 4'd0)) |-> (out == A)
    );

// In subtraction mode with B==0, output passes A.
    sub_passthrough_b_zero: assert property (
        @(posedge clk) (C == 1'b1 && (B == 4'd0)) |-> (out == A)
    );

// In addition mode with A==0, output passes B.
    add_passthrough_a_zero: assert property (
        @(posedge clk) (C == 1'b0 && (A == 4'd0)) |-> (out == B)
    );

///// Functional equivalence /////
    // Y reflects strict ascending order A < B < C.
    check_y_definition: assert property (
        @(posedge CLK) Y == ((A < B) && (B < C))
    );

///// Consequences of the definition /////
    // If A >= B, Y must be 0.
    check_y_zero_when_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (Y == 1'b0)
    );

// If B >= C, Y must be 0.
    check_y_zero_when_B_ge_C: assert property (
        @(posedge CLK) (B >= C) |-> (Y == 1'b0)
    );

// If Y is 1, then A < C (implied by A < B and B < C).
    check_transitive_A_lt_C_when_Y_one: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A < C)
    );

// salida_rgb outputs only 000, 001, or 111.
    check_rgb_value_domain: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b000) || (salida_rgb == 3'b001) || (salida_rgb == 3'b111)
    );

// When video_mostrar=1 and entrada=0011 in rect (150..200,100..150), output 111.
    check_video_on_rect1_white: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) &&
        (entrada == 4'b0011) &&
        (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
        (pixel_y >= 10'd100) && (pixel_y <= 10'd150)
        |-> (salida_rgb == 3'b111)
    );

// When video_mostrar=1 and not in rect1 with entrada=0011, output 000.
    check_video_on_else_black: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) &&
        !((entrada == 4'b0011) &&
          (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
          (pixel_y >= 10'd100) && (pixel_y <= 10'd150))
        |-> (salida_rgb == 3'b000)
    );

// When video_mostrar=0 and entrada=0100 in rect (100..200,50..150), output 001.
    check_video_off_rect2_blue: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) &&
        (entrada == 4'b0100) &&
        (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
        (pixel_y >= 10'd50)  && (pixel_y <= 10'd150)
        |-> (salida_rgb == 3'b001)
    );

// When video_mostrar=0 and not in rect2 with entrada=0100, output 000.
    check_video_off_else_black: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) &&
        !((entrada == 4'b0100) &&
          (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
          (pixel_y >= 10'd50)  && (pixel_y <= 10'd150))
        |-> (salida_rgb == 3'b000)
    );

// Output 111 occurs only when video_mostrar=1 with entrada=0011 in rect1.
    check_white_implies_video_on_rect1: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b111)
        |-> (video_mostrar == 1'b1) &&
            (entrada == 4'b0011) &&
            (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
            (pixel_y >= 10'd100) && (pixel_y <= 10'd150)
    );

// Output 001 occurs only when video_mostrar=0 with entrada=0100 in rect2.
    check_blue_implies_video_off_rect2: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b001)
        |-> (video_mostrar == 1'b0) &&
            (entrada == 4'b0100) &&
            (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
            (pixel_y >= 10'd50)  && (pixel_y <= 10'd150)
    );

// When video_mostrar=1, output is either 000 or 111.
    check_video_on_output_domain: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) |-> (salida_rgb == 3'b000) || (salida_rgb == 3'b111)
    );

// When video_mostrar=1, all RGB bits are equal (000 or 111).
    check_video_on_bits_equal: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) |-> (salida_rgb[2] == salida_rgb[1]) && (salida_rgb[1] == salida_rgb[0])
    );

// When video_mostrar=0, upper RGB bits are 0 (outputs 000 or 001).
    check_video_off_upper_bits_zero: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) |-> (salida_rgb[2] == 1'b0) && (salida_rgb[1] == 1'b0)
    );

// Sum equals A^B^C_in on A rising edge.
    check_sum_func_on_A: assert property (
        @(posedge A) Sum == (A ^ B ^ C_in)
    );

// Sum equals A^B^C_in on B rising edge.
    check_sum_func_on_B: assert property (
        @(posedge B) Sum == (A ^ B ^ C_in)
    );

// Sum equals A^B^C_in on C_in rising edge.
    check_sum_func_on_Cin: assert property (
        @(posedge C_in) Sum == (A ^ B ^ C_in)
    );

// C_out equals (A & B) | (C_in & (A ^ B)) on A rising edge.
    check_cout_func_on_A: assert property (
        @(posedge A) C_out == ((A & B) | (C_in & (A ^ B)))
    );

// C_out equals (A & B) | (C_in & (A ^ B)) on B rising edge.
    check_cout_func_on_B: assert property (
        @(posedge B) C_out == ((A & B) | (C_in & (A ^ B)))
    );

// C_out equals (A & B) | (C_in & (A ^ B)) on C_in rising edge.
    check_cout_func_on_Cin: assert property (
        @(posedge C_in) C_out == ((A & B) | (C_in & (A ^ B)))
    );

// {C_out,Sum} equals A+B+C_in on A rising edge.
    check_bin_sum_on_A: assert property (
        @(posedge A) {C_out, Sum} == ({1'b0, A} + {1'b0, B} + {1'b0, C_in})
    );

// {C_out,Sum} equals A+B+C_in on B rising edge.
    check_bin_sum_on_B: assert property (
        @(posedge B) {C_out, Sum} == ({1'b0, A} + {1'b0, B} + {1'b0, C_in})
    );

// {C_out,Sum} equals A+B+C_in on C_in rising edge.
    check_bin_sum_on_Cin: assert property (
        @(posedge C_in) {C_out, Sum} == ({1'b0, A} + {1'b0, B} + {1'b0, C_in})
    );

///// Mux functionality /////
    // When disabled (E=0), Y must be 0.
    check_disabled_forces_zero: assert property (
        @(posedge clk) (E == 1'b0) |-> (Y == 8'h00)
    );

// When E=1 and S=00, Y selects A.
    check_select_00_routes_A: assert property (
        @(posedge clk) (E == 1'b1 && S == 2'b00) |-> (Y == A)
    );

// When E=1 and S=01, Y selects B.
    check_select_01_routes_B: assert property (
        @(posedge clk) (E == 1'b1 && S == 2'b01) |-> (Y == B)
    );

// When E=1 and S=10, Y selects C.
    check_select_10_routes_C: assert property (
        @(posedge clk) (E == 1'b1 && S == 2'b10) |-> (Y == C)
    );

// When E=1 and S=11, Y selects D.
    check_select_11_routes_D: assert property (
        @(posedge clk) (E == 1'b1 && S == 2'b11) |-> (Y == D)
    );

// Y must equal the combinational mux function of E/S/A/B/C/D.
    check_mux_equivalence: assert property (
        @(posedge clk)
            Y == (E ? (S == 2'b00 ? A
                     : S == 2'b01 ? B
                     : S == 2'b10 ? C
                     :               D)
                  : 8'h00)
    );

///// Functional mapping to left shift /////
    // For known shift, out equals in left-shifted by shift.
    check_out_eq_left_shift_when_shift_known: assert property (
        @(posedge CLK) (!$isunknown(shift)) |-> (out == (in << shift))
    );

// Zero shift passes input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

// One-bit shift produces {in[14:0], 1'b0}.
    check_one_shift_behavior: assert property (
        @(posedge CLK) (shift == 4'd1) |-> (out == {in[14:0], 1'b0})
    );

// Max shift (15) produces {in[0], 15'b0}.
    check_max_shift_behavior: assert property (
        @(posedge CLK) (shift == 4'd15) |-> (out == {in[0], 15'b0})
    );

///// Structural bit properties of left shift /////
    // For known positive shift, LSBs are zero-filled.
    check_lsb_zero_fill_mask: assert property (
        @(posedge CLK) (!$isunknown(shift) && (shift > 4'd0)) |-> ((out & ((16'h0001 << shift) - 16'h0001)) == 16'h0000)
    );

// For known shift, right-shifting out by shift restores masked in.
    check_out_right_shift_mask_relation: assert property (
        @(posedge CLK) (!$isunknown(shift)) |-> ((out >> shift) == (in & (16'hFFFF >> shift)))
    );

// For known shift, MSB of out equals in[15 - shift].
    check_msb_maps_from_in: assert property (
        @(posedge CLK) (!$isunknown(shift)) |-> (out[15] == in[15 - shift])
    );

// For known positive shift, LSB is 0.
    check_lsb_zero_when_shift_pos: assert property (
        @(posedge CLK) (!$isunknown(shift) && (shift > 4'd0)) |-> (out[0] == 1'b0)
    );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

check_bit_move: assert property (
                @(posedge CLK) (!$isunknown(shift) && (in[i] === 1'b1) && ((i + shift) <= 4'd15)) |-> (out[i + shift] === 1'b1)
            );

// Clock: clk posedge. Reset: rst synchronous active-high. Counter increments on en, holds otherwise.

  // Reset drives count to 0 on each asserted cycle.
  reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 32'd0)
  );

// If both rst and en are HIGH, reset dominates and count is 0.
  reset_dominates_enable: assert property (
    @(posedge clk) (rst && en) |-> (count == 32'd0)
  );

// During reset, next-cycle output must be zero.
    reset_clears_next: assert property (
        @(posedge clk) (!rst) |=> (out == 4'b0000)
    );

// If reset is held across consecutive cycles, output is zero now.
    reset_held_keeps_zero: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (out == 4'b0000)
    );

// When not in reset in consecutive cycles, output increments by one.
    run_increments_by_one: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (out == $past(out) + 4'd1)
    );

// Wrap from 0xF to 0x0 when running.
    wrap_from_f_to_0: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );

// LSB toggles every running cycle.
    lsb_toggles_when_running: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (out[0] == ~$past(out[0]))
    );

// Output changes every running cycle (no hold).
    out_changes_each_running_cycle: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (out != $past(out))
    );

// On reset release, next-cycle output becomes 1.
    release_next_is_one: assert property (
        @(posedge clk) $rose(rst) |=> (out == 4'd1)
    );

// When running, seeing 0 implies previous was 0xF (wrap property).
    zero_implies_prev_f_when_running: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && (out == 4'd0)) |-> ($past(out) == 4'hF)
    );

// No clock/reset in RTL; combinational AND. Sample on posedge of i_bus1[0].

    // Output equals bitwise AND of inputs (vector-level).
    check_and_vector: assert property (
        @(posedge i_bus1[0]) o_bus == (i_bus1 & i_bus2)
    );

// Output is a subset of i_bus1 (no 1s where i_bus1 has 0s).
    check_output_subset_input1: assert property (
        @(posedge i_bus1[0]) (o_bus & ~i_bus1) == 8'h00
    );

// Output is a subset of i_bus2 (no 1s where i_bus2 has 0s).
    check_output_subset_input2: assert property (
        @(posedge i_bus1[0]) (o_bus & ~i_bus2) == 8'h00
    );

// When i_bus1 is all 1s, o_bus passes through i_bus2.
    check_allones_i_bus1_passthrough: assert property (
        @(posedge i_bus1[0]) (i_bus1 == 8'hFF) |-> (o_bus == i_bus2)
    );

// When i_bus2 is all 1s, o_bus passes through i_bus1.
    check_allones_i_bus2_passthrough: assert property (
        @(posedge i_bus1[0]) (i_bus2 == 8'hFF) |-> (o_bus == i_bus1)
    );

// When i_bus1 is all 0s, o_bus is all 0s.
    check_allzeros_i_bus1_zeroout: assert property (
        @(posedge i_bus1[0]) (i_bus1 == 8'h00) |-> (o_bus == 8'h00)
    );

// When i_bus2 is all 0s, o_bus is all 0s.
    check_allzeros_i_bus2_zeroout: assert property (
        @(posedge i_bus1[0]) (i_bus2 == 8'h00) |-> (o_bus == 8'h00)
    );

// LSB equals AND of corresponding input bits.
    check_bit0_and: assert property (
        @(posedge i_bus1[0]) o_bus[0] == (i_bus1[0] & i_bus2[0])
    );

// MSB equals AND of corresponding input bits.
    check_bit7_and: assert property (
        @(posedge i_bus1[0]) o_bus[7] == (i_bus1[7] & i_bus2[7])
    );

// Output also equals AND with reversed operand order (commutativity).
    check_and_commutative_form: assert property (
        @(posedge i_bus1[0]) o_bus == (i_bus2 & i_bus1)
    );

// Output equals 8-bit sum (zero-extended to 9 bits).
    check_sum_definition: assert property (
        @(posedge clk) disable iff (1'b0) res == (in1 + in2)
    );

// Lower byte matches truncated 8-bit sum.
    check_lower_byte_match: assert property (
        @(posedge clk) disable iff (1'b0) res[7:0] == (in1 + in2)
    );

// Commutativity preserved: swapping operands yields same result.
    check_commutative_sum: assert property (
        @(posedge clk) disable iff (1'b0) res == (in2 + in1)
    );

// Adding zero on in2 returns in1 in the lower byte and zero MSB.
    check_add_zero_in2: assert property (
        @(posedge clk) disable iff (1'b0) (in2 == 8'd0) |-> (res[7:0] == in1 && res[8] == 1'b0)
    );

// Adding zero on in1 returns in2 in the lower byte and zero MSB.
    check_add_zero_in1: assert property (
        @(posedge clk) disable iff (1'b0) (in1 == 8'd0) |-> (res[7:0] == in2 && res[8] == 1'b0)
    );

// LSB equals XOR of input LSBs (no carry-in).
    check_lsb_xor: assert property (
        @(posedge clk) disable iff (1'b0) res[0] == (in1[0] ^ in2[0])
    );

// If reset is LOW at a clock edge, q will be 0 by the next clock.
    check_reset_low_forces_q0_next: assert property (
        @(posedge clk) !reset |-> ##1 (q == 1'b0)
    );

// On the cycle reset deasserts (0->1), q is 0 before the clocked update.
    check_q_zero_on_reset_release_sample: assert property (
        @(posedge clk) $rose(reset) |-> (q == 1'b0)
    );

// After reset deasserts, next cycle q equals d sampled at deassertion.
    check_q_captures_d_after_reset_release: assert property (
        @(posedge clk) $rose(reset) |-> ##1 (q == $past(d))
    );

// When previous cycle was not in reset, q equals previous cycle's d.
    check_q_follows_d_when_prev_reset_high: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (q == $past(d))
    );

// Sum[0] matches XOR of A0,B0,Cin.
    check_sum0_xor: assert property (
        @(posedge CLK) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[2] matches XOR of A2,B2 and carry c2.
    check_sum2_from_c2: assert property (
        @(posedge CLK) Sum[2] == (A[2] ^ B[2] ^ c2_exp)
    );

// Sum[3] matches XOR of A3,B3 and carry c3.
    check_sum3_from_c3: assert property (
        @(posedge CLK) Sum[3] == (A[3] ^ B[3] ^ c3_exp)
    );

// If A3=1 and B3=1 then Cout must be 1.
    check_cout_msb_11: assert property (
        @(posedge CLK) (A[3] == 1'b1 && B[3] == 1'b1) |-> (Cout == 1'b1)
    );

// If A3!=B3 then Cout equals c3 (carry into MSB).
    check_cout_msb_mismatch_equals_c3: assert property (
        @(posedge CLK) (A[3] ^ B[3]) |-> (Cout == c3_exp)
    );

// If A3==B3 then Sum[3] equals c3.
    check_sum3_when_msb_equal: assert property (
        @(posedge CLK) (A[3] == B[3]) |-> (Sum[3] == c3_exp)
    );

// If A3!=B3 then Sum[3] is inverse of c3.
    check_sum3_when_msb_mismatch: assert property (
        @(posedge CLK) (A[3] ^ B[3]) |-> (Sum[3] == ~c3_exp)
    );

// Output equals selected input when select[0] rises.
    check_mapping_on_sel0_rise: assert property (
        @(posedge select[0]) out == data_in[select]
    );

// Output equals selected input when select[1] rises.
    check_mapping_on_sel1_rise: assert property (
        @(posedge select[1]) out == data_in[select]
    );

// Output equals selected input when data_in[0] rises.
    check_mapping_on_data0_rise: assert property (
        @(posedge data_in[0]) out == data_in[select]
    );

// Output equals selected input when data_in[1] rises.
    check_mapping_on_data1_rise: assert property (
        @(posedge data_in[1]) out == data_in[select]
    );

// Output equals selected input when data_in[2] rises.
    check_mapping_on_data2_rise: assert property (
        @(posedge data_in[2]) out == data_in[select]
    );

// Output equals selected input when data_in[3] rises.
    check_mapping_on_data3_rise: assert property (
        @(posedge data_in[3]) out == data_in[select]
    );

// Output equals selected input when out rises.
    check_mapping_on_out_rise: assert property (
        @(posedge out) out == data_in[select]
    );

// When both read addresses are equal, both outputs must match (sampled on write_en rising edge).
    check_equal_outputs_on_we_rise: assert property (
        @(posedge write_en) (addr1 == addr2) |-> (data_out1 == data_out2)
    );

// When both read addresses are equal, both outputs must match (sampled on write_en falling edge).
    check_equal_outputs_on_we_fall: assert property (
        @(negedge write_en) (addr1 == addr2) |-> (data_out1 == data_out2)
    );

// x equals the max of a and b per RTL conditional
    check_output_is_max_expr: assert property (
        @(posedge clk) x == ((a > b) ? a : b)
    );

// When a > b, x must be a
    check_select_a_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (x == a)
    );

// When a <= b, x must be b
    check_select_b_when_a_le_b: assert property (
        @(posedge clk) (a <= b) |-> (x == b)
    );

// On tie (a == b), x selects b
    check_select_b_on_tie: assert property (
        @(posedge clk) (a == b) |-> (x == b)
    );

// x must always equal either a or b
    check_x_equals_a_or_b_only: assert property (
        @(posedge clk) (x == a) || (x == b)
    );

// If x equals b, then a must be less than or equal to b
    check_if_x_is_b_then_a_le_b: assert property (
        @(posedge clk) (x == b) |-> (a <= b)
    );

// x is at least as large as a
    check_x_ge_a: assert property (
        @(posedge clk) (x >= a)
    );

// x is at least as large as b
    check_x_ge_b: assert property (
        @(posedge clk) (x >= b)
    );

// If either input is 4'hF, x must be 4'hF
    check_x_is_F_if_any_F: assert property (
        @(posedge clk) ((a == 4'hF) || (b == 4'hF)) |-> (x == 4'hF)
    );

// If both inputs are zero, x must be zero
    check_x_is_zero_if_both_zero: assert property (
        @(posedge clk) ((a == 4'h0) && (b == 4'h0)) |-> (x == 4'h0)
    );

// clr high forces q to 0 on the next cycle.
    check_clr_forces_zero: assert property (
        @(posedge clk) disable iff (1'b0) clr |=> (q == 1'b0)
    );

// When clr and pr are both high, clear wins and q goes to 0 next cycle.
    check_priority_clr_over_pr: assert property (
        @(posedge clk) disable iff (1'b0) (clr && pr) |=> (q == 1'b0)
    );

// pr high (with clr low) forces q to 1 on the next cycle.
    check_pr_sets_one_when_no_clr: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && pr) |=> (q == 1'b1)
    );

// With ena and no clr/pr, q loads d on the next cycle.
    check_ena_loads_d_when_no_clr_pr: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && ena) |=> (q == $past(d))
    );

// With no clr/pr/ena, q holds its previous value.
    check_hold_when_no_ctrl: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && !ena) |=> (q == $past(q))
    );

// With pr and ena asserted (and clr low), pr has priority and q goes to 1.
    check_priority_pr_over_ena: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && pr && ena) |=> (q == 1'b1)
    );

// When loading a 1 (ena=1, no clr/pr, d=1), q becomes 1 next cycle.
    check_load_one: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && ena && d) |=> (q == 1'b1)
    );

// When loading a 0 (ena=1, no clr/pr, d=0), q becomes 0 next cycle.
    check_load_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!clr && !pr && ena && !d) |=> (q == 1'b0)
    );

// For valid BCD (0..9), output equals zero-extended input.
    check_valid_mapping: assert property (
        @(posedge CLK) (bcd_in <= 4'd9) |-> (bin_out == {4'b0000, bcd_in})
    );

// For invalid BCD (>9), output defaults to zero.
    check_invalid_defaults_to_zero: assert property (
        @(posedge CLK) (bcd_in >= 4'd10) |-> (bin_out == 8'd0)
    );

// Upper nibble of output is always zero.
    check_upper_nibble_zero: assert property (
        @(posedge CLK) bin_out[7:4] == 4'b0000
    );

// Output value is always between 0 and 9.
    check_output_range_0_to_9: assert property (
        @(posedge CLK) bin_out <= 8'd9
    );

// If output is zero, input is either 0 or invalid (>9).
    check_zero_output_input_condition: assert property (
        @(posedge CLK) (bin_out == 8'd0) |-> ((bcd_in == 4'd0) || (bcd_in >= 4'd10))
    );

// For valid inputs, lower nibble equals input value.
    check_lower_nibble_matches_on_valid: assert property (
        @(posedge CLK) (bcd_in <= 4'd9) |-> (bin_out[3:0] == bcd_in)
    );

// For invalid inputs, lower nibble is zero.
    check_lower_nibble_zero_on_invalid: assert property (
        @(posedge CLK) (bcd_in >= 4'd10) |-> (bin_out[3:0] == 4'd0)
    );

///// Functional equivalence /////
    // F equals B^C^D when sampled on A rising edge.
    check_func_on_A_edge: assert property (
        @(posedge A) F == (B ^ C ^ D)
    );

// F equals B^C^D when sampled on B rising edge.
    check_func_on_B_edge: assert property (
        @(posedge B) F == (B ^ C ^ D)
    );

// F equals B^C^D when sampled on C rising edge.
    check_func_on_C_edge: assert property (
        @(posedge C) F == (B ^ C ^ D)
    );

// F equals B^C^D when sampled on D rising edge.
    check_func_on_D_edge: assert property (
        @(posedge D) F == (B ^ C ^ D)
    );

///// Truth table by B,C, D (independent of A) /////
    // For BCD=000, F must be 0.
    truth_table_bcd_000: assert property (
        @(posedge A) ({B,C,D} == 3'b000) |-> (F == 1'b0)
    );

// For BCD=001, F must be 1.
    truth_table_bcd_001: assert property (
        @(posedge A) ({B,C,D} == 3'b001) |-> (F == 1'b1)
    );

// For BCD=010, F must be 1.
    truth_table_bcd_010: assert property (
        @(posedge A) ({B,C,D} == 3'b010) |-> (F == 1'b1)
    );

// For BCD=011, F must be 0.
    truth_table_bcd_011: assert property (
        @(posedge A) ({B,C,D} == 3'b011) |-> (F == 1'b0)
    );

// For BCD=100, F must be 1.
    truth_table_bcd_100: assert property (
        @(posedge A) ({B,C,D} == 3'b100) |-> (F == 1'b1)
    );

// For BCD=101, F must be 0.
    truth_table_bcd_101: assert property (
        @(posedge A) ({B,C,D} == 3'b101) |-> (F == 1'b0)
    );

// For BCD=110, F must be 0.
    truth_table_bcd_110: assert property (
        @(posedge A) ({B,C,D} == 3'b110) |-> (F == 1'b0)
    );

// For BCD=111, F must be 1.
    truth_table_bcd_111: assert property (
        @(posedge A) ({B,C,D} == 3'b111) |-> (F == 1'b1)
    );

// No reset in DUT; assertions are always active (disable iff (1'b0)).
    // DUT is combinational tri-state inverter: TE=1 => Z=~A; TE=0 => Z='z.

    // When enabled, Z equals bitwise inversion of A.
    check_inversion_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1) |-> (Z === ~A)
    );

// When enabled, Z is never high-impedance.
    check_not_z_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1) |-> (Z !== 1'bz)
    );

// When enabled and A=0, Z must be 1.
    check_drive_one_when_A0: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1 && A === 1'b0) |-> (Z === 1'b1)
    );

// When enabled and A=1, Z must be 0.
    check_drive_zero_when_A1: assert property (
        @(posedge clk) disable iff (1'b0) (TE === 1'b1 && A === 1'b1) |-> (Z === 1'b0)
    );

// Upper 16 bits of result match a[31:16] & b[31:16].
    check_upper_half: assert property (
        @(posedge CLK) disable iff (!RESETn)
        result[31:16] == (a[31:16] & b[31:16])
    );

// Y equals (A0 & B0) | ~C0 (LSB function as coded).
    check_y_function: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ((A1A2[0] & B1B2[0]) | (~(C1C2[0])))
    );

// C0=0 forces Y=1 regardless of A0,B0.
    check_c0_low_forces_y1: assert property (
        @(posedge CLK) disable iff (!RESETn) (C1C2[0] == 1'b0) |-> (Y == 1'b1)
    );

// With C0=1, Y reduces to A0 & B0.
    check_c0_high_reduces_to_and: assert property (
        @(posedge CLK) disable iff (!RESETn) (C1C2[0] == 1'b1) |-> (Y == (A1A2[0] & B1B2[0]))
    );

// A0 & B0 = 1 guarantees Y=1.
    check_and1_implies_y1: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A1A2[0] & B1B2[0]) == 1'b1) |-> (Y == 1'b1)
    );

// If C0=1 and A0 & B0 = 0, then Y=0.
    check_c1_and_and0_implies_y0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((C1C2[0] == 1'b1) && ((A1A2[0] & B1B2[0]) == 1'b0)) |-> (Y == 1'b0)
    );

// Y=0 only when C0=1 and A0 & B0 = 0.
    check_y0_only_under_conditions: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> ((C1C2[0] == 1'b1) && ((A1A2[0] & B1B2[0]) == 1'b0))
    );

// Y=1 implies either A0 & B0 = 1 or C0=0.
    check_y1_implies_conditions: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b1) |-> (((A1A2[0] & B1B2[0]) == 1'b1) || (C1C2[0] == 1'b0))
    );

// When A0 & B0 = 0, Y reduces to ~C0.
    check_and0_reduces_to_not_c0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A1A2[0] & B1B2[0]) == 1'b0) |-> (Y == (~(C1C2[0])))
    );

///// Combinational output relationship /////
    // out_if_else reflects whether q and data differ on any bit.
    check_out_matches_neq: assert property (
        @(posedge clk) out_if_else == (q != data)
    );

// out_if_else equals the reduction-OR of q ^ data.
    check_out_matches_xor_or: assert property (
        @(posedge clk) out_if_else == (|(q ^ data))
    );

///// Next-state behavior /////
    // Complete next-state function for q (priority: load over ena!=0).
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> q == (
            $past(load) ? $past(data) :
            (($past(ena) != 2'b00) ? {$past(q[97:0]), $past(q[99:98])} : $past(q))
        )
    );

// When load is asserted, q loads data on the next cycle.
    check_load_updates_from_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

// When load is deasserted and ena!=0, q rotates left by 2 bits.
    check_shift_when_ena_nonzero: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q == {$past(q[97:0]), $past(q[99:98])})
    );

// When load is deasserted and ena==0, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

// Upper bits shift down by 2 when rotating (bits [99:2] from prior [97:0]).
    check_shift_upper_bits: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q[99:2] == $past(q[97:0]))
    );

// Lower bits wrap from prior top two bits when rotating (bits [1:0] from prior [99:98]).
    check_shift_lower_bits: assert property (
        @(posedge clk) (!load && (ena != 2'b00)) |=> (q[1:0] == $past(q[99:98]))
    );

// Clock: clock (posedge). No reset. Sequential 4-bit up-counter with wrap to 0 at 15.

    // When q is 15, next value must be 0.
    check_wrap_on_max: assert property (
        @(posedge clock) (q == 4'hF) |=> (q == 4'h0)
    );

// When q is not 15, next value increments by 1.
    check_increment_when_not_max: assert property (
        @(posedge clock) (q != 4'hF) |=> (q == $past(q) + 4'd1)
    );

// q must change every cycle (no stutter).
    check_no_stutter: assert property (
        @(posedge clock) 1'b1 |=> (q != $past(q))
    );

// LSB toggles every cycle.
    check_lsb_toggles: assert property (
        @(posedge clock) 1'b1 |=> (q[0] != $past(q[0]))
    );

// Bit1 updates with carry from bit0: next q[1] = past q[1] XOR past q[0].
    check_bit1_updates_with_carry: assert property (
        @(posedge clock) 1'b1 |=> (q[1] == ($past(q[1]) ^ $past(q[0])))
    );

// Bit2 updates with carry from bits[1:0]: next q[2] = past q[2] XOR (past q[1] & past q[0]).
    check_bit2_updates_with_carry: assert property (
        @(posedge clock) 1'b1 |=> (q[2] == ($past(q[2]) ^ ($past(q[1]) & $past(q[0]))))
    );

// Bit3 updates with carry from bits[2:0]: next q[3] = past q[3] XOR (past q[2] & past q[1] & past q[0]).
    check_bit3_updates_with_carry: assert property (
        @(posedge clock) 1'b1 |=> (q[3] == ($past(q[3]) ^ ($past(q[2]) & $past(q[1]) & $past(q[0]))))
    );

// After 16 cycles, q returns to its prior value (period 16).
    check_periodicity_16: assert property (
        @(posedge clock) 1'b1 |-> ##16 (q == $past(q,16))
    );

// If q is 0 now, it must have been 15 in the previous cycle.
    check_zero_preceded_by_max: assert property (
        @(posedge clock) 1'b1 |=> ((q == 4'h0) |-> ($past(q) == 4'hF))
    );

// After 2 cycles, q advances by +2 modulo 16.
    check_two_cycle_step: assert property (
        @(posedge clock) 1'b1 |-> ##2 (q == (($past(q,2) + 4'd2) & 4'hF))
    );

// Y must be the bitwise inversion of A at every sample.
    check_y_is_invert_of_a: assert property (
        @(posedge CLK) (Y === ~A)
    );

// Clock: clk (posedge). Logic: combinational mux into a registered 32-bit output.

    // During reset, readdata must be cleared to 0.
    reset_clears_readdata: assert property (
        @(posedge clk) (!reset_n) |-> (readdata == 32'd0)
    );

// After one cycle out of reset, upper 22 bits are always zero (zero-extension).
    upper_bits_zero_postreset: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) |-> (readdata[31:10] == 22'd0)
    );

// When prior address was not 0, the full word must be zero.
    full_word_zero_when_addr_not00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && ($past(address) != 2'b00) |-> (readdata == 32'd0)
    );

// Nonzero LSBs imply prior address selected the port (address==0).
    lsb_nonzero_implies_addr00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && (readdata[9:0] != 10'd0) |-> ($past(address) == 2'b00)
    );

// Clock: clk (posedge). Reset: rst (synchronous, active-high). Logic: sequential up/down counter.

    // Reset drives count to zero on the following clock.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// While reset stays asserted across cycles, count remains zero.
    hold_zero_while_reset: assert property (
        @(posedge clk) rst && $past(rst,1,1'b0) |-> (count == 4'd0)
    );

// With enable=0 (not in reset), count holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!enable) |=> $stable(count)
    );

// With enable=1 (not in reset), count must change on the next cycle.
    change_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (enable) |=> !$stable(count)
    );

///// Reset behavior /////
    // On reset, out must be cleared to 0.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 16'h0000)
    );

// RTL is purely combinational; out implements (~a & ~b), e/w are don't-cares.

    // out must equal (~a & ~b) every cycle.
    check_function_equivalence: assert property (
        @(posedge clk) out == ((~a) & (~b))
    );

// When a=0 and b=0, out must be 1.
    check_out_high_when_a0_b0: assert property (
        @(posedge clk) (!a && !b) |-> (out == 1'b1)
    );

// When a=1 and b=0, out must be 0.
    check_out_low_when_a1_b0: assert property (
        @(posedge clk) (a && !b) |-> (out == 1'b0)
    );

// When a=0 and b=1, out must be 0.
    check_out_low_when_a0_b1: assert property (
        @(posedge clk) (!a && b) |-> (out == 1'b0)
    );

// When a=1 and b=1, out must be 0.
    check_out_low_when_a1_b1: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b0)
    );

// Enumerated case: ~a & ~b & ~e & ~w -> out=1.
    check_case_a0_b0_e0_w0: assert property (
        @(posedge clk) (!a && !b && !e && !w) |-> (out == 1'b1)
    );

// Enumerated case: ~a & ~b & e & w -> out=1.
    check_case_a0_b0_e1_w1: assert property (
        @(posedge clk) (!a && !b && e && w) |-> (out == 1'b1)
    );

// Enumerated case: ~a & b & e & w -> out=0.
    check_case_a0_b1_e1_w1: assert property (
        @(posedge clk) (!a && b && e && w) |-> (out == 1'b0)
    );

// Enumerated case: a & ~b & e & w -> out=0.
    check_case_a1_b0_e1_w1: assert property (
        @(posedge clk) (a && !b && e && w) |-> (out == 1'b0)
    );

// Enumerated case: a & b & e & w -> out=0.
    check_case_a1_b1_e1_w1: assert property (
        @(posedge clk) (a && b && e && w) |-> (out == 1'b0)
    );

// While reset is HIGH, out_vec must be zero.
  reset_clears_outvec: assert property (
    @(posedge clk) reset |-> (out_vec == 32'd0)
  );

// Next-cycle out_vec equals previous in_vec or its 16-bit-swapped version based on previous control.
  deterministic_next_state: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec == ($past(control) ? {$past(in_vec[15:0]), $past(in_vec[31:16])} : $past(in_vec)))
  );

// Next-cycle upper 16 bits reflect previous control selection (swap or passthrough).
  next_upper_half_function: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec[31:16] == ($past(control) ? $past(in_vec[15:0]) : $past(in_vec[31:16])))
  );

// Next-cycle lower 16 bits reflect previous control selection (swap or passthrough).
  next_lower_half_function: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |=> (out_vec[15:0] == ($past(control) ? $past(in_vec[31:16]) : $past(in_vec[15:0])))
  );

// If control is LOW, next-cycle out_vec passes through previous in_vec.
  passthrough_when_control0: assert property (
    @(posedge clk) disable iff (reset)
      (!control) |=> (out_vec == $past(in_vec))
  );

// If control is HIGH, next-cycle out_vec swaps previous in_vec upper/lower 16 bits.
  swap_when_control1: assert property (
    @(posedge clk) disable iff (reset)
      (control) |=> ((out_vec[31:16] == $past(in_vec[15:0])) && (out_vec[15:0] == $past(in_vec[31:16])))
  );

// sel==00 routes a to o.
    check_sel00_routes_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (o === a)
    );

// sel==01 routes b to o.
    check_sel01_routes_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (o === b)
    );

// sel==10 routes c to o.
    check_sel10_routes_c: assert property (
        @(posedge clk) (sel == 2'b10) |-> (o === c)
    );

// sel==11 routes d to o.
    check_sel11_routes_d: assert property (
        @(posedge clk) (sel == 2'b11) |-> (o === d)
    );

// For known sel, o equals the selected input (single-expression form).
    check_function_when_sel_known: assert property (
        @(posedge clk) (!$isunknown(sel)) |-> (o === ((sel==2'b00) ? a :
                                                     (sel==2'b01) ? b :
                                                     (sel==2'b10) ? c : d))
    );

// Mapping for bin=000 -> gray=000
    map_000: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b000)) |-> (gray == 3'b000)
    );

// Mapping for bin=001 -> gray=001
    map_001: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b001)) |-> (gray == 3'b001)
    );

// Mapping for bin=010 -> gray=011
    map_010: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b010)) |-> (gray == 3'b011)
    );

// Mapping for bin=011 -> gray=010
    map_011: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b011)) |-> (gray == 3'b010)
    );

// Mapping for bin=100 -> gray=110
    map_100: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b100)) |-> (gray == 3'b110)
    );

// Mapping for bin=101 -> gray=111
    map_101: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b101)) |-> (gray == 3'b111)
    );

// Mapping for bin=110 -> gray=101
    map_110: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b110)) |-> (gray == 3'b101)
    );

// Mapping for bin=111 -> gray=100
    map_111: assert property (
        @(posedge clk) (!$isunknown(bin) && (bin == 3'b111)) |-> (gray == 3'b100)
    );

// Unknown bin selects default mapping gray=000
    unknown_bin_drives_default_gray: assert property (
        @(posedge clk) $isunknown(bin) |-> (gray == 3'b000)
    );

///// Functional next-state behavior /////
    // Next cycle Q equals (EN ? D : Q) from the previous cycle.
    check_next_state_equation: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ($past(EN) ? $past(D) : $past(Q)))
    );

///// Update behavior /////
    // When EN is 1, Q on the next cycle equals D from this cycle.
    check_update_on_enable: assert property (
        @(posedge CLK) EN |=> (Q == $past(D))
    );

// When EN is 0, Q holds its previous value.
    check_hold_on_disable: assert property (
        @(posedge CLK) !EN |=> (Q == $past(Q))
    );

///// Multi-cycle consistency /////
    // If EN=0 for two consecutive cycles, Q two cycles later equals its value two cycles ago.
    check_two_cycle_hold_when_disabled: assert property (
        @(posedge CLK) !EN ##1 !EN |=> (Q == $past(Q,2))
    );

// If EN=1 for two consecutive cycles, Q two cycles later equals D from one cycle ago.
    check_two_cycle_enable_latest_data: assert property (
        @(posedge CLK) EN ##1 EN |=> (Q == $past(D,1))
    );

// Output is bitwise inversion of input each cycle.
    check_bitwise_inversion: assert property (
        @(posedge clk) disable iff (!reset_n)
        fp_cpx_req_bufp0_cq == ~fp_cpx_req_bufpt_cq_l
    );

// Out XOR In is all ones (complement relation).
    check_xor_all_ones: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufp0_cq ^ fp_cpx_req_bufpt_cq_l) == 8'hFF
    );

// Out OR In is all ones (no bit can be 0 on both).
    check_or_all_ones: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufp0_cq | fp_cpx_req_bufpt_cq_l) == 8'hFF
    );

// Out AND In is all zeros (no bit can be 1 on both).
    check_and_all_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (fp_cpx_req_bufp0_cq & fp_cpx_req_bufpt_cq_l) == 8'h00
    );

// scryptResultAvailable equals (preparing > 0) when sampled on scryptResultAvailableIn rising edge.
    result_flag_matches_prep_on_scryptin_rise: assert property (
        @(posedge scryptResultAvailableIn) (scryptResultAvailable == (preparing > 8'd0))
    );

// scryptResultAvailable equals (preparing > 0) when sampled on scryptResultAvailableIn falling edge.
    result_flag_matches_prep_on_scryptin_fall: assert property (
        @(negedge scryptResultAvailableIn) (scryptResultAvailable == (preparing > 8'd0))
    );

// If scryptResultAvailable rises, preparing must be > 0 at that time.
    result_flag_rise_requires_positive_prep: assert property (
        @(posedge scryptResultAvailable) (preparing > 8'd0)
    );

// If scryptResultAvailable falls, preparing must be 0 at that time.
    result_flag_fall_requires_zero_prep: assert property (
        @(negedge scryptResultAvailable) (preparing == 8'd0)
    );

// Increment and decrement conditions for preparing cannot be true simultaneously.
    inc_dec_conditions_mutex: assert property (
        @(posedge scryptResultAvailableIn)
            !(
                (pipelineReady && scheduleTask && (workCounter == 3'd3) && !decreasePrepare && !doWork) &&
                (!pipelineReady && !scheduleTask && decreasePrepare && !doWork)
            )
    );

// No preparing update condition is true when doWork is HIGH.
    no_update_when_doWork_high: assert property (
        @(posedge scryptResultAvailableIn)
            doWork |-> !(
                (pipelineReady && scheduleTask && (workCounter == 3'd3) && !decreasePrepare && !doWork) ||
                (!pipelineReady && !scheduleTask && decreasePrepare && !doWork)
            )
    );

///// Reset behavior /////
    // While reset is asserted (low), outputs drive c0=0, c1=1, locked=0.
    check_reset_values: assert property (
        @(posedge inclk0) !areset |-> (c0 == 1'b0) && (c1 == 1'b1) && (locked == 1'b0)
    );

///// Locked relation /////
    // locked equals c0 AND NOT c1 every active cycle.
    check_locked_matches_outputs: assert property (
        @(posedge inclk0) disable iff (!areset) locked == (c0 & ~c1)
    );

///// State transitions /////
    // From state 00, next state is 01 and locked=0.
    check_transition_from_00: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b0 && c1 == 1'b0) |=> (c0 == 1'b0 && c1 == 1'b1 && locked == 1'b0)
    );

// From state 01, next state is 11 and locked=0.
    check_transition_from_01: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b0 && c1 == 1'b1) |=> (c0 == 1'b1 && c1 == 1'b1 && locked == 1'b0)
    );

// From state 11, next state is 10 and locked=1.
    check_transition_from_11: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b1 && c1 == 1'b1) |=> (c0 == 1'b1 && c1 == 1'b0 && locked == 1'b1)
    );

// From state 10, next state is 00 and locked=0.
    check_transition_from_10: assert property (
        @(posedge inclk0) disable iff (!areset)
            (c0 == 1'b1 && c1 == 1'b0) |=> (c0 == 1'b0 && c1 == 1'b0 && locked == 1'b0)
    );

///// Locked pulse behavior /////
    // locked cannot stay HIGH for two consecutive cycles.
    check_locked_single_cycle_pulse: assert property (
        @(posedge inclk0) disable iff (!areset) locked |=> !locked
    );

///// Post-reset sequencing /////
    // On the first cycle after reset deasserts, state is 11 with locked=0.
    check_first_cycle_after_reset_deassert: assert property (
        @(posedge inclk0) disable iff (!areset) $rose(areset) |-> (c0 == 1'b1) && (c1 == 1'b1) && (locked == 1'b0)
    );

///// Locked next-state when not in 11 /////
    // If current state is not 11, next locked is 0.
    check_locked_next_zero_when_not_11: assert property (
        @(posedge inclk0) disable iff (!areset)
            !(c0 && c1) |=> (locked == 1'b0)
    );

///// Reset behavior /////
    // If rst is HIGH at a clock edge, count is 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

// While rst remains HIGH across cycles, count stays 0.
    hold_zero_during_reset: assert property (
        @(posedge clk) $past(rst) && rst |-> (count == 4'h0)
    );

///// Counting behavior (out of reset) /////
    // From 15 with rst LOW at both cycles, wrap to 0.
    wrap_from_15_noreset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// From non-15 with rst LOW at both cycles, next count increments or is 0 (async reset may have occurred between edges).
    step_or_zero_noreset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && ($past(count) != 4'hF)) |-> ((count == ($past(count) + 4'h1)) || (count == 4'h0))
    );

// If not wrapping and next value is non-zero, it must be an exact +1 increment.
    strict_step_when_nonzero: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && ($past(count) != 4'hF) && (count != 4'h0)) |-> (count == ($past(count) + 4'h1))
    );

// If current is non-zero out of reset, it must have increased vs. previous sample (no hold/decrement).
    monotonic_increase_noreset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && (count != 4'h0)) |-> (count > $past(count))
    );

// If current is non-zero out of reset, previous sample was not 15 (no non-zero after wrap).
    no_nonzero_after_prev_15: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !rst && (count != 4'h0)) |-> ($past(count) != 4'hF)
    );

// Y is always the logical NOT of A.
    check_inversion: assert property (
        @(posedge CLK) (Y == ~A)
    );

// When A is 0, Y must be 1.
    check_when_a0_y1: assert property (
        @(posedge CLK) (A == 1'b0) |-> (Y == 1'b1)
    );

// When A is 1, Y must be 0.
    check_when_a1_y0: assert property (
        @(posedge CLK) (A == 1'b1) |-> (Y == 1'b0)
    );

// A and Y must never be equal at a sampling edge.
    check_never_equal: assert property (
        @(posedge CLK) (A != Y)
    );

// No explicit clock in RTL; sample on posedge of global_shift_enable.
    // Active-low reset: ctu_tst_pre_grst_l (arst_l is unused).
    // Purely combinational logic; assertions check combinational definitions.

    ///// Direct signal definitions /////
    // se equals global_shift_enable.
    check_se_equals_gse: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) se == global_shift_enable
    );

// testmode_l is inverse of ctu_tst_scanmode.
    check_testmode_l_inverse: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) testmode_l == ~ctu_tst_scanmode
    );

// mem_bypass equals ~ctu_tst_macrotest & ~testmode_l.
    check_mem_bypass_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_bypass == (~ctu_tst_macrotest & ~testmode_l)
    );

// sehold equals ctu_tst_macrotest & ~se.
    check_sehold_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) sehold == (ctu_tst_macrotest & ~se)
    );

// mem_write_disable equals ~ctu_tst_pre_grst_l | se.
    check_mem_write_disable_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_write_disable == (~ctu_tst_pre_grst_l | se)
    );

// mux_drive_disable equals ~ctu_tst_pre_grst_l | short_chain_select | se.
    check_mux_drive_disable_def: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            mux_drive_disable == (~ctu_tst_pre_grst_l |
                                  (ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) |
                                  se)
    );

///// Scan-out mux selection /////
    // so_0 selects between short/long chain based on short_chain_select.
    check_so0_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_0 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_0 : long_chain_so_0)
    );

// so_1 selects between short/long chain based on short_chain_select.
    check_so1_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_1 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_1 : long_chain_so_1)
    );

// so_2 selects between short/long chain based on short_chain_select.
    check_so2_mux: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l)
            so_2 == ((ctu_tst_short_chain & ~testmode_l & ~(ctu_tst_scan_disable & se)) ? short_chain_so_2 : long_chain_so_2)
    );

///// Derived implications (from direct definitions) /////
    // When testmode_l is HIGH, mem_bypass must be LOW.
    check_testmode_blocks_mem_bypass: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) testmode_l |-> (mem_bypass == 1'b0)
    );

// When se is HIGH, sehold must be LOW.
    check_shift_disables_sehold: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) se |-> (sehold == 1'b0)
    );

// mem_write_disable implies mux_drive_disable (mux_disable = memw_disable | short_chain_select).
    check_memw_implies_mux_disable: assert property (
        @(posedge global_shift_enable) disable iff (!ctu_tst_pre_grst_l) mem_write_disable |-> mux_drive_disable
    );

// Q at each cycle equals prior-cycle mux of S/R/D.
    check_state_equation: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (Q == ($past(S) ? 1'b1 : ($past(R) ? 1'b0 : $past(D))))
    );

// S high sets Q to 1 on the next cycle.
    check_set_forces_one: assert property (
        @(posedge CLK) disable iff (1'b0)
        S |=> (Q == 1'b1)
    );

// R high with S low resets Q to 0 on the next cycle.
    check_reset_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!S && R) |=> (Q == 1'b0)
    );

// With S=0 and R=0, Q captures D on the next cycle.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!S && !R) |=> (Q == $past(D))
    );

// When S and R are both high, S has priority and Q becomes 1 next cycle.
    check_set_overrides_reset: assert property (
        @(posedge CLK) disable iff (1'b0)
        (S && R) |=> (Q == 1'b1)
    );

// If idle last cycle (S=R=0) and D matched Q, Q must hold its value.
    check_no_spurious_change_when_idle: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> ((!$past(S) && !$past(R) && ($past(D) == $past(Q))) |-> (Q == $past(Q)))
    );

///// Functional mapping /////
    // Out matches the RTL's conditional mapping exactly.
    check_out_function: assert property (
        @(posedge clk) disable iff (reset)
            out == ((in > 16'h7FFF) ? ((~in) + 16'h1) : in)
    );

// For in <= 0x7FFF, out equals in.
    check_low_half_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            (in <= 16'h7FFF) |-> (out == in)
    );

// For in > 0x7FFF, out equals two's complement of in.
    check_high_half_twos_complement: assert property (
        @(posedge clk) disable iff (reset)
            (in > 16'h7FFF) |-> (out == ((~in) + 16'h1))
    );

///// Boundary and range properties /////
    // For in == 0x8000, out == 0x8000.
    check_boundary_in_8000_out_8000: assert property (
        @(posedge clk) disable iff (reset)
            (in == 16'h8000) |-> (out == 16'h8000)
    );

// Out[15] is 0 for all inputs except when in == 0x8000.
    check_out_msb_zero_except_8000: assert property (
        @(posedge clk) disable iff (reset)
            (in != 16'h8000) |-> (out[15] == 1'b0)
    );

// Out never exceeds 0x8000.
    check_out_upper_bound_8000: assert property (
        @(posedge clk) disable iff (reset)
            (out <= 16'h8000)
    );

// For in > 0x7FFF, in + out wraps to 0 (16-bit).
    check_high_half_sum_zero: assert property (
        @(posedge clk) disable iff (reset)
            (in > 16'h7FFF) |-> ((in + out) == 16'h0000)
    );

///// Specific corner cases /////
    // For in == 0x7FFF, out == 0x7FFF.
    check_boundary_7fff_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            (in == 16'h7FFF) |-> (out == 16'h7FFF)
    );

// For in == 0xFFFF, out == 0x0001.
    check_boundary_ffff_maps_to_one: assert property (
        @(posedge clk) disable iff (reset)
            (in == 16'hFFFF) |-> (out == 16'h0001)
    );

// Clock: clk; no reset present in RTL.
    // Sequential behavior: on posedge clk, if load=1 load data; else shift left and insert data[3] at LSB.

    // Next-cycle out matches RTL next-state function based on prior cycle inputs.
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(load) ? $past(data) : {$past(out[2:0]), $past(data[3])}))
    );

// When load is 1, next-cycle out equals prior-cycle data.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (out == $past(data))
    );

// When load is 0, next-cycle out equals prior out shifted with prior data[3] into LSB.
    check_shift_concat: assert property (
        @(posedge clk) !load |=> (out == {$past(out[2:0]), $past(data[3])})
    );

// In shift mode, upper bits move from lower bits of prior out.
    check_shift_upper_bits_move: assert property (
        @(posedge clk) !load |=> (out[3:1] == $past(out[2:0]))
    );

// In shift mode, LSB becomes prior-cycle data[3].
    check_shift_lsb_source: assert property (
        @(posedge clk) !load |=> (out[0] == $past(data[3]))
    );

// Reset high forces count to zero in the same cycle.
  check_reset_now: assert property (
    @(posedge clk) rst |-> (count == 8'h00)
  );

// Reset high forces count to zero in the next cycle too.
  check_reset_next: assert property (
    @(posedge clk) rst |=> (count == 8'h00)
  );

// If enabled and below MAX_COUNT, increment by 1 next cycle.
  check_increment_when_enabled_below_max: assert property (
    @(posedge clk) disable iff (rst) (cnt_en && (count < MAX_COUNT)) |=> (count == $past(count) + 1)
  );

// If disabled, clear to zero next cycle.
  check_clear_when_disabled: assert property (
    @(posedge clk) disable iff (rst) (!cnt_en) |=> (count == 8'h00)
  );

// If enabled and at/above MAX_COUNT, clear to zero next cycle.
  check_clear_when_enabled_at_or_above_max: assert property (
    @(posedge clk) disable iff (rst) (cnt_en && (count >= MAX_COUNT)) |=> (count == 8'h00)
  );

// Incrementing implies the value changes (no stutter).
  check_no_stutter_on_increment: assert property (
    @(posedge clk) disable iff (rst) (cnt_en && (count < MAX_COUNT)) |=> (count != $past(count))
  );

// From MAX_COUNT with enable, wrap/clear to zero next cycle.
  check_wrap_to_zero_from_max_enabled: assert property (
    @(posedge clk) disable iff (rst) ($past(cnt_en) && ($past(count) >= MAX_COUNT)) |-> (count == 8'h00)
  );

// Nonzero count implies prior cycle had enable and count<MAX_COUNT.
  check_nonzero_implies_prev_enable_below_max: assert property (
    @(posedge clk) disable iff (rst) (count != 8'h00) |-> ($past(cnt_en) && ($past(count) < MAX_COUNT))
  );

// On reset release with enable, go to 1 next cycle.
  check_release_with_enable_goes_to_one: assert property (
    @(posedge clk) $fell(rst) && cnt_en |=> (count == 8'd1)
  );

// On reset release with disable, stay at 0 next cycle.
  check_release_with_disable_keeps_zero: assert property (
    @(posedge clk) $fell(rst) && !cnt_en |=> (count == 8'h00)
  );

// On valid decode (0..3) with EN high, upper bits [15:4] must be all 1s next cycle.
    check_high_bits_ones_on_valid_decode: assert property (
        @(posedge clk) (EN && ({A,B} inside {4'b0000,4'b0001,4'b0010,4'b0011})) |=> (Y[15:4] == 12'hFFF)
    );

// EQ equals signed equality of A and B.
    eq_reflects_signed_equality: assert property (
        @(posedge CLK) (EQ == (A == B))
    );

// GT equals signed greater-than of A over B.
    gt_reflects_signed_gt: assert property (
        @(posedge CLK) (GT == (A > B))
    );

// EQ and GT are never both 1.
    check_outputs_mutex: assert property (
        @(posedge CLK) !(EQ && GT)
    );

// When A < B, outputs are both 0.
    less_case_outputs_zero_zero: assert property (
        @(posedge CLK) (A < B) |-> (!EQ && !GT)
    );

// Outputs both 0 only when A < B.
    zero_zero_implies_less: assert property (
        @(posedge CLK) (!EQ && !GT) |-> (A < B)
    );

// When A != B, EQ is 0.
    neq_implies_eq_zero: assert property (
        @(posedge CLK) (A != B) |-> (EQ == 1'b0)
    );

// While reset is asserted, output tick must be LOW.
    reset_clears_tick: assert property (
        @(posedge clk) reset |-> (got_code_tick == 1'b0)
    );

// No tick when scan_done_tick is LOW.
    tick_requires_done: assert property (
        @(posedge clk) disable iff (reset) (scan_done_tick == 1'b0) |-> (got_code_tick == 1'b0)
    );

// got_code_tick is a single-cycle pulse.
    tick_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (reset) got_code_tick |=> !got_code_tick
    );

// After a tick, remain LOW until a BRK code is observed with scan_done_tick.
    holdoff_until_break_after_tick: assert property (
        @(posedge clk) disable iff (reset) got_code_tick |=> (!got_code_tick until (scan_done_tick && (scan_out == BRK)))
    );

// With back-to-back done pulses, if prior was not BRK in wait_brk, then no tick now.
    consecutive_done_without_break_no_tick: assert property (
        @(posedge clk) disable iff (reset)
            scan_done_tick && $past(!reset) && $past(scan_done_tick) && !($past(scan_out == BRK) && !$past(got_code_tick)) |-> !got_code_tick
    );

// With back-to-back done pulses, a tick now implies prior was BRK and no tick.
    consecutive_done_tick_implies_prev_break: assert property (
        @(posedge clk) disable iff (reset)
            scan_done_tick && $past(!reset) && $past(scan_done_tick) && got_code_tick |-> $past(scan_out == BRK) && !$past(got_code_tick)
    );

// After reset deasserts, no tick until a BRK code is seen with scan_done_tick.
    after_reset_block_tick_until_break: assert property (
        @(posedge clk) $fell(reset) |-> (!got_code_tick until (scan_done_tick && (scan_out == BRK)))
    );

// On the first cycle after reset deasserts, a BRK done does not raise tick.
    first_cycle_after_reset_break_no_tick: assert property (
        @(posedge clk) $past(reset) && !reset && scan_done_tick && (scan_out == BRK) |-> !got_code_tick
    );

// DUT sky130_fd_sc_hdll__nand4b has no clock/reset; pure combinational. Sample on external CLK.
    // Y implements Y = ~(B & C & D & ~A_N) = A_N | ~B | ~C | ~D.

    // Y must equal the NAND4b Boolean function.
    check_functional_equivalence: assert property (
        @(posedge CLK) Y == ~(B & C & D & ~A_N)
    );

// Y low only when B=C=D=1 and A_N=0.
    check_only_low_when_all_ones_A_N_low: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (B && C && D && ~A_N)
    );

// When B=C=D=1 and A_N=0, Y must be low.
    check_low_when_all_ones_A_N_low_sufficient: assert property (
        @(posedge CLK) (B && C && D && ~A_N) |-> (Y == 1'b0)
    );

// A_N high forces Y high.
    check_A_N_high_forces_one: assert property (
        @(posedge CLK) A_N |-> (Y == 1'b1)
    );

// B low forces Y high.
    check_B_zero_forces_one: assert property (
        @(posedge CLK) (!B) |-> (Y == 1'b1)
    );

// C low forces Y high.
    check_C_zero_forces_one: assert property (
        @(posedge CLK) (!C) |-> (Y == 1'b1)
    );

// D low forces Y high.
    check_D_zero_forces_one: assert property (
        @(posedge CLK) (!D) |-> (Y == 1'b1)
    );

// If Y is high, at least one of A_N or ~B or ~C or ~D is true.
    check_Y_high_implies_cause: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A_N || !B || !C || !D)
    );

// When B=C=D=1, Y equals A_N.
    check_when_BCD_all_ones_output_equals_A_N: assert property (
        @(posedge CLK) (B && C && D) |-> (Y == A_N)
    );

// When A_N=0 and B=C=1, Y equals ~D.
    check_when_AN_low_BC_ones_output_equals_notD: assert property (
        @(posedge CLK) (~A_N && B && C) |-> (Y == !D)
    );

// Y must equal B1 | (A1 & A2).
    check_y_equals_or_and: assert property (
        @(posedge CLK) Y == (B1 || (A1 && A2))
    );

// B1 HIGH forces Y HIGH.
    check_b1_implies_y_high: assert property (
        @(posedge CLK) B1 |-> Y
    );

// A1&A2 HIGH forces Y HIGH.
    check_a1a2_implies_y_high: assert property (
        @(posedge CLK) (A1 && A2) |-> Y
    );

// If B1=0 and !(A1&A2), then Y must be 0.
    check_blocking_inputs_imply_y_low: assert property (
        @(posedge CLK) (!B1 && !(A1 && A2)) |-> (!Y)
    );

// Y=0 implies B1=0 and !(A1&A2).
    check_y_low_implies_blocking_inputs: assert property (
        @(posedge CLK) (!Y) |-> (!B1 && !(A1 && A2))
    );

// When A1&A2=0, Y equals B1.
    check_y_equals_b1_when_and_zero: assert property (
        @(posedge CLK) (!(A1 && A2)) |-> (Y == B1)
    );

// When B1=0, Y equals A1&A2.
    check_y_equals_and_when_b1_zero: assert property (
        @(posedge CLK) (!B1) |-> (Y == (A1 && A2))
    );

// With known inputs, Y is not X/Z.
    check_known_inputs_imply_known_y: assert property (
        @(posedge CLK) (!$isunknown({A1, A2, B1})) |-> (!$isunknown(Y))
    );

// All inputs LOW => Y LOW.
    check_all_zero_inputs_imply_y_low: assert property (
        @(posedge CLK) (!B1 && !A1 && !A2) |-> (!Y)
    );

// Y=1 implies B1=1 or A1&A2=1.
    check_y_high_implies_source: assert property (
        @(posedge CLK) (Y) |-> (B1 || (A1 && A2))
    );

// When in==4'b1110, out must be 2'b00.
      map_in_1110_to_out_00: assert property (
        @(posedge clk) (in === 4'b1110) |-> (out == 2'b00)
      );

// When in==4'b1101, out must be 2'b01.
      map_in_1101_to_out_01: assert property (
        @(posedge clk) (in === 4'b1101) |-> (out == 2'b01)
      );

// When in==4'b1011, out must be 2'b10.
      map_in_1011_to_out_10: assert property (
        @(posedge clk) (in === 4'b1011) |-> (out == 2'b10)
      );

// When in==4'b0111, out must be 2'b11.
      map_in_0111_to_out_11: assert property (
        @(posedge clk) (in === 4'b0111) |-> (out == 2'b11)
      );

// For any input not matching the four patterns, out must be 2'b00 (default case).
      default_for_unmatched_inputs: assert property (
        @(posedge clk) (in !== 4'b1110) && (in !== 4'b1101) && (in !== 4'b1011) && (in !== 4'b0111) |-> (out == 2'b00)
      );

// out==2'b01 only occurs for in==4'b1101.
      only_out_01_on_1101: assert property (
        @(posedge clk) (out == 2'b01) |-> (in === 4'b1101)
      );

// out==2'b10 only occurs for in==4'b1011.
      only_out_10_on_1011: assert property (
        @(posedge clk) (out == 2'b10) |-> (in === 4'b1011)
      );

// out==2'b11 only occurs for in==4'b0111.
      only_out_11_on_0111: assert property (
        @(posedge clk) (out == 2'b11) |-> (in === 4'b0111)
      );

// Y matches NAND(A_N,B_N,C,D) when A_N rises.
    check_nand_eq_on_A_N: assert property (
        @(posedge A_N) Y == ~(A_N & B_N & C & D)
    );

// Y matches NAND(A_N,B_N,C,D) when B_N rises.
    check_nand_eq_on_B_N: assert property (
        @(posedge B_N) Y == ~(A_N & B_N & C & D)
    );

// Y matches NAND(A_N,B_N,C,D) when C rises.
    check_nand_eq_on_C: assert property (
        @(posedge C) Y == ~(A_N & B_N & C & D)
    );

// Y matches NAND(A_N,B_N,C,D) when D rises.
    check_nand_eq_on_D: assert property (
        @(posedge D) Y == ~(A_N & B_N & C & D)
    );

// No clock or reset in RTL; pure combinational. Assertions sampled on external CLK.
    // Functional behavior: Y = ~(A | B | C | D_N). Power pins unused in logic.

    // Y equals bitwise NOR of A,B,C,D_N.
    check_function_nor4b: assert property (
        @(posedge CLK) disable iff (1'b0) (Y === ~(A | B | C | D_N))
    );

// If any input is HIGH, Y must be LOW.
    check_any_high_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) (|{A,B,C,D_N}) |-> (Y == 1'b0)
    );

// If all inputs are LOW, Y must be HIGH.
    check_all_low_forces_high: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B && !C && !D_N) |-> (Y == 1'b1)
    );

// If Y is HIGH, then all inputs are LOW.
    check_y_high_implies_all_low: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b1) |-> (!A && !B && !C && !D_N)
    );

// If Y is LOW, then at least one input is HIGH.
    check_y_low_implies_any_high: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b0) |-> (|{A,B,C,D_N})
    );

// A rising to HIGH forces Y LOW.
    check_rose_A_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(A) |-> (Y == 1'b0)
    );

// B rising to HIGH forces Y LOW.
    check_rose_B_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(B) |-> (Y == 1'b0)
    );

// C rising to HIGH forces Y LOW.
    check_rose_C_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(C) |-> (Y == 1'b0)
    );

// D_N rising to HIGH forces Y LOW.
    check_rose_DN_forces_low: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(D_N) |-> (Y == 1'b0)
    );

///// Reset behavior /////
  // When reset is asserted, byte_out must be all zeros.
  reset_clears_output: assert property (
    @(posedge clk) reset |-> (byte_out == 9'b0)
  );

///// Functional mapping /////
  // Next cycle, byte_out[7:0] equals data_in from the previous cycle.
  map_lower_byte_next: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (byte_out[7:0] == $past(data_in))
  );

// Next cycle, byte_out[8] equals XOR-reduction of previous cycle's data_in.
  map_parity_next: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (byte_out[8] == ^$past(data_in))
  );

///// Parity consistency /////
  // Parity bit matches XOR of the stored data bits.
  parity_matches_lower_bits: assert property (
    @(posedge clk) disable iff (reset) (byte_out[8] == ^byte_out[7:0])
  );

// The 9-bit byte_out always has even parity.
  even_parity_invariant: assert property (
    @(posedge clk) disable iff (reset) (^byte_out == 1'b0)
  );

// DUT has no reset; purely combinational logic sampled on clk.
    // Behavior: EQ=1 when A==B; LT=1 when A<B; GT=1 when A>B; exactly one high.

    // Exactly one of EQ/LT/GT is HIGH at any time.
    check_onehot_outputs: assert property (
        @(posedge clk) $onehot({EQ, LT, GT})
    );

// When A equals B, EQ must be 1 and LT/GT must be 0.
    check_eq_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !LT && !GT)
    );

// If EQ is 1, then A must equal B.
    check_equal_implied_by_EQ: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// When A is less than B, LT must be 1 and EQ/GT must be 0.
    check_lt_when_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && LT && !GT)
    );

// If LT is 1, then A must be less than B.
    check_less_implied_by_LT: assert property (
        @(posedge clk) LT |-> (A < B)
    );

// When A is greater than B, GT must be 1 and EQ/LT must be 0.
    check_gt_when_greater: assert property (
        @(posedge clk) (A > B) |-> (!EQ && !LT && GT)
    );

// If GT is 1, then A must be greater than B.
    check_greater_implied_by_GT: assert property (
        @(posedge clk) GT |-> (A > B)
    );

///// Combinational function checks /////
    // Y must equal OR of inputs per gate structure.
    check_y_is_or: assert property (
        @(posedge clk) Y == (A || B || C_N || D_N)
    );

// Y cannot be HIGH unless some input is HIGH.
    check_no_false_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A || B || C_N || D_N)
    );

// When all inputs are LOW, Y must be LOW.
    check_all_low_implies_y_low: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C_N == 1'b0 && D_N == 1'b0) |-> (Y == 1'b0)
    );

// Y is LOW only if all inputs are LOW (no other way to get 0 on OR).
    check_y_low_only_if_all_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A == 1'b0 && B == 1'b0 && C_N == 1'b0 && D_N == 1'b0)
    );

// A being HIGH forces Y HIGH.
    check_A_dominates: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b1)
    );

// B being HIGH forces Y HIGH.
    check_B_dominates: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b1)
    );

// C_N being HIGH forces Y HIGH.
    check_C_N_dominates: assert property (
        @(posedge clk) (C_N == 1'b1) |-> (Y == 1'b1)
    );

// D_N being HIGH forces Y HIGH.
    check_D_N_dominates: assert property (
        @(posedge clk) (D_N == 1'b1) |-> (Y == 1'b1)
    );

///// Edge-sensitive sanity checks /////
    // A rising edge on Y implies some input is HIGH in that cycle.
    check_y_rise_requires_input_high: assert property (
        @(posedge clk) $rose(Y) |-> (A || B || C_N || D_N)
    );

// A falling edge on Y implies all inputs are LOW in that cycle.
    check_y_fall_requires_all_low: assert property (
        @(posedge clk) $fell(Y) |-> (A == 1'b0 && B == 1'b0 && C_N == 1'b0 && D_N == 1'b0)
    );

// Output equals the AND of all six inputs.
    check_and_equivalence: assert property (
        @(posedge clk) o == (i0 & i1 & i2 & i3 & i4 & i5)
    );

// Output equals data_in left-shifted by shift_amount.
    check_output_matches_shift: assert property (
        @(posedge clk) (data_out == (data_in << shift_amount))
    );

// Clock: clk (posedge). Reset: rst (active-high, synchronous).
    // Sequential behavior: out_pc resets to 0, else increments by 4 each clk.

    // Reset drives out_pc to zero on each clock with rst=1.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (out_pc == 32'd0)
    );

// Output vector must equal 1 << input_lines for all inputs 0..15.
  check_vector_mapping: assert property (
    @(posedge clk) output_lines == (16'h0001 << input_lines)
  );

// Outputs are always exactly one-hot.
  check_onehot_outputs: assert property (
    @(posedge clk) $onehot(output_lines)
  );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// When input_lines == idx, output_lines must be one-hot at bit idx.
      check_decode_map: assert property (
        @(posedge clk) (input_lines == idx) |-> (output_lines == (16'h0001 << idx))
      );

// Output implements NAND: out == ~(a & b).
    check_nand_function: assert property (
        @(posedge clk) out == (~(a & b))
    );

// When both inputs are 1, out is 0.
    check_tt_11_zero: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b0)
    );

// When any input is 0, out is 1.
    check_any_zero_high: assert property (
        @(posedge clk) ((!a) || (!b)) |-> (out == 1'b1)
    );

// Out low only if both inputs are 1.
    check_low_only_when_both_one: assert property (
        @(posedge clk) (out == 1'b0) |-> (a && b)
    );

// DeMorgan equivalence form: out == (~a) || (~b).
    check_demorgan_form: assert property (
        @(posedge clk) out == ((~a) || (~b))
    );

// Clock: clk; Reset: n_rst (active-low, asynchronous)
    // Logic: mixed (seq cnt register with async reset; comb next-state and outputs)
    // Behavior: 4-bit saturating up/down counter; hold when both or none; out2=cnt[0], out1=~cnt[0]

    // During active reset, counter is 0 and outputs reflect LSB
    check_reset_state: assert property (
        @(posedge clk) !n_rst |-> (cnt == 4'd0) && (out2 == 1'b0) && (out1 == 1'b1)
    );

// out2 always equals cnt LSB
    check_out2_matches_cnt_lsb: assert property (
        @(posedge clk) disable iff (!n_rst) out2 == cnt[0]
    );

// out1 always equals complement of cnt LSB
    check_out1_complements_cnt_lsb: assert property (
        @(posedge clk) disable iff (!n_rst) out1 == ~cnt[0]
    );

// Increment by 1 when up=1, dn=0, and not at max (based on previous cycle)
    check_increment_when_up_only: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && up && !dn && (cnt < 4'hf)) |-> (cnt == $past(cnt) + 4'd1)
    );

// Hold at max when up=1, dn=0, and at 0xF (saturate high)
    check_saturate_at_max_on_up: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && up && !dn && (cnt == 4'hf)) |-> (cnt == 4'hf)
    );

// Decrement by 1 when dn=1, up=0, and not at zero (based on previous cycle)
    check_decrement_when_dn_only: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && dn && !up && (cnt > 4'd0)) |-> (cnt == $past(cnt) - 4'd1)
    );

// Hold at zero when dn=1, up=0, and at 0 (saturate low)
    check_saturate_at_zero_on_dn: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && dn && !up && (cnt == 4'd0)) |-> (cnt == 4'd0)
    );

// Hold when both controls are deasserted
    check_hold_when_both_low: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && !up && !dn) |-> (cnt == $past(cnt))
    );

// Hold when both controls are asserted
    check_hold_when_both_high: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && up && dn) |-> (cnt == $past(cnt))
    );

// From mid-range (1..14), next value changes by at most 1 or holds
    check_unit_step_in_midrange: assert property (
        @(posedge clk) disable iff (!n_rst)
            $past(n_rst && (cnt > 4'd0) && (cnt < 4'hf)) |->
                ( (cnt == $past(cnt)) ||
                  (cnt == $past(cnt) + 4'd1) ||
                  (cnt == $past(cnt) - 4'd1) )
    );

// Y always equals the muxed add/sub result.
    check_y_matches_spec: assert property (
        @(posedge CLK) (Y == y_ref)
    );

// When C==0, Y equals A + B.
    check_y_add_when_c0: assert property (
        @(posedge CLK) (!C) |-> (Y == add_ref)
    );

// When C==1, Y equals A + (~B + 1).
    check_y_sub_when_c1: assert property (
        @(posedge CLK) (C) |-> (Y == sub_ref)
    );

// For subtraction mode, Y equals A - B (3-bit wraparound).
    check_y_sub_equiv_minus: assert property (
        @(posedge CLK) (C) |-> (Y == (A - B))
    );

// If B is zero, Y equals A regardless of C.
    check_b_zero_y_eq_a: assert property (
        @(posedge CLK) (B == 3'd0) |-> (Y == A)
    );

// In subtraction mode, equal inputs yield zero.
    check_c1_equal_inputs_y_zero: assert property (
        @(posedge CLK) (C && (A == B)) |-> (Y == 3'd0)
    );

// In subtraction mode, B==7 increments A by 1 (3-bit wrap).
    check_c1_b_max_incr: assert property (
        @(posedge CLK) (C && (B == 3'd7)) |-> (Y == (A + 3'd1))
    );

// In addition mode, reversing with -B returns A: (Y + (~B + 1)) == A.
    check_c0_reverse_identity: assert property (
        @(posedge CLK) (!C) |-> ((Y + (~B + 3'd1)) == A)
    );

// In subtraction mode, reversing with +B returns A: (Y + B) == A.
    check_c1_reverse_identity: assert property (
        @(posedge CLK) (C) |-> ((Y + B) == A)
    );

///// Reset behavior /////
    // On synchronous reset, counter=0 and precharge_safe=1 on next cycle.
    reset_sync_values: assert property (
        @(posedge sys_clk) sdram_rst |=> (counter == 3'd0) && (precharge_safe == 1'b1)
    );

// Output matches the case-encoded mapping for all inputs.
    check_functional_mapping: assert property (
        @(posedge CLK) out == expected_out(in)
    );

// When button is LOW, count holds its value into the next cycle.
    check_count_hold_when_button_low: assert property (
        @(posedge clk) !button |=> (count == $past(count))
    );

// When button is HIGH, count increments by 1 (modulo 8) into the next cycle.
    check_count_increment_when_button_high: assert property (
        @(posedge clk) button |=> (count == ($past(count) + 3'd1))
    );

// When button is HIGH and count==7, next count wraps to 0.
    check_count_wrap_7_to_0: assert property (
        @(posedge clk) (button && (count == 3'd7)) |=> (count == 3'd0)
    );

// Two consecutive cycles of button HIGH increment count by 2 (modulo 8).
    check_two_cycle_count_increment: assert property (
        @(posedge clk) button[*2] |=> (count == ($past(count,2) + 3'd2))
    );

// Eight consecutive cycles of button HIGH return count to its original value.
    check_count_period_8_when_held_high: assert property (
        @(posedge clk) button[*8] |=> (count == $past(count,8))
    );

// X equals (~A_N) & B
    check_function_equation: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

// When B is 0, X must be 0
    check_x_zero_when_b_zero: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

// When A_N is 1, X must be 0
    check_x_zero_when_a_n_one: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

// When A_N is 0 and B is 1, X must be 1
    check_x_one_when_a0_b1: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (X == 1'b1)
    );

// On B rising edge with A_N==0, X must be 1
    check_x_one_on_b_rise_when_a0: assert property (
        @(posedge clk) ($rose(B) && (A_N == 1'b0)) |-> (X == 1'b1)
    );

// On B falling edge, X must be 0
    check_x_zero_on_b_fall: assert property (
        @(posedge clk) $fell(B) |-> (X == 1'b0)
    );

// On A_N falling edge with B==1, X must be 1
    check_x_one_on_an_fall_when_b1: assert property (
        @(posedge clk) ($fell(A_N) && (B == 1'b1)) |-> (X == 1'b1)
    );

// On A_N rising edge with B==1, X must be 0
    check_x_zero_on_an_rise_when_b1: assert property (
        @(posedge clk) ($rose(A_N) && (B == 1'b1)) |-> (X == 1'b0)
    );

// X can only rise when B==1 and A_N==0
    check_x_rise_requires_b1_a0: assert property (
        @(posedge clk) $rose(X) |-> ((B == 1'b1) && (A_N == 1'b0))
    );

// X can only fall when B==0 or A_N==1
    check_x_fall_requires_b0_or_a1: assert property (
        @(posedge clk) $fell(X) |-> ((B == 1'b0) || (A_N == 1'b1))
    );

///// OR3 functional correctness /////
    // X equals logical OR of A,B,C each cycle.
    check_or_function_equivalence: assert property (
        @(posedge CLK) (X == (A | B | C))
    );

// If A is 1, X must be 1 the same cycle.
    check_a_high_forces_x_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

// If B is 1, X must be 1 the same cycle.
    check_b_high_forces_x_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

// If C is 1, X must be 1 the same cycle.
    check_c_high_forces_x_high: assert property (
        @(posedge CLK) (C == 1'b1) |-> (X == 1'b1)
    );

// If all inputs are 0, X must be 0 the same cycle.
    check_all_zero_forces_x_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X == 1'b0)
    );

// If X is 0, then all inputs must be 0.
    check_x_zero_implies_all_zero: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0))
    );

// Reset low drives Q to zero in the same cycle.
    check_reset_clears_q_now: assert property (
        @(posedge clk) !not_reset |-> (Q == 16'h0000)
    );

// After any cycle with reset low, Q is zero on the next cycle.
    check_zero_one_cycle_after_reset: assert property (
        @(posedge clk) (!not_reset) |=> (Q == 16'h0000)
    );

// With Load high, next cycle Q equals sampled D or becomes zero if an async reset occurred.
    check_load_captures_d_or_zero_next: assert property (
        @(posedge clk) disable iff (!not_reset)
            (Load) |=> ((Q == $past(D)) || (Q == 16'h0000))
    );

// With Load low, next cycle Q holds or becomes zero if an async reset occurred.
    check_hold_or_zero_next: assert property (
        @(posedge clk) disable iff (!not_reset)
            (!Load) |=> ($stable(Q) || (Q == 16'h0000))
    );

// If no Load, any observed Q change by next cycle must be a reset to zero.
    check_change_without_load_means_zero: assert property (
        @(posedge clk) disable iff (!not_reset)
            (!Load) |=> (!$changed(Q) || (Q == 16'h0000))
    );

// Loading D==0 guarantees Q==0 on the next cycle (or remains 0 under reset).
    check_load_zero_data_results_zero: assert property (
        @(posedge clk) disable iff (!not_reset)
            (Load && (D == 16'h0000)) |=> (Q == 16'h0000)
    );

// Reset has priority over Load when asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (!not_reset && Load) |-> (Q == 16'h0000)
    );

// If Q rises from zero to nonzero, the prior cycle must have had Load asserted.
    check_nonzero_rise_requires_prior_load: assert property (
        @(posedge clk) disable iff (!not_reset)
            (Q == 16'h0000) |=> ((Q != 16'h0000) -> $past(Load))
    );

// If a nonzero value is observed after a Load with nonzero D, it must equal the sampled D.
    check_nonzero_after_load_matches_d: assert property (
        @(posedge clk) disable iff (!not_reset)
            (Load && (D != 16'h0000)) |=> ((Q != 16'h0000) -> (Q == $past(D)))
    );

// With no Load, a nonzero Q remains unchanged into the next cycle unless reset forces it to zero.
    check_hold_preserves_nonzero: assert property (
        @(posedge clk) disable iff (!not_reset)
            (!Load) |=> (((Q != 16'h0000) && ($past(Q) != 16'h0000)) -> (Q == $past(Q)))
    );

// Sum equals b when adding, or (0 - b) when subtracting.
    check_sum_function: assert property (
        @(posedge clk) sum == (sub ? (32'h0000_0000 - b) : b)
    );

// When not subtracting, sum mirrors b.
    check_sum_when_add: assert property (
        @(posedge clk) (!sub) |-> (sum == b)
    );

// When subtracting, sum + b == 0 (two's complement negation).
    check_sum_when_sub: assert property (
        @(posedge clk) sub |-> ((sum + b) == 32'h0000_0000)
    );

// If b is zero, sum must be zero regardless of sub.
    check_sum_zero_when_b_zero: assert property (
        @(posedge clk) (b == 32'h0000_0000) |-> (sum == 32'h0000_0000)
    );

// Subtracting the most-negative value returns itself (overflow wraps).
    check_sum_minint_case_when_sub: assert property (
        @(posedge clk) (sub && (b == 32'h8000_0000)) |-> (sum == 32'h8000_0000)
    );

// On sub rising edge with b stable, sum equals (0 - b) in that cycle.
    check_sum_on_sub_rise: assert property (
        @(posedge clk) $rose(sub) && $stable(b) |-> (sum == (32'h0000_0000 - b))
    );

// On sub falling edge with b stable, sum equals b in that cycle.
    check_sum_on_sub_fall: assert property (
        @(posedge clk) $fell(sub) && $stable(b) |-> (sum == b)
    );

// Y implements a 2:1 mux with EN selecting A over B.
    check_mux_function: assert property (
        @(posedge CLK) Y == (EN ? A : B)
    );

// When EN is 1, Y equals A.
    check_select_a_when_en: assert property (
        @(posedge CLK) EN |-> (Y == A)
    );

// When EN is 0, Y equals B.
    check_select_b_when_not_en: assert property (
        @(posedge CLK) !EN |-> (Y == B)
    );

// On EN rising edge, Y equals A in the same cycle.
    check_en_rise_selects_a: assert property (
        @(posedge CLK) $rose(EN) |-> (Y == A)
    );

// On EN falling edge, Y equals B in the same cycle.
    check_en_fall_selects_b: assert property (
        @(posedge CLK) $fell(EN) |-> (Y == B)
    );

// If CO is HIGH now, it must be LOW on the next cycle.
    check_co_clears_next_if_high: assert property (
        @(posedge CLK) (CO == 1'b1) |=> (CO == 1'b0)
    );

// Once CO is LOW, it remains LOW on the next cycle.
    check_co_low_sticky: assert property (
        @(posedge CLK) (CO == 1'b0) |=> (CO == 1'b0)
    );

// From any time, CO becomes LOW within two cycles and thus cannot persist HIGH.
    check_co_eventually_low_within_two: assert property (
        @(posedge CLK) 1'b1 |-> ##[0:2] (CO == 1'b0)
    );

// After any falling edge of CO, it stays LOW forever.
    check_co_stays_low_after_fall: assert property (
        @(posedge CLK) $fell(CO) |-> (CO == 1'b0)[*1:$]
    );

// out equals selected input per mux function.
    check_mux_equivalence: assert property (
        @(posedge CLK) out == (sel ? in1 : in0)
    );

// When sel is 0, out mirrors in0.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == in0)
    );

// When sel is 1, out mirrors in1.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == in1)
    );

// On a rising edge of sel, out equals in1 in the same cycle.
    check_sel_rise_selects_in1: assert property (
        @(posedge CLK) $rose(sel) |-> (out == in1)
    );

// On a falling edge of sel, out equals in0 in the same cycle.
    check_sel_fall_selects_in0: assert property (
        @(posedge CLK) $fell(sel) |-> (out == in0)
    );

// If inputs are equal, out equals that common value regardless of sel.
    check_inputs_equal_forces_out: assert property (
        @(posedge CLK) (in0 == in1) |-> (out == in0)
    );

// Core mux function: Y equals B when SEL=1, else A.
    check_mux_function: assert property (
        @(posedge CLK) Y == (SEL ? B : A)
    );

// When SEL is 1, Y must equal B.
    check_sel1_routes_B: assert property (
        @(posedge CLK) SEL |-> (Y == B)
    );

// When SEL is 0, Y must equal A.
    check_sel0_routes_A: assert property (
        @(posedge CLK) !SEL |-> (Y == A)
    );

// If A and B are equal, Y must equal that value regardless of SEL.
    check_equal_inputs_passthrough: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

// If Y differs from A, then SEL must be 1 and Y must be B.
    check_y_not_a_implies_sel1_b: assert property (
        @(posedge CLK) (Y != A) |-> (SEL && (Y == B))
    );

// If Y differs from B, then SEL must be 0 and Y must be A.
    check_y_not_b_implies_sel0_a: assert property (
        @(posedge CLK) (Y != B) |-> (!SEL && (Y == A))
    );

// If Y equals A, then either SEL is 0 or inputs are equal.
    check_y_eq_a_implication: assert property (
        @(posedge CLK) (Y == A) |-> (!SEL || (A == B))
    );

// If Y equals B, then either SEL is 1 or inputs are equal.
    check_y_eq_b_implication: assert property (
        @(posedge CLK) (Y == B) |-> (SEL || (A == B))
    );

///// OR-combine outputs toward master /////
    // m_pi_req is bitwise OR of all slave pi_req.
    check_m_pi_req_or: assert property (
        @(posedge clk) disable iff (reset) m_pi_req == (s0_pi_req | s1_pi_req | s2_pi_req)
    );

// m_iob_read is bitwise OR of master write and all slave read.
    check_m_iob_read_or: assert property (
        @(posedge clk) disable iff (reset) m_iob_read == (m_iob_write | s0_iob_read | s1_iob_read | s2_iob_read)
    );

// m_dr_split is OR of all slave dr_split.
    check_m_dr_split_or: assert property (
        @(posedge clk) disable iff (reset) m_dr_split == (s0_dr_split | s1_dr_split | s2_dr_split)
    );

// m_rdi_data is OR of all slave rdi_data.
    check_m_rdi_data_or: assert property (
        @(posedge clk) disable iff (reset) m_rdi_data == (s0_rdi_data | s1_rdi_data | s2_rdi_data)
    );

///// Pass-through from master to slave 0 /////
    // All 1-bit control/status signals pass through to s0.
    check_s0_ctrl_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            {s0_iob_poweron, s0_iob_reset, s0_datao_clear, s0_datao_set, s0_cono_clear, s0_cono_set,
             s0_iob_fm_datai, s0_iob_fm_status, s0_rdi_pulse}
          =={m_iob_poweron, m_iob_reset, m_datao_clear, m_datao_set, m_cono_clear, m_cono_set,
             m_iob_fm_datai, m_iob_fm_status, m_rdi_pulse}
    );

// IOS bus passes through to s0.
    check_s0_ios_passthrough: assert property (
        @(posedge clk) disable iff (reset) s0_ios == m_ios
    );

// IOB write bus passes through to s0.
    check_s0_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s0_iob_write == m_iob_write
    );

///// Pass-through from master to slave 1 /////
    // All 1-bit control/status signals pass through to s1.
    check_s1_ctrl_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            {s1_iob_poweron, s1_iob_reset, s1_datao_clear, s1_datao_set, s1_cono_clear, s1_cono_set,
             s1_iob_fm_datai, s1_iob_fm_status, s1_rdi_pulse}
          =={m_iob_poweron, m_iob_reset, m_datao_clear, m_datao_set, m_cono_clear, m_cono_set,
             m_iob_fm_datai, m_iob_fm_status, m_rdi_pulse}
    );

// IOS bus passes through to s1.
    check_s1_ios_passthrough: assert property (
        @(posedge clk) disable iff (reset) s1_ios == m_ios
    );

// IOB write bus passes through to s1.
    check_s1_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s1_iob_write == m_iob_write
    );

///// Pass-through from master to slave 2 /////
    // All 1-bit control/status signals pass through to s2.
    check_s2_ctrl_passthrough: assert property (
        @(posedge clk) disable iff (reset)
            {s2_iob_poweron, s2_iob_reset, s2_datao_clear, s2_datao_set, s2_cono_clear, s2_cono_set,
             s2_iob_fm_datai, s2_iob_fm_status, s2_rdi_pulse}
          =={m_iob_poweron, m_iob_reset, m_datao_clear, m_datao_set, m_cono_clear, m_cono_set,
             m_iob_fm_datai, m_iob_fm_status, m_rdi_pulse}
    );

// IOS bus passes through to s2.
    check_s2_ios_passthrough: assert property (
        @(posedge clk) disable iff (reset) s2_ios == m_ios
    );

// IOB write bus passes through to s2.
    check_s2_write_passthrough: assert property (
        @(posedge clk) disable iff (reset) s2_iob_write == m_iob_write
    );

///// Reset behavior /////
    // While reset is asserted low, out_clk must be 0.
    reset_low_out_zero: assert property (
        @(posedge clk) (!reset) |-> (out_clk == 1'b0)
    );

// On the cycle where reset falls (asynchronous assert), out_clk must be 0.
    async_reset_fall_clears_out: assert property (
        @(posedge clk) $fell(reset) |-> (out_clk == 1'b0)
    );

// On the first clock after reset deasserts high, out_clk remains 0.
    out_zero_on_first_cycle_after_deassert: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> (out_clk == 1'b0)
    );

// On the second clock after reset deasserts high, out_clk becomes 1.
    out_one_on_second_cycle_after_deassert: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> ##1 (out_clk == 1'b1)
    );

///// Divide-by-2 behavior /////
    // After at least one active cycle, out_clk toggles every clock.
    toggle_every_cycle_after_warmup: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (out_clk != $past(out_clk))
    );

// After at least two active cycles, out_clk repeats its value every two clocks.
    periodicity_two_cycles: assert property (
        @(posedge clk) disable iff (!reset) $past(reset,2) |-> (out_clk == $past(out_clk,2))
    );

// Any rising edge of out_clk is followed by a falling edge next cycle.
    rise_followed_by_fall: assert property (
        @(posedge clk) disable iff (!reset) $rose(out_clk) |-> ##1 $fell(out_clk)
    );

// Any falling edge of out_clk is followed by a rising edge next cycle.
    fall_followed_by_rise: assert property (
        @(posedge clk) disable iff (!reset) $fell(out_clk) |-> ##1 $rose(out_clk)
    );

// When C=0 the sum equals A+B (8-bit truncation).
    check_sum_when_C0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (sum == (A + B))
    );

// When C=1 the sum equals two's complement of (A+B).
    check_sum_when_C1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (sum == (~(A + B) + 8'd1))
    );

// Sum is zero whenever (A+B) is zero, regardless of C.
    check_zero_result_on_zero_input_sum: assert property (
        @(posedge CLK) ((A + B) == 8'h00) |-> (sum == 8'h00)
    );

// Sum is always within 8-bit range.
    check_sum_within_range: assert property (
        @(posedge CLK) (sum <= 8'hFF)
    );

// For C=1, sum plus (A+B) wraps to zero (8-bit).
    check_twos_complement_sum_cancel: assert property (
        @(posedge CLK) (C == 1'b1) |-> (((sum + (A + B)) == 8'h00))
    );

// For C=0, sum cancels with two's complement of (A+B) to zero.
    check_normal_sum_cancel_with_negated_ab: assert property (
        @(posedge CLK) (C == 1'b0) |-> (((sum + (~(A + B) + 8'd1)) == 8'h00))
    );

// Clock: clk (posedge). Reset: reset (active-high). Logic: sequential (registered out).
  // Behavior: on each clk, out <= select ? {8'h00,in} : {in,8'h00}; reset clears out to 0.

  // Out is zero on the cycle after reset is asserted.
  check_reset_clears_next: assert property (
    @(posedge clk) reset |=> (out == 16'h0000)
  );

// While reset is held HIGH for 2+ cycles, out is zero.
  check_reset_holds_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (out == 16'h0000)
  );

// Select decoding terms are one-hot for any S1,S0 combination.
    check_select_terms_onehot: assert property (
        @(posedge CLK) $onehot({(~S1 & ~S0), (~S1 & S0), (S1 & ~S0), (S1 & S0)})
    );

// Output matches the sum-of-products mux equation.
    check_mux_sop_function: assert property (
        @(posedge CLK) Y == ((A & ~S1 & ~S0) | (B & ~S1 & S0) | (C & S1 & ~S0) | (D & S1 & S0))
    );

// When S1S0=00, Y equals A.
    check_select_00_match_A: assert property (
        @(posedge CLK) (~S1 && ~S0) |-> (Y == A)
    );

// When S1S0=01, Y equals B.
    check_select_01_match_B: assert property (
        @(posedge CLK) (~S1 &&  S0) |-> (Y == B)
    );

// When S1S0=10, Y equals C.
    check_select_10_match_C: assert property (
        @(posedge CLK) ( S1 && ~S0) |-> (Y == C)
    );

// When S1S0=11, Y equals D.
    check_select_11_match_D: assert property (
        @(posedge CLK) ( S1 &&  S0) |-> (Y == D)
    );

// When S1=0, Y is a 2:1 mux between A and B selected by S0.
    check_when_S1_low_2to1_AB: assert property (
        @(posedge CLK) (S1 == 1'b0) |-> (Y == (S0 ? B : A))
    );

// When S1=1, Y is a 2:1 mux between C and D selected by S0.
    check_when_S1_high_2to1_CD: assert property (
        @(posedge CLK) (S1 == 1'b1) |-> (Y == (S0 ? D : C))
    );

// When S0=0, Y is a 2:1 mux between A and C selected by S1.
    check_when_S0_low_2to1_AC: assert property (
        @(posedge CLK) (S0 == 1'b0) |-> (Y == (S1 ? C : A))
    );

// When S0=1, Y is a 2:1 mux between B and D selected by S1.
    check_when_S0_high_2to1_BD: assert property (
        @(posedge CLK) (S0 == 1'b1) |-> (Y == (S1 ? D : B))
    );

// out_func equals OR of the two XOR results of (a,b) and (c,d)
    check_function_equivalence_xor_or: assert property (
        @(posedge CLK) out_func == ((a ^ b) || (c ^ d))
    );

// out_func equals (a!=b)||(c!=d)
    check_function_equivalence_neq_or: assert property (
        @(posedge CLK) out_func == ((a != b) || (c != d))
    );

// When both pairs are equal, out_func must be 0
    check_zero_when_both_pairs_equal: assert property (
        @(posedge CLK) ((a == b) && (c == d)) |-> (out_func == 1'b0)
    );

// If a and b differ, out_func must be 1
    check_one_when_ab_differs: assert property (
        @(posedge CLK) (a != b) |-> (out_func == 1'b1)
    );

// If c and d differ, out_func must be 1
    check_one_when_cd_differs: assert property (
        @(posedge CLK) (c != d) |-> (out_func == 1'b1)
    );

// If out_func is 0, both pairs must be equal
    check_zero_implies_both_pairs_equal: assert property (
        @(posedge CLK) (out_func == 1'b0) |-> ((a == b) && (c == d))
    );

// If out_func is 1, at least one pair must differ
    check_one_implies_some_pair_differs: assert property (
        @(posedge CLK) (out_func == 1'b1) |-> ((a != b) || (c != d))
    );

// Gray vector equals bin_in XOR (bin_in >> 1).
    check_gray_vector_equivalence: assert property (
        @(posedge CLK) gray_out == (bin_in ^ (bin_in >> 1))
    );

// MSB of Gray equals MSB of binary input.
    check_gray_msb_mapping: assert property (
        @(posedge CLK) gray_out[7] == bin_in[7]
    );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

check_gray_bit_mapping: assert property (
                @(posedge CLK) gray_out[i] == (bin_in[i] ^ bin_in[i+1])
            );

// Clock: posedge shift. No reset present in RTL. Sequential update on shift edge; out is combinational mirror of register[7].

    // After each shift edge, at the next shift edge out equals the previous in.
    out_lags_in_by_one_shift: assert property (
        @(posedge shift) 1'b1 |=> (out == $past(in))
    );

// If in matches out at a shift edge, then at the next shift edge out remains the same.
    out_holds_when_in_matches: assert property (
        @(posedge shift) (in == out) |=> (out == $past(out))
    );

// When sel=1, OUT is two's complement of A.
    check_sel1_twos_comp: assert property (
        @(posedge CLK) sel |-> (OUT == ((~A) + 4'b0001))
    );

// When sel=1, A + OUT wraps to zero (4-bit two's complement identity).
    check_sel1_adds_to_zero: assert property (
        @(posedge CLK) sel |-> ((A + OUT) == 4'b0000)
    );

// When sel=1 and A==0, OUT==0.
    check_sel1_zero_case: assert property (
        @(posedge CLK) (sel && (A == 4'b0000)) |-> (OUT == 4'b0000)
    );

// When sel=1 and A==4'b1000, OUT==4'b1000 (min value is self-complement).
    check_sel1_min_value_fixed_point: assert property (
        @(posedge CLK) (sel && (A == 4'b1000)) |-> (OUT == 4'b1000)
    );

// If B equals two's complement of A, OUT equals that value regardless of sel.
    check_equal_paths_agree: assert property (
        @(posedge CLK) (B == ((~A) + 4'b0001)) |-> (OUT == B)
    );

///// Reset behavior /////
    // On reset, count=0 and state=S0.
    check_reset_state_count: assert property (
        @(posedge clk) reset |-> (count == 4'd0) && (state == S0)
    );

// On reset, yout is 0.
    check_reset_yout_low: assert property (
        @(posedge clk) reset |-> (yout == 1'b0)
    );

// While RESET is HIGH, Q must be 0 at each CLK edge.
    check_reset_forces_q_zero: assert property (
        @(posedge CLK) RESET |-> (Q == 1'b0)
    );

// If RESET rose since last CLK edge, Q must be 0 at this CLK edge.
    check_async_reset_rise_clears_q_by_next_clk: assert property (
        @(posedge CLK) $rose(RESET) |-> (Q == 1'b0)
    );

// If RESET fell since last CLK edge, Q is still 0 at this CLK edge (before capture).
    check_reset_release_q_zero_before_capture: assert property (
        @(posedge CLK) $fell(RESET) |-> (Q == 1'b0)
    );

// If Q==D at a CLK edge and not crossing reset, Q holds its value at the next CLK.
    check_q_holds_when_q_equals_d: assert property (
        @(posedge CLK) disable iff (RESET) (!$past(RESET) && (Q == D)) |=> (Q == $past(Q))
    );

// If reset is HIGH at a clock edge, q must be 0 on the next clock edge.
    check_reset_clears_next: assert property (
        @(posedge clk) r |-> ##1 (q == 1'b0)
    );

// While reset is HIGH at consecutive sampled cycles, q is 0 now.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk) (r && $past(r)) |-> (q == 1'b0)
    );

// Clock: clk (posedge). Reset: rst (active-high, asynchronous). Logic: sequential counter with wrap to 0 at 15.

    // After reset deassertion, count is 0 on that sampled clock edge.
    check_count_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 4'd0)
    );

// When not at max (15), count increments by 1 on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != 4'hF) |=> (count == $past(count) + 4'd1)
    );

// When at max (15), count wraps to 0 on the next clock.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'd0)
    );

// Every cycle out of reset, the transition is either +1 or wrap-to-0 from 15.
    check_valid_transition_each_cycle: assert property (
        @(posedge clk) disable iff (rst)
            1'b1 |=> ((($past(count) != 4'hF) && (count == $past(count) + 4'd1)) ||
                      (($past(count) == 4'hF) && (count == 4'd0)))
    );

// Mux function: out equals selected input every cycle.
    check_mux_function: assert property (
        @(posedge clk) out == (sel ? b : a)
    );

// When sel is 0, out equals a.
    check_sel0_path: assert property (
        @(posedge clk) (!sel) |-> (out == a)
    );

// When sel is 1, out equals b.
    check_sel1_path: assert property (
        @(posedge clk) (sel) |-> (out == b)
    );

// If inputs are equal, out equals that value regardless of sel.
    check_equal_inputs_drive_out: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// On sel rising edge with stable inputs, out selects b.
    check_out_switches_to_b_on_sel_rise: assert property (
        @(posedge clk) ($rose(sel) && $stable(a) && $stable(b)) |-> (out == b)
    );

// On sel falling edge with stable inputs, out selects a.
    check_out_switches_to_a_on_sel_fall: assert property (
        @(posedge clk) ($fell(sel) && $stable(a) && $stable(b)) |-> (out == a)
    );

// x implements the 2-of-3 majority of a,b,c.
    check_x_majority_function: assert property (
        @(posedge clk) x == ((a & b) | (a & c) | (b & c))
    );

// If a and b are 1, x must be 1.
    check_x_when_ab: assert property (
        @(posedge clk) (a && b) |-> x
    );

// If a and c are 1, x must be 1.
    check_x_when_ac: assert property (
        @(posedge clk) (a && c) |-> x
    );

// If b and c are 1, x must be 1.
    check_x_when_bc: assert property (
        @(posedge clk) (b && c) |-> x
    );

// If only a is 1, x must be 0.
    check_x_when_only_a: assert property (
        @(posedge clk) (a && !b && !c) |-> !x
    );

// If only b is 1, x must be 0.
    check_x_when_only_b: assert property (
        @(posedge clk) (b && !a && !c) |-> !x
    );

// If only c is 1, x must be 0.
    check_x_when_only_c: assert property (
        @(posedge clk) (c && !a && !b) |-> !x
    );

// If all are 0, x must be 0.
    check_x_when_all_zero: assert property (
        @(posedge clk) (!a && !b && !c) |-> !x
    );

// If all are 1, x must be 1.
    check_x_when_all_one: assert property (
        @(posedge clk) (a && b && c) |-> x
    );

// x can be 1 only if at least two inputs are 1.
    check_x_implies_two_high: assert property (
        @(posedge clk) x |-> ((a && b) || (a && c) || (b && c))
    );

// During reset, lfsr and Q must be zero.
  reset_drives_zero: assert property (
    @(posedge clk) (!rst_n) |-> (lfsr == 64'h0) && (Q == 64'h0)
  );

// Q upper bits are always zero-extended.
  q_upper_zero_ext: assert property (
    @(posedge clk) disable iff (!rst_n)
      (Q[63:4] == 60'h0)
  );

// If previous taps {0,4,5,6} were all zero, Q's lower nibble is zero.
  q_zero_from_zero_taps: assert property (
    @(posedge clk) disable iff (!rst_n)
      $past(rst_n) &&
      ({$past(lfsr[0]), $past(lfsr[4]), $past(lfsr[5]), $past(lfsr[6])} == 4'b0000)
      |-> (Q[3:0] == 4'b0000)
  );

// out equals ~in + 1 (two's complement mapping).
    check_twos_complement_mapping: assert property (
        @(posedge in[0]) out == (~in + 4'd1)
    );

// Inverse relationship holds: in equals ~out + 1.
    check_involution: assert property (
        @(posedge in[0]) in == (~out + 4'd1)
    );

// Sum of in and out wraps to 0 on the low 4 bits.
    check_sum_low_nibble_zero: assert property (
        @(posedge in[0]) sum5[3:0] == 4'd0
    );

// Carry-out of in + out equals OR reduction of in.
    check_sum_carry_vs_orin: assert property (
        @(posedge in[0]) sum5[4] == (|in)
    );

// Zero maps to zero.
    check_zero_in_to_out: assert property (
        @(posedge in[0]) (in == 4'd0) |-> (out == 4'd0)
    );

// Only zero maps to zero.
    check_zero_only_if_in_zero: assert property (
        @(posedge in[0]) (out == 4'd0) |-> (in == 4'd0)
    );

// LSB is preserved by two's complement.
    check_lsb_preserved: assert property (
        @(posedge in[0]) out[0] == in[0]
    );

// Value 8 maps to itself.
    check_eight_maps_to_eight: assert property (
        @(posedge in[0]) (in == 4'd8) |-> (out == 4'd8)
    );

// Only value 8 maps to 8.
    check_only_eight_maps_to_eight: assert property (
        @(posedge in[0]) (out == 4'd8) |-> (in == 4'd8)
    );

// Out is never exactly bitwise-not of in (addition of 1 ensures difference).
    check_not_pure_bitwise_not: assert property (
        @(posedge in[0]) out != ~in
    );

// Analysis: no clock/reset in RTL; pure combinational AND4 with buffer; X = A & B & C & D.

    // X equals the AND of inputs A,B,C,D.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A & B & C & D)
    );

// If all inputs are HIGH, X must be HIGH.
    check_all_inputs_high_implies_X_high: assert property (
        @(posedge CLK) (A & B & C & D) |-> (X == 1'b1)
    );

// If any input is LOW, X must be LOW.
    check_any_input_low_implies_X_low: assert property (
        @(posedge CLK) (!A || !B || !C || !D) |-> (X == 1'b0)
    );

// A rising edge on X implies all inputs are HIGH.
    check_X_rise_requires_all_inputs_high: assert property (
        @(posedge CLK) $rose(X) |-> (A & B & C & D)
    );

// A falling edge on X implies at least one input is LOW.
    check_X_fall_requires_any_input_low: assert property (
        @(posedge CLK) $fell(X) |-> (!A || !B || !C || !D)
    );

// Clock: clk_i (posedge). Reset: reset_n (active-low async). Sequential counter toggles clk_o when count >= 17333.

    // Under reset, clk_o and count are driven LOW/zero.
    check_reset_forces_low: assert property (
        @(posedge clk_i) !reset_n |-> (clk_o == 1'b0) && (count == 16'd0)
    );

// No back-to-back clk_o toggles on consecutive active cycles.
    check_no_back_to_back_toggles: assert property (
        @(posedge clk_i) disable iff (!reset_n)
            $changed(clk_o) |-> ##1 (reset_n && $stable(clk_o))
    );

// Clock: clock (posedge). Reset: reset_n active-low async. Sequential registered output.

  // During reset, readdata must be zero.
  reset_clears_readdata: assert property (
    @(posedge clock) (!reset_n) |-> (readdata == 32'h0000_0000)
  );

// On the cycle reset_n rises, readdata is still 0 before the update.
  reset_release_holds_zero_one_cycle: assert property (
    @(posedge clock) $rose(reset_n) |-> (readdata == 32'h0000_0000)
  );

// If address is 0 this cycle, next cycle readdata is 0x560F6F0F (barring reset).
  next_cycle_update_addr0: assert property (
    @(posedge clock) disable iff (!reset_n)
      (address == 1'b0) |=> (readdata == 32'h560F_6F0F)
  );

// If address is 1 this cycle, next cycle readdata is 0xADC3C2C2 (barring reset).
  next_cycle_update_addr1: assert property (
    @(posedge clock) disable iff (!reset_n)
      (address == 1'b1) |=> (readdata == 32'hADC3_C2C2)
  );

// SUM equals A ^ B ^ ~CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// When CIN==1, SUM equals A ^ B.
    check_sum_when_cin1: assert property (
        @(posedge clk) (CIN == 1'b1) |-> (SUM == (A ^ B))
    );

// When CIN==0, SUM equals ~(A ^ B).
    check_sum_when_cin0: assert property (
        @(posedge clk) (CIN == 1'b0) |-> (SUM == ~(A ^ B))
    );

// When A == B, SUM equals ~CIN.
    check_sum_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (SUM == ~CIN)
    );

// When A != B, SUM equals CIN.
    check_sum_when_a_ne_b: assert property (
        @(posedge clk) (A != B) |-> (SUM == CIN)
    );

// COUT equals (A & B) | (A & ~CIN) | (B & ~CIN).
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// When CIN==1, COUT equals A & B.
    check_cout_when_cin1: assert property (
        @(posedge clk) (CIN == 1'b1) |-> (COUT == (A & B))
    );

// When CIN==0, COUT equals A | B.
    check_cout_when_cin0: assert property (
        @(posedge clk) (CIN == 1'b0) |-> (COUT == (A | B))
    );

// When A==0 and B==0, COUT is 0.
    check_cout_ab00_zero: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (COUT == 1'b0)
    );

// When A==1 and B==1, COUT is 1.
    check_cout_ab11_one: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (COUT == 1'b1)
    );

// When A==0 and B==1, COUT equals ~CIN.
    check_cout_a0b1: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b1)) |-> (COUT == ~CIN)
    );

// When A==1 and B==0, COUT equals ~CIN.
    check_cout_a1b0: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b0)) |-> (COUT == ~CIN)
    );

///// Magnitude comparison encoding /////
    // 'out' matches the ternary mapping of a and b.
    check_functional_equivalence: assert property (
        @(posedge CLK) out == ((a > b) ? 2'b01 : (a < b) ? 2'b10 : 2'b00)
    );

// out[0] is 1 iff a > b.
    check_out0_maps_gt: assert property (
        @(posedge CLK) out[0] == (a > b)
    );

// out[1] is 1 iff a < b.
    check_out1_maps_lt: assert property (
        @(posedge CLK) out[1] == (a < b)
    );

// out never takes invalid value 2'b11.
    check_out_not_11: assert property (
        @(posedge CLK) out != 2'b11
    );

// If a > b then out must be 2'b01.
    check_gt_implies_out01: assert property (
        @(posedge CLK) (a > b) |-> (out == 2'b01)
    );

// If a < b then out must be 2'b10.
    check_lt_implies_out10: assert property (
        @(posedge CLK) (a < b) |-> (out == 2'b10)
    );

// If a == b then out must be 2'b00.
    check_eq_implies_out00: assert property (
        @(posedge CLK) (a == b) |-> (out == 2'b00)
    );

// If out is 2'b01 then a must be > b.
    check_out01_implies_gt: assert property (
        @(posedge CLK) (out == 2'b01) |-> (a > b)
    );

// If out is 2'b10 then a must be < b.
    check_out10_implies_lt: assert property (
        @(posedge CLK) (out == 2'b10) |-> (a < b)
    );

// If out is 2'b00 then a must equal b.
    check_out00_implies_eq: assert property (
        @(posedge CLK) (out == 2'b00) |-> (a == b)
    );

// Output equals XOR of inputs.
    check_out_matches_xor: assert property (
        @(posedge CLK) out_if_else == (a ^ b)
    );

// Output is 1 when inputs differ.
    check_out_one_when_inputs_differ: assert property (
        @(posedge CLK) (a != b) |-> (out_if_else == 1'b1)
    );

// Output is 0 when inputs are equal.
    check_out_zero_when_inputs_equal: assert property (
        @(posedge CLK) (a == b) |-> (out_if_else == 1'b0)
    );

// X implements X = A | ~SLEEP_B.
    check_function_equation: assert property (
        @(posedge clk) X == (A | (~SLEEP_B))
    );

// When SLEEP_B is LOW, X must be HIGH.
    check_sleep_forces_high: assert property (
        @(posedge clk) (SLEEP_B == 1'b0) |-> (X == 1'b1)
    );

// When SLEEP_B is HIGH, X must equal A.
    check_awake_pass_through: assert property (
        @(posedge clk) (SLEEP_B == 1'b1) |-> (X == A)
    );

// When SLEEP_B is HIGH and A is LOW, X must be LOW.
    check_awake_low_results_low: assert property (
        @(posedge clk) (SLEEP_B == 1'b1 && A == 1'b0) |-> (X == 1'b0)
    );

// When SLEEP_B is HIGH and A is HIGH, X must be HIGH.
    check_awake_high_results_high: assert property (
        @(posedge clk) (SLEEP_B == 1'b1 && A == 1'b1) |-> (X == 1'b1)
    );

// On A rising while SLEEP_B is HIGH, X must be HIGH in the same cycle.
    check_rise_A_awake: assert property (
        @(posedge clk) (SLEEP_B == 1'b1 && $rose(A)) |-> (X == 1'b1)
    );

// On A falling while SLEEP_B is HIGH, X must be LOW in the same cycle.
    check_fall_A_awake: assert property (
        @(posedge clk) (SLEEP_B == 1'b1 && $fell(A)) |-> (X == 1'b0)
    );

// On SLEEP_B falling, X must be forced HIGH in the same cycle.
    check_sleepb_fall_forces_high: assert property (
        @(posedge clk) $fell(SLEEP_B) |-> (X == 1'b1)
    );

// On SLEEP_B rising, X must equal A in the same cycle.
    check_sleepb_rise_restores_passthrough: assert property (
        @(posedge clk) $rose(SLEEP_B) |-> (X == A)
    );

// If X is LOW, then A is LOW and SLEEP_B is HIGH.
    check_zero_output_implies_inputs_zero: assert property (
        @(posedge clk) (X == 1'b0) |-> ((A == 1'b0) && (SLEEP_B == 1'b1))
    );

// When VPWR is HIGH at posedge GATE, Q becomes 1 on the next cycle
    update_q_to_one_when_vpwr_high: assert property (
        @(posedge GATE) VPWR |=> (Q == 1'b1)
    );

// When VPWR is LOW and VGND is HIGH at posedge GATE, Q becomes 0 on the next cycle
    update_q_to_zero_when_vgnd_high_and_vpwr_low: assert property (
        @(posedge GATE) (!VPWR && VGND) |=> (Q == 1'b0)
    );

// When both rails are LOW and NOTIFIER is HIGH at posedge GATE, Q captures D on next cycle
    latch_d_when_rails_low_and_notifier_high: assert property (
        @(posedge GATE) (!VPWR && !VGND && NOTIFIER) |=> (Q == $past(D))
    );

// When both rails are LOW and NOTIFIER is LOW at posedge GATE, Q holds its previous value
    hold_q_when_no_controls_active: assert property (
        @(posedge GATE) (!VPWR && !VGND && !NOTIFIER) |=> (Q == $past(Q))
    );

// Clock: clk (posedge). No reset present. q is d delayed by 2 cycles.

    // Q equals D delayed by exactly 2 clock cycles.
    check_q_two_cycle_delay: assert property (
        @(posedge clk) 1'b1 |-> ##2 (q == $past(d, 2))
    );

// EN matches the combinational function of D[7:5].
    check_function_equivalence: assert property (
        @(posedge clk) EN == { (D[7] && !D[6] && !D[5]),
                               (!D[7] && D[6] && !D[5]),
                               (!D[7] && !D[6] && D[5]) }
    );

// EN is one-hot or zero at all times.
    check_en_is_onehot0: assert property (
        @(posedge clk) $onehot0(EN)
    );

// If none of D[7:5] are HIGH, EN must be 000.
    check_none_high_results_zero: assert property (
        @(posedge clk) (D[7:5] == 3'b000) |-> (EN == 3'b000)
    );

// If exactly one of D[7:5] is HIGH, EN mirrors D[7:5].
    check_onehot_maps_directly: assert property (
        @(posedge clk) $onehot(D[7:5]) |-> (EN == D[7:5])
    );

// If two or more of D[7:5] are HIGH, EN must be 000.
    check_multi_high_results_zero: assert property (
        @(posedge clk) ((D[7] & D[6]) | (D[7] & D[5]) | (D[6] & D[5])) |-> (EN == 3'b000)
    );

// EN[2]==1 implies D7=1, D6=0, D5=0.
    check_en2_implies_d7_only: assert property (
        @(posedge clk) EN[2] |-> (D[7] && !D[6] && !D[5])
    );

// EN[1]==1 implies D6=1, D7=0, D5=0.
    check_en1_implies_d6_only: assert property (
        @(posedge clk) EN[1] |-> (!D[7] && D[6] && !D[5])
    );

// EN[0]==1 implies D5=1, D7=0, D6=0.
    check_en0_implies_d5_only: assert property (
        @(posedge clk) EN[0] |-> (!D[7] && !D[6] && D[5])
    );

///// Reset behavior /////
    // When rst is HIGH at a clock edge, out must be 0.
    reset_forces_zero_now: assert property (
        @(posedge clk) rst |-> (out == 4'b0000)
    );

// On a rising edge of rst between clocks, out must be 0 at the next sample.
    reset_rise_clears_out: assert property (
        @(posedge clk) $rose(rst) |-> (out == 4'b0000)
    );

///// Load and count behavior /////
    // With load asserted, next out equals previous load_value.
    next_on_load: assert property (
        @(posedge clk) disable iff (rst) load |=> (out == $past(load_value))
    );

// With en asserted and load deasserted, next out increments by 1 (mod 16).
    next_on_en_no_load: assert property (
        @(posedge clk) disable iff (rst) (en && !load) |=> (out == $past(out) + 4'd1)
    );

// With neither en nor load, out holds its previous value.
    hold_when_idle: assert property (
        @(posedge clk) disable iff (rst) (!en && !load) |=> (out == $past(out))
    );

// load has priority over en when both are HIGH.
    load_has_priority_over_en: assert property (
        @(posedge clk) disable iff (rst) (load && en) |=> (out == $past(load_value))
    );

// Increment from 4'hF wraps to 4'h0 when en is asserted and no load.
    wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (en && !load && (out == 4'hF)) |=> (out == 4'h0)
    );

// Reset drives count to 0 on the next rising edge.
    reset_clears_count_next: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// When count equals max_val (no reset), next value is 0.
    wrap_to_zero_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == max_val) |=> (count == 32'd0)
    );

// When count is not max_val (no reset), next value increments by 1.
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != max_val) |=> (count == $past(count) + 32'd1)
    );

// Next value function is exactly: (count==max_val) ? 0 : count+1 (no reset).
    deterministic_update: assert property (
        @(posedge clk) disable iff (rst) 1 |=> (count == (($past(count) == $past(max_val)) ? 32'd0 : $past(count) + 32'd1))
    );

// If not due to reset, a 0 value must come from prior equality to max or overflow.
    zero_implies_prev_eq_max_or_overflow: assert property (
        @(posedge clk) disable iff (rst) 1 |=> ((count == 32'd0 && !$past(rst)) -> ($past(count) == $past(max_val) || $past(count) == 32'hFFFF_FFFF))
    );

// If previous count was neither max_val nor 32'hFFFF_FFFF (no reset), next count is not 0.
    no_zero_without_eq_or_overflow: assert property (
        @(posedge clk) disable iff (rst) 1 |=> (($past(count) != $past(max_val) && $past(count) != 32'hFFFF_FFFF) -> (count != 32'd0))
    );

// Analysis: no reset; pure combinational always @(*); behavior is case-based bit permutation.

    // Result must equal data when shift_amount == 2'b00.
    check_shift00_identity: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

// Result must equal {data[3], data[0], data[1], data[2]} when shift_amount == 2'b01.
    check_shift01_permutation: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[3], data[0], data[1], data[2]})
    );

// Result must equal {data[2], data[3], data[0], data[1]} when shift_amount == 2'b10.
    check_shift10_permutation: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[2], data[3], data[0], data[1]})
    );

// Result must equal {data[1], data[2], data[3], data[0]} when shift_amount == 2'b11.
    check_shift11_permutation: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[1], data[2], data[3], data[0]})
    );

// Result must always equal the case-derived permutation for the current shift_amount.
    check_functional_equivalence: assert property (
        @(posedge clk)
            result == (
                (shift_amount == 2'b00) ? data :
                (shift_amount == 2'b01) ? {data[3], data[0], data[1], data[2]} :
                (shift_amount == 2'b10) ? {data[2], data[3], data[0], data[1]} :
                                          {data[1], data[2], data[3], data[0]}
            )
    );

// When select=0, out is the byte-reversed form of in.
    check_select0_byte_swap: assert property (
        @(posedge clk) disable iff (reset) (!select) |-> (out == {in[7:0], in[15:8], in[23:16], in[31:24]})
    );

// When select=0 and in is zero, out must be zero (byte-reversing zero yields zero).
    check_select0_zero_input_zero_output: assert property (
        @(posedge clk) disable iff (reset) (!select && (in == 32'b0)) |-> (out == 32'b0)
    );

///// Reset behavior /////
    // On reset, shift_reg is cleared to 0 by the next clock.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) reset |=> (shift_reg == 8'h00)
    );

// On reset, d_ff is cleared to 0 by the next clock.
    check_reset_clears_dff: assert property (
        @(posedge clk) reset |=> (d_ff == 1'b0)
    );

// On reset, out_signal is cleared to 0 by the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out_signal == 1'b0)
    );

// Y must always be driven to either VPWR or VGND.
    check_y_within_power_rails: assert property (
        @(posedge VPWR) (Y == VPWR) || (Y == VGND)
    );

// Y matches the RTL combinational definition selecting VPWR/VGND.
    check_y_matches_rtl_condition: assert property (
        @(posedge VPWR)
            Y == ( (((A & B) & C) | ((A & C) & ~B) | ((B & C) & ~A) | (~(A & B) & ~(A & C) & ~(B & C))) ? VPWR : VGND )
    );

// If no two inputs are HIGH, Y must be VPWR.
    check_y_vpwr_when_no_two_high: assert property (
        @(posedge VPWR) (~(A & B) && ~(A & C) && ~(B & C)) |-> (Y == VPWR)
    );

// If A and C are HIGH, Y must be VPWR (independent of B).
    check_y_vpwr_when_a_and_c: assert property (
        @(posedge VPWR) (A && C) |-> (Y == VPWR)
    );

// If B and C are HIGH and A is LOW, Y must be VPWR.
    check_y_vpwr_when_b_and_c_no_a: assert property (
        @(posedge VPWR) (B && C && !A) |-> (Y == VPWR)
    );

// If A and B are HIGH and C is LOW, Y must be VGND.
    check_y_vgnd_when_a_and_b_no_c: assert property (
        @(posedge VPWR) (A && B && !C) |-> (Y == VGND)
    );

// If all inputs are LOW, Y must be VPWR.
    check_y_vpwr_when_all_zero: assert property (
        @(posedge VPWR) (!A && !B && !C) |-> (Y == VPWR)
    );

// If all inputs are HIGH, Y must be VPWR.
    check_y_vpwr_when_all_one: assert property (
        @(posedge VPWR) (A && B && C) |-> (Y == VPWR)
    );

// If A is LOW and C is HIGH, Y must be VPWR (independent of B).
    check_y_vpwr_when_a0_c1: assert property (
        @(posedge VPWR) (!A && C) |-> (Y == VPWR)
    );

// If VPWR equals VGND, Y must equal that common value.
    check_y_equal_rail_when_rails_equal: assert property (
        @(posedge VPWR) (VPWR == VGND) |-> (Y == VPWR)
    );

// Output is the exact bitwise inversion of input.
    check_function_exact_inversion: assert property (
        @(posedge CLK) disable iff (1'b0) (Y === ~A)
    );

// Known input implies known output.
    check_known_input_implies_known_output: assert property (
        @(posedge CLK) disable iff (1'b0) (!$isunknown(A)) |-> (!$isunknown(Y))
    );

// Unknown input propagates to unknown output.
    check_x_propagation_from_input_to_output: assert property (
        @(posedge CLK) disable iff (1'b0) ($isunknown(A)) |-> ($isunknown(Y))
    );

// When both are known, A and Y must differ.
    check_when_known_they_differ: assert property (
        @(posedge CLK) disable iff (1'b0) ((!$isunknown(A)) && (!$isunknown(Y))) |-> (A !== Y)
    );

// Output is never driven to high-Z.
    check_output_never_highz: assert property (
        @(posedge CLK) disable iff (1'b0) (Y !== 1'bz)
    );

// DUT is purely combinational; no reset. Function: X = (~B1_N) | (A1 & A2).

    // X must equal (~B1_N) | (A1 & A2).
    check_function_equivalence: assert property (
        @(posedge clk) X == ((~B1_N) | (A1 & A2))
    );

// When B1_N is LOW, X must be HIGH.
    check_X_high_when_B1N_low: assert property (
        @(posedge clk) (B1_N == 1'b0) |-> (X == 1'b1)
    );

// When A1 and A2 are HIGH, X must be HIGH (independent of B1_N).
    check_X_high_when_A1A2_high: assert property (
        @(posedge clk) (A1 && A2) |-> (X == 1'b1)
    );

// If B1_N is HIGH and A1 is LOW, X must be LOW.
    check_X_low_when_B1N_high_A1_low: assert property (
        @(posedge clk) (B1_N && !A1) |-> (X == 1'b0)
    );

// If B1_N is HIGH and A2 is LOW, X must be LOW.
    check_X_low_when_B1N_high_A2_low: assert property (
        @(posedge clk) (B1_N && !A2) |-> (X == 1'b0)
    );

// If X is LOW, then B1_N is HIGH and not (A1 & A2).
    check_zero_implies_conditions: assert property (
        @(posedge clk) (X == 1'b0) |-> (B1_N && !(A1 && A2))
    );

// If X is HIGH, then B1_N is LOW or (A1 & A2) is HIGH.
    check_one_implies_conditions: assert property (
        @(posedge clk) (X == 1'b1) |-> ((~B1_N) || (A1 && A2))
    );

// When B1_N is HIGH, X must equal (A1 & A2).
    check_X_equals_A1A2_when_B1N_high: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (X == (A1 & A2))
    );

// X implements (~B1_N) | (A1 & A2).
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) X == ((~B1_N) | (A1 & A2))
    );

// B1_N low forces X high.
    check_b1n_low_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0) (B1_N == 1'b0) |-> (X == 1'b1)
    );

// With B1_N high, X equals A1 & A2.
    check_b1n_high_equals_and: assert property (
        @(posedge clk) disable iff (1'b0) (B1_N == 1'b1) |-> (X == (A1 & A2))
    );

// X low implies B1_N high and not (A1 & A2).
    check_x_low_implication: assert property (
        @(posedge clk) disable iff (1'b0) (X == 1'b0) |-> ((B1_N == 1'b1) && !(A1 && A2))
    );

// If B1_N high and X high, then both A1 and A2 are high.
    check_b1n_high_x_high_implies_both_as_high: assert property (
        @(posedge clk) disable iff (1'b0) ((B1_N == 1'b1) && (X == 1'b1)) |-> ((A1 == 1'b1) && (A2 == 1'b1))
    );

// A1 & A2 high guarantees X high.
    check_and_true_sets_x_high: assert property (
        @(posedge clk) disable iff (1'b0) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

// Both A1 and A2 low makes X equal ~B1_N.
    check_both_as_low_x_eq_not_b1n: assert property (
        @(posedge clk) disable iff (1'b0) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == (~B1_N))
    );

// With B1_N high and A1 low, X must be low.
    check_b1n_high_a1_low_clears_x: assert property (
        @(posedge clk) disable iff (1'b0) ((B1_N == 1'b1) && (A1 == 1'b0)) |-> (X == 1'b0)
    );

// With B1_N high and A2 low, X must be low.
    check_b1n_high_a2_low_clears_x: assert property (
        @(posedge clk) disable iff (1'b0) ((B1_N == 1'b1) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// X high implies (~B1_N) or (A1 & A2).
    check_x_high_implication: assert property (
        @(posedge clk) disable iff (1'b0) (X == 1'b1) |-> ((~B1_N) | (A1 & A2))
    );

// Out equals the combinational ternary function sel ? in1 : in0.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (!RESETn) out === (sel ? in1 : in0)
    );

// When sel is 0, out equals in0 in the same cycle.
    check_sel0_maps_to_in0: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 1'b0) |-> (out === in0)
    );

// When sel is 1, out equals in1 in the same cycle.
    check_sel1_maps_to_in1: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 1'b1) |-> (out === in1)
    );

// When in0 equals in1, out equals that value regardless of sel.
    check_equal_inputs_reflect_on_out: assert property (
        @(posedge CLK) disable iff (!RESETn) (in0 === in1) |-> (out === in0)
    );

// No clock/reset in DUT; this checker samples on external CLK.
    // Logic is purely combinational; key behavior: S == (A ^ B).

    // S must equal bitwise XOR of A and B (bus-level).
    check_sum_is_bitwise_xor: assert property (
        @(posedge CLK) S == (A ^ B)
    );

// Bit 0: S[0] equals A[0] XOR B[0].
    check_sum_bit0_is_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0])
    );

// Bit 1: S[1] equals A[1] XOR B[1].
    check_sum_bit1_is_xor: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1])
    );

// Bit 2: S[2] equals A[2] XOR B[2].
    check_sum_bit2_is_xor: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2])
    );

// Bit 3: S[3] equals A[3] XOR B[3].
    check_sum_bit3_is_xor: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3])
    );

// Bit 0: equal inputs imply sum bit is 0.
    check_bit0_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A[0] == B[0]) |-> (S[0] == 1'b0)
    );

// Bit 1: equal inputs imply sum bit is 0.
    check_bit1_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A[1] == B[1]) |-> (S[1] == 1'b0)
    );

// Bit 2: equal inputs imply sum bit is 0.
    check_bit2_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A[2] == B[2]) |-> (S[2] == 1'b0)
    );

// Bit 3: equal inputs imply sum bit is 0.
    check_bit3_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A[3] == B[3]) |-> (S[3] == 1'b0)
    );

// Bit 0: unequal inputs imply sum bit is 1.
    check_bit0_one_when_inputs_unequal: assert property (
        @(posedge CLK) (A[0] != B[0]) |-> (S[0] == 1'b1)
    );

// Bit 1: unequal inputs imply sum bit is 1.
    check_bit1_one_when_inputs_unequal: assert property (
        @(posedge CLK) (A[1] != B[1]) |-> (S[1] == 1'b1)
    );

// Bit 2: unequal inputs imply sum bit is 1.
    check_bit2_one_when_inputs_unequal: assert property (
        @(posedge CLK) (A[2] != B[2]) |-> (S[2] == 1'b1)
    );

// Bit 3: unequal inputs imply sum bit is 1.
    check_bit3_one_when_inputs_unequal: assert property (
        @(posedge CLK) (A[3] != B[3]) |-> (S[3] == 1'b1)
    );

///// Functional equivalence to comparisons /////
    // EQ must reflect (A == B).
    check_eq_definition: assert property (
        @(posedge CLK) EQ == (A == B)
    );

// GT must reflect (A > B).
    check_gt_definition: assert property (
        @(posedge CLK) GT == (A > B)
    );

// LT must reflect (A < B).
    check_lt_definition: assert property (
        @(posedge CLK) LT == (A < B)
    );

///// Output consistency /////
    // Exactly one of {EQ, GT, LT} is HIGH.
    check_outputs_onehot: assert property (
        @(posedge CLK) $onehot({EQ, GT, LT})
    );

// If not equal, exactly one of GT or LT is HIGH.
    check_not_eq_xor: assert property (
        @(posedge CLK) (!EQ) |-> (GT ^ LT)
    );

// Mux function: out equals a when sel==0, else equals b.
    check_mux_function: assert property (
        @(posedge clk) disable iff (1'b0) out == (sel ? b : a)
    );

// When sel is 0, out must match a.
    check_sel0_routes_a: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b0) |-> (out == a)
    );

// When sel is 1, out must match b.
    check_sel1_routes_b: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b1) |-> (out == b)
    );

// If both inputs are equal, out must equal that value regardless of sel.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) disable iff (1'b0) (a == b) |-> (out == a)
    );

// No clock or reset in DUT; pure combinational inverter: Y = ~A.

    // On A rising edge, Y must equal bitwise NOT of A.
    check_inversion_on_A_posedge: assert property (
        @(posedge A) (Y === ~A)
    );

// On A falling edge, Y must equal bitwise NOT of A.
    check_inversion_on_A_negedge: assert property (
        @(negedge A) (Y === ~A)
    );

// On Y rising edge, A must equal bitwise NOT of Y.
    check_inversion_on_Y_posedge: assert property (
        @(posedge Y) (A === ~Y)
    );

// On Y falling edge, A must equal bitwise NOT of Y.
    check_inversion_on_Y_negedge: assert property (
        @(negedge Y) (A === ~Y)
    );

// Sum equals a ^ b ^ cin.
    check_sum_xor3: assert property (
        @(posedge CLK) disable iff (!RESETn)
        sum == (a ^ b ^ cin)
    );

// Carry-out equals (a & b) | ((a ^ b) & cin).
    check_cout_logic: assert property (
        @(posedge CLK) disable iff (!RESETn)
        cout == ((a & b) | ((a ^ b) & cin))
    );

// With cin=0, sum equals a ^ b.
    check_sum_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b0) |-> (sum == (a ^ b))
    );

// With cin=0, carry equals a & b.
    check_cout_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b0) |-> (cout == (a & b))
    );

// With cin=1, sum equals ~(a ^ b).
    check_sum_when_cin1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b1) |-> (sum == ~(a ^ b))
    );

// With cin=1, carry equals (a & b) | (a ^ b).
    check_cout_when_cin1: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (cin == 1'b1) |-> (cout == ((a & b) | (a ^ b)))
    );

// If a & b is 1, carry must be 1.
    check_carry_when_ab: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (a & b) |-> (cout == 1'b1)
    );

// If cin=1 and a ^ b = 1, carry must be 1.
    check_carry_when_cin_and_axorb: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((cin == 1'b1) && (a ^ b)) |-> (cout == 1'b1)
    );

// When neither a&b nor (a^b)&cin is 1, carry must be 0.
    check_no_carry_sources: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (!((a & b) | ((a ^ b) & cin))) |-> (cout == 1'b0)
    );

// All-low inputs produce sum=0 and cout=0.
    check_all_zero_case: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((!a) && (!b) && (!cin)) |-> ((sum == 1'b0) && (cout == 1'b0))
    );

// All-high inputs produce sum=1 and cout=1.
    check_all_one_case: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (a && b && cin) |-> ((sum == 1'b1) && (cout == 1'b1))
    );

// Output equals XOR of inputs each cycle.
    check_out_eq_xor: assert property (
        @(posedge CLK) (out_lut == (a ^ b))
    );

// Truth table: 00 -> 0.
    check_case_00: assert property (
        @(posedge CLK) ({a,b} == 2'b00) |-> (out_lut == 1'b0)
    );

// Truth table: 01 -> 1.
    check_case_01: assert property (
        @(posedge CLK) ({a,b} == 2'b01) |-> (out_lut == 1'b1)
    );

// Truth table: 10 -> 1.
    check_case_10: assert property (
        @(posedge CLK) ({a,b} == 2'b10) |-> (out_lut == 1'b1)
    );

// Truth table: 11 -> 0.
    check_case_11: assert property (
        @(posedge CLK) ({a,b} == 2'b11) |-> (out_lut == 1'b0)
    );

// When b is 0, output passes a.
    check_b0_passthrough: assert property (
        @(posedge CLK) (b == 1'b0) |-> (out_lut == a)
    );

// When b is 1, output is inverted a.
    check_b1_invert: assert property (
        @(posedge CLK) (b == 1'b1) |-> (out_lut == ~a)
    );

// When a is 0, output passes b.
    check_a0_passthrough: assert property (
        @(posedge CLK) (a == 1'b0) |-> (out_lut == b)
    );

// When a is 1, output is inverted b.
    check_a1_invert: assert property (
        @(posedge CLK) (a == 1'b1) |-> (out_lut == ~b)
    );

// eq must equal (a == b)
    check_eq_definition: assert property (
        @(posedge clk) (eq == (a == b))
    );

// gt must equal (a > b)
    check_gt_definition: assert property (
        @(posedge clk) (gt == (a > b))
    );

// lt must equal (a < b)
    check_lt_definition: assert property (
        @(posedge clk) (lt == (a < b))
    );

// Exactly one of {eq, gt, lt} is HIGH
    check_onehot_relation: assert property (
        @(posedge clk) ((eq + gt + lt) == 1)
    );

// If eq is HIGH, gt and lt must be LOW
    check_eq_exclusive: assert property (
        @(posedge clk) eq |-> (!gt && !lt)
    );

// If gt is HIGH, eq and lt must be LOW
    check_gt_exclusive: assert property (
        @(posedge clk) gt |-> (!eq && !lt)
    );

// If lt is HIGH, eq and gt must be LOW
    check_lt_exclusive: assert property (
        @(posedge clk) lt |-> (!eq && !gt)
    );

// If a equals b, outputs must be eq=1, gt=0, lt=0
    check_outputs_when_equal: assert property (
        @(posedge clk) (a == b) |-> (eq && !gt && !lt)
    );

// If a is greater than b, outputs must be gt=1, eq=0, lt=0
    check_outputs_when_greater: assert property (
        @(posedge clk) (a > b) |-> (gt && !eq && !lt)
    );

// If a is less than b, outputs must be lt=1, eq=0, gt=0
    check_outputs_when_less: assert property (
        @(posedge clk) (a < b) |-> (lt && !eq && !gt)
    );

///// Reset and stall behavior /////
    // On !cpu_stall and rst, all pipeline registers clear to 0 on next cycle.
    reset_clears_regs: assert property (
        @(posedge clk) (!cpu_stall && rst) |=> (p_c_rfw == 1'b0) && (p_c_wbsource == 2'b00) &&
                                           (p_alu_r == 32'b0) && (p_rf_waddr == 5'b0) &&
                                           (p_jalra == 32'b0) && (p_dout == 32'b0)
    );

// When cpu_stall is asserted, all pipeline registers hold their value.
    hold_regs_on_stall: assert property (
        @(posedge clk) disable iff (rst) cpu_stall |=> $stable({p_c_rfw, p_c_wbsource, p_alu_r, p_rf_waddr, p_jalra, p_dout})
    );

///// Register captures when enabled (!cpu_stall and !rst) /////
    // p_c_rfw captures ex_c_rfw on next cycle.
    capture_p_c_rfw: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_c_rfw == $past(ex_c_rfw))
    );

// p_c_wbsource captures ex_c_wbsource on next cycle.
    capture_p_c_wbsource: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_c_wbsource == $past(ex_c_wbsource))
    );

// p_alu_r captures ex_alu_r on next cycle.
    capture_p_alu_r: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_alu_r == $past(ex_alu_r))
    );

// p_rf_waddr captures ex_rf_waddr on next cycle.
    capture_p_rf_waddr: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_rf_waddr == $past(ex_rf_waddr))
    );

// p_jalra captures ex_jalra on next cycle.
    capture_p_jalra: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_jalra == $past(ex_jalra))
    );

// p_dout captures dmem_in on next cycle.
    capture_p_dout: assert property (
        @(posedge clk) disable iff (rst) (!cpu_stall) |=> (p_dout == $past(dmem_in))
    );

///// Combinational pass-throughs /////
    // dmem_addr is a pure pass-through of ex_alu_r.
    comb_dmem_addr_passthrough: assert property (
        @(posedge clk) disable iff (rst) dmem_addr == ex_alu_r
    );

// dmem_drw is a pure pass-through of ex_c_drw.
    comb_dmem_drw_passthrough: assert property (
        @(posedge clk) disable iff (rst) dmem_drw == ex_c_drw
    );

// dmem_data selects wb_wdata when forward, else ex_rfb.
    comb_dmem_data_forward_mux: assert property (
        @(posedge clk) disable iff (rst)
            dmem_data == ((p_c_rfw && (ex_rt == p_rf_waddr) && (p_rf_waddr != 5'd0)) ? wb_wdata : ex_rfb)
    );

// Analysis: no clock/reset; pure combinational; Y = (A & B) | (C & D); power pins unused by logic.

    // Y equals (A & B) | (C & D).
    check_function_posA: assert property (
        @(posedge A) Y === ((A & B) | (C & D))
    );

// Y must be 1 when A and B are both 1.
    check_y_high_when_ab11: assert property (
        @(posedge B) (A==1'b1 && B==1'b1) |-> (Y==1'b1)
    );

// Y must be 1 when C and D are both 1.
    check_y_high_when_cd11: assert property (
        @(posedge D) (C==1'b1 && D==1'b1) |-> (Y==1'b1)
    );

// Y must be 0 when B=0 and D=0.
    check_y_zero_when_b0_d0: assert property (
        @(posedge B) (B==1'b0 && D==1'b0) |-> (Y==1'b0)
    );

// When B=1 and C=0 and D=0, Y equals A.
    check_y_equals_a_when_b1_cd00: assert property (
        @(posedge A) (B==1'b1 && C==1'b0 && D==1'b0) |-> (Y===A)
    );

// When D=1 and A=0 and B=0, Y equals C.
    check_y_equals_c_when_d1_ab00: assert property (
        @(posedge C) (D==1'b1 && A==1'b0 && B==1'b0) |-> (Y===C)
    );

// Y must be 0 when all inputs are 0.
    check_y_zero_all_zero: assert property (
        @(posedge A) (A==1'b0 && B==1'b0 && C==1'b0 && D==1'b0) |-> (Y==1'b0)
    );

// Y must be 1 when all inputs are 1.
    check_y_one_all_one: assert property (
        @(posedge A) (A==1'b1 && B==1'b1 && C==1'b1 && D==1'b1) |-> (Y==1'b1)
    );

// If A=0 and B=0, Y reduces to C & D.
    check_y_depends_on_cd_when_ab00: assert property (
        @(posedge A) (A==1'b0 && B==1'b0) |-> (Y === (C & D))
    );

// If C=0 and D=0, Y reduces to A & B.
    check_y_depends_on_ab_when_cd00: assert property (
        @(posedge C) (C==1'b0 && D==1'b0) |-> (Y === (A & B))
    );

// Clock: clk (posedge). No reset in RTL.
    // Sequential logic: count registered each clk; output_signal = count.
    // Behavior: output is 0..4 based on input; special cases 16'h0000 -> 0, 16'hFFFF -> 4; else based on input[3:0] consecutive 1s ending at bit 3.

    // Output value is always within 0..4 on the next cycle.
    check_output_range_0_to_4: assert property (
        @(posedge clk) 1'b1 |=> (output_signal inside {4'h0,4'h1,4'h2,4'h3,4'h4})
    );

// All-zero input drives 0 next cycle.
    check_all_zero_maps_to_zero: assert property (
        @(posedge clk) (input_signal == 16'h0000) |=> (output_signal == 4'h0)
    );

// All-one 16-bit input drives 4 next cycle.
    check_all_ones16_maps_to_four: assert property (
        @(posedge clk) (input_signal == 16'hFFFF) |=> (output_signal == 4'h4)
    );

// Lower nibble 1111 drives 4 next cycle.
    check_lower_nibble_1111_maps_to_four: assert property (
        @(posedge clk) (input_signal[3:0] == 4'hF) |=> (output_signal == 4'h4)
    );

// Lower nibble 1110 drives 3 next cycle.
    check_lower_nibble_1110_maps_to_three: assert property (
        @(posedge clk) ((input_signal[3:1] == 3'b111) && (input_signal[0] == 1'b0)) |=> (output_signal == 4'h3)
    );

// Lower nibble 11x? with b1==0 (i.e., b3=1,b2=1,b1=0) drives 2 next cycle.
    check_lower_nibble_110x_b1_0_maps_to_two: assert property (
        @(posedge clk) ((input_signal[3:2] == 2'b11) && (input_signal[1] == 1'b0)) |=> (output_signal == 4'h2)
    );

// Lower nibble 10xx (b3=1,b2=0) drives 1 next cycle.
    check_lower_nibble_10xx_maps_to_one: assert property (
        @(posedge clk) ((input_signal[3] == 1'b1) && (input_signal[2] == 1'b0)) |=> (output_signal == 4'h1)
    );

// If b3 is 0, output is 0 next cycle.
    check_b3_zero_maps_to_zero: assert property (
        @(posedge clk) (input_signal[3] == 1'b0) |=> (output_signal == 4'h0)
    );

// Reset sets Q to zero on the next cycle.
    check_reset_clears_q_next: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

// While reset stays asserted, Q remains zero.
    check_hold_zero_while_reset: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (Q == 4'b0000)
    );

// Step size each cycle is 0, +1, or -1 (modulo 16) when not in reset.
    check_step_bounded_no_reset: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> ((Q == $past(Q)) || (Q == $past(Q) + 1'b1) || (Q == $past(Q) - 1'b1))
    );

// X equals A OR B OR C OR (~D_N).
    check_func_equiv: assert property (
        @(posedge CLK) X === (A | B | C | ~D_N)
    );

// If A is 1 then X is 1.
    check_a_one_implies_x_one: assert property (
        @(posedge CLK) (A === 1'b1) |-> (X === 1'b1)
    );

// If B is 1 then X is 1.
    check_b_one_implies_x_one: assert property (
        @(posedge CLK) (B === 1'b1) |-> (X === 1'b1)
    );

// If C is 1 then X is 1.
    check_c_one_implies_x_one: assert property (
        @(posedge CLK) (C === 1'b1) |-> (X === 1'b1)
    );

// If D_N is 0 then X is 1.
    check_dn_zero_implies_x_one: assert property (
        @(posedge CLK) (D_N === 1'b0) |-> (X === 1'b1)
    );

// If A,B,C are 0 and D_N is 1 then X is 0.
    check_all_zero_and_dn_one_implies_x_zero: assert property (
        @(posedge CLK) ((A === 1'b0) && (B === 1'b0) && (C === 1'b0) && (D_N === 1'b1)) |-> (X === 1'b0)
    );

// If X is 0 then A,B,C are 0 and D_N is 1.
    check_x_zero_implies_inputs_zero_dn_one: assert property (
        @(posedge CLK) (X === 1'b0) |-> ((A === 1'b0) && (B === 1'b0) && (C === 1'b0) && (D_N === 1'b1))
    );

// If X is 1 and D_N is 1 then at least one of A,B,C is 1.
    check_x_one_dn_one_requires_abc_one: assert property (
        @(posedge CLK) ((X === 1'b1) && (D_N === 1'b1)) |-> ((A === 1'b1) || (B === 1'b1) || (C === 1'b1))
    );

// If X is 1 and A,B,C are 0 then D_N is 0.
    check_x_one_with_abc_zero_requires_dn_zero: assert property (
        @(posedge CLK) ((X === 1'b1) && (A === 1'b0) && (B === 1'b0) && (C === 1'b0)) |-> (D_N === 1'b0)
    );

// If A,B,C are 0 then X equals ~D_N.
    check_abc_zero_links_x_to_not_dn: assert property (
        @(posedge CLK) ((A === 1'b0) && (B === 1'b0) && (C === 1'b0)) |-> (X === (~D_N))
    );

// If D_N is 1 then X equals A|B|C.
    check_dn_one_links_x_to_abc_or: assert property (
        @(posedge CLK) (D_N === 1'b1) |-> (X === (A | B | C))
    );

// Q_N is always the complement of Q.
    check_qn_complement: assert property (
        @(posedge CLK) Q_N == ~Q
    );

// Backpressure passthrough: in_ready mirrors out_ready.
    check_in_ready_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) in_ready == out_ready
    );

// Data payload passes through unchanged.
    check_data_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_data == in_data
    );

// Start-of-packet passes through unchanged.
    check_sop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_startofpacket == in_startofpacket
    );

// End-of-packet passes through unchanged.
    check_eop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_endofpacket == in_endofpacket
    );

// out_valid equals in_valid when channel <= MAX; otherwise 0.
    check_out_valid_definition: assert property (
        @(posedge clk) disable iff (!reset_n) out_valid == (in_valid && (in_channel <= MAX_CHANNEL))
    );

// Clock: clk; Reset: rst_l (active-low, asynchronous)
    // Logic: sequential DFF with async reset and scan mux; so mirrors q

    // so must always mirror q (continuous assign)
    so_mirrors_q: assert property (
        @(posedge clk) so == q
    );

// While reset is asserted low, q must be all zeros
    reset_low_forces_q_zero: assert property (
        @(posedge clk) !rst_l |-> (q == {SIZE{1'b0}})
    );

// While reset is asserted low, so must be all zeros (since so==q)
    reset_low_forces_so_zero: assert property (
        @(posedge clk) !rst_l |-> (so == {SIZE{1'b0}})
    );

// One cycle after reset was low, q must still be all zeros
    q_zero_one_cycle_after_reset_low: assert property (
        @(posedge clk) $past(!rst_l) |-> (q == {SIZE{1'b0}})
    );

// One cycle after reset was low, so must still be all zeros
    so_zero_one_cycle_after_reset_low: assert property (
        @(posedge clk) $past(!rst_l) |-> (so == {SIZE{1'b0}})
    );

// With se=1 (scan), q loads si on the next cycle
    capture_si_when_se: assert property (
        @(posedge clk) disable iff (!rst_l) se |=> (q == $past(si))
    );

// With se=0 (functional), q loads din on the next cycle
    capture_din_when_not_se: assert property (
        @(posedge clk) disable iff (!rst_l) !se |=> (q == $past(din))
    );

// General mux behavior: q next equals prior selected input when not in reset
    selected_mux_update: assert property (
        @(posedge clk) disable iff (!rst_l) 1 |=> (q == $past(se ? si : din))
    );

// Clock: posedge clk. Logic: mixed (combinational next-state + sequential regs).

    ///// Reset behavior /////
    // new_data must be LOW during reset.
    check_reset_new_data_low: assert property (
        @(posedge clk) rst |-> (new_data == 1'b0)
    );

// data holds its value during reset.
    check_reset_data_stable: assert property (
        @(posedge clk) rst |-> $stable(data)
    );

///// Functional mapping /////
    // out equals sum of high and low nibbles of in (4-bit wrap).
    check_functional_sum: assert property (
        @(posedge clk) out == (in[15:12] + in[3:0])
    );

// When disabled, output must be 0.
    check_disabled_drives_zero: assert property (
        @(posedge CLK) (!EN) |-> (Y == 1'b0)
    );

// When enabled and SEL==00, output selects D[0].
    check_enabled_sel00_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b00)) |-> (Y == D[0])
    );

// When enabled and SEL==01, output selects D[1].
    check_enabled_sel01_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b01)) |-> (Y == D[1])
    );

// When enabled and SEL==10, output selects D[2].
    check_enabled_sel10_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b10)) |-> (Y == D[2])
    );

// When enabled and SEL==11, output selects D[3].
    check_enabled_sel11_maps: assert property (
        @(posedge CLK) (EN && (SEL == 2'b11)) |-> (Y == D[3])
    );

// On falling edge of EN, output must be 0 in the same cycle.
    check_en_fall_forces_zero: assert property (
        @(posedge CLK) $fell(EN) |-> (Y == 1'b0)
    );

// Output equals bitwise inversion of input on clkin rising edge.
    check_inversion_pos: assert property (
        @(posedge clkin) clkout === ~clkin
    );

// Output equals bitwise inversion of input on clkin falling edge.
    check_inversion_neg: assert property (
        @(negedge clkin) clkout === ~clkin
    );

// A 0->1 transition on clkin causes a 1->0 transition on clkout.
    rise_in_fall_out: assert property (
        @(posedge clkin) $rose(clkin) |-> $fell(clkout)
    );

// A 1->0 transition on clkin causes a 0->1 transition on clkout.
    fall_in_rise_out: assert property (
        @(negedge clkin) $fell(clkin) |-> $rose(clkout)
    );

// At clkin rising edge, clkout must differ from clkin.
    not_equal_posedge: assert property (
        @(posedge clkin) clkout !== clkin
    );

// At clkin falling edge, clkout must differ from clkin.
    not_equal_negedge: assert property (
        @(negedge clkin) clkout !== clkin
    );

// Output equals selected input functionally every cycle.
    check_mux_function_equivalence: assert property (
        @(posedge CLK) out == (sel ? b : a)
    );

// When sel=0, out mirrors a.
    check_route_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == a)
    );

// When sel=1, out mirrors b.
    check_route_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == b)
    );

// On sel rising edge, out equals b immediately.
    check_sel_rise_routes_b_now: assert property (
        @(posedge CLK) $rose(sel) |-> (out == b)
    );

// On sel falling edge, out equals a immediately.
    check_sel_fall_routes_a_now: assert property (
        @(posedge CLK) $fell(sel) |-> (out == a)
    );

// Clocks: none in RTL (assertions sample on CLK). Reset: none. Logic: purely combinational.

    // data_out equals left or right shift of data_in per shift_direction
    check_functional_equation: assert property (
        @(posedge CLK) data_out == (shift_direction ? (data_in >> shift_amount) : (data_in << shift_amount))
    );

// Zero shift is a passthrough
    check_zero_shift_passthrough: assert property (
        @(posedge CLK) (shift_amount == 4'd0) |-> (data_out == data_in)
    );

// Left shift by 1 produces {data_in[14:0], 1'b0}
    check_left_shift_by_1: assert property (
        @(posedge CLK) (shift_direction == 1'b0 && shift_amount == 4'd1) |-> (data_out == {data_in[14:0], 1'b0})
    );

// Right shift by 1 produces {1'b0, data_in[15:1]}
    check_right_shift_by_1: assert property (
        @(posedge CLK) (shift_direction == 1'b1 && shift_amount == 4'd1) |-> (data_out == {1'b0, data_in[15:1]})
    );

// Left shift by 15 moves bit 0 to MSB and zeros others
    check_left_shift_by_15: assert property (
        @(posedge CLK) (shift_direction == 1'b0 && shift_amount == 4'd15) |-> (data_out == {data_in[0], 15'b0})
    );

// Right shift by 15 moves MSB to LSB and zeros others
    check_right_shift_by_15: assert property (
        @(posedge CLK) (shift_direction == 1'b1 && shift_amount == 4'd15) |-> (data_out == {15'b0, data_in[15]})
    );

// Shifting zero always yields zero
    check_zero_input_results_zero: assert property (
        @(posedge CLK) (data_in == 16'b0) |-> (data_out == 16'b0)
    );

// When S==0, Y equals A + B (4-bit wraparound).
    check_add_result_when_S0: assert property (
        @(posedge clk) (S == 1'b0) |-> (Y == (A + B))
    );

// When S==1, Y equals A - B (4-bit wraparound).
    check_sub_result_when_S1: assert property (
        @(posedge clk) (S == 1'b1) |-> (Y == (A - B))
    );

// If B is zero, Y must equal A regardless of S.
    check_passthrough_when_B_zero: assert property (
        @(posedge clk) (B == 4'h0) |-> (Y == A)
    );

// For subtraction with equal operands, result is zero.
    check_zero_when_A_eq_B_and_sub: assert property (
        @(posedge clk) (S == 1'b1 && A == B) |-> (Y == 4'h0)
    );

// Inverse identity for addition: (A+B)-B == A.
    check_add_inverse_identity: assert property (
        @(posedge clk) (S == 1'b0) |-> ((Y - B) == A)
    );

// Inverse identity for subtraction: (A-B)+B == A.
    check_sub_inverse_identity: assert property (
        @(posedge clk) (S == 1'b1) |-> ((Y + B) == A)
    );

// On S rising edge with stable A,B, Y reflects subtraction.
    check_y_on_rose_S_with_inputs_stable: assert property (
        @(posedge clk) ($rose(S) && $stable(A) && $stable(B)) |-> (Y == (A - B))
    );

// On S falling edge with stable A,B, Y reflects addition.
    check_y_on_fell_S_with_inputs_stable: assert property (
        @(posedge clk) ($fell(S) && $stable(A) && $stable(B)) |-> (Y == (A + B))
    );

// When adding equal operands, result LSB must be 0 (2*A mod 16 is even).
    check_even_result_when_S0_and_A_eq_B: assert property (
        @(posedge clk) (S == 1'b0 && A == B) |-> (Y[0] == 1'b0)
    );

// Overall 5-bit sum equals A + B + Cin.
    adder_sum_correct: assert property (
        @(posedge CLK) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// LSB sum is XOR of A[0], B[0], and Cin.
    sum_bit0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit1 sum uses c0 as carry in.
    sum_bit1_xor_with_c0: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ c0)
    );

// Bit2 sum uses c1 as carry in.
    sum_bit2_xor_with_c1: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ c1)
    );

// Bit3 sum uses c2 as carry in.
    sum_bit3_xor_with_c2: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ c2)
    );

// Cout equals the final carry c3.
    cout_equals_c3: assert property (
        @(posedge CLK) Cout == c3
    );

// Vector sum equals A ^ B ^ carry_in for each bit.
    sum_vector_xor_correct: assert property (
        @(posedge CLK) S == (A ^ B ^ carry_in_vec)
    );

// If B==0 and Cin==0, output equals A and no carry.
    identity_when_B_zero_and_Cin_zero: assert property (
        @(posedge CLK) (B == 4'b0000 && Cin == 1'b0) |-> (S == A && Cout == 1'b0)
    );

// If A==0 and Cin==0, output equals B and no carry.
    identity_when_A_zero_and_Cin_zero: assert property (
        @(posedge CLK) (A == 4'b0000 && Cin == 1'b0) |-> (S == B && Cout == 1'b0)
    );

// If A==0 and B==0, S reflects Cin in LSB and Cout==0.
    both_operands_zero_behavior: assert property (
        @(posedge CLK) (A == 4'b0000 && B == 4'b0000) |-> (S == {3'b000, Cin} && Cout == 1'b0)
    );

// Sum output must equal the RTL expression A + B + CIN (concatenated with COUT).
    check_sum_matches_rtl: assert property (
        @(posedge CLK) {COUT, S} == (A + B + CIN)
    );

// S must equal the low 4 bits of A + B + CIN per RTL.
    check_s_lower_bits: assert property (
        @(posedge CLK) S == (A + B + CIN)
    );

// If B and CIN are zero, output equals A with no carry (per RTL expression).
    check_identity_with_B_zero_CIN_zero: assert property (
        @(posedge CLK) (B == 4'b0000) && (CIN == 1'b0) |-> ({COUT, S} == {1'b0, A})
    );

// If A and CIN are zero, output equals B with no carry (per RTL expression).
    check_identity_with_A_zero_CIN_zero: assert property (
        @(posedge CLK) (A == 4'b0000) && (CIN == 1'b0) |-> ({COUT, S} == {1'b0, B})
    );

// If A and B are zero, S equals CIN in bit[0] and COUT is zero (per RTL expression).
    check_zero_plus_zero: assert property (
        @(posedge CLK) (A == 4'b0000) && (B == 4'b0000) |-> (S == {3'b000, CIN}) && (COUT == 1'b0)
    );

// Y implements the 4:1 mux boolean function of selects and data.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (!RESETn)
        Y == ((~S1 & ~S0 & A) | (~S1 & S0 & B) | (S1 & ~S0 & C) | (S1 & S0 & D))
    );

// When S1S0=00, Y equals A.
    check_sel00_routes_A: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b0 && S0==1'b0) |-> (Y == A)
    );

// When S1S0=01, Y equals B.
    check_sel01_routes_B: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b0 && S0==1'b1) |-> (Y == B)
    );

// When S1S0=10, Y equals C.
    check_sel10_routes_C: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b1 && S0==1'b0) |-> (Y == C)
    );

// When S1S0=11, Y equals D.
    check_sel11_routes_D: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (S1==1'b1 && S0==1'b1) |-> (Y == D)
    );

// EN[2] mirrors D[7] (highest priority)
    check_en2_mirrors_d7: assert property (
        @(posedge D[0]) disable iff (1'b0) (EN[2] == D[7])
    );

// EN[1] is set iff D[6] is 1 and D[7] is 0
    check_en1_priority: assert property (
        @(posedge D[0]) disable iff (1'b0) (EN[1] == (!D[7] && D[6]))
    );

// EN[0] is set iff D[5] is 1 and D[7:6] are 0
    check_en0_priority: assert property (
        @(posedge D[0]) disable iff (1'b0) (EN[0] == (!D[7] && !D[6] && D[5]))
    );

// EN is one-hot or zero
    check_en_onehot0: assert property (
        @(posedge D[0]) disable iff (1'b0) $onehot0(EN)
    );

// If D7 is 1, EN must be 3'b100
    check_d7_implies_en100: assert property (
        @(posedge D[0]) disable iff (1'b0) D[7] |-> (EN == 3'b100)
    );

// If D6 is 1 and D7 is 0, EN must be 3'b010
    check_d6_implies_en010: assert property (
        @(posedge D[0]) disable iff (1'b0) (!D[7] && D[6]) |-> (EN == 3'b010)
    );

// If only D5 among top bits is 1, EN must be 3'b001
    check_d5_implies_en001: assert property (
        @(posedge D[0]) disable iff (1'b0) (!D[7] && !D[6] && D[5]) |-> (EN == 3'b001)
    );

// If D[7:5]==3'b000, EN must be 3'b000
    check_none_implies_en000: assert property (
        @(posedge D[0]) disable iff (1'b0) (!D[7] && !D[6] && !D[5]) |-> (EN == 3'b000)
    );

// 00 with op=0 increments to 01.
    check_00_when_op0_increments: assert property (
        @(posedge CLK) (count_i == 2'b00) && (op == 1'b0) |-> (count == 2'b01)
    );

// 00 with op=1 saturates (holds at 00).
    check_00_when_op1_saturates: assert property (
        @(posedge CLK) (count_i == 2'b00) && (op == 1'b1) |-> (count == 2'b00)
    );

// 01 with op=0 increments to 10.
    check_01_when_op0_increments: assert property (
        @(posedge CLK) (count_i == 2'b01) && (op == 1'b0) |-> (count == 2'b10)
    );

// 01 with op=1 decrements to 00.
    check_01_when_op1_decrements: assert property (
        @(posedge CLK) (count_i == 2'b01) && (op == 1'b1) |-> (count == 2'b00)
    );

// 10 with op=0 decrements to 01.
    check_10_when_op0_decrements: assert property (
        @(posedge CLK) (count_i == 2'b10) && (op == 1'b0) |-> (count == 2'b01)
    );

// 10 with op=1 increments to 11.
    check_10_when_op1_increments: assert property (
        @(posedge CLK) (count_i == 2'b10) && (op == 1'b1) |-> (count == 2'b11)
    );

// 11 with op=0 decrements to 10.
    check_11_when_op0_decrements: assert property (
        @(posedge CLK) (count_i == 2'b11) && (op == 1'b0) |-> (count == 2'b10)
    );

// 11 with op=1 saturates (holds at 11).
    check_11_when_op1_saturates: assert property (
        @(posedge CLK) (count_i == 2'b11) && (op == 1'b1) |-> (count == 2'b11)
    );

// For mid values (01,10) output always differs from input.
    check_mid_values_always_change: assert property (
        @(posedge CLK) (count_i inside {2'b01,2'b10}) |-> (count != count_i)
    );

// Output is either equal or +/-1 from input (no multi-step or wrap beyond 1).
    check_output_step_or_hold_valid: assert property (
        @(posedge CLK) 1'b1 |-> ( (count == count_i) || (count == (count_i + 2'b01)) || (count == (count_i - 2'b01)) )
    );

// Holding output equals input only at bounds (00 or 11) with op=1.
    check_hold_only_at_bounds_with_op1: assert property (
        @(posedge CLK) (count == count_i) |-> ((count_i inside {2'b00,2'b11}) && (op == 1'b1))
    );

// Combinational function: X equals A AND SLEEP_B.
    check_functional_and: assert property (
        @(posedge CLK) (X == (A & SLEEP_B))
    );

// When SLEEP_B is LOW, X must be LOW.
    check_sleep_b_low_forces_low: assert property (
        @(posedge CLK) (!SLEEP_B) |-> (X == 1'b0)
    );

// When SLEEP_B is HIGH, X equals A.
    check_sleep_b_high_transparent: assert property (
        @(posedge CLK) (SLEEP_B) |-> (X == A)
    );

// When A is LOW, X must be LOW.
    check_a_low_forces_low: assert property (
        @(posedge CLK) (!A) |-> (X == 1'b0)
    );

// X HIGH implies both A and SLEEP_B are HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A && SLEEP_B)
    );

// X rising requires both A and SLEEP_B HIGH.
    check_x_rise_requires_enabled_and_a: assert property (
        @(posedge CLK) $rose(X) |-> (A && SLEEP_B)
    );

// X falling requires A LOW or SLEEP_B LOW.
    check_x_fall_requires_either_low: assert property (
        @(posedge CLK) $fell(X) |-> ((!A) || (!SLEEP_B))
    );

// On SLEEP_B rising, X equals A in the same cycle.
    check_enable_rise_sets_x_equal_a: assert property (
        @(posedge CLK) $rose(SLEEP_B) |-> (X == A)
    );

// On SLEEP_B falling, X is forced LOW in the same cycle.
    check_enable_fall_forces_x_low: assert property (
        @(posedge CLK) $fell(SLEEP_B) |-> (X == 1'b0)
    );

// With reset high and preset low, q is set to 1.
    check_preset_low_sets_one: assert property (
        @(posedge clk) disable iff (!reset) (!preset) |-> (q == 1'b1)
    );

// With both reset and preset high, q captures d.
    check_data_captured_when_enabled: assert property (
        @(posedge clk) disable iff (!reset) (preset) |-> (q == d)
    );

// On preset falling (becoming active) with reset high, q is set to 1.
    check_fall_preset_sets_one: assert property (
        @(posedge clk) disable iff (!reset) $fell(preset) |-> (q == 1'b1)
    );

// On preset rising with reset high, q is transparent to d.
    check_rise_preset_transparent: assert property (
        @(posedge clk) disable iff (!reset) $rose(preset) |-> (q == d)
    );

// If both reset and preset are high across two cycles and d is stable, q remains stable.
    check_stable_d_implies_stable_q_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (preset && $past(preset) && $past(reset) && $stable(d)) |-> $stable(q)
    );

// If both reset and preset are high across two cycles and d changes, q changes.
    check_data_change_propagates_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (preset && $past(preset) && $past(reset) && $changed(d)) |-> $changed(q)
    );

// Clock: clk; Reset: rst (active-high synchronous).
    // Logic: Mixed — sequential flop for q; combinational so = q.
    // Behavior: se has priority; else if rst, q<=0; else q<=din.

    // so always mirrors q.
    check_so_mirrors_q: assert property (
        @(posedge clk) disable iff (rst) (so == q)
    );

// Reset drives out to zero on the next clock.
  reset_clears_out_on_next: assert property (
    @(posedge clk) rst |=> (out == 8'h00)
  );

// When not in reset, next out equals previous out plus previous data_in (mod 256).
  accumulate_updates: assert property (
    @(posedge clk) disable iff (rst) 1 |=> (out == $past(out) + $past(data_in))
  );

// With zero input, out holds its value across the next clock.
  hold_when_data_zero: assert property (
    @(posedge clk) disable iff (rst) (data_in == 8'h00) |=> (out == $past(out))
  );

// With input 1, out increments by one on the next clock (mod 256).
  inc_by_one_when_data_one: assert property (
    @(posedge clk) disable iff (rst) (data_in == 8'h01) |=> (out == $past(out) + 8'h01)
  );

// With input 0xFF, out decrements by one on the next clock (mod 256).
  dec_by_one_when_data_ff: assert property (
    @(posedge clk) disable iff (rst) (data_in == 8'hFF) |=> (out == $past(out) + 8'hFF)
  );

// Explicit wrap: 0xFF plus 1 wraps to 0 on the next clock.
  wrap_ff_plus_one_to_zero: assert property (
    @(posedge clk) disable iff (rst) (out == 8'hFF && data_in == 8'h01) |=> (out == 8'h00)
  );

// ctrl=1: output is A + B
    check_add: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd1) |-> (data_out == (data_in_A + data_in_B))
    );

// ctrl=2: output is A - B
    check_sub: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd2) |-> (data_out == (data_in_A - data_in_B))
    );

// ctrl=3: output is A & B
    check_and: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd3) |-> (data_out == (data_in_A & data_in_B))
    );

// ctrl=4: output is A | B
    check_or: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd4) |-> (data_out == (data_in_A | data_in_B))
    );

// ctrl=5: output is A ^ B
    check_xor: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd5) |-> (data_out == (data_in_A ^ data_in_B))
    );

// ctrl=6: output is ~A
    check_not_a: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd6) |-> (data_out == (~data_in_A))
    );

// ctrl=7: output is ~B
    check_not_b: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd7) |-> (data_out == (~data_in_B))
    );

// ctrl=8: output is A << 1
    check_shl_a1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd8) |-> (data_out == (data_in_A << 1))
    );

// ctrl=9: output is A >> 1
    check_shr_a1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd9) |-> (data_out == (data_in_A >> 1))
    );

// ctrl=10: output is B << 1
    check_shl_b1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd10) |-> (data_out == (data_in_B << 1))
    );

// ctrl=11: output is B >> 1
    check_shr_b1: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd11) |-> (data_out == (data_in_B >> 1))
    );

// ctrl=12: output is (A==B) ? 1 : 0
    check_eq: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd12) |-> (data_out == ((data_in_A == data_in_B) ? 16'h0001 : 16'h0000))
    );

// ctrl=13: output is (A<B) ? 1 : 0
    check_lt: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd13) |-> (data_out == ((data_in_A < data_in_B) ? 16'h0001 : 16'h0000))
    );

// ctrl=14: output is (A>B) ? 1 : 0
    check_gt: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd14) |-> (data_out == ((data_in_A > data_in_B) ? 16'h0001 : 16'h0000))
    );

// ctrl=15: output is (A<=B) ? 1 : 0
    check_le: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd15) |-> (data_out == ((data_in_A <= data_in_B) ? 16'h0001 : 16'h0000))
    );

// ctrl=16: output is (A>=B) ? 1 : 0
    check_ge: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) (ctrl == 5'd16) |-> (data_out == ((data_in_A >= data_in_B) ? 16'h0001 : 16'h0000))
    );

// ctrl not in 1..16: output is 0
    check_default_zero: assert property (
        @(posedge ctrl[0]) disable iff (1'b0) ((ctrl == 5'd0) || (ctrl > 5'd16)) |-> (data_out == 16'h0000)
    );

// Combinational DUT with no reset; assertions are sampled on CLK.

    // When ctrl==00, result equals a+b (8-bit wrap-around).
    check_add_function: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (result == (a + b))
    );

// When ctrl==01, result equals a-b (8-bit wrap-around).
    check_sub_function: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (result == (a - b))
    );

// When ctrl==10, result equals a^b.
    check_xor_function: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (result == (a ^ b))
    );

// When ctrl==11, result is zero.
    check_default_zero: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (result == 8'h00)
    );

// Result matches the full case-expression behavior.
    check_case_equivalence: assert property (
        @(posedge CLK)
        result == ((ctrl == 2'b00) ? (a + b) :
                   (ctrl == 2'b01) ? (a - b) :
                   (ctrl == 2'b10) ? (a ^ b) :
                                     8'h00)
    );

// For XOR op, equal inputs yield zero.
    check_xor_equal_inputs_zero: assert property (
        @(posedge CLK) (ctrl == 2'b10 && (a == b)) |-> (result == 8'h00)
    );

// For XOR op, XOR with zero b returns a.
    check_xor_with_zero_b_returns_a: assert property (
        @(posedge CLK) (ctrl == 2'b10 && (b == 8'h00)) |-> (result == a)
    );

// For ADD op, adding zero b returns a.
    check_add_with_zero_b_returns_a: assert property (
        @(posedge CLK) (ctrl == 2'b00 && (b == 8'h00)) |-> (result == a)
    );

// For SUB op, equal inputs yield zero.
    check_sub_equal_inputs_zero: assert property (
        @(posedge CLK) (ctrl == 2'b01 && (a == b)) |-> (result == 8'h00)
    );

// o is the bitwise inversion of x.
    check_o_is_not_x: assert property (
        @(posedge clk) o == ~x
    );

// cfo is permanently 0.
    check_cfo_const_zero: assert property (
        @(posedge clk) cfo == 1'b0
    );

// ofo is permanently 0.
    check_ofo_const_zero: assert property (
        @(posedge clk) ofo == 1'b0
    );

// When x is all zeros, o is all ones.
    check_zero_x_allones_o: assert property (
        @(posedge clk) (x == 16'h0000) |-> (o == 16'hFFFF)
    );

// When x is all ones, o is all zeros.
    check_allones_x_zero_o: assert property (
        @(posedge clk) (x == 16'hFFFF) |-> (o == 16'h0000)
    );

// out must never be 11.
    check_out_never_11: assert property (
        @(posedge clk) !(out == 2'b11)
    );

// out[0] reflects (in1 > in2).
    check_bit0_matches_gt: assert property (
        @(posedge clk) out[0] == (in1 > in2)
    );

// out[1] reflects (in1 < in2).
    check_bit1_matches_lt: assert property (
        @(posedge clk) out[1] == (in1 < in2)
    );

// Output is always the bitwise inverse of input.
    check_inversion: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y === ~A)
    );

// No clock/reset in RTL; purely combinational. Sample checks on CLK.

    // out_xor equals bitwise XOR of inputs.
    check_out_xor_def: assert property (
        @(posedge CLK) out_xor == (in1 ^ in2)
    );

///// Priority encoder mapping /////
    // encoder_in 0001 -> encoder_out 00.
    encoder_map_0001: assert property (
        @(posedge clk) disable iff (reset) (encoder_in == 4'b0001) |-> (encoder_out == 2'b00)
    );

// encoder_in 0010 -> encoder_out 01.
    encoder_map_0010: assert property (
        @(posedge clk) disable iff (reset) (encoder_in == 4'b0010) |-> (encoder_out == 2'b01)
    );

// encoder_in 0100 -> encoder_out 10.
    encoder_map_0100: assert property (
        @(posedge clk) disable iff (reset) (encoder_in == 4'b0100) |-> (encoder_out == 2'b10)
    );

// encoder_in 1000 -> encoder_out 11.
    encoder_map_1000: assert property (
        @(posedge clk) disable iff (reset) (encoder_in == 4'b1000) |-> (encoder_out == 2'b11)
    );

// For any non-listed pattern, encoder_out is 00 (default case).
    encoder_map_default_otherwise_00: assert property (
        @(posedge clk) disable iff (reset)
            ((encoder_in != 4'b0001) && (encoder_in != 4'b0010) && (encoder_in != 4'b0100) && (encoder_in != 4'b1000))
            |-> (encoder_out == 2'b00)
    );

///// AND output behavior /////
    // and_out equals counter_out AND {2'b00, encoder_out}.
    and_out_matches_spec: assert property (
        @(posedge clk) disable iff (reset) (and_out == {2'b00, (counter_out[1:0] & encoder_out)})
    );

// Upper two bits of and_out are always zero.
    and_out_upper_bits_zero: assert property (
        @(posedge clk) disable iff (reset) (and_out[3:2] == 2'b00)
    );

// Clock: clk; Reset: rst_n active-low async; Logic: sequential reg with comb next-state captured on clk.
    // Behavior: On reset Q=64'h1; when rst_n=1, Q[0]=~$past(Q[63]), Q[62:1]=$past(Q[61:0]) ^ {62{$past(Q[63])}}, Q[63]=$past(Q[62]}.

    ///// Reset behavior /////
    // While reset is asserted, Q is forced to 64'h1.
    check_reset_value: assert property (
        @(posedge clk) !rst_n |-> (Q == 64'h0000_0000_0000_0001)
    );

// If reset stays asserted across cycles, Q remains 64'h1.
    check_reset_hold_value: assert property (
        @(posedge clk) (!rst_n && $past(!rst_n)) |-> (Q == 64'h0000_0000_0000_0001)
    );

// When previous MSB was 0, next Q[0] is 1.
    check_bit0_when_msb0: assert property (
        @(posedge clk) disable iff (!rst_n) ($past(Q[63]) == 1'b0) |-> (Q[0] == 1'b1)
    );

// When disabled, next pwm_out is 0.
  check_disable_forces_zero_next: assert property (
    @(posedge clk) (!enable) |=> (pwm_out == 8'h00)
  );

// A falling edge on enable forces next pwm_out to 0.
  check_enable_fall_clears_next: assert property (
    @(posedge clk) $fell(enable) |=> (pwm_out == 8'h00)
  );

// On reset, next cycle count must be zero.
    reset_clears_next: assert property (
        @(posedge CLK) reset |=> (count == 4'd0)
    );

// When disabled (and not in reset), hold value next cycle.
    hold_when_disabled: assert property (
        @(posedge CLK) disable iff (reset) (!enable) |=> (count == $past(count))
    );

// When enabled (and not in reset), increment by 1 next cycle (mod 16).
    increment_when_enabled: assert property (
        @(posedge CLK) disable iff (reset) enable |=> (count == $past(count) + 4'd1)
    );

// When enabled at max value, wrap to 0 next cycle.
    wrap_on_max: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// LSB toggles on each enabled increment.
    lsb_toggle_on_inc: assert property (
        @(posedge CLK) disable iff (reset) enable |=> (count[0] == ~$past(count[0]))
    );

// Bit1 toggles on increment when there is carry from bit0 (bit0 was 1).
    bit1_toggle_with_carry: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count[0] == 1'b1)) |=> (count[1] == ~$past(count[1]))
    );

// Bit1 holds on increment when there is no carry from bit0 (bit0 was 0).
    bit1_hold_without_carry: assert property (
        @(posedge CLK) disable iff (reset) (enable && (count[0] == 1'b0)) |=> (count[1] == $past(count[1]))
    );

// Two consecutive enables cause a net +2 after two cycles (mod 16).
    two_enables_add_two: assert property (
        @(posedge CLK) disable iff (reset) (enable ##1 enable) |=> (count == $past(count, 2) + 4'd2)
    );

// Two consecutive disables hold the value after two cycles.
    two_disables_hold: assert property (
        @(posedge CLK) disable iff (reset) ((!enable) ##1 (!enable)) |=> (count == $past(count, 2))
    );

// A rising edge of enable (no reset) causes a +1 next cycle.
    inc_on_enable_rise: assert property (
        @(posedge CLK) disable iff (reset) $rose(enable) |=> (count == $past(count) + 4'd1)
    );

// During reset, rs232_tx is driven HIGH.
    reset_value: assert property (
        @(posedge clk) !rst_n |-> (rs232_tx == 1'b1)
    );

// If last cycle sel_data and num==9, drive stop bit HIGH.
    update_stop_bit_num9: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(sel_data) && ($past(num) == 4'd9)) |-> (rs232_tx == 1'b1)
    );

// If last cycle sel_data and num>=10 (default), drive HIGH.
    update_default_high_num_ge_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(sel_data) && ($past(num) >= 4'd10)) |-> (rs232_tx == 1'b1)
    );

// Reset drives storage, out_valid, and out_data to zero on the next cycle.
    reset_initializes: assert property (
        @(posedge clk) reset |=> (stored_data == 32'h0) && (out_valid == 1'b0) && (out_data == 32'h0)
    );

// When in_valid is 1, out_valid is 1 on the next cycle.
    out_valid_set_on_valid: assert property (
        @(posedge clk) disable iff (reset) in_valid |=> out_valid
    );

// When in_valid is 0, out_valid is 0 on the next cycle.
    out_valid_clear_without_valid: assert property (
        @(posedge clk) disable iff (reset) !in_valid |=> !out_valid
    );

// When in_valid is 0, out_data holds its previous value.
    out_data_holds_without_valid: assert property (
        @(posedge clk) disable iff (reset) !in_valid |=> (out_data == $past(out_data))
    );

// On in_valid, out_data reflects the in_data from the previous cycle.
    out_data_reflects_input_on_valid: assert property (
        @(posedge clk) disable iff (reset) in_valid |=> (out_data == $past(in_data))
    );

// When n==0, output passes through input a.
    check_passthrough_when_n_zero: assert property (
        @(posedge CLK) (n == 5'd0) |-> (b == a)
    );

// When n>0, output equals a left-shifted by n.
    check_shift_when_n_positive: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b == (a << n))
    );

// When n>0, the lower n bits of b are zero after left shift.
    check_lower_bits_zero_after_shift: assert property (
        @(posedge CLK) (n > 5'd0) |-> ((b & (((32'h1 << n) - 32'h1))) == 32'h0)
    );

// When n>0, bit b[n] equals a[0] after left shift.
    check_bit_n_equals_a0: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b[n] == a[0])
    );

// When n>0, MSB of b equals a[31-n].
    check_msb_matches_source_bit: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b[31] == a[31 - n])
    );

// If n hypothetically exceeded 31, b would be forced to zero per RTL branch.
    check_large_n_forces_zero: assert property (
        @(posedge CLK) (n > 5'd31) |-> (b == 32'h0)
    );

// If a is zero, b is zero regardless of n.
    check_zero_input_produces_zero_output: assert property (
        @(posedge CLK) (a == 32'h0) |-> (b == 32'h0)
    );

// For n==31, b equals {a[0], 31'b0}.
    check_shift_by_31_behavior: assert property (
        @(posedge CLK) (n == 5'd31) |-> (b == {a[0], 31'b0})
    );

// DUT has no clock/reset; pure combinational datapath. Sample properties on external clk.
    // Function: out = (sub ? A - B : A + B).

    // Out matches selected operation for all input combinations.
    check_out_matches_operation: assert property (
        @(posedge clk) out == (sub ? (A - B) : (A + B))
    );

// In add mode, adding zero passes through A.
    check_add_zero_B: assert property (
        @(posedge clk) (sub == 1'b0 && B == 8'h00) |-> (out == A)
    );

// In add mode, adding zero-A passes through B.
    check_add_zero_A: assert property (
        @(posedge clk) (sub == 1'b0 && A == 8'h00) |-> (out == B)
    );

// In sub mode, subtracting zero passes through A.
    check_sub_zero_B: assert property (
        @(posedge clk) (sub == 1'b1 && B == 8'h00) |-> (out == A)
    );

// In sub mode, subtracting equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (sub == 1'b1 && (A == B)) |-> (out == 8'h00)
    );

// On sub rising edge with A,B stable, output equals A - B.
    check_out_on_sub_rise: assert property (
        @(posedge clk) ($rose(sub) && $stable(A) && $stable(B)) |-> (out == (A - B))
    );

// On sub falling edge with A,B stable, output equals A + B.
    check_out_on_sub_fall: assert property (
        @(posedge clk) ($fell(sub) && $stable(A) && $stable(B)) |-> (out == (A + B))
    );

// In add mode, addition is commutative with respect to A and B.
    check_add_commutative: assert property (
        @(posedge clk) (sub == 1'b0) |-> (out == (B + A))
    );

// Output matches A & B when A rises.
    check_z_on_A_posedge: assert property (
        @(posedge A) Z == (A & B)
    );

// Output matches A & B when A falls.
    check_z_on_A_negedge: assert property (
        @(negedge A) Z == (A & B)
    );

// Output matches A & B when B rises.
    check_z_on_B_posedge: assert property (
        @(posedge B) Z == (A & B)
    );

// Output matches A & B when B falls.
    check_z_on_B_negedge: assert property (
        @(negedge B) Z == (A & B)
    );

// TE high forces ENCLK low.
  check_te_forces_low: assert property (
    @(posedge CLK) TE |-> (ENCLK == 1'b0)
  );

// EN low forces ENCLK low (regardless of TE).
  check_en_low_forces_low: assert property (
    @(posedge CLK) !EN |-> (ENCLK == 1'b0)
  );

// When enabled and not in test, ENCLK mirrors CLK.
  check_enable_passes_clk: assert property (
    @(posedge CLK) (!TE && EN) |-> (ENCLK == CLK)
  );

// ENCLK high implies EN=1, TE=0, and CLK is high.
  check_enclk_high_implies_enable: assert property (
    @(posedge CLK) (ENCLK == 1'b1) |-> (EN && !TE && (CLK == 1'b1))
  );

// A rising TE immediately drives ENCLK low.
  check_te_rise_clears_enclk: assert property (
    @(posedge CLK) $rose(TE) |=> (ENCLK == 1'b0)
  );

// A falling EN immediately drives ENCLK low.
  check_en_fall_clears_enclk: assert property (
    @(posedge CLK) $fell(EN) |=> (ENCLK == 1'b0)
  );

// A rising EN with TE low immediately makes ENCLK equal to CLK.
  check_en_rise_passes_clk: assert property (
    @(posedge CLK) ($rose(EN) && !TE) |=> (ENCLK == CLK)
  );

// ENCLK can only rise when EN=1 and TE=0 (and CLK=1 at this sample).
  check_enclk_rise_requires_enable: assert property (
    @(posedge CLK) $rose(ENCLK) |-> (EN && !TE && (CLK == 1'b1))
  );

// Clock: clk (posedge). Reset: reset (active-high synchronous). Three-stage sequential pipeline.

    ///// Reset behavior ///// 
    // After a reset cycle, stage-1 regs clear to zero on the next clock.
    reset_clears_stage1: assert property (
        @(posedge clk) reset |=> (r_b == 20'b0) && (r_e == 20'b0)
    );

// After a reset cycle, stage-2 regs clear to zero on the next clock.
    reset_clears_stage2: assert property (
        @(posedge clk) reset |=> (r_c == 20'b0) && (rr_e == 20'b0) && (rr_b == 20'b0)
    );

// After a reset cycle, stage-3 reg and output clear to zero on the next clock.
    reset_clears_stage3_and_q: assert property (
        @(posedge clk) reset |=> (r_qx == 20'b0) && (q == 20'b0)
    );

// If reset is held for consecutive cycles, all pipeline regs and q remain zero.
    hold_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (r_b==20'b0) && (r_e==20'b0) && (r_c==20'b0) && (rr_e==20'b0) && (rr_b==20'b0) && (r_qx==20'b0) && (q==20'b0)
    );

// On D0 rising edge, mux output matches selected input.
    check_func_on_D0_rise: assert property (
        @(posedge D0[0]) (S == (ctrl ? D1 : D0))
    );

// On D0 falling edge, mux output matches selected input.
    check_func_on_D0_fall: assert property (
        @(negedge D0[0]) (S == (ctrl ? D1 : D0))
    );

// On D1 rising edge, mux output matches selected input.
    check_func_on_D1_rise: assert property (
        @(posedge D1[0]) (S == (ctrl ? D1 : D0))
    );

// On D1 falling edge, mux output matches selected input.
    check_func_on_D1_fall: assert property (
        @(negedge D1[0]) (S == (ctrl ? D1 : D0))
    );

// On S rising edge, mux output equals selected input.
    check_func_on_S_rise: assert property (
        @(posedge S[0]) (S == (ctrl ? D1 : D0))
    );

// On S falling edge, mux output equals selected input.
    check_func_on_S_fall: assert property (
        @(negedge S[0]) (S == (ctrl ? D1 : D0))
    );

// Exact functional equivalence to the RTL expression.
    check_function_equivalence: assert property (
        @(posedge CLK) Y == ((S0 | S1) ? ((S0 & S1) ? D : C) : ((S0 & ~S1) ? B : A))
    );

// When S1=0,S0=0, Y must equal A.
    check_sel_00_to_A: assert property (
        @(posedge CLK) (S1 == 1'b0 && S0 == 1'b0) |-> (Y == A)
    );

// When S1=0,S0=1, Y must equal C.
    check_sel_01_to_C: assert property (
        @(posedge CLK) (S1 == 1'b0 && S0 == 1'b1) |-> (Y == C)
    );

// When S1=1,S0=0, Y must equal C.
    check_sel_10_to_C: assert property (
        @(posedge CLK) (S1 == 1'b1 && S0 == 1'b0) |-> (Y == C)
    );

// When S1=1,S0=1, Y must equal D.
    check_sel_11_to_D: assert property (
        @(posedge CLK) (S1 == 1'b1 && S0 == 1'b1) |-> (Y == D)
    );

// When exactly one select is HIGH, Y must equal C.
    check_xor_select_to_C: assert property (
        @(posedge CLK) (S0 ^ S1) |-> (Y == C)
    );

// When any select is HIGH, Y must be C or D per S0&S1.
    check_or_select_rule: assert property (
        @(posedge CLK) (S0 | S1) |-> (Y == ((S0 & S1) ? D : C))
    );

// When both selects are LOW, Y must equal A.
    check_nor_select_to_A: assert property (
        @(posedge CLK) !(S0 | S1) |-> (Y == A)
    );

// Analysis:
    // - Clock: CLK (posedge)
    // - Reset: RESET_B active-low, asynchronous; forces Q=0
    // - Logic: Sequential D flip-flop with async reset; Q captures D on CLK rising edge when RESET_B==1

    ///// Reset behavior /////
    // Reset low forces Q=0 at every clock edge.
    check_reset_low_forces_q0: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

// Falling edge of RESET_B implies Q=0 at this clock.
    check_reset_fall_forces_q0: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

// Rising edge of RESET_B keeps Q=0 in this cycle (assignment to D occurs after this edge).
    check_reset_rise_keeps_q0: assert property (
        @(posedge CLK) $rose(RESET_B) |-> (Q == 1'b0)
    );

// While held in reset across cycles, Q stays stable.
    check_q_stable_while_in_reset: assert property (
        @(posedge CLK) ($past(RESET_B) == 1'b0 && RESET_B == 1'b0) |-> $stable(Q)
    );

// While held in reset across cycles, Q remains 0.
    check_q_zero_while_in_reset: assert property (
        @(posedge CLK) ($past(RESET_B) == 1'b0 && RESET_B == 1'b0) |-> (Q == 1'b0)
    );

///// Non-reset invariants /////
    // Q=1 implies reset is deasserted.
    check_q1_implies_reset_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) (Q == 1'b1) |-> (RESET_B == 1'b1)
    );

// No rising edge on Q in the first cycle after reset is deasserted.
    check_no_q_rise_just_after_reset: assert property (
        @(posedge CLK) disable iff (!RESET_B) ($past(RESET_B) == 1'b0) |-> (!$rose(Q))
    );

// No change on Q between cycles when reset stays asserted.
    check_no_q_change_across_held_reset: assert property (
        @(posedge CLK) ($past(RESET_B) == 1'b0 && RESET_B == 1'b0) |-> (Q == $past(Q))
    );

// Y equals NOR of A, B, C.
    check_func_nor3_output: assert property (
        @(posedge CLK) Y == ~(A | B | C)
    );

// Y HIGH implies all inputs LOW.
    check_y_high_implies_all_low: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (!A && !B && !C)
    );

// All inputs LOW implies Y HIGH.
    check_all_low_implies_y_high: assert property (
        @(posedge CLK) (!A && !B && !C) |-> (Y == 1'b1)
    );

// Any input HIGH implies Y LOW.
    check_any_high_implies_y_low: assert property (
        @(posedge CLK) (A || B || C) |-> (Y == 1'b0)
    );

// Rising A forces Y LOW in same cycle.
    check_roseA_causes_y_low: assert property (
        @(posedge CLK) $rose(A) |-> (Y == 1'b0)
    );

// Rising B forces Y LOW in same cycle.
    check_roseB_causes_y_low: assert property (
        @(posedge CLK) $rose(B) |-> (Y == 1'b0)
    );

// Rising C forces Y LOW in same cycle.
    check_roseC_causes_y_low: assert property (
        @(posedge CLK) $rose(C) |-> (Y == 1'b0)
    );

// A falling to 0 with B,C already 0 makes Y HIGH.
    check_fellA_others_zero_causes_y_high: assert property (
        @(posedge CLK) ($fell(A) && !B && !C) |-> (Y == 1'b1)
    );

// B falling to 0 with A,C already 0 makes Y HIGH.
    check_fellB_others_zero_causes_y_high: assert property (
        @(posedge CLK) ($fell(B) && !A && !C) |-> (Y == 1'b1)
    );

// C falling to 0 with A,B already 0 makes Y HIGH.
    check_fellC_others_zero_causes_y_high: assert property (
        @(posedge CLK) ($fell(C) && !A && !B) |-> (Y == 1'b1)
    );

// Output equals two's complement of input (mod 16).
  check_twos_complement_mapping: assert property (
    @(posedge clk) out == (~in + 4'b0001)
  );

// Two's complement is involutive: applying it to out yields in.
  check_involution: assert property (
    @(posedge clk) ((~out + 4'b0001) == in)
  );

// Zero input maps to zero output.
  check_zero_in_to_zero_out: assert property (
    @(posedge clk) (in == 4'b0000) |-> (out == 4'b0000)
  );

// Zero output implies zero input.
  check_zero_out_implies_zero_in: assert property (
    @(posedge clk) (out == 4'b0000) |-> (in == 4'b0000)
  );

// -8 (1000) is a fixed point under two's complement.
  check_neg8_fixed_point: assert property (
    @(posedge clk) (in == 4'b1000) |-> (out == 4'b1000)
  );

// Input and output sum to zero modulo 16.
  check_sum_zero_mod16: assert property (
    @(posedge clk) ((out + in) == 4'b0000)
  );

// Analysis: No clock/reset in RTL; purely combinational full adder: S=A^B^Ci, Co=(A&B)|((A^B)&Ci). Assertions sampled on CLK, gated by RESETn.

    // Sum equals three-input XOR of A, B, Ci.
    check_sum_is_xor3: assert property (
        @(posedge CLK) disable iff (!RESETn) S == (A ^ B ^ Ci)
    );

// Carry equals (A&B) | ((A^B)&Ci) as implemented.
    check_carry_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A & B) | ((A ^ B) & Ci))
    );

// Carry equals majority-of-three equivalent form.
    check_carry_majority_equiv: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A & B) | (A & Ci) | (B & Ci))
    );

// With Ci=0, sum reduces to A^B and carry to A&B.
    check_ci0_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b0) |-> ((S == (A ^ B)) && (Co == (A & B)))
    );

// With Ci=1, sum is XNOR of A and B; carry is A|B.
    check_ci1_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci == 1'b1) |-> ((S == !(A ^ B)) && (Co == (A | B)))
    );

// When A equals B, sum equals Ci; carry equals A&B.
    check_a_eq_b_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == B) |-> ((S == Ci) && (Co == (A & B)))
    );

// When A differs from B, sum is ~Ci and carry equals Ci.
    check_a_xor_b_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (A ^ B) |-> ((S == !Ci) && (Co == Ci))
    );

// If both A and B are 1, carry must be 1 and sum equals Ci.
    check_ab_both1_implies_carry: assert property (
        @(posedge CLK) disable iff (!RESETn) (A & B) |-> ((Co == 1'b1) && (S == Ci))
    );

// If Ci=1 and exactly one of A,B is 1, carry must be 1.
    check_ci_and_axorb_implies_carry: assert property (
        @(posedge CLK) disable iff (!RESETn) (Ci & (A ^ B)) |-> (Co == 1'b1)
    );

// All inputs zero produce S=0 and Co=0.
    check_all_zero_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (!(A | B | Ci)) |-> ((S == 1'b0) && (Co == 1'b0))
    );

// All inputs one produce S=1 and Co=1.
    check_all_one_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (A & B & Ci) |-> ((S == 1'b1) && (Co == 1'b1))
    );

///// Reset behavior /////
    // When reset is HIGH at a clock edge, count must be 0.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// On a sampled rising edge of reset, count is cleared to 0.
    reset_rise_clears_count: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd0)
    );

// While reset stays HIGH across cycles, count remains 0.
    hold_zero_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0)
    );

// If at max (15) in prior cycle, next value wraps to 0.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (!$past(rst) && ($past(count) == 4'hF)) |-> (count == 4'd0)
    );

// After 16 cycles with no reset, count returns to its prior value (mod-16).
    period_16_no_reset: assert property (
        @(posedge clk) disable iff (rst) (!rst)[*16] |=> (count == $past(count,16))
    );

// On reset, next cycle data_out is zero.
  reset_clears_output_next: assert property (
    @(posedge clk) reset |=> (data_out == 32'd0)
  );

// While reset stays asserted, data_out remains zero.
  hold_zero_during_reset: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (data_out == 32'd0)
  );

// When enabled (and not in reset), next data_out equals prior data_in.
  enable_loads_input_next: assert property (
    @(posedge clk) disable iff (reset) enable |=> (data_out == $past(data_in))
  );

// When disabled (and not in reset), next data_out holds prior value.
  hold_value_when_disabled: assert property (
    @(posedge clk) disable iff (reset) !enable |=> (data_out == $past(data_out))
  );

// With enable asserted in back-to-back cycles (no reset), output follows the second cycle's input.
  two_consecutive_enables_pipeline: assert property (
    @(posedge clk) disable iff (reset) (enable ##1 enable) |-> (data_out == $past(data_in, 1))
  );

// When A+B == 31, on a rise of carry_out the sum must be 15.
    check_sum_eq_15_when_ab_eq31: assert property (
        (({1'b0, A} + {1'b0, B}) == 5'd31) |-> (sum == 4'd15)
    );

// Clock: clk (posedge). Reset: rst (active-high async).
    // Behavior: load copies x into shiftreg and clears out; shift outputs LSB and shifts right with zero fill; rst clears state.

    ///// Reset behavior /////
    // If reset is sampled HIGH, next cycle shiftreg and out are zero.
    reset_clears_state: assert property (
        @(posedge clk) rst |=> (shiftreg == 64'd0) && (out == 1'b0)
    );

// While reset is held across consecutive cycles, state is held at zero.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (shiftreg == 64'd0) && (out == 1'b0)
    );

///// Load behavior /////
    // Load clears out on the next cycle.
    load_clears_out: assert property (
        @(posedge clk) disable iff (rst) ld |=> (out == 1'b0)
    );

///// Priority /////
    // When ld and shift are both HIGH, out follows ld behavior (clears to 0).
    ld_priority_out: assert property (
        @(posedge clk) disable iff (rst) (ld && shift) |=> (rst || (out == 1'b0))
    );

// Functional equivalence to NAND4 with inverted A_N.
    check_func_nand4b: assert property (
        @(posedge CLK) Y == ~(D & C & B & ~A_N)
    );

// Equivalent OR-of-literals form.
    check_func_or_form: assert property (
        @(posedge CLK) Y == (A_N | ~B | ~C | ~D)
    );

// A_N high forces Y high.
    check_an_high_forces_y_high: assert property (
        @(posedge CLK) A_N |-> (Y == 1'b1)
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );

// C low forces Y high.
    check_c_low_forces_y_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

// D low forces Y high.
    check_d_low_forces_y_high: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );

// Y low only when A_N low and B,C,D high.
    check_y_low_only_when_all_ones: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A_N == 1'b0 && B == 1'b1 && C == 1'b1 && D == 1'b1)
    );

// Rising A_N forces Y high.
    check_an_rise_forces_y_high: assert property (
        @(posedge CLK) $rose(A_N) |-> (Y == 1'b1)
    );

// Falling B forces Y high.
    check_b_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(B) |-> (Y == 1'b1)
    );

// Falling C forces Y high.
    check_c_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(C) |-> (Y == 1'b1)
    );

// Falling D forces Y high.
    check_d_fall_forces_y_high: assert property (
        @(posedge CLK) $fell(D) |-> (Y == 1'b1)
    );

// Falling A_N with B,C,D high forces Y low.
    check_an_fall_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($fell(A_N) && B && C && D) |-> (Y == 1'b0)
    );

// Rising B with A_N low and C,D high forces Y low.
    check_b_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(B) && (A_N == 1'b0) && C && D) |-> (Y == 1'b0)
    );

// Rising C with A_N low and B,D high forces Y low.
    check_c_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(C) && (A_N == 1'b0) && B && D) |-> (Y == 1'b0)
    );

// Rising D with A_N low and B,C high forces Y low.
    check_d_rise_with_others_one_forces_y_low: assert property (
        @(posedge CLK) ($rose(D) && (A_N == 1'b0) && B && C) |-> (Y == 1'b0)
    );

// F equals the RTL expression when sampled on A.
    check_function_equivalence_on_A: assert property (
        @(posedge A) F == ((~A & ~B) | (A & ~B) | (B & C))
    );

// F equals the RTL expression when sampled on B.
    check_function_equivalence_on_B: assert property (
        @(posedge B) F == ((~A & ~B) | (A & ~B) | (B & C))
    );

// F equals the RTL expression when sampled on C.
    check_function_equivalence_on_C: assert property (
        @(posedge C) F == ((~A & ~B) | (A & ~B) | (B & C))
    );

// F equals the simplified form ~B | (B & C) on A edges.
    check_simplified_equivalence_on_A: assert property (
        @(posedge A) F == ((~B) | (B & C))
    );

// If B is 0 then F must be 1 (A,C don't matter).
    check_B0_implies_F1_on_A: assert property (
        @(posedge A) (B != 1'b0) || (F == 1'b1)
    );

// If B is 1 then F equals C.
    check_B1_implies_F_eq_C_on_A: assert property (
        @(posedge A) (B != 1'b1) || (F == C)
    );

// If F is 0 then B must be 1 and C must be 0.
    check_F0_implies_B1C0_on_A: assert property (
        @(posedge A) (F != 1'b0) || ((B == 1'b1) && (C == 1'b0))
    );

// If B and C are 1 then F must be 1.
    check_B1C1_implies_F1_on_A: assert property (
        @(posedge A) (!((B == 1'b1) && (C == 1'b1))) || (F == 1'b1)
    );

// If B is 1 and C is 0 then F must be 0.
    check_B1C0_implies_F0_on_A: assert property (
        @(posedge A) (!((B == 1'b1) && (C == 1'b0))) || (F == 1'b0)
    );

// If F is 1 then (~B) or (B & C) must hold.
    check_F1_implies_minterms_on_A: assert property (
        @(posedge A) (F != 1'b1) || ((~B) || (B && C))
    );

///// Reset behavior /////
    // On reset assertion, all regs/counters/outputs are cleared and state is IDLE.
    check_reset_values: assert property (
        @(posedge clk50) !reset_n |-> (state == STATE_IDLE)
                                   && (act_cnt == 18'd0)
                                   && (leadvrf_cnt == 18'd0)
                                   && (datarcv_cnt == 18'd0)
                                   && (bits_detected == 6'd0)
                                   && (databuf == 32'h0000_0000)
                                   && (rpt_cnt == 23'd0)
                                   && (ir_code == 32'h0000_0000)
                                   && (ir_code_ack == 1'b0)
    );

// When ack is asserted, ir_code updates to prior databuf.
    check_code_updates_on_ack: assert property (
        @(posedge clk50) disable iff (!reset_n)
            (ir_code_ack) |-> (ir_code == $past(databuf))
    );

// On release timeout (when decode is not true), code and ack clear.
    check_release_clears_code_ack: assert property (
        @(posedge clk50) disable iff (!reset_n)
            ($past(rpt_cnt) >= RPT_RELEASE_THOLD
             && !(($past(bits_detected) == 6'd32) && ($past(databuf[15:8]) == ~ $past(databuf[7:0]))))
            |-> (ir_code == 32'h0000_0000 && ir_code_ack == 1'b0)
    );

// Bit3 is always 0.
    check_compout3_zero: assert property (
        @(posedge clk) (CompOut[3] == 1'b0)
    );

// Exactly one of CompOut[2:0] is 1.
    check_compout_onehot_2_0: assert property (
        @(posedge clk) $onehot(CompOut[2:0])
    );

// If Ain == Bin, CompOut encodes equals (0001).
    check_equal_drives_eq_code: assert property (
        @(posedge clk) (Ain == Bin) |-> (CompOut == 4'b0001)
    );

// If Ain > Bin, CompOut encodes greater (0010).
    check_greater_drives_gt_code: assert property (
        @(posedge clk) (Ain > Bin) |-> (CompOut == 4'b0010)
    );

// If Ain < Bin, CompOut encodes less (0100).
    check_less_drives_lt_code: assert property (
        @(posedge clk) (Ain < Bin) |-> (CompOut == 4'b0100)
    );

// If CompOut[0] is 1, inputs must be equal.
    check_eq_code_means_equal: assert property (
        @(posedge clk) (CompOut[0] == 1'b1) |-> (Ain == Bin)
    );

// If CompOut[1] is 1, Ain must be greater than Bin.
    check_gt_code_means_greater: assert property (
        @(posedge clk) (CompOut[1] == 1'b1) |-> (Ain > Bin)
    );

// If CompOut[2] is 1, Ain must be less than Bin.
    check_lt_code_means_less: assert property (
        @(posedge clk) (CompOut[2] == 1'b1) |-> (Ain < Bin)
    );

// On any clock after reset is high, value must be 0.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (value == 4'h0)
    );

// If reset stays asserted across consecutive clocks, value stays 0.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(reset) && reset) |-> (value == 4'h0)
    );

// When not in reset previously and value was 0xF, wrap to 0.
    wrap_when_max: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && ($past(value) == 4'hF) |-> (value == 4'h0)
    );

// Sanity: value is always within 4-bit range.
    value_within_range: assert property (
        @(posedge clk) 1'b1 |-> (value inside {[4'h0:4'hF]})
    );

// If num1 > num2, output must equal num1.
    check_larger_is_num1_when_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) (num1 > num2) |-> (larger == num1)
    );

// If num2 > num1, output must equal num2.
    check_larger_is_num2_when_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) (num2 > num1) |-> (larger == num2)
    );

// If num1 == num2, output must equal num1 (tie breaks to num1).
    check_larger_is_num1_when_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (num1 == num2) |-> (larger == num1)
    );

// Output must always equal one of the two inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) (larger == num1) || (larger == num2)
    );

// If output selects num1 and inputs differ, then num1 must be greater.
    check_num1_selected_implies_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) ((larger == num1) && (num1 != num2)) |-> (num1 > num2)
    );

// If output selects num2 and inputs differ, then num2 must be greater.
    check_num2_selected_implies_gt: assert property (
        @(posedge CLK) disable iff (!RESETn) ((larger == num2) && (num1 != num2)) |-> (num2 > num1)
    );

// Output value must be at least as large as each input (i.e., equals the max).
    check_output_is_at_least_each_input: assert property (
        @(posedge CLK) disable iff (!RESETn) (larger >= num1) && (larger >= num2)
    );

// When sel==15, dout equals din16.
    route_sel15_to_din16: assert property (
        @(posedge clk) (sel == 4'd15) |-> (dout == din16)
    );

// X equals ((A&B&C&D) || (E&F&G&H) || (I&J)).
    check_x_equals_expr: assert property (
        @(posedge clk) disable iff (1'b0) X == ((A && B && C && D) || (E && F && G && H) || (I && J))
    );

// If A&B&C&D are all 1, X must be 1.
    check_x_one_if_abcd: assert property (
        @(posedge clk) disable iff (1'b0) (A && B && C && D) |-> (X == 1'b1)
    );

// If E&F&G&H are all 1, X must be 1.
    check_x_one_if_efgh: assert property (
        @(posedge clk) disable iff (1'b0) (E && F && G && H) |-> (X == 1'b1)
    );

// If I&J are both 1, X must be 1.
    check_x_one_if_ij: assert property (
        @(posedge clk) disable iff (1'b0) (I && J) |-> (X == 1'b1)
    );

// If none of the enabling terms are true, X must be 0.
    check_x_zero_if_no_terms: assert property (
        @(posedge clk) disable iff (1'b0) !((A && B && C && D) || (E && F && G && H) || (I && J)) |-> (X == 1'b0)
    );

// If X is 1, at least one enabling term must be true.
    check_x_one_implies_some_term: assert property (
        @(posedge clk) disable iff (1'b0) (X == 1'b1) |-> ((A && B && C && D) || (E && F && G && H) || (I && J))
    );

// No clock or reset in DUT; combinational logic only. Sample on posedges of inputs.

    // Z equals (A >= B) when sampled on B's rising edge.
    check_func_eq_on_B: assert property (
        @(posedge B) Z == (A >= B)
    );

// Z equals (A >= B) when sampled on A[0]'s rising edge.
    check_func_eq_on_A0: assert property (
        @(posedge A[0]) Z == (A >= B)
    );

// Z equals (A >= B) when sampled on A[1]'s rising edge.
    check_func_eq_on_A1: assert property (
        @(posedge A[1]) Z == (A >= B)
    );

// If B is 0, Z must be 1 (A is unsigned and >= 0).
    check_b0_implies_z1: assert property (
        @(posedge A[0]) (B == 1'b0) |-> (Z == 1'b1)
    );

// If B is 1 and A is 0, Z must be 0 (0 >= 1 is false).
    check_b1_a0_implies_z0: assert property (
        @(posedge A[1]) (B == 1'b1 && A == 2'b00) |-> (Z == 1'b0)
    );

// If B is 1 and A != 0, Z must be 1 (A in {1,2,3} >= 1).
    check_b1_a_nonzero_implies_z1: assert property (
        @(posedge A[0]) (B == 1'b1 && A != 2'b00) |-> (Z == 1'b1)
    );

// SELECT==00 routes IN1 to OUT in the same cycle.
    check_sel00_routes_IN1: assert property (
        @(posedge CLK) (SELECT == 2'b00) |-> (OUT == IN1)
    );

// SELECT==01 routes IN2 to OUT in the same cycle.
    check_sel01_routes_IN2: assert property (
        @(posedge CLK) (SELECT == 2'b01) |-> (OUT == IN2)
    );

// SELECT==10 routes IN3 to OUT in the same cycle.
    check_sel10_routes_IN3: assert property (
        @(posedge CLK) (SELECT == 2'b10) |-> (OUT == IN3)
    );

// SELECT==11 routes IN4 to OUT in the same cycle.
    check_sel11_routes_IN4: assert property (
        @(posedge CLK) (SELECT == 2'b11) |-> (OUT == IN4)
    );

// When SELECT==00 and IN1 changes, OUT matches IN1 that same cycle.
    check_propagation_sel00: assert property (
        @(posedge CLK) (SELECT == 2'b00 && $changed(IN1)) |-> (OUT == IN1)
    );

// When SELECT==01 and IN2 changes, OUT matches IN2 that same cycle.
    check_propagation_sel01: assert property (
        @(posedge CLK) (SELECT == 2'b01 && $changed(IN2)) |-> (OUT == IN2)
    );

// When SELECT==10 and IN3 changes, OUT matches IN3 that same cycle.
    check_propagation_sel10: assert property (
        @(posedge CLK) (SELECT == 2'b10 && $changed(IN3)) |-> (OUT == IN3)
    );

// When SELECT==11 and IN4 changes, OUT matches IN4 that same cycle.
    check_propagation_sel11: assert property (
        @(posedge CLK) (SELECT == 2'b11 && $changed(IN4)) |-> (OUT == IN4)
    );

// EQ reflects A == B.
    check_eq_definition: assert property (
        @(posedge CLK) (EQ == (A == B))
    );

// GT reflects A > B.
    check_gt_definition: assert property (
        @(posedge CLK) (GT == (A > B))
    );

// LT reflects A < B.
    check_lt_definition: assert property (
        @(posedge CLK) (LT == (A < B))
    );

// When A == B, only EQ is high.
    check_eq_mapping: assert property (
        @(posedge CLK) (A == B) |-> (EQ && !GT && !LT)
    );

// When A > B, only GT is high.
    check_gt_mapping: assert property (
        @(posedge CLK) (A > B) |-> (GT && !EQ && !LT)
    );

// When A < B, only LT is high.
    check_lt_mapping: assert property (
        @(posedge CLK) (A < B) |-> (LT && !EQ && !GT)
    );

// Outputs are one-hot across EQ/GT/LT.
    check_outputs_onehot: assert property (
        @(posedge CLK) $onehot({EQ, GT, LT})
    );

// gray_out[0] equals in[0].
    check_gray0_is_in0: assert property (
        @(posedge clk) gray_out[0] == in[0]
    );

// gray_out[1] equals in[0] XOR in[1].
    check_gray1_is_in0_xor_in1: assert property (
        @(posedge clk) gray_out[1] == (in[0] ^ in[1])
    );

// gray_out[2] equals in[1] XOR in[2].
    check_gray2_is_in1_xor_in2: assert property (
        @(posedge clk) gray_out[2] == (in[1] ^ in[2])
    );

// gray_out[3] equals in[2] XOR in[3].
    check_gray3_is_in2_xor_in3: assert property (
        @(posedge clk) gray_out[3] == (in[2] ^ in[3])
    );

// Vector mapping: gray_out == {in[2]^in[3], in[1]^in[2], in[0]^in[1], in[0]}.
    check_vector_mapping: assert property (
        @(posedge clk) gray_out == { (in[2] ^ in[3]), (in[1] ^ in[2]), (in[0] ^ in[1]), in[0] }
    );

// O equals the selected input bit every cycle.
    check_mux_function: assert property (
        @(posedge clk) O == I[S]
    );

// When S==2'b00, O must equal I[0].
    check_sel00_map: assert property (
        @(posedge clk) (S == 2'b00) |-> (O == I[0])
    );

// When S==2'b01, O must equal I[1].
    check_sel01_map: assert property (
        @(posedge clk) (S == 2'b01) |-> (O == I[1])
    );

// When S==2'b10, O must equal I[2].
    check_sel10_map: assert property (
        @(posedge clk) (S == 2'b10) |-> (O == I[2])
    );

// When S==2'b11, O must equal I[3].
    check_sel11_map: assert property (
        @(posedge clk) (S == 2'b11) |-> (O == I[3])
    );

// Out must equal the selected input for all sel values (full functional check).
    check_mux_functional: assert property (
        @(posedge clk) out == ((sel == 2'b00) ? in0 :
                               (sel == 2'b01) ? in1 :
                               (sel == 2'b10) ? in2 :
                                                in3)
    );

// When sel==00, out equals in0.
    check_sel00_out_eq_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// When sel==01, out equals in1.
    check_sel01_out_eq_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// When sel==10, out equals in2.
    check_sel10_out_eq_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// When sel==11, out equals in3.
    check_sel11_out_eq_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// When input is 0xFF, output wraps to 0x00.
    check_wrap_when_max: assert property (
        @(posedge clk) (inValue == 8'hFF) |-> (outValue == 8'h00)
    );

// When input is not 0xFF, output equals input + 1.
    check_increment_nonmax: assert property (
        @(posedge clk) (inValue != 8'hFF) |-> (outValue == inValue + 8'd1)
    );

// Only max input (0xFF) can produce output 0x00.
    check_zero_only_from_max: assert property (
        @(posedge clk) (outValue == 8'h00) |-> (inValue == 8'hFF)
    );

// Output 0xFF occurs only when input is 0xFE.
    check_out_ff_implies_in_fe: assert property (
        @(posedge clk) (outValue == 8'hFF) |-> (inValue == 8'hFE)
    );

// Output is never equal to input (no fixed point for +1 mod 256).
    check_out_never_equals_in: assert property (
        @(posedge clk) (outValue != inValue)
    );

// Output minus input is always 1 mod 256.
    check_modulo_difference_one: assert property (
        @(posedge clk) ((outValue - inValue) == 8'h01)
    );

// For non-max input, output is strictly greater than input.
    check_monotonic_nonmax: assert property (
        @(posedge clk) (inValue != 8'hFF) |-> (outValue > inValue)
    );

// input_tm_cnt==0 maps to 0
    check_cnt0_maps_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (input_tm_cnt == 2'd0) |-> (fifo_wrptr_inc == 4'b0000)
    );

// input_tm_cnt==1 maps to 1
    check_cnt1_maps_one: assert property (
        @(posedge CLK) disable iff (1'b0) (input_tm_cnt == 2'd1) |-> (fifo_wrptr_inc == 4'b0001)
    );

// input_tm_cnt==2 with ge2_free maps to 2
    check_cnt2_ge2_maps_two: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd2) && ge2_free) |-> (fifo_wrptr_inc == 4'b0010)
    );

// input_tm_cnt==2 without ge2_free maps to 1
    check_cnt2_no_ge2_maps_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd2) && !ge2_free) |-> (fifo_wrptr_inc == 4'b0001)
    );

// input_tm_cnt==3 with ge3_free maps to 3
    check_cnt3_ge3_maps_three: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd3) && ge3_free) |-> (fifo_wrptr_inc == 4'b0011)
    );

// input_tm_cnt==3 without ge3_free but with ge2_free maps to 2
    check_cnt3_no_ge3_ge2_maps_two: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd3) && !ge3_free && ge2_free) |-> (fifo_wrptr_inc == 4'b0010)
    );

// input_tm_cnt==3 without ge3_free and without ge2_free maps to 1
    check_cnt3_no_ge3_no_ge2_maps_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((input_tm_cnt == 2'd3) && !ge3_free && !ge2_free) |-> (fifo_wrptr_inc == 4'b0001)
    );

// Output encoding limited to 0..3
    check_out_value_domain: assert property (
        @(posedge CLK) disable iff (1'b0) fifo_wrptr_inc inside {4'b0000,4'b0001,4'b0010,4'b0011}
    );

// If output is 3 then ge3_free and cnt==3 held
    check_out3_implies_ge3_cnt3: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0011) |-> (ge3_free && (input_tm_cnt == 2'd3))
    );

// If output is 2 then ge2_free and cnt>=2 and not (ge3_free && cnt==3)
    check_out2_implies_ge2_and_not_ge3cnt3: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0010) |-> (ge2_free && (input_tm_cnt >= 2'd2) && !(ge3_free && (input_tm_cnt == 2'd3)))
    );

// If output is 1 then cnt>=1 and neither higher-priority condition held
    check_out1_implies_no_higher_conditions: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0001) |-> ((input_tm_cnt >= 2'd1) && !(ge3_free && (input_tm_cnt == 2'd3)) && !(ge2_free && (input_tm_cnt >= 2'd2)))
    );

// If output is 0 then cnt==0
    check_out0_implies_cnt0: assert property (
        @(posedge CLK) disable iff (1'b0) (fifo_wrptr_inc == 4'b0000) |-> (input_tm_cnt == 2'd0)
    );

// Y equals (A | B) & ~C.
    check_functional_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ((A | B) & ~C)
    );

// If C is 1, Y must be 0.
    check_y_zero_when_C_is_one: assert property (
        @(posedge CLK) disable iff (1'b0) (C == 1'b1) |-> (Y == 1'b0)
    );

// If A and B are both 0, Y must be 0.
    check_y_zero_when_A_and_B_zero: assert property (
        @(posedge CLK) disable iff (1'b0) ((A == 1'b0) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// If C is 0 and either A or B is 1, Y must be 1.
    check_y_one_when_C_zero_and_AorB_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((C == 1'b0) && (A || B)) |-> (Y == 1'b1)
    );

// If Y is 1, then C is 0 and at least one of A or B is 1.
    check_y_one_implies_C_zero_and_AorB_one: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b1) |-> ((C == 1'b0) && (A || B))
    );

// With known inputs, output must be known (no X/Z).
    check_no_x_when_inputs_known: assert property (
        @(posedge CLK) disable iff (1'b0) (!$isunknown({A,B,C})) |-> (!$isunknown(Y))
    );

// On A rising with C=0, Y must be 1.
    check_y_one_on_rise_A_when_C_zero: assert property (
        @(posedge CLK) disable iff (1'b0) ($rose(A) && (C == 1'b0)) |-> (Y == 1'b1)
    );

// On B rising with C=0, Y must be 1.
    check_y_one_on_rise_B_when_C_zero: assert property (
        @(posedge CLK) disable iff (1'b0) ($rose(B) && (C == 1'b0)) |-> (Y == 1'b1)
    );

// On C rising, Y must be 0.
    check_y_zero_on_rise_C: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(C) |-> (Y == 1'b0)
    );

// Clock: clk; Reset: rst (active-high async). Logic: sequential.

    ///// Reset behavior /////
    // While reset is asserted, PC_Out is 0.
    reset_drives_zero: assert property (
        @(posedge clk) rst |-> (PC_Out == 32'h0000_0000)
    );

///// Hold behavior /////
    // When not flushing and PCWrite is LOW, PC_Out holds its value.
    hold_when_no_write: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && !PCWrite) |=> (PC_Out == $past(PC_Out))
    );

///// Flush behavior /////
    // When flush is asserted, next PC_Out keeps old MSB and clears lower 31 bits.
    flush_clears_lower31: assert property (
        @(posedge clk) disable iff (rst)
            flush |=> (PC_Out == { $past(PC_Out[31]), {31{1'b0}} })
    );

///// Write/Branch/PCSrc behavior /////
    // On PCWrite with Branch, next PC_Out equals ConBA.
    branch_updates_to_ConBA: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && Branch) |=> (PC_Out == $past(ConBA))
    );

// On PCWrite without Branch and PCSrc=0 or 1, next PC_Out equals PC_In+4.
    pcs01_inc4: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && (PCSrc inside {3'h0,3'h1})) |=> (PC_Out == ($past(PC_In) + 32'h4))
    );

// On PCWrite without Branch and PCSrc=2, next PC_Out equals {PC_In[31:28], JT, 2'b0}.
    pcs2_jump_address: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && (PCSrc == 3'h2)) |=> (PC_Out == { $past(PC_In[31:28]), $past(JT), 2'b0 })
    );

// On PCWrite without Branch and PCSrc=2, LSBs of next PC_Out are 0.
    pcs2_lsb_zero: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && (PCSrc == 3'h2)) |=> (PC_Out[1:0] == 2'b00)
    );

// On PCWrite without Branch and PCSrc=3, next PC_Out equals DataBusA.
    pcs3_load_from_DataBusA: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && (PCSrc == 3'h3)) |=> (PC_Out == $past(DataBusA))
    );

// On PCWrite without Branch and PCSrc=4, next PC_Out equals 0x80000004.
    pcs4_const_8000_0004: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && (PCSrc == 3'h4)) |=> (PC_Out == 32'h8000_0004)
    );

// On PCWrite without Branch and PCSrc=5, next PC_Out equals 0x80000008.
    pcs5_const_8000_0008: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && (PCSrc == 3'h5)) |=> (PC_Out == 32'h8000_0008)
    );

// On PCWrite without Branch and PCSrc not in 0..5 (i.e., 6 or 7), next PC_Out equals 0x80000008.
    default_const_8000_0008: assert property (
        @(posedge clk) disable iff (rst)
            (!flush && PCWrite && !Branch && !(PCSrc inside {3'h0,3'h1,3'h2,3'h3,3'h4,3'h5})) |=> (PC_Out == 32'h8000_0008)
    );

// Clock: clk (posedge). Reset: rst (active-high, synchronous). Sequential 4-bit counter: reset->0; if en: +1 with wrap at 15; else hold.

    // On any cycle with rst asserted, next count must be 0.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// When en is HIGH and count is 15, next count wraps to 0.
    count_wraps_on_max_when_en: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 4'hF)) |=> (count == 4'h0)
    );

// With en HIGH and not at max, next count must not be 0 (no spurious clear).
    no_unexpected_zero_on_en_not_max: assert property (
        @(posedge clk) disable iff (rst) (en && (count != 4'hF)) |=> (count != 4'h0)
    );

// Output equals ~(io_ready & io_valid_0) when io_ready rises.
    check_equiv_on_posedge_ready: assert property (
        @(posedge io_ready) io_chosen == ~(io_ready & io_valid_0)
    );

// Output equals ~(io_ready & io_valid_0) when io_valid_0 rises.
    check_equiv_on_posedge_valid: assert property (
        @(posedge io_valid_0) io_chosen == ~(io_ready & io_valid_0)
    );

// If both inputs HIGH, output must be LOW (sampled on io_ready rise).
    check_low_when_both_high_on_ready: assert property (
        @(posedge io_ready) (io_ready && io_valid_0) |-> (io_chosen == 1'b0)
    );

// If both inputs HIGH, output must be LOW (sampled on io_valid_0 rise).
    check_low_when_both_high_on_valid: assert property (
        @(posedge io_valid_0) (io_ready && io_valid_0) |-> (io_chosen == 1'b0)
    );

// When io_ready is HIGH and io_valid_0 is LOW, output must be HIGH (on io_ready rise).
    check_high_when_ready_high_and_valid_low_on_ready: assert property (
        @(posedge io_ready) (io_ready && !io_valid_0) |-> (io_chosen == 1'b1)
    );

// When io_ready is LOW, output must be HIGH (on io_valid_0 rise).
    check_high_when_ready_low_on_valid: assert property (
        @(posedge io_valid_0) (!io_ready) |-> (io_chosen == 1'b1)
    );

// Output LOW implies both inputs are HIGH (sampled on io_ready rise).
    check_zero_implies_both_high_on_ready: assert property (
        @(posedge io_ready) (io_chosen == 1'b0) |-> (io_ready && io_valid_0)
    );

// Output LOW implies both inputs are HIGH (sampled on io_valid_0 rise).
    check_zero_implies_both_high_on_valid: assert property (
        @(posedge io_valid_0) (io_chosen == 1'b0) |-> (io_ready && io_valid_0)
    );

// Output HIGH implies not both inputs HIGH (sampled on io_ready rise).
    check_one_implies_not_both_high_on_ready: assert property (
        @(posedge io_ready) (io_chosen == 1'b1) |-> !(io_ready && io_valid_0)
    );

// Output HIGH implies not both inputs HIGH (sampled on io_valid_0 rise).
    check_one_implies_not_both_high_on_valid: assert property (
        @(posedge io_valid_0) (io_chosen == 1'b1) |-> !(io_ready && io_valid_0)
    );

///// Reset behavior /////
    // While reset is asserted at the clock edge, count must be zero.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

///// Counting behavior (clocked) /////
    // If previous cycle was not in reset and count was within 0..9, it remains within 0..9.
    range_closed_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) <= 4'd9)) |-> (count <= 4'd9)
    );

// No two consecutive 9s when not in reset across the boundary.
    no_back_to_back_nine: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset)) |-> !($past(count) == 4'd9 && count == 4'd9)
    );

// From a previous value 9 without reset, next is 0 (wrap) or 1 (if async reset occurred mid-cycle).
    prev_nine_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(count) == 4'd9)) |-> ((count == 4'd0) || (count == 4'd1))
    );

// If the count decreases across cycles without reset, it can only drop to 0 or 1.
    decrease_only_to_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && (count < $past(count))) |-> ((count == 4'd0) || (count == 4'd1))
    );

// When count is 9 (not in reset), the next cycle must be 0 or 1.
    next_after_nine_is_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'd9) |-> ##1 (count == 4'd0 || count == 4'd1)
    );

// Output equals one-hot value of 1 shifted by A.
    check_decode_equivalence: assert property (
        @(posedge clk) Y == (16'h0001 << A)
    );

// Exactly one output bit is HIGH.
    check_onehot_output: assert property (
        @(posedge clk) $onehot(Y)
    );

// Output is never all zero for 4-bit binary A.
    check_nonzero_output: assert property (
        @(posedge clk) Y != 16'h0000
    );

// When MSB of A is 0, upper half of Y must be zero.
    check_upper_zero_when_msb0: assert property (
        @(posedge clk) (A[3] == 1'b0) |-> (Y[15:8] == 8'h00)
    );

// When MSB of A is 1, lower half of Y must be zero.
    check_lower_zero_when_msb1: assert property (
        @(posedge clk) (A[3] == 1'b1) |-> (Y[7:0] == 8'h00)
    );

// When A[3:2]==00, only Y[3:0] may be nonzero.
    check_quarter00_zero_upper12: assert property (
        @(posedge clk) (A[3:2] == 2'b00) |-> (Y[15:4] == 12'h000)
    );

// When A[3:2]==01, only Y[7:4] may be nonzero.
    check_quarter01_zero_elsewhere: assert property (
        @(posedge clk) (A[3:2] == 2'b01) |-> (Y[15:8] == 8'h00 && Y[3:0] == 4'h0)
    );

// When A[3:2]==10, only Y[11:8] may be nonzero.
    check_quarter10_zero_elsewhere: assert property (
        @(posedge clk) (A[3:2] == 2'b10) |-> (Y[15:12] == 4'h0 && Y[7:0] == 8'h00)
    );

// When A[3:2]==11, only Y[15:12] may be nonzero.
    check_quarter11_zero_lower12: assert property (
        @(posedge clk) (A[3:2] == 2'b11) |-> (Y[11:0] == 12'h000)
    );

// Corner case: A==0 decodes to Y==0x0001.
    check_decode_A0: assert property (
        @(posedge clk) (A == 4'd0) |-> (Y == 16'h0001)
    );

// When op==000, out equals a + b (truncated to 4 bits).
    check_addition: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b000) |-> (out == (a + b))
    );

// When op==001, out equals a - b (truncated to 4 bits).
    check_subtraction: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b001) |-> (out == (a - b))
    );

// When op==010, out equals a & b.
    check_bitwise_and: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b010) |-> (out == (a & b))
    );

// When op==011, out equals a | b.
    check_bitwise_or: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b011) |-> (out == (a | b))
    );

// When op==100, out equals a ^ b.
    check_bitwise_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b100) |-> (out == (a ^ b))
    );

// When op==101, out equals {a[2:0], 1'b0} (shift left by 1 with zero fill).
    check_shift_left: assert property (
        @(posedge CLK) disable iff (1'b0) (op == 3'b101) |-> (out == {a[2:0], 1'b0})
    );

// When op is 110 or 111, out is 0 (default case).
    check_default_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (op inside {3'b110, 3'b111}) |-> (out == 4'b0000)
    );

///// Reset behavior /////
  // After any cycle with rst=1, Y must be 0 on the next clock.
  reset_clears_Y_next: assert property (
    @(posedge clk) rst |=> (Y == 1'b0)
  );

// Reset high causes count to be zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 3'b000)
    );

// If reset is held high across cycles, count is zero.
    reset_holds_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (count == 3'b000)
    );

// With en=1 (and prior cycle out of reset), count increments by 1 next cycle.
    increment_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count == $past(count) + 3'b001)
    );

// With en=0 (and prior cycle out of reset), count holds its value next cycle.
    hold_on_disable: assert property (
        @(posedge clk) disable iff (rst) (!en && $past(!rst)) |=> (count == $past(count))
    );

// With en=1, LSB toggles each cycle.
    lsb_toggles_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count[0] != $past(count[0]))
    );

// With en=1, bit1 equals prev(bit1) XOR prev(bit0).
    bit1_xor_carry_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count[1] == ($past(count[1]) ^ $past(count[0])))
    );

// With en=1, bit2 equals prev(bit2) XOR (prev(bit1)&prev(bit0)).
    bit2_xor_carry_on_en: assert property (
        @(posedge clk) disable iff (rst) (en && $past(!rst)) |=> (count[2] == ($past(count[2]) ^ ($past(count[1]) & $past(count[0]))))
    );

// X high only when A_N=0, B_N=0, C=1, D=1.
    check_x_implies_inputs_ok: assert property (
        @(posedge CLK) X |-> (!A_N && !B_N && C && D)
    );

// When A_N=0, B_N=0, C=1, D=1, X must be high.
    check_inputs_ok_implies_x: assert property (
        @(posedge CLK) (!A_N && !B_N && C && D) |-> X
    );

// Any blocking condition (A_N=1 or B_N=1 or C=0 or D=0) forces X low.
    check_blocking_conditions_force_x_low: assert property (
        @(posedge CLK) (A_N || B_N || !C || !D) |-> !X
    );

// With A_N=B_N=0 and C=1, X equals D.
    check_gate_open_x_eq_d: assert property (
        @(posedge CLK) (!A_N && !B_N && C) |-> (X == D)
    );

// With A_N=B_N=0 and D=1, X equals C.
    check_gate_open_x_eq_c: assert property (
        @(posedge CLK) (!A_N && !B_N && D) |-> (X == C)
    );

// With C=D=1, X equals (~A_N & ~B_N).
    check_cd_high_x_equals_nor_ab: assert property (
        @(posedge CLK) (C && D) |-> (X == (!A_N && !B_N))
    );

// With gate open via C=1, a rising D sets X high.
    check_d_rise_sets_x_when_c_open: assert property (
        @(posedge CLK) ($rose(D) && !A_N && !B_N && C) |-> X
    );

// With gate open via C=1, a falling D clears X low.
    check_d_fall_clears_x_when_c_open: assert property (
        @(posedge CLK) ($fell(D) && !A_N && !B_N && C) |-> !X
    );

// With gate open via D=1, a rising C sets X high.
    check_c_rise_sets_x_when_d_open: assert property (
        @(posedge CLK) ($rose(C) && !A_N && !B_N && D) |-> X
    );

// With gate open via D=1, a falling C clears X low.
    check_c_fall_clears_x_when_d_open: assert property (
        @(posedge CLK) ($fell(C) && !A_N && !B_N && D) |-> !X
    );

// Y must equal (A & ~B & C) | D.
  check_functional_equivalence: assert property (
    @(posedge clk) Y == ((A & (~B) & C) | D)
  );

// D high forces Y high.
  check_D_high_forces_Y_high: assert property (
    @(posedge clk) D |-> (Y == 1'b1)
  );

// When D is low and A=1,B=0,C=1, Y must be high.
  check_and_true_sets_Y_when_D_low: assert property (
    @(posedge clk) (!D && A && !B && C) |-> (Y == 1'b1)
  );

// When D is low and B is high, Y must be low.
  check_B_high_blocks_when_D_low: assert property (
    @(posedge clk) (!D && B) |-> (Y == 1'b0)
  );

// When D is low and A is low, Y must be low.
  check_A_low_blocks_when_D_low: assert property (
    @(posedge clk) (!D && !A) |-> (Y == 1'b0)
  );

// When D is low and C is low, Y must be low.
  check_C_low_blocks_when_D_low: assert property (
    @(posedge clk) (!D && !C) |-> (Y == 1'b0)
  );

// If Y is high while D is low, A=1,B=0,C=1 must hold.
  check_Y_high_requires_inputs_when_D_low: assert property (
    @(posedge clk) (Y && !D) |-> (A && !B && C)
  );

// If Y is low while D is low, at least one of A=0, B=1, or C=0 holds.
  check_Y_low_implies_one_input_blocks_when_D_low: assert property (
    @(posedge clk) (!Y && !D) |-> ((!A) || B || (!C))
  );

// Out is always a known 2-bit value.
    check_out_known: assert property (
        @(posedge clk) disable iff (1'b0) !$isunknown(out)
    );

// Inputs 0..4 map to 00.
    check_map_00_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd0:4'd4]}) |-> (out == 2'b00)
    );

// Inputs 5..8 map to 01.
    check_map_01_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd5:4'd8]}) |-> (out == 2'b01)
    );

// Inputs 9..11 map to 10.
    check_map_10_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd9:4'd11]}) |-> (out == 2'b10)
    );

// Inputs 12..15 map to 11.
    check_map_11_forward: assert property (
        @(posedge clk) disable iff (1'b0) (in inside {[4'd12:4'd15]}) |-> (out == 2'b11)
    );

// Out 00 only occurs for inputs 0..4.
    check_map_00_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b00) |-> (in inside {[4'd0:4'd4]})
    );

// Out 01 only occurs for inputs 5..8.
    check_map_01_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b01) |-> (in inside {[4'd5:4'd8]})
    );

// Out 10 only occurs for inputs 9..11.
    check_map_10_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b10) |-> (in inside {[4'd9:4'd11]})
    );

// Out 11 only occurs for inputs 12..15.
    check_map_11_reverse: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b11) |-> (in inside {[4'd12:4'd15]})
    );

// Out must equal the RTL ternary expression for all inputs.
    check_function_equivalence: assert property (
        @(posedge CLK) out == ((in < 4'd5) ? 2'b00 :
                               (in < 4'd9) ? 2'b01 :
                               (in < 4'd11) ? 2'b10 : 2'b11)
    );

// For in=0..4, out must be 00.
    check_out_for_in_lt_5: assert property (
        @(posedge CLK) (in < 4'd5) |-> (out == 2'b00)
    );

// For in=5..8, out must be 01.
    check_out_for_5_to_8: assert property (
        @(posedge CLK) (in >= 4'd5 && in < 4'd9) |-> (out == 2'b01)
    );

// For in=9..10, out must be 10.
    check_out_for_9_to_10: assert property (
        @(posedge CLK) (in >= 4'd9 && in < 4'd11) |-> (out == 2'b10)
    );

// For in=11..15, out must be 11.
    check_out_for_11_to_15: assert property (
        @(posedge CLK) (in >= 4'd11) |-> (out == 2'b11)
    );

// If out is 00, in must be 0..4.
    check_in_range_when_out_00: assert property (
        @(posedge CLK) (out == 2'b00) |-> (in < 4'd5)
    );

// If out is 01, in must be 5..8.
    check_in_range_when_out_01: assert property (
        @(posedge CLK) (out == 2'b01) |-> (in >= 4'd5 && in < 4'd9)
    );

// If out is 10, in must be 9..10.
    check_in_range_when_out_10: assert property (
        @(posedge CLK) (out == 2'b10) |-> (in >= 4'd9 && in < 4'd11)
    );

// If out is 11, in must be 11..15.
    check_in_range_when_out_11: assert property (
        @(posedge CLK) (out == 2'b11) |-> (in >= 4'd11)
    );

///// Decoder checks /////
    // Decoder outputs sel when sel is one-hot.
    decoder_matches_onehot_sel: assert property (
        @(posedge clk) $onehot(sel) |-> (decoder_out == sel)
    );

// Decoder outputs 0 when sel is not one-hot.
    decoder_zero_when_not_onehot: assert property (
        @(posedge clk) !$onehot(sel) |-> (decoder_out == 8'b0)
    );

// Decoder output is always one-hot or zero.
    decoder_out_onehot0: assert property (
        @(posedge clk) $onehot0(decoder_out)
    );

///// mux2 checks /////
    // When sel[0]==0, mux2_out replicates in[decoder_out + 1].
    mux2_sel0_replication: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (mux2_out == {in[decoder_out + 1], in[decoder_out + 1]})
    );

// When sel[0]==1, mux2_out replicates in[decoder_out].
    mux2_sel1_replication: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (mux2_out == {in[decoder_out], in[decoder_out]})
    );

// mux2_out bits are always identical.
    mux2_bits_identical: assert property (
        @(posedge clk) (mux2_out[1] == mux2_out[0])
    );

///// Final mux checks /////
    // Final mux selects mux2_out bit indexed by sel[0].
    final_mux_select: assert property (
        @(posedge clk) (out == mux2_out[sel[0]])
    );

// End-to-end: out equals selected input bit.
    end_to_end_out_value: assert property (
        @(posedge clk) out == (sel[0] ? in[decoder_out] : in[decoder_out + 1])
    );

// When sel[0]==0, out equals in[decoder_out + 1].
    end_to_end_sel0: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (out == in[decoder_out + 1])
    );

// When sel[0]==1, out equals in[decoder_out].
    end_to_end_sel1: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (out == in[decoder_out])
    );

// When sel==000, out equals data0.
    check_sel_000_maps_to_data0: assert property (
        @(posedge CLK) (sel == 3'b000) |-> (out == data0)
    );

// When sel==001, out equals data1.
    check_sel_001_maps_to_data1: assert property (
        @(posedge CLK) (sel == 3'b001) |-> (out == data1)
    );

// When sel==010, out equals data2.
    check_sel_010_maps_to_data2: assert property (
        @(posedge CLK) (sel == 3'b010) |-> (out == data2)
    );

// When sel==011, out equals data3.
    check_sel_011_maps_to_data3: assert property (
        @(posedge CLK) (sel == 3'b011) |-> (out == data3)
    );

// When sel==100, out equals data4.
    check_sel_100_maps_to_data4: assert property (
        @(posedge CLK) (sel == 3'b100) |-> (out == data4)
    );

// When sel==101, out equals data5.
    check_sel_101_maps_to_data5: assert property (
        @(posedge CLK) (sel == 3'b101) |-> (out == data5)
    );

// When sel==110, out replicates data5[3] on all bits.
    check_sel_110_default_replication: assert property (
        @(posedge CLK) (sel == 3'b110) |-> (out == {4{data5[3]}})
    );

// When sel==111, out replicates data5[3] on all bits.
    check_sel_111_default_replication: assert property (
        @(posedge CLK) (sel == 3'b111) |-> (out == {4{data5[3]}})
    );

// Async active-low reset drives counter output to zero.
    reset_clears_output: assert property (
        @(posedge clock) (!resetn) |-> (o_dataout == '0)
    );

// Counter reset clears output on the next cycle.
    sync_counter_reset_next_zero: assert property (
        @(posedge clock) disable iff (!resetn) i_counter_reset |=> (o_dataout == '0)
    );

// When not taking the increment path and not resetting, output holds its value.
    hold_when_no_increment_condition: assert property (
        @(posedge clock) disable iff (!resetn)
            (!i_counter_reset && !(i_start && !i_dataout_stall && (o_dataout < i_size)))
            |=> $stable(o_dataout)
    );

// Without counter reset, output changes per step only by 0 or +1.
    bounded_step_without_reset: assert property (
        @(posedge clock) disable iff (!resetn)
            (!i_counter_reset) |=> ((o_dataout == $past(o_dataout)) || (o_dataout == $past(o_dataout) + 1))
    );

// Stall blocks increment: when stalled and not resetting, output holds.
    hold_when_stalled: assert property (
        @(posedge clock) disable iff (!resetn)
            (!i_counter_reset && i_dataout_stall) |=> $stable(o_dataout)
    );

// Z implements add/sub based on op (sampled on posedge of A[0]).
    check_func_on_posedge_a0: assert property (
        @(posedge A[0]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

// Z implements add/sub based on op (sampled on posedge of A[1]).
    check_func_on_posedge_a1: assert property (
        @(posedge A[1]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

// Z implements add/sub based on op (sampled on posedge of A[2]).
    check_func_on_posedge_a2: assert property (
        @(posedge A[2]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

// Z implements add/sub based on op (sampled on posedge of B[0]).
    check_func_on_posedge_b0: assert property (
        @(posedge B[0]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

// Z implements add/sub based on op (sampled on posedge of B[1]).
    check_func_on_posedge_b1: assert property (
        @(posedge B[1]) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

// Z implements add/sub based on op (sampled on posedge of op).
    check_func_on_posedge_op: assert property (
        @(posedge op) Z == ((op ? (A - B) : (A + B)) & 4'hF)
    );

// When op==0 and B==0, Z equals A (sampled on posedge of A[0]).
    add_identity_b_zero: assert property (
        @(posedge A[0]) (op == 1'b0) && (B == 4'h0) |-> (Z == A)
    );

// When op==1 and B==0, Z equals A (sampled on posedge of A[0]).
    sub_identity_b_zero: assert property (
        @(posedge A[0]) (op == 1'b1) && (B == 4'h0) |-> (Z == A)
    );

// When op==0 and A==0, Z equals B (sampled on posedge of B[0]).
    add_identity_a_zero: assert property (
        @(posedge B[0]) (op == 1'b0) && (A == 4'h0) |-> (Z == B)
    );

// When op==1 and A==B, Z is zero (sampled on posedge of A[0]).
    sub_equal_operands_zero: assert property (
        @(posedge A[0]) (op == 1'b1) && (A == B) |-> (Z == 4'h0)
    );

// Addition is commutative when op==0 (sampled on posedge of A[3]).
    add_commutes: assert property (
        @(posedge A[3]) (op == 1'b0) |-> (Z == ((B + A) & 4'hF))
    );

// sum must be XOR of a, b, c_in per full_adder.
    check_sum_is_xor: assert property (
        @(posedge clk) disable iff (1'b0) sum == (a ^ b ^ c_in)
    );

// When (sum & out_xor) is false, c_out equals the full_adder carry.
    check_cout_equals_carry_when_not_forced: assert property (
        @(posedge clk) disable iff (1'b0)
            !(sum & out_xor) |-> (c_out == ((a & b) | (a & c_in) | (b & c_in)))
    );

// EQ reflects 4-state equality of A and B.
    def_eq_matches_relop: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

// GT reflects 4-state greater-than of A over B.
    def_gt_matches_relop: assert property (
        @(posedge CLK) (GT === (A > B))
    );

// LT reflects 4-state less-than of A under B.
    def_lt_matches_relop: assert property (
        @(posedge CLK) (LT === (A < B))
    );

// When inputs are known (no X/Z), exactly one of EQ/GT/LT is 1.
    onehot_outputs_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |=> $onehot({EQ,GT,LT})
    );

// When inputs are known, outputs must be known (no X/Z).
    no_x_on_outputs_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |=> (!$isunknown({EQ,GT,LT}))
    );

// pos selects index of lowest-order '1' in in (bit 0 has highest priority).
    check_pos_priority_bit0: assert property (
        @(posedge clk) in[0] |-> (pos == 3'd0)
    );

// pos==1 when in[1] is 1 and no lower bit is set.
    check_pos_priority_bit1: assert property (
        @(posedge clk) (in[1] && !in[0]) |-> (pos == 3'd1)
    );

// pos==2 when in[2] is 1 and no lower bit is set.
    check_pos_priority_bit2: assert property (
        @(posedge clk) (in[2] && !in[1] && !in[0]) |-> (pos == 3'd2)
    );

// pos==3 when in[3] is 1 and no lower bit is set.
    check_pos_priority_bit3: assert property (
        @(posedge clk) (in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd3)
    );

// pos==4 when in[4] is 1 and no lower bit is set.
    check_pos_priority_bit4: assert property (
        @(posedge clk) (in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd4)
    );

// pos==5 when in[5] is 1 and no lower bit is set.
    check_pos_priority_bit5: assert property (
        @(posedge clk) (in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd5)
    );

// pos==6 when in[6] is 1 and no lower bit is set.
    check_pos_priority_bit6: assert property (
        @(posedge clk) (in[6] && !in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd6)
    );

// pos==7 when in[7] is 1 and no lower bit is set.
    check_pos_priority_bit7: assert property (
        @(posedge clk) (in[7] && !in[6] && !in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd7)
    );

// When no bits are set, pos is 0.
    check_pos_when_none_set: assert property (
        @(posedge clk) (~|in) |-> (pos == 3'd0)
    );

// out_sum equals pos plus the selected mux output (b if both sel=1, else a if any sel=1, else 0).
    check_out_sum_matches_equation: assert property (
        @(posedge clk)
        out_sum == ({1'b0, pos} + {3'b0, ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0))})
    );

// When neither select is asserted, out_sum equals pos (mux_out=0).
    check_out_sum_sel00_no_add: assert property (
        @(posedge clk)
        (!sel_b1 && !sel_b2) |-> (out_sum == {1'b0, pos})
    );

// When exactly one select is asserted, out_sum equals pos + a.
    check_out_sum_sel_one_add_a: assert property (
        @(posedge clk)
        (sel_b1 ^ sel_b2) |-> (out_sum == ({1'b0, pos} + {3'b0, a}))
    );

// When both selects are asserted, out_sum equals pos + b.
    check_out_sum_sel11_add_b: assert property (
        @(posedge clk)
        (sel_b1 && sel_b2) |-> (out_sum == ({1'b0, pos} + {3'b0, b}))
    );

// The MSB of out_sum is high only when selected mux output is 1 and pos==7.
    check_out_sum_msb_carry: assert property (
        @(posedge clk)
        out_sum[3] == ( ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) & (&pos) )
    );

// lower_out equals lower_ina OR lower_io
    check_lower_out_def: assert property (
        @(posedge clk) lower_out === (lower_ina | lower_io)
    );

// sec_out equals sec_ina OR sec_io
    check_sec_out_def: assert property (
        @(posedge clk) sec_out === (sec_ina | sec_io)
    );

// If any lower input is 1, lower_out must be 1
    check_lower_out_one_if_any_one: assert property (
        @(posedge clk) ((lower_ina === 1'b1) || (lower_io === 1'b1)) |-> (lower_out === 1'b1)
    );

// If any sec input is 1, sec_out must be 1
    check_sec_out_one_if_any_one: assert property (
        @(posedge clk) ((sec_ina === 1'b1) || (sec_io === 1'b1)) |-> (sec_out === 1'b1)
    );

// lower_out is 0 only if both lower inputs are 0
    check_lower_out_zero_only_if_both_zero: assert property (
        @(posedge clk) (lower_out === 1'b0) |-> ((lower_ina === 1'b0) && (lower_io === 1'b0))
    );

// sec_out is 0 only if both sec inputs are 0
    check_sec_out_zero_only_if_both_zero: assert property (
        @(posedge clk) (sec_out === 1'b0) |-> ((sec_ina === 1'b0) && (sec_io === 1'b0))
    );

// With known lower inputs, lower_out must be known
    check_lower_out_known_when_inputs_known: assert property (
        @(posedge clk) (!$isunknown(lower_ina) && !$isunknown(lower_io)) |-> !$isunknown(lower_out)
    );

// With known sec inputs, sec_out must be known
    check_sec_out_known_when_inputs_known: assert property (
        @(posedge clk) (!$isunknown(sec_ina) && !$isunknown(sec_io)) |-> !$isunknown(sec_out)
    );

// Output is never Z at any VPWR rising edge.
    check_output_never_z: assert property (
        @(posedge VPWR) X !== 1'bz
    );

// When A and B_N are unchanged since last VPWR edge, X equals A | B_N.
    check_or_when_inputs_stable: assert property (
        @(posedge VPWR) (($past(A) === A) && ($past(B_N) === B_N)) |-> (X === (A | B_N))
    );

// Stable 0/0 inputs across a VPWR cycle yield X=0.
    check_tt_00: assert property (
        @(posedge VPWR) (($past(A) === 1'b0) && (A === 1'b0) && ($past(B_N) === 1'b0) && (B_N === 1'b0)) |-> (X === 1'b0)
    );

// Stable 0/1 inputs across a VPWR cycle yield X=1.
    check_tt_01: assert property (
        @(posedge VPWR) (($past(A) === 1'b0) && (A === 1'b0) && ($past(B_N) === 1'b1) && (B_N === 1'b1)) |-> (X === 1'b1)
    );

// Stable 1/0 inputs across a VPWR cycle yield X=1.
    check_tt_10: assert property (
        @(posedge VPWR) (($past(A) === 1'b1) && (A === 1'b1) && ($past(B_N) === 1'b0) && (B_N === 1'b0)) |-> (X === 1'b1)
    );

// Stable 1/1 inputs across a VPWR cycle yield X=1.
    check_tt_11: assert property (
        @(posedge VPWR) (($past(A) === 1'b1) && (A === 1'b1) && ($past(B_N) === 1'b1) && (B_N === 1'b1)) |-> (X === 1'b1)
    );

// With known inputs unchanged for two VPWR cycles, X is known (not X/Z).
    check_known_output_after_two_stable_cycles: assert property (
        @(posedge VPWR)
            ((A === 1'b0 || A === 1'b1) && (B_N === 1'b0 || B_N === 1'b1) &&
             ($past(A,2) === A) && ($past(B_N,2) === B_N))
            |-> ((X !== 1'bx) && (X !== 1'bz))
    );

// Changes on VPB/VGND/VNB do not affect X when A and B_N are stable across a VPWR cycle.
    check_supplies_no_effect_when_inputs_stable: assert property (
        @(posedge VPWR)
            (($past(A) === A) && ($past(B_N) === B_N) &&
             (($past(VPB) !== VPB) || ($past(VGND) !== VGND) || ($past(VNB) !== VNB)))
            |-> (X === (A | B_N))
    );

///// Structural properties of out /////
    // Upper 12 bits of out are always zero.
    check_out_upper_zero: assert property (
        @(posedge clk) (out[15:4] == 12'h000)
    );

// Lower nibble of out is one-hot.
    check_out_lower_onehot: assert property (
        @(posedge clk) $onehot(out[3:0])
    );

///// Direct input-to-output mapping /////
    // When disabled, out is 0x0001.
    check_out_when_disabled: assert property (
        @(posedge clk) (enable == 1'b0) |-> (out == 16'h0001)
    );

// When enabled, out equals 1 shifted by sel.
    check_out_when_enabled: assert property (
        @(posedge clk) (enable == 1'b1) |-> (out == (16'h0001 << sel))
    );

// Output equals bitwise OR of inputs.
    check_or_function: assert property (
        @(posedge clk) disable iff (clr) (y == (d0 | d1))
    );

// Output is 1 when either input is 1.
    check_output_high_when_any_high: assert property (
        @(posedge clk) disable iff (clr) ((d0 == 1'b1) || (d1 == 1'b1)) |-> (y == 1'b1)
    );

// Output is 0 when both inputs are 0.
    check_output_low_when_both_low: assert property (
        @(posedge clk) disable iff (clr) ((d0 == 1'b0) && (d1 == 1'b0)) |-> (y == 1'b0)
    );

// If output is 0, both inputs must be 0.
    check_zero_implies_both_zero: assert property (
        @(posedge clk) disable iff (clr) (y == 1'b0) |-> ((d0 == 1'b0) && (d1 == 1'b0))
    );

// If output is 1, at least one input must be 1.
    check_one_implies_any_one: assert property (
        @(posedge clk) disable iff (clr) (y == 1'b1) |-> ((d0 == 1'b1) || (d1 == 1'b1))
    );

// When d1 is 0, output equals d0.
    check_equals_d0_when_d1_zero: assert property (
        @(posedge clk) disable iff (clr) (d1 == 1'b0) |-> (y == d0)
    );

// When d0 is 0, output equals d1.
    check_equals_d1_when_d0_zero: assert property (
        @(posedge clk) disable iff (clr) (d0 == 1'b0) |-> (y == d1)
    );

// If inputs are known (not X/Z), output is known (not X/Z).
    check_no_unknown_output_when_inputs_known: assert property (
        @(posedge clk) disable iff (clr) (!$isunknown(d0) && !$isunknown(d1)) |-> !$isunknown(y)
    );

// gray_out[0] equals data_in[0].
    check_gray_bit0_is_d0: assert property (
        @(posedge clk) gray_out[0] == data_in[0]
    );

// gray_out[1] equals data_in[0] XOR data_in[1].
    check_gray_bit1_is_d0_xor_d1: assert property (
        @(posedge clk) gray_out[1] == (data_in[0] ^ data_in[1])
    );

// gray_out[2] equals data_in[1] XOR data_in[2].
    check_gray_bit2_is_d1_xor_d2: assert property (
        @(posedge clk) gray_out[2] == (data_in[1] ^ data_in[2])
    );

// gray_out[3] equals data_in[2] XOR data_in[3].
    check_gray_bit3_is_d2_xor_d3: assert property (
        @(posedge clk) gray_out[3] == (data_in[2] ^ data_in[3])
    );

// gray_out[4] equals data_in[3] XOR data_in[4].
    check_gray_bit4_is_d3_xor_d4: assert property (
        @(posedge clk) gray_out[4] == (data_in[3] ^ data_in[4])
    );

// gray_out[5] equals data_in[4] XOR data_in[5].
    check_gray_bit5_is_d4_xor_d5: assert property (
        @(posedge clk) gray_out[5] == (data_in[4] ^ data_in[5])
    );

// gray_out[6] equals data_in[5] XOR data_in[6].
    check_gray_bit6_is_d5_xor_d6: assert property (
        @(posedge clk) gray_out[6] == (data_in[5] ^ data_in[6])
    );

// gray_out[7] equals data_in[6] XOR data_in[7].
    check_gray_bit7_is_d6_xor_d7: assert property (
        @(posedge clk) gray_out[7] == (data_in[6] ^ data_in[7])
    );

// C[1] equals (A[1]&B[1]) | (C[0] & (A[1]^B[1])).
    fa1_carry_def: assert property (
        @(posedge CLK) C[1] == ((A[1] & B[1]) | (C[0] & (A[1] ^ B[1])))
    );

///// fa1_2 (bit 2) behavior /////
    // S[2] equals A[2] ^ B[2] ^ C[1].
    fa2_sum_def: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ C[1])
    );

// C[2] equals (A[2]&B[2]) | (C[1] & (A[2]^B[2])).
    fa2_carry_def: assert property (
        @(posedge CLK) C[2] == ((A[2] & B[2]) | (C[1] & (A[2] ^ B[2])))
    );

///// fa1_3 (bit 3) behavior /////
    // S[3] equals A[3] ^ B[3] ^ C[2].
    fa3_sum_def: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ C[2])
    );

// C[3] equals (A[3]&B[3]) | (C[2] & (A[3]^B[3])).
    fa3_carry_def: assert property (
        @(posedge CLK) C[3] == ((A[3] & B[3]) | (C[2] & (A[3] ^ B[3])))
    );

// Z implements saturating add: Z == min(15, A+B)
    check_saturating_function: assert property (
        @(posedge CLK) Z == ((sum5 > 5'd15) ? 4'hF : sum5[3:0])
    );

// On overflow (sum > 15), Z saturates to 4'hF
    check_saturates_on_overflow: assert property (
        @(posedge CLK) (sum5 > 5'd15) |-> (Z == 4'hF)
    );

// Without overflow, Z equals lower 4 bits of the sum
    check_passthrough_without_overflow: assert property (
        @(posedge CLK) (sum5 <= 5'd15) |-> (Z == sum5[3:0])
    );

// Z is always within 0..15
    check_output_range: assert property (
        @(posedge CLK) Z <= 4'hF
    );

// DUT has no reset; purely combinational

    // Upper 4 bits of out are always zero.
    check_out_upper_zero: assert property (
        @(posedge CLK) out[11:8] == 4'b0000
    );

// Lower 8 bits equal upper byte AND NOT lower byte.
    check_out_lower_eq_hi_and_not_lo: assert property (
        @(posedge CLK) out[7:0] == (in[15:8] & ~in[7:0])
    );

// Lower 8 bits equal upper byte AND (upper XOR lower).
    check_out_lower_eq_hi_and_xor: assert property (
        @(posedge CLK) out[7:0] == (in[15:8] & (in[15:8] ^ in[7:0]))
    );

// Output bits are a subset of the upper input byte.
    check_out_subset_of_hi: assert property (
        @(posedge CLK) (out[7:0] & ~in[15:8]) == 8'h00
    );

// No output bit is set where the lower input byte has a 1.
    check_out_disjoint_with_lo: assert property (
        @(posedge CLK) (out[7:0] & in[7:0]) == 8'h00
    );

// If the upper byte is zero, the entire output is zero.
    check_hi_zero_implies_out_zero: assert property (
        @(posedge CLK) (in[15:8] == 8'h00) |-> (out == 12'h000)
    );

// If the lower byte is all ones, the entire output is zero.
    check_lo_ones_implies_out_zero: assert property (
        @(posedge CLK) (in[7:0] == 8'hFF) |-> (out == 12'h000)
    );

// If the lower byte is zero, the lower output equals the upper byte.
    check_lo_zero_implies_out_eq_hi: assert property (
        @(posedge CLK) (in[7:0] == 8'h00) |-> ((out[7:0] == in[15:8]) && (out[11:8] == 4'b0000))
    );

// If upper and lower bytes are equal, the output is zero.
    check_equal_bytes_implies_out_zero: assert property (
        @(posedge CLK) (in[15:8] == in[7:0]) |-> (out == 12'h000)
    );

// ab must be NOR of a and b
    check_ab_is_nor2: assert property (
        @(posedge CLK) ab == ~(a | b)
    );

// cd must be NOR of c and d
    check_cd_is_nor2: assert property (
        @(posedge CLK) cd == ~(c | d)
    );

// y must be NOR of ab and cd
    check_y_is_nor2_of_ab_cd: assert property (
        @(posedge CLK) y == ~(ab | cd)
    );

// y must equal (a|b)&(c|d)
    check_y_equals_and_of_ors: assert property (
        @(posedge CLK) y == ((a | b) & (c | d))
    );

// If a and b are both 0, y must be 0
    check_y_zero_if_a_b_both_zero: assert property (
        @(posedge CLK) (!a && !b) |-> (y == 1'b0)
    );

// If c and d are both 0, y must be 0
    check_y_zero_if_c_d_both_zero: assert property (
        @(posedge CLK) (!c && !d) |-> (y == 1'b0)
    );

// If at least one of a/b and one of c/d are 1, y must be 1
    check_y_one_if_each_pair_has_one: assert property (
        @(posedge CLK) (((a | b) & (c | d)) == 1'b1) |-> (y == 1'b1)
    );

// If y is 1 then ab and cd must both be 0
    check_y_high_implies_ab_cd_low: assert property (
        @(posedge CLK) (y == 1'b1) |-> ((ab == 1'b0) && (cd == 1'b0))
    );

// If y is 0 then either ab or cd must be 1
    check_y_low_implies_ab_or_cd_high: assert property (
        @(posedge CLK) (y == 1'b0) |-> ((ab == 1'b1) || (cd == 1'b1))
    );

// When mux_sel==10, output equals mux_in2.
    check_sel_10_maps_to_in2: assert property (
        @(posedge clk) disable iff (!rst_n) (mux_sel == 2'b10) |-> (mux_out == mux_in2)
    );

// When mux_sel==11, output equals mux_in3.
    check_sel_11_maps_to_in3: assert property (
        @(posedge clk) disable iff (!rst_n) (mux_sel == 2'b11) |-> (mux_out == mux_in3)
    );

// If upper select=1 and mux_in2==mux_in3, output equals that value.
    check_high_tree_pair_equal: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mux_sel[1] == 1'b1 && (mux_in2 == mux_in3)) |-> (mux_out == mux_in2)
    );

// No reset in RTL; purely combinational behavior sampled on CLK.

    // When S==00, Q passes D unchanged.
    check_no_shift: assert property (
        @(posedge CLK) (S == 2'b00) |-> (Q == D)
    );

// When S==01, Q is left shift by 1 with zero fill.
    check_left_shift: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Q == {D[2:0], 1'b0})
    );

// For left shift, LSB is zero (zero-fill).
    check_left_shift_lsb_zero: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Q[0] == 1'b0)
    );

// When S==10, Q is right shift by 1 with zero fill.
    check_right_shift: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Q == {1'b0, D[3:1]})
    );

// For right shift, MSB is zero (zero-fill).
    check_right_shift_msb_zero: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Q[3] == 1'b0)
    );

// When S==11, Q is a circular rotate-left by 2 bits.
    check_circular_shift: assert property (
        @(posedge CLK) (S == 2'b11) |-> (Q == {D[1:0], D[3:2]})
    );

// axis_tvalid is the inverse of ll_src_rdy_in_n each cycle.
    map_valid_inversion: assert property (
        @(posedge clk) disable iff (rst) (axis_tvalid == ~ll_src_rdy_in_n)
    );

// axis_tlast is the inverse of ll_eof_in_n each cycle.
    map_last_inversion: assert property (
        @(posedge clk) disable iff (rst) (axis_tlast == ~ll_eof_in_n)
    );

// ll_dst_rdy_out_n is the inverse of axis_tready each cycle.
    map_ready_inversion: assert property (
        @(posedge clk) disable iff (rst) (ll_dst_rdy_out_n == ~axis_tready)
    );

///// Reset behavior /////
    // While reset is asserted (active-high, synchronous), reg_0x61 is 0x00.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (reg_0x61 == 8'h00)
    );

// Sum and carry match 5-bit arithmetic addition of inputs
    check_overall_sum: assert property (
        @(posedge clk) {C_out, S} == (A + B + C_in)
    );

// LSB sum bit equals XOR of inputs
    check_s0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ C_in)
    );

// Bit1 sum uses ripple carry from bit0
    check_s1_xor: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ c1)
    );

// Bit2 sum uses ripple carry from bit1
    check_s2_xor: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ c2)
    );

// Bit3 sum uses ripple carry from bit2
    check_s3_xor: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ c3)
    );

// Final carry-out equation at MSB
    check_cout_equation: assert property (
        @(posedge clk) C_out == ((A[3] & B[3]) | (c3 & (A[3] ^ B[3])))
    );

// If both MSB inputs are 1, carry-out must be 1
    check_cout_msb_both_one: assert property (
        @(posedge clk) (~(A[3] & B[3])) || (C_out == 1'b1)
    );

// If both MSB inputs are 0, carry-out must be 0
    check_cout_msb_both_zero: assert property (
        @(posedge clk) (~(~A[3] & ~B[3])) || (C_out == 1'b0)
    );

// If MSB inputs differ, carry-out equals c3
    check_cout_msb_diff_equals_c3: assert property (
        @(posedge clk) (~(A[3] ^ B[3])) || (C_out == c3)
    );

// If MSB inputs are equal, S[3] equals c3
    check_s3_when_msb_equal: assert property (
        @(posedge clk) (A[3] ^ B[3]) || (S[3] == c3)
    );

// If MSB inputs differ, S[3] is the inverse of c3
    check_s3_when_msb_diff: assert property (
        @(posedge clk) (~(A[3] ^ B[3])) || (S[3] == ~c3)
    );

// With A=0 and B=0, S mirrors C_in on bit0 and C_out is 0
    check_zero_inputs_behavior: assert property (
        @(posedge clk) (~((A == 4'd0) && (B == 4'd0))) || ((S == {3'b000, C_in}) && (C_out == 1'b0))
    );

// With A=15, B=15, C_in=0, result is 30 -> C_out=1, S=14
    check_all_ones_no_cin: assert property (
        @(posedge clk) (~((A == 4'hF) && (B == 4'hF) && (C_in == 1'b0))) || ((S == 4'he) && (C_out == 1'b1))
    );

// With A=15, B=15, C_in=1, result is 31 -> C_out=1, S=15
    check_all_ones_with_cin: assert property (
        @(posedge clk) (~((A == 4'hF) && (B == 4'hF) && (C_in == 1'b1))) || ((S == 4'hf) && (C_out == 1'b1))
    );

// If bit0 generates a carry (A0&B0), bit1 sum must invert A1^B1
    check_s1_when_carry_generated_at_bit0: assert property (
        @(posedge clk) (~(A[0] & B[0])) || (S[1] == (A[1] ^ B[1] ^ 1'b1))
    );

///// Power-good mux behavior /////
    // When VPWR > VGND, Y must equal VPB.
    check_y_selects_vpb_when_pwrgood: assert property (
        @(posedge CLK) (VPWR > VGND) |-> (Y == VPB)
    );

// When VPWR <= VGND, Y must equal VNB.
    check_y_selects_vnb_when_not_pwrgood: assert property (
        @(posedge CLK) !(VPWR > VGND) |-> (Y == VNB)
    );

// Output equals logical AND of inputs.
    check_out_is_and: assert property (
        @(posedge clk) out == (a & b)
    );

// Output HIGH only if both inputs HIGH.
    check_out_high_requires_inputs_high: assert property (
        @(posedge clk) (out == 1'b1) |-> (a && b)
    );

// If input a is LOW then output must be LOW.
    check_out_low_when_a_low: assert property (
        @(posedge clk) (!a) |-> (out == 1'b0)
    );

// If input b is LOW then output must be LOW.
    check_out_low_when_b_low: assert property (
        @(posedge clk) (!b) |-> (out == 1'b0)
    );

// If both inputs are HIGH then output must be HIGH.
    check_out_high_when_both_high: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b1)
    );

// A rising output implies both inputs are HIGH.
    check_out_rise_requires_inputs_high: assert property (
        @(posedge clk) $rose(out) |-> (a && b)
    );

// A falling output implies at least one input is LOW.
    check_out_fall_requires_one_low: assert property (
        @(posedge clk) $fell(out) |-> (!a || !b)
    );

// Out equals left shift for inputs 0..7.
    check_left_shift_range_eq: assert property (
        @(posedge clk) disable iff (1'b0) (in <= 4'd7) |-> (out == (in << 1))
    );

// Out equals right shift for inputs 8..15.
    check_right_shift_range_eq: assert property (
        @(posedge clk) disable iff (1'b0) (in >= 4'd8) |-> (out == (in >> 1))
    );

// Piecewise definition matches MSB: 0 => left shift, 1 => right shift.
    check_piecewise_functionality: assert property (
        @(posedge clk) disable iff (1'b0) out == (in[3] ? (in >> 1) : (in << 1))
    );

// LSB is zero when left shifting (in <= 7).
    check_left_shift_lsb_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in <= 4'd7) |-> (out[0] == 1'b0)
    );

// MSB is zero when right shifting (in >= 8).
    check_right_shift_msb_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in >= 4'd8) |-> (out[3] == 1'b0)
    );

// Left shift moves bits up by one (out[3:1] = in[2:0]) for in <= 7.
    check_left_shift_bit_move: assert property (
        @(posedge clk) disable iff (1'b0) (in <= 4'd7) |-> (out[3:1] == in[2:0])
    );

// Right shift moves bits down by one (out[2:0] = in[3:1]) for in >= 8.
    check_right_shift_bit_move: assert property (
        @(posedge clk) disable iff (1'b0) (in >= 4'd8) |-> (out[2:0] == in[3:1])
    );

// Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in == 4'd0) |-> (out == 4'd0)
    );

// Maximum value 15 maps to 7 (15 >> 1).
    check_fifteen_maps_to_seven: assert property (
        @(posedge clk) disable iff (1'b0) (in == 4'd15) |-> (out == 4'd7)
    );

// When S1S0==00, Q0==D and others are 0.
    sel00_routes_d_to_q0: assert property (
        @(posedge CLK) (!S1 && !S0) |-> (Q0 == D && (Q1 == 1'b0) && (Q2 == 1'b0) && (Q3 == 1'b0))
    );

// When S1S0==01, Q1==D and others are 0.
    sel01_routes_d_to_q1: assert property (
        @(posedge CLK) (!S1 &&  S0) |-> (Q1 == D && (Q0 == 1'b0) && (Q2 == 1'b0) && (Q3 == 1'b0))
    );

// When S1S0==10, Q2==D and others are 0.
    sel10_routes_d_to_q2: assert property (
        @(posedge CLK) ( S1 && !S0) |-> (Q2 == D && (Q0 == 1'b0) && (Q1 == 1'b0) && (Q3 == 1'b0))
    );

// When S1S0==11, Q3==D and others are 0.
    sel11_routes_d_to_q3: assert property (
        @(posedge CLK) ( S1 &&  S0) |-> (Q3 == D && (Q0 == 1'b0) && (Q1 == 1'b0) && (Q2 == 1'b0))
    );

// If Q0 is HIGH, then D=1 and S1S0==00.
    q0_high_implies_sel00_and_d: assert property (
        @(posedge CLK) (Q0 == 1'b1) |-> (D == 1'b1 && !S1 && !S0)
    );

// If Q1 is HIGH, then D=1 and S1S0==01.
    q1_high_implies_sel01_and_d: assert property (
        @(posedge CLK) (Q1 == 1'b1) |-> (D == 1'b1 && !S1 &&  S0)
    );

// If Q2 is HIGH, then D=1 and S1S0==10.
    q2_high_implies_sel10_and_d: assert property (
        @(posedge CLK) (Q2 == 1'b1) |-> (D == 1'b1 &&  S1 && !S0)
    );

// If Q3 is HIGH, then D=1 and S1S0==11.
    q3_high_implies_sel11_and_d: assert property (
        @(posedge CLK) (Q3 == 1'b1) |-> (D == 1'b1 &&  S1 &&  S0)
    );

// Outputs are at most one-hot at all times.
    outputs_onehot0: assert property (
        @(posedge CLK) $onehot0({Q3, Q2, Q1, Q0})
    );

// OR of all outputs equals D.
    or_of_outputs_matches_d: assert property (
        @(posedge CLK) ((Q0 | Q1 | Q2 | Q3) == D)
    );

// LSB is odd parity of input bits.
    check_lsb_parity: assert property (
        @(posedge clk) out[0] == (^in)
    );

// MSB is 1 iff exactly 2 or 3 ones (not all four).
    check_msb_two_or_three: assert property (
        @(posedge clk)
            out[1] == ( ((in[0]&in[1]) | (in[0]&in[2]) | (in[0]&in[3]) | (in[1]&in[2]) | (in[1]&in[3]) | (in[2]&in[3])) & ~(&in) )
    );

// 0000 maps to 00.
    check_map_0000: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );

// 0001 maps to 01.
    check_map_0001: assert property (
        @(posedge clk) (in == 4'b0001) |-> (out == 2'b01)
    );

// 0010 maps to 01.
    check_map_0010: assert property (
        @(posedge clk) (in == 4'b0010) |-> (out == 2'b01)
    );

// 0011 maps to 10.
    check_map_0011: assert property (
        @(posedge clk) (in == 4'b0011) |-> (out == 2'b10)
    );

// 0100 maps to 01.
    check_map_0100: assert property (
        @(posedge clk) (in == 4'b0100) |-> (out == 2'b01)
    );

// 0101 maps to 10.
    check_map_0101: assert property (
        @(posedge clk) (in == 4'b0101) |-> (out == 2'b10)
    );

// 0110 maps to 10.
    check_map_0110: assert property (
        @(posedge clk) (in == 4'b0110) |-> (out == 2'b10)
    );

// 0111 maps to 11.
    check_map_0111: assert property (
        @(posedge clk) (in == 4'b0111) |-> (out == 2'b11)
    );

// 1000 maps to 01.
    check_map_1000: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 2'b01)
    );

// 1001 maps to 10.
    check_map_1001: assert property (
        @(posedge clk) (in == 4'b1001) |-> (out == 2'b10)
    );

// 1010 maps to 10.
    check_map_1010: assert property (
        @(posedge clk) (in == 4'b1010) |-> (out == 2'b10)
    );

// 1011 maps to 11.
    check_map_1011: assert property (
        @(posedge clk) (in == 4'b1011) |-> (out == 2'b11)
    );

// 1100 maps to 10.
    check_map_1100: assert property (
        @(posedge clk) (in == 4'b1100) |-> (out == 2'b10)
    );

// 1101 maps to 11.
    check_map_1101: assert property (
        @(posedge clk) (in == 4'b1101) |-> (out == 2'b11)
    );

// 1110 maps to 11.
    check_map_1110: assert property (
        @(posedge clk) (in == 4'b1110) |-> (out == 2'b11)
    );

// 1111 maps to 00.
    check_map_1111: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 2'b00)
    );

// lt must reflect (a < b).
    check_lt_definition: assert property (
        @(posedge clk) disable iff (!reset_n) lt == (a < b)
    );

// eq must reflect (a == b).
    check_eq_definition: assert property (
        @(posedge clk) disable iff (!reset_n) eq == (a == b)
    );

// gt must reflect (a > b).
    check_gt_definition: assert property (
        @(posedge clk) disable iff (!reset_n) gt == (a > b)
    );

// Exactly one of lt/eq/gt must be HIGH.
    check_onehot_outputs: assert property (
        @(posedge clk) disable iff (!reset_n) $onehot({lt, eq, gt})
    );

// At least one of lt/eq/gt must be HIGH.
    check_outputs_complete: assert property (
        @(posedge clk) disable iff (!reset_n) (lt || eq || gt)
    );

// No two outputs can be HIGH simultaneously.
    check_outputs_mutex: assert property (
        @(posedge clk) disable iff (!reset_n) !(lt && eq) && !(lt && gt) && !(eq && gt)
    );

// and0_out equals A & B
    check_and0_out_function: assert property (
        @(posedge clk) and0_out == (A & B)
    );

// and1_out equals C & and0_out
    check_and1_out_function: assert property (
        @(posedge clk) and1_out == (C & and0_out)
    );

// X is driven by and1_out
    check_x_equals_and1_out: assert property (
        @(posedge clk) X == and1_out
    );

// X equals A & B & C
    check_x_equals_abc: assert property (
        @(posedge clk) X == (A & B & C)
    );

// If X is 1 then all inputs are 1
    check_x_high_requires_all_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (A && B && C)
    );

// If any input is 0 then X is 0
    check_any_input_low_forces_x_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C)) |-> (X == 1'b0)
    );

// If all inputs are 1 then X is 1
    check_all_inputs_high_imply_x_high: assert property (
        @(posedge clk) (A && B && C) |-> (X == 1'b1)
    );

// Rising edge of X implies all inputs are 1
    check_x_rise_requires_all_high: assert property (
        @(posedge clk) $rose(X) |-> (A && B && C)
    );

// Falling edge of X implies at least one input is 0
    check_x_fall_implies_any_low: assert property (
        @(posedge clk) $fell(X) |-> (!A || !B || !C)
    );

// Y equals PADP XOR PADN.
    check_xor_definition: assert property (
        @(posedge CLK) (Y == (PADP ^ PADN))
    );

// Clk: CLK (posedge). RESET is synchronous, active-HIGH. Logic is sequential (flop with conditional load).

    ///// Functional behavior /////
    // Only SET asserted (no RESET): Q loads 4'hF on next cycle.
    set_only_loads_ones: assert property (
        @(posedge CLK) disable iff (RESET) (SET && !RESET) |=> (Q == 4'hF)
    );

// Only RESET asserted (no SET): Q loads 4'h0 on next cycle.
    reset_only_loads_zeros: assert property (
        @(posedge CLK) (RESET && !SET) |=> (Q == 4'h0)
    );

// Both asserted: Q loads D on next cycle.
    both_high_loads_d: assert property (
        @(posedge CLK) (SET && RESET) |=> (Q == D)
    );

// Rising SET with RESET low: Q loads 4'hF on next cycle.
    set_rise_loads_ones: assert property (
        @(posedge CLK) disable iff (RESET) ($rose(SET) && !RESET) |=> (Q == 4'hF)
    );

// Rising RESET with SET low: Q loads 4'h0 on next cycle.
    reset_rise_loads_zeros: assert property (
        @(posedge CLK) ($rose(RESET) && !SET) |=> (Q == 4'h0)
    );

// q_n must be the logical inverse of q when not in reset.
    check_qn_is_inverse_of_q: assert property (
        @(posedge clk) disable iff (!reset) (q_n == ~q)
    );

// If reset is LOW at this cycle, q must be 0 on the next cycle.
    check_reset_low_clears_q_next: assert property (
        @(posedge clk) (!reset) |=> (q == 1'b0)
    );

// If reset was LOW on the previous cycle, q must be 0 now.
    check_prev_reset_low_q_is_zero_now: assert property (
        @(posedge clk) $past(!reset) |-> (q == 1'b0)
    );

// If reset is LOW at this cycle, q_n must be 1 on the next cycle.
    check_reset_low_sets_qn_next: assert property (
        @(posedge clk) (!reset) |=> (q_n == 1'b1)
    );

// If reset was LOW on the previous cycle, q_n must be 1 now.
    check_prev_reset_low_qn_is_one_now: assert property (
        @(posedge clk) $past(!reset) |-> (q_n == 1'b1)
    );

// q and q_n must never be equal when not in reset.
    check_q_and_qn_never_equal: assert property (
        @(posedge clk) disable iff (!reset) (q != q_n)
    );

// While reset is held across consecutive cycles, Q is 0.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (q == 1'b0)
    );

// Clock: CLK (posedge). Reset: RST active-high asynchronous.
    // Sequential 4-bit up-counter with enable; reset clears to 0; EN increments, else holds.

    // On any clock where reset is asserted, COUNT must be 0.
    check_reset_clears_count: assert property (
        @(posedge CLK) RST |-> (COUNT == 4'b0000)
    );

// Immediately after reset deasserts, if EN is 0 then COUNT remains 0.
    check_hold_after_reset_release_without_en: assert property (
        @(posedge CLK) disable iff (RST) $fell(RST) && !EN |-> (COUNT == 4'b0000)
    );

// G must equal the Gray encoding of D
    check_gray_encode_vector: assert property (
        @(posedge CLK) G == {D[3], (D[3]^D[2]), (D[2]^D[1]), (D[1]^D[0])}
    );

// Out equals selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) out == ((sel == 1'b0) ? A : B)
    );

// When sel is 0, out equals A.
    check_sel0_routes_A: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == A)
    );

// When sel is 1, out equals B.
    check_sel1_routes_B: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == B)
    );

// G[0] equals B[0].
    check_g0_map: assert property (
        @(posedge CLK) disable iff (1'b0) (G[0] == B[0])
    );

// G[1] equals B[0] XOR B[1].
    check_g1_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (G[1] == (B[0] ^ B[1]))
    );

// G[2] equals B[1] XOR B[2].
    check_g2_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (G[2] == (B[1] ^ B[2]))
    );

// G[3] equals B[2] XOR B[3].
    check_g3_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (G[3] == (B[2] ^ B[3]))
    );

// Vector form: G equals B XOR (B << 1).
    check_vector_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) (G == (B ^ (B << 1)))
    );

// Out equals S0 when Sel is 2'b00.
    check_sel00_routes_S0: assert property (
        @(posedge CLK) (Sel == 2'b00) |-> (out == S0)
    );

// Out equals S1 when Sel is 2'b01.
    check_sel01_routes_S1: assert property (
        @(posedge CLK) (Sel == 2'b01) |-> (out == S1)
    );

// Out equals S2 when Sel is 2'b10.
    check_sel10_routes_S2: assert property (
        @(posedge CLK) (Sel == 2'b10) |-> (out == S2)
    );

// Out equals S3 when Sel is 2'b11.
    check_sel11_routes_S3: assert property (
        @(posedge CLK) (Sel == 2'b11) |-> (out == S3)
    );

// Structural equivalence to the RTL ternary expression.
    check_functional_equivalence: assert property (
        @(posedge CLK) out == (Sel[1] ? (Sel[0] ? S3 : S2) : (Sel[0] ? S1 : S0))
    );

// When Sel[1]==0, out selects between S1 and S0 per Sel[0].
    check_lower_half_select: assert property (
        @(posedge CLK) (Sel[1] == 1'b0) |-> (out == (Sel[0] ? S1 : S0))
    );

// When Sel[1]==1, out selects between S3 and S2 per Sel[0].
    check_upper_half_select: assert property (
        @(posedge CLK) (Sel[1] == 1'b1) |-> (out == (Sel[0] ? S3 : S2))
    );

///// Reset behavior /////
  // While reset is held low across cycles, Q is 0.
  check_reset_holds_zero: assert property (
    @(posedge CLK) (!RST && $past(!RST)) |-> (Q == 4'b0)
  );

// If reset is low this cycle, Q is 0 next cycle.
  check_reset_next_cycle_zero: assert property (
    @(posedge CLK) (!RST) |=> (Q == 4'b0)
  );

// On reset deassertion edge, Q remains 0 in the current cycle.
  check_zero_on_reset_release_cycle: assert property (
    @(posedge CLK) $rose(RST) |-> (Q == 4'b0)
  );

///// Functional behavior /////
  // With reset deasserted, Q updates to D with one-cycle latency.
  check_q_follows_d_one_cycle: assert property (
    @(posedge CLK) disable iff (!RST) 1'b1 |=> (Q == $past(D))
  );

// When not in reset, any change in Q matches the previous D.
  check_q_change_matches_prev_d: assert property (
    @(posedge CLK) disable iff (!RST) $changed(Q) |-> (Q == $past(D))
  );

// When not in reset for two cycles and D changes, Q changes next cycle.
  check_d_change_propagates: assert property (
    @(posedge CLK) (RST && $past(RST) && (D != $past(D))) |=> (Q != $past(Q))
  );

// When not in reset for two cycles and D is stable, Q is stable next cycle.
  check_d_stable_keeps_q_stable: assert property (
    @(posedge CLK) (RST && $past(RST) && $stable(D)) |=> (Q == $past(Q))
  );

// Output equals bitwise XOR of a and b.
    check_xor_definition: assert property (
        @(posedge clk) disable iff (!rst_n) out == (a ^ b)
    );

// If a is zero, output passes through b.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (!rst_n) (a == 32'h0) |-> (out == b)
    );

// If b is zero, output passes through a.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (!rst_n) (b == 32'h0) |-> (out == a)
    );

// If inputs are equal, output is zero.
    check_equal_inputs_zero_out: assert property (
        @(posedge clk) disable iff (!rst_n) (a == b) |-> (out == 32'h0)
    );

// If output is zero, inputs are equal.
    check_zero_out_implies_equal_inputs: assert property (
        @(posedge clk) disable iff (!rst_n) (out == 32'h0) |-> (a == b)
    );

// Self-inverse: (a ^ b) ^ b == a.
    check_self_inverse_via_b: assert property (
        @(posedge clk) disable iff (!rst_n) ((out ^ b) == a)
    );

// Self-inverse: (a ^ b) ^ a == b.
    check_self_inverse_via_a: assert property (
        @(posedge clk) disable iff (!rst_n) ((out ^ a) == b)
    );

// Sum and carry match 4-bit addition with carry-in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// LSB sum is XOR of A[0], B[0], and Cin.
    check_s0_is_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// When A[1]==B[1], S[1] equals carry out from bit0.
    check_s1_matches_c1_when_a1_eq_b1: assert property (
        @(posedge clk)
        (A[1] == B[1]) |-> (S[1] == ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

// When A[1]!=B[1], S[1] is inverse of carry out from bit0.
    check_s1_inverts_c1_when_a1_ne_b1: assert property (
        @(posedge clk)
        (A[1] ^ B[1]) |-> (S[1] == ~((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

// No overflow implies Cout is 0.
    check_cout_zero_when_no_overflow: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) < 5'd16) |-> (Cout == 1'b0)
    );

// Overflow implies Cout is 1.
    check_cout_one_when_overflow: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> (Cout == 1'b1)
    );

// Adding zero B and zero Cin passes A through and no carry.
    check_add_zero_B_yields_A: assert property (
        @(posedge clk) ((B == 4'b0) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

// Adding zero A and zero Cin passes B through and no carry.
    check_add_zero_A_yields_B: assert property (
        @(posedge clk) ((A == 4'b0) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

// B is bitwise complement of A with Cin=0 yields S=0xF and no carry.
    check_complement_sum_all_ones: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b0)) |-> ((S == 4'hF) && (Cout == 1'b0))
    );

// B is bitwise complement of A with Cin=1 yields S=0x0 and carry out.
    check_complement_with_cin_carryout: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b1)) |-> ((S == 4'h0) && (Cout == 1'b1))
    );

// While reset is asserted low, count must be 0.
    reset_drives_zero: assert property (
        @(posedge clk) !rst |-> (count == 3'b000)
    );

// When enable is LOW, count holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && !enable) |=> (count == $past(count))
    );

// When enable and load are HIGH, next count equals data_in.
    load_updates_count: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && load) |=> (count == $past(data_in))
    );

// When enable is HIGH and load is LOW, next count increments by 1 (mod 8).
    increment_updates_count: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load) |=> (count == ($past(count) + 3'd1))
    );

// Any change to count requires enable to have been HIGH in the previous cycle.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && $changed(count)) |-> $past(enable)
    );

// If load is HIGH but enable is LOW, count does not change.
    load_ignored_without_enable: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && !enable && load) |=> (count == $past(count))
    );

// Increment wraps from 7 to 0 when enable is HIGH and load is LOW.
    wrap_on_increment_from_7: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load && ($past(count) == 3'd7)) |=> (count == 3'd0)
    );

// Increment does not produce 0 unless previous value was 7.
    no_zero_after_increment_unless_from_7: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load && ($past(count) != 3'd7)) |=> (count != 3'd0)
    );

// Increment always changes count (no self-loop when adding 1 mod 8).
    increment_always_changes_value: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load) |=> (count != $past(count))
    );

// Two consecutive increments add 2 (mod 8).
    two_step_increment_sequence: assert property (
        @(posedge clk) disable iff (!rst)
            (enable && !load) ##1 (enable && !load) |=> (count == ($past(count,2) + 3'd2))
    );

///// Exact decode mapping /////
    // Outputs for R-type opcode (000000).
    decode_rtype_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_RTYPE) |-> (brnch == 1'b0) && (memorywrite == 1'b0) && (memoryread == 1'b0) &&
                                 (alusrc == 1'b0) && (regw == 1'b1) && (regdst == 1'b1) &&
                                 (aluop == 1'b1) && (memtoreg == 1'b1)
    );

// Outputs for LW opcode (100011).
    decode_lw_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_LW) |-> (brnch == 1'b0) && (memorywrite == 1'b0) && (memoryread == 1'b1) &&
                              (alusrc == 1'b1) && (regw == 1'b1) && (regdst == 1'b0) &&
                              (aluop == 1'b0) && (memtoreg == 1'b0)
    );

// Outputs for SW opcode (101011).
    decode_sw_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_SW) |-> (brnch == 1'b0) && (memorywrite == 1'b1) && (memoryread == 1'b0) &&
                              (alusrc == 1'b1) && (regw == 1'b0) && (regdst == 1'b0) &&
                              (aluop == 1'b0) && (memtoreg == 1'b0)
    );

// Outputs for BEQ opcode (000100).
    decode_beq_match: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OP_BEQ) |-> (brnch == 1'b1) && (memorywrite == 1'b0) && (memoryread == 1'b0) &&
                              (alusrc == 1'b0) && (regw == 1'b0) && (regdst == 1'b0) &&
                              (aluop == 1'b0) && (memtoreg == 1'b0)
    );

// Outputs for all other opcodes: all control signals LOW.
    decode_default_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout != OP_RTYPE && imemout != OP_LW && imemout != OP_SW && imemout != OP_BEQ)
        |-> (brnch == 1'b0) && (memorywrite == 1'b0) && (memoryread == 1'b0) &&
            (alusrc == 1'b0) && (regw == 1'b0) && (regdst == 1'b0) &&
            (aluop == 1'b0) && (memtoreg == 1'b0)
    );

///// Invariants implied by the decode /////
    // Read and write to memory are never asserted together.
    check_memread_write_mutex: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(memoryread && memorywrite)
    );

// BRNCH can be HIGH only for BEQ.
    unique_brnch_on_beq: assert property (
        @(posedge clk) disable iff (!reset_n)
        brnch |-> (imemout == OP_BEQ)
    );

// MEMORYREAD can be HIGH only for LW.
    unique_memoryread_on_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memoryread |-> (imemout == OP_LW)
    );

// MEMORYWRITE can be HIGH only for SW.
    unique_memorywrite_on_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memorywrite |-> (imemout == OP_SW)
    );

// MEMTOREG can be HIGH only for R-type.
    unique_memtoreg_on_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        memtoreg |-> (imemout == OP_RTYPE)
    );

// REGDST can be HIGH only for R-type.
    unique_regdst_on_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        regdst |-> (imemout == OP_RTYPE)
    );

// ALUOP can be HIGH only for R-type.
    unique_aluop_on_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        aluop |-> (imemout == OP_RTYPE)
    );

// REGW can be HIGH only for R-type or LW.
    unique_regw_on_rtype_or_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        regw |-> ((imemout == OP_RTYPE) || (imemout == OP_LW))
    );

// ALUSRC can be HIGH only for LW or SW.
    unique_alusrc_on_lw_or_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        alusrc |-> ((imemout == OP_LW) || (imemout == OP_SW))
    );

// Next-state function: ENCLK_next = TE ? EN : ENCLK
    check_next_state_function: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == ($past(TE) ? $past(EN) : $past(ENCLK)))
    );

// When TE is high, capture EN on the next cycle
    check_capture_when_te_high: assert property (
        @(posedge CLK) TE |=> (ENCLK == $past(EN))
    );

// When TE is low, hold ENCLK value on the next cycle
    check_hold_when_te_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

// Y matches sum-of-products definition.
    check_y_sum_of_products: assert property (
        @(posedge CLK) disable iff (!RESETn) Y === ((A & ~B) | (~A & B))
    );

// Y equals bitwise XOR of A and B.
    check_y_xor_equiv: assert property (
        @(posedge CLK) disable iff (!RESETn) Y === (A ^ B)
    );

// When inputs are equal, Y is 0.
    check_y_low_when_inputs_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (A === B) |-> (Y === 1'b0)
    );

// When inputs differ, Y is 1.
    check_y_high_when_inputs_differ: assert property (
        @(posedge CLK) disable iff (!RESETn) (A !== B) |-> (Y === 1'b1)
    );

// If Y is 1, exactly one input is 1.
    check_one_hot_inputs_when_y_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y === 1'b1) |-> ((A === 1'b1) ^ (B === 1'b1))
    );

// If Y is 0, inputs are equal.
    check_inputs_equal_when_y_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y === 1'b0) |-> (A === B)
    );

// Truth table: A=0, B=0 -> Y=0.
    check_tt_00: assert property (
        @(posedge CLK) disable iff (!RESETn) (A === 1'b0 && B === 1'b0) |-> (Y === 1'b0)
    );

// Truth table: A=0, B=1 -> Y=1.
    check_tt_01: assert property (
        @(posedge CLK) disable iff (!RESETn) (A === 1'b0 && B === 1'b1) |-> (Y === 1'b1)
    );

// Truth table: A=1, B=0 -> Y=1.
    check_tt_10: assert property (
        @(posedge CLK) disable iff (!RESETn) (A === 1'b1 && B === 1'b0) |-> (Y === 1'b1)
    );

// Truth table: A=1, B=1 -> Y=0.
    check_tt_11: assert property (
        @(posedge CLK) disable iff (!RESETn) (A === 1'b1 && B === 1'b1) |-> (Y === 1'b0)
    );

///// Reset behavior /////
    // While global reset is asserted, sync_dat_o must be INIT.
    check_sync_init_while_rst: assert property (
        @(posedge clk_i) rst_i |-> (sync_dat_o == INIT)
    );

///// Functional mapping /////
    // Y equals the 4:1 mux function of S selecting A/B/C/D.
    check_mux_equation: assert property (
        @(posedge CLK) Y == ((S == 2'b00) ? A :
                             (S == 2'b01) ? B :
                             (S == 2'b10) ? C : D)
    );

// When S==00, Y must equal A.
    check_sel_00: assert property (
        @(posedge CLK) (S == 2'b00) |-> (Y == A)
    );

// When S==01, Y must equal B.
    check_sel_01: assert property (
        @(posedge CLK) (S == 2'b01) |-> (Y == B)
    );

// When S==10, Y must equal C.
    check_sel_10: assert property (
        @(posedge CLK) (S == 2'b10) |-> (Y == C)
    );

// When S==11, Y must equal D.
    check_sel_11: assert property (
        @(posedge CLK) (S == 2'b11) |-> (Y == D)
    );

// Clock: CLK (posedge). No reset in RTL. Sequential: EN-gated register capturing TE into ENCLK.

    // ENCLK next equals TE if EN was 1, else holds previous ENCLK.
    check_functional_update_equation: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == ($past(EN) ? $past(TE) : $past(ENCLK)))
    );

// When EN is 1, ENCLK on the next edge equals TE from this edge.
    check_update_on_enable: assert property (
        @(posedge CLK) EN |=> (ENCLK == $past(TE))
    );

// When EN is 0, ENCLK holds its previous value on the next edge.
    check_hold_when_disabled: assert property (
        @(posedge CLK) !EN |=> (ENCLK == $past(ENCLK))
    );

// If EN is 1 and TE equals current ENCLK, no change occurs next cycle.
    check_no_change_on_enable_if_same_data: assert property (
        @(posedge CLK) (EN && (TE == ENCLK)) |=> (ENCLK == $past(ENCLK))
    );

// If EN is 1 and TE differs from current ENCLK, a change occurs next cycle.
    check_change_on_enable_if_data_diff: assert property (
        @(posedge CLK) (EN && (TE != ENCLK)) |=> (ENCLK != $past(ENCLK))
    );

// Each cycle, ENCLK is either the held value or the prior cycle's TE.
    check_next_value_is_prev_data_or_hold: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK == $past(ENCLK)) || (ENCLK == $past(TE)))
    );

// Synchronous clear drives count to zero on that clock.
  sync_clear_zero: assert property (
    @(posedge clk) clr |=> (count == 8'h00)
  );

// With enable and no clear (prev cycle not in clear), count increments by 1.
  inc_on_ce: assert property (
    @(posedge clk) disable iff (clr)
      (ce && $past(!clr)) |=> (count == $past(count) + 8'd1)
  );

// With ce low and no clear (prev cycle not in clear), count holds.
  hold_when_ce_low: assert property (
    @(posedge clk) disable iff (clr)
      (!ce && $past(!clr)) |=> (count == $past(count))
  );

// clr dominates ce when both are high.
  clr_priority_over_ce: assert property (
    @(posedge clk) (clr && ce) |=> (count == 8'h00)
  );

// Sum and carry must equal 5-bit addition of A+B+Ci.
    check_sum_matches_adder: assert property (
        @(posedge CLK) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// Carry-out equals MSB of 5-bit sum.
    check_carry_is_msb_of_sum: assert property (
        @(posedge CLK) Co == (({1'b0, A} + {1'b0, B} + Ci) >= 5'd16)
    );

// Bit 0 sum is XOR of A[0], B[0], Ci.
    check_s0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Bit 1 sum is XOR of A[1], B[1], and c1.
    check_s1_xor: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ ( (A[0] & B[0]) | (A[0] & Ci) | (B[0] & Ci) ))
    );

// When B==0 and Ci==0, output equals A with zero carry.
    check_propagate_A_when_B_zero: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, A})
    );

// When A==0 and Ci==0, output equals B with zero carry.
    check_propagate_B_when_A_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, B})
    );

// After 96 clocks, o_cpllpd_ovrd must be 0.
    cpllpd_zero_after_96: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##96 (o_cpllpd_ovrd == 1'b0)
    );

// After 128 clocks, o_cpllreset_ovrd must be 0.
    cpllreset_zero_after_128: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 (o_cpllreset_ovrd == 1'b0)
    );

// After 96 clocks, o_cpllpd_ovrd remains 0 for at least 64 clocks.
    cpllpd_zero_hold_64_post96: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##96 (o_cpllpd_ovrd == 1'b0)[*64]
    );

// After 128 clocks, o_cpllreset_ovrd remains 0 for at least 64 clocks.
    cpllreset_zero_hold_64_post128: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 (o_cpllreset_ovrd == 1'b0)[*64]
    );

// After 128 clocks, both outputs must be 0 simultaneously.
    both_zero_after_128: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 ((o_cpllpd_ovrd == 1'b0) && (o_cpllreset_ovrd == 1'b0))
    );

// o_cpllpd_ovrd is known (not X/Z) after 96 clocks.
    cpllpd_known_after_96: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##96 (!$isunknown(o_cpllpd_ovrd))
    );

// o_cpllreset_ovrd is known (not X/Z) after 128 clocks.
    cpllreset_known_after_128: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 (!$isunknown(o_cpllreset_ovrd))
    );

// After 128 clocks, both outputs stay 0 for at least 64 clocks.
    both_zero_hold_64_post128: assert property (
        @(posedge i_ibufds_gte2) 1'b1 |-> ##128 ((o_cpllpd_ovrd == 1'b0) && (o_cpllreset_ovrd == 1'b0))[*64]
    );

// Clocks: posedge dqs_in, posedge strobe; no reset in RTL.
    // Sequential logic: 5-stage delay line on dqs_in; so is registered on strobe when se=1.

    ///// dqs_in delay line behavior /////
    // dqs_out equals dqs_in delayed by 5 posedges of dqs_in.
    check_dqsout_delay_5: assert property (
        @(posedge dqs_in) 1'b1 |-> ##5 (dqs_out == $past(dqs_in,5))
    );

///// strobe/so register behavior /////
    // When se==1 at strobe edge, so captures si.
    check_so_captures_si_when_se: assert property (
        @(posedge strobe) se |=> (so == $past(si))
    );

// When se==0 at strobe edge, so holds its previous value.
    check_so_holds_when_se_low: assert property (
        @(posedge strobe) !se |=> (so == $past(so))
    );

// When reset is asserted low, Q must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst_n) |-> (Q == 4'b0000)
    );

// Upper two bits of Q are always zero when out of reset.
    check_q_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!rst_n) (Q[3:2] == 2'b00)
    );

// Once Q is zero out of reset, it remains zero on the next cycle.
    check_q_zero_absorbing: assert property (
        @(posedge clk) disable iff (!rst_n) (Q == 4'b0000) |=> (Q == 4'b0000)
    );

// On reset deassertion, Q becomes zero at the first active clock.
    check_q_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> (Q == 4'b0000)
    );

// Result equals bitwise XOR of inputs every cycle.
    check_result_matches_xor: assert property (
        @(posedge clk) result == (a ^ b)
    );

// If inputs are equal, result is zero.
    check_zero_when_inputs_equal: assert property (
        @(posedge clk) (a == b) |-> (result == 8'h00)
    );

// If b is zero, result equals a.
    check_passthrough_when_b_zero: assert property (
        @(posedge clk) (b == 8'h00) |-> (result == a)
    );

// If a is zero, result equals b.
    check_passthrough_when_a_zero: assert property (
        @(posedge clk) (a == 8'h00) |-> (result == b)
    );

// If b is bitwise-not of a, result is all ones.
    check_ones_when_b_is_not_a: assert property (
        @(posedge clk) (b == ~a) |-> (result == 8'hFF)
    );

// When b is all ones, result is bitwise-not of a.
    check_result_inverts_a_when_b_ones: assert property (
        @(posedge clk) (b == 8'hFF) |-> (result == ~a)
    );

// When a is all ones, result is bitwise-not of b.
    check_result_inverts_b_when_a_ones: assert property (
        @(posedge clk) (a == 8'hFF) |-> (result == ~b)
    );

// Clock: posedge clk; Reset: active-high synchronous 'reset'; Logic: sequential.

    // Synchronous reset drives count=0 and overflow=0 on the following cycle.
    reset_clears_outputs_next: assert property (
        @(posedge clk) reset |=> (count == 4'h0) && (overflow == 1'b0)
    );

// When disabled, both outputs hold their previous values.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count)) && (overflow == $past(overflow))
    );

// With enable and count==15, next count wraps to 0 and overflow asserts.
    wrap_sets_overflow_and_zero: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0) && (overflow == 1'b1)
    );

// With enable and count!=15, next count increments by 1.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (enable && (count != 4'hF)) |=> (count == $past(count) + 4'd1)
    );

// With enable and count!=15, next overflow is 0.
    no_overflow_on_non_wrap: assert property (
        @(posedge clk) disable iff (reset) (enable && (count != 4'hF)) |=> (overflow == 1'b0)
    );

// When enabled, count must change on the next cycle.
    count_changes_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count != $past(count))
    );

// Clock: clk; Reset: reset (active-high, synchronous). Sequential regs with comb output.

    // On reset assertion, output becomes 0 on the next clock.
    reset_clears_output_next: assert property (
        @(posedge clk) reset |=> (parallel_out == 8'h00)
    );

// While reset is held across consecutive cycles, output remains 0.
    output_zero_while_reset_held: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (parallel_out == 8'h00)
    );

// If enable is LOW in the current cycle, output holds into the next cycle.
    hold_next_when_disable_now: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (parallel_out == $past(parallel_out))
    );

// If enable is LOW for two consecutive cycles, output is stable across both boundaries.
    stable_across_two_disable_cycles: assert property (
        @(posedge clk) disable iff (reset) (!enable ##1 !enable) |-> ($stable(parallel_out) ##1 $stable(parallel_out))
    );

// out implements two's complement of in (4-bit wrap)
    check_twos_complement_equation: assert property (
        @(posedge clk) out == ((~in) + 4'd1)
    );

// in + out wraps to zero modulo 16
    check_additive_inverse_mod16: assert property (
        @(posedge clk) (in + out) == 4'd0
    );

// 0 maps to 0
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 4'd0)
    );

// 1 maps to 0xF
    check_one_maps_to_all_ones: assert property (
        @(posedge clk) (in == 4'd1) |-> (out == 4'hF)
    );

// 0xF maps to 1
    check_all_ones_maps_to_one: assert property (
        @(posedge clk) (in == 4'hF) |-> (out == 4'd1)
    );

// Two's complement equals (0 - in) modulo 16
    check_subtraction_form: assert property (
        @(posedge clk) out == (4'd0 - in)
    );

// Double two's complement returns original value
    check_double_complement_is_identity: assert property (
        @(posedge clk) ((~out) + 4'd1) == in
    );

// Bitwise NOT of out equals (in - 1) modulo 16
    check_not_out_equals_in_minus_one: assert property (
        @(posedge clk) (~out) == (in - 4'd1)
    );

// LSB is preserved by two's complement
    check_lsb_preserved: assert property (
        @(posedge clk) out[0] == in[0]
    );

// Minimum 4-bit value (8) maps to itself
    check_min_int_maps_to_itself: assert property (
        @(posedge clk) (in == 4'd8) |-> (out == 4'd8)
    );

// d_out must always match the full case mapping of the RTL.
    check_full_mapping: assert property (
        @(posedge CLK)
            1'b1 |=> (
                d_out == (
                    (shift_amount == 3'd0) ? d_in :
                    (shift_amount == 3'd1) ? {d_in[0],     d_in[7:1]} :
                    (shift_amount == 3'd2) ? {d_in[1:0],   d_in[7:2]} :
                    (shift_amount == 3'd3) ? {d_in[2:0],   d_in[7:3]} :
                    (shift_amount == 3'd4) ? {d_in[3:0],   d_in[7:4]} :
                    (shift_amount == 3'd5) ? {d_in[4:0],   d_in[7:5]} :
                    (shift_amount == 3'd6) ? {d_in[5:0],   d_in[7:6]} :
                                              8'h00
                )
            )
    );

// Addition mode: S is O + A (4-bit).
    check_add_sum: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b1) |-> (S == ((O + A) & 4'hF))
    );

// Addition mode: D is zero.
    check_add_d_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b1) |-> (D == 4'b0)
    );

// Addition mode: B is zero.
    check_add_b_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b1) |-> (B == 1'b0)
    );

// Subtraction mode: S is zero.
    check_sub_s_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0) |-> (S == 4'b0)
    );

// Subtraction no-borrow path: D = (O - A) (4-bit).
    check_sub_no_borrow_d: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && !(O < A)) |-> (D == ((O - A) & 4'hF))
    );

// Subtraction no-borrow path: B = 0.
    check_sub_no_borrow_b: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && !(O < A)) |-> (B == 1'b0)
    );

// Subtraction borrow path: D = (O + 16) - A (low 4 bits).
    check_sub_borrow_d: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && (O < A)) |-> (D == (((O + 5'd16) - A) & 4'hF))
    );

// Subtraction borrow path: B = 1.
    check_sub_borrow_b: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && (O < A)) |-> (B == 1'b1)
    );

// In subtraction mode, B matches (O < A).
    check_sub_b_matches_comparison: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0) |-> (B == (O < A))
    );

// In subtraction mode, D equals (O - A) modulo 16.
    check_sub_d_modulo: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0) |-> (D == ((O - A) & 4'hF))
    );

// Special case: O == A in subtraction yields D=0 and B=0.
    check_sub_equal_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && (O == A)) |-> (D == 4'b0 && B == 1'b0)
    );

// Out is 0 when input has zero 1s (0000).
    map_0ones: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );

// Out is 1 when input has exactly one 1.
    map_1one: assert property (
        @(posedge clk) (in inside {4'b0001, 4'b0010, 4'b0100, 4'b1000}) |-> (out == 2'b01)
    );

// Out is 2 when input has exactly two 1s.
    map_2ones: assert property (
        @(posedge clk) (in inside {4'b0011, 4'b0101, 4'b0110, 4'b1001, 4'b1010, 4'b1100}) |-> (out == 2'b10)
    );

// Out is 3 when input has three or four 1s (saturating at 3).
    map_3or4ones: assert property (
        @(posedge clk) (in inside {4'b0111, 4'b1011, 4'b1101, 4'b1110, 4'b1111}) |-> (out == 2'b11)
    );

///// Functional mapping /////
    // If bit 3 is set, pos must be 2'b11.
    map_bit3_priority: assert property (
        @(posedge CLK) disable iff (!RESETn) in[3] |-> (pos == 2'b11)
    );

// If bit 2 is set and bit 3 is clear, pos must be 2'b10.
    map_bit2_priority: assert property (
        @(posedge CLK) disable iff (!RESETn) (!in[3] && in[2]) |-> (pos == 2'b10)
    );

// If bit 1 is set and bits 3:2 are clear, pos must be 2'b01.
    map_bit1_priority: assert property (
        @(posedge CLK) disable iff (!RESETn) (!in[3] && !in[2] && in[1]) |-> (pos == 2'b01)
    );

// If only bit 0 is the highest set (bits 3:1 clear and bit 0 set), pos must be 2'b00.
    map_bit0_priority: assert property (
        @(posedge CLK) disable iff (!RESETn) (!in[3] && !in[2] && !in[1] && in[0]) |-> (pos == 2'b00)
    );

// If input is zero, pos must be 2'b00.
    map_zero_input: assert property (
        @(posedge CLK) disable iff (!RESETn) (in == 4'b0000) |-> (pos == 2'b00)
    );

///// Inverse mapping /////
    // If pos is 2'b11, bit 3 must be set.
    inv_pos_11_implies_bit3: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos == 2'b11) |-> (in[3] == 1'b1)
    );

// If pos is 2'b10, bit 2 must be set and bit 3 must be clear.
    inv_pos_10_implies_bit2_only_higher_clear: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos == 2'b10) |-> (!in[3] && in[2])
    );

// If pos is 2'b01, bit 1 must be set and bits 3:2 must be clear.
    inv_pos_01_implies_bit1_only_higher_clear: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos == 2'b01) |-> (!in[3] && !in[2] && in[1])
    );

// If pos is 2'b00, input must be zero or bit 0 is highest set (bits 3:1 clear).
    inv_pos_00_implies_zero_or_bit0_only: assert property (
        @(posedge CLK) disable iff (!RESETn) (pos == 2'b00) |-> ((in == 4'b0000) || (!in[3] && !in[2] && !in[1] && in[0]))
    );

///// Full spec equivalence /////
    // pos equals the specified priority-encoder function of in.
    pos_matches_function: assert property (
        @(posedge CLK) disable iff (!RESETn)
            pos == ((in == 4'b0000) ? 2'b00 :
                    (in[3] ? 2'b11 :
                     (in[2] ? 2'b10 :
                      (in[1] ? 2'b01 :
                               2'b00))))
    );

// S equals (A+B) modulo 16.
    check_sum_mod16: assert property (
        @(posedge clk) S == ((A + B) & 4'hF)
    );

// Adding zero on B leaves S equal to A.
    check_identity_B_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (S == A)
    );

// Adding zero on A leaves S equal to B.
    check_identity_A_zero: assert property (
        @(posedge clk) (A == 4'd0) |-> (S == B)
    );

// Both inputs zero results in zero sum.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 4'd0 && B == 4'd0) |-> (S == 4'd0)
    );

// On reset, Q becomes zero on the next cycle.
    reset_drives_zero_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'd0)
    );

// Reset overrides EN when both are asserted.
    reset_overrides_enable: assert property (
        @(posedge CLK) (RST && EN) |=> (Q == 4'd0)
    );

// When EN=0 and not in reset, Q holds its value.
    hold_when_en_low: assert property (
        @(posedge CLK) disable iff (RST) (!EN) |=> $stable(Q)
    );

// When EN=1 and not in reset, Q increments by 1 modulo 16.
    increment_when_en_high: assert property (
        @(posedge CLK) disable iff (RST) EN |=> (Q == $past(Q) + 4'd1)
    );

// X implements A1_N & ~A2_N & B1 & ~B2.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A1_N && !A2_N && B1 && !B2)
    );

// X can be 1 only when the input pattern holds.
    check_x_high_requires_pattern: assert property (
        @(posedge CLK) X |-> (A1_N && !A2_N && B1 && !B2)
    );

// When the input pattern holds, X must be 1.
    check_pattern_implies_x_high: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) |-> X
    );

// A1_N low forces X low.
    check_a1n_zero_forces_x_zero: assert property (
        @(posedge CLK) !A1_N |-> !X
    );

// A2_N high forces X low.
    check_a2n_one_forces_x_zero: assert property (
        @(posedge CLK) A2_N |-> !X
    );

// B1 low forces X low.
    check_b1_zero_forces_x_zero: assert property (
        @(posedge CLK) !B1 |-> !X
    );

// B2 high forces X low.
    check_b2_one_forces_x_zero: assert property (
        @(posedge CLK) B2 |-> !X
    );

// Leaving the pattern via A1_N going low makes X low next cycle.
    check_leave_pattern_via_a1n_drop: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (!A1_N) |-> !X
    );

// Leaving the pattern via A2_N going high makes X low next cycle.
    check_leave_pattern_via_a2n_rise: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (A2_N) |-> !X
    );

// Leaving the pattern via B1 going low makes X low next cycle.
    check_leave_pattern_via_b1_drop: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (!B1) |-> !X
    );

// Leaving the pattern via B2 going high makes X low next cycle.
    check_leave_pattern_via_b2_rise: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (B2) |-> !X
    );

// ctrl=00: dout equals B left-shifted by A[4:0].
    check_left_shift_correctness: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (dout == (B << A[4:0]))
    );

// ctrl=01: dout equals B logical-right-shifted by A[4:0].
    check_right_logical_shift_correctness: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (dout == (B >> A[4:0]))
    );

// ctrl=10 (default): dout passes B unchanged.
    check_noop_ctrl_10_outputs_input: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (dout == B)
    );

// Zero shift amount yields passthrough regardless of ctrl.
    check_zero_shift_amount_no_change: assert property (
        @(posedge CLK) (A[4:0] == 5'd0) |-> (dout == B)
    );

// Left shift with nonzero amount forces LSB to 0.
    check_left_shift_lsb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b00 && (A[4:0] != 5'd0)) |-> (dout[0] == 1'b0)
    );

// Logical right shift with nonzero amount forces MSB to 0.
    check_logical_right_msb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b01 && (A[4:0] != 5'd0)) |-> (dout[31] == 1'b0)
    );

// Arithmetic right shift with nonzero amount preserves sign bit.
    check_arith_right_sign_preserved: assert property (
        @(posedge CLK) (ctrl == 2'b11 && (A[4:0] != 5'd0)) |-> (dout[31] == B[31])
    );

// Zero data input always yields zero output.
    check_zero_data_maps_to_zero: assert property (
        @(posedge CLK) (B == 32'h0) |-> (dout == 32'h0)
    );

// Mux output must equal selected input.
    check_mux_function: assert property (
        @(posedge clk) c == (sel ? b : a)
    );

// When sel==0, output equals a.
    check_sel0_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (c == a)
    );

// When sel==1, output equals b.
    check_sel1_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (c == b)
    );

// If inputs are equal, output equals that value regardless of sel.
    check_equal_inputs_force_equal_output: assert property (
        @(posedge clk) (a == b) |-> (c == a)
    );

// If output differs from a, selection must be b and b must differ from a.
    check_output_diff_from_a_implies_select_b: assert property (
        @(posedge clk) (c != a) |-> (sel && (b != a))
    );

// If output differs from b, selection must be a and a must differ from b.
    check_output_diff_from_b_implies_select_a: assert property (
        @(posedge clk) (c != b) |-> (!sel && (a != b))
    );

// On reset, counter must be all zeros on the next cycle.
    check_reset_clears_counter_next: assert property (
        @(posedge clk) reset |=> (counter == 64'b0)
    );

// On reset, output must be all zeros on the next cycle.
    check_reset_clears_output_next: assert property (
        @(posedge clk) reset |=> (output_val == 64'b0)
    );

// Output bits can only be 1 where the replicated input mask bits are 1.
    check_output_mask_subset: assert property (
        @(posedge clk) disable iff (reset)
            (output_val & ~{8{input_val}}) == 64'b0
    );

// If the input mask is all zeros, the output must be zero.
    check_output_zero_when_input_zero: assert property (
        @(posedge clk) disable iff (reset)
            (input_val == 8'h00) |-> (output_val == 64'b0)
    );

///// Reset behavior /////
    // During reset, readdata must be 0.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'h0)
    );

///// Output formatting /////
    // Upper 12 bits of readdata are always zero when not in reset.
    check_readdata_upper_zero: assert property (
        @(posedge clk) disable iff (!reset_n) readdata[31:20] == 12'b0
    );

// Next-cycle readdata is zero when previous address was 2'b10 or 2'b11.
    check_update_on_addr_other_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
            $past(reset_n) && ($past(address) inside {2'b10,2'b11}) |->
                (readdata == 32'h0)
    );

// SUM implements three-input XOR of A, B, CI.
    check_sum_xor3: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT_N is the inverse of the majority function of A, B, CI.
    check_coutn_inverse_majority: assert property (
        @(posedge clk) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

// When A equals B, SUM equals CI.
    check_sum_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == CI)
    );

// When A differs from B, SUM equals inverted CI.
    check_sum_when_ab_differs: assert property (
        @(posedge clk) (A != B) |-> (SUM == ~CI)
    );

// If both A and B are 1, COUT_N must be 0 regardless of CI.
    check_coutn_low_when_ab_11: assert property (
        @(posedge clk) (A & B) |-> (COUT_N == 1'b0)
    );

// If both A and B are 0, COUT_N must be 1 regardless of CI.
    check_coutn_high_when_ab_00: assert property (
        @(posedge clk) (~A & ~B) |-> (COUT_N == 1'b1)
    );

// For input vector 000, SUM=0 and COUT_N=1.
    check_vector_000: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && CI == 1'b0) |-> (SUM == 1'b0 && COUT_N == 1'b1)
    );

// For input vector 111, SUM=1 and COUT_N=0.
    check_vector_111: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && CI == 1'b1) |-> (SUM == 1'b1 && COUT_N == 1'b0)
    );

// Y equals logical NOR of A and B.
    check_y_equals_nor: assert property (
        @(posedge clk) Y == (~(A | B))
    );

// If A is 1, Y must be 0.
    check_y_zero_when_a_one: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// If B is 1, Y must be 0.
    check_y_zero_when_b_one: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b0)
    );

// If both A and B are 0, Y must be 1.
    check_y_one_when_both_zero: assert property (
        @(posedge clk) (!A && !B) |-> (Y == 1'b1)
    );

// Y high implies both inputs are 0.
    check_y_high_implies_inputs_zero: assert property (
        @(posedge clk) (Y == 1'b1) |-> (!A && !B)
    );

// Y can only rise when both inputs are 0.
    check_y_rise_requires_both_zero: assert property (
        @(posedge clk) $rose(Y) |-> (!A && !B)
    );

// Y can only fall when at least one input is 1.
    check_y_fall_requires_any_one: assert property (
        @(posedge clk) $fell(Y) |-> (A || B)
    );

// A rising to 1 forces Y low in the same cycle.
    check_a_rise_forces_y_low: assert property (
        @(posedge clk) $rose(A) |-> (Y == 1'b0)
    );

// B rising to 1 forces Y low in the same cycle.
    check_b_rise_forces_y_low: assert property (
        @(posedge clk) $rose(B) |-> (Y == 1'b0)
    );

// Run is tied HIGH.
    check_run_const: assert property (
        @(posedge CLK) Run === 1'b1
    );

// R1in reflects T[0].
    check_r1in_map: assert property (
        @(posedge CLK) R1in === T[0]
    );

// R1out reflects T[2].
    check_r1out_map: assert property (
        @(posedge CLK) R1out === T[2]
    );

// R2in is LSB of T[4]+T[1] (equivalently XOR).
    check_r2in_sum_lsb: assert property (
        @(posedge CLK) R2in === (T[4] ^ T[1])
    );

// R2out reflects T[3].
    check_r2out_map: assert property (
        @(posedge CLK) R2out === T[3]
    );

// Add equals T[3] & Ins[0].
    check_add_map: assert property (
        @(posedge CLK) Add === (T[3] & Ins[0])
    );

// Sub equals T[3] & Ins[1].
    check_sub_map: assert property (
        @(posedge CLK) Sub === (T[3] & Ins[1])
    );

// Mul equals T[3] & Ins[2].
    check_mul_map: assert property (
        @(posedge CLK) Mul === (T[3] & Ins[2])
    );

// Div equals T[3] & Ins[3].
    check_div_map: assert property (
        @(posedge CLK) Div === (T[3] & Ins[3])
    );

// SelectY reflects T[3].
    check_selecty_map: assert property (
        @(posedge CLK) SelectY === T[3]
    );

// Zin reflects T[3].
    check_zin_map: assert property (
        @(posedge CLK) Zin === T[3]
    );

// Zout reflects T[4].
    check_zout_map: assert property (
        @(posedge CLK) Zout === T[4]
    );

// Yin reflects T[2].
    check_yin_map: assert property (
        @(posedge CLK) Yin === T[2]
    );

// End reflects T[5].
    check_end_map: assert property (
        @(posedge CLK) End === T[5]
    );

///// Operation selection checks /////
    // When op==00, c must equal a+b (signed 32-bit).
    check_add_mapping: assert property (
        @(posedge clk) (op == 2'b00) |-> (c == (a + b))
    );

// When op==01, c must equal a-b (signed 32-bit).
    check_sub_mapping: assert property (
        @(posedge clk) (op == 2'b01) |-> (c == (a - b))
    );

///// Basic arithmetic identities (guarded) /////
    // Adding zero leaves a unchanged.
    check_zero_add_rhs: assert property (
        @(posedge clk) ((op == 2'b00) && (b == 32'sd0)) |-> (c == a)
    );

// Subtracting zero leaves a unchanged.
    check_zero_sub_rhs: assert property (
        @(posedge clk) ((op == 2'b01) && (b == 32'sd0)) |-> (c == a)
    );

// Analysis: no clock/reset in DUT; pure combinational 3-input OR with inverted C_N (X = A | B | ~C_N).

    // X must implement X = A | B | ~C_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A || B || !C_N)
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> (X == 1'b1)
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> (X == 1'b1)
    );

// C_N low (active-low input) forces X high.
    check_cn_low_forces_x_high: assert property (
        @(posedge clk) (!C_N) |-> (X == 1'b1)
    );

// All inputs deasserted (A=0,B=0,C_N=1) force X low.
    check_blocking_inputs_force_x_low: assert property (
        @(posedge clk) (!A && !B && C_N) |-> (X == 1'b0)
    );

// X low implies A=0, B=0, and C_N=1.
    check_x_low_implies_inputs_blocking: assert property (
        @(posedge clk) (X == 1'b0) |-> (!A && !B && C_N)
    );

// X high implies A=1 or B=1 or C_N=0.
    check_x_high_implies_some_input_asserted: assert property (
        @(posedge clk) (X == 1'b1) |-> (A || B || !C_N)
    );

// Rising A drives X high immediately.
    check_a_rise_drives_x_high: assert property (
        @(posedge clk) $rose(A) |-> (X == 1'b1)
    );

// Rising B drives X high immediately.
    check_b_rise_drives_x_high: assert property (
        @(posedge clk) $rose(B) |-> (X == 1'b1)
    );

// Falling C_N (i.e., C_N=1->0) drives X high immediately.
    check_cn_fall_drives_x_high: assert property (
        @(posedge clk) $fell(C_N) |-> (X == 1'b1)
    );

// Falling A with B=0 and C_N=1 drives X low.
    check_a_fall_with_others_low_drives_x_low: assert property (
        @(posedge clk) $fell(A) && (B == 1'b0) && (C_N == 1'b1) |-> (X == 1'b0)
    );

// Falling B with A=0 and C_N=1 drives X low.
    check_b_fall_with_others_low_drives_x_low: assert property (
        @(posedge clk) $fell(B) && (A == 1'b0) && (C_N == 1'b1) |-> (X == 1'b0)
    );

// Rising C_N with A=0 and B=0 drives X low.
    check_cn_rise_with_others_low_drives_x_low: assert property (
        @(posedge clk) $rose(C_N) && (A == 1'b0) && (B == 1'b0) |-> (X == 1'b0)
    );

///// Reset behavior /////
    // During reset cycles, amp_out must be 0.
    amp_out_zero_during_reset: assert property (
        @(posedge clk) reset |-> (amp_out == 16'h0000)
    );

// On reset assertion edge, amp_out updates to 0 in the same cycle.
    amp_out_zero_on_reset_rise: assert property (
        @(posedge clk) $rose(reset) |-> (amp_out == 16'h0000)
    );

// No explicit clock or reset in RTL; pure combinational. Sample assertions on posedge of Ci.

    // Outputs form the 5-bit sum of inputs.
    check_fullsum_correct: assert property (
        @(posedge Ci) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// LSB sum bit is XOR of A[0], B[0], and Ci.
    check_s0_is_xor: assert property (
        @(posedge Ci) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Bit1 sum uses carry from bit0 ripple logic.
    check_s1_is_xor_with_carry0: assert property (
        @(posedge Ci)
            S[1] == (A[1] ^ B[1] ^ ( (A[0] & B[0]) | ((A[0] ^ B[0]) & Ci) ))
    );

// Bit2 sum uses carry from bit1 ripple logic.
    check_s2_is_xor_with_carry1: assert property (
        @(posedge Ci)
            S[2] == (A[2] ^ B[2] ^
                     ( (A[1] & B[1]) |
                       ((A[1] ^ B[1]) &
                         ( (A[0] & B[0]) | ((A[0] ^ B[0]) & Ci) ))))
    );

// Bit3 sum uses carry from bit2 ripple logic.
    check_s3_is_xor_with_carry2: assert property (
        @(posedge Ci)
            S[3] == (A[3] ^ B[3] ^
                     ( (A[2] & B[2]) |
                       ((A[2] ^ B[2]) &
                         ( (A[1] & B[1]) |
                           ((A[1] ^ B[1]) &
                             ( (A[0] & B[0]) | ((A[0] ^ B[0]) & Ci) ))))))
    );

// Adding zero (B=0, Ci=0) returns A with no carry.
    check_identity_when_B_zero_and_Ci_zero: assert property (
        @(posedge Ci) (B == 4'b0000 && Ci == 1'b0) |-> (S == A) && (Co == 1'b0)
    );

// Adding zero (A=0, Ci=0) returns B with no carry.
    check_identity_when_A_zero_and_Ci_zero: assert property (
        @(posedge Ci) (A == 4'b0000 && Ci == 1'b0) |-> (S == B) && (Co == 1'b0)
    );

// When A=0 and B=0, sum equals Ci in LSB and no carry.
    check_zero_zero_inputs_propagate_ci: assert property (
        @(posedge Ci) (A == 4'b0000 && B == 4'b0000) |-> (S == {3'b000, Ci}) && (Co == 1'b0)
    );

// Max operands with Ci=1 produce all ones with carry-out.
    check_max_sum_all_ones_with_carry: assert property (
        @(posedge Ci) (A == 4'hF && B == 4'hF && Ci == 1'b1) |-> ({Co, S} == 5'h1F)
    );

// out implements (~a | b).
    check_func_equiv: assert property (
        @(posedge clk) out == ((~a) | b)
    );

// If a is LOW, out must be HIGH.
    check_a0_implies_out1: assert property (
        @(posedge clk) (a == 1'b0) |-> (out == 1'b1)
    );

// If b is HIGH, out must be HIGH.
    check_b1_implies_out1: assert property (
        @(posedge clk) (b == 1'b1) |-> (out == 1'b1)
    );

// If a is HIGH and b is LOW, out must be LOW.
    check_a1b0_implies_out0: assert property (
        @(posedge clk) (a == 1'b1 && b == 1'b0) |-> (out == 1'b0)
    );

// If both a and b are HIGH, out must be HIGH.
    check_a1b1_implies_out1: assert property (
        @(posedge clk) (a == 1'b1 && b == 1'b1) |-> (out == 1'b1)
    );

// If both a and b are LOW, out must be HIGH.
    check_a0b0_implies_out1: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b0) |-> (out == 1'b1)
    );

// If a is LOW and b is HIGH, out must be HIGH.
    check_a0b1_implies_out1: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b1) |-> (out == 1'b1)
    );

// If out is LOW, then a must be HIGH and b must be LOW.
    check_out0_only_when_a1b0: assert property (
        @(posedge clk) (out == 1'b0) |-> (a == 1'b1 && b == 1'b0)
    );

// Y implements 2:1 mux function: Y = (~S & A) | (S & B).
    check_mux_function: assert property (
        @(posedge CLK) Y == ((~S & A) | (S & B))
    );

// When S=0, Y equals A.
    check_select_low: assert property (
        @(posedge CLK) (S == 1'b0) |-> (Y == A)
    );

// When S=1, Y equals B.
    check_select_high: assert property (
        @(posedge CLK) (S == 1'b1) |-> (Y == B)
    );

// If A and B are equal, Y equals that value.
    check_equal_inputs: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

// On S rising edge, Y equals B in the same cycle.
    check_on_S_rise: assert property (
        @(posedge CLK) $rose(S) |-> (Y == B)
    );

// On S falling edge, Y equals A in the same cycle.
    check_on_S_fall: assert property (
        @(posedge CLK) $fell(S) |-> (Y == A)
    );

// DUT is purely combinational with no reset; assertions sample on external clk.

    // Y equals bitwise AND of A and B.
    check_and_function: assert property (
        @(posedge clk) (Y === (A & B))
    );

// When both inputs are HIGH, Y is HIGH.
    check_both_high_implies_y_high: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (Y === 1'b1)
    );

// If any input is LOW, Y is LOW.
    check_any_low_implies_y_low: assert property (
        @(posedge clk) ((A === 1'b0) || (B === 1'b0)) |-> (Y === 1'b0)
    );

// Y can be HIGH only if both inputs are HIGH.
    check_y_high_requires_both_high: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A === 1'b1) && (B === 1'b1))
    );

// Y being LOW implies at least one input is LOW.
    check_y_low_requires_some_input_low: assert property (
        @(posedge clk) (Y === 1'b0) |-> ((A === 1'b0) || (B === 1'b0))
    );

// Y can only rise when both inputs are HIGH.
    check_y_rose_requires_inputs1: assert property (
        @(posedge clk) $rose(Y) |-> ((A === 1'b1) && (B === 1'b1))
    );

// A reset high sets count to 0 on the next clock.
    check_reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// After 16 cycles without reset, count returns to its value from 16 cycles ago.
    check_return_to_prior_after_16_no_reset: assert property (
        @(posedge clk) disable iff (reset) (!reset[*16]) |=> (count == $past(count, 16))
    );

// If reset is held high across cycles, count stays 0.
    check_hold_zero_while_reset_held: assert property (
        @(posedge clk) ($past(1'b1) && reset && $past(reset)) |-> (count == 4'd0)
    );

// Result never encodes 2'b11.
    check_result_no_11: assert property (
        @(posedge clk) (result != 2'b11)
    );

// If A > B then result is 2'b10.
    map_AgtB_to_10: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b10)
    );

// If result is 2'b10 then A > B.
    map_10_to_AgtB: assert property (
        @(posedge clk) (result == 2'b10) |-> (A > B)
    );

// If B > A then result is 2'b01.
    map_BgtA_to_01: assert property (
        @(posedge clk) (B > A) |-> (result == 2'b01)
    );

// If result is 2'b01 then B > A.
    map_01_to_BgtA: assert property (
        @(posedge clk) (result == 2'b01) |-> (B > A)
    );

// If A == B then result is 2'b00.
    map_AeqB_to_00: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

// If result is 2'b00 then A == B.
    map_00_to_AeqB: assert property (
        @(posedge clk) (result == 2'b00) |-> (A == B)
    );

// With no shift and mask 1111, pass-through of iDATA.
    check_fullmask_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 && iMASK == 4'hf) |-> (oDATA == iDATA)
    );

// With no shift and mask 0001, top byte equals iDATA[31:24], lower 24 bits zero.
    check_mask_0001_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 && iMASK == 4'b0001) |-> (oDATA[31:24] == iDATA[31:24] && oDATA[23:0] == 24'h0)
    );

// With no shift and mask 0010, top byte equals iDATA[23:16], lower 24 bits zero.
    check_mask_0010_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 && iMASK == 4'b0010) |-> (oDATA[31:24] == iDATA[23:16] && oDATA[23:0] == 24'h0)
    );

// With no shift and mask 0100, top byte equals iDATA[15:8], lower 24 bits zero.
    check_mask_0100_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 && iMASK == 4'b0100) |-> (oDATA[31:24] == iDATA[15:8] && oDATA[23:0] == 24'h0)
    );

// With no shift and mask 1000, top byte equals iDATA[7:0], lower 24 bits zero.
    check_mask_1000_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 && iMASK == 4'b1000) |-> (oDATA[31:24] == iDATA[7:0] && oDATA[23:0] == 24'h0)
    );

// With no shift and mask 0011, top halfword equals iDATA[31:16], lower 16 bits zero.
    check_mask_0011_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 && iMASK == 4'b0011) |-> (oDATA[31:16] == iDATA[31:16] && oDATA[15:0] == 16'h0)
    );

// With no shift and any other mask, top 24 bits equal iDATA[31:8], low byte zero.
    check_default_mask_noshift: assert property (
        @(posedge CLK) disable iff (1'b0)
        (iSHIFT == 2'b00 &&
         !((iMASK == 4'hf) || (iMASK == 4'b0001) || (iMASK == 4'b0010) ||
           (iMASK == 4'b0100) || (iMASK == 4'b1000) || (iMASK == 4'b0011)))
         |-> (oDATA[31:8] == iDATA[31:8] && oDATA[7:0] == 8'h0)
    );

// While reset is asserted (low), count is 0 at each clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'd0)
    );

// On reset assertion (1->0), count is 0 at that clock.
    check_zero_on_reset_assert: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'd0)
    );

// On reset deassertion (0->1), next count becomes 1 (after 0).
    check_one_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd1) && ($past(count) == 4'd0)
    );

// In run (rst=1), if count is 0 then previous must have been 15 (wrap).
    check_wrap_from_fifteen_only: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'd0) |-> ($past(count) == 4'd15)
    );

// In run (rst=1), for any count != 1, previous equals current-1 (mod 16).
    check_prev_matches_curr_minus_one: assert property (
        @(posedge clk) disable iff (!rst) (count != 4'd1) |-> ($past(count) == (count - 4'd1))
    );

// If count is non-zero at a clock, reset must be deasserted.
    check_nonzero_implies_not_in_reset: assert property (
        @(posedge clk) (count != 4'd0) |-> (rst == 1'b1)
    );

// For control 00, output equals input shifted left by 1.
    check_left_shift1_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b00) |-> (out == (in << 1))
    );

// For control 01, output equals input shifted left by 2.
    check_left_shift2_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b01) |-> (out == (in << 2))
    );

// For control 10, output equals input shifted right by 1.
    check_right_shift1_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b10) |-> (out == (in >> 1))
    );

// For control 11, output equals input shifted right by 2.
    check_right_shift2_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b11) |-> (out == (in >> 2))
    );

// For left shift by 1, LSB is zero.
    check_left1_lsb_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b00) |-> (out[0] == 1'b0)
    );

// For left shift by 2, two LSBs are zero.
    check_left2_lsbs_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b01) |-> (out[1:0] == 2'b00)
    );

// For right shift by 1, MSB is zero.
    check_right1_msb_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b10) |-> (out[3] == 1'b0)
    );

// For right shift by 2, two MSBs are zero.
    check_right2_msbs_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b11) |-> (out[3:2] == 2'b00)
    );

// For left shift by 1, upper bits map to input [2:0].
    check_left1_bit_mapping: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b00) |-> (out[3:1] == in[2:0])
    );

// For right shift by 1, lower bits map to input [3:1].
    check_right1_bit_mapping: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b10) |-> (out[2:0] == in[3:1])
    );

// On reset, outputs must be driven LOW.
    check_reset_outputs_low: assert property (
        @(posedge CLK) RST |-> (HI == 1'b0) && (LO == 1'b0)
    );

// HI and LO are never both HIGH.
    check_outputs_mutex: assert property (
        @(posedge CLK) disable iff (RST) !(HI && LO)
    );

// If HI is HIGH, LO must be LOW.
    check_hi_excludes_lo: assert property (
        @(posedge CLK) disable iff (RST) HI |-> !LO
    );

// If LO is HIGH, HI must be LOW.
    check_lo_excludes_hi: assert property (
        @(posedge CLK) disable iff (RST) LO |-> !HI
    );

// If previously not in reset and VPB == VNB, outputs must be HI=0, LO=0.
    map_prev_eq_to_zero: assert property (
        @(posedge CLK) disable iff (RST) ($past(!RST) && $past(VPB == VNB)) |-> (!HI && !LO)
    );

// HI=1,LO=0 implies previously VPB > VNB.
    hi_implies_prev_gt: assert property (
        @(posedge CLK) disable iff (RST) (HI && !LO) |-> $past(VPB > VNB)
    );

// LO=1,HI=0 implies previously VNB > VPB.
    lo_implies_prev_lt: assert property (
        @(posedge CLK) disable iff (RST) (LO && !HI) |-> $past(VNB > VPB)
    );

// If A and B are both 1, Y must be 0.
    check_y_low_if_ab_both_one: assert property (
        @(posedge CLK) (A && B) |-> (Y == 1'b0)
    );

// If neither pair (A,B) nor (C,D) are both 1, Y must be 1.
    check_y_high_when_no_pair_is_11: assert property (
        @(posedge CLK) (!(A && B) && !(C && D)) |-> (Y == 1'b1)
    );

// If C is 0, Y equals ~(A & B).
    check_y_equals_nand_ab_if_c_zero: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == ~(A & B))
    );

// If D is 0, Y equals ~(A & B).
    check_y_equals_nand_ab_if_d_zero: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == ~(A & B))
    );

// out must equal bitwise AND of inputs.
    check_out_is_and: assert property (
        @(posedge clk) out == (in1 & in2)
    );

// fets[3:0] must equal {4{clk500kHz}} & state
    check_fets_lo_assign: assert property (
        @(posedge clk500kHz) fets[3:0] == ({4{clk500kHz}} & state)
    );

// fets[7:4] must equal (~fets[3:0]) & state
    check_fets_hi_assign: assert property (
        @(posedge clk500kHz) fets[7:4] == ((~fets[3:0]) & state)
    );

// When state[0]==0, fets[0]==0
    check_lo_zero_when_state0_b0: assert property (
        @(posedge clk500kHz) (state[0] == 1'b0) |-> (fets[0] == 1'b0)
    );

// When state[1]==0, fets[1]==0
    check_lo_zero_when_state0_b1: assert property (
        @(posedge clk500kHz) (state[1] == 1'b0) |-> (fets[1] == 1'b0)
    );

// When state[2]==0, fets[2]==0
    check_lo_zero_when_state0_b2: assert property (
        @(posedge clk500kHz) (state[2] == 1'b0) |-> (fets[2] == 1'b0)
    );

// When state[3]==0, fets[3]==0
    check_lo_zero_when_state0_b3: assert property (
        @(posedge clk500kHz) (state[3] == 1'b0) |-> (fets[3] == 1'b0)
    );

// When state[0]==0, fets[4]==0
    check_hi_zero_when_state0_b0: assert property (
        @(posedge clk500kHz) (state[0] == 1'b0) |-> (fets[4] == 1'b0)
    );

// When state[1]==0, fets[5]==0
    check_hi_zero_when_state0_b1: assert property (
        @(posedge clk500kHz) (state[1] == 1'b0) |-> (fets[5] == 1'b0)
    );

// When state[2]==0, fets[6]==0
    check_hi_zero_when_state0_b2: assert property (
        @(posedge clk500kHz) (state[2] == 1'b0) |-> (fets[6] == 1'b0)
    );

// When state[3]==0, fets[7]==0
    check_hi_zero_when_state0_b3: assert property (
        @(posedge clk500kHz) (state[3] == 1'b0) |-> (fets[7] == 1'b0)
    );

// Clock: clk (posedge). Reset: reset (active-high, synchronous). Logic: sequential 4-bit counter.

    // On a cycle with reset HIGH, next cycle count must be 0.
    check_reset_sets_zero_next: assert property (
        @(posedge clk) reset |-> ##1 (count == 4'd0)
    );

// If reset stays HIGH across cycles, count is 0 on the later cycle.
    check_reset_holds_zero: assert property (
        @(posedge clk) reset && $past(reset) |-> (count == 4'd0)
    );

// When reset and load are both HIGH, reset overrides and next cycle is 0.
    check_reset_overrides_load: assert property (
        @(posedge clk) (reset && load) |-> ##1 (count == 4'd0)
    );

// With load HIGH and not in reset, next cycle count equals current data_in.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset) load |-> ##1 (count == $past(data_in))
    );

// With load LOW and not in reset, next cycle count increments by 1 (mod 16).
    check_increment_when_idle: assert property (
        @(posedge clk) disable iff (reset) (!load) |-> ##1 (count == ($past(count) + 4'd1))
    );

// Data 0001 maps to led_display 1.
  check_map_0001_to_1: assert property (
    @(posedge data[0]) (data == 4'b0001) |-> (led_display == 4'd1)
  );

// Data 0010 maps to led_display 2.
  check_map_0010_to_2: assert property (
    @(posedge data[0]) (data == 4'b0010) |-> (led_display == 4'd2)
  );

// Data 0100 maps to led_display 3.
  check_map_0100_to_3: assert property (
    @(posedge data[0]) (data == 4'b0100) |-> (led_display == 4'd3)
  );

// Data 1000 maps to led_display 4.
  check_map_1000_to_4: assert property (
    @(posedge data[0]) (data == 4'b1000) |-> (led_display == 4'd4)
  );

// Any non-listed data value maps to 0.
  check_default_zero_for_others: assert property (
    @(posedge data[0]) (data != 4'b0001 && data != 4'b0010 && data != 4'b0100 && data != 4'b1000) |-> (led_display == 4'd0)
  );

// Output is always one of {0,1,2,3,4}.
  check_output_value_set: assert property (
    @(posedge data[0]) (led_display inside {4'd0,4'd1,4'd2,4'd3,4'd4})
  );

// led_display 1 occurs only when data is 0001.
  check_rev_1_implies_0001: assert property (
    @(posedge data[0]) (led_display == 4'd1) |-> (data == 4'b0001)
  );

// led_display 2 occurs only when data is 0010.
  check_rev_2_implies_0010: assert property (
    @(posedge data[0]) (led_display == 4'd2) |-> (data == 4'b0010)
  );

// led_display 3 occurs only when data is 0100.
  check_rev_3_implies_0100: assert property (
    @(posedge data[0]) (led_display == 4'd3) |-> (data == 4'b0100)
  );

// led_display 4 occurs only when data is 1000.
  check_rev_4_implies_1000: assert property (
    @(posedge data[0]) (led_display == 4'd4) |-> (data == 4'b1000)
  );

// Output contains no X/Z.
  check_output_never_unknown: assert property (
    @(posedge data[0]) !$isunknown(led_display)
  );

///// Reset behavior /////
  // While reset is asserted low, count is forced to A.
  reset_forces_A: assert property (
    @(posedge clk) (reset == 1'b0) |-> (count == A)
  );

// While reset is asserted low, MSB of count stays 0.
  msb_zero_in_reset: assert property (
    @(posedge clk) (reset == 1'b0) |-> (count[2] == 1'b0)
  );

///// Legal values and X-checks when active /////
  // When not in reset, count only takes A, B, or C.
  active_values_restricted: assert property (
    @(posedge clk) disable iff (!reset) (count inside {A, B, C})
  );

// When not in reset, count has no X/Z bits.
  no_x_on_count_active: assert property (
    @(posedge clk) disable iff (!reset) !$isunknown(count)
  );

// When not in reset, count[2] is always 0.
  msb_zero_active: assert property (
    @(posedge clk) disable iff (!reset) (count[2] == 1'b0)
  );

///// Step-by-step sequencing /////
  // From A, next value is B (when previous cycle also active).
  step_A_to_B: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(count) == A) |-> (count == B)
  );

// From B, next value is C (when previous cycle also active).
  step_B_to_C: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(count) == B) |-> (count == C)
  );

// From C, next value is A (when previous cycle also active).
  step_C_to_A: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(count) == C) |-> (count == A)
  );

// When continuously active, count changes every cycle (no self-loop).
  count_changes_each_active_cycle: assert property (
    @(posedge clk) disable iff (!reset) $past(reset) |-> (count != $past(count))
  );

///// Multi-cycle sequencing /////
  // Starting at A, the next two steps are B then C, then back to A.
  period_three_from_A: assert property (
    @(posedge clk) disable iff (!reset) (count == A) |-> ##1 (count == B) ##1 (count == C) ##1 (count == A)
  );

// When sel==00, q equals a.
    check_sel00_routes_a: assert property (
        @(posedge clk) disable iff (reset) (sel == 2'b00) |-> (q == a)
    );

// When sel!=00, q equals b.
    check_sel_not00_routes_b: assert property (
        @(posedge clk) disable iff (reset) (sel != 2'b00) |-> (q == b)
    );

// q is always either a or b.
    check_q_is_a_or_b_only: assert property (
        @(posedge clk) disable iff (reset) (q == a) || (q == b)
    );

// If inputs differ and q==a, selection must be 00.
    check_q_eq_a_implies_sel00_when_inputs_differ: assert property (
        @(posedge clk) disable iff (reset) ((a != b) && (q == a)) |-> (sel == 2'b00)
    );

// If inputs differ and q==b, selection must be not 00.
    check_q_eq_b_implies_sel_not00_when_inputs_differ: assert property (
        @(posedge clk) disable iff (reset) ((a != b) && (q == b)) |-> (sel != 2'b00)
    );

// If a==b, q equals that value regardless of sel.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) disable iff (reset) (a == b) |-> (q == a)
    );

///// Functional equivalence /////
    // Z must equal TE_B & A when sampled on A rising.
    check_func_equiv_on_A: assert property (
        @(posedge A) Z == (TE_B & A)
    );

// Z must equal TE_B & A when sampled on TE_B rising.
    check_func_equiv_on_TEB: assert property (
        @(posedge TE_B) Z == (TE_B & A)
    );

///// Enable low forces zero /////
    // If TE_B is LOW, Z must be 0 (sampled on A rising).
    check_zero_when_teb_low_on_A: assert property (
        @(posedge A) (TE_B == 1'b0) |-> (Z == 1'b0)
    );

///// Enable high passes A /////
    // If TE_B is HIGH, Z equals A (sampled on A rising).
    check_passthrough_when_teb_high_on_A: assert property (
        @(posedge A) (TE_B == 1'b1) |-> (Z == A)
    );

///// Output implications /////
    // If Z is HIGH, both TE_B and A must be HIGH (sampled on A rising).
    check_z_high_implies_inputs_high_on_A: assert property (
        @(posedge A) (Z == 1'b1) |-> (TE_B == 1'b1 && A == 1'b1)
    );

// Clock: clk (posedge). No reset in RTL. Mixed logic: comb AND into a DFF, out is reg'd AND (1-cycle delay).

    // Out equals AND of inputs delayed by 1 clock.
    check_out_is_delayed_and: assert property (
        @(posedge clk) 1'b1 |-> ##1 (out == $past(a & b))
    );

// If both inputs are 1 at a clock, out is 1 on the next clock.
    check_next_out_one_when_both_one: assert property (
        @(posedge clk) (a && b) |-> ##1 (out == 1'b1)
    );

// If either input is 0 at a clock, out is 0 on the next clock.
    check_next_out_zero_when_either_zero: assert property (
        @(posedge clk) (!(a && b)) |-> ##1 (out == 1'b0)
    );

// Reset drives counter to 0 when rst is HIGH at the clock edge.
    reset_clears_counter: assert property (
        @(posedge clk) rst |-> (counter_value == 7'h00)
    );

// When count=0 and ud=0, next cycle counter_value becomes 0.
    next_zero_when_count0_ud0: assert property (
        @(posedge clk) disable iff (rst) ({count,ud} == 2'b00) |=> (counter_value == 7'h00)
    );

// When count=0 and ud=1, next cycle holds previous counter_value.
    hold_when_count0_ud1: assert property (
        @(posedge clk) disable iff (rst) ({count,ud} == 2'b01) |=> (counter_value == $past(counter_value))
    );

// When count=1 and ud=0, next cycle decrements by 1 (mod 128).
    dec_when_count1_ud0: assert property (
        @(posedge clk) disable iff (rst) ({count,ud} == 2'b10) |=> (counter_value == ($past(counter_value) - 7'd1))
    );

// When count=1 and ud=1, next cycle increments by 1 (mod 128).
    inc_when_count1_ud1: assert property (
        @(posedge clk) disable iff (rst) ({count,ud} == 2'b11) |=> (counter_value == ($past(counter_value) + 7'd1))
    );

// Out equals the RTL's ternary mux function.
    check_mux_functional_equivalence: assert property (
        @(posedge clk) out == (selectinput[1] ? (selectinput[0] ? data3 : data2) : (selectinput[0] ? data1 : data0))
    );

// When select is 00, out == data0.
    check_select_00_map: assert property (
        @(posedge clk) (selectinput == 2'b00) |-> (out == data0)
    );

// When select is 01, out == data1.
    check_select_01_map: assert property (
        @(posedge clk) (selectinput == 2'b01) |-> (out == data1)
    );

// When select is 10, out == data2.
    check_select_10_map: assert property (
        @(posedge clk) (selectinput == 2'b10) |-> (out == data2)
    );

// When select is 11, out == data3.
    check_select_11_map: assert property (
        @(posedge clk) (selectinput == 2'b11) |-> (out == data3)
    );

// If MSB is 0, out selects between data0/data1 by LSB.
    check_msb0_submux: assert property (
        @(posedge clk) (!selectinput[1]) |-> (out == (selectinput[0] ? data1 : data0))
    );

// If MSB is 1, out selects between data2/data3 by LSB.
    check_msb1_submux: assert property (
        @(posedge clk) (selectinput[1]) |-> (out == (selectinput[0] ? data3 : data2))
    );

// If LSB is 0, out selects between data0/data2 by MSB.
    check_lsb0_submux: assert property (
        @(posedge clk) (!selectinput[0]) |-> (out == (selectinput[1] ? data2 : data0))
    );

// If LSB is 1, out selects between data1/data3 by MSB.
    check_lsb1_submux: assert property (
        @(posedge clk) (selectinput[0]) |-> (out == (selectinput[1] ? data3 : data1))
    );

// When ctrl is 0, S must equal D0.
    check_select_ctrl0: assert property (
        @(posedge CLK) (ctrl == 1'b0) |-> (S === D0)
    );

// When ctrl is 1, S must equal D1.
    check_select_ctrl1: assert property (
        @(posedge CLK) (ctrl == 1'b1) |-> (S === D1)
    );

// Functional equivalence to the RTL expression.
    check_functional_equation: assert property (
        @(posedge CLK) S === ((ctrl == 1'b0) ? D0 : D1)
    );

// If inputs are equal, S must equal that value regardless of ctrl, including X.
    check_equal_inputs_bypass_ctrl: assert property (
        @(posedge CLK) (D0 === D1) |-> (S === D0)
    );

// If ctrl is X/Z and inputs differ, S must be unknown (X/Z).
    check_unknown_ctrl_diff_inputs_yield_unknown_S: assert property (
        @(posedge CLK) ((ctrl !== 1'b0) && (ctrl !== 1'b1) && (D0 !== D1)) |-> $isunknown(S)
    );

// Mux function: out equals sel ? in1 : in0.
    check_mux_function: assert property (
        @(posedge clk) out === (sel ? in1 : in0)
    );

// When sel is 0, out equals in0.
    check_sel0_path: assert property (
        @(posedge clk) (!sel) |-> (out === in0)
    );

// When sel is 1, out equals in1.
    check_sel1_path: assert property (
        @(posedge clk) (sel) |-> (out === in1)
    );

// If sel stays 0 and in0 changes, out follows in0.
    check_out_follows_in0_when_sel0: assert property (
        @(posedge clk) (!sel && $stable(sel) && $changed(in0)) |-> (out === in0)
    );

// If sel stays 1 and in1 changes, out follows in1.
    check_out_follows_in1_when_sel1: assert property (
        @(posedge clk) (sel && $stable(sel) && $changed(in1)) |-> (out === in1)
    );

// If sel stays 0, changes on in1 do not affect out.
    check_unselected_in1_no_effect_when_sel0: assert property (
        @(posedge clk) (!sel && $stable(sel) && $changed(in1)) |-> (out === in0)
    );

// If sel stays 1, changes on in0 do not affect out.
    check_unselected_in0_no_effect_when_sel1: assert property (
        @(posedge clk) (sel && $stable(sel) && $changed(in0)) |-> (out === in1)
    );

// If in0 equals in1, out equals that common value regardless of sel.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (in0 === in1) |-> (out === in0)
    );

// When S==0, Y must equal A.
    check_select_0_routes_A: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b0) |-> (Y == A)
    );

// When S==1, Y must equal B.
    check_select_1_routes_B: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1) |-> (Y == B)
    );

// If A and B are equal, Y must equal them regardless of S.
    check_equal_inputs_forward: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Y == A)
    );

// If S==1 and Y equals A, then inputs must be equal.
    check_consistency_S1: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1 && Y == A) |-> (A == B)
    );

// If S==0 and Y equals B, then inputs must be equal.
    check_consistency_S0: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b0 && Y == B) |-> (A == B)
    );

// If A!=B and Y equals A, then S must be 0.
    check_inverse_on_A: assert property (
        @(posedge CLK) disable iff (1'b0) ((A != B) && (Y == A)) |-> (S == 1'b0)
    );

// If A!=B and Y equals B, then S must be 1.
    check_inverse_on_B: assert property (
        @(posedge CLK) disable iff (1'b0) ((A != B) && (Y == B)) |-> (S == 1'b1)
    );

///// Output relationships /////
    // Q_N is always the bitwise inverse of Q.
    check_qn_is_invert_of_q: assert property (
        @(posedge CLK) (Q_N === ~Q)
    );

///// Capture behavior /////
    // Q captures the selected input (SCE ? SCD : D) from the previous cycle.
    check_q_captures_mux_prev: assert property (
        @(posedge CLK) 1'b1 ##1 (Q == $past(SCE ? SCD : D))
    );

// Q_N captures the inverse of the selected input from the previous cycle.
    check_qn_captures_inverted_mux_prev: assert property (
        @(posedge CLK) 1'b1 ##1 (Q_N === ~$past(SCE ? SCD : D))
    );

///// Scan enable selection /////
    // When SCE=0, Q captures D on the next rising edge.
    check_q_from_d_when_sce0: assert property (
        @(posedge CLK) (SCE == 1'b0) |=> (Q == $past(D))
    );

// When SCE=1, Q captures SCD on the next rising edge.
    check_q_from_scd_when_sce1: assert property (
        @(posedge CLK) (SCE == 1'b1) |=> (Q == $past(SCD))
    );

// When SCE=0, Q_N captures ~D on the next rising edge.
    check_qn_from_d_when_sce0: assert property (
        @(posedge CLK) (SCE == 1'b0) |=> (Q_N === ~$past(D))
    );

// When SCE=1, Q_N captures ~SCD on the next rising edge.
    check_qn_from_scd_when_sce1: assert property (
        @(posedge CLK) (SCE == 1'b1) |=> (Q_N === ~$past(SCD))
    );

// Synchronous reset drives q to 0 on the next clock.
    reset_clears_q_next: assert property (
        @(posedge clk) reset |=> (q == 1'b0)
    );

// gray[0] equals binary[0].
    check_map_g0_from_b0: assert property (
        @(posedge clk) gray[0] == binary[0]
    );

// gray[1] equals binary[0] XOR binary[1].
    check_map_g1_from_b01: assert property (
        @(posedge clk) gray[1] == (binary[0] ^ binary[1])
    );

// gray[2] equals binary[1] XOR binary[2].
    check_map_g2_from_b12: assert property (
        @(posedge clk) gray[2] == (binary[1] ^ binary[2])
    );

// gray[3] equals binary[2] XOR binary[3].
    check_map_g3_from_b23: assert property (
        @(posedge clk) gray[3] == (binary[2] ^ binary[3])
    );

// gray vector matches bitwise mapping from binary.
    check_map_vector: assert property (
        @(posedge clk) gray == { (binary[2] ^ binary[3]), (binary[1] ^ binary[2]), (binary[0] ^ binary[1]), binary[0] }
    );

// ctrl==00 selects D0.
    check_ctrl_00_selects_D0: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (S == D0)
    );

// ctrl==01 selects D1.
    check_ctrl_01_selects_D1: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (S == D1)
    );

// ctrl==10 selects D2.
    check_ctrl_10_selects_D2: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (S == D2)
    );

// ctrl==11 drives zero (default case).
    check_ctrl_11_selects_zero: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (S == 8'b0)
    );

// Exact functional equivalence to the case statement.
    check_function_equivalence: assert property (
        @(posedge clk)
            S == ((ctrl == 2'b00) ? D0 :
                  (ctrl == 2'b01) ? D1 :
                  (ctrl == 2'b10) ? D2 : 8'b0)
    );

///// Reset behavior /////
    // While reset is asserted, counter_value must be 0.
    reset_value_during_rst: assert property (
        @(posedge clk) rst |-> (counter_value == 6'h00)
    );

// When sel==00, out equals in[0].
    check_sel00_routes_in0: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == in[0])
    );

// When sel==01, out equals in[1].
    check_sel01_routes_in1: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == in[1])
    );

// When sel==10, out equals in[2].
    check_sel10_routes_in2: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == in[2])
    );

// When sel==11, out equals in[3].
    check_sel11_routes_in3: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == in[3])
    );

// load==0: sign-extend data_in[7:0] into data_out[15:0]
    check_load0_signext8: assert property (
        @(posedge CLK) (load == 3'd0) |-> (data_out == {{8{data_in[7]}}, data_in[7:0]})
    );

// load==1: sign-extend data_in[3:0] into data_out[15:0]
    check_load1_signext4: assert property (
        @(posedge CLK) (load == 3'd1) |-> (data_out == {{12{data_in[3]}}, data_in[3:0]})
    );

// load==2: sign-extend data_in[10:0] into data_out[15:0]
    check_load2_signext11: assert property (
        @(posedge CLK) (load == 3'd2) |-> (data_out == {{5{data_in[10]}}, data_in[10:0]})
    );

// load==3: zero-extend data_in[3:0] into data_out[15:0]
    check_load3_zeroext4: assert property (
        @(posedge CLK) (load == 3'd3) |-> (data_out == {12'b0, data_in[3:0]})
    );

// load==4: zero-extend data_in[7:0] into data_out[15:0]
    check_load4_zeroext8: assert property (
        @(posedge CLK) (load == 3'd4) |-> (data_out == {8'b0, data_in[7:0]})
    );

// load==5: sign-extend data_in[4:0] into data_out[15:0]
    check_load5_signext5: assert property (
        @(posedge CLK) (load == 3'd5) |-> (data_out == {{11{data_in[4]}}, data_in[4:0]})
    );

// load==6/7: zero-extend data_in[4:2] into data_out[15:0]
    check_load67_zeroext3_from_4to2: assert property (
        @(posedge CLK) (load inside {3'd6, 3'd7}) |-> (data_out == {13'b0, data_in[4:2]})
    );

// FE_ID must be 0 while reset is asserted (active-low async reset).
    reset_fe_id_zero: assert property (
        @(posedge clk) !rst_n |-> (FE_ID == 4'h0)
    );

// FE_ID can only take values 0 through 8 when not in reset.
    id_value_range: assert property (
        @(posedge clk) disable iff (!rst_n) (FE_ID inside {4'h0,4'h1,4'h2,4'h3,4'h4,4'h5,4'h6,4'h7,4'h8})
    );

// Next-state function matches RTL: reset has priority, else CE updates sum, else hold.
    check_next_state_function: assert property (
        @(posedge C) 1'b1 |=> ( S == ( $past(R) ? 32'sd0 : ($past(CE) ? ($past(A) + $past(B)) : $past(S)) ) )
    );

// On any cycle with reset asserted, S becomes 0 on the next cycle.
    check_sync_reset_clears_S: assert property (
        @(posedge C) R |=> (S == 32'sd0)
    );

// With CE high and not in reset, S updates to A+B on the next cycle.
    check_update_when_CE_high: assert property (
        @(posedge C) disable iff (R) CE |=> (S == $past(A) + $past(B))
    );

// With CE low and not in reset, S holds its previous value on the next cycle.
    check_hold_when_CE_low: assert property (
        @(posedge C) disable iff (R) !CE |=> (S == $past(S))
    );

// Reset has priority over CE when both are asserted.
    check_reset_priority_over_CE: assert property (
        @(posedge C) (R && CE) |=> (S == 32'sd0)
    );

// If CE is high and A+B is zero (not in reset), next S is zero.
    check_sum_zero_case: assert property (
        @(posedge C) disable iff (R) (CE && ((A + B) == 32'sd0)) |=> (S == 32'sd0)
    );

// If CE is high and A+B equals current S (not in reset), S remains unchanged next cycle.
    check_idempotent_update_when_sum_equals_S: assert property (
        @(posedge C) disable iff (R) (CE && ((A + B) == S)) |=> (S == $past(S))
    );

// If CE stays low for two consecutive cycles (not in reset), S is unchanged across them.
    check_hold_two_cycles_when_CE_low: assert property (
        @(posedge C) disable iff (R) (!CE ##1 !CE) |-> (S == $past(S))
    );

// out equals (C ? B : A) XOR invert.
    check_mux_function: assert property (
        @(posedge clk) out == ((C ? B : A) ^ invert)
    );

// When C==0, out equals A XOR invert.
    check_C0_path: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == (A ^ invert))
    );

// When C==1, out equals B XOR invert.
    check_C1_path: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (B ^ invert))
    );

// When invert==0, out equals selected input.
    check_invert0_behavior: assert property (
        @(posedge clk) (invert == 1'b0) |-> (out == (C ? B : A))
    );

// When invert==1, out equals inverse of selected input.
    check_invert1_behavior: assert property (
        @(posedge clk) (invert == 1'b1) |-> (out == ~(C ? B : A))
    );

// When reset is HIGH at a clock edge, q is driven to 0.
    reset_forces_zero_at_clk: assert property (
        @(posedge clk) reset |-> (q == 4'h0)
    );

// While reset remains HIGH across clock edges, q stays 0.
    reset_hold_zero_stable: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'h0 && $past(q) == 4'h0)
    );

// With reset LOW, wrap from 0xF to 0x0 on the next cycle.
    count_wraps_f_to_0: assert property (
        @(posedge clk) disable iff (reset) ($past(!reset) && ($past(q) == 4'hF)) |-> (q == 4'h0)
    );

// With reset LOW, if q is 1 this cycle, previous q was 0 or previous cycle was in reset.
    one_implies_prev_zero_or_reset: assert property (
        @(posedge clk) disable iff (reset) (q == 4'h1) |-> ($past(q) == 4'h0 || $past(reset))
    );

// When EN is HIGH, Z must equal A.
    check_en_selects_a: assert property (
        @(posedge clk) EN |-> (Z == A)
    );

// When EN is LOW and B is HIGH, Z must be 1.
    check_b_forces_one_when_en0: assert property (
        @(posedge clk) (!EN && (B == 1'b1)) |-> (Z == 1'b1)
    );

// When EN is LOW and B is LOW, Z must equal C.
    check_c_selected_when_en0_b0: assert property (
        @(posedge clk) (!EN && (B == 1'b0)) |-> (Z == C)
    );

// X implements XOR of A and B.
    check_xor_function: assert property (
        @(posedge clk) X == (A ^ B)
    );

// When A is 0, X must equal B.
    check_A_zero_passthrough: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == B)
    );

// When B is 0, X must equal A.
    check_B_zero_passthrough: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == A)
    );

// When A is 1, X must equal bitwise NOT of B.
    check_A_one_invert: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == ~B)
    );

// When B is 1, X must equal bitwise NOT of A.
    check_B_one_invert: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == ~A)
    );

// When A and B are equal, X must be 0.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (A == B) |-> (X == 1'b0)
    );

///// Functional mapping /////
    // Output equals the data selected by sel (pure combinational mux behavior).
    check_mux_function: assert property (
        @(posedge CLK) o == (
            (sel == 3'd0) ? i0 :
            (sel == 3'd1) ? i1 :
            (sel == 3'd2) ? i2 :
            (sel == 3'd3) ? i3 :
            (sel == 3'd4) ? i4 :
            (sel == 3'd5) ? i5 :
            (sel == 3'd6) ? i6 : i7
        )
    );

///// Reset behavior /////
    // While Reset is LOW, Out must be 0.
    check_reset_out_zero: assert property (
        @(posedge Clock) (!Reset) |-> (Out == 1'b0)
    );

// On Reset rising edge, next LFSR becomes shifted RESET pattern (111...110).
    check_lfsr_on_reset_release: assert property (
        @(posedge Clock) $rose(Reset) |-> (LFSR == POST_RESET_VAL)
    );

// On Reset rising edge, Out remains 0.
    check_out_on_reset_release: assert property (
        @(posedge Clock) $rose(Reset) |-> (Out == 1'b0)
    );

///// Running behavior (Reset HIGH) /////
    // LFSR upper bits shift down by one when running.
    check_lfsr_upper_shift: assert property (
        @(posedge Clock) disable iff (!Reset) $past(Reset) |-> (LFSR[14:1] == $past(LFSR[13:0]))
    );

// LFSR[0] is feedback XOR of previous LFSR[13] and LFSR[14].
    check_lfsr_feedback_bit: assert property (
        @(posedge Clock) disable iff (!Reset) $past(Reset) |-> (LFSR[0] == ($past(LFSR[13]) ^ $past(LFSR[14])))
    );

// Out never falls while running (only reset can clear it).
    check_out_never_falls_running: assert property (
        @(posedge Clock) disable iff (!Reset) !$fell(Out)
    );

// Out can only rise when previous LFSR matched the compare value.
    check_out_rise_only_on_match: assert property (
        @(posedge Clock) disable iff (!Reset) $rose(Out) |-> ($past(LFSR) == MATCH_VAL)
    );

// If previous LFSR matched, Out must be 1 this cycle.
    check_match_implies_out1: assert property (
        @(posedge Clock) disable iff (!Reset) ($past(LFSR) == MATCH_VAL) |-> (Out == 1'b1)
    );

// If previous LFSR did not match, Out holds its value.
    check_out_holds_without_match: assert property (
        @(posedge Clock) disable iff (!Reset) ($past(LFSR) != MATCH_VAL) |-> (Out == $past(Out))
    );

// Mux functional equivalence: out equals en ? b : a.
    check_mux_func: assert property (
        @(posedge CLK) disable iff (!RESETn) out == (en ? b : a)
    );

// When en is 1, out mirrors b.
    check_en_selects_b: assert property (
        @(posedge CLK) disable iff (!RESETn) en |-> (out == b)
    );

// When en is 0, out mirrors a.
    check_en0_selects_a: assert property (
        @(posedge CLK) disable iff (!RESETn) !en |-> (out == a)
    );

// If a equals b, out equals that value regardless of en.
    check_same_inputs_pass_through: assert property (
        @(posedge CLK) disable iff (!RESETn) (a == b) |-> (out == a)
    );

// Y equals bitwise NOT of A every cycle.
    check_inversion_value: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y === ~A)
    );

// When control_in==00, data_out passes through data_in.
    check_passthrough_value: assert property (
        @(posedge clk) (control_in == 2'b00) |-> (data_out == data_in)
    );

// When control_in==01, data_out is bitwise NOT of data_in.
    check_invert_value: assert property (
        @(posedge clk) (control_in == 2'b01) |-> (data_out == ~data_in)
    );

// When control_in==01, XOR with input is all 1s.
    check_invert_xor_allones: assert property (
        @(posedge clk) (control_in == 2'b01) |-> ((data_out ^ data_in) == 8'hFF)
    );

// When control_in==10, LSB after left shift is 0.
    check_leftshift_lsb_zero: assert property (
        @(posedge clk) (control_in == 2'b10) |-> (data_out[0] == 1'b0)
    );

// When control_in==10, upper bits shift left by 1.
    check_leftshift_upper_bits: assert property (
        @(posedge clk) (control_in == 2'b10) |-> (data_out[7:1] == data_in[6:0])
    );

// When control_in==11, MSB after right shift is 0.
    check_rightshift_msb_zero: assert property (
        @(posedge clk) (control_in == 2'b11) |-> (data_out[7] == 1'b0)
    );

// When control_in==11, lower bits shift right by 1.
    check_rightshift_lower_bits: assert property (
        @(posedge clk) (control_in == 2'b11) |-> (data_out[6:0] == data_in[7:1])
    );

// When control_in==00, XOR with input is all 0s.
    check_passthrough_xor_allzeros: assert property (
        @(posedge clk) (control_in == 2'b00) |-> ((data_out ^ data_in) == 8'h00)
    );

// For any control, data_out matches the selected transform.
    check_function_selection: assert property (
        @(posedge clk)
            data_out == (control_in == 2'b00 ? data_in :
                         control_in == 2'b01 ? ~data_in :
                         control_in == 2'b10 ? {data_in[6:0], 1'b0} :
                                               {1'b0, data_in[7:1]})
    );

// Y implements a 4-input NAND of A,B,C,D.
    check_y_is_nand4: assert property (
        @(posedge CLK) Y == ~(A & B & C & D)
    );

// When all inputs are HIGH, Y must be LOW.
    check_all_high_implies_y0: assert property (
        @(posedge CLK) (A & B & C & D) |-> (Y == 1'b0)
    );

// When not all inputs are HIGH, Y must be HIGH.
    check_not_all_high_implies_y1: assert property (
        @(posedge CLK) !(A & B & C & D) |-> (Y == 1'b1)
    );

// If Y is LOW, then all inputs are HIGH.
    check_y0_implies_all_high: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A & B & C & D)
    );

// If Y is HIGH, then not all inputs are HIGH.
    check_y1_implies_not_all_high: assert property (
        @(posedge CLK) (Y == 1'b1) |-> !(A & B & C & D)
    );

// A falling Y implies inputs are all HIGH now.
    check_y_fall_means_all_high: assert property (
        @(posedge CLK) $fell(Y) |-> (A & B & C & D)
    );

// A rising Y implies not all inputs are HIGH now.
    check_y_rise_means_not_all_high: assert property (
        @(posedge CLK) $rose(Y) |-> !(A & B & C & D)
    );

// When inputs collectively rise to all HIGH, Y is LOW.
    check_all_high_rose_implies_y0: assert property (
        @(posedge CLK) $rose(A & B & C & D) |-> (Y == 1'b0)
    );

// When inputs collectively fall from all HIGH, Y is HIGH.
    check_all_high_fell_implies_y1: assert property (
        @(posedge CLK) $fell(A & B & C & D) |-> (Y == 1'b1)
    );

// Y equals A_N | B_N | ~C | ~D.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (A_N | B_N | (~C) | (~D))
    );

// Y is 0 only when A_N=0, B_N=0, C=1, and D=1.
    check_y_zero_only_in_one_case: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

// When C=1 and D=1, Y reduces to A_N | B_N.
    check_reduce_when_c_and_d_high: assert property (
        @(posedge clk) (C && D) |-> (Y == (A_N | B_N))
    );

// When A_N=0 and B_N=0, Y reduces to ~C | ~D.
    check_reduce_when_a_and_b_low: assert property (
        @(posedge clk) (!A_N && !B_N) |-> (Y == ((~C) | (~D)))
    );

// A_N=1 forces Y=1.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> (Y == 1'b1)
    );

// B_N=1 forces Y=1.
    check_b_n_high_forces_y_high: assert property (
        @(posedge clk) B_N |-> (Y == 1'b1)
    );

// C=0 forces Y=1.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) (!C) |-> (Y == 1'b1)
    );

// D=0 forces Y=1.
    check_d_low_forces_y_high: assert property (
        @(posedge clk) (!D) |-> (Y == 1'b1)
    );

// If Y=0 then A_N must be 0.
    check_y_zero_implies_a_n_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A_N == 1'b0)
    );

// If Y=0 then B_N must be 0.
    check_y_zero_implies_b_n_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (B_N == 1'b0)
    );

// If Y=0 then C must be 1.
    check_y_zero_implies_c_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (C == 1'b1)
    );

// If Y=0 then D must be 1.
    check_y_zero_implies_d_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (D == 1'b1)
    );

// sum equals a + b + cin
    check_sum_add_pos_cin: assert property (
        @(posedge cin) sum == (a + b + cin)
    );

// cout matches majority of a[3], b[3], cin
    check_cout_majority_pos_cin: assert property (
        @(posedge cin) cout == ((a[3] & b[3]) | (a[3] & cin) | (b[3] & cin))
    );

// sum[0] is XOR of a[0], b[0], cin
    check_sum0_xor_pos_cin: assert property (
        @(posedge cin) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// If both MSBs are 0 then cout is 0
    check_cout_zero_when_msb_zero: assert property (
        @(posedge cin) ((a[3] == 1'b0) && (b[3] == 1'b0)) |-> (cout == 1'b0)
    );

// If both MSBs are 1 then cout is 1
    check_cout_one_when_msb_one: assert property (
        @(posedge cin) ((a[3] == 1'b1) && (b[3] == 1'b1)) |-> (cout == 1'b1)
    );

// If MSBs differ, cout equals cin
    check_cout_tracks_cin_when_msb_mismatch: assert property (
        @(posedge cin) (a[3] ^ b[3]) |-> (cout == cin)
    );

// cout equals ab + (a^b)cin equivalent form
    check_cout_alt_form: assert property (
        @(posedge cin) cout == ((a[3] & b[3]) | ((a[3] ^ b[3]) & cin))
    );

// With a=0 and b=0, sum=cin and cout=0
    check_zero_inputs_behavior: assert property (
        @(posedge cin) ((a == 4'b0000) && (b == 4'b0000)) |-> ((sum == {3'b000, cin}) && (cout == 1'b0))
    );

// Exactly one of gt/eq/lt is HIGH.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({gt, eq, lt})
    );

// If a > b then gt=1, eq=0, lt=0.
    check_outputs_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (gt && !eq && !lt)
    );

// If a == b then eq=1, gt=0, lt=0.
    check_outputs_when_a_eq_b: assert property (
        @(posedge clk) (a == b) |-> (!gt && eq && !lt)
    );

// If a < b then lt=1, gt=0, eq=0.
    check_outputs_when_a_lt_b: assert property (
        @(posedge clk) (a < b) |-> (!gt && !eq && lt)
    );

// gt implies a > b.
    check_gt_implies_relation: assert property (
        @(posedge clk) gt |-> (a > b)
    );

// eq implies a == b.
    check_eq_implies_relation: assert property (
        @(posedge clk) eq |-> (a == b)
    );

// lt implies a < b.
    check_lt_implies_relation: assert property (
        @(posedge clk) lt |-> (a < b)
    );

///// Reset behavior /////
    // While reset is asserted, Q and lfsr must be zero.
    check_reset_drives_zero: assert property (
        @(posedge clk) (!rst_n) |-> (Q == 64'h0) && (lfsr == 64'h0)
    );

// While reset is asserted, Q and lfsr remain stable.
    check_reset_stability: assert property (
        @(posedge clk) (!rst_n) |-> $stable(Q) && $stable(lfsr)
    );

// If previous lfsr was zero out of reset, Q must be zero now.
    check_q_zero_when_prev_lfsr_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
            ($past(rst_n) && $past(lfsr == 64'h0)) |-> (Q == 64'h0)
    );

// For C==000, R equals 4-bit sum of A and B (wraps on overflow).
    check_addition_result: assert property (
        @(posedge clk) (C == 3'b000) |-> (R === (A + B))
    );

// For C==001, R equals 4-bit difference A - B (wraps on underflow).
    check_subtraction_result: assert property (
        @(posedge clk) (C == 3'b001) |-> (R === (A - B))
    );

// For all other C values, R is driven to zero.
    check_default_zero: assert property (
        @(posedge clk) ((C != 3'b000) && (C != 3'b001)) |-> (R === 4'b0000)
    );

// Addition identity: adding zero on B passes A through.
    check_add_zero_b: assert property (
        @(posedge clk) ((C == 3'b000) && (B == 4'b0000)) |-> (R === A)
    );

// Addition identity: adding zero on A passes B through.
    check_add_zero_a: assert property (
        @(posedge clk) ((C == 3'b000) && (A == 4'b0000)) |-> (R === B)
    );

// Subtraction identity: subtracting zero passes A through.
    check_sub_zero_b: assert property (
        @(posedge clk) ((C == 3'b001) && (B == 4'b0000)) |-> (R === A)
    );

// Subtraction of equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) ((C == 3'b001) && (A == B)) |-> (R === 4'b0000)
    );

// When adding equal operands, result equals A<<1 (4-bit wrap).
    check_add_double_when_equal: assert property (
        @(posedge clk) ((C == 3'b000) && (A == B)) |-> (R === (A << 1))
    );

// Example wrap on addition: 0xF + 1 => 0x0.
    check_add_wrap_example: assert property (
        @(posedge clk) ((C == 3'b000) && (A == 4'hF) && (B == 4'h1)) |-> (R === 4'h0)
    );

// Example borrow on subtraction: 0x0 - 1 => 0xF.
    check_sub_borrow_example: assert property (
        @(posedge clk) ((C == 3'b001) && (A == 4'h0) && (B == 4'h1)) |-> (R === 4'hF)
    );

// Synchronous reset drives out to zero on the same clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (out == 4'b0000)
    );

// While reset remains asserted across cycles, out stays at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) reset && $past(reset) |-> (out == 4'b0000)
    );

// X equals bitwise OR of inputs.
    check_x_equals_or: assert property (
        @(posedge CLK) X === (A | B | C | D)
    );

// All inputs LOW imply X is LOW.
    check_all_zero_implies_x_zero: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b0 && C==1'b0 && D==1'b0) |-> (X==1'b0)
    );

// A HIGH implies X HIGH.
    check_a_high_implies_x_high: assert property (
        @(posedge CLK) (A==1'b1) |-> (X==1'b1)
    );

// B HIGH implies X HIGH.
    check_b_high_implies_x_high: assert property (
        @(posedge CLK) (B==1'b1) |-> (X==1'b1)
    );

// C HIGH implies X HIGH.
    check_c_high_implies_x_high: assert property (
        @(posedge CLK) (C==1'b1) |-> (X==1'b1)
    );

// D HIGH implies X HIGH.
    check_d_high_implies_x_high: assert property (
        @(posedge CLK) (D==1'b1) |-> (X==1'b1)
    );

// X LOW implies all inputs LOW.
    check_x_zero_implies_all_zero: assert property (
        @(posedge CLK) (X==1'b0) |-> (A==1'b0 && B==1'b0 && C==1'b0 && D==1'b0)
    );

// X HIGH implies at least one input HIGH.
    check_x_one_implies_any_one: assert property (
        @(posedge CLK) (X==1'b1) |-> (A | B | C | D)
    );

// No explicit clock or reset; pure combinational; assertions sampled on input/power edges.

    // X equals A1 & A2 & B1 when sampled on A1's rising edge.
    check_x_eq_and_on_a1: assert property (
        @(posedge A1) X == (A1 & A2 & B1)
    );

// X equals A1 & A2 & B1 when sampled on A2's rising edge.
    check_x_eq_and_on_a2: assert property (
        @(posedge A2) X == (A1 & A2 & B1)
    );

// X equals A1 & A2 & B1 when sampled on B1's rising edge.
    check_x_eq_and_on_b1: assert property (
        @(posedge B1) X == (A1 & A2 & B1)
    );

// When A2 and B1 are HIGH, X follows A1.
    check_follow_a1_when_others_high: assert property (
        @(posedge A1) (A2 && B1) |-> (X == A1)
    );

// When A1 and B1 are HIGH, X follows A2.
    check_follow_a2_when_others_high: assert property (
        @(posedge A2) (A1 && B1) |-> (X == A2)
    );

// When A1 and A2 are HIGH, X follows B1.
    check_follow_b1_when_others_high: assert property (
        @(posedge B1) (A1 && A2) |-> (X == B1)
    );

// A rising X implies all inputs are HIGH (sampled on A1 edge).
    check_x_rise_requires_all_high: assert property (
        @(posedge A1) $rose(X) |-> (A1 && A2 && B1)
    );

// A falling X implies at least one input is LOW (sampled on A1 edge).
    check_x_fall_requires_some_low: assert property (
        @(posedge A1) $fell(X) |-> (!A1 || !A2 || !B1)
    );

// Output equals the mux expression.
    check_mux_equation: assert property (
        @(posedge clk) S == ((ctrl == 1'b0) ? D0 : D1)
    );

// When ctrl is 0, S must equal D0.
    check_ctrl_low_selects_D0: assert property (
        @(posedge clk) (ctrl == 1'b0) |-> (S == D0)
    );

// When ctrl is 1, S must equal D1.
    check_ctrl_high_selects_D1: assert property (
        @(posedge clk) (ctrl == 1'b1) |-> (S == D1)
    );

// On rising ctrl edge, S must reflect D1.
    check_output_updates_on_ctrl_rise: assert property (
        @(posedge clk) $rose(ctrl) |-> (S == D1)
    );

// On falling ctrl edge, S must reflect D0.
    check_output_updates_on_ctrl_fall: assert property (
        @(posedge clk) $fell(ctrl) |-> (S == D0)
    );

// Decoder outputs are a 1-hot decode of input_bits.
    decode_equation: assert property (
        @(posedge CLK) output_bits == (4'b0001 << input_bits)
    );

// Mapping: input 00 -> output 0001.
    map_in_00: assert property (
        @(posedge CLK) (input_bits == 2'b00) |-> (output_bits == 4'b0001)
    );

// Mapping: input 01 -> output 0010.
    map_in_01: assert property (
        @(posedge CLK) (input_bits == 2'b01) |-> (output_bits == 4'b0010)
    );

// Mapping: input 10 -> output 0100.
    map_in_10: assert property (
        @(posedge CLK) (input_bits == 2'b10) |-> (output_bits == 4'b0100)
    );

// Mapping: input 11 -> output 1000.
    map_in_11: assert property (
        @(posedge CLK) (input_bits == 2'b11) |-> (output_bits == 4'b1000)
    );

// Reverse mapping: output 0001 implies input 00.
    map_out_0001: assert property (
        @(posedge CLK) (output_bits == 4'b0001) |-> (input_bits == 2'b00)
    );

// Reverse mapping: output 0010 implies input 01.
    map_out_0010: assert property (
        @(posedge CLK) (output_bits == 4'b0010) |-> (input_bits == 2'b01)
    );

// Reverse mapping: output 0100 implies input 10.
    map_out_0100: assert property (
        @(posedge CLK) (output_bits == 4'b0100) |-> (input_bits == 2'b10)
    );

// Reverse mapping: output 1000 implies input 11.
    map_out_1000: assert property (
        @(posedge CLK) (output_bits == 4'b1000) |-> (input_bits == 2'b11)
    );

// Outputs are at most one-hot (allows all-zero).
    check_onehot0: assert property (
        @(posedge CLK) $onehot0(output_bits)
    );

// Output vector equals 5-bit addition of inputs.
    check_add_result_matches_addition: assert property (
        @(posedge CLK) {C_out, S} == ({1'b0, A} + {1'b0, B} + C_in)
    );

// LSB sum is XOR of A[0], B[0], and C_in.
    check_sum_bit0_xor: assert property (
        @(posedge CLK) S[0] == s0
    );

// Bit1 sum equals XOR of A[1], B[1], and carry0.
    check_sum_bit1_xor_with_carry0: assert property (
        @(posedge CLK) S[1] == s1
    );

// Bit2 sum equals XOR of A[2], B[2], and carry1.
    check_sum_bit2_xor_with_carry1: assert property (
        @(posedge CLK) S[2] == s2
    );

// Bit3 sum equals XOR of A[3], B[3], and carry2.
    check_sum_bit3_xor_with_carry2: assert property (
        @(posedge CLK) S[3] == s3
    );

// Final carry-out equals majority function of A[3], B[3], and carry2.
    check_carry_out_function: assert property (
        @(posedge CLK) C_out == c3
    );

// With A=B=0, S equals C_in on bit0 and carry-out is 0.
    check_zero_operands_behavior: assert property (
        @(posedge CLK) ((A == 4'd0) && (B == 4'd0)) |-> ((S == {3'b000, C_in}) && (C_out == 1'b0))
    );

// With A=B=15, result equals 30 + C_in.
    check_max_operands_behavior: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'hF)) |-> ({C_out, S} == (5'd30 + C_in))
    );

// On subtraction selection and B==0, Q must equal A.
    check_sub_identity_B_zero: assert property (
        @(posedge C) (B == 16'd0) |-> (Q == A)
    );

// On addition selection and B==0, Q must equal A.
    check_add_identity_B_zero: assert property (
        @(negedge C) (B == 16'd0) |-> (Q == A)
    );

// Clock: posedge clk. Reset: areset_n active-low, asynchronous.
    // Logic: sequential with async reset; load has priority over shift; else hold.

    ///// Reset behavior /////
    // When reset is asserted at the clock edge, q is zero.
    check_reset_clears_q: assert property (
        @(posedge clk) (!areset_n) |-> (q == 4'b0000)
    );

///// Load behavior /////
    // On load, q updates with data on the next cycle.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (!areset_n) load |=> (q == $past(data))
    );

// Load has priority over ena when both are asserted.
    check_priority_load_over_ena: assert property (
        @(posedge clk) disable iff (!areset_n) (load && ena) |=> (q == $past(data))
    );

///// Shift behavior /////
    // On ena without load, q shifts left by one with zero fill.
    check_shift_left_when_ena_only: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q == {$past(q[2:0]), 1'b0})
    );

// On shift, LSB becomes zero.
    check_shift_lsb_zero: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[0] == 1'b0)
    );

// On shift, MSB takes previous bit2.
    check_shift_msb_from_bit2: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[3] == $past(q[2]))
    );

// On shift, bit2 takes previous bit1.
    check_shift_bit2_from_bit1: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[2] == $past(q[1]))
    );

// On shift, bit1 takes previous bit0.
    check_shift_bit1_from_bit0: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[1] == $past(q[0]))
    );

///// Hold behavior /////
    // When neither load nor ena is asserted, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!areset_n) (!load && !ena) |=> (q == $past(q))
    );

///// Functional equivalence to RTL expression /////
    // Y matches the RTL Boolean expression at A1 rising edge.
    check_func_eq_on_A1_pos: assert property (
        @(posedge A1) Y == ((A1 & A2 & ~A3 & ~A4 & B1) | (A1 & A2 & ~A3 & ~A4 & ~B1))
    );

// Y matches the RTL Boolean expression at A2 rising edge.
    check_func_eq_on_A2_pos: assert property (
        @(posedge A2) Y == ((A1 & A2 & ~A3 & ~A4 & B1) | (A1 & A2 & ~A3 & ~A4 & ~B1))
    );

// Y matches the RTL Boolean expression at A3 rising edge.
    check_func_eq_on_A3_pos: assert property (
        @(posedge A3) Y == ((A1 & A2 & ~A3 & ~A4 & B1) | (A1 & A2 & ~A3 & ~A4 & ~B1))
    );

// Y matches the RTL Boolean expression at A4 rising edge.
    check_func_eq_on_A4_pos: assert property (
        @(posedge A4) Y == ((A1 & A2 & ~A3 & ~A4 & B1) | (A1 & A2 & ~A3 & ~A4 & ~B1))
    );

// Y matches the RTL Boolean expression at B1 rising edge.
    check_func_eq_on_B1_pos: assert property (
        @(posedge B1) Y == ((A1 & A2 & ~A3 & ~A4 & B1) | (A1 & A2 & ~A3 & ~A4 & ~B1))
    );

///// Functional definitions /////
    // din_15_0_eq_0 equals din_15_8_eq_0 AND din_7_0_eq_0.
    check_def_din_15_0_eq_0: assert property (
        @(posedge CLK) disable iff (!RESETn) din_15_0_eq_0 == (din_15_8_eq_0 && din_7_0_eq_0)
    );

// lead0_16b_2 equals ((!din_15_8_eq_0)&&din_15_12_eq_0) || (din_15_8_eq_0&&din_7_4_eq_0).
    check_def_lead0_16b_2: assert property (
        @(posedge CLK) disable iff (!RESETn) lead0_16b_2 == (((!din_15_8_eq_0) && din_15_12_eq_0) || (din_15_8_eq_0 && din_7_4_eq_0))
    );

// lead0_16b_1 equals ((!din_15_8_eq_0)&&lead0_8b_1_hi) || (din_15_8_eq_0&&lead0_8b_1_lo).
    check_def_lead0_16b_1: assert property (
        @(posedge CLK) disable iff (!RESETn) lead0_16b_1 == (((!din_15_8_eq_0) && lead0_8b_1_hi) || (din_15_8_eq_0 && lead0_8b_1_lo))
    );

// lead0_16b_0 equals ((!din_15_8_eq_0)&&lead0_8b_0_hi) || (din_15_8_eq_0&&lead0_8b_0_lo).
    check_def_lead0_16b_0: assert property (
        @(posedge CLK) disable iff (!RESETn) lead0_16b_0 == (((!din_15_8_eq_0) && lead0_8b_0_hi) || (din_15_8_eq_0 && lead0_8b_0_lo))
    );

///// MUX select behavior /////
    // When din_15_8_eq_0==0, lead0_16b_2 follows din_15_12_eq_0.
    check_mux_lead0_16b_2_sel0: assert property (
        @(posedge CLK) disable iff (!RESETn) (!din_15_8_eq_0) |-> (lead0_16b_2 == din_15_12_eq_0)
    );

// When din_15_8_eq_0==1, lead0_16b_2 follows din_7_4_eq_0.
    check_mux_lead0_16b_2_sel1: assert property (
        @(posedge CLK) disable iff (!RESETn) (din_15_8_eq_0) |-> (lead0_16b_2 == din_7_4_eq_0)
    );

// When din_15_8_eq_0==0, lead0_16b_1 follows lead0_8b_1_hi.
    check_mux_lead0_16b_1_sel0: assert property (
        @(posedge CLK) disable iff (!RESETn) (!din_15_8_eq_0) |-> (lead0_16b_1 == lead0_8b_1_hi)
    );

// When din_15_8_eq_0==1, lead0_16b_1 follows lead0_8b_1_lo.
    check_mux_lead0_16b_1_sel1: assert property (
        @(posedge CLK) disable iff (!RESETn) (din_15_8_eq_0) |-> (lead0_16b_1 == lead0_8b_1_lo)
    );

// When din_15_8_eq_0==0, lead0_16b_0 follows lead0_8b_0_hi.
    check_mux_lead0_16b_0_sel0: assert property (
        @(posedge CLK) disable iff (!RESETn) (!din_15_8_eq_0) |-> (lead0_16b_0 == lead0_8b_0_hi)
    );

// When din_15_8_eq_0==1, lead0_16b_0 follows lead0_8b_0_lo.
    check_mux_lead0_16b_0_sel1: assert property (
        @(posedge CLK) disable iff (!RESETn) (din_15_8_eq_0) |-> (lead0_16b_0 == lead0_8b_0_lo)
    );

// Pure combinational DUT: Y = ~(~B1_N | (A1 & A2)); no resets present.

    // Y implements the Boolean function from inputs.
    check_output_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y === ~( (~B1_N) | (A1 & A2) )
    );

// not gate: b = ~B1_N.
    check_not_gate: assert property (
        @(posedge CLK) disable iff (1'b0) b === ~B1_N
    );

// and gate: and0_out = A1 & A2.
    check_and_gate: assert property (
        @(posedge CLK) disable iff (1'b0) and0_out === (A1 & A2)
    );

// nor gate: nor0_out_Y = ~(b | and0_out).
    check_nor_gate: assert property (
        @(posedge CLK) disable iff (1'b0) nor0_out_Y === ~(b | and0_out)
    );

// buffer: Y = nor0_out_Y.
    check_buffer: assert property (
        @(posedge CLK) disable iff (1'b0) Y === nor0_out_Y
    );

// If B1_N is 0, Y must be 0.
    check_b1n_low_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) (B1_N === 1'b0) |-> (Y === 1'b0)
    );

// If both A1 and A2 are 1, Y must be 0.
    check_both_a_high_forces_y_low: assert property (
        @(posedge CLK) disable iff (1'b0) ((A1 === 1'b1) && (A2 === 1'b1)) |-> (Y === 1'b0)
    );

// If B1_N is 1 and A1 is 0, Y must be 1.
    check_b1n_high_a1_low_sets_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N === 1'b1) && (A1 === 1'b0)) |-> (Y === 1'b1)
    );

// If B1_N is 1 and A2 is 0, Y must be 1.
    check_b1n_high_a2_low_sets_y_high: assert property (
        @(posedge CLK) disable iff (1'b0) ((B1_N === 1'b1) && (A2 === 1'b0)) |-> (Y === 1'b1)
    );

// If Y is 1, then B1_N is 1 and not (A1 & A2).
    check_y_high_implies_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (Y === 1'b1) |-> ((B1_N === 1'b1) && !((A1 === 1'b1) && (A2 === 1'b1)))
    );

// Sum equals three-input XOR of A, B, and C_in.
    check_sum_is_parity: assert property (
        @(posedge CLK) Sum == (A ^ B ^ C_in)
    );

// C_out equals (A & B) | ((A ^ B) & C_in) per RTL.
    check_cout_function: assert property (
        @(posedge CLK) C_out == ((A & B) | ((A ^ B) & C_in))
    );

// C_out equals majority(A,B,C_in).
    check_cout_is_majority: assert property (
        @(posedge CLK) C_out == ((A & B) | (A & C_in) | (B & C_in))
    );

// When C_in is 0, Sum reduces to A ^ B.
    check_cin0_sum: assert property (
        @(posedge CLK) (C_in == 1'b0) |-> (Sum == (A ^ B))
    );

// When C_in is 0, C_out reduces to A & B.
    check_cin0_cout: assert property (
        @(posedge CLK) (C_in == 1'b0) |-> (C_out == (A & B))
    );

// When C_in is 1, Sum is the inversion of A ^ B.
    check_cin1_sum: assert property (
        @(posedge CLK) (C_in == 1'b1) |-> (Sum == ~(A ^ B))
    );

// When C_in is 1, C_out reduces to A | B.
    check_cin1_cout: assert property (
        @(posedge CLK) (C_in == 1'b1) |-> (C_out == (A | B))
    );

// When A equals B, Sum equals C_in.
    check_equal_inputs_sum: assert property (
        @(posedge CLK) (A == B) |-> (Sum == C_in)
    );

// When A equals B, C_out equals A (same as B).
    check_equal_inputs_cout: assert property (
        @(posedge CLK) (A == B) |-> (C_out == A)
    );

// When A != B, Sum equals ~C_in and C_out equals C_in.
    check_xor_inputs_behavior: assert property (
        @(posedge CLK) (A ^ B) |-> ( (Sum == ~C_in) && (C_out == C_in) )
    );

///// Reset behavior /////
    // During reset, the internal register is cleared to 0.
    reset_clears_reg: assert property (
        @(posedge clk) reset |-> (reg_data == 1'b0)
    );

// During reset, Bus_out is forced low.
    reset_forces_busout_low: assert property (
        @(posedge clk) reset |-> (Bus_out == 1'b0)
    );

// If Bus_out is HIGH, r_out must be HIGH.
    check_busout_high_requires_enable: assert property (
        @(posedge clk) (Bus_out == 1'b1) |-> (r_out == 1'b1)
    );

// Adder outputs equal A + B + Cin (sum and carry)
    check_adder_sum_and_carry: assert property (
        @(posedge clk) {Cout, Sum} == (A + B + Cin)
    );

// LSB sum bit is XOR of A[0], B[0], and Cin
    check_sum0_xor: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Carry-out equals overflow of 4-bit addition
    check_cout_overflow: assert property (
        @(posedge clk) Cout == ((A + B + Cin) > 5'd15)
    );

// Upper decoder bits are zero
    check_decoder_upper_zero: assert property (
        @(posedge clk) O[15:4] == 12'h000
    );

// Y equals A | ~B when all are known.
    check_functional_equivalence_known: assert property (
        @(posedge CLK) disable iff (!RESETn) !$isunknown({A,B,Y}) |-> (Y == (A | ~B))
    );

// If B is 0, Y must be 1.
    check_B_low_forces_Y_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 1'b0) |-> (Y == 1'b1)
    );

// If B is 1, Y equals A.
    check_B_high_equals_A: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 1'b1) |-> (Y == A)
    );

// If A is 0, Y equals ~B.
    check_A_low_equals_notB: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == 1'b0) |-> (Y == ~B)
    );

// Y can be 0 only when A==0 and B==1.
    check_only_case_Y_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> ((A == 1'b0) && (B == 1'b1))
    );

// If Y is 1, then A==1 or B==0.
    check_Y_high_implies_A_or_notB: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b1) |-> ((A == 1'b1) || (B == 1'b0))
    );

// If A and B are known, Y is known.
    check_knownness_when_inputs_known: assert property (
        @(posedge CLK) disable iff (!RESETn) !$isunknown({A,B}) |-> !$isunknown(Y)
    );

// q[1] becomes previous q[0].
    check_middle_shifts_from_lsb: assert property (
        @(posedge clk) 1'b1 |=> (q[1] == $past(q[0]))
    );

// q[2] becomes previous q[1].
    check_msb_shifts_from_mid: assert property (
        @(posedge clk) 1'b1 |=> (q[2] == $past(q[1]))
    );

// Upper pair shifts from lower pair.
    check_upper_pair_shift: assert property (
        @(posedge clk) 1'b1 |=> (q[2:1] == $past(q[1:0]))
    );

// When select=00, output is all zeros.
    check_sel00_zero: assert property (
        @(posedge clk) disable iff (1'b0) (select == 2'b00) |-> (data_out == {W{1'b0}})
    );

// When select=10, output equals ch_1.
    check_sel10_pass_ch1: assert property (
        @(posedge clk) disable iff (1'b0) (select == 2'b10) |-> (data_out == ch_1)
    );

// When select=11, output equals ch_2.
    check_sel11_pass_ch2: assert property (
        @(posedge clk) disable iff (1'b0) (select == 2'b11) |-> (data_out == ch_2)
    );

// When sel == 2'b00, out equals in0.
    check_mux_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// When sel == 2'b01, out equals in1.
    check_mux_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// When sel == 2'b10, out equals in2.
    check_mux_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// When sel == 2'b11, out equals in3.
    check_mux_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// Out equals the 4:1 mux function of sel and inputs.
    check_mux_function: assert property (
        @(posedge clk) out == ((sel == 2'b00) ? in0 :
                               (sel == 2'b01) ? in1 :
                               (sel == 2'b10) ? in2 : in3)
    );

// If only sel changes (inputs stable), out updates to the newly selected input.
    check_out_updates_on_sel_change: assert property (
        @(posedge clk) (!$stable(sel) && $stable({in0, in1, in2, in3})) |->
                       (out == ((sel == 2'b00) ? in0 :
                                (sel == 2'b01) ? in1 :
                                (sel == 2'b10) ? in2 : in3))
    );

// Combinational DUT with no reset; use posedge of c as the sampling clock.

    // y equals a & b for all input combinations.
    check_y_eq_and: assert property (
        @(posedge c) (y == (a & b))
    );

// y high only when both a and b are high.
    check_y_high_implies_inputs_high: assert property (
        @(posedge c) y |-> (a && b)
    );

// a low forces y low.
    check_a_low_forces_y_low: assert property (
        @(posedge c) (!a) |-> (y == 1'b0)
    );

// b low forces y low.
    check_b_low_forces_y_low: assert property (
        @(posedge c) (!b) |-> (y == 1'b0)
    );

// Both inputs high force y high.
    check_both_high_forces_y_high: assert property (
        @(posedge c) (a && b) |-> (y == 1'b1)
    );

// When b is 1, y equals a.
    check_b_one_implies_y_eq_a: assert property (
        @(posedge c) (b == 1'b1) |-> (y == a)
    );

// When a is 1, y equals b.
    check_a_one_implies_y_eq_b: assert property (
        @(posedge c) (a == 1'b1) |-> (y == b)
    );

// y rising requires both inputs high.
    check_y_rise_requires_inputs_high: assert property (
        @(posedge c) $rose(y) |-> (a && b)
    );

// y falling requires at least one input low.
    check_y_fall_requires_input_low: assert property (
        @(posedge c) $fell(y) |-> (!a || !b)
    );

// If D is 1 on this edge, Q will be 1 on the next edge.
    check_next_q_high_when_d_high: assert property (
        @(posedge CLK) (D == 1'b1) |-> ##1 (Q == 1'b1)
    );

// If D is 0 on this edge, Q will be 0 on the next edge.
    check_next_q_low_when_d_low: assert property (
        @(posedge CLK) (D == 1'b0) |-> ##1 (Q == 1'b0)
    );

// DUT has no clock/reset; pure combinational XOR with output buffer.
    // Key behavior: X = A ^ B, with X buffered from xor0_out_X.

    // X must equal A XOR B.
    check_xor_equals_expr: assert property (
        @(posedge CLK) X == (A ^ B)
    );

// Internal XOR output must equal A XOR B.
    check_internal_xor_equals_expr: assert property (
        @(posedge CLK) xor0_out_X == (A ^ B)
    );

// Buffer must pass internal XOR output to X.
    check_buf_pass_through: assert property (
        @(posedge CLK) X == xor0_out_X
    );

// Truth table: 00 -> 0.
    check_truth_00: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0) |-> (X == 1'b0)
    );

// Truth table: 01 -> 1.
    check_truth_01: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b1) |-> (X == 1'b1)
    );

// Truth table: 10 -> 1.
    check_truth_10: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b0) |-> (X == 1'b1)
    );

// Truth table: 11 -> 0.
    check_truth_11: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1) |-> (X == 1'b0)
    );

// When B is 0, X must equal A.
    check_b_zero_transparent: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == A)
    );

// When B is 1, X must equal inverted A.
    check_b_one_inverts_a: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == ~A)
    );

// When A is 0, X must equal B.
    check_a_zero_transparent: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == B)
    );

// When A is 1, X must equal inverted B.
    check_a_one_inverts_b: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == ~B)
    );

// EQ equals (A == B).
    check_eq_definition: assert property (
        @(posedge CLK) (EQ === (A == B))
    );

// GT equals (A > B).
    check_gt_definition: assert property (
        @(posedge CLK) (GT === (A > B))
    );

// LT equals (A < B).
    check_lt_definition: assert property (
        @(posedge CLK) (LT === (A < B))
    );

// If EQ is 1 then GT is 0.
    check_eq_excludes_gt: assert property (
        @(posedge CLK) EQ |-> (GT == 1'b0)
    );

// If EQ is 1 then LT is 0.
    check_eq_excludes_lt: assert property (
        @(posedge CLK) EQ |-> (LT == 1'b0)
    );

// If GT is 1 then EQ is 0.
    check_gt_excludes_eq: assert property (
        @(posedge CLK) GT |-> (EQ == 1'b0)
    );

// If GT is 1 then LT is 0.
    check_gt_excludes_lt: assert property (
        @(posedge CLK) GT |-> (LT == 1'b0)
    );

// If LT is 1 then EQ is 0.
    check_lt_excludes_eq: assert property (
        @(posedge CLK) LT |-> (EQ == 1'b0)
    );

// If LT is 1 then GT is 0.
    check_lt_excludes_gt: assert property (
        @(posedge CLK) LT |-> (GT == 1'b0)
    );

// With known inputs, exactly one of {EQ,GT,LT} is 1.
    check_onehot_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B})) |-> $onehot({EQ,GT,LT})
    );

///// State encoding /////
    // State must be one of the defined encodings.
    check_state_encoding: assert property (
        @(posedge Clk) disable iff (tReset) (State inside {Idle, StartBit, Receiving, Done})
    );

// X equals A AND B each cycle.
    check_and_equivalence: assert property (
        @(posedge CLK) X == (A & B)
    );

// If X is HIGH, both inputs are HIGH.
    check_x_high_implies_inputs_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A == 1'b1) && (B == 1'b1)
    );

// If A is LOW, X must be LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == 1'b0)
    );

// If B is LOW, X must be LOW.
    check_b_low_forces_x_low: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == 1'b0)
    );

// If both inputs are HIGH, X must be HIGH.
    check_inputs_high_force_x_high: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1) |-> (X == 1'b1)
    );

// When X rises, both inputs are HIGH that cycle.
    check_x_rise_inputs_high_now: assert property (
        @(posedge CLK) $rose(X) |-> (A == 1'b1) && (B == 1'b1)
    );

// When X falls, at least one input is LOW that cycle.
    check_x_fall_inputs_low_now: assert property (
        @(posedge CLK) $fell(X) |-> (!A || !B)
    );

// When enable is HIGH, out equals bitwise OR of in0 and in1.
  check_or_when_enabled: assert property (
    @(posedge CLK) enable |-> (out == (in0 | in1))
  );

// When enable is LOW, out is all zeros.
  check_zero_when_disabled: assert property (
    @(posedge CLK) !enable |-> (out == 32'h0)
  );

// Output never has 1s where both inputs have 0s.
  check_no_spurious_ones: assert property (
    @(posedge CLK) (out & ~(in0 | in1)) == 32'h0
  );

// When enabled, output includes all 1-bits present in either input.
  check_out_superset_inputs_when_enabled: assert property (
    @(posedge CLK) enable |-> (((in0 | in1) & ~out) == 32'h0)
  );

// When enabled and in1 is zero, out equals in0.
  check_in1_zero_passthrough: assert property (
    @(posedge CLK) (enable && (in1 == 32'h0)) |-> (out == in0)
  );

// When enabled and in0 is zero, out equals in1.
  check_in0_zero_passthrough: assert property (
    @(posedge CLK) (enable && (in0 == 32'h0)) |-> (out == in1)
  );

// When enabled and inputs are equal, out equals that common value.
  check_equal_inputs_passthrough: assert property (
    @(posedge CLK) (enable && (in0 == in1)) |-> (out == in0)
  );

// When enabled, out is a superset of each input bitwise.
  check_bitwise_inclusion_when_enabled: assert property (
    @(posedge CLK) enable |-> ((out | in0) == out && (out | in1) == out)
  );

///// Functional decode checks /////
    // Y must always be exactly one-hot.
    check_y_onehot: assert property (
        @(posedge CLK) $onehot(Y)
    );

// Y must equal 1 shifted left by ABC.
    check_decode_shift: assert property (
        @(posedge CLK) Y == (8'b00000001 << ABC)
    );

///// Inverse mapping: Y bit implies ABC value /////
    // If Y[0] is HIGH, ABC must be 000.
    check_y0_implies_abc0: assert property (
        @(posedge CLK) Y[0] |-> (ABC == 3'b000)
    );

// If Y[1] is HIGH, ABC must be 001.
    check_y1_implies_abc1: assert property (
        @(posedge CLK) Y[1] |-> (ABC == 3'b001)
    );

// If Y[2] is HIGH, ABC must be 010.
    check_y2_implies_abc2: assert property (
        @(posedge CLK) Y[2] |-> (ABC == 3'b010)
    );

// If Y[3] is HIGH, ABC must be 011.
    check_y3_implies_abc3: assert property (
        @(posedge CLK) Y[3] |-> (ABC == 3'b011)
    );

// If Y[4] is HIGH, ABC must be 100.
    check_y4_implies_abc4: assert property (
        @(posedge CLK) Y[4] |-> (ABC == 3'b100)
    );

// If Y[5] is HIGH, ABC must be 101.
    check_y5_implies_abc5: assert property (
        @(posedge CLK) Y[5] |-> (ABC == 3'b101)
    );

// If Y[6] is HIGH, ABC must be 110.
    check_y6_implies_abc6: assert property (
        @(posedge CLK) Y[6] |-> (ABC == 3'b110)
    );

// If Y[7] is HIGH, ABC must be 111.
    check_y7_implies_abc7: assert property (
        @(posedge CLK) Y[7] |-> (ABC == 3'b111)
    );

// No reset in DUT; assertions are always active.

    // Y implements B1_N & ~(A1 & A2).
    check_functional_equation: assert property (
        @(posedge CLK) Y == (B1_N & ~(A1 & A2))
    );

// If B1_N is LOW, Y must be LOW.
    check_b1n_low_forces_y_low: assert property (
        @(posedge CLK) (!B1_N) |-> (Y == 1'b0)
    );

// If both A1 and A2 are HIGH, Y must be LOW.
    check_a1a2_both_high_forces_y_low: assert property (
        @(posedge CLK) (A1 && A2) |-> (Y == 1'b0)
    );

// When B1_N is HIGH, Y equals ~(A1 & A2).
    check_b1n_high_reduces_to_nand: assert property (
        @(posedge CLK) B1_N |-> (Y == ~(A1 & A2))
    );

// If either A1 or A2 is LOW, Y equals B1_N.
    check_either_a_low_passes_b1n: assert property (
        @(posedge CLK) (!A1 || !A2) |-> (Y == B1_N)
    );

// If Y is HIGH, then B1_N is HIGH and at least one of A1/A2 is LOW.
    check_y_high_implies_conditions: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (B1_N && (!A1 || !A2))
    );

// If Y is LOW, then B1_N is LOW or (A1 & A2) is HIGH.
    check_y_low_implies_causes: assert property (
        @(posedge CLK) (Y == 1'b0) |-> ((!B1_N) || (A1 && A2))
    );

// With B1_N HIGH, a 0->1 transition on (A1 & A2) forces Y LOW.
    check_rise_a1and_a2_forces_y_low_when_b1n_high: assert property (
        @(posedge CLK) (B1_N && $rose(A1 && A2)) |-> (Y == 1'b0)
    );

// Y is always the logical inversion of A.
    check_inversion: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == ~A)
    );

// A and Y are never both HIGH simultaneously.
    check_never_both_high: assert property (
        @(posedge CLK) disable iff (!RESETn) !(A && Y)
    );

// Q is 0 whenever RST is asserted at the clock edge.
    check_q_zero_when_rst_high: assert property (
        @(posedge CLK) RST |-> (Q == 3'b000)
    );

// On a rising edge of RST, Q is forced to 0 in that cycle.
    check_reset_rise_forces_zero: assert property (
        @(posedge CLK) $rose(RST) |-> (Q == 3'b000)
    );

// If reset is high in two consecutive cycles, Q is 0 in both.
    check_hold_zero_during_reset: assert property (
        @(posedge CLK) RST && $past(RST) |-> (Q == 3'b000) && ($past(Q) == 3'b000)
    );

// X equals (A|B|C|D) masked off when all inputs are 1
    check_functional_equivalence: assert property (
        @(posedge CLK) X == ((A | B | C | D) & ~(A & B & C & D))
    );

// All inputs 1 forces X to 0
    check_all_ones_forces_zero: assert property (
        @(posedge CLK) (A & B & C & D) |-> (X == 1'b0)
    );

// All inputs 0 forces X to 0
    check_all_zeros_forces_zero: assert property (
        @(posedge CLK) !(A | B | C | D) |-> (X == 1'b0)
    );

// When not all ones, X equals the OR of inputs
    check_not_all_ones_equals_or: assert property (
        @(posedge CLK) !(A & B & C & D) |-> (X == (A | B | C | D))
    );

// If some but not all inputs are 1, X is 1
    check_partial_ones_give_one: assert property (
        @(posedge CLK) ((A | B | C | D) && !(A & B & C & D)) |-> (X == 1'b1)
    );

// X high implies at least one input high and not all inputs high
    check_x_high_condition: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A | B | C | D) && !(A & B & C & D))
    );

// X low occurs only when all zeros or all ones
    check_x_low_only_allzeros_or_allones: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((!(A | B | C | D)) || (A & B & C & D))
    );

// Exactly one-hot on A drives X high
    check_singleton_A: assert property (
        @(posedge CLK) (A && !B && !C && !D) |-> (X == 1'b1)
    );

// Exactly one-hot on B drives X high
    check_singleton_B: assert property (
        @(posedge CLK) (!A && B && !C && !D) |-> (X == 1'b1)
    );

// Exactly one-hot on C drives X high
    check_singleton_C: assert property (
        @(posedge CLK) (!A && !B && C && !D) |-> (X == 1'b1)
    );

// Exactly one-hot on D drives X high
    check_singleton_D: assert property (
        @(posedge CLK) (!A && !B && !C && D) |-> (X == 1'b1)
    );

// Result matches selected operation each cycle.
    check_function_select: assert property (
        @(posedge CLK) result == (sub ? (num1 - num2) : (num1 + num2))
    );

// When sub==0, result equals num1 + num2.
    check_add_path: assert property (
        @(posedge CLK) (sub == 1'b0) |-> (result == (num1 + num2))
    );

// When sub==1, result equals num1 - num2.
    check_sub_path: assert property (
        @(posedge CLK) (sub == 1'b1) |-> (result == (num1 - num2))
    );

// Addition identity: adding zero returns num1.
    check_add_zero_identity: assert property (
        @(posedge CLK) (sub == 1'b0 && (num2 == 4'b0000)) |-> (result == num1)
    );

// Subtraction identity: subtracting zero returns num1.
    check_sub_zero_identity: assert property (
        @(posedge CLK) (sub == 1'b1 && (num2 == 4'b0000)) |-> (result == num1)
    );

// Subtracting equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge CLK) (sub == 1'b1 && (num1 == num2)) |-> (result == 4'b0000)
    );

// Output equals bitwise AND of DATA_IN and MASK.
    check_output_is_bitwise_and: assert property (
        @(posedge CLK) DATA_OUT == (DATA_IN & MASK)
    );

// When MASK is all zeros, output must be zero.
    check_zero_mask_clears_output: assert property (
        @(posedge CLK) (MASK == 4'b0000) |-> (DATA_OUT == 4'b0000)
    );

// When MASK is all ones, output equals input.
    check_allones_mask_passthrough: assert property (
        @(posedge CLK) (MASK == 4'b1111) |-> (DATA_OUT == DATA_IN)
    );

// Bits not selected by MASK must be zero.
    check_unmasked_bits_are_zero: assert property (
        @(posedge CLK) (DATA_OUT & ~MASK) == 4'b0000
    );

// On masked bits, output matches input.
    check_masked_bits_match_input: assert property (
        @(posedge CLK) ((DATA_OUT ^ DATA_IN) & MASK) == 4'b0000
    );

// Output cannot introduce new 1s where input has 0s.
    check_no_new_ones_compared_to_input: assert property (
        @(posedge CLK) (DATA_OUT & ~DATA_IN) == 4'b0000
    );

// Result matches the combinational ternary equation.
    check_result_matches_equation: assert property (
        @(posedge CLK) result == (add ? (a + b) : (sub ? (a - b) : 8'h00))
    );

// When add is asserted, result equals a + b (priority over sub).
    check_add_priority: assert property (
        @(posedge CLK) add |-> (result == (a + b))
    );

// When only sub is asserted, result equals a - b.
    check_sub_when_no_add: assert property (
        @(posedge CLK) (!add && sub) |-> (result == (a - b))
    );

// When neither add nor sub is asserted, result is zero.
    check_zero_when_no_ops: assert property (
        @(posedge CLK) (!add && !sub) |-> (result == 8'h00)
    );

// When both add and sub are asserted, add takes precedence (result is a + b).
    check_both_ops_add_wins: assert property (
        @(posedge CLK) (add && sub) |-> (result == (a + b))
    );

// Clock: CLK posedge; Reset: RESET synchronous active-high.
    // Behavior: EN_OUT=1 iff SLOWCLK is unchanged from previous CLK; else EN_OUT=0.

    // During RESET, EN_OUT must be driven LOW.
    reset_drives_en_low: assert property (
        @(posedge CLK) RESET |-> (EN_OUT == 1'b0)
    );

///// Functional capture behavior (common to both builds) /////
    // When not in reset and se was 0 last cycle, q captures din.
    check_capture_din_when_se0: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b0)) |-> (q == $past(din))
    );

// When not in reset, se was 0, and din equaled q last cycle, q holds its value.
    check_hold_when_se0_and_din_matches_q: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b0) && ($past(din) == $past(q))) |-> (q == $past(q))
    );

///// Scan-enabled build /////
    // Combined next-state function: q captures si when se=1, else din, when not in reset.
    check_scan_combined_nextstate: assert property (
        @(posedge clk) disable iff (!rst_l) $past(rst_l) |-> (q == ($past(se) ? $past(si) : $past(din)))
    );

// When not in reset and se was 1 last cycle, q captures si.
    check_capture_si_when_se1: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b1)) |-> (q == $past(si))
    );

// so directly reflects q at all times (when property enabled).
    check_so_equals_q: assert property (
        @(posedge clk) disable iff (!rst_l) (so == q)
    );

// When not in reset and se was 0, so reflects previous din (via so=q).
    check_so_follows_prev_din_when_se0: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b0)) |-> (so == $past(din))
    );

// When not in reset and se was 1, so reflects previous si (via so=q).
    check_so_follows_prev_si_when_se1: assert property (
        @(posedge clk) disable iff (!rst_l) ($past(rst_l) && ($past(se) == 1'b1)) |-> (so == $past(si))
    );

///// Reset behavior /////
    // RESET drives Q to zero on the next clock.
    reset_clears_next: assert property (
        @(posedge CLK) RESET |=> (Q == 4'b0000)
    );

// While RESET is held across cycles, Q remains zero.
    reset_holds_zero: assert property (
        @(posedge CLK) $past(RESET) && RESET |-> (Q == 4'b0000)
    );

///// Counting behavior /////
    // When UP_DOWN=1 and not in reset, Q increments by 1 on the next clock.
    count_up_step: assert property (
        @(posedge CLK) disable iff (RESET) UP_DOWN |=> (Q == $past(Q) + 4'd1)
    );

// When UP_DOWN=0 and not in reset, Q decrements by 1 on the next clock.
    count_down_step: assert property (
        @(posedge CLK) disable iff (RESET) !UP_DOWN |=> (Q == $past(Q) - 4'd1)
    );

// Without reset, Q changes every cycle (always +/-1).
    q_changes_each_cycle: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q != $past(Q))
    );

// When counting up from 0xF, Q wraps to 0 on the next clock.
    count_up_wrap_to_zero: assert property (
        @(posedge CLK) disable iff (RESET) (UP_DOWN && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// When counting down from 0, Q wraps to 0xF on the next clock.
    count_down_wrap_to_f: assert property (
        @(posedge CLK) disable iff (RESET) (!UP_DOWN && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Two consecutive UP cycles (no reset) advance Q by +2 modulo 16.
    two_cycles_up: assert property (
        @(posedge CLK) disable iff (RESET) (UP_DOWN ##1 UP_DOWN) |=> (Q == $past(Q,2) + 4'd2)
    );

// Two consecutive DOWN cycles (no reset) decrement Q by -2 modulo 16.
    two_cycles_down: assert property (
        @(posedge CLK) disable iff (RESET) ((!UP_DOWN) ##1 (!UP_DOWN)) |=> (Q == $past(Q,2) - 4'd2)
    );

///// Next-state function /////
    // When not at MAX_COUNT, count increments by 1 next cycle.
    increment_when_below_max: assert property (
        @(posedge clk) disable iff (rst) (count != MAX_COUNT) |=> (count == $past(count) + 8'd1)
    );

// When at MAX_COUNT, count wraps to 0 next cycle.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == MAX_COUNT) |=> (count == 8'd0)
    );

///// Invariants /////
    // While not in reset, count never exceeds MAX_COUNT.
    count_bounded_by_max: assert property (
        @(posedge clk) disable iff (rst) (count <= MAX_COUNT)
    );

// MAX_COUNT cannot persist for two consecutive cycles when not in reset.
    no_two_cycles_at_max: assert property (
        @(posedge clk) disable iff (rst) (count == MAX_COUNT) |=> (count != MAX_COUNT)
    );

penultimate_to_max: assert property (
                @(posedge clk) disable iff (rst) (count == (MAX_COUNT - 1)) |=> (count == MAX_COUNT)
            );

zero_to_one_next: assert property (
                @(posedge clk) disable iff (rst) ((count == 8'd0) && !$past(rst)) |=> (count == 8'd1)
            );

// Output equals (A | B) & C.
    check_function_equivalence: assert property (
        @(posedge clk) out == ((A | B) & C)
    );

// If out is HIGH, C must be HIGH.
    check_out_implies_C: assert property (
        @(posedge clk) out |-> (C == 1'b1)
    );

// If C is LOW, out must be LOW.
    check_out_zero_when_C_zero: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == 1'b0)
    );

// If A and B are both LOW, out must be LOW.
    check_out_zero_when_A_and_B_zero: assert property (
        @(posedge clk) (!A && !B) |-> (out == 1'b0)
    );

// If C is HIGH and (A or B) is HIGH, out must be HIGH.
    check_out_one_when_C_and_AorB_one: assert property (
        @(posedge clk) (C && (A || B)) |-> (out == 1'b1)
    );

// A rising out requires C HIGH.
    check_out_rise_requires_C_high: assert property (
        @(posedge clk) $rose(out) |-> (C == 1'b1)
    );

// A rising out requires A or B HIGH.
    check_out_rise_requires_A_or_B_high: assert property (
        @(posedge clk) $rose(out) |-> (A || B)
    );

// A falling out implies C LOW or both A and B LOW.
    check_out_fall_requires_inputs_low: assert property (
        @(posedge clk) $fell(out) |-> (!C || (!A && !B))
    );

// OUT must equal A + B modulo 16.
    check_sum_mod16: assert property (
        @(posedge CLK) OUT == (A + B)
    );

// LSB is XOR of inputs (CIN=0).
    check_bit0_xor: assert property (
        @(posedge CLK) OUT[0] == (A[0] ^ B[0])
    );

// Bit1 sum with carry from bit0.
    check_bit1_sum: assert property (
        @(posedge CLK) OUT[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

// Bit2 sum with carry from lower bits.
    check_bit2_sum: assert property (
        @(posedge CLK) OUT[2] == ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

// Bit3 sum with carry from lower bits.
    check_bit3_sum: assert property (
        @(posedge CLK) OUT[3] == ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

// Adding zero on A passes B through.
    check_a_zero_passthru: assert property (
        @(posedge CLK) (A == 4'h0) |-> (OUT == B)
    );

// Adding zero on B passes A through.
    check_b_zero_passthru: assert property (
        @(posedge CLK) (B == 4'h0) |-> (OUT == A)
    );

// 15 + 1 wraps to 0 (carry-out ignored).
    check_wrap_15_plus_1: assert property (
        @(posedge CLK) ((A == 4'hF) && (B == 4'h1)) |-> (OUT == 4'h0)
    );

// y equals a & b when a rises.
    check_y_eq_and_on_posedge_a: assert property (
        @(posedge a) y == (a & b)
    );

// y equals a & b when a falls.
    check_y_eq_and_on_negedge_a: assert property (
        @(negedge a) y == (a & b)
    );

// y equals a & b when b rises.
    check_y_eq_and_on_posedge_b: assert property (
        @(posedge b) y == (a & b)
    );

// y equals a & b when b falls.
    check_y_eq_and_on_negedge_b: assert property (
        @(negedge b) y == (a & b)
    );

// y equals a & b when y rises (redundant functional check on y edge).
    check_y_eq_and_on_posedge_y: assert property (
        @(posedge y) y == (a & b)
    );

// y equals a & b when y falls (redundant functional check on y edge).
    check_y_eq_and_on_negedge_y: assert property (
        @(negedge y) y == (a & b)
    );

// Note: No clock/reset in RTL; sample assertions on posedge of sel1.

  // When sel1=1 and sel2=1, out must equal d3.
  check_sel11_routes_d3: assert property (
    @(posedge sel1) (sel1 && sel2) |-> (out == d3)
  );

// When sel1=1 and sel2=0, out must equal d2.
  check_sel10_routes_d2: assert property (
    @(posedge sel1) (sel1 && !sel2) |-> (out == d2)
  );

// When sel1=0 and sel2=1, out must equal d1.
  check_sel01_routes_d1: assert property (
    @(posedge sel1) (!sel1 && sel2) |-> (out == d1)
  );

// When sel1=0 and sel2=0, out must equal d0.
  check_sel00_routes_d0: assert property (
    @(posedge sel1) (!sel1 && !sel2) |-> (out == d0)
  );

// Out equals the exact ternary selection used in the RTL.
  check_mux_functional_equivalence: assert property (
    @(posedge sel1) out == ((sel1 & sel2) ? d3 :
                            (sel1 & ~sel2) ? d2 :
                            (~sel1 & sel2) ? d1 :
                            d0)
  );

// Exactly one of the four selection minterms is true for any sel1/sel2.
  check_onehot_minterms: assert property (
    @(posedge sel1) $onehot({(sel1 & sel2), (sel1 & ~sel2), (~sel1 & sel2), (~sel1 & ~sel2)})
  );

// Reset forces count to zero whenever sampled high on clk.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 8'd0)
    );

// On every non-reset cycle, next count is either zero or previous+1.
    check_zero_or_plus1_transition: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |-> ##1 (reset || (count == 8'd0) || (count == ($past(count) + 8'd1)))
    );

// On reset deassertion, count becomes 0 (if max_count==0) or 1 (otherwise) at that clk edge.
    check_reset_deassertion_result: assert property (
        @(posedge clk) $fell(reset) |-> (count == 8'd0 || count == 8'd1)
    );

// data_out matches exact RTL expression (pass-through vs shifted)
    check_function_equivalence: assert property (
        @(posedge A) data_out == (passthrough ? data_in : expected_shifted)
    );

// Pass-through case: when A&~B&~C, output equals input
    check_passthrough: assert property (
        @(posedge A) passthrough |-> (data_out == data_in)
    );

// Shift-left case: when not pass-through and dir==0, output equals data_in<<1
    check_shift_left_vector: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out == left_shifted)
    );

// Shift-right case: when not pass-through and dir==1, output equals data_in>>1
    check_shift_right_vector: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out == right_shifted)
    );

// Left shift zeros the LSB
    check_shift_left_lsb_zero: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[0] == 1'b0)
    );

// Left shift bit mapping: out[1] <= in[0]
    check_shift_left_bit1_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[1] == data_in[0])
    );

// Left shift bit mapping: out[2] <= in[1]
    check_shift_left_bit2_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[2] == data_in[1])
    );

// Left shift bit mapping: out[3] <= in[2]
    check_shift_left_bit3_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b0)) |-> (data_out[3] == data_in[2])
    );

// Right shift zeros the MSB
    check_shift_right_msb_zero: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[3] == 1'b0)
    );

// Right shift bit mapping: out[2] <= in[3]
    check_shift_right_bit2_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[2] == data_in[3])
    );

// Right shift bit mapping: out[1] <= in[2]
    check_shift_right_bit1_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[1] == data_in[2])
    );

// Right shift bit mapping: out[0] <= in[1]
    check_shift_right_bit0_map: assert property (
        @(posedge A) (!passthrough && (dir == 1'b1)) |-> (data_out[0] == data_in[1])
    );

// EQ reflects A == B.
    check_eq_definition: assert property (
        @(posedge clk) (EQ == (A == B))
    );

// GT reflects A > B.
    check_gt_definition: assert property (
        @(posedge clk) (GT == (A > B))
    );

// LT reflects A < B.
    check_lt_definition: assert property (
        @(posedge clk) (LT == (A < B))
    );

// NE reflects A != B.
    check_ne_definition: assert property (
        @(posedge clk) (NE == (A != B))
    );

// Exactly one of EQ, GT, LT is HIGH at any time.
    check_egtlt_onehot: assert property (
        @(posedge clk) $onehot({EQ, GT, LT})
    );

// NE is the logical complement of EQ.
    check_ne_complement_eq: assert property (
        @(posedge clk) (NE == !EQ)
    );

// NE equals (GT or LT).
    check_ne_eq_gt_or_lt: assert property (
        @(posedge clk) (NE == (GT || LT))
    );

// If GT is HIGH, LT must be LOW in the same cycle.
    check_gt_excludes_lt: assert property (
        @(posedge clk) GT |-> !LT
    );

// If LT is HIGH, GT must be LOW in the same cycle.
    check_lt_excludes_gt: assert property (
        @(posedge clk) LT |-> !GT
    );

// If EQ is HIGH, both GT and LT must be LOW.
    check_eq_excludes_gt_lt: assert property (
        @(posedge clk) EQ |-> (!GT && !LT)
    );

// 5-bit result matches arithmetic sum of inputs.
    check_sum_5bit: assert property (
        @(posedge CLK) disable iff (1'b0) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// LSB sum bit equals A0 ^ B0 ^ Ci.
    check_bit0_sum: assert property (
        @(posedge CLK) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Bit1 sum equals A1 ^ B1 ^ C0.
    check_bit1_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
    );

// Bit2 sum equals A2 ^ B2 ^ C1.
    check_bit2_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[2] == (A[2] ^ B[2] ^ (
                        (A[1] & B[1]) |
                        ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                    ))
    );

// Bit3 sum equals A3 ^ B3 ^ C2.
    check_bit3_sum: assert property (
        @(posedge CLK) disable iff (1'b0)
            S[3] == (A[3] ^ B[3] ^ (
                        (A[2] & B[2]) |
                        ((A[2] ^ B[2]) & (
                            (A[1] & B[1]) |
                            ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                        ))
                    ))
    );

// Final carry-out equals (A3 & B3) | ((A3 ^ B3) & C2).
    check_final_carry: assert property (
        @(posedge CLK) disable iff (1'b0)
            Co == (
                (A[3] & B[3]) |
                ((A[3] ^ B[3]) & (
                    (A[2] & B[2]) |
                    ((A[2] ^ B[2]) & (
                        (A[1] & B[1]) |
                        ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
                    ))
                ))
            )
    );

// Adding zero B with zero carry-in passes A through, no carry-out.
    check_pass_through_A: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, A})
    );

// Adding zero A with zero carry-in passes B through, no carry-out.
    check_pass_through_B: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((A == 4'b0000) && (Ci == 1'b0)) |-> ({Co, S} == {1'b0, B})
    );

// All zeros on inputs yield zero sum and zero carry.
    check_all_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((A == 4'b0000) && (B == 4'b0000) && (Ci == 1'b0)) |-> ((S == 4'b0000) && (Co == 1'b0))
    );

// A + ~A + 1 = 16 => zero sum and carry-out set.
    check_complement_plus_one: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B == ~A) && (Ci == 1'b1)) |-> ((S == 4'b0000) && (Co == 1'b1))
    );

// When SET_B is LOW at a clock edge, Q must be 0 on the next clock.
    clear_forces_q0_next: assert property (
        @(posedge CLK) !SET_B |-> (Q == 1'b0)
    );

// If SET_B is LOW for two consecutive clocks, Q is 0 at the current clock.
    q0_when_clear_two_cycles: assert property (
        @(posedge CLK) (!SET_B && $past(!SET_B)) |=> (Q == 1'b0)
    );

// While SET_B stays LOW across clocks, Q remains stable (holds 0).
    q_stable_during_persistent_clear: assert property (
        @(posedge CLK) (!SET_B && $past(!SET_B)) |=> $stable(Q)
    );

// Analysis: No clock/reset in RTL; pure combinational comparator; out encodes: 01(gt), 10(eq), 00(lt).

    ///// Functional mapping from inputs to output /////
    // If in_0 > in_1 then out must be 01.
    check_map_gt_to_01: assert property (
        @(posedge clk) (in_0 > in_1) |-> (out == 2'b01)
    );

// If in_0 == in_1 then out must be 10.
    check_map_eq_to_10: assert property (
        @(posedge clk) (in_0 == in_1) |-> (out == 2'b10)
    );

// If neither (in_0 > in_1) nor (in_0 == in_1) then out must be 00 (else branch).
    check_map_else_to_00: assert property (
        @(posedge clk) (!(in_0 > in_1) && !(in_0 == in_1)) |-> (out == 2'b00)
    );

///// Output code consistency /////
    // out never takes the invalid code 11.
    check_out_never_11: assert property (
        @(posedge clk) out != 2'b11
    );

///// Output implies condition (no spurious codes) /////
    // If out is 01, then in_0 > in_1 must have been true.
    check_out_01_implies_gt: assert property (
        @(posedge clk) (out == 2'b01) |-> (in_0 > in_1)
    );

// If out is 10, then in_0 == in_1 must have been true.
    check_out_10_implies_eq: assert property (
        @(posedge clk) (out == 2'b10) |-> (in_0 == in_1)
    );

// Q equals data sampled on the previous posedge.
    check_q_matches_prev_posedge_data: assert property (
        @(posedge clk) 1 |=> (Q == $past(data))
    );

// Q_bar equals complement of data sampled on the previous posedge.
    check_qbar_matches_prev_posedge_data_complement: assert property (
        @(posedge clk) 1 |=> (Q_bar == ~ $past(data))
    );

// Outputs are always complements at posedge sampling.
    check_outputs_are_complements_posedge: assert property (
        @(posedge clk) 1 |=> (Q_bar == ~Q)
    );

// Outputs are always complements at negedge sampling.
    check_outputs_are_complements_negedge: assert property (
        @(negedge clk) 1 |=> (Q_bar == ~Q)
    );

// If data changes between two consecutive posedges, both outputs change by the next posedge.
    check_output_change_reflects_data_change: assert property (
        @(posedge clk) 1 |=> 1 |=> (($past(data) != $past(data,2)) |-> ($changed(Q) && $changed(Q_bar)))
    );

// No clock/reset in DUT; combinational; sample on edges of A/B/out.

    // Core relation: out equals (|A) & ~(|B) on A[0] edges.
    check_func_equiv_on_A0: assert property (
        @(posedge A[0]) out == ((|A) & ~(|B))
    );

// If A is zero, out must be 0.
    check_out_zero_when_A_zero_on_A1: assert property (
        @(posedge A[1]) (A == 4'd0) |-> (out == 1'b0)
    );

// If B is nonzero, out must be 0.
    check_out_zero_when_B_nonzero_on_B0: assert property (
        @(posedge B[0]) (B != 4'd0) |-> (out == 1'b0)
    );

// If A is nonzero and B is zero, out must be 1.
    check_out_one_when_Ane0_Beq0_on_A2: assert property (
        @(posedge A[2]) ((A != 4'd0) && (B == 4'd0)) |-> (out == 1'b1)
    );

// If out is 1, A must be nonzero and B must be zero.
    check_out_one_only_if_Ane0_Beq0_on_A3: assert property (
        @(posedge A[3]) (out == 1'b1) |-> ((A != 4'd0) && (B == 4'd0))
    );

// If both A and B are zero, out must be 0.
    check_out_zero_when_both_zero_on_B1: assert property (
        @(posedge B[1]) ((A == 4'd0) && (B == 4'd0)) |-> (out == 1'b0)
    );

// If both A and B are nonzero, out must be 0.
    check_out_zero_when_both_nonzero_on_B2: assert property (
        @(posedge B[2]) ((A != 4'd0) && (B != 4'd0)) |-> (out == 1'b0)
    );

// If out is 0, then either A is zero or B is nonzero.
    check_out_zero_implies_Azero_or_Bnonzero_on_B3: assert property (
        @(posedge B[3]) (out == 1'b0) |-> ((A == 4'd0) || (B != 4'd0))
    );

// When A is nonzero, out equals ~(|B).
    check_when_A_nonzero_out_eq_not_reduceB_on_A0: assert property (
        @(posedge A[0]) (A != 4'd0) |-> (out == ~(|B))
    );

// Analysis: no clock/reset in RTL; purely combinational; Y=1 if A|B|C or (D^E when A=B=C=0).

    // Y equals the combinational function encoded by the if/else chain.
    check_y_function_equivalence: assert property (
        @(posedge CLK) Y == (A || B || C || ((!A && !B && !C) && (D ^ E)))
    );

// If any of A,B,C is 1, Y must be 1.
    check_y_high_when_any_abc: assert property (
        @(posedge CLK) (A || B || C) |-> (Y == 1'b1)
    );

// If A,B,C are 0 and D^E is 1, Y must be 1.
    check_y_high_when_dxorE_no_abc: assert property (
        @(posedge CLK) (!A && !B && !C && (D ^ E)) |-> (Y == 1'b1)
    );

// If A,B,C are 0 and D^E is 0, Y must be 0.
    check_y_low_when_no_conditions: assert property (
        @(posedge CLK) (!A && !B && !C && !(D ^ E)) |-> (Y == 1'b0)
    );

// Y=1 only when one of the specified conditions holds.
    check_y_high_only_when_condition_true: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A || B || C || ((!A && !B && !C) && (D ^ E)))
    );

// Y=0 only when no condition in the chain is met.
    check_y_low_only_when_no_condition_true: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (!A && !B && !C && !(D ^ E))
    );

// Functional NOR relation: out equals ~(a | b).
    check_out_is_nor_ab: assert property (
        @(posedge CLK) out == ~(a | b)
    );

// Out HIGH only when both inputs are LOW.
    check_out_high_only_when_both_low: assert property (
        @(posedge CLK) out |-> (!a && !b)
    );

// If any input is HIGH, out must be LOW.
    check_any_input_high_forces_out_low: assert property (
        @(posedge CLK) (a || b) |-> (!out)
    );

// If both inputs are LOW, out must be HIGH.
    check_both_low_implies_out_high: assert property (
        @(posedge CLK) (!a && !b) |-> out
    );

// Synchronous reset drives cntB_reg to zero.
    reset_clears_cntB: assert property (
        @(posedge clk) rst |-> (cntB_reg == 4'b0000)
    );

// Q must be 0 on any clock where reset is asserted.
    reset_clears_Q: assert property (
        @(posedge clk) reset |-> (Q == 4'b0000)
    );

// When SEL==00, Y equals D0 in the same cycle.
    check_sel00_maps_d0: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b00) |-> (Y == D0)
    );

// When SEL==01, Y equals D1 in the same cycle.
    check_sel01_maps_d1: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b01) |-> (Y == D1)
    );

// When SEL==10, Y equals D2 in the same cycle.
    check_sel10_maps_d2: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b10) |-> (Y == D2)
    );

// When SEL==11, Y equals D3 in the same cycle.
    check_sel11_maps_d3: assert property (
        @(posedge clk) disable iff (!reset_n) (SEL == 2'b11) |-> (Y == D3)
    );

// Functional equivalence to a 4:1 mux tree driven by SEL bits.
    check_mux_function: assert property (
        @(posedge clk) disable iff (!reset_n) Y == (SEL[1] ? (SEL[0] ? D3 : D2) : (SEL[0] ? D1 : D0))
    );

// sum is a mux of a and b selected by cout.
    check_sum_mux: assert property (
        @(posedge CLK) sum == (cout ? b : a)
    );

// cout equals the carry-out of adding a[8:0], b[8:0], and cin.
    check_cout_is_low9_carry: assert property (
        @(posedge CLK) cout == ((a[8:0] + b[8:0] + cin) >= 10'd512)
    );

// If low 9 bits of a and b are zero and cin is zero, cout must be zero.
    check_cout_zero_when_no_generate_no_cin: assert property (
        @(posedge CLK) ((a[8:0] == 9'd0) && (b[8:0] == 9'd0) && (cin == 1'b0)) |-> (cout == 1'b0)
    );

// If low 9 bits of a and b are all ones, cout must be one.
    check_cout_one_when_low9_all_ones: assert property (
        @(posedge CLK) ((a[8:0] == 9'h1FF) && (b[8:0] == 9'h1FF)) |-> (cout == 1'b1)
    );

// If all low 9 bits propagate (a^b == all 1s) and cin is one, cout must be one.
    check_cout_one_when_all_propagate_and_cin1: assert property (
        @(posedge CLK) (((a[8:0] ^ b[8:0]) == 9'h1FF) && (cin == 1'b1)) |-> (cout == 1'b1)
    );

// A generate at bit 8 (a[8]&b[8]) forces cout high.
    check_g8_forces_cout: assert property (
        @(posedge CLK) (a[8] & b[8]) |-> cout
    );

// RsOut_sel equals Rd_write_byte_en when MEM_REG writes to Rs_IF_ID and no load-use
    check_rsout_sel_set_on_match: assert property (
        @(posedge clk) (!loaduse && RegWrite_MEM_REG && (Rd_MEM_REG == Rs_IF_ID)) |-> (RsOut_sel == Rd_write_byte_en)
    );

// RsOut_sel is zero otherwise
    check_rsout_sel_zero_else: assert property (
        @(posedge clk) !( !loaduse && RegWrite_MEM_REG && (Rd_MEM_REG == Rs_IF_ID) ) |-> (RsOut_sel == 4'b0000)
    );

// RtOut_sel equals Rd_write_byte_en when MEM_REG writes to Rt_IF_ID and no load-use
    check_rtout_sel_set_on_match: assert property (
        @(posedge clk) (!loaduse && RegWrite_MEM_REG && (Rd_MEM_REG == Rt_IF_ID)) |-> (RtOut_sel == Rd_write_byte_en)
    );

// RtOut_sel is zero otherwise
    check_rtout_sel_zero_else: assert property (
        @(posedge clk) !( !loaduse && RegWrite_MEM_REG && (Rd_MEM_REG == Rt_IF_ID) ) |-> (RtOut_sel == 4'b0000)
    );

// A_in_sel is 0x55 when EX_MEM writes to Rs_ID_EX (priority case)
    check_a_in_sel_exmem_priority: assert property (
        @(posedge clk) (RegWrite_EX_MEM && (Rd_EX_MEM == Rs_ID_EX)) |-> (A_in_sel == 8'b01010101)
    );

// A_in_sel maps from MEM_REG byte enables when EX_MEM does not match and MEM_REG matches Rs_ID_EX
    check_a_in_sel_memreg_map: assert property (
        @(posedge clk)
        ((!RegWrite_EX_MEM || (Rd_EX_MEM != Rs_ID_EX)) && RegWrite_MEM_REG && (Rd_MEM_REG == Rs_ID_EX)) |->
        ( (A_in_sel[7:6] == (Rd_write_byte_en[3] ? 2'b10 : 2'b00)) &&
          (A_in_sel[5:4] == (Rd_write_byte_en[2] ? 2'b10 : 2'b00)) &&
          (A_in_sel[3:2] == (Rd_write_byte_en[1] ? 2'b10 : 2'b00)) &&
          (A_in_sel[1:0] == 2'b10) )
    );

// A_in_sel is zero when neither EX_MEM nor MEM_REG matches Rs_ID_EX
    check_a_in_sel_zero_else: assert property (
        @(posedge clk)
        !( (RegWrite_EX_MEM && (Rd_EX_MEM == Rs_ID_EX)) || (RegWrite_MEM_REG && (Rd_MEM_REG == Rs_ID_EX)) ) |-> (A_in_sel == 8'b00000000)
    );

// B_in_sel is 0x55 when EX_MEM writes to Rt_ID_EX (priority case)
    check_b_in_sel_exmem_priority: assert property (
        @(posedge clk) (RegWrite_EX_MEM && (Rd_EX_MEM == Rt_ID_EX)) |-> (B_in_sel == 8'b01010101)
    );

// B_in_sel maps from MEM_REG byte enables when EX_MEM does not match and MEM_REG matches Rt_ID_EX
    check_b_in_sel_memreg_map: assert property (
        @(posedge clk)
        ((!RegWrite_EX_MEM || (Rd_EX_MEM != Rt_ID_EX)) && RegWrite_MEM_REG && (Rd_MEM_REG == Rt_ID_EX)) |->
        ( (B_in_sel[7:6] == (Rd_write_byte_en[3] ? 2'b10 : 2'b00)) &&
          (B_in_sel[5:4] == (Rd_write_byte_en[2] ? 2'b10 : 2'b00)) &&
          (B_in_sel[3:2] == (Rd_write_byte_en[1] ? 2'b10 : 2'b00)) &&
          (B_in_sel[1:0] == (Rd_write_byte_en[0] ? 2'b10 : 2'b00)) )
    );

// B_in_sel is zero when neither EX_MEM nor MEM_REG matches Rt_ID_EX
    check_b_in_sel_zero_else: assert property (
        @(posedge clk)
        !( (RegWrite_EX_MEM && (Rd_EX_MEM == Rt_ID_EX)) || (RegWrite_MEM_REG && (Rd_MEM_REG == Rt_ID_EX)) ) |-> (B_in_sel == 8'b00000000)
    );

///// 16:1 mux selection mapping /////
    // When sel==0, output equals i0000.
    sel_0_maps_to_i0000: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd0) |-> (o == i0000)
    );

// When sel==1, output equals i0001.
    sel_1_maps_to_i0001: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd1) |-> (o == i0001)
    );

// When sel==2, output equals i0010.
    sel_2_maps_to_i0010: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd2) |-> (o == i0010)
    );

// When sel==3, output equals i0011.
    sel_3_maps_to_i0011: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd3) |-> (o == i0011)
    );

// When sel==4, output equals i0100.
    sel_4_maps_to_i0100: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd4) |-> (o == i0100)
    );

// When sel==5, output equals i0101.
    sel_5_maps_to_i0101: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd5) |-> (o == i0101)
    );

// When sel==6, output equals i0110.
    sel_6_maps_to_i0110: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd6) |-> (o == i0110)
    );

// When sel==7, output equals i0111.
    sel_7_maps_to_i0111: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd7) |-> (o == i0111)
    );

// When sel==8, output equals i1000.
    sel_8_maps_to_i1000: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd8) |-> (o == i1000)
    );

// When sel==9, output equals i1001.
    sel_9_maps_to_i1001: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd9) |-> (o == i1001)
    );

// When sel==10, output equals i1010.
    sel_10_maps_to_i1010: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd10) |-> (o == i1010)
    );

// When sel==11, output equals i1011.
    sel_11_maps_to_i1011: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd11) |-> (o == i1011)
    );

// When sel==12, output equals i1100.
    sel_12_maps_to_i1100: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd12) |-> (o == i1100)
    );

// When sel==13, output equals i1101.
    sel_13_maps_to_i1101: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd13) |-> (o == i1101)
    );

// When sel==14, output equals i1110.
    sel_14_maps_to_i1110: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd14) |-> (o == i1110)
    );

// When sel==15, output equals i1111 (default case).
    sel_15_maps_to_i1111: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 4'd15) |-> (o == i1111)
    );

// Y must equal B | S0 (4-state aware).
    check_y_equals_b_or_s0: assert property (
        @(posedge clk) disable iff (1'b0) (Y === (B | S0))
    );

// When both B and S0 are 0, Y must be 0.
    check_y_zero_when_both_zero: assert property (
        @(posedge clk) disable iff (1'b0) ((B === 1'b0) && (S0 === 1'b0)) |-> (Y === 1'b0)
    );

// When B is 1, Y must be 1.
    check_y_one_when_b_one: assert property (
        @(posedge clk) disable iff (1'b0) (B === 1'b1) |-> (Y === 1'b1)
    );

// When S0 is 1, Y must be 1.
    check_y_one_when_s0_one: assert property (
        @(posedge clk) disable iff (1'b0) (S0 === 1'b1) |-> (Y === 1'b1)
    );

// If Y is 0, then both B and S0 must be 0.
    check_y_zero_implies_inputs_zero: assert property (
        @(posedge clk) disable iff (1'b0) (Y === 1'b0) |-> ((B === 1'b0) && (S0 === 1'b0))
    );

// If Y is 1, then at least one of B or S0 must be 1.
    check_y_one_implies_any_input_one: assert property (
        @(posedge clk) disable iff (1'b0) (Y === 1'b1) |-> ((B === 1'b1) || (S0 === 1'b1))
    );

// When S0 is 0, Y must equal B.
    check_y_eq_b_when_s0_zero: assert property (
        @(posedge clk) disable iff (1'b0) (S0 === 1'b0) |-> (Y === B)
    );

// When B is 0, Y must equal S0.
    check_y_eq_s0_when_b_zero: assert property (
        @(posedge clk) disable iff (1'b0) (B === 1'b0) |-> (Y === S0)
    );

// When select is 00, output equals data_in_0.
    check_sel_00_maps_in0: assert property (
        @(posedge CLK) ({ctrl_sel_1, ctrl_sel_0} == 2'b00) |-> (data_out == data_in_0)
    );

// When select is 01, output equals data_in_1.
    check_sel_01_maps_in1: assert property (
        @(posedge CLK) ({ctrl_sel_1, ctrl_sel_0} == 2'b01) |-> (data_out == data_in_1)
    );

// When select is 10, output equals data_in_2.
    check_sel_10_maps_in2: assert property (
        @(posedge CLK) ({ctrl_sel_1, ctrl_sel_0} == 2'b10) |-> (data_out == data_in_2)
    );

// When select is 11, output equals data_in_3.
    check_sel_11_maps_in3: assert property (
        @(posedge CLK) ({ctrl_sel_1, ctrl_sel_0} == 2'b11) |-> (data_out == data_in_3)
    );

// Output equals the 4:1 mux function of select and inputs.
    check_functional_equivalence: assert property (
        @(posedge CLK) data_out == (ctrl_sel_1
                                    ? (ctrl_sel_0 ? data_in_3 : data_in_2)
                                    : (ctrl_sel_0 ? data_in_1 : data_in_0))
    );

// On A rising, Y matches the mux equation.
    equation_hold_on_A_rise: assert property (
        @(posedge A) Y == ((!S && A) | (S && B))
    );

// On A falling, Y matches the mux equation.
    equation_hold_on_A_fall: assert property (
        @(negedge A) Y == ((!S && A) | (S && B))
    );

// On B rising, Y matches the mux equation.
    equation_hold_on_B_rise: assert property (
        @(posedge B) Y == ((!S && A) | (S && B))
    );

// On B falling, Y matches the mux equation.
    equation_hold_on_B_fall: assert property (
        @(negedge B) Y == ((!S && A) | (S && B))
    );

// When S=0 and A rises, Y follows A.
    y_follows_A_when_S0_rise: assert property (
        @(posedge A) (!S) |-> (Y == A)
    );

// When S=0 and A falls, Y follows A.
    y_follows_A_when_S0_fall: assert property (
        @(negedge A) (!S) |-> (Y == A)
    );

// When S=1 and B rises, Y follows B.
    y_follows_B_when_S1_rise: assert property (
        @(posedge B) (S) |-> (Y == B)
    );

// When S=1 and B falls, Y follows B.
    y_follows_B_when_S1_fall: assert property (
        @(negedge B) (S) |-> (Y == B)
    );

///// Reset behavior /////
    // After any cycle with rst HIGH, outputs are zero in the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (out_receive == '0) && (out_send == '0)
    );

// While rst is held HIGH across consecutive cycles, outputs are zero.
    reset_held_forces_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (out_receive == '0) && (out_send == '0)
    );

// While rst is held HIGH across consecutive cycles, outputs do not change.
    reset_held_outputs_stable: assert property (
        @(posedge clk) ($past(rst) && rst) |-> $stable(out_receive) && $stable(out_send)
    );

// On the first cycle after rst was HIGH (deassertion at this clock), outputs are still zero this cycle.
    deassertion_cycle_outputs_zero: assert property (
        @(posedge clk) ($past(rst) && !rst) |-> (out_receive == '0) && (out_send == '0)
    );

// A rising edge of rst leads to zeroed outputs by the next cycle.
    rise_reset_zero_next: assert property (
        @(posedge clk) $rose(rst) |=> (out_receive == '0) && (out_send == '0)
    );

// Adding bitwise complement with cin==0 yields 0xF and no carry.
    check_complement_no_cin: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((B == ~A) && (cin == 1'b0)) |-> ((sum == 4'hF) && (cout == 1'b0))
    );

// Adding bitwise complement with cin==1 yields 0x0 and carry.
    check_complement_with_cin: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((B == ~A) && (cin == 1'b1)) |-> ((sum == 4'h0) && (cout == 1'b1))
    );

// out_and equals the AND of all six pairwise input ANDs.
    check_out_and_matches_impl: assert property (
        @(posedge clk) out_and == ((in[0] & in[1]) & (in[0] & in[2]) & (in[0] & in[3]) & (in[1] & in[2]) & (in[1] & in[3]) & (in[2] & in[3]))
    );

// out_or equals the OR of or1..or4 expression.
    check_out_or_matches_impl: assert property (
        @(posedge clk) out_or == (((in[0] | in[1]) | (in[0] | in[2])) | ((in[0] | in[3]) | (in[1] | in[2] | in[3])))
    );

// out_xor equals the XOR chain of the three pairwise XORs with in[0].
    check_out_xor_matches_impl: assert property (
        @(posedge clk) out_xor == (((in[0] ^ in[1]) ^ (in[0] ^ in[2])) ^ (in[0] ^ in[3]))
    );

// out_and equals reduction AND of all inputs.
    check_out_and_reduction: assert property (
        @(posedge clk) out_and == (&in)
    );

// out_or equals reduction OR of all inputs.
    check_out_or_reduction: assert property (
        @(posedge clk) out_or == (|in)
    );

// out_xor equals reduction XOR (parity) of all inputs.
    check_out_xor_reduction: assert property (
        @(posedge clk) out_xor == (^in)
    );

// Clock: clk; Reset: reset_n (active-low). Logic is combinational pass-through with out_valid masked when in_channel > 8'h0F.

    // in_ready is a direct pass-through of out_ready.
    check_in_ready_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (in_ready == out_ready)
    );

// out_data matches in_data every cycle.
    check_out_data_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (out_data == in_data)
    );

// out_startofpacket matches in_startofpacket every cycle.
    check_out_sop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (out_startofpacket == in_startofpacket)
    );

// out_endofpacket matches in_endofpacket every cycle.
    check_out_eop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (out_endofpacket == in_endofpacket)
    );

// out_valid is deasserted when in_channel > 8'h0F.
    check_valid_masked_when_channel_high: assert property (
        @(posedge clk) disable iff (!reset_n) (in_channel > 8'h0F) |-> (out_valid == 1'b0)
    );

// When in_channel <= 8'h0F, out_valid equals in_valid.
    check_valid_follows_input_when_channel_ok: assert property (
        @(posedge clk) disable iff (!reset_n) (in_channel <= 8'h0F) |-> (out_valid == in_valid)
    );

// out_valid implies in_valid is asserted.
    check_out_valid_implies_in_valid: assert property (
        @(posedge clk) disable iff (!reset_n) out_valid |-> in_valid
    );

// out_valid implies channel is within range (<= 8'h0F).
    check_out_valid_implies_channel_in_range: assert property (
        @(posedge clk) disable iff (!reset_n) out_valid |-> (in_channel <= 8'h0F)
    );

// If in_valid is low, out_valid must be low.
    check_in_valid_low_forces_out_valid_low: assert property (
        @(posedge clk) disable iff (!reset_n) (!in_valid) |-> (!out_valid)
    );

// If input is valid and output is dropped, the channel must be > 8'h0F.
    check_drop_only_due_to_channel: assert property (
        @(posedge clk) disable iff (!reset_n) (in_valid && !out_valid) |-> (in_channel > 8'h0F)
    );

// out_valid equals (in_valid && (in_channel <= 8'h0F)).
    check_valid_logic_equivalence: assert property (
        @(posedge clk) disable iff (!reset_n) out_valid == (in_valid && (in_channel <= 8'h0F))
    );

// X equals B1&C1&D1&(A1|A2) when A1 rises.
    check_eq_on_A1_posedge: assert property (
        @(posedge A1) X === (B1 & C1 & D1 & (A1 | A2))
    );

// X equals B1&C1&D1&(A1|A2) when A2 rises.
    check_eq_on_A2_posedge: assert property (
        @(posedge A2) X === (B1 & C1 & D1 & (A1 | A2))
    );

// X equals B1&C1&D1&(A1|A2) when B1 rises.
    check_eq_on_B1_posedge: assert property (
        @(posedge B1) X === (B1 & C1 & D1 & (A1 | A2))
    );

// X equals B1&C1&D1&(A1|A2) when C1 rises.
    check_eq_on_C1_posedge: assert property (
        @(posedge C1) X === (B1 & C1 & D1 & (A1 | A2))
    );

// X equals B1&C1&D1&(A1|A2) when D1 rises.
    check_eq_on_D1_posedge: assert property (
        @(posedge D1) X === (B1 & C1 & D1 & (A1 | A2))
    );

///// Functional correctness checks /////

    // Output equals selected input when sel[0] rises.
    check_out_matches_sel_on_sel0_posedge: assert property (
        @(posedge sel[0]) out == selected_input_value(sel, in0, in1, in2, in3)
    );

// Output equals selected input when sel[1] rises.
    check_out_matches_sel_on_sel1_posedge: assert property (
        @(posedge sel[1]) out == selected_input_value(sel, in0, in1, in2, in3)
    );

// Output equals selected input when in0 rises.
    check_out_matches_sel_on_in0_posedge: assert property (
        @(posedge in0) out == selected_input_value(sel, in0, in1, in2, in3)
    );

// Output equals selected input when in1 rises.
    check_out_matches_sel_on_in1_posedge: assert property (
        @(posedge in1) out == selected_input_value(sel, in0, in1, in2, in3)
    );

// Output equals selected input when in2 rises.
    check_out_matches_sel_on_in2_posedge: assert property (
        @(posedge in2) out == selected_input_value(sel, in0, in1, in2, in3)
    );

// Output equals selected input when in3 rises.
    check_out_matches_sel_on_in3_posedge: assert property (
        @(posedge in3) out == selected_input_value(sel, in0, in1, in2, in3)
    );

// When sel==00, out mirrors in0 on in0 rising edges.
    check_route_in0_when_sel00: assert property (
        @(posedge in0) (sel == 2'b00) |-> (out == in0)
    );

// When sel==01, out mirrors in1 on in1 rising edges.
    check_route_in1_when_sel01: assert property (
        @(posedge in1) (sel == 2'b01) |-> (out == in1)
    );

// When sel==10, out mirrors in2 on in2 rising edges.
    check_route_in2_when_sel10: assert property (
        @(posedge in2) (sel == 2'b10) |-> (out == in2)
    );

// When sel==11, out mirrors in3 on in3 rising edges.
    check_route_in3_when_sel11: assert property (
        @(posedge in3) (sel == 2'b11) |-> (out == in3)
    );

// When out rises, it equals the value of the currently selected input.
    check_out_posedge_matches_selected: assert property (
        @(posedge out) out == selected_input_value(sel, in0, in1, in2, in3)
    );

///// Combinational mapping checks /////
    // y[0] equals x[5].
    map_y0_from_x5: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[0] == x[5])
    );

// y[1] equals x[6].
    map_y1_from_x6: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[1] == x[6])
    );

// y[2] equals x[7].
    map_y2_from_x7: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[2] == x[7])
    );

// y[3] equals x[8].
    map_y3_from_x8: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[3] == x[8])
    );

// y[4] equals x[0] XOR x[5].
    map_y4_from_x0_x5: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[4] == (x[0] ^ x[5]))
    );

// y[5] equals x[1] XOR x[6].
    map_y5_from_x1_x6: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[5] == (x[1] ^ x[6]))
    );

// y[6] equals x[2] XOR x[7].
    map_y6_from_x2_x7: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[6] == (x[2] ^ x[7]))
    );

// y[7] equals x[3] XOR x[8].
    map_y7_from_x3_x8: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[7] == (x[3] ^ x[8]))
    );

// y[8] equals x[4].
    map_y8_from_x4: assert property (
        @(posedge CLK) disable iff (!RESETn) (y[8] == x[4])
    );

// Full vector mapping equals the RTL function.
    map_y_vector: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (y == { x[4], (x[3] ^ x[8]), (x[2] ^ x[7]), (x[1] ^ x[6]), (x[0] ^ x[5]), x[8], x[7], x[6], x[5] })
    );

///// Derived consistency checks /////
    // x[0] can be recovered as y[4] XOR y[0].
    recover_x0_via_y4_xor_y0: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[4] ^ y[0]) == x[0])
    );

// x[1] can be recovered as y[5] XOR y[1].
    recover_x1_via_y5_xor_y1: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[5] ^ y[1]) == x[1])
    );

// x[2] can be recovered as y[6] XOR y[2].
    recover_x2_via_y6_xor_y2: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[6] ^ y[2]) == x[2])
    );

// x[3] can be recovered as y[7] XOR y[3].
    recover_x3_via_y7_xor_y3: assert property (
        @(posedge CLK) disable iff (!RESETn) ((y[7] ^ y[3]) == x[3])
    );

// Sum[0] matches RTL expression A0 ^ B0 ^ Cin.
    check_sum0_matches_rtl: assert property (
        @(posedge CLK) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[1] matches RTL expression A1 ^ B1 ^ C0.
    check_sum1_matches_rtl: assert property (
        @(posedge CLK) Sum[1] == (A[1] ^ B[1] ^ c0_exp)
    );

// Sum[2] matches RTL expression A2 ^ B2 ^ C1.
    check_sum2_matches_rtl: assert property (
        @(posedge CLK) Sum[2] == (A[2] ^ B[2] ^ c1_exp)
    );

// Sum[3] matches RTL expression A3 ^ B3 ^ C2.
    check_sum3_matches_rtl: assert property (
        @(posedge CLK) Sum[3] == (A[3] ^ B[3] ^ c2_exp)
    );

// Cout matches RTL expression using A3, B3, and C2.
    check_cout_matches_rtl: assert property (
        @(posedge CLK) Cout == ((A[3] & B[3]) | (A[3] & c2_exp) | (B[3] & c2_exp))
    );

// Full 5-bit result equals A + B + Cin.
    check_full_result_adds: assert property (
        @(posedge CLK) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Outputs are known when inputs are known.
    check_known_propagation: assert property (
        @(posedge CLK) (!$isunknown({A, B, Cin})) |-> (!$isunknown({Sum, Cout}))
    );

// If B==0 and Cin==0 then Sum==A and Cout==0.
    check_identity_B_zero: assert property (
        @(posedge CLK) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == A) && (Cout == 1'b0))
    );

// If A==0 and Cin==0 then Sum==B and Cout==0.
    check_identity_A_zero: assert property (
        @(posedge CLK) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((Sum == B) && (Cout == 1'b0))
    );

// If B==4'hF and Cin==1 then {Cout,Sum} == {1,A}.
    check_full_carry_propagation: assert property (
        @(posedge CLK) ((B == 4'hF) && (Cin == 1'b1)) |-> ({Cout, Sum} == {1'b1, A})
    );

// Gray MSB equals binary MSB.
    check_gray_msb_copies_bin_msb: assert property (
        @(posedge CLK) gray[3] == bin[3]
    );

// Gray[2] equals bin[3] XOR bin[2].
    check_gray_bit2_xor: assert property (
        @(posedge CLK) gray[2] == (bin[3] ^ bin[2])
    );

// Gray[1] equals bin[2] XOR bin[1].
    check_gray_bit1_xor: assert property (
        @(posedge CLK) gray[1] == (bin[2] ^ bin[1])
    );

// Gray[0] equals bin[1] XOR bin[0].
    check_gray_bit0_xor: assert property (
        @(posedge CLK) gray[0] == (bin[1] ^ bin[0])
    );

// Binary bit2 reconstructs as gray[3] XOR gray[2].
    check_inverse_bin2_from_gray: assert property (
        @(posedge CLK) bin[2] == (gray[3] ^ gray[2])
    );

// Binary bit0 reconstructs as gray[3]^gray[2]^gray[1]^gray[0].
    check_inverse_bin0_from_gray: assert property (
        @(posedge CLK) bin[0] == (gray[3] ^ gray[2] ^ gray[1] ^ gray[0])
    );

// Clock: CLK (posedge). Reset: EN active-low, asynchronous.

    ///// Asynchronous reset behavior /////
    // When EN is LOW at a clock edge, output must be 0.
    reset_level_forces_zero: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (d_ff3_sign_out == 1'b0)
    );

// On a falling edge of EN between clocks, output must be 0 at the next clock.
    reset_fall_clears_output: assert property (
        @(posedge CLK) $fell(EN) |-> (d_ff3_sign_out == 1'b0)
    );

// Combinational RTL; no reset/clock in DUT; assertions are sampled on clk.

    // out1 equals (in1 & in2 & in3 & in4) | in5.
    check_out1_equation: assert property (
        @(posedge clk) out1 == ((in1 & in2 & in3 & in4) | in5)
    );

// in5 high forces out1 high.
    check_in5_forces_out1: assert property (
        @(posedge clk) in5 |-> out1
    );

// When in5 is low, out1 equals in1&in2&in3&in4.
    check_out1_when_in5_low: assert property (
        @(posedge clk) !in5 |-> (out1 == (in1 & in2 & in3 & in4))
    );

// All of in1..in4 high implies out1 high.
    check_all_in_high_implies_out1_high: assert property (
        @(posedge clk) (in1 & in2 & in3 & in4) |-> out1
    );

// With in5 low and any of in1..in4 low, out1 must be low.
    check_any_in_low_with_in5_low_implies_out1_low: assert property (
        @(posedge clk) (!in5 && !(in1 & in2 & in3 & in4)) |-> !out1
    );

// out1 low implies in5 is low and not(all of in1..in4 are high).
    check_out1_low_implies_inputs: assert property (
        @(posedge clk) !out1 |-> (!in5 && !(in1 & in2 & in3 & in4))
    );

// If out1 is high while in5 is low, then all of in1..in4 must be high.
    check_out1_high_with_in5_low_implies_all_in_high: assert property (
        @(posedge clk) (out1 && !in5) |-> (in1 && in2 && in3 && in4)
    );

// DEMUX is purely combinational with no reset; assertions are sampled on CLK.

    // For sel==2'b00, out == {in, 3'b000}.
    demux_map_sel00: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == {in, 3'b000})
    );

// For sel==2'b01, out == {3'b000, in}.
    demux_map_sel01: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == {3'b000, in})
    );

// For sel==2'b10, out == {2'b00, in, 1'b0}.
    demux_map_sel10: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == {2'b00, in, 1'b0})
    );

// For sel==2'b11, out == {1'b0, in, 2'b00}.
    demux_map_sel11: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == {1'b0, in, 2'b00})
    );

// Outputs are one-hot or all zero.
    demux_onehot_or_zero: assert property (
        @(posedge CLK) $onehot0(out)
    );

// When in is 0, all outputs are 0.
    demux_zero_when_in0: assert property (
        @(posedge CLK) (in == 1'b0) |-> (out == 4'b0000)
    );

// When in is 1, at least one output is 1.
    demux_nonzero_when_in1: assert property (
        @(posedge CLK) (in == 1'b1) |-> (out != 4'b0000)
    );

// OR-reduce of out equals in.
    demux_or_reduce_matches_in: assert property (
        @(posedge CLK) ((|out) == in)
    );

// out[3] can be 1 only when sel==2'b00 and in==1.
    demux_out3_only_when_sel00_in1: assert property (
        @(posedge CLK) (out[3] == 1'b1) |-> ((sel == 2'b00) && (in == 1'b1))
    );

// out[2] can be 1 only when sel==2'b11 and in==1.
    demux_out2_only_when_sel11_in1: assert property (
        @(posedge CLK) (out[2] == 1'b1) |-> ((sel == 2'b11) && (in == 1'b1))
    );

// out[1] can be 1 only when sel==2'b10 and in==1.
    demux_out1_only_when_sel10_in1: assert property (
        @(posedge CLK) (out[1] == 1'b1) |-> ((sel == 2'b10) && (in == 1'b1))
    );

// out[0] can be 1 only when sel==2'b01 and in==1.
    demux_out0_only_when_sel01_in1: assert property (
        @(posedge CLK) (out[0] == 1'b1) |-> ((sel == 2'b01) && (in == 1'b1))
    );

// Clock: clk (posedge). Reset: rst (active-high, synchronous). Logic: sequential counter with enable.

    // Reset sets count to 0 on the next clock.
    check_reset_sets_zero_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// While reset is held for 2+ cycles, count reads as 0 each cycle.
    check_reset_keeps_zero_while_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0)
    );

// When en is low and not in reset, count holds its value.
    check_hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst) (!en) |=> (count == $past(count))
    );

// When en is high and not in reset, count increments modulo 16.
    check_increment_mod16_when_en_high: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == (($past(count) + 4'd1) & 4'hF))
    );

// When prior-cycle inputs are known, result is known in this cycle.
    check_known_result_when_inputs_known: assert property (
        @(posedge clk)
            $past(1'b1) && !$isunknown({$past(select), $past(operand1), $past(operand2)}) |-> 
                !$isunknown(result)
    );

// Output equals input (combinational pass-through).
    check_output_equals_input: assert property (
        @(posedge clk) (twos_comp == signed_mag)
    );

// Sign bits match between input and output.
    check_sign_bit_match: assert property (
        @(posedge clk) (twos_comp[15] == signed_mag[15])
    );

// If input is non-negative, output equals input.
    check_nonneg_passthrough: assert property (
        @(posedge clk) (signed_mag >= 0) |-> (twos_comp == signed_mag)
    );

// If input is negative, output equals input.
    check_neg_passthrough: assert property (
        @(posedge clk) (signed_mag < 0) |-> (twos_comp == signed_mag)
    );

// Zero input passes through as zero.
    check_zero_passthrough: assert property (
        @(posedge clk) (signed_mag == 16'sd0) |-> (twos_comp == 16'sd0)
    );

// Minimum value (0x8000) passes through unchanged.
    check_min_int_passthrough: assert property (
        @(posedge clk) (signed_mag == 16'sh8000) |-> (twos_comp == 16'sh8000)
    );

// Maximum value (0x7FFF) passes through unchanged.
    check_max_int_passthrough: assert property (
        @(posedge clk) (signed_mag == 16'sh7FFF) |-> (twos_comp == 16'sh7FFF)
    );

// Output bits match input bits (bitwise equality).
    check_bitwise_equality: assert property (
        @(posedge clk) (twos_comp ^ signed_mag) == 16'sd0
    );

// When a is high, output is 00 regardless of others.
    check_a_selects_00: assert property (
        @(posedge CLK) a |-> (x == 1'b0) && (y == 1'b0)
    );

// When a is low and b is high, output is 10.
    check_b_selects_10: assert property (
        @(posedge CLK) (!a && b) |-> (x == 1'b1) && (y == 1'b0)
    );

// When a and b are low and c is high, output is 01.
    check_c_selects_01: assert property (
        @(posedge CLK) (!a && !b && c) |-> (x == 1'b0) && (y == 1'b1)
    );

// When a,b,c are low and d is high, output is 11.
    check_d_selects_11: assert property (
        @(posedge CLK) (!a && !b && !c && d) |-> (x == 1'b1) && (y == 1'b1)
    );

// When all inputs are low, output is 00.
    check_none_selects_00: assert property (
        @(posedge CLK) (!a && !b && !c && !d) |-> (x == 1'b0) && (y == 1'b0)
    );

// b has priority over c when a is low.
    check_b_overrides_c: assert property (
        @(posedge CLK) (!a && b && c) |-> (x == 1'b1) && (y == 1'b0)
    );

// c has priority over d when a and b are low.
    check_c_overrides_d: assert property (
        @(posedge CLK) (!a && !b && c && d) |-> (x == 1'b0) && (y == 1'b1)
    );

// x matches the RTL's LSB mapping.
    check_x_functional_equiv: assert property (
        @(posedge CLK) x == (a ? 1'b0 : b ? 1'b1 : c ? 1'b0 : d ? 1'b1 : 1'b0)
    );

// y matches the RTL's mapping.
    check_y_functional_equiv: assert property (
        @(posedge CLK) y == (a ? 1'b0 : b ? 1'b0 : c ? 1'b1 : d ? 1'b1 : 1'b0)
    );

// If y is 1, either c is selected or d is selected with higher-priority inputs low.
    check_y_one_implies_c_or_d: assert property (
        @(posedge CLK) y |-> ((!a && !b && c) || (!a && !b && !c && d))
    );

// Y reflects if any input is HIGH.
    check_y_is_or: assert property (
        @(posedge CLK) Y == (A || B || C || D)
    );

// Z reflects if any input is HIGH (priority mux of 1-bit inputs == OR).
    check_z_is_or: assert property (
        @(posedge CLK) Z == (A || B || C || D)
    );

// Y and Z are identical for all input combinations.
    check_y_equals_z: assert property (
        @(posedge CLK) Z == Y
    );

// If A is HIGH, X=0 and Y=Z=1 (A has highest priority).
    check_a_has_priority: assert property (
        @(posedge CLK) A |-> (X == 2'd0) && (Y == 1'b1) && (Z == 1'b1)
    );

// If A is LOW and B is HIGH, X=1 and Y=Z=1.
    check_b_selected_when_a0: assert property (
        @(posedge CLK) (!A && B) |-> (X == 2'd1) && (Y == 1'b1) && (Z == 1'b1)
    );

// If A,B are LOW and C is HIGH, X=2 and Y=Z=1.
    check_c_selected_when_ab0: assert property (
        @(posedge CLK) (!A && !B && C) |-> (X == 2'd2) && (Y == 1'b1) && (Z == 1'b1)
    );

// If A,B,C are LOW and D is HIGH, X=3 and Y=Z=1.
    check_d_selected_when_abc0: assert property (
        @(posedge CLK) (!A && !B && !C && D) |-> (X == 2'd3) && (Y == 1'b1) && (Z == 1'b1)
    );

// If all inputs are LOW, X=0 and Y=Z=0 (default case).
    check_default_when_none_high: assert property (
        @(posedge CLK) (!A && !B && !C && !D) |-> (X == 2'd0) && (Y == 1'b0) && (Z == 1'b0)
    );

// If Y=1 and X=0, then A must be HIGH.
    check_decode_unique_a: assert property (
        @(posedge CLK) (Y && (X == 2'd0)) |-> A
    );

// If Y=1 and X=1, then !A and B must be true.
    check_decode_unique_b: assert property (
        @(posedge CLK) (Y && (X == 2'd1)) |-> (!A && B)
    );

// If Y=1 and X=2, then !A,!B and C must be true.
    check_decode_unique_c: assert property (
        @(posedge CLK) (Y && (X == 2'd2)) |-> (!A && !B && C)
    );

// If Y=1 and X=3, then !A,!B,!C and D must be true.
    check_decode_unique_d: assert property (
        @(posedge CLK) (Y && (X == 2'd3)) |-> (!A && !B && !C && D)
    );

// If Y=0, then all inputs must be LOW.
    check_y_zero_means_no_inputs: assert property (
        @(posedge CLK) (!Y) |-> (!A && !B && !C && !D)
    );

// When A and any other input are HIGH, A's priority selects X=0 and Y=Z=1.
    check_overshadowing_when_a_and_others: assert property (
        @(posedge CLK) (A && (B || C || D)) |-> (X == 2'd0) && (Y == 1'b1) && (Z == 1'b1)
    );

// When A=0 and B with (C or D) are HIGH, B's priority selects X=1 and Y=Z=1.
    check_overshadowing_when_b_over_cd: assert property (
        @(posedge CLK) (!A && B && (C || D)) |-> (X == 2'd1) && (Y == 1'b1) && (Z == 1'b1)
    );

// When A=B=0 and C&D are HIGH, C's priority selects X=2 and Y=Z=1.
    check_overshadowing_when_c_over_d: assert property (
        @(posedge CLK) (!A && !B && C && D) |-> (X == 2'd2) && (Y == 1'b1) && (Z == 1'b1)
    );

// Clock: clk (posedge). Reset: in_rst_n active-LOW, asynchronous. Sequential two-flop reset synchronizer.

    // When input reset is asserted LOW, output reset must be LOW.
    check_reset_forces_out_low: assert property (
        @(posedge clk) !in_rst_n |-> (out_rst_n == 1'b0)
    );

// Output reset HIGH only when input reset is HIGH.
    check_out_high_requires_in_high: assert property (
        @(posedge clk) disable iff (!in_rst_n) out_rst_n |-> in_rst_n
    );

// On sampled falling edge of in_rst_n, out_rst_n is LOW in the same cycle.
    check_reset_fall_forces_out_low_now: assert property (
        @(posedge clk) $fell(in_rst_n) |-> (out_rst_n == 1'b0)
    );

// After a sampled falling edge of in_rst_n, out_rst_n remains LOW in the next cycle.
    check_reset_fall_keeps_out_low_next: assert property (
        @(posedge clk) $fell(in_rst_n) |-> ##1 (out_rst_n == 1'b0)
    );

// On sampled rising edge of in_rst_n, out_rst_n is still LOW in that cycle.
    check_out_low_on_reset_rise: assert property (
        @(posedge clk) $rose(in_rst_n) |-> (out_rst_n == 1'b0)
    );

// Rising edge of out_rst_n requires in_rst_n HIGH in both current and previous cycle.
    check_out_rise_requires_in_high_now_and_prev: assert property (
        @(posedge clk) disable iff (!in_rst_n) $rose(out_rst_n) |-> (in_rst_n && $past(in_rst_n))
    );

// No back-to-back rising edges on out_rst_n.
    check_no_back_to_back_out_rises: assert property (
        @(posedge clk) disable iff (!in_rst_n) $rose(out_rst_n) |-> ##1 (!$rose(out_rst_n))
    );

// If in_rst_n is LOW for two consecutive cycles, out_rst_n is LOW at the second cycle.
    check_persistent_reset_low_ensures_out_low: assert property (
        @(posedge clk) (!in_rst_n)[*2] |-> (out_rst_n == 1'b0)
    );

// Analysis: no clock/reset in RTL; pure combinational; out = (a & b & c) | c = c.

    // out must always equal c.
    check_out_equals_c: assert property (
        @(posedge clk) disable iff (1'b0) out == c
    );

// When c is 1, out must be 1.
    check_out_high_when_c_high: assert property (
        @(posedge clk) disable iff (1'b0) (c == 1'b1) |-> (out == 1'b1)
    );

// When c is 0, out must be 0.
    check_out_low_when_c_low: assert property (
        @(posedge clk) disable iff (1'b0) (c == 1'b0) |-> (out == 1'b0)
    );

// Output equals logical AND of inputs.
    check_and_equivalence: assert property (
        @(posedge clk) out == (a & b)
    );

// Truth table: 0 & 0 -> 0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out == 1'b0)
    );

// Truth table: 0 & 1 -> 0.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out == 1'b0)
    );

// Truth table: 1 & 0 -> 0.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out == 1'b0)
    );

// Truth table: 1 & 1 -> 1.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b1)
    );

// Output rising requires both inputs HIGH.
    check_out_rise_requires_inputs_high: assert property (
        @(posedge clk) $rose(out) |-> (a && b)
    );

// Output falling requires at least one input LOW.
    check_out_fall_requires_one_low: assert property (
        @(posedge clk) $fell(out) |-> (!a || !b)
    );

// A rising with B HIGH sets output HIGH.
    check_a_rise_with_b_high_sets_out: assert property (
        @(posedge clk) ($rose(a) && b) |-> (out == 1'b1)
    );

// B rising with A HIGH sets output HIGH.
    check_b_rise_with_a_high_sets_out: assert property (
        @(posedge clk) ($rose(b) && a) |-> (out == 1'b1)
    );

// A falling with B HIGH clears output LOW.
    check_a_fall_with_b_high_clears_out: assert property (
        @(posedge clk) ($fell(a) && b) |-> (out == 1'b0)
    );

// B falling with A HIGH clears output LOW.
    check_b_fall_with_a_high_clears_out: assert property (
        @(posedge clk) ($fell(b) && a) |-> (out == 1'b0)
    );

// In add mode, result equals A + 2*B (mod 16).
    check_add_mode_function: assert property (
        @(posedge CLK) disable iff (1'b0) (!subtract) |-> (result == ((A + B + B) & 4'hF))
    );

// In subtract mode, result equals A + 2*(~B+1) (mod 16).
    check_sub_mode_function: assert property (
        @(posedge CLK) disable iff (1'b0) (subtract) |-> (result == ((A + (~B + 4'd1) + (~B + 4'd1)) & 4'hF))
    );

// In subtract mode, adding 2*B back to result yields A (mod 16).
    check_sub_mode_invert_to_A: assert property (
        @(posedge CLK) disable iff (1'b0) (subtract) |-> (((result + (B << 1)) & 4'hF) == A)
    );

// In add mode, subtracting 2*B from result yields A (mod 16).
    check_add_mode_invert_to_A: assert property (
        @(posedge CLK) disable iff (1'b0) (!subtract) |-> (((result + ((~(B << 1)) + 4'd1)) & 4'hF) == A)
    );

// When B is zero, result passes A through regardless of subtract.
    check_B_zero_passthrough: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 4'd0) |-> (result == A)
    );

// In add mode with A=0, result equals (B << 1) (mod 16).
    check_add_mode_A_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (!subtract && (A == 4'd0)) |-> (result == ((B << 1) & 4'hF))
    );

// In subtract mode with A=0, result equals ((~B+1) << 1) (mod 16).
    check_sub_mode_A_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (subtract && (A == 4'd0)) |-> (result == (((~B + 4'd1) << 1) & 4'hF))
    );

// When B==8, doubling cancels (mod 16) so result equals A for either mode.
    check_B_eight_passthrough: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 4'h8) |-> (result == A)
    );

// In subtract mode with B==15, result equals A + 2 (mod 16).
    check_sub_mode_B_15: assert property (
        @(posedge CLK) disable iff (1'b0) (subtract && (B == 4'hF)) |-> (result == ((A + 4'd2) & 4'hF))
    );

// Clock: clk (posedge), Reset: rst active-low asynchronous, Sequential DFF with enable.

    // While reset is held LOW across consecutive cycles, q must be 0.
    check_q_zero_while_reset_low: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (q == 1'b0)
    );

// On reset deassertion (0->1), q is 0 at that clock edge.
    check_q_zero_on_reset_deassert: assert property (
        @(posedge clk) $rose(rst) |-> (q == 1'b0)
    );

// With enable LOW in the previous cycle and not in reset now, q holds or is 0 if an async reset occurred mid-cycle.
    check_hold_when_en_low_or_reset_midcycle: assert property (
        @(posedge clk) disable iff (!rst) !$past(en) |-> (q == $past(q) || q == 1'b0)
    );

// With enable HIGH in the previous cycle and not in reset now, q captures previous d or is 0 if an async reset occurred mid-cycle.
    check_capture_when_en_high_or_reset_midcycle: assert property (
        @(posedge clk) disable iff (!rst) $past(en) |-> (q == $past(d) || q == 1'b0)
    );

// Immediately after reset deassertion with enable HIGH, next cycle q equals this cycle's d if still out of reset.
    check_capture_after_reset_deassert_with_en: assert property (
        @(posedge clk) ($rose(rst) && en) |=> ( rst ? (q == $past(d)) : 1'b1 )
    );

// No clock or reset in DUT; purely combinational; assertions sample on input posedges.
    // Functional intent: Y = ~(A1 & A2) & ~(B1 & B2) & ~(C1 & C2).

    // Y implements the intended boolean function when A1 rises.
    func_equiv_on_A1_pos: assert property (
        @(posedge A1) Y == ((~(A1 & A2)) & (~(B1 & B2)) & (~(C1 & C2)))
    );

// Y implements the intended boolean function when A2 rises.
    func_equiv_on_A2_pos: assert property (
        @(posedge A2) Y == ((~(A1 & A2)) & (~(B1 & B2)) & (~(C1 & C2)))
    );

// Y implements the intended boolean function when B1 rises.
    func_equiv_on_B1_pos: assert property (
        @(posedge B1) Y == ((~(A1 & A2)) & (~(B1 & B2)) & (~(C1 & C2)))
    );

// Y implements the intended boolean function when B2 rises.
    func_equiv_on_B2_pos: assert property (
        @(posedge B2) Y == ((~(A1 & A2)) & (~(B1 & B2)) & (~(C1 & C2)))
    );

// Y implements the intended boolean function when C1 rises.
    func_equiv_on_C1_pos: assert property (
        @(posedge C1) Y == ((~(A1 & A2)) & (~(B1 & B2)) & (~(C1 & C2)))
    );

// Y implements the intended boolean function when C2 rises.
    func_equiv_on_C2_pos: assert property (
        @(posedge C2) Y == ((~(A1 & A2)) & (~(B1 & B2)) & (~(C1 & C2)))
    );

// If A1&A2 are both HIGH, Y must be LOW (sampled on A1 rise).
    pairA_high_forces_Y_low_A1: assert property (
        @(posedge A1) (A1 & A2) |-> (Y == 1'b0)
    );

// If B1&B2 are both HIGH, Y must be LOW (sampled on B1 rise).
    pairB_high_forces_Y_low_B1: assert property (
        @(posedge B1) (B1 & B2) |-> (Y == 1'b0)
    );

// If C1&C2 are both HIGH, Y must be LOW (sampled on C1 rise).
    pairC_high_forces_Y_low_C1: assert property (
        @(posedge C1) (C1 & C2) |-> (Y == 1'b0)
    );

// If Y is HIGH, no input pair can be simultaneously HIGH (sampled on Y rise).
    y_high_implies_no_pair_high: assert property (
        @(posedge Y) Y |-> (!(A1 & A2) && !(B1 & B2) && !(C1 & C2))
    );

// During load, outputs hold their previous values.
    hold_outputs_during_load: assert property (
        @(posedge clk) ($past(1'b1) && load) |=> (data_out == $past(data_out)) && (valid == $past(valid))
    );

// When !load and ctrl==10, next data_out equals data_in and valid is 1.
    compute_passthrough_data_in: assert property (
        @(posedge clk) (!load && (ctrl == 2'b10)) |=> ((data_out == $past(data_in)) && (valid == 1'b1))
    );

// When !load and ctrl==11, next data_out equals bitwise ~data_in and valid is 1.
    compute_invert_data_in: assert property (
        @(posedge clk) (!load && (ctrl == 2'b11)) |=> ((data_out == ~$past(data_in)) && (valid == 1'b1))
    );

// Any cycle with !load drives valid high on the next cycle.
    valid_high_on_operation: assert property (
        @(posedge clk) !load |=> (valid == 1'b1)
    );

// load followed by ctrl==00 yields data_out equal to the loaded reg value.
    load_then_ctrl00_uses_loaded_data: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b00))) |=> (data_out == $past(data_in, 2)) && (valid == 1'b1)
    );

// load followed by ctrl==01 yields data_out equal to ~loaded reg value.
    load_then_ctrl01_uses_inverted_loaded_data: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b01))) |=> (data_out == ~$past(data_in, 2)) && (valid == 1'b1)
    );

// load followed by ctrl==10 yields data_out equal to next-cycle data_in.
    load_then_ctrl10_uses_next_data_in: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b10))) |=> (data_out == $past(data_in, 1)) && (valid == 1'b1)
    );

// load followed by ctrl==11 yields data_out equal to ~next-cycle data_in.
    load_then_ctrl11_uses_inverted_next_data_in: assert property (
        @(posedge clk) (load ##1 (!load && (ctrl == 2'b11))) |=> (data_out == ~$past(data_in, 1)) && (valid == 1'b1)
    );

// Q updates with D on the next cycle when both enables are HIGH.
    update_on_enable: assert property (
        @(posedge clk) (en && enclk) |=> (q == $past(d))
    );

// Q holds its value on the next cycle when at least one enable is LOW.
    hold_when_not_both: assert property (
        @(posedge clk) !(en && enclk) |=> (q == $past(q))
    );

// If EN is LOW, Q must hold its previous value on the next cycle.
    hold_when_en_low: assert property (
        @(posedge clk) !en |=> (q == $past(q))
    );

// If ENCLK is LOW, Q must hold its previous value on the next cycle.
    hold_when_enclk_low: assert property (
        @(posedge clk) !enclk |=> (q == $past(q))
    );

// With both enables HIGH and D different from current Q, Q must change next cycle.
    enabled_and_data_diff_causes_change: assert property (
        @(posedge clk) (en && enclk && (d != q)) |=> (q != $past(q))
    );

// With both enables HIGH and D equal to current Q, Q must not change next cycle.
    enabled_and_data_equal_causes_no_change: assert property (
        @(posedge clk) (en && enclk && (d == q)) |=> (q == $past(q))
    );

// If data equals key this cycle, match will be 1 next cycle.
    check_next_match_set_on_equal: assert property (
        @(posedge clock) (data == key) |=> (match == 1'b1)
    );

// If data differs from key this cycle, match will be 0 next cycle.
    check_next_match_clear_on_notequal: assert property (
        @(posedge clock) (data != key) |=> (match == 1'b0)
    );

// Out equals in0 when sel==00.
    check_mux_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// Out equals in1 when sel==01.
    check_mux_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// Out equals in2 when sel==10.
    check_mux_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// Out equals in3 when sel==11.
    check_mux_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// Output never less than input
    check_out_ge_a: assert property (
        @(posedge clk) out >= a
    );

// For a == 0, out == 0
    check_out_zero_when_a_zero: assert property (
        @(posedge clk) (a == 4'd0) |-> (out == 6'd0)
    );

// For a == 1, out == 3
    check_out_three_when_a_one: assert property (
        @(posedge clk) (a == 4'd1) |-> (out == 6'd3)
    );

// LSB of out equals LSB of a (3 is odd)
    check_lsb_matches_a: assert property (
        @(posedge clk) out[0] == a[0]
    );

// When a[3]==0 (a<8), out equals 3*a without wrap
    check_low_range_exact: assert property (
        @(posedge clk) (!a[3]) |-> (out == (({2'b00, a} << 1) + {2'b00, a}))
    );

// When rst is HIGH, count is driven to 0.
    reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// While rst remains HIGH across cycles, count does not change.
    reset_holds_value_stable: assert property (
        @(posedge clk) ($past(rst) && rst) |-> $stable(count)
    );

///// Power gating on output /////
    // When VPWR is LOW, X must be LOW.
    check_x_low_when_vpwr_low: assert property (
        @(posedge VPB) (VPWR == 1'b0) |-> (X == 1'b0)
    );

///// Reset behavior /////
    // When rst is LOW at a clock edge, count must be 0 in the same cycle.
    check_reset_clears_now: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

// When rst is LOW at a clock edge, count must be 0 at the next clock edge.
    check_reset_clears_next: assert property (
        @(posedge clk) (rst == 1'b0) |=> (count == 4'b0000)
    );

// On a sampled rising edge of rst, count is 0 at that cycle.
    check_reset_release_sample_zero: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0000)
    );

///// Enable/Count behavior (active when rst is HIGH) /////
    // When enabled, count increments by 1 modulo 16 on the next cycle.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst == 1'b0) (en == 1'b1) |=> (count == ($past(count) + 4'h1))
    );

// When enabled, count must change on the next cycle.
    check_change_when_enabled: assert property (
        @(posedge clk) disable iff (rst == 1'b0) (en == 1'b1) |=> (count != $past(count))
    );

// When not enabled, count holds its value on the next cycle.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst == 1'b0) (en == 1'b0) |=> (count == $past(count))
    );

// When enabled at 0xF, the next value wraps to 0x0.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (rst == 1'b0) ((count == 4'hF) && (en == 1'b1)) |=> (count == 4'h0)
    );

// On synchronous reset, next cycle count must be 0.
    check_reset_next_zero: assert property (
        @(posedge clk) rst |-> ##1 (count == 16'd0)
    );

// Exact next-state function: next count = rst ? 0 : (prev==FFFF ? 0 : prev+1).
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |-> ##1 ( count == ( rst ? 16'd0 : ( ($past(count,1) == 16'hFFFF) ? 16'd0 : ($past(count,1) + 16'd1) ) ) )
    );

// If not in reset and previous count was not max, next must be previous+1.
    check_increment_when_no_reset: assert property (
        @(posedge clk) disable iff (rst) (!rst && ($past(count,1) != 16'hFFFF)) |-> ##1 (count == $past(count,1) + 16'd1)
    );

// tri_i_in drives one-hot bit (sel) with tri_i_out when sel<8.
    check_tri_i_in_sel_lt8: assert property (
        @(posedge CLK)
        (gpio_sel <= 4'h7) |-> (tri_i_in == ((8'b0000_0001 << gpio_sel) & {8{tri_i_out}}))
    );

// tri_i_in is zero when sel>=8.
    check_tri_i_in_sel_ge8_zero: assert property (
        @(posedge CLK)
        (gpio_sel >= 4'h8) |-> (tri_i_in == 8'h00)
    );

// scl_i_in equals tri_i_out when selected (sel==8).
    check_scl_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'h8) |-> (scl_i_in == tri_i_out)
    );

// sda_i_in equals tri_i_out when selected (sel==9).
    check_sda_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'h9) |-> (sda_i_in == tri_i_out)
    );

// spick_i_in equals tri_i_out when selected (sel==A).
    check_spick_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'hA) |-> (spick_i_in == tri_i_out)
    );

// miso_i_in equals tri_i_out when selected (sel==B).
    check_miso_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'hB) |-> (miso_i_in == tri_i_out)
    );

// mosi_i_in equals tri_i_out when selected (sel==C).
    check_mosi_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'hC) |-> (mosi_i_in == tri_i_out)
    );

// ss_i_in equals tri_i_out when selected (sel==D).
    check_ss_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'hD) |-> (ss_i_in == tri_i_out)
    );

// pwm_i_in equals tri_i_out when selected (sel==E).
    check_pwm_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'hE) |-> (pwm_i_in == tri_i_out)
    );

// cap0_i_in equals tri_i_out when selected (sel==F).
    check_cap0_i_in_select: assert property (
        @(posedge CLK)
        (gpio_sel == 4'hF) |-> (cap0_i_in == tri_i_out)
    );

// Demux outputs are exactly one-hot when tri_i_out==1.
    check_demux_onehot_when_1: assert property (
        @(posedge CLK)
        (tri_i_out == 1'b1) |-> $onehot({cap0_i_in, pwm_i_in, ss_i_in, mosi_i_in, miso_i_in, spick_i_in, sda_i_in, scl_i_in, tri_i_in})
    );

// Demux outputs are all zero when tri_i_out==0.
    check_demux_all_zero_when_0: assert property (
        @(posedge CLK)
        (tri_i_out == 1'b0) |-> ({cap0_i_in, pwm_i_in, ss_i_in, mosi_i_in, miso_i_in, spick_i_in, sda_i_in, scl_i_in, tri_i_in} == 16'h0000)
    );

// out1 equals AND of XNORs of in1 and in2
    check_out1_definition: assert property (
        @(posedge CLK) out1 == (&(~(in1 ^ in2)))
    );

// out2 equals out1 XOR in3[1]
    check_out2_definition: assert property (
        @(posedge CLK) out2 == (out1 ^ in3[1])
    );

// If LSBs differ, out1 must be 0
    check_out1_zero_if_bit0_diff: assert property (
        @(posedge CLK) (in1[0] ^ in2[0]) |-> (out1 == 1'b0)
    );

// If mid bits differ, out1 must be 0
    check_out1_zero_if_bit1_diff: assert property (
        @(posedge CLK) (in1[1] ^ in2[1]) |-> (out1 == 1'b0)
    );

// If MSBs differ, out1 must be 0
    check_out1_zero_if_bit2_diff: assert property (
        @(posedge CLK) (in1[2] ^ in2[2]) |-> (out1 == 1'b0)
    );

// If all bits match, out1 must be 1
    check_out1_one_if_all_equal: assert property (
        @(posedge CLK) (~(in1[0] ^ in2[0]) && ~(in1[1] ^ in2[1]) && ~(in1[2] ^ in2[2])) |-> (out1 == 1'b1)
    );

// When out1 is 0, out2 equals in3[1]
    check_out2_when_out1_zero: assert property (
        @(posedge CLK) (!out1) |-> (out2 == in3[1])
    );

// When out1 is 1, out2 equals NOT in3[1]
    check_out2_when_out1_one: assert property (
        @(posedge CLK) (out1) |-> (out2 == ~in3[1])
    );

// When CTRL is 0, OUT1 mirrors IN0.
    check_select_ctrl0_vector: assert property (
        @(posedge CLK) (CTRL == 1'b0) |-> (OUT1 == IN0)
    );

// When CTRL is 1, OUT1 mirrors IN1.
    check_select_ctrl1_vector: assert property (
        @(posedge CLK) (CTRL == 1'b1) |-> (OUT1 == IN1)
    );

// Rising CTRL selects IN1 immediately.
    check_ctrl_rise_selects_IN1: assert property (
        @(posedge CLK) $rose(CTRL) |-> (OUT1 == IN1)
    );

// Falling CTRL selects IN0 immediately.
    check_ctrl_fall_selects_IN0: assert property (
        @(posedge CLK) $fell(CTRL) |-> (OUT1 == IN0)
    );

// OUT1 always equals either IN0 or IN1.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) (OUT1 == IN0) || (OUT1 == IN1)
    );

// Boolean mux identity: OUT1 == (CTRL ? IN1 : IN0).
    check_mux_boolean_equivalence: assert property (
        @(posedge CLK) OUT1 == (({32{CTRL}} & IN1) | ({32{~CTRL}} & IN0))
    );

// If inputs are equal, OUT1 matches them.
    check_input_equality_passthrough: assert property (
        @(posedge CLK) (IN0 == IN1) |-> (OUT1 == IN0)
    );

// OR covers all 1s present in A.
  check_or_covers_A: assert property (
    @(posedge CLK) disable iff (!RESETn) ((~or_res & A) == '0)
  );

// RTL is purely combinational: ctrl=0 selects A, ctrl=1 selects D, otherwise out=0.

    // When ctrl==0, out equals A.
    check_ctrl0_selects_A: assert property (
        @(posedge CLK) (ctrl == 1'b0) |-> (out == A)
    );

// When ctrl==1, out equals D.
    check_ctrl1_selects_D: assert property (
        @(posedge CLK) (ctrl == 1'b1) |-> (out == D)
    );

// If ctrl is X/Z, out must be 0.
    check_default_zero_on_unknown_ctrl: assert property (
        @(posedge CLK) (ctrl !== 1'b0 && ctrl !== 1'b1) |-> (out == 8'h00)
    );

// On ctrl rising edge, out reflects D.
    check_out_on_ctrl_rise: assert property (
        @(posedge CLK) $rose(ctrl) |-> (out == D)
    );

// On ctrl falling edge, out reflects A.
    check_out_on_ctrl_fall: assert property (
        @(posedge CLK) $fell(ctrl) |-> (out == A)
    );

///// Functional equivalence sampled on input/supply edges /////
    // On A rising edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_posedge_A: assert property (
        @(posedge A) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On A falling edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_negedge_A: assert property (
        @(negedge A) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On B rising edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_posedge_B: assert property (
        @(posedge B) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On B falling edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_negedge_B: assert property (
        @(negedge B) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On C rising edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_posedge_C: assert property (
        @(posedge C) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On C falling edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_negedge_C: assert property (
        @(negedge C) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On VPWR rising edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_posedge_VPWR: assert property (
        @(posedge VPWR) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On VPWR falling edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_negedge_VPWR: assert property (
        @(negedge VPWR) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On VGND rising edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_posedge_VGND: assert property (
        @(posedge VGND) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On VGND falling edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_negedge_VGND: assert property (
        @(negedge VGND) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

///// Supply-specific simplifications /////
    // With VPWR=1 and VGND=0, X equals A&B&C.
    x_when_vpwr1_vgnd0: assert property (
        @(posedge A) ((VPWR == 1'b1) && (VGND == 1'b0)) |-> (X == (A & B & C))
    );

// With VPWR=0 and VGND=0, X equals ~(A&B&C).
    x_when_vpwr0_vgnd0: assert property (
        @(posedge A) ((VPWR == 1'b0) && (VGND == 1'b0)) |-> (X == ~(A & B & C))
    );

// If VGND != 0, X must be 0.
    vgnd_nonzero_forces_x0: assert property (
        @(posedge VGND) (VGND != 1'b0) |-> (X == 1'b0)
    );

// O updates to S-selected input with 1-cycle latency.
    check_mux_register_latency1: assert property (
        @(posedge clk) 1'b1 |=> (O == $past(S ? I1 : I0))
    );

// If S=0 at a rising edge, next cycle O equals prior I0.
    check_select0_path: assert property (
        @(posedge clk) (S == 1'b0) |=> (O == $past(I0))
    );

// If S=1 at a rising edge, next cycle O equals prior I1.
    check_select1_path: assert property (
        @(posedge clk) (S == 1'b1) |=> (O == $past(I1))
    );

// Next-cycle O must equal either prior I0 or prior I1.
    check_next_is_one_of_inputs: assert property (
        @(posedge clk) 1'b1 |=> ((O == $past(I0)) || (O == $past(I1)))
    );

// When inputs are equal at a rising edge, next-cycle O equals that value.
    check_inputs_equal_path: assert property (
        @(posedge clk) (I0 == I1) |=> (O == $past(I0))
    );

// in_ready is a combinational passthrough of out_ready
    check_in_ready_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) in_ready == out_ready
    );

// out_data is a combinational passthrough of in_data
    check_out_data_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_data == in_data
    );

// out_startofpacket is a combinational passthrough of in_startofpacket
    check_out_sop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_startofpacket == in_startofpacket
    );

// out_endofpacket is a combinational passthrough of in_endofpacket
    check_out_eop_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) out_endofpacket == in_endofpacket
    );

// When in_channel > 0, out_valid is forced LOW
    check_out_valid_block_when_channel_gt0: assert property (
        @(posedge clk) disable iff (!reset_n) (in_channel > 8'd0) |-> (out_valid == 1'b0)
    );

// When in_channel == 0, out_valid follows in_valid
    check_out_valid_follow_when_channel_0: assert property (
        @(posedge clk) disable iff (!reset_n) (in_channel == 8'd0) |-> (out_valid == in_valid)
    );

// If out_valid is HIGH, then in_channel must be 0 and in_valid must be HIGH
    check_out_valid_high_implies_inputs: assert property (
        @(posedge clk) disable iff (!reset_n) out_valid |-> ((in_channel == 8'd0) && (in_valid == 1'b1))
    );

// If in_channel == 0 and in_valid is HIGH, out_valid must be HIGH
    check_out_valid_high_when_allowed: assert property (
        @(posedge clk) disable iff (!reset_n) ((in_channel == 8'd0) && (in_valid == 1'b1)) |-> (out_valid == 1'b1)
    );

// If in_channel == 0 and in_valid is LOW, out_valid must be LOW
    check_out_valid_low_when_not_valid: assert property (
        @(posedge clk) disable iff (!reset_n) ((in_channel == 8'd0) && (in_valid == 1'b0)) |-> (out_valid == 1'b0)
    );

// X must be 1 if any input is 1.
    check_x_high_if_any_input_high: assert property (
        @(posedge clk) ((A===1'b1) || (B===1'b1) || (C===1'b1) || (D===1'b1)) |-> (X===1'b1)
    );

// X must be 0 if all inputs are 0.
    check_x_low_if_all_inputs_low: assert property (
        @(posedge clk) ((A===1'b0) && (B===1'b0) && (C===1'b0) && (D===1'b0)) |-> (X===1'b0)
    );

// When B,C,D are 0, X equals A.
    check_pass_A_when_others_low: assert property (
        @(posedge clk) ((B===1'b0) && (C===1'b0) && (D===1'b0)) |-> (X === A)
    );

// When A,C,D are 0, X equals B.
    check_pass_B_when_others_low: assert property (
        @(posedge clk) ((A===1'b0) && (C===1'b0) && (D===1'b0)) |-> (X === B)
    );

// When A,B,D are 0, X equals C.
    check_pass_C_when_others_low: assert property (
        @(posedge clk) ((A===1'b0) && (B===1'b0) && (D===1'b0)) |-> (X === C)
    );

// When A,B,C are 0, X equals D.
    check_pass_D_when_others_low: assert property (
        @(posedge clk) ((A===1'b0) && (B===1'b0) && (C===1'b0)) |-> (X === D)
    );

// A rising edge on X implies at least one input is 1 now.
    check_x_rise_requires_some_input_high: assert property (
        @(posedge clk) $rose(X) |-> ((A===1'b1) || (B===1'b1) || (C===1'b1) || (D===1'b1))
    );

// A falling edge on X implies all inputs are 0 now.
    check_x_fall_requires_all_inputs_low: assert property (
        @(posedge clk) $fell(X) |-> ((A===1'b0) && (B===1'b0) && (C===1'b0) && (D===1'b0))
    );

///// Reset behavior /////
  // While reset is asserted low, outputs are cleared.
  reset_outputs_cleared: assert property (
    @(posedge clk) !reset |-> (out == 2'b00) && (valid == 1'b0)
  );

///// Encoding from inputs (uses previous cycle inputs due to registered outputs) /////
  // If in[3] was 1, out must be 3 and valid 1.
  encode_in3_maps_to_3: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(in[3])) |-> (out == 2'b11) && (valid == 1'b1)
  );

// If in[2] was 1 and in[3] was 0, out must be 2 and valid 1.
  encode_in2_maps_to_2: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(in[3]) && $past(in[2])) |-> (out == 2'b10) && (valid == 1'b1)
  );

// If in[1] was 1 and in[3:2] were 0, out must be 1 and valid 1.
  encode_in1_maps_to_1: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(in[3]) && !$past(in[2]) && $past(in[1])) |-> (out == 2'b01) && (valid == 1'b1)
  );

// If only in[0] was 1 among higher bits 3:1=0, out must be 0 and valid 1.
  encode_in0_maps_to_0: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(in[3]) && !$past(in[2]) && !$past(in[1]) && $past(in[0])) |-> (out == 2'b00) && (valid == 1'b1)
  );

// If no inputs were 1, out must be 0 and valid 0.
  encode_none_maps_to_none: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && ($past(in) == 4'b0000)) |-> (out == 2'b00) && (valid == 1'b0)
  );

///// Valid flag semantics /////
  // valid equals OR-reduction of previous cycle inputs.
  valid_equals_or_prev_in: assert property (
    @(posedge clk) disable iff (!reset) $past(reset) |-> (valid == (|$past(in)))
  );

// When valid is 0, out must be 0.
  valid_zero_implies_out_zero: assert property (
    @(posedge clk) disable iff (!reset) (valid == 1'b0) |-> (out == 2'b00)
  );

///// Reverse mapping checks (outputs imply prior inputs) /////
  // out==3 implies prior in[3]==1.
  out3_implies_prev_in3: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b11)) |-> $past(in[3])
  );

// out==2 implies prior in[3]==0 and in[2]==1.
  out2_implies_prev_in2_only: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b10)) |-> (!$past(in[3]) && $past(in[2]))
  );

// out==1 implies prior in[3:2]==0 and in[1]==1.
  out1_implies_prev_in1_only: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b01)) |-> (!$past(in[3]) && !$past(in[2]) && $past(in[1]))
  );

// out==0 with valid==1 implies prior in[3:1]==0 and in[0]==1.
  out0_valid1_implies_prev_in0_only: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b00) && (valid == 1'b1)) |-> (!$past(in[3]) && !$past(in[2]) && !$past(in[1]) && $past(in[0]))
  );

// out==0 with valid==0 implies prior inputs were all zero.
  out0_valid0_implies_prev_none: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b00) && (valid == 1'b0)) |-> ($past(in) == 4'b0000)
  );

// If load is high, next-cycle sampled count equals that cycle's load_value.
    check_load_updates_count_next_cycle: assert property (
        @(posedge clk) load |=> (count == $past(load_value))
    );

// If load is low, next-cycle sampled count equals previous count + 1 (mod 16).
    check_increment_on_no_load: assert property (
        @(posedge clk) !load |=> (count == ($past(count) + 4'd1))
    );

// Next-cycle sampled count always equals either prior load_value or prior count + 1.
    check_next_count_comes_from_load_or_increment: assert property (
        @(posedge clk) 1'b1 |=> (count == ($past(load) ? $past(load_value) : ($past(count) + 4'd1)))
    );

// With no load and count at max, next-cycle sampled count wraps to 0.
    check_wrap_from_max_on_increment: assert property (
        @(posedge clk) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// With no load and count at 0, next-cycle sampled count becomes 1.
    check_increment_from_zero: assert property (
        @(posedge clk) (!load && (count == 4'h0)) |=> (count == 4'h1)
    );

// If load assigns the same value as current count, next-cycle sampled count holds.
    check_stable_when_load_assigns_same: assert property (
        @(posedge clk) (load && (load_value == count)) |=> (count == $past(count))
    );

// Two consecutive cycles of no load advance count by two.
    check_two_cycle_increment_when_no_load: assert property (
        @(posedge clk) (!load ##1 !load) |=> (count == ($past(count, 2) + 4'd2))
    );

// Three consecutive cycles of no load advance count by three.
    check_three_cycle_increment_when_no_load: assert property (
        @(posedge clk) (!load ##1 !load ##1 !load) |=> (count == ($past(count, 3) + 4'd3))
    );

// A load followed by no-load causes one increment from the loaded value.
    check_load_then_no_load_results_in_loaded_plus_one: assert property (
        @(posedge clk) (load ##1 !load) |=> (count == ($past(load_value, 2) + 4'd1))
    );

// Two consecutive loads make the next-cycle sampled count equal the second load_value.
    check_two_consecutive_loads_results_in_second_value: assert property (
        @(posedge clk) (load ##1 load) |=> (count == $past(load_value))
    );

// When signs match, Z's sign equals the inputs' sign.
    check_eqsign_signbit: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] == b[31]) |-> (Z[31] == a[31])
    );

///// Different-sign path /////
    // When signs differ, overflow is always zero.
    check_diffsign_ovf_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31]) |-> (ovf == 1'b0)
    );

// When signs differ, Z's magnitude is the absolute difference of magnitudes.
    check_diffsign_absdiff: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31]) |-> (Z[30:0] == absdiff31(a[30:0], b[30:0]))
    );

// When signs differ and magnitudes are equal, result is exactly zero.
    check_diffsign_equal_mags_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31] && a[30:0] == b[30:0]) |-> (Z == 32'd0)
    );

// When signs differ and |a| > |b|, Z's sign equals a's sign.
    check_diffsign_sign_from_a: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31] && a[30:0] > b[30:0]) |-> (Z[31] == a[31])
    );

// When signs differ and |b| > |a|, Z's sign equals b's sign.
    check_diffsign_sign_from_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31] && b[30:0] > a[30:0]) |-> (Z[31] == b[31])
    );

///// General consistency /////
    // ovf can only be high when input signs match.
    check_ovf_only_on_eqsign: assert property (
        @(posedge CLK) disable iff (1'b0) ovf |-> (a[31] == b[31])
    );

///// Reset behavior /////
    // While reset is LOW, count must be 0.
    check_count_zero_while_reset_low: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 4'd0)
    );

// If reset stays LOW across consecutive clocks, count remains 0.
    check_count_zero_on_consecutive_reset_low: assert property (
        @(posedge clk) ($past(reset) == 1'b0 && reset == 1'b0) |-> (count == 4'd0)
    );

// On reset deassertion (0->1) at a clock edge, count becomes 1.
    check_count_one_on_reset_rise: assert property (
        @(posedge clk) $rose(reset) |-> (count == 4'd1)
    );

// On reset deassertion (0->1), the previous sampled count was 0.
    check_past_count_zero_on_reset_rise: assert property (
        @(posedge clk) $rose(reset) |-> ($past(count) == 4'd0)
    );

///// General invariants /////
    // Count value remains within 4-bit range during normal operation.
    check_count_range_when_not_in_reset: assert property (
        @(posedge clk) disable iff (!reset) (count inside {[4'd0:4'd15]})
    );

// If a > b, drive result=a and select=00.
    check_a_gt_b_drives_a_and_sel00: assert property (
        @(posedge CLK) (a > b) |-> (comparison_result == a) && (input_selected == 2'b00)
    );

// If b > a, drive result=b and select=01.
    check_b_gt_a_drives_b_and_sel01: assert property (
        @(posedge CLK) (b > a) |-> (comparison_result == b) && (input_selected == 2'b01)
    );

// If a == b, drive result=a and pass through select.
    check_equal_drives_a_and_sel_passthrough: assert property (
        @(posedge CLK) (a == b) |-> (comparison_result == a) && (input_selected == select)
    );

// Result is always either a or b.
    check_result_is_either_a_or_b: assert property (
        @(posedge CLK) (comparison_result == a) || (comparison_result == b)
    );

// MSB of input_selected is 1 only when a == b (values 2 or 3 only on equality).
    check_sel_msb_one_only_when_equal: assert property (
        @(posedge CLK) (input_selected[1] == 1'b1) |-> (a == b)
    );

// When a != b, MSB of input_selected must be 0 (only 00 or 01 allowed).
    check_not_equal_forces_sel_msb_zero: assert property (
        @(posedge CLK) (a != b) |-> (input_selected[1] == 1'b0)
    );

// If result==a, then a >= b.
    check_result_a_implies_a_ge_b: assert property (
        @(posedge CLK) (comparison_result == a) |-> (a >= b)
    );

///// Multiplexer (outv/o2/o1/o0) /////
    // outv must be three copies of (vec[2] | vec[1] | vec[0]).
    check_outv_replication: assert property (
        @(posedge clk) outv == {3{|vec}}
    );

// o2 equals outv[2].
    check_o2_matches_outv2: assert property (
        @(posedge clk) o2 == outv[2]
    );

// o1 equals outv[1].
    check_o1_matches_outv1: assert property (
        @(posedge clk) o1 == outv[1]
    );

// o0 equals outv[0].
    check_o0_matches_outv0: assert property (
        @(posedge clk) o0 == outv[0]
    );

// If all vec bits are 0 then outv is 3'b000.
    check_outv_all_zero_when_vec_zero: assert property (
        @(posedge clk) (~|vec) |-> (outv == 3'b000)
    );

// If any vec bit is 1 then outv is 3'b111.
    check_outv_all_one_when_any_vec_high: assert property (
        @(posedge clk) (|vec) |-> (outv == 3'b111)
    );

///// Minimum-of-four (min) /////
    // min is less than or equal to a.
    check_min_le_a: assert property (
        @(posedge clk) min <= a
    );

// min is less than or equal to b.
    check_min_le_b: assert property (
        @(posedge clk) min <= b
    );

// min is less than or equal to c.
    check_min_le_c: assert property (
        @(posedge clk) min <= c
    );

// min is less than or equal to d.
    check_min_le_d: assert property (
        @(posedge clk) min <= d
    );

// min equals one of the inputs a/b/c/d.
    check_min_is_input: assert property (
        @(posedge clk) (min == a) || (min == b) || (min == c) || (min == d)
    );

// If a is strictly less than b,c,d then min equals a.
    check_unique_min_a: assert property (
        @(posedge clk) (a < b) && (a < c) && (a < d) |-> (min == a)
    );

// If b is strictly less than a,c,d then min equals b.
    check_unique_min_b: assert property (
        @(posedge clk) (b < a) && (b < c) && (b < d) |-> (min == b)
    );

// If c is strictly less than a,b,d then min equals c.
    check_unique_min_c: assert property (
        @(posedge clk) (c < a) && (c < b) && (c < d) |-> (min == c)
    );

// If d is strictly less than a,b,c then min equals d.
    check_unique_min_d: assert property (
        @(posedge clk) (d < a) && (d < b) && (d < c) |-> (min == d)
    );

// min matches the exact pairwise comparator/mux structure.
    check_min_structural_equivalence: assert property (
        @(posedge clk)
            min == ( (((a < b) ? a : b) < ((c < d) ? c : d))
                     ? ((a < b) ? a : b)
                     : ((c < d) ? c : d) )
    );

///// Reset behavior /////
    // If reset was LOW in the previous cycle, OutputData must be 0 now.
    reset_prev_low_forces_zero_now: assert property (
        @(posedge OutputClock) $past(!reset_b) |-> (OutputData == 1'b0)
    );

// If reset is LOW now, OutputData will be 0 on the next cycle.
    reset_low_forces_zero_next: assert property (
        @(posedge OutputClock) (!reset_b) |=> (OutputData == 1'b0)
    );

// On the cycle reset_b rises, OutputData is 0.
    reset_release_cycle_zero: assert property (
        @(posedge OutputClock) $rose(reset_b) |-> (OutputData == 1'b0)
    );

// While reset is held LOW across consecutive cycles, OutputData stays 0.
    reset_held_low_keeps_zero: assert property (
        @(posedge OutputClock) (!reset_b && $past(!reset_b)) |-> (OutputData == 1'b0)
    );

///// Active behavior /////
    // When not in reset and the previous cycle was also not in reset, OutputData is either 0 (due to any async reset between clocks) or equals the previous InputData.
    active_out_is_zero_or_prev_in: assert property (
        @(posedge OutputClock) disable iff (!reset_b)
            $past(reset_b) |-> ((OutputData == 1'b0) || (OutputData == $past(InputData)))
    );

// After a reset release, if reset remains HIGH next cycle, OutputData captures InputData from the release cycle.
    capture_after_reset_release: assert property (
        @(posedge OutputClock) $rose(reset_b) |-> ##1 (!reset_b || (OutputData == $past(InputData)))
    );

// Analysis: no clock/reset in RTL; purely combinational always @(*).
    // Behavior: xor_out = XOR of data_in[7:0]; parity = xor_out when sel_b1==0, else ~xor_out.

    // When sel_b1==0, parity equals XOR of data_in bits.
    check_parity_sel0: assert property (
        @(posedge CLK) (!sel_b1) |-> (parity == ^data_in)
    );

// When sel_b1==1, parity equals inverted XOR of data_in bits.
    check_parity_sel1: assert property (
        @(posedge CLK) (sel_b1) |-> (parity == ~(^data_in))
    );

// Parity matches the Boolean equation parity == (^data_in) ^ sel_b1.
    check_parity_equation: assert property (
        @(posedge CLK) 1'b1 |-> (parity == ((^data_in) ^ sel_b1))
    );

// If XOR of data_in is 0, parity equals sel_b1.
    check_xor_zero_parity_equals_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b0) |-> (parity == sel_b1)
    );

// If XOR of data_in is 1, parity equals inverse of sel_b1.
    check_xor_one_parity_equals_not_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b1) |-> (parity == ~sel_b1)
    );

// If all bits of B are 1, X equals ~A.
    check_all_B_ones_implies_X_eq_notA: assert property (
        @(posedge CLK) (B == 8'hFF) |-> (X == (~A))
    );

// If C equals ~A, X equals ~A regardless of B.
    check_when_C_equals_notA_then_X_eq_notA: assert property (
        @(posedge CLK) (C == (~A)) |-> (X == (~A))
    );

// If B equals ~C, X equals ~(A & B).
    check_when_B_equals_notC_then_X_eq_not_AandB: assert property (
        @(posedge CLK) (B == (~C)) |-> (X == (~(A & B)))
    );

///// Bitwise mapping /////
    // MSB maps directly: gray[3] == binary[3].
    check_map_bit3: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] == binary[3]
    );

// gray[2] == binary[3] ^ binary[2].
    check_map_bit2: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] == (binary[3] ^ binary[2])
    );

// gray[1] == binary[2] ^ binary[1].
    check_map_bit1: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] == (binary[2] ^ binary[1])
    );

// gray[0] == binary[1] ^ binary[0].
    check_map_bit0: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] == (binary[1] ^ binary[0])
    );

///// Vector mapping equivalence /////
    // gray == binary XOR (binary >> 1).
    check_map_vector: assert property (
        @(posedge clk) disable iff (1'b0) gray == (binary ^ {1'b0, binary[3:1]})
    );

///// Inverse relations derived from mapping /////
    // Recover binary[2] from gray: binary[2] == gray[2] ^ gray[3].
    check_inverse_b2: assert property (
        @(posedge clk) disable iff (1'b0) binary[2] == (gray[2] ^ gray[3])
    );

// Recover binary[1] from gray: binary[1] == gray[1] ^ gray[2] ^ gray[3].
    check_inverse_b1: assert property (
        @(posedge clk) disable iff (1'b0) binary[1] == (gray[1] ^ gray[2] ^ gray[3])
    );

// Recover binary[0] from gray: binary[0] == gray[0] ^ gray[1] ^ gray[2] ^ gray[3].
    check_inverse_b0: assert property (
        @(posedge clk) disable iff (1'b0) binary[0] == (gray[0] ^ gray[1] ^ gray[2] ^ gray[3])
    );

///// Additional consistency checks /////
    // Parity of gray equals LSB of binary.
    check_parity_relation: assert property (
        @(posedge clk) disable iff (1'b0) (^gray) == binary[0]
    );

// Upper pair mapping consistency: {gray[3],gray[2]}.
    check_upper_pair_map: assert property (
        @(posedge clk) disable iff (1'b0) {gray[3], gray[2]} == {binary[3], (binary[3] ^ binary[2])}
    );

// out equals the canonical 4:1 mux function of sel and inputs.
    check_mux_function: assert property (
        @(posedge CLK) out == (sel[1] ? (sel[0] ? in3 : in2) : (sel[0] ? in1 : in0))
    );

// When sel==00, out must equal in0.
    check_sel00_maps_in0: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == in0)
    );

// When sel==01, out must equal in1.
    check_sel01_maps_in1: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == in1)
    );

// When sel==10, out must equal in2.
    check_sel10_maps_in2: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == in2)
    );

// When sel==11, out must equal in3.
    check_sel11_maps_in3: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == in3)
    );

// MSB of sel selects between lower pair (in0/in1) when 0.
    check_group_select_low: assert property (
        @(posedge CLK) (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

// MSB of sel selects between upper pair (in2/in3) when 1.
    check_group_select_high: assert property (
        @(posedge CLK) (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

// Isolation: with sel==10 stable, changes on in0/in1/in3 do not affect out.
    check_isolation_sel10: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b10 && sel == 2'b10 && in2 == $past(in2) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

// Isolation: with sel==11 stable, changes on in0/in1/in2 do not affect out.
    check_isolation_sel11: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b11 && sel == 2'b11 && in3 == $past(in3) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in2 != $past(in2))))
        |-> (out == $past(out))
    );

// Out matches truth table at sel[0] rising edges.
    check_truth_table_on_sel0: assert property (
        @(posedge sel[0]) out == ((sel == 2'b00) ? data_in[0] :
                                   (sel == 2'b01) ? data_in[3] :
                                   1'b0)
    );

// Out matches truth table at sel[1] rising edges.
    check_truth_table_on_sel1: assert property (
        @(posedge sel[1]) out == ((sel == 2'b00) ? data_in[0] :
                                   (sel == 2'b01) ? data_in[3] :
                                   1'b0)
    );

// When sel==00, out equals data_in[0] at data_in[0] edges.
    check_sel00_data0_drives_out: assert property (
        @(posedge data_in[0]) (sel == 2'b00) |-> (out == data_in[0])
    );

// When sel==01, out equals data_in[3] at data_in[3] edges.
    check_sel01_data3_drives_out: assert property (
        @(posedge data_in[3]) (sel == 2'b01) |-> (out == data_in[3])
    );

// Reset drives reg_0x23 to 8'h00 on the next clock.
    check_reset_clears_reg_next: assert property (
        @(posedge clk) reset |-> (reg_0x23 == 8'h00)
    );

// Reset dominates write: if reset is asserted, next value is 0 regardless of wenb.
    check_reset_dominates_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |-> (reg_0x23 == 8'h00)
    );

// Clock: clk (posedge). Reset: reset (active-high, async in RTL). Logic: sequential 3-stage pipeline (stage1_out<=a|b, stage2_out<=stage1_out, out<=stage2_out).

    // On any clock where reset is HIGH, all pipeline registers are 0.
    check_reset_clears_pipeline: assert property (
        @(posedge clk) reset |-> (stage1_out == 1'b0) && (stage2_out == 1'b0) && (out == 1'b0)
    );

// When not in scan, reset high clears q to zero on next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (q == {SIZE{1'b0}})
    );

// When not in scan, reset high drives so to zero on next cycle (since so=q).
    check_reset_clears_so: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (so == {SIZE{1'b0}})
    );

// Sum equals 8-bit addition of a and b (modulo 256).
    check_sum_is_add: assert property (
        @(posedge CLK) sum == (a + b)
    );

// If a is zero, sum equals b.
    check_zero_a_identity: assert property (
        @(posedge CLK) (a == 8'h00) |-> (sum == b)
    );

// If b is zero, sum equals a.
    check_zero_b_identity: assert property (
        @(posedge CLK) (b == 8'h00) |-> (sum == a)
    );

// Subtracting b from sum recovers a (modulo 256).
    check_subtract_recovers_a: assert property (
        @(posedge CLK) (sum - b) == a
    );

// Subtracting a from sum recovers b (modulo 256).
    check_subtract_recovers_b: assert property (
        @(posedge CLK) (sum - a) == b
    );

// Specific wrap-around example: 0xFF + 0x01 -> 0x00.
    check_wrap_example_ff_plus_01: assert property (
        @(posedge CLK) ((a == 8'hFF) && (b == 8'h01)) |-> (sum == 8'h00)
    );

// X matches the RTL combinational expression.
    check_x_matches_rtl_expr: assert property (
        @(posedge CLK) X == (SLEEP ? (((A & SLEEP) & (~SLEEP)) | (A & SLEEP)) : A)
    );

// X equals A for all cycles.
    check_x_equals_a: assert property (
        @(posedge CLK) X == A
    );

// When SLEEP is 0, X equals A.
    check_sleep0_passthrough: assert property (
        @(posedge CLK) (SLEEP == 1'b0) |-> (X == A)
    );

// When SLEEP is 1, X equals A.
    check_sleep1_passthrough: assert property (
        @(posedge CLK) (SLEEP == 1'b1) |-> (X == A)
    );

// The term (A & SLEEP) & (~SLEEP) is zero when SLEEP is 1.
    check_and_term_zero_on_sleep1: assert property (
        @(posedge CLK) (SLEEP == 1'b1) |-> (((A & SLEEP) & (~SLEEP)) == 1'b0)
    );

// Clock: clk (posedge). Reset: reset (active-high synchronous).
    // Sequential: registers internal_state and data_out update on posedge clk.
    // Function: reset clears regs; key==0 -> data_out=data_in, hold internal_state; else -> internal_state=data_in^key, data_out=$past(internal_state)^key.

    // On reset, both internal_state and data_out are driven to 0.
    reset_clears_regs: assert property (
        @(posedge clk) reset |-> (internal_state == 32'h0) && (data_out == 32'h0)
    );

///// Counter behavior on v4642b6 clock /////
    // Counter increments by 1 on each rising edge of v4642b6 (checked between consecutive edges).
    check_counter_increments: assert property (
        @(posedge v4642b6) 1'b1 |=> (v817794 == $past(v817794) + 4'd1)
    );

// If counter is 15 on one edge, it wraps to 0 on the next edge.
    check_counter_wrap: assert property (
        @(posedge v4642b6) (v817794 == 4'hF) |=> (v817794 == 4'h0)
    );

///// Combinational select logic for v4642b6 /////
    // When sel=0000, v4642b6 equals v24708e[0].
    check_sel_0000: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0000) |-> (v4642b6 == v24708e[0])
    );

// When sel=0001, v4642b6 equals v24708e[1].
    check_sel_0001: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0001) |-> (v4642b6 == v24708e[1])
    );

// When sel=0010, v4642b6 equals v24708e[2].
    check_sel_0010: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0010) |-> (v4642b6 == v24708e[2])
    );

// When sel=0011, v4642b6 equals v24708e[3].
    check_sel_0011: assert property (
        @(posedge v4642b6) (v0550b6 == 4'b0011) |-> (v4642b6 == v24708e[3])
    );

// RTL has no reset; assertions are not reset-disabled.
    // Combinational behavior: if (A>B) result=A<<shift_amount; else if (A<B) result=B>>shift_amount; else result=A.

    // If A > B, result equals A shifted left by shift_amount.
    check_left_shift_when_A_gt_B: assert property (
        @(posedge CLK) (A > B) |-> (result == (A << shift_amount))
    );

// If A < B, result equals B shifted right by shift_amount.
    check_right_shift_when_A_lt_B: assert property (
        @(posedge CLK) (A < B) |-> (result == (B >> shift_amount))
    );

// If A == B, result equals A.
    check_passthrough_when_A_eq_B: assert property (
        @(posedge CLK) (A == B) |-> (result == A)
    );

// If shift_amount is 0 and A > B, result equals A (no left shift effect).
    check_no_shift_behavior_left: assert property (
        @(posedge CLK) ((A > B) && (shift_amount == 4'd0)) |-> (result == A)
    );

// If shift_amount is 0 and A < B, result equals B (no right shift effect).
    check_no_shift_behavior_right: assert property (
        @(posedge CLK) ((A < B) && (shift_amount == 4'd0)) |-> (result == B)
    );

// For left shift by >=1 (A > B), LSB of result is 0.
    check_lsb_zero_after_left_shift: assert property (
        @(posedge CLK) ((A > B) && (shift_amount != 4'd0)) |-> (result[0] == 1'b0)
    );

// For right shift by >=1 (A < B), MSB of result is 0.
    check_msb_zero_after_right_shift: assert property (
        @(posedge CLK) ((A < B) && (shift_amount != 4'd0)) |-> (result[15] == 1'b0)
    );

// Left shift by 15 when A > B produces {A[0], 15'b0}.
    check_left_shift_by_15: assert property (
        @(posedge CLK) ((A > B) && (shift_amount == 4'd15)) |-> (result == {A[0], 15'b0})
    );

// Right shift by 15 when A < B produces {15'b0, B[15]}.
    check_right_shift_by_15: assert property (
        @(posedge CLK) ((A < B) && (shift_amount == 4'd15)) |-> (result == {15'b0, B[15]})
    );

// For right shift case, result is less than or equal to B (unsigned).
    check_right_shift_monotonic: assert property (
        @(posedge CLK) (A < B) |-> (result <= B)
    );

// No clock/reset in RTL; combinational logic. Sample assertions on posedge of input3.

    // Output must equal the RTL's priority function.
    check_output1_function_equivalence: assert property (
        @(posedge input3)
            output1 == (
                ((input1 >= 4'b0110) && (input2 == 2'b10)) ||
                ( !((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                  !(input3 && !input4) &&
                  (input5 && input6 && input7 && input8) )
            )
    );

// If first condition holds, output1 must be 1.
    check_first_condition_sets_one: assert property (
        @(posedge input3)
            ((input1 >= 4'b0110) && (input2 == 2'b10)) |-> (output1 == 1'b1)
    );

// If first is false and second holds, output1 must be 0.
    check_second_condition_sets_zero_when_first_false: assert property (
        @(posedge input3)
            (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
             (input3 == 1'b1) && (input4 == 1'b0)) |-> (output1 == 1'b0)
    );

// If first and second are false and third holds, output1 must be 1.
    check_third_condition_sets_one_when_higher_false: assert property (
        @(posedge input3)
            (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
             !((input3 == 1'b1) && (input4 == 1'b0)) &&
             (input5 && input6 && input7 && input8)) |-> (output1 == 1'b1)
    );

// If none of the conditions hold, output1 must be 0.
    check_default_sets_zero: assert property (
        @(posedge input3)
            (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
             !((input3 == 1'b1) && (input4 == 1'b0)) &&
             !(input5 && input6 && input7 && input8)) |-> (output1 == 1'b0)
    );

// If output1 is 1, it must be due to the first or third condition per priority.
    check_no_spurious_one: assert property (
        @(posedge input3)
            (output1 == 1'b1) |-> (
                ((input1 >= 4'b0110) && (input2 == 2'b10)) ||
                (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                 !((input3 == 1'b1) && (input4 == 1'b0)) &&
                 (input5 && input6 && input7 && input8))
            )
    );

// If output1 is 0, it must be due to the second condition or default case.
    check_no_spurious_zero: assert property (
        @(posedge input3)
            (output1 == 1'b0) |-> (
                (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                 (input3 == 1'b1) && (input4 == 1'b0)) ||
                (!((input1 >= 4'b0110) && (input2 == 2'b10)) &&
                 !((input3 == 1'b1) && (input4 == 1'b0)) &&
                 !(input5 && input6 && input7 && input8))
            )
    );

// Clock: clk (posedge). Reset: none.
    // Synchronous sequential counter with priority: LOAD > UP > DOWN.

    // When LOAD is high, Q loads DIN on the next cycle.
    check_load_updates_q: assert property (
        @(posedge clk) LOAD |=> (Q == $past(DIN))
    );

// When LOAD=0 and UP=1, Q increments with wrap at 15.
    check_up_increments: assert property (
        @(posedge clk) (!LOAD && UP) |=> (Q == (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1)))
    );

// When LOAD=0, UP=0, and DOWN=1, Q decrements with wrap at 0.
    check_down_decrements: assert property (
        @(posedge clk) (!LOAD && !UP && DOWN) |=> (Q == (($past(Q) == 4'h0) ? 4'hF : ($past(Q) - 4'd1)))
    );

// When LOAD=0 and UP=0 and DOWN=0, Q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!LOAD && !UP && !DOWN) |=> (Q == $past(Q))
    );

// When LOAD=0 and both UP and DOWN are 1, UP takes priority (count up).
    check_up_priority_over_down: assert property (
        @(posedge clk) (!LOAD && UP && DOWN) |=> (Q == (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1)))
    );

// Exact next-state function when LOAD=0 (encodes priority and wrap behavior).
    check_no_load_next_state_function: assert property (
        @(posedge clk) (!LOAD) |=> (
            Q == (
                $past(UP) ? (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1)) :
                ($past(DOWN) ? (($past(Q) == 4'h0) ? 4'hF : ($past(Q) - 4'd1)) :
                $past(Q))
            )
        )
    );

// eq reflects in_a == in_b.
    check_eq_definition: assert property (
        @(posedge clk) disable iff (!rst_n) eq == (in_a == in_b)
    );

// gt reflects in_a > in_b.
    check_gt_definition: assert property (
        @(posedge clk) disable iff (!rst_n) gt == (in_a > in_b)
    );

// lt reflects in_a < in_b.
    check_lt_definition: assert property (
        @(posedge clk) disable iff (!rst_n) lt == (in_a < in_b)
    );

// Exactly one of eq/gt/lt is HIGH.
    check_outputs_onehot: assert property (
        @(posedge clk) disable iff (!rst_n) $onehot({eq, gt, lt})
    );

// When not equal, gt and lt are complementary.
    check_eq_low_implies_gt_xor_lt: assert property (
        @(posedge clk) disable iff (!rst_n) (!eq) |-> (gt ^ lt)
    );

// If eq is HIGH, gt and lt must be LOW.
    check_eq_excludes_gt_lt: assert property (
        @(posedge clk) disable iff (!rst_n) eq |-> (!gt && !lt)
    );

// No clock/reset in RTL; pure combinational: X = A | ~B_N; sample on VPWR posedge.

    // If A is 1, X must be 1.
    check_A1_implies_X1: assert property (
        @(posedge VPWR) (A == 1'b1) |-> (X == 1'b1)
    );

// If B_N is 0, X must be 1.
    check_BN0_implies_X1: assert property (
        @(posedge VPWR) (B_N == 1'b0) |-> (X == 1'b1)
    );

// If A is 0 and B_N is 1, X must be 0.
    check_only_zero_case: assert property (
        @(posedge VPWR) ((A == 1'b0) && (B_N == 1'b1)) |-> (X == 1'b0)
    );

// If X is 0, then A must be 0 and B_N must be 1.
    check_X0_implies_inputs: assert property (
        @(posedge VPWR) (X == 1'b0) |-> ((A == 1'b0) && (B_N == 1'b1))
    );

// If X is 1, then A is 1 or B_N is 0.
    check_X1_implies_inputs: assert property (
        @(posedge VPWR) (X == 1'b1) |-> ((A == 1'b1) || (B_N == 1'b0))
    );

// Truth table: A=0, B_N=0 -> X=1.
    check_truth_00: assert property (
        @(posedge VPWR) ((A == 1'b0) && (B_N == 1'b0)) |-> (X == 1'b1)
    );

// Truth table: A=0, B_N=1 -> X=0.
    check_truth_01: assert property (
        @(posedge VPWR) ((A == 1'b0) && (B_N == 1'b1)) |-> (X == 1'b0)
    );

// Truth table: A=1, B_N=0 -> X=1.
    check_truth_10: assert property (
        @(posedge VPWR) ((A == 1'b1) && (B_N == 1'b0)) |-> (X == 1'b1)
    );

// Truth table: A=1, B_N=1 -> X=1.
    check_truth_11: assert property (
        @(posedge VPWR) ((A == 1'b1) && (B_N == 1'b1)) |-> (X == 1'b1)
    );

// When B_N is 1, X equals A.
    check_BN1_X_eq_A: assert property (
        @(posedge VPWR) (B_N == 1'b1) |-> (X == A)
    );

// When A is 0, X equals !B_N.
    check_A0_X_eq_notBN: assert property (
        @(posedge VPWR) (A == 1'b0) |-> (X == !B_N)
    );

// XY=00, state=00 -> next 00
    check_xy00_s00_to_00: assert property (
        @(posedge Clk) ({x,y} == 2'b00 && state == 2'b00) |=> (state == 2'b00)
    );

// XY=00, state=01 -> next 10
    check_xy00_s01_to_10: assert property (
        @(posedge Clk) ({x,y} == 2'b00 && state == 2'b01) |=> (state == 2'b10)
    );

// XY=00, state=10 -> next 00
    check_xy00_s10_to_00: assert property (
        @(posedge Clk) ({x,y} == 2'b00 && state == 2'b10) |=> (state == 2'b00)
    );

// XY=00, state=11 -> next 10
    check_xy00_s11_to_10: assert property (
        @(posedge Clk) ({x,y} == 2'b00 && state == 2'b11) |=> (state == 2'b10)
    );

// XY=01, state=00 -> next 00
    check_xy01_s00_to_00: assert property (
        @(posedge Clk) ({x,y} == 2'b01 && state == 2'b00) |=> (state == 2'b00)
    );

// XY=01, state=01 -> next 11
    check_xy01_s01_to_11: assert property (
        @(posedge Clk) ({x,y} == 2'b01 && state == 2'b01) |=> (state == 2'b11)
    );

// XY=01, state=10 -> next 00
    check_xy01_s10_to_00: assert property (
        @(posedge Clk) ({x,y} == 2'b01 && state == 2'b10) |=> (state == 2'b00)
    );

// XY=01, state=11 -> next 11
    check_xy01_s11_to_11: assert property (
        @(posedge Clk) ({x,y} == 2'b01 && state == 2'b11) |=> (state == 2'b11)
    );

// XY=10, state=00 -> next 01
    check_xy10_s00_to_01: assert property (
        @(posedge Clk) ({x,y} == 2'b10 && state == 2'b00) |=> (state == 2'b01)
    );

// XY=10, state=01 -> next 10
    check_xy10_s01_to_10: assert property (
        @(posedge Clk) ({x,y} == 2'b10 && state == 2'b01) |=> (state == 2'b10)
    );

// XY=10, state=10 -> next 10
    check_xy10_s10_to_10: assert property (
        @(posedge Clk) ({x,y} == 2'b10 && state == 2'b10) |=> (state == 2'b10)
    );

// XY=10, state=11 -> next 00
    check_xy10_s11_to_00: assert property (
        @(posedge Clk) ({x,y} == 2'b10 && state == 2'b11) |=> (state == 2'b00)
    );

// XY=11, state=00 -> next 01
    check_xy11_s00_to_01: assert property (
        @(posedge Clk) ({x,y} == 2'b11 && state == 2'b00) |=> (state == 2'b01)
    );

// XY=11, state=01 -> next 11
    check_xy11_s01_to_11: assert property (
        @(posedge Clk) ({x,y} == 2'b11 && state == 2'b01) |=> (state == 2'b11)
    );

// XY=11, state=10 -> next 11
    check_xy11_s10_to_11: assert property (
        @(posedge Clk) ({x,y} == 2'b11 && state == 2'b10) |=> (state == 2'b11)
    );

// XY=11, state=11 -> next 00
    check_xy11_s11_to_00: assert property (
        @(posedge Clk) ({x,y} == 2'b11 && state == 2'b11) |=> (state == 2'b00)
    );

// When reset is asserted at a clock edge, count must be 0.
    check_reset_clears: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// While reset remains asserted across consecutive clock edges, count stays 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0) && ($past(count) == 4'd0)
    );

// On the sampled rising edge of reset, count is 0.
    check_reset_assert_edge_clears: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd0)
    );

// Final 5-bit result equals A+B+CI.
    check_full_sum: assert property (
        @(posedge clk) disable iff (1'b0) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

// S[0] equals A[0]^B[0]^CI.
    check_sum0_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[0] == (A[0] ^ B[0] ^ CI)
    );

// S[1] equals A[1]^B[1]^C[0].
    check_sum1_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[1] == (A[1] ^ B[1] ^ C[0])
    );

// S[2] equals A[2]^B[2]^C[1].
    check_sum2_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[2] == (A[2] ^ B[2] ^ C[1])
    );

// S[3] equals A[3]^B[3]^C[2].
    check_sum3_xor: assert property (
        @(posedge clk) disable iff (1'b0) S[3] == (A[3] ^ B[3] ^ C[2])
    );

// C[0] equals majority(A[0],B[0],CI).
    check_carry0_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[0] == ((A[0] & B[0]) | (B[0] & CI) | (A[0] & CI))
    );

// C[1] equals majority(A[1],B[1],C[0]).
    check_carry1_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[1] == ((A[1] & B[1]) | (B[1] & C[0]) | (A[1] & C[0]))
    );

// C[2] equals majority(A[2],B[2],C[1]).
    check_carry2_majority: assert property (
        @(posedge clk) disable iff (1'b0) C[2] == ((A[2] & B[2]) | (B[2] & C[1]) | (A[2] & C[1]))
    );

// CO equals majority(A[3],B[3],C[2]).
    check_carry3_majority: assert property (
        @(posedge clk) disable iff (1'b0) CO == ((A[3] & B[3]) | (B[3] & C[2]) | (A[3] & C[2]))
    );

///// Reset behavior /////
    // When reset is asserted, counter/state/output drive to 0.
    check_reset_values: assert property (
        @(posedge clk) reset |-> (count == 16'd0) && (osc_state == 1'b0) && (osc_out == 1'b0)
    );

// For known A, Y equals bitwise NOT of (1 << A).
    check_decode_map: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> (Y == ~(16'h0001 << A))
    );

// For unknown A (X/Z), Y drives all ones via default.
    check_default_on_unknown_A: assert property (
        @(posedge CLK) $isunknown(A) |-> (Y == 16'hFFFF)
    );

// For known A, ~Y is one-hot (exactly one bit set).
    check_onehot_zero: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> $onehot(~Y)
    );

// For known A, the selected bit Y[A] is 0.
    check_selected_bit_zero: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> (Y[A] == 1'b0)
    );

// For known A, Y is not all ones.
    check_not_all_ones_when_known: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> (Y != 16'hFFFF)
    );

// For known A, Y contains no X/Z.
    check_y_known_when_a_known: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> (!$isunknown(Y))
    );

// For known A, OR-ing Y with the A-bit mask yields all ones (others are 1).
    check_masking_behavior: assert property (
        @(posedge CLK) (!$isunknown(A)) |-> ((Y | (16'h0001 << A)) == 16'hFFFF)
    );

// q reflects d=1 exactly 3 cycles later.
    propagate_d1_after_3: assert property (
        @(posedge clk) (d == 1'b1) |-> ##3 (q == 1'b1)
    );

// q reflects d=0 exactly 3 cycles later.
    propagate_d0_after_3: assert property (
        @(posedge clk) (d == 1'b0) |-> ##3 (q == 1'b0)
    );

// Y[0] must equal ~A & ~B & ~C.
    check_y0_decode: assert property (
        @(posedge CLK) Y[0] == ((~A) & (~B) & (~C))
    );

// Y[1] must equal ~A & ~B & C.
    check_y1_decode: assert property (
        @(posedge CLK) Y[1] == ((~A) & (~B) & ( C))
    );

// Y[2] must equal ~A & B & ~C.
    check_y2_decode: assert property (
        @(posedge CLK) Y[2] == ((~A) & ( B) & (~C))
    );

// Y[3] must equal ~A & B & C.
    check_y3_decode: assert property (
        @(posedge CLK) Y[3] == ((~A) & ( B) & ( C))
    );

// Y[4] must equal A & ~B & ~C.
    check_y4_decode: assert property (
        @(posedge CLK) Y[4] == (( A) & (~B) & (~C))
    );

// Y[5] must equal A & ~B & C.
    check_y5_decode: assert property (
        @(posedge CLK) Y[5] == (( A) & (~B) & ( C))
    );

// Y[6] must equal A & B & ~C.
    check_y6_decode: assert property (
        @(posedge CLK) Y[6] == (( A) & ( B) & (~C))
    );

// Y[7] must equal A & B & C.
    check_y7_decode: assert property (
        @(posedge CLK) Y[7] == (( A) & ( B) & ( C))
    );

// Exactly one output bit must be HIGH (one-hot).
    check_onehot_y: assert property (
        @(posedge CLK) $onehot(Y)
    );

// Inputs can be reconstructed from outputs: A == OR of Y[7:4].
    check_reconstruct_a: assert property (
        @(posedge CLK) A == (Y[7] | Y[6] | Y[5] | Y[4])
    );

// Inputs can be reconstructed from outputs: B == OR of Y[7],Y[6],Y[3],Y[2].
    check_reconstruct_b: assert property (
        @(posedge CLK) B == (Y[7] | Y[6] | Y[3] | Y[2])
    );

// Inputs can be reconstructed from outputs: C == OR of Y[7],Y[5],Y[3],Y[1].
    check_reconstruct_c: assert property (
        @(posedge CLK) C == (Y[7] | Y[5] | Y[3] | Y[1])
    );

// Sum equals (~a | b).
    check_sum_function: assert property (
        @(posedge clk) disable iff (1'b0) sum == ((~a) | b)
    );

// Cout equals (a | ~b).
    check_cout_function: assert property (
        @(posedge clk) disable iff (1'b0) cout == (a | (~b))
    );

// At least one output is HIGH at all times.
    check_sum_or_cout_one: assert property (
        @(posedge clk) disable iff (1'b0) (sum | cout) == 1'b1
    );

// Output XOR equals input XOR.
    check_xor_relation: assert property (
        @(posedge clk) disable iff (1'b0) (sum ^ cout) == (a ^ b)
    );

// For a=0,b=0 -> sum=1, cout=1.
    check_tt_00: assert property (
        @(posedge clk) disable iff (1'b0) (!a && !b) |-> (sum && cout)
    );

// For a=0,b=1 -> sum=1, cout=0.
    check_tt_01: assert property (
        @(posedge clk) disable iff (1'b0) (!a && b) |-> (sum && !cout)
    );

// For a=1,b=0 -> sum=0, cout=1.
    check_tt_10: assert property (
        @(posedge clk) disable iff (1'b0) (a && !b) |-> (!sum && cout)
    );

// For a=1,b=1 -> sum=1, cout=1.
    check_tt_11: assert property (
        @(posedge clk) disable iff (1'b0) (a && b) |-> (sum && cout)
    );

// Sum is LOW only when a=1 and b=0.
    check_sum_zero_only_on_10: assert property (
        @(posedge clk) disable iff (1'b0) (sum == 1'b0) |-> (a && !b)
    );

// Cout is LOW only when a=0 and b=1.
    check_cout_zero_only_on_01: assert property (
        @(posedge clk) disable iff (1'b0) (cout == 1'b0) |-> (!a && b)
    );

// Clock: CLK (posedge). Reset: RST active-high, synchronous. Logic: sequential.
    // Behavior: RST->0; LOAD->DATA_OUT:=DATA_IN; else if EN->count with wrap; else hold.

    // On RST high at a clock, DATA_OUT becomes 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (DATA_OUT == 4'b0000)
    );

// LOAD updates DATA_OUT with DATA_IN on the next cycle.
    load_captures_data_in: assert property (
        @(posedge CLK) disable iff (RST) LOAD |=> (DATA_OUT == $past(DATA_IN))
    );

// LOAD has priority over EN when both are asserted.
    load_overrides_en: assert property (
        @(posedge CLK) disable iff (RST) (LOAD && EN) |=> (DATA_OUT == $past(DATA_IN))
    );

// With EN and not LOAD, non-max value increments by 1 on the next cycle.
    en_increments_nonmax: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD && (DATA_OUT != 4'hF)) |=> (DATA_OUT == $past(DATA_OUT) + 4'd1)
    );

// With EN and not LOAD, 4'hF wraps to 0 on the next cycle.
    en_wraps_at_max_to_zero: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD && (DATA_OUT == 4'hF)) |=> (DATA_OUT == 4'h0)
    );

// With neither EN nor LOAD, DATA_OUT holds its previous value.
    holds_when_idle: assert property (
        @(posedge CLK) disable iff (RST) (!EN && !LOAD) |=> (DATA_OUT == $past(DATA_OUT))
    );

// With EN and not LOAD, DATA_OUT must change (either increment or wrap).
    en_causes_change: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD) |=> (DATA_OUT != $past(DATA_OUT))
    );

// When not RESET and not LOAD, the only allowed transitions are hold, +1, or wrap.
    allowed_transitions_without_load: assert property (
        @(posedge CLK) disable iff (RST)
            (!RST && !LOAD) |=> (
                // hold when EN==0
                (( !$past(EN) ) && (DATA_OUT == $past(DATA_OUT))) ||
                // +1 when EN==1 and not max
                (( $past(EN) && ($past(DATA_OUT) != 4'hF) ) && (DATA_OUT == $past(DATA_OUT) + 4'd1)) ||
                // wrap to 0 when EN==1 and max
                (( $past(EN) && ($past(DATA_OUT) == 4'hF) ) && (DATA_OUT == 4'h0))
            )
    );

// No clock/reset in RTL; pure combinational AND. Assertions sample on input posedges.

    // Y must equal A & B & C sampled on posedge A.
    check_y_matches_and_on_A: assert property (
        @(posedge A) Y == (A & B & C)
    );

// Y must equal A & B & C sampled on posedge B.
    check_y_matches_and_on_B: assert property (
        @(posedge B) Y == (A & B & C)
    );

// Y must equal A & B & C sampled on posedge C.
    check_y_matches_and_on_C: assert property (
        @(posedge C) Y == (A & B & C)
    );

// When B and C are HIGH, Y follows A on posedge A.
    check_follow_A_when_BC_high: assert property (
        @(posedge A) (B && C) |-> (Y == A)
    );

// When A and C are HIGH, Y follows B on posedge B.
    check_follow_B_when_AC_high: assert property (
        @(posedge B) (A && C) |-> (Y == B)
    );

// When A and B are HIGH, Y follows C on posedge C.
    check_follow_C_when_AB_high: assert property (
        @(posedge C) (A && B) |-> (Y == C)
    );

// If B is LOW, Y must be LOW on posedge A.
    check_y_zero_when_B_zero_on_A: assert property (
        @(posedge A) (!B) |-> (Y == 1'b0)
    );

// If C is LOW, Y must be LOW on posedge A.
    check_y_zero_when_C_zero_on_A: assert property (
        @(posedge A) (!C) |-> (Y == 1'b0)
    );

// If Y is HIGH on posedge B, A and C must be HIGH.
    check_y_high_implies_A_and_C_high_on_B: assert property (
        @(posedge B) Y |-> (A && C)
    );

// If Y is HIGH on posedge C, A and B must be HIGH.
    check_y_high_implies_A_and_B_high_on_C: assert property (
        @(posedge C) Y |-> (A && B)
    );

// Output equals i0 & i1 when i0 rises.
    check_and_on_i0_posedge: assert property (
        @(posedge i0) disable iff (1'b0) o === (i0 & i1)
    );

// Output equals i0 & i1 when i1 rises.
    check_and_on_i1_posedge: assert property (
        @(posedge i1) disable iff (1'b0) o === (i0 & i1)
    );

// Output equals i0 & i1 when o rises.
    check_and_on_o_posedge: assert property (
        @(posedge o) disable iff (1'b0) o === (i0 & i1)
    );

// No clock/reset in RTL; purely combinational. Use posedge of A1[0] as sampling event.

    // Y must equal one of the eight inputs.
    check_Y_is_from_inputs: assert property (
        @(posedge A1[0]) (Y == A1) || (Y == A2) || (Y == B1) || (Y == B2) || (Y == C1) || (Y == C2) || (Y == D1) || (Y == D2)
    );

// No input can be strictly greater than Y (Y is an upper bound).
    check_Y_is_upper_bound: assert property (
        @(posedge A1[0]) (Y >= A1) && (Y >= A2) && (Y >= B1) && (Y >= B2) && (Y >= C1) && (Y >= C2) && (Y >= D1) && (Y >= D2)
    );

// If A1 is strictly greater than all others, Y equals A1.
    check_strict_max_A1: assert property (
        @(posedge A1[0]) (A1 > A2) && (A1 > B1) && (A1 > B2) && (A1 > C1) && (A1 > C2) && (A1 > D1) && (A1 > D2) |-> (Y == A1)
    );

// If A2 is strictly greater than all others, Y equals A2.
    check_strict_max_A2: assert property (
        @(posedge A1[0]) (A2 > A1) && (A2 > B1) && (A2 > B2) && (A2 > C1) && (A2 > C2) && (A2 > D1) && (A2 > D2) |-> (Y == A2)
    );

// If B1 is strictly greater than all others, Y equals B1.
    check_strict_max_B1: assert property (
        @(posedge A1[0]) (B1 > A1) && (B1 > A2) && (B1 > B2) && (B1 > C1) && (B1 > C2) && (B1 > D1) && (B1 > D2) |-> (Y == B1)
    );

// If B2 is strictly greater than all others, Y equals B2.
    check_strict_max_B2: assert property (
        @(posedge A1[0]) (B2 > A1) && (B2 > A2) && (B2 > B1) && (B2 > C1) && (B2 > C2) && (B2 > D1) && (B2 > D2) |-> (Y == B2)
    );

// If C1 is strictly greater than all others, Y equals C1.
    check_strict_max_C1: assert property (
        @(posedge A1[0]) (C1 > A1) && (C1 > A2) && (C1 > B1) && (C1 > B2) && (C1 > C2) && (C1 > D1) && (C1 > D2) |-> (Y == C1)
    );

// If C2 is strictly greater than all others, Y equals C2.
    check_strict_max_C2: assert property (
        @(posedge A1[0]) (C2 > A1) && (C2 > A2) && (C2 > B1) && (C2 > B2) && (C2 > C1) && (C2 > D1) && (C2 > D2) |-> (Y == C2)
    );

// If D1 is strictly greater than all others, Y equals D1.
    check_strict_max_D1: assert property (
        @(posedge A1[0]) (D1 > A1) && (D1 > A2) && (D1 > B1) && (D1 > B2) && (D1 > C1) && (D1 > C2) && (D1 > D2) |-> (Y == D1)
    );

// If D2 is strictly greater than all others, Y equals D2.
    check_strict_max_D2: assert property (
        @(posedge A1[0]) (D2 > A1) && (D2 > A2) && (D2 > B1) && (D2 > B2) && (D2 > C1) && (D2 > C2) && (D2 > D1) |-> (Y == D2)
    );

// Clock: CLK. Resets: SET_B, RESET_B (active-low, synchronous).
    // Sequential FF with priority: SCD > SCE > !RESET_B > !SET_B. Q = ~Q_N.

    // Q is always inverse of Q_N.
    check_q_inverts_qn: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (Q == ~Q_N)
    );

// SCD high forces Q_N to 0 on the next cycle.
    check_scd_forces_zero: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) SCD |=> (Q_N == 1'b0)
    );

// With SCE high and SCD low, Q_N loads D on the next cycle.
    check_sce_loads_d_no_scd: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SCE && !SCD) |=> (Q_N == $past(D))
    );

// With RESET_B low and no later overrides, Q_N goes to 0 on the next cycle.
    check_reset_forces_zero_when_unoverridden: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b0)
    );

// With SET_B low and no later overrides, Q_N goes to 1 on the next cycle.
    check_set_forces_one_when_unoverridden: assert property (
        @(posedge CLK) (SET_B == 1'b0) && (RESET_B == 1'b1) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b1)
    );

// If SET_B and RESET_B both low (no SCE/SCD), RESET_B wins driving 0.
    check_reset_overrides_set: assert property (
        @(posedge CLK) (SET_B == 1'b0) && (RESET_B == 1'b0) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b0)
    );

// If RESET_B low and SCE high (no SCD), SCE overrides and Q_N loads D.
    check_sce_overrides_reset: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && (SCE == 1'b1) && (SCD == 1'b0) |=> (Q_N == $past(D))
    );

// When SET_B, RESET_B deasserted and SCE/SCD low, Q_N holds its value.
    check_hold_when_no_ctrls: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SET_B == 1'b1) && (RESET_B == 1'b1) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == $past(Q_N))
    );

// After SCE load (no SCD), Q reflects ~D on next cycle.
    check_q_updates_after_sce: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SCE && !SCD) |=> (Q == ~$past(D))
    );

// After SCD high, Q goes to 1 on the next cycle.
    check_q_one_after_scd: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) SCD |=> (Q == 1'b1)
    );

// No clock/reset in RTL; sampled on external CLK. Combinational mux behavior.

  // Out equals the bit selected by sel.
  check_mux_function: assert property (
    @(posedge CLK) (out === in[sel])
  );

// When sel==00, out mirrors in[0].
  check_sel_00: assert property (
    @(posedge CLK) (sel == 2'b00) |-> (out === in[0])
  );

// When sel==01, out mirrors in[1].
  check_sel_01: assert property (
    @(posedge CLK) (sel == 2'b01) |-> (out === in[1])
  );

// When sel==10, out mirrors in[2].
  check_sel_10: assert property (
    @(posedge CLK) (sel == 2'b10) |-> (out === in[2])
  );

// When sel==11, out mirrors in[3].
  check_sel_11: assert property (
    @(posedge CLK) (sel == 2'b11) |-> (out === in[3])
  );

// When concatenation equals 0, datao must be datai[0].
    sel_0_routes_bit0: assert property (
        @(posedge clk) disable iff (1'b0) ({C,B,A} == 18'd0) |-> (datao == datai[0])
    );

// When concatenation equals 32, datao must be datai[0].
    sel_32_routes_bit0: assert property (
        @(posedge clk) disable iff (1'b0) ({C,B,A} == 18'd32) |-> (datao == datai[0])
    );

// When concatenation is neither 0 nor 32, datao must be datai[1].
    other_sel_routes_bit1: assert property (
        @(posedge clk) disable iff (1'b0) !(({C,B,A} == 18'd0) || ({C,B,A} == 18'd32)) |-> (datao == datai[1])
    );

// Explicit check for 31 case label: datao must be datai[1].
    sel_31_routes_bit1: assert property (
        @(posedge clk) disable iff (1'b0) ({C,B,A} == 18'd31) |-> (datao == datai[1])
    );

// Output must always equal either datai[0] or datai[1].
    output_from_bit0_or_bit1_only: assert property (
        @(posedge clk) disable iff (1'b0) 1'b1 |-> ((datao == datai[0]) || (datao == datai[1]))
    );

// If datai[0] equals datai[1], datao equals that value regardless of select.
    equal_inputs_pass_through: assert property (
        @(posedge clk) disable iff (1'b0) (datai[0] === datai[1]) |-> (datao == datai[0])
    );

// If inputs differ and datao equals datai[0], select must be 0 or 32.
    di0_implies_bit0_region_when_inputs_differ: assert property (
        @(posedge clk) disable iff (1'b0)
            ((datai[0] != datai[1]) && (datao == datai[0])) |-> (({C,B,A} == 18'd0) || ({C,B,A} == 18'd32))
    );

// If inputs differ and select is not {0,32}, datao must be datai[1].
    non_bit0_region_implies_di1_when_inputs_differ: assert property (
        @(posedge clk) disable iff (1'b0)
            ((datai[0] != datai[1]) && !((({C,B,A} == 18'd0) || ({C,B,A} == 18'd32)))) |-> (datao == datai[1])
    );

// X equals NAND of A_N, B, C, D.
    check_function_nand_equivalence: assert property (
        @(posedge CLK) X == ~(A_N & B & C & D)
    );

// When all inputs are HIGH, X must be LOW.
    check_all_high_implies_X_low: assert property (
        @(posedge CLK) (A_N && B && C && D) |-> (X == 1'b0)
    );

// When any input is LOW, X must be HIGH.
    check_any_low_implies_X_high: assert property (
        @(posedge CLK) ((!A_N) || (!B) || (!C) || (!D)) |-> (X == 1'b1)
    );

// If X is LOW, then all inputs must be HIGH.
    check_X_low_implies_all_high: assert property (
        @(posedge CLK) (X == 1'b0) |-> (A_N && B && C && D)
    );

// If X is HIGH, then at least one input is LOW.
    check_X_high_implies_any_low: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((!A_N) || (!B) || (!C) || (!D))
    );

// With B,C,D HIGH, X equals NOT A_N.
    check_dep_A: assert property (
        @(posedge CLK) (B && C && D) |-> (X == ~A_N)
    );

// With A_N,C,D HIGH, X equals NOT B.
    check_dep_B: assert property (
        @(posedge CLK) (A_N && C && D) |-> (X == ~B)
    );

// With A_N,B,D HIGH, X equals NOT C.
    check_dep_C: assert property (
        @(posedge CLK) (A_N && B && D) |-> (X == ~C)
    );

// With A_N,B,C HIGH, X equals NOT D.
    check_dep_D: assert property (
        @(posedge CLK) (A_N && B && C) |-> (X == ~D)
    );

// Clock: clk; Reset: reset (active-high, synchronous)
  // Logic: sequential; outputs registered on posedge clk
  // Function: if enable then W=A, X=Y=B, Z=0; else W=X=Y=0, Z=C (visible next cycle)

  // Synchronous reset drives all outputs to zero on the next cycle.
  reset_clears_outputs_next: assert property (
    @(posedge clk) reset |=> (W == 3'b000) && (X == 3'b000) && (Y == 3'b000) && (Z == 3'b000)
  );

// W next-cycle equals A when enable is 1, else 0.
  w_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (W == ($past(enable) ? $past(A) : 3'b000))
  );

// X next-cycle equals B when enable is 1, else 0.
  x_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (X == ($past(enable) ? $past(B) : 3'b000))
  );

// Y next-cycle equals B when enable is 1, else 0.
  y_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (Y == ($past(enable) ? $past(B) : 3'b000))
  );

// Z next-cycle equals 0 when enable is 1, else C.
  z_next_matches_enable: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (Z == ($past(enable) ? 3'b000 : $past(C)))
  );

// X and Y are always equal from the next cycle onward.
  x_equals_y_next_cycle: assert property (
    @(posedge clk) disable iff (reset)
      1'b1 |-> ##1 (X == Y)
  );

// out_and equals bitwise AND of inputs.
  check_out_and_function: assert property (
    @(posedge CLK) out_and == (in1 & in2)
  );

// out_or equals bitwise OR of inputs.
  check_out_or_function: assert property (
    @(posedge CLK) out_or == (in1 | in2)
  );

// out_xor equals bitwise XOR of inputs.
  check_out_xor_function: assert property (
    @(posedge CLK) out_xor == (in1 ^ in2)
  );

// out_not equals bitwise NOT of in1.
  check_out_not_function: assert property (
    @(posedge CLK) out_not == ~in1
  );

// De Morgan for OR: a|b == ~(~a & ~b).
  check_or_demorgan: assert property (
    @(posedge CLK) out_or == ~(~in1 & ~in2)
  );

// De Morgan for AND: a&b == ~(~a | ~b).
  check_and_demorgan: assert property (
    @(posedge CLK) out_and == ~(~in1 | ~in2)
  );

// OR equals (AND | XOR) for same operands.
  check_or_is_and_or_xor: assert property (
    @(posedge CLK) out_or == (out_and | out_xor)
  );

// XOR equals OR AND NOT(AND) for same operands.
  check_xor_is_or_andnot_and: assert property (
    @(posedge CLK) out_xor == (out_or & ~out_and)
  );

// AND and XOR are bitwise disjoint.
  check_and_xor_mutex: assert property (
    @(posedge CLK) (out_and & out_xor) == '0
  );

// in1 and its complement are bitwise disjoint.
  check_in1_out_not_mutex: assert property (
    @(posedge CLK) (in1 & out_not) == '0
  );

// in1 XOR ~in1 yields all ones.
  check_in1_xor_out_not_allones: assert property (
    @(posedge CLK) (in1 ^ out_not) == 8'hFF
  );

// If in[7] is 1, pos must be 7 (highest priority).
    check_priority_bit7: assert property (
        @(posedge clk) in[7] |-> (pos == 3'd7)
    );

// If in[6] is 1 and in[7] is 0, pos must be 6.
    check_priority_bit6: assert property (
        @(posedge clk) (!in[7] && in[6]) |-> (pos == 3'd6)
    );

// If in[5] is 1 and in[7:6] are 0, pos must be 5.
    check_priority_bit5: assert property (
        @(posedge clk) ((in[7:6] == 2'b00) && in[5]) |-> (pos == 3'd5)
    );

// If in[4] is 1 and in[7:5] are 0, pos must be 4.
    check_priority_bit4: assert property (
        @(posedge clk) ((in[7:5] == 3'b000) && in[4]) |-> (pos == 3'd4)
    );

// If in[3] is 1 and in[7:4] are 0, pos must be 3.
    check_priority_bit3: assert property (
        @(posedge clk) ((in[7:4] == 4'b0000) && in[3]) |-> (pos == 3'd3)
    );

// If in[2] is 1 and in[7:3] are 0, pos must be 2.
    check_priority_bit2: assert property (
        @(posedge clk) ((in[7:3] == 5'b00000) && in[2]) |-> (pos == 3'd2)
    );

// If in[1] is 1 and in[7:2] are 0, pos must be 1.
    check_priority_bit1: assert property (
        @(posedge clk) ((in[7:2] == 6'b000000) && in[1]) |-> (pos == 3'd1)
    );

// If only in[0] is 1 (no higher bits), pos must be 0.
    check_priority_bit0: assert property (
        @(posedge clk) ((in[7:1] == 7'b0000000) && in[0]) |-> (pos == 3'd0)
    );

// If all inputs are 0, pos must be 0.
    check_zero_input: assert property (
        @(posedge clk) (in == 8'b0000_0000) |-> (pos == 3'd0)
    );

// If pos is 7, then in[7] must be 1.
    check_inverse_pos7_requires_in7: assert property (
        @(posedge clk) (pos == 3'd7) |-> in[7]
    );

// If pos is 6, then in[7] must be 0 and in[6] must be 1.
    check_inverse_pos6_requires_in6_and_no7: assert property (
        @(posedge clk) (pos == 3'd6) |-> (!in[7] && in[6])
    );

// If pos is 0, no higher bits [7:1] may be set.
    check_inverse_pos0_blocks_higher: assert property (
        @(posedge clk) (pos == 3'd0) |-> (in[7:1] == 7'b0000000)
    );

// Synchronous reset drives q to 0 on the reset cycle.
    check_reset_sets_zero: assert property (
        @(posedge clk) rst |-> (q == 4'b0000)
    );

// Y equals logical AND of A and B.
    check_function_and: assert property (
        @(posedge CLK) (Y == (A & B))
    );

// If A is 0 then Y must be 0.
    check_y_zero_when_a_zero: assert property (
        @(posedge CLK) (A == 1'b0) |-> (Y == 1'b0)
    );

// If B is 0 then Y must be 0.
    check_y_zero_when_b_zero: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b0)
    );

// If B is 1 then Y equals A.
    check_y_eq_a_when_b_one: assert property (
        @(posedge CLK) (B == 1'b1) |-> (Y == A)
    );

// If A is 1 then Y equals B.
    check_y_eq_b_when_a_one: assert property (
        @(posedge CLK) (A == 1'b1) |-> (Y == B)
    );

// Y rising implies both inputs are 1.
    check_y_rise_requires_inputs_high: assert property (
        @(posedge CLK) $rose(Y) |-> (A == 1'b1 && B == 1'b1)
    );

// Y falling implies at least one input is 0.
    check_y_fall_requires_any_input_low: assert property (
        @(posedge CLK) $fell(Y) |-> ((A == 1'b0) || (B == 1'b0))
    );

// If both inputs are 1 then Y must be 1.
    check_high_when_both_high: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1) |-> (Y == 1'b1)
    );

// S=0 selects I[0]
    check_s0_selects_i0: assert property (
        @(posedge CLK) (S == 4'd0) |-> (O == I[0])
    );

// S=1 selects I[1]
    check_s1_selects_i1: assert property (
        @(posedge CLK) (S == 4'd1) |-> (O == I[1])
    );

// S=2 selects I[2]
    check_s2_selects_i2: assert property (
        @(posedge CLK) (S == 4'd2) |-> (O == I[2])
    );

// S=3 selects I[3]
    check_s3_selects_i3: assert property (
        @(posedge CLK) (S == 4'd3) |-> (O == I[3])
    );

// S=4 selects I[4]
    check_s4_selects_i4: assert property (
        @(posedge CLK) (S == 4'd4) |-> (O == I[4])
    );

// S=5 selects I[5]
    check_s5_selects_i5: assert property (
        @(posedge CLK) (S == 4'd5) |-> (O == I[5])
    );

// S=6 selects I[6]
    check_s6_selects_i6: assert property (
        @(posedge CLK) (S == 4'd6) |-> (O == I[6])
    );

// S=7 selects I[7]
    check_s7_selects_i7: assert property (
        @(posedge CLK) (S == 4'd7) |-> (O == I[7])
    );

// S=8 selects I[8]
    check_s8_selects_i8: assert property (
        @(posedge CLK) (S == 4'd8) |-> (O == I[8])
    );

// S=9 selects I[9]
    check_s9_selects_i9: assert property (
        @(posedge CLK) (S == 4'd9) |-> (O == I[9])
    );

// S=10 selects I[10]
    check_s10_selects_i10: assert property (
        @(posedge CLK) (S == 4'd10) |-> (O == I[10])
    );

// S=11 selects I[11]
    check_s11_selects_i11: assert property (
        @(posedge CLK) (S == 4'd11) |-> (O == I[11])
    );

// S out of range (12..15) drives O=0
    check_default_zero_when_s_ge_12: assert property (
        @(posedge CLK) (S >= 4'd12) |-> (O == 1'b0)
    );

// Combinational cell with no clock/reset; sample on input edges.

    // SUM equals three-input XOR (sampled on A edge).
    sum_eq_xor_on_A: assert property (
        @(posedge A) SUM == (A ^ B ^ CI)
    );

// SUM equals three-input XOR (sampled on B edge).
    sum_eq_xor_on_B: assert property (
        @(posedge B) SUM == (A ^ B ^ CI)
    );

// SUM equals three-input XOR (sampled on CI edge).
    sum_eq_xor_on_CI: assert property (
        @(posedge CI) SUM == (A ^ B ^ CI)
    );

// COUT_N equals OR of NOR terms per RTL (sampled on A edge).
    coutn_eq_or_nor_on_A: assert property (
        @(posedge A) COUT_N == ((~(A|B)) | (~(A|CI)) | (~(B|CI)))
    );

// COUT_N equals OR of NOR terms per RTL (sampled on B edge).
    coutn_eq_or_nor_on_B: assert property (
        @(posedge B) COUT_N == ((~(A|B)) | (~(A|CI)) | (~(B|CI)))
    );

// COUT_N equals OR of NOR terms per RTL (sampled on CI edge).
    coutn_eq_or_nor_on_CI: assert property (
        @(posedge CI) COUT_N == ((~(A|B)) | (~(A|CI)) | (~(B|CI)))
    );

// If A and B are 1, COUT_N must be 0 regardless of CI.
    coutn_zero_when_A_and_B_one: assert property (
        @(posedge A) (A && B) |-> (COUT_N == 1'b0)
    );

// If A and CI are 1, COUT_N must be 0 regardless of B.
    coutn_zero_when_A_and_CI_one: assert property (
        @(posedge CI) (A && CI) |-> (COUT_N == 1'b0)
    );

// If B and CI are 1, COUT_N must be 0 regardless of A.
    coutn_zero_when_B_and_CI_one: assert property (
        @(posedge B) (B && CI) |-> (COUT_N == 1'b0)
    );

// When A and B are equal, SUM equals CI.
    sum_equals_CI_when_A_eq_B: assert property (
        @(posedge CI) (A == B) |-> (SUM == CI)
    );

// When enabled, ENCLK updates to TE on the next clock.
    update_on_enable: assert property (
        @(posedge CLK) EN |=> (ENCLK == $past(TE))
    );

// When disabled, ENCLK holds its previous value on the next clock.
    hold_when_disabled: assert property (
        @(posedge CLK) !EN |=> (ENCLK == $past(ENCLK))
    );

// Any change in ENCLK from one cycle to the next requires EN to have been HIGH in the prior cycle.
    change_requires_prev_enable: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK != $past(ENCLK)) |-> $past(EN))
    );

// If ENCLK changes, the new value must equal TE from the prior cycle.
    change_matches_prev_te: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK != $past(ENCLK)) |-> (ENCLK == $past(TE)))
    );

// If enabled and TE differs from current ENCLK, ENCLK must toggle on the next clock.
    enabled_differs_causes_toggle: assert property (
        @(posedge CLK) (EN && (TE != ENCLK)) |=> (ENCLK != $past(ENCLK))
    );

// If enabled and TE equals current ENCLK, ENCLK remains unchanged on the next clock.
    enabled_same_keeps_stable: assert property (
        @(posedge CLK) (EN && (TE == ENCLK)) |=> (ENCLK == $past(ENCLK))
    );

///// Reset behavior /////
  // While reset is asserted, outputs are driven to zero.
  check_reset_clears_outputs: assert property (
    @(posedge clk) reset |-> (parallel_out == 32'b0) && (serial_out == 1'b0)
  );

// If reset stays asserted across cycles, outputs remain zero.
  check_reset_holds_zero: assert property (
    @(posedge clk) $past(reset) && reset |-> (parallel_out == 32'b0) && (serial_out == 1'b0)
  );

///// Structural relations /////
  // serial_out always mirrors MSB of parallel_out.
  check_serial_out_matches_msb: assert property (
    @(posedge clk) disable iff (reset) (serial_out == parallel_out[31])
  );

///// Reset behavior /////
    // While reset is asserted at the clock edge, CRC must be zero.
    reset_forces_zero: assert property (
        @(posedge CLK) RST |-> (CRC == 16'h0000)
    );

// Clock: clk (posedge). Reset: reset active-low (asynchronous). Sequential counter with load > up/down; wrap in 4 bits.

    // While reset is asserted, count must be 0.
    check_reset_forces_zero_now: assert property (
        @(posedge clk) !reset |-> (count == 4'd0)
    );

// If reset is asserted, the next-cycle count remains 0.
    check_reset_holds_zero_next: assert property (
        @(posedge clk) !reset |=> (count == 4'd0)
    );

// Load updates count with load_data on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!reset) load |=> (count == $past(load_data))
    );

// Load has priority over up_down when both are 1.
    check_load_overrides_updown: assert property (
        @(posedge clk) disable iff (!reset) (load && up_down) |=> (count == $past(load_data))
    );

// When not loading and up_down=1, increment by 1.
    check_increment_when_up: assert property (
        @(posedge clk) disable iff (!reset) (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// When not loading and up_down=0, decrement by 1.
    check_decrement_when_down: assert property (
        @(posedge clk) disable iff (!reset) (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// Next-state must be load_data, or +1, or -1 based on controls.
    check_next_state_matches_controls: assert property (
        @(posedge clk) disable iff (!reset)
            1'b1 |=> (
                ($past(load) && (count == $past(load_data))) ||
                (!$past(load) &&  $past(up_down) && (count == ($past(count) + 4'd1))) ||
                (!$past(load) && !$past(up_down) && (count == ($past(count) - 4'd1)))
            )
    );

// Increment from 4'hF wraps to 4'h0 when not loading.
    check_increment_wraps_around: assert property (
        @(posedge clk) disable iff (!reset) (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// Decrement from 4'h0 wraps to 4'hF when not loading.
    check_decrement_wraps_around: assert property (
        @(posedge clk) disable iff (!reset) (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// When not loading, count must change next cycle (no hold behavior).
    check_no_hold_without_load: assert property (
        @(posedge clk) disable iff (!reset) (!load) |=> (count != $past(count))
    );

// out implements exact ternary function of inputs
    check_function_exact: assert property (
        @(posedge clk) out == ((sel == 1'b0) ? a : b)
    );

// When sel==0, out equals a in the same cycle
    check_sel0_path: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel==1, out equals b in the same cycle
    check_sel1_path: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// Clock: clk. Reset: reset (active-high async in RTL). Mixed sequential/combinational logic.

    ///// Reset behavior /////
    // During reset, counter is 0.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// During reset, out is 0.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 1'b0)
    );

// Out equals upper nibble AND selected 4-bit input
    check_function_equivalence: assert property (
        @(posedge clk) out == ((sel == 2'b00 ? in0 :
                                sel == 2'b01 ? in1 :
                                sel == 2'b10 ? in2 : in3) & in[7:4])
    );

// When sel==00, out == (in0 & in[7:4])
    check_sel_00_map: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == (in0 & in[7:4]))
    );

// When sel==01, out == (in1 & in[7:4])
    check_sel_01_map: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == (in1 & in[7:4]))
    );

// When sel==10, out == (in2 & in[7:4])
    check_sel_10_map: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == (in2 & in[7:4]))
    );

// When sel==11, out == (in3 & in[7:4])
    check_sel_11_map: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == (in3 & in[7:4]))
    );

// out cannot have 1s where in[7:4] has 0s
    check_out_subset_of_upper_nibble: assert property (
        @(posedge clk) (out & ~in[7:4]) == 4'b0000
    );

// If sel==00 and in0 is zero, out must be zero
    check_zero_when_sel00_in0_zero: assert property (
        @(posedge clk) ((sel == 2'b00) && (in0 == 4'b0000)) |-> (out == 4'b0000)
    );

// If sel==01 and in1 is zero, out must be zero
    check_zero_when_sel01_in1_zero: assert property (
        @(posedge clk) ((sel == 2'b01) && (in1 == 4'b0000)) |-> (out == 4'b0000)
    );

// If sel==10 and in2 is zero, out must be zero
    check_zero_when_sel10_in2_zero: assert property (
        @(posedge clk) ((sel == 2'b10) && (in2 == 4'b0000)) |-> (out == 4'b0000)
    );

// If sel==11 and in3 is zero, out must be zero
    check_zero_when_sel11_in3_zero: assert property (
        @(posedge clk) ((sel == 2'b11) && (in3 == 4'b0000)) |-> (out == 4'b0000)
    );

///// Reset behavior /////
    // With reset asserted, next-cycle read_0 reflects RESET_VAL.
    reset_drives_read0_next: assert property (
        @(posedge CLK) !RST_N |-> (read_0 == RESET_VAL)
    );

///// Combinational read chain (priority mux) /////
    // read_1 selects write_0 when enabled, else read_0.
    chain_read1_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_1 == (EN_write_0 ? write_0 : read_0)
    );

// read_2 selects write_1 when enabled, else read_1.
    chain_read2_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_2 == (EN_write_1 ? write_1 : read_1)
    );

// read_3 selects write_2 when enabled, else read_2.
    chain_read3_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_3 == (EN_write_2 ? write_2 : read_2)
    );

// read_4 selects write_3 when enabled, else read_3.
    chain_read4_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_4 == (EN_write_3 ? write_3 : read_3)
    );

// read_5 selects write_4 when enabled, else read_4.
    chain_read5_mux: assert property (
        @(posedge CLK) disable iff (!RST_N) read_5 == (EN_write_4 ? write_4 : read_4)
    );

// Analysis: No clock/reset in RTL; pure combinational (2 always @*). MUX selects in2 only when sel1&sel2==1; else in1. Comparator directly drives eq/gt/lt.
    // Assertions below are clocked on 'clk'.

    ///// Multiplexer checks /////
    // MUX implements: mux_out = ((sel1==1)&&(sel2==1)) ? in2 : in1.
    check_mux_function: assert property (
        @(posedge clk) mux_out === (((sel1 === 1'b1) && (sel2 === 1'b1)) ? in2 : in1)
    );

// When both selects are 1, output must be in2.
    check_mux_both_sel_to_in2: assert property (
        @(posedge clk) ((sel1 === 1'b1) && (sel2 === 1'b1)) |-> (mux_out === in2)
    );

///// Comparator functional mapping /////
    // eq_out matches (comp_in1 == comp_in2).
    check_comp_eq_mapping: assert property (
        @(posedge clk) eq_out === (comp_in1 == comp_in2)
    );

// gt_out matches (comp_in1 > comp_in2).
    check_comp_gt_mapping: assert property (
        @(posedge clk) gt_out === (comp_in1 > comp_in2)
    );

// lt_out matches (comp_in1 < comp_in2).
    check_comp_lt_mapping: assert property (
        @(posedge clk) lt_out === (comp_in1 < comp_in2)
    );

///// Comparator consistency /////
    // If eq_out is 1, then gt_out and lt_out must be 0.
    check_eq_excludes_gt_lt: assert property (
        @(posedge clk) (eq_out === 1'b1) |-> ((gt_out === 1'b0) && (lt_out === 1'b0))
    );

// If gt_out is 1, then eq_out and lt_out must be 0.
    check_gt_excludes_eq_lt: assert property (
        @(posedge clk) (gt_out === 1'b1) |-> ((eq_out === 1'b0) && (lt_out === 1'b0))
    );

// If lt_out is 1, then eq_out and gt_out must be 0.
    check_lt_excludes_eq_gt: assert property (
        @(posedge clk) (lt_out === 1'b1) |-> ((eq_out === 1'b0) && (gt_out === 1'b0))
    );

// gt_out and lt_out cannot both be 1 simultaneously.
    check_no_gt_and_lt_same_time: assert property (
        @(posedge clk) !((gt_out === 1'b1) && (lt_out === 1'b1))
    );

// With known comparator inputs, exactly one of {eq,gt,lt} must be 1.
    check_trichotomy_when_inputs_known: assert property (
        @(posedge clk) (!$isunknown({comp_in1, comp_in2})) |-> ((((eq_out === 1'b1) ? 1 : 0) + ((gt_out === 1'b1) ? 1 : 0) + ((lt_out === 1'b1) ? 1 : 0)) == 1)
    );

// Out equals delayed data or its inversion based on select s.
    check_out_select_invert: assert property (
        @(posedge CLK) disable iff (1'b0) out == (s ? ~d_delayed : d_delayed)
    );

// Clock: clk (posedge). Reset: RESET (active-high, synchronous).
    // Behavior: if RESET then Q<=0; else if LOAD then Q<=DATA; else Q<=Q+1 (2-bit wrap).

    // Synchronous reset drives Q to 0 on the next clock.
    reset_clears_q: assert property (
        @(posedge clk) RESET |=> (Q == 2'b00)
    );

// Next-state matches RTL when not in reset: load has priority else increment.
    next_state_matches_rtl: assert property (
        @(posedge clk) disable iff (RESET)
            1'b1 |=> (Q == ($past(LOAD) ? $past(DATA) : ($past(Q) + 2'b01)))
    );

// When LOAD is asserted (no reset), Q updates to DATA on the next clock.
    next_q_on_load: assert property (
        @(posedge clk) disable iff (RESET)
            LOAD |=> (Q == $past(DATA))
    );

// When LOAD is deasserted (no reset), Q increments by 1 on the next clock.
    next_q_on_no_load_increment: assert property (
        @(posedge clk) disable iff (RESET)
            !LOAD |=> (Q == ($past(Q) + 2'b01))
    );

// Increment wraps from 3 to 0 when LOAD is low (no reset).
    increment_wraps_at_3: assert property (
        @(posedge clk) disable iff (RESET)
            (!LOAD && (Q == 2'b11)) |=> (Q == 2'b00)
    );

// With LOAD low for two cycles (no reset), Q increases by 2 over two clocks.
    two_cycle_increment_when_no_load: assert property (
        @(posedge clk) disable iff (RESET)
            (!LOAD ##1 !LOAD) |=> (Q == ($past(Q,2) + 2'd2))
    );

// With LOAD high for two cycles (no reset), Q follows DATA from the immediately preceding cycle.
    two_consecutive_loads_follow_data: assert property (
        @(posedge clk) disable iff (RESET)
            (LOAD ##1 LOAD) |=> (Q == $past(DATA,1))
    );

// LOAD followed by no-LOAD (no reset): Q becomes loaded DATA then increments next.
    load_then_increment: assert property (
        @(posedge clk) disable iff (RESET)
            (LOAD ##1 !LOAD) |=> (Q == ($past(DATA,2) + 2'b01))
    );

// X equals the Boolean function (A & B) | (C & D).
    check_functional_equivalence: assert property (
        @(posedge clk) X === ((A & B) | (C & D))
    );

// When A and B are both 1, X must be 1.
    check_ab_true_implies_x1: assert property (
        @(posedge clk) (A === 1'b1 && B === 1'b1) |-> (X === 1'b1)
    );

// When C and D are both 1, X must be 1.
    check_cd_true_implies_x1: assert property (
        @(posedge clk) (C === 1'b1 && D === 1'b1) |-> (X === 1'b1)
    );

// If X is 1, at least one product term (A&B or C&D) is 1.
    check_x1_requires_some_term1: assert property (
        @(posedge clk) (X === 1'b1) |-> (((A & B) === 1'b1) || ((C & D) === 1'b1))
    );

// If both (A&B) and (C&D) are 0, X must be 0.
    check_terms_zero_implies_x0: assert property (
        @(posedge clk) (((A & B) === 1'b0) && ((C & D) === 1'b0)) |-> (X === 1'b0)
    );

// If X is 0, both (A&B) and (C&D) are 0.
    check_x0_requires_terms_zero: assert property (
        @(posedge clk) (X === 1'b0) |-> (((A & B) === 1'b0) && ((C & D) === 1'b0))
    );

// A&B rising with C&D=0 forces X=1 in the same cycle.
    check_ab_rise_causes_x1_when_cd0: assert property (
        @(posedge clk) $rose(A & B) && ((C & D) === 1'b0) |-> (X === 1'b1)
    );

// C&D rising with A&B=0 forces X=1 in the same cycle.
    check_cd_rise_causes_x1_when_ab0: assert property (
        @(posedge clk) $rose(C & D) && ((A & B) === 1'b0) |-> (X === 1'b1)
    );

// A&B falling with C&D=0 forces X=0 in the same cycle.
    check_ab_fall_causes_x0_when_cd0: assert property (
        @(posedge clk) $fell(A & B) && ((C & D) === 1'b0) |-> (X === 1'b0)
    );

// X equals bitwise XOR of A and B each cycle.
    check_xor_function: assert property (
        @(posedge clk) X === (A ^ B)
    );

// Output equals the RTL expression.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
        X == ((A1 & A2) | (B1 & B2) | VPWR | VGND | VPB | VNB)
    );

// If A1&A2 are HIGH, X must be HIGH.
    check_and_a_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2) |-> X
    );

// If B1&B2 are HIGH, X must be HIGH.
    check_and_b_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (B1 & B2) |-> X
    );

// If VPWR is HIGH, X must be HIGH.
    check_vpwr_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        VPWR |-> X
    );

// If VGND is HIGH, X must be HIGH.
    check_vgnd_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        VGND |-> X
    );

// If VPB is HIGH, X must be HIGH.
    check_vpb_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        VPB |-> X
    );

// If VNB is HIGH, X must be HIGH.
    check_vnb_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        VNB |-> X
    );

// If all inputs are LOW, X must be LOW.
    check_all_zero_forces_x_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1 && !A2 && !B1 && !B2 && !VPWR && !VGND && !VPB && !VNB) |-> (!X)
    );

// twos_comp implements ~binary + 1
    check_twos_comp_definition: assert property (
        @(posedge clk) twos_comp == (~binary + 4'b0001)
    );

// binary + twos_comp wraps to 0 (mod 16)
    check_zero_sum_mod16: assert property (
        @(posedge clk) (binary + twos_comp) == 4'b0000
    );

// Two's complement is an involution: t(t(x)) == x
    check_double_complement_returns_input: assert property (
        @(posedge clk) (~twos_comp + 4'b0001) == binary
    );

// LSB is preserved by two's complement
    check_lsb_preserved: assert property (
        @(posedge clk) twos_comp[0] == binary[0]
    );

// Zero maps to zero
    check_zero_input_gives_zero_output: assert property (
        @(posedge clk) (binary == 4'b0000) |-> (twos_comp == 4'b0000)
    );

// Only zero maps to zero
    check_only_zero_maps_to_zero: assert property (
        @(posedge clk) (twos_comp == 4'b0000) |-> (binary == 4'b0000)
    );

// Minimum 4-bit signed value (1000) maps to itself
    check_min_int_fixed_point: assert property (
        @(posedge clk) (binary == 4'b1000) |-> (twos_comp == 4'b1000)
    );

// No other value is a fixed point
    check_non_fixed_point_for_others: assert property (
        @(posedge clk) ((binary != 4'b0000) && (binary != 4'b1000)) |-> (twos_comp != binary)
    );

// Subtracting 1 from result yields bitwise NOT of input
    check_subtract_one_equals_not_input: assert property (
        @(posedge clk) (twos_comp - 4'b0001) == ~binary
    );

// Bitwise NOT of result equals input minus 1
    check_not_result_equals_input_minus_one: assert property (
        @(posedge clk) ~twos_comp == (binary - 4'b0001)
    );

// While reset is LOW, out is forced to 0.
    check_reset_forces_out_zero: assert property (
        @(posedge clk) !reset |-> (out == 1'b0)
    );

// On reset deassertion (LOW->HIGH), out remains 0 in that sampled cycle.
    check_out_zero_on_reset_release: assert property (
        @(posedge clk) $rose(reset) |-> (out == 1'b0)
    );

// With reset HIGH in consecutive cycles, out equals previous cycle's a & b.
    check_sync_update_matches_prev_and: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (out === $past(a & b))
    );

// If previous a and b were 1 with reset HIGH, out becomes 1.
    check_prev_inputs_one_implies_out_one: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) && $past(a) && $past(b) |-> (out == 1'b1)
    );

// If either previous a or b was 0 with reset HIGH, out becomes 0.
    check_prev_inputs_zero_implies_out_zero: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) && ((!$past(a)) || (!$past(b))) |-> (out == 1'b0)
    );

// A rise on out requires previous a & b to be 1 and reset HIGH previously.
    check_out_rise_requires_prev_and_one: assert property (
        @(posedge clk) disable iff (!reset) $rose(out) |-> ($past(reset) && ($past(a & b) === 1'b1))
    );

// DUT is pure combinational; clk/reset_n are for SVA sampling only.

    // Exactly one TimeSteps bit is HIGH (one-hot decode).
    check_onehot_timesteps: assert property (
        @(posedge clk) disable iff (!reset_n) $onehot(TimeSteps)
    );

// TimeSteps[0] matches ~3 & ~2 & ~1 & ~0.
    check_ts0_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[0] == (~StepCounter[3] & ~StepCounter[2] & ~StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[1] matches ~3 & ~2 & ~1 & 0.
    check_ts1_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[1] == (~StepCounter[3] & ~StepCounter[2] & ~StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[2] matches ~3 & ~2 & 1 & ~0.
    check_ts2_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[2] == (~StepCounter[3] & ~StepCounter[2] & StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[3] matches ~3 & ~2 & 1 & 0.
    check_ts3_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[3] == (~StepCounter[3] & ~StepCounter[2] & StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[4] matches ~3 & 2 & ~1 & ~0.
    check_ts4_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[4] == (~StepCounter[3] & StepCounter[2] & ~StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[5] matches ~3 & 2 & ~1 & 0.
    check_ts5_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[5] == (~StepCounter[3] & StepCounter[2] & ~StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[6] matches ~3 & 2 & 1 & ~0.
    check_ts6_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[6] == (~StepCounter[3] & StepCounter[2] & StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[7] matches ~3 & 2 & 1 & 0.
    check_ts7_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[7] == (~StepCounter[3] & StepCounter[2] & StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[8] matches 3 & ~2 & ~1 & ~0.
    check_ts8_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[8] == (StepCounter[3] & ~StepCounter[2] & ~StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[9] matches 3 & ~2 & ~1 & 0.
    check_ts9_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[9] == (StepCounter[3] & ~StepCounter[2] & ~StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[10] matches 3 & ~2 & 1 & ~0.
    check_ts10_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[10] == (StepCounter[3] & ~StepCounter[2] & StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[11] matches 3 & ~2 & 1 & 0.
    check_ts11_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[11] == (StepCounter[3] & ~StepCounter[2] & StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[12] matches 3 & 2 & ~1 & ~0.
    check_ts12_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[12] == (StepCounter[3] & StepCounter[2] & ~StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[13] matches 3 & 2 & ~1 & 0.
    check_ts13_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[13] == (StepCounter[3] & StepCounter[2] & ~StepCounter[1] & StepCounter[0]))
    );

// TimeSteps[14] matches 3 & 2 & 1 & ~0.
    check_ts14_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[14] == (StepCounter[3] & StepCounter[2] & StepCounter[1] & ~StepCounter[0]))
    );

// TimeSteps[15] matches 3 & 2 & 1 & 0.
    check_ts15_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
            (TimeSteps[15] == (StepCounter[3] & StepCounter[2] & StepCounter[1] & StepCounter[0]))
    );

///// OR-combine returns to master /////
    // m_addr_ack is the OR of s0_addr_ack and s1_addr_ack.
    check_m_addr_ack_or: assert property (
        @(posedge clk) disable iff (reset) m_addr_ack == (s0_addr_ack | s1_addr_ack)
    );

// m_rd_rs is the OR of s0_rd_rs and s1_rd_rs.
    check_m_rd_rs_or: assert property (
        @(posedge clk) disable iff (reset) m_rd_rs == (s0_rd_rs | s1_rd_rs)
    );

///// Shared ORed data bus /////
    // m_mb_read equals m_mb_write | s0_mb_read | s1_mb_read.
    check_m_mb_read_or: assert property (
        @(posedge clk) disable iff (reset) m_mb_read == (m_mb_write | s0_mb_read | s1_mb_read)
    );

// s0_mb_write equals m_mb_write | s0_mb_read | s1_mb_read.
    check_s0_mb_write_or: assert property (
        @(posedge clk) disable iff (reset) s0_mb_write == (m_mb_write | s0_mb_read | s1_mb_read)
    );

// s1_mb_write equals m_mb_write | s0_mb_read | s1_mb_read.
    check_s1_mb_write_or: assert property (
        @(posedge clk) disable iff (reset) s1_mb_write == (m_mb_write | s0_mb_read | s1_mb_read)
    );

// The ORed bus value is consistent across m_mb_read and s0_mb_write.
    check_mb_bus_consistency_s0: assert property (
        @(posedge clk) disable iff (reset) s0_mb_write == m_mb_read
    );

// The ORed bus value is consistent across m_mb_read and s1_mb_write.
    check_mb_bus_consistency_s1: assert property (
        @(posedge clk) disable iff (reset) s1_mb_write == m_mb_read
    );

///// Pass-through of master control/address to both slaves /////
    // s0_wr_rs passes through m_wr_rs.
    pass_s0_wr_rs: assert property (
        @(posedge clk) disable iff (reset) s0_wr_rs == m_wr_rs
    );

// s1_wr_rs passes through m_wr_rs.
    pass_s1_wr_rs: assert property (
        @(posedge clk) disable iff (reset) s1_wr_rs == m_wr_rs
    );

// s0_rq_cyc passes through m_rq_cyc.
    pass_s0_rq_cyc: assert property (
        @(posedge clk) disable iff (reset) s0_rq_cyc == m_rq_cyc
    );

// s1_rq_cyc passes through m_rq_cyc.
    pass_s1_rq_cyc: assert property (
        @(posedge clk) disable iff (reset) s1_rq_cyc == m_rq_cyc
    );

// s0_rd_rq passes through m_rd_rq.
    pass_s0_rd_rq: assert property (
        @(posedge clk) disable iff (reset) s0_rd_rq == m_rd_rq
    );

// s1_rd_rq passes through m_rd_rq.
    pass_s1_rd_rq: assert property (
        @(posedge clk) disable iff (reset) s1_rd_rq == m_rd_rq
    );

// s0_wr_rq passes through m_wr_rq.
    pass_s0_wr_rq: assert property (
        @(posedge clk) disable iff (reset) s0_wr_rq == m_wr_rq
    );

// s1_wr_rq passes through m_wr_rq.
    pass_s1_wr_rq: assert property (
        @(posedge clk) disable iff (reset) s1_wr_rq == m_wr_rq
    );

// s0_ma passes through m_ma.
    pass_s0_ma: assert property (
        @(posedge clk) disable iff (reset) s0_ma == m_ma
    );

// s1_ma passes through m_ma.
    pass_s1_ma: assert property (
        @(posedge clk) disable iff (reset) s1_ma == m_ma
    );

// s0_sel passes through m_sel.
    pass_s0_sel: assert property (
        @(posedge clk) disable iff (reset) s0_sel == m_sel
    );

// s1_sel passes through m_sel.
    pass_s1_sel: assert property (
        @(posedge clk) disable iff (reset) s1_sel == m_sel
    );

// s0_fmc_select passes through m_fmc_select.
    pass_s0_fmc_select: assert property (
        @(posedge clk) disable iff (reset) s0_fmc_select == m_fmc_select
    );

// s1_fmc_select passes through m_fmc_select.
    pass_s1_fmc_select: assert property (
        @(posedge clk) disable iff (reset) s1_fmc_select == m_fmc_select
    );

// On reset, count is driven to zero on that clock edge.
    reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

///// Functional checks (sampled on a data edge since no clock/reset in RTL) /////
    // out_hi is always zero because hi_byte truncates to 8'b0 and a bit-select is zero-extended.
    check_out_hi_const_zero: assert property (
        @(posedge in[0]) (out_hi == 8'h00)
    );

// out_lo[7:1] must always be zero due to zero-extension of a single selected bit.
    check_out_lo_zero_extended: assert property (
        @(posedge in[0]) (out_lo[7:1] == 7'b0)
    );

// out_lo[0] equals the selected bit from in[3:0] indexed by in[13:12].
    check_out_lo_dynamic_index: assert property (
        @(posedge in[0]) (out_lo[0] == in[in[13:12]])
    );

// out_lo can only be 8'h00 or 8'h01 (zero-extended single bit).
    check_out_lo_binary_range: assert property (
        @(posedge in[0]) (out_lo inside {8'h00, 8'h01})
    );

// Equivalent Boolean form of selection: out_lo equals OR of gated bits, zero-extended.
    check_out_lo_boolean_form: assert property (
        @(posedge in[0])
        out_lo == {7'b0, (((in[13:12]==2'd0) && in[0]) ||
                          ((in[13:12]==2'd1) && in[1]) ||
                          ((in[13:12]==2'd2) && in[2]) ||
                          ((in[13:12]==2'd3) && in[3]))}
    );

///// Functional correctness /////
    // Y equals bitwise XOR of A and B.
    check_y_equals_bitwise_xor: assert property (
        @(posedge clk) Y === (A ^ B)
    );

// Y[0] equals A[0] XOR B[0].
    check_y0_is_xor: assert property (
        @(posedge clk) Y[0] === (A[0] ^ B[0])
    );

// Y[1] equals A[1] XOR B[1].
    check_y1_is_xor: assert property (
        @(posedge clk) Y[1] === (A[1] ^ B[1])
    );

// Y[2] equals A[2] XOR B[2].
    check_y2_is_xor: assert property (
        @(posedge clk) Y[2] === (A[2] ^ B[2])
    );

// Y[3] equals A[3] XOR B[3].
    check_y3_is_xor: assert property (
        @(posedge clk) Y[3] === (A[3] ^ B[3])
    );

// Output equals absolute value: out = in if in>=0 else (~in+1).
    check_abs_function: assert property (
        @(posedge CLK) out == ((in >= 32'sd0) ? $unsigned(in) : $unsigned(~in + 32'sd1))
    );

// Non-negative input passes through unchanged.
    check_nonneg_passthrough: assert property (
        @(posedge CLK) (in >= 32'sd0) |-> (out == $unsigned(in))
    );

// Negative input produces two's complement magnitude.
    check_neg_twos_complement: assert property (
        @(posedge CLK) (in < 32'sd0) |-> (out == $unsigned(~in + 32'sd1))
    );

// Zero input yields zero output.
    check_zero_out_zero: assert property (
        @(posedge CLK) (in == 32'sd0) |-> (out == 32'd0)
    );

// Most-negative value maps to itself (two's complement wrap).
    check_minint_edgecase: assert property (
        @(posedge CLK) (in == 32'sh80000000) |-> (out == 32'h80000000)
    );

// For negative inputs except most-negative, MSB of output is 0.
    check_neg_not_min_msb0: assert property (
        @(posedge CLK) ((in < 32'sd0) && (in != 32'sh80000000)) |-> (out[31] == 1'b0)
    );

// For non-negative inputs, MSB of output is 0.
    check_nonneg_msb0: assert property (
        @(posedge CLK) (in >= 32'sd0) |-> (out[31] == 1'b0)
    );

// For negative inputs except most-negative, output differs from input.
    check_neg_not_min_out_neq_in: assert property (
        @(posedge CLK) ((in < 32'sd0) && (in != 32'sh80000000)) |-> (out != $unsigned(in))
    );

// If output equals input, then input was non-negative or most-negative.
    check_out_eq_in_implies_sign_condition: assert property (
        @(posedge CLK) (out == $unsigned(in)) |-> ((in >= 32'sd0) || (in == 32'sh80000000))
    );

// For negative inputs except most-negative, output is non-zero.
    check_neg_not_min_out_nonzero: assert property (
        @(posedge CLK) ((in < 32'sd0) && (in != 32'sh80000000)) |-> (out != 32'd0)
    );

// Analysis: Clock=CLK (posedge), no reset. Sequential D-FF gated by TE; ENCLK is registered EN when TE=1, else holds.

    // On TE=1, ENCLK updates to EN on the next cycle.
    update_on_TE_high: assert property (
        @(posedge CLK) TE |=> (ENCLK == $past(EN))
    );

// On TE=0, ENCLK holds its previous value on the next cycle.
    hold_when_TE_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

///// Combinational correctness (sampled on posedge of 'a') /////
    // out_or equals reduction OR of in.
    check_out_or_reduction: assert property (
        @(posedge a) out_or == (|in)
    );

// out_xor equals reduction XOR of in.
    check_out_xor_reduction: assert property (
        @(posedge a) out_xor == (^in)
    );

// out_nor equals reduction AND of in (by RTL composition).
    check_out_nor_is_and: assert property (
        @(posedge a) out_nor == (&in)
    );

///// Logical relationships implied by reductions /////
    // If out_nor is 1 (all bits are 1), out_or must be 1.
    check_nor_implies_or: assert property (
        @(posedge a) out_nor |-> out_or
    );

// If out_or is 0 (all bits are 0), out_xor must be 0.
    check_or_zero_implies_xor_zero: assert property (
        @(posedge a) !out_or |-> (out_xor == 1'b0)
    );

// If out_or is 0 (all bits are 0), out_nor must be 0.
    check_or_zero_implies_nor_zero: assert property (
        @(posedge a) !out_or |-> (out_nor == 1'b0)
    );

// If out_xor is 1 (odd parity), out_or must be 1.
    check_xor_one_implies_or_one: assert property (
        @(posedge a) out_xor |-> out_or
    );

// If out_nor is 1 (all ones, even count of ones), out_xor must be 0.
    check_nor_one_implies_xor_zero: assert property (
        @(posedge a) out_nor |-> (out_xor == 1'b0)
    );

///// Corner-case input patterns /////
    // When in is all zeros, all outputs are zero.
    check_all_zero_input: assert property (
        @(posedge a) (in == 100'b0) |-> (out_or == 1'b0 && out_xor == 1'b0 && out_nor == 1'b0)
    );

// When in is all ones, out_or=1, out_xor=0 (even parity), out_nor=1.
    check_all_ones_input: assert property (
        @(posedge a) (in == {100{1'b1}}) |-> (out_or == 1'b1 && out_xor == 1'b0 && out_nor == 1'b1)
    );

// X implements A | B | ~C_N | ~D_N sampled on A rising edge.
    check_truth_on_A_posedge: assert property (
        @(posedge A) X == (A | B | ~C_N | ~D_N)
    );

// X implements A | B | ~C_N | ~D_N sampled on B rising edge.
    check_truth_on_B_posedge: assert property (
        @(posedge B) X == (A | B | ~C_N | ~D_N)
    );

// X implements A | B | ~C_N | ~D_N sampled on C_N rising edge.
    check_truth_on_Cn_posedge: assert property (
        @(posedge C_N) X == (A | B | ~C_N | ~D_N)
    );

// X implements A | B | ~C_N | ~D_N sampled on D_N rising edge.
    check_truth_on_Dn_posedge: assert property (
        @(posedge D_N) X == (A | B | ~C_N | ~D_N)
    );

// X implements A | B | ~C_N | ~D_N sampled on X rising edge.
    check_truth_on_X_posedge: assert property (
        @(posedge X) X == (A | B | ~C_N | ~D_N)
    );

// Addition with A == 0 returns zero-extended B.
    check_add_zero_A: assert property (
        @(posedge CLK) (opcode == 2'b00) && (A == 8'h00) |-> (result == {8'h00, B})
    );

// Addition with B == 0 returns zero-extended A.
    check_add_zero_B: assert property (
        @(posedge CLK) (opcode == 2'b00) && (B == 8'h00) |-> (result == {8'h00, A})
    );

// Subtraction with A == B yields zero.
    check_sub_equal_zero: assert property (
        @(posedge CLK) (opcode == 2'b01) && (A == B) |-> (result == 16'h0000)
    );

// When A > B, outputs must be GT=1 and EQ=0.
    outputs_for_a_greater: assert property (
        @(posedge CLK) disable iff (!RESETn) (A > B) |-> (GT == 1'b1 && EQ == 1'b0)
    );

// When A == B, outputs must be GT=0 and EQ=1.
    outputs_for_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == B) |-> (GT == 1'b0 && EQ == 1'b1)
    );

// When A < B, outputs must be GT=0 and EQ=0.
    outputs_for_a_less: assert property (
        @(posedge CLK) disable iff (!RESETn) (A < B) |-> (GT == 1'b0 && EQ == 1'b0)
    );

// GT can be 1 only when A > B (and then EQ must be 0).
    gt_only_when_a_greater: assert property (
        @(posedge CLK) disable iff (!RESETn) (GT == 1'b1) |-> ((A > B) && (EQ == 1'b0))
    );

// EQ can be 1 only when A == B (and then GT must be 0).
    eq_only_when_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (EQ == 1'b1) |-> ((A == B) && (GT == 1'b0))
    );

// Combination GT=0 and EQ=0 occurs only when A < B.
    zero_zero_only_when_a_less: assert property (
        @(posedge CLK) disable iff (!RESETn) ((GT == 1'b0) && (EQ == 1'b0)) |-> (A < B)
    );

// GT and EQ are never both 1 simultaneously.
    gt_eq_mutex: assert property (
        @(posedge CLK) disable iff (!RESETn) !(GT && EQ)
    );

// GT exactly matches the boolean result of (A > B).
    gt_matches_compare: assert property (
        @(posedge CLK) disable iff (!RESETn) GT == (A > B)
    );

// EQ exactly matches the boolean result of (A == B).
    eq_matches_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) EQ == (A == B)
    );

// When A is not greater than B, GT must be 0.
    no_gt_when_not_greater: assert property (
        @(posedge CLK) disable iff (!RESETn) !(A > B) |-> (GT == 1'b0)
    );

///// Multiplexer selection mapping /////
    // When sel=0000, out equals in1.
    mux_map_sel_0000_to_in1: assert property (
        @(posedge clk) (sel == 4'b0000) |-> (out == in1)
    );

// When sel=0001, out equals in2.
    mux_map_sel_0001_to_in2: assert property (
        @(posedge clk) (sel == 4'b0001) |-> (out == in2)
    );

// When sel=0010, out equals in3.
    mux_map_sel_0010_to_in3: assert property (
        @(posedge clk) (sel == 4'b0010) |-> (out == in3)
    );

// When sel=0011, out equals in4.
    mux_map_sel_0011_to_in4: assert property (
        @(posedge clk) (sel == 4'b0011) |-> (out == in4)
    );

// When sel=0100, out equals in5.
    mux_map_sel_0100_to_in5: assert property (
        @(posedge clk) (sel == 4'b0100) |-> (out == in5)
    );

// When sel=0101, out equals in6.
    mux_map_sel_0101_to_in6: assert property (
        @(posedge clk) (sel == 4'b0101) |-> (out == in6)
    );

// When sel=0110, out equals in7.
    mux_map_sel_0110_to_in7: assert property (
        @(posedge clk) (sel == 4'b0110) |-> (out == in7)
    );

// When sel=0111, out equals in8.
    mux_map_sel_0111_to_in8: assert property (
        @(posedge clk) (sel == 4'b0111) |-> (out == in8)
    );

// When sel=1000, out equals in9.
    mux_map_sel_1000_to_in9: assert property (
        @(posedge clk) (sel == 4'b1000) |-> (out == in9)
    );

// When sel=1001, out equals in10.
    mux_map_sel_1001_to_in10: assert property (
        @(posedge clk) (sel == 4'b1001) |-> (out == in10)
    );

// When sel=1010, out equals in11.
    mux_map_sel_1010_to_in11: assert property (
        @(posedge clk) (sel == 4'b1010) |-> (out == in11)
    );

// When sel=1011, out equals in12.
    mux_map_sel_1011_to_in12: assert property (
        @(posedge clk) (sel == 4'b1011) |-> (out == in12)
    );

// When sel=1100, out equals in13.
    mux_map_sel_1100_to_in13: assert property (
        @(posedge clk) (sel == 4'b1100) |-> (out == in13)
    );

// When sel=1101, out equals in14.
    mux_map_sel_1101_to_in14: assert property (
        @(posedge clk) (sel == 4'b1101) |-> (out == in14)
    );

// When sel=1110, out equals in15.
    mux_map_sel_1110_to_in15: assert property (
        @(posedge clk) (sel == 4'b1110) |-> (out == in15)
    );

// When sel=1111, out equals in16.
    mux_map_sel_1111_to_in16: assert property (
        @(posedge clk) (sel == 4'b1111) |-> (out == in16)
    );

// SUB decode on CISEL/BSEL from OP[2:0] == 3'b001.
    check_cisel_bsel_decode: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (CISEL == (OP == 3'b001)) && (BSEL == (OP == 3'b001))
    );

// For ADD (000): OSEL=00, no shifts, not logical, CISEL/BSEL=0.
    check_add_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b000) |-> (OSEL == 2'b00) && (SHIFT_LA == 1'b0) && (SHIFT_LR == 1'b0) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// For SUB (001): OSEL=00, no shifts, not logical, CISEL/BSEL=1.
    check_sub_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b001) |-> (OSEL == 2'b00) && (SHIFT_LA == 1'b0) && (SHIFT_LR == 1'b0) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b1) && (BSEL == 1'b1)
    );

// For SRA (010): OSEL=01, LA=1, LR=1, not logical, CISEL/BSEL=0.
    check_sra_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b010) |-> (OSEL == 2'b01) && (SHIFT_LA == 1'b1) && (SHIFT_LR == 1'b1) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// For SRL (011): OSEL=01, LA=0, LR=1, not logical, CISEL/BSEL=0.
    check_srl_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b011) |-> (OSEL == 2'b01) && (SHIFT_LA == 1'b0) && (SHIFT_LR == 1'b1) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// For SLL (100): OSEL=01, LA=1, LR=0, not logical, CISEL/BSEL=0.
    check_sll_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b100) |-> (OSEL == 2'b01) && (SHIFT_LA == 1'b1) && (SHIFT_LR == 1'b0) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// For AND (101): OSEL=10, no shifts, logical_op=1, CISEL/BSEL=0.
    check_and_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b101) |-> (OSEL == 2'b10) && (SHIFT_LA == 1'b0) && (SHIFT_LR == 1'b0) && (LOGICAL_OP == 1'b1) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// For OR (110): OSEL=10, no shifts, logical_op=0, CISEL/BSEL=0.
    check_or_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b110) |-> (OSEL == 2'b10) && (SHIFT_LA == 1'b0) && (SHIFT_LR == 1'b0) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// For default (111): OSEL=11, no shifts, not logical, CISEL/BSEL=0.
    check_default_111_outputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (OP == 3'b111) |-> (OSEL == 2'b11) && (SHIFT_LA == 1'b0) && (SHIFT_LR == 1'b0) && (LOGICAL_OP == 1'b0) && (CISEL == 1'b0) && (BSEL == 1'b0)
    );

// Any SHIFT_LA high implies OSEL selects shift path (01).
    check_shift_la_implies_osel01: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (SHIFT_LA == 1'b1) |-> (OSEL == 2'b01)
    );

// Any SHIFT_LR high implies OSEL selects shift path (01).
    check_shift_lr_implies_osel01: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (SHIFT_LR == 1'b1) |-> (OSEL == 2'b01)
    );

// LOGICAL_OP high only for AND opcode and implies OSEL==10.
    check_logical_op_implies_and: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (LOGICAL_OP == 1'b1) |-> ((OP == 3'b101) && (OSEL == 2'b10))
    );

// Out must equal the combinational mapping defined by ctrl and in.
    check_functional_mapping: assert property (
        @(posedge clk) out == expected_out(in, ctrl)
    );

// For ctrl==11, out is always 00 regardless of in.
    check_ctrl11_zero: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (out == 2'b00)
    );

// For ctrl==10 and in==1000, out is 01.
    check_ctrl10_map_onehot3: assert property (
        @(posedge clk) (ctrl == 2'b10 && in == 4'b1000) |-> (out == 2'b01)
    );

// For ctrl==10 and in!=1000, out is 00.
    check_ctrl10_others_zero: assert property (
        @(posedge clk) (ctrl == 2'b10 && in != 4'b1000) |-> (out == 2'b00)
    );

// For ctrl==01 and in==1000, out is 10.
    check_ctrl01_map_onehot3: assert property (
        @(posedge clk) (ctrl == 2'b01 && in == 4'b1000) |-> (out == 2'b10)
    );

// For ctrl==01 and in==0100, out is 01.
    check_ctrl01_map_onehot2: assert property (
        @(posedge clk) (ctrl == 2'b01 && in == 4'b0100) |-> (out == 2'b01)
    );

// For ctrl==01 and in==0010, out is 00.
    check_ctrl01_deprioritize_onehot1: assert property (
        @(posedge clk) (ctrl == 2'b01 && in == 4'b0010) |-> (out == 2'b00)
    );

// For ctrl==00 and in==0001, out is 00.
    check_ctrl00_map_onehot0: assert property (
        @(posedge clk) (ctrl == 2'b00 && in == 4'b0001) |-> (out == 2'b00)
    );

// For ctrl==00 and in==0010, out is 01.
    check_ctrl00_map_onehot1: assert property (
        @(posedge clk) (ctrl == 2'b00 && in == 4'b0010) |-> (out == 2'b01)
    );

// For ctrl==00 and in==0100, out is 10.
    check_ctrl00_map_onehot2: assert property (
        @(posedge clk) (ctrl == 2'b00 && in == 4'b0100) |-> (out == 2'b10)
    );

// For ctrl==00 and in==1000, out is 11.
    check_ctrl00_map_onehot3: assert property (
        @(posedge clk) (ctrl == 2'b00 && in == 4'b1000) |-> (out == 2'b11)
    );

// For ctrl==00 and inputs not explicitly listed, out is 00.
    check_ctrl00_default_zero: assert property (
        @(posedge clk) (ctrl == 2'b00 && !(in inside {4'b0001,4'b0010,4'b0100,4'b1000})) |-> (out == 2'b00)
    );

// For ctrl==01 and inputs not explicitly listed, out is 00.
    check_ctrl01_default_zero: assert property (
        @(posedge clk) (ctrl == 2'b01 && !(in inside {4'b0001,4'b0010,4'b0100,4'b1000})) |-> (out == 2'b00)
    );

// For ctrl==10 and inputs not explicitly listed, out is 00.
    check_ctrl10_default_zero: assert property (
        @(posedge clk) (ctrl == 2'b10 && !(in inside {4'b0001,4'b0010,4'b0100,4'b1000})) |-> (out == 2'b00)
    );

// Z equals selected input per S.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (1'b0) Z == (S ? B : A)
    );

// When S is 0, Z equals A.
    check_select0_path: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b0) |-> (Z == A)
    );

// When S is 1, Z equals B.
    check_select1_path: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1) |-> (Z == B)
    );

// If A and B are equal, Z equals that value regardless of S.
    check_equal_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Z == A)
    );

// Z always matches one of the inputs (A or B).
    check_output_matches_one_input: assert property (
        @(posedge CLK) disable iff (1'b0) (Z == A) || (Z == B)
    );

// Y must equal (~B) | A_N (gate-level functional equivalence).
    check_function_equation_or: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ((~B) | A_N)
    );

// Y must equal ~(B & ~A_N) (De Morgan equivalent form).
    check_function_equation_demorgan: assert property (
        @(posedge CLK) disable iff (!RESETn) Y == ~(B & ~A_N)
    );

// If B is 0, Y must be 1 (since ~B is 1).
    check_y_high_when_b_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 1'b0) |-> (Y == 1'b1)
    );

// If A_N is 1, Y must be 1 (OR with 1 drives 1).
    check_y_high_when_a_n_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// If B is 1 and A_N is 0, Y must be 0 (only case that drives 0).
    check_y_low_when_b_high_a_n_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((B == 1'b1) && (A_N == 1'b0)) |-> (Y == 1'b0)
    );

// If Y is 0, then B must be 1 and A_N must be 0 (unique low condition).
    check_y_low_implies_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> ((B == 1'b1) && (A_N == 1'b0))
    );

// If Y is 1, then either B is 0 or A_N is 1.
    check_y_high_implies_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b1) |-> ((B == 1'b0) || (A_N == 1'b1))
    );

// When sel=00, out must equal in0.
    check_sel00_path: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ({sel1, sel0} == 2'b00) |-> (out == in0)
    );

// When sel=01, out must equal in1.
    check_sel01_path: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ({sel1, sel0} == 2'b01) |-> (out == in1)
    );

// When sel=10, out must equal in2.
    check_sel10_path: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ({sel1, sel0} == 2'b10) |-> (out == in2)
    );

// When sel=11, out must equal in3.
    check_sel11_path: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ({sel1, sel0} == 2'b11) |-> (out == in3)
    );

// During reset, outputs must be LOW.
    reset_outputs_low: assert property (
        @(posedge clk) !rst_n |-> (rise == 1'b0) && (down == 1'b0)
    );

// Outputs are never both HIGH simultaneously.
    check_mutual_exclusion: assert property (
        @(posedge clk) disable iff (!rst_n) !(rise && down)
    );

// 'rise' is a single-cycle pulse.
    rise_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n) rise |=> !rise
    );

// 'down' is a single-cycle pulse.
    down_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n) down |=> !down
    );

// An LSB rising edge does not update anyedge on the next cycle.
    rise_no_capture: assert property (
        @(posedge clk) $rose(in[0]) |=> (anyedge == $past(anyedge))
    );

// Reset loads ResetValue on the next clock edge.
    check_reset_loads_resetvalue_next: assert property (
        @(posedge Clock) Reset |=> (Out === ResetValue)
    );

// Reset has priority over Set on the next clock edge.
    check_reset_over_set_priority: assert property (
        @(posedge Clock) (Reset && Set) |=> (Out === ResetValue)
    );

// If Reset is held across consecutive clocks, Out is ResetValue.
    check_reset_held_keeps_resetvalue: assert property (
        @(posedge Clock) ($past(Reset) && Reset) |-> (Out === ResetValue)
    );

// Synchronous reset drives count to 0 on the next cycle.
  reset_drives_zero: assert property (
    @(posedge clk) reset |-> (count == 3'b000)
  );

// With enable HIGH and count==111, count holds (no case match).
  hold_111_when_enable_high: assert property (
    @(posedge clk) disable iff (reset) (enable && (count == 3'b111)) |-> (count == 3'b111)
  );

// When not stalled (stall[2]==0), instruction/operator/category propagate to EX next cycle.
    propagate_instr_ops: assert property (
        @(posedge clock) disable iff (reset)
            (stall[2] == 1'b0) |=> (ex_instruction == $past(id_instruction)) &&
                                  (ex_operator == $past(id_operator)) &&
                                  (ex_category == $past(id_category))
    );

// When not stalled (stall[2]==0), operands propagate to EX next cycle.
    propagate_operands: assert property (
        @(posedge clock) disable iff (reset)
            (stall[2] == 1'b0) |=> (ex_operand_a == $past(id_operand_a)) &&
                                  (ex_operand_b == $past(id_operand_b))
    );

// When not stalled (stall[2]==0), writeback controls/data propagate to EX next cycle.
    propagate_writeback: assert property (
        @(posedge clock) disable iff (reset)
            (stall[2] == 1'b0) |=> (ex_register_write_enable == $past(id_register_write_enable)) &&
                                  (ex_register_write_address == $past(id_register_write_address)) &&
                                  (ex_register_write_data == $past(id_register_write_data))
    );

// When sel==00, out must equal in[0].
    check_sel00_selects_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// When sel==01, out must equal in[1].
    check_sel01_selects_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// When sel==10, out must equal in[2].
    check_sel10_selects_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// When sel==11, out must equal in[3].
    check_sel11_selects_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// q equals bitwise AND of a and b each cycle.
    check_bitwise_and_equivalence: assert property (
        @(posedge clk) q == (a & b)
    );

// q cannot have 1s where a has 0s.
    check_q_masked_by_a: assert property (
        @(posedge clk) (q & ~a) == {bits{1'b0}}
    );

// q cannot have 1s where b has 0s.
    check_q_masked_by_b: assert property (
        @(posedge clk) (q & ~b) == {bits{1'b0}}
    );

// If a is all zeros, q must be all zeros.
    check_zero_a_forces_zero_q: assert property (
        @(posedge clk) (a == {bits{1'b0}}) |-> (q == {bits{1'b0}})
    );

// If b is all zeros, q must be all zeros.
    check_zero_b_forces_zero_q: assert property (
        @(posedge clk) (b == {bits{1'b0}}) |-> (q == {bits{1'b0}})
    );

// If a is all ones, q passes b.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (a == {bits{1'b1}}) |-> (q == b)
    );

// If b is all ones, q passes a.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (b == {bits{1'b1}}) |-> (q == a)
    );

///// Reset behavior /////
    // On reset, q_reg is cleared to 0000 on the next cycle.
    reset_clears_qreg_next: assert property (
        @(posedge clk) reset |-> ##1 (q_reg == 4'b0000)
    );

// On reset, q holds its value into the next cycle (no assignment under reset).
    reset_holds_q_across_cycle: assert property (
        @(posedge clk) reset |-> ##1 (q == $past(q))
    );

// When disabled, q holds its value into the next cycle.
    q_stable_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |-> ##1 $stable(q)
    );

// xor_out must equal a ^ b.
    check_xor_out_function: assert property (
        @(posedge clk) xor_out === (a ^ b)
    );

// sum must equal a ^ b.
    check_sum_function: assert property (
        @(posedge clk) sum === (a ^ b)
    );

// cout must equal a & b.
    check_cout_function: assert property (
        @(posedge clk) cout === (a & b)
    );

// sum must mirror xor_out.
    check_sum_equals_xor_out: assert property (
        @(posedge clk) sum === xor_out
    );

// Truth table: a=0,b=0 -> xor_out=0,sum=0,cout=0.
    check_tt_00: assert property (
        @(posedge clk) (a === 1'b0 && b === 1'b0) |-> (xor_out === 1'b0 && sum === 1'b0 && cout === 1'b0)
    );

// Truth table: a=1,b=1 -> xor_out=0,sum=0,cout=1.
    check_tt_11: assert property (
        @(posedge clk) (a === 1'b1 && b === 1'b1) |-> (xor_out === 1'b0 && sum === 1'b0 && cout === 1'b1)
    );

// Truth table: a=1,b=0 -> xor_out=1,sum=1,cout=0.
    check_tt_10: assert property (
        @(posedge clk) (a === 1'b1 && b === 1'b0) |-> (xor_out === 1'b1 && sum === 1'b1 && cout === 1'b0)
    );

// Truth table: a=0,b=1 -> xor_out=1,sum=1,cout=0.
    check_tt_01: assert property (
        @(posedge clk) (a === 1'b0 && b === 1'b1) |-> (xor_out === 1'b1 && sum === 1'b1 && cout === 1'b0)
    );

// When cout is 1, sum must be 0.
    check_cout1_implies_sum0: assert property (
        @(posedge clk) (cout === 1'b1) |-> (sum === 1'b0)
    );

// When sum is 1, cout must be 0.
    check_sum1_implies_cout0: assert property (
        @(posedge clk) (sum === 1'b1) |-> (cout === 1'b0)
    );

// When ctrl is 0, S equals D0.
    check_select0: assert property (
        @(posedge CLK) (ctrl === 1'b0) |-> (S === D0)
    );

// When ctrl is 1, S equals D1.
    check_select1: assert property (
        @(posedge CLK) (ctrl === 1'b1) |-> (S === D1)
    );

// On ctrl rising edge, output selects D1.
    check_ctrl_rise_selects_D1: assert property (
        @(posedge CLK) $rose(ctrl) |-> (S === D1)
    );

// On ctrl falling edge, output selects D0.
    check_ctrl_fall_selects_D0: assert property (
        @(posedge CLK) $fell(ctrl) |-> (S === D0)
    );

// When ctrl=0 and D0 changes, S immediately reflects D0.
    check_selected_input_update_sel0: assert property (
        @(posedge CLK) (ctrl === 1'b0) && $stable(ctrl) && $changed(D0) |-> (S === D0)
    );

// When ctrl=1 and D1 changes, S immediately reflects D1.
    check_selected_input_update_sel1: assert property (
        @(posedge CLK) (ctrl === 1'b1) && $stable(ctrl) && $changed(D1) |-> (S === D1)
    );

// With ctrl=0 and differing inputs, S is not equal to D1.
    check_exclusive_if_inputs_differ_sel0: assert property (
        @(posedge CLK) (ctrl === 1'b0) && (D0 !== D1) |-> (S !== D1)
    );

// With ctrl=1 and differing inputs, S is not equal to D0.
    check_exclusive_if_inputs_differ_sel1: assert property (
        @(posedge CLK) (ctrl === 1'b1) && (D0 !== D1) |-> (S !== D0)
    );

///// AND gate functional checks /////
    // Y must equal A & B & C.
    check_y_equals_and: assert property (
        @(posedge CLK) (Y == (A & B & C))
    );

// If Y is HIGH, all inputs must be HIGH.
    check_y_high_requires_all_high: assert property (
        @(posedge CLK) Y |-> (A && B && C)
    );

// If all inputs are HIGH, Y must be HIGH.
    check_all_high_implies_y_high: assert property (
        @(posedge CLK) (A && B && C) |-> Y
    );

// If any input is LOW, Y must be LOW.
    check_any_low_implies_y_low: assert property (
        @(posedge CLK) ((!A) || (!B) || (!C)) |-> (!Y)
    );

// Y can only rise when all inputs are HIGH.
    check_y_rise_requires_all_high: assert property (
        @(posedge CLK) $rose(Y) |-> (A && B && C)
    );

// Y can only fall when any input is LOW.
    check_y_fall_requires_any_low: assert property (
        @(posedge CLK) $fell(Y) |-> ((!A) || (!B) || (!C))
    );

///// Functional mapping rules /////
    // When common_anode is LOW, out must equal the base decode of in.
    check_mapping_common_cathode: assert property (
        @(posedge clk) !common_anode |-> (out == base_decode(in))
    );

// When common_anode is HIGH, out must be the bitwise inversion of the base decode.
    check_mapping_common_anode: assert property (
        @(posedge clk) common_anode |-> (out == ~base_decode(in))
    );

// pos equals bitwise inversion of in[2:0].
    check_pos_inversion_vector: assert property (
        @(posedge clk) pos == ~in[2:0]
    );

// pos[0] equals ~in[0].
    check_pos0_inversion: assert property (
        @(posedge clk) pos[0] == ~in[0]
    );

// pos[1] equals ~in[1].
    check_pos1_inversion: assert property (
        @(posedge clk) pos[1] == ~in[1]
    );

// pos[2] equals ~in[2].
    check_pos2_inversion: assert property (
        @(posedge clk) pos[2] == ~in[2]
    );

///// Reset behavior /////
    // When reset is asserted, internal state clears to zero.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |-> (lfsr_q == 16'h0000)
    );

// When reset is asserted, output reflects cleared state.
    check_reset_drives_output_zero: assert property (
        @(posedge clk) rst |-> (crc_out == 16'h0000)
    );

// Y implements a 3-input NOR of A,B,C.
    check_function_equivalence: assert property (
        @(posedge clk) Y === ~(A | B | C)
    );

// Any input HIGH forces Y LOW.
    check_any_input_one_forces_y_zero: assert property (
        @(posedge clk) ((A===1'b1) || (B===1'b1) || (C===1'b1)) |-> (Y===1'b0)
    );

// All inputs LOW force Y HIGH.
    check_all_inputs_zero_forces_y_one: assert property (
        @(posedge clk) ((A===1'b0) && (B===1'b0) && (C===1'b0)) |-> (Y===1'b1)
    );

// If Y is HIGH, all inputs must be LOW.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) (Y===1'b1) |-> ((A===1'b0) && (B===1'b0) && (C===1'b0))
    );

// If Y is LOW, at least one input must be HIGH.
    check_y_low_implies_any_input_high: assert property (
        @(posedge clk) (Y===1'b0) |-> ((A===1'b1) || (B===1'b1) || (C===1'b1))
    );

// On Y rising, all inputs must be LOW.
    check_output_rise_requires_all_inputs_zero: assert property (
        @(posedge clk) $rose(Y) |-> ((A===1'b0) && (B===1'b0) && (C===1'b0))
    );

// On Y falling, at least one input must be HIGH.
    check_output_fall_requires_any_input_one: assert property (
        @(posedge clk) $fell(Y) |-> ((A===1'b1) || (B===1'b1) || (C===1'b1))
    );

// X equals the bitwise AND of all inputs.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) (X === (A_N & B_N & C & D))
    );

// If A_N is 0 then X must be 0.
    check_zero_dominance_A_N: assert property (
        @(posedge clk) disable iff (1'b0) (A_N == 1'b0) |-> (X == 1'b0)
    );

// If B_N is 0 then X must be 0.
    check_zero_dominance_B_N: assert property (
        @(posedge clk) disable iff (1'b0) (B_N == 1'b0) |-> (X == 1'b0)
    );

// If C is 0 then X must be 0.
    check_zero_dominance_C: assert property (
        @(posedge clk) disable iff (1'b0) (C == 1'b0) |-> (X == 1'b0)
    );

// If D is 0 then X must be 0.
    check_zero_dominance_D: assert property (
        @(posedge clk) disable iff (1'b0) (D == 1'b0) |-> (X == 1'b0)
    );

// If all inputs are 1 then X must be 1.
    check_all_ones_implies_X_one: assert property (
        @(posedge clk) disable iff (1'b0) (A_N && B_N && C && D) |-> (X == 1'b1)
    );

// If X is 1 then all inputs must be 1.
    check_X_one_implies_all_ones: assert property (
        @(posedge clk) disable iff (1'b0) (X == 1'b1) |-> (A_N && B_N && C && D)
    );

// Clock: clk (posedge). Reset: reset (active-high, synchronous). Logic: sequential with load/shift; data_out mirrors shift_reg.

  // Reset sets register to 0 on the next cycle.
  reset_clears: assert property (
    @(posedge clk) reset |=> (data_out == 4'b0000)
  );

// Reset overrides load when both are asserted.
  reset_overrides_load: assert property (
    @(posedge clk) (reset && load) |=> (data_out == 4'b0000)
  );

// Load captures data_in on the next cycle (when not in reset).
  load_writes_next: assert property (
    @(posedge clk) disable iff (reset) load |=> (data_out == $past(data_in))
  );

// Shift operation: next value is {prev[2:0], 1'b0} when not loading.
  shift_next_value: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out == { $past(data_out[2:0]), 1'b0 })
  );

// Shift LSB becomes 0.
  shift_lsb_zero: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[0] == 1'b0)
  );

// Shift moves bit0 to bit1.
  shift_bit1_from_bit0: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[1] == $past(data_out[0]))
  );

// Shift moves bit1 to bit2.
  shift_bit2_from_bit1: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[2] == $past(data_out[1]))
  );

// Shift moves bit2 to bit3.
  shift_bit3_from_bit2: assert property (
    @(posedge clk) disable iff (reset) !load |=> (data_out[3] == $past(data_out[2]))
  );

// After 4 consecutive shifts (no load), the register becomes 0.
  four_shifts_zero: assert property (
    @(posedge clk) disable iff (reset) (!load)[*4] |=> (data_out == 4'b0000)
  );

// A load followed by a shift brings loaded bit2 to MSB two cycles later.
  load_then_shift_moves_loaded_bit2_to_msb: assert property (
    @(posedge clk) disable iff (reset) (load ##1 !load) |=> (data_out[3] == $past(data_in[2], 2))
  );

// Output equals the selected input bit for all sel values.
    check_mux_function: assert property (
        @(posedge CLK) out == ((sel == 2'b00) ? data_in[0] :
                               (sel == 2'b01) ? data_in[1] :
                               (sel == 2'b10) ? data_in[2] : data_in[3])
    );

// When sel==2'b00, out equals data_in[0].
    check_sel_00: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == data_in[0])
    );

// When sel==2'b01, out equals data_in[1].
    check_sel_01: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == data_in[1])
    );

// When sel==2'b10, out equals data_in[2].
    check_sel_10: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == data_in[2])
    );

// When sel==2'b11, out equals data_in[3].
    check_sel_11: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == data_in[3])
    );

// If sel is stable and the selected input changes, out follows that new value.
    check_out_follows_selected_change: assert property (
        @(posedge CLK) $stable(sel) && (data_in[sel] != $past(data_in[sel])) |-> (out == data_in[sel])
    );

// Clock: clk. Reset: reset active-low (asynchronous). Sequential 8-bit register with write enable; hold otherwise.

    // While reset is asserted LOW, out_data must be 0x00.
    check_in_reset_forces_zero: assert property (
        @(posedge clk) (!reset) |-> (out_data == 8'h00)
    );

// On the cycle after reset was LOW, out_data is still 0x00.
    check_post_reset_zero: assert property (
        @(posedge clk) $past(!reset) |-> (out_data == 8'h00)
    );

// First cycle after deasserting reset with no write, out_data remains 0x00.
    check_deassert_no_write_keeps_zero: assert property (
        @(posedge clk) disable iff (!reset) ($past(!reset) && reset && !wenb) |-> (out_data == 8'h00)
    );

// First cycle after deasserting reset with a write, next cycle out_data equals in_data of the deassert cycle.
    check_deassert_write_updates_next: assert property (
        @(posedge clk) disable iff (!reset) ($past(!reset) && reset && wenb) |-> ##1 (out_data == $past(in_data))
    );

// With reset HIGH in consecutive cycles, a write in the previous cycle updates out_data with previous in_data.
    check_write_updates_from_prev_cycle: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && $past(wenb)) |-> (out_data == $past(in_data))
    );

// With reset HIGH in consecutive cycles, no write in the previous cycle holds out_data stable.
    check_hold_when_no_write: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && !$past(wenb)) |-> (out_data == $past(out_data))
    );

// On reset, OUT is cleared on the next cycle.
    check_reset_clears_out_next: assert property (
        @(posedge Clk) Reset |=> (OUT == 32'h0000_0000)
    );

// Reset overrides Load when both asserted.
    check_reset_overrides_load: assert property (
        @(posedge Clk) (Reset && Load) |=> (OUT == 32'h0000_0000)
    );

// While reset is held across cycles, OUT remains zero.
    check_out_zero_while_reset_held: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (OUT == 32'h0000_0000)
    );

// With Load and not Reset, OUT captures IN on the next cycle.
    check_load_updates_out: assert property (
        @(posedge Clk) disable iff (Reset) Load |=> (OUT == $past(IN))
    );

// When idle (no reset, no load), OUT holds its value.
    check_hold_when_idle: assert property (
        @(posedge Clk) disable iff (Reset) (!Load) |=> (OUT == $past(OUT))
    );

check_two_consecutive_loads: assert property (
        @(posedge Clk) disable iff (Reset) two_consecutive_loads |=> (OUT == $past(IN))
    );

// Two idle cycles (no reset, no load) keep OUT unchanged across both.
    check_two_idle_cycles_hold: assert property (
        @(posedge Clk) disable iff (Reset) (!Load && !Reset) ##1 (!Load && !Reset) |=> (OUT == $past(OUT,2))
    );

// While reset is asserted low, outputs are forced to 0.
    reset_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 4'h0) && (max_count == 1'b0)
    );

// When count is 0xF, next cycle wraps to 0 and pulses max_count.
    wrap_on_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (count == 4'hF) |=> (count == 4'h0) && (max_count == 1'b1)
    );

// When count is not 0xF, next cycle increments and clears max_count.
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (count != 4'hF) |=> (count == $past(count) + 4'h1) && (max_count == 1'b0)
    );

// max_count high implies count is zero in the same cycle.
    max_count_only_with_zero_count: assert property (
        @(posedge clk) disable iff (reset == 1'b0) max_count |-> (count == 4'h0)
    );

// max_count can only be asserted following a 0xF state (out of reset).
    max_count_only_after_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (max_count && $past(reset)) |-> ($past(count) == 4'hF)
    );

// max_count is a single-cycle pulse.
    max_count_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (reset == 1'b0) max_count |=> !max_count
    );

// When count is 0xF, max_count must be 0 in the same cycle.
    max_low_when_count_is_F: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (count == 4'hF) |-> (max_count == 1'b0)
    );

// Out of reset, seeing count==0 implies the previous count was 0xF.
    zero_count_means_wrapped: assert property (
        @(posedge clk) disable iff (reset == 1'b0) (reset && $past(reset) && (count == 4'h0)) |-> ($past(count) == 4'hF)
    );

// After a max_count pulse, next cycle count is 1 and max_count clears.
    next_after_maxcount_is_one: assert property (
        @(posedge clk) disable iff (reset == 1'b0) max_count |=> (count == 4'h1) && (max_count == 1'b0)
    );

// Out of reset, each step follows either wrap-to-zero or increment-by-one rule.
    update_follows_spec: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            (reset && $past(reset)) |-> (
                ($past(count) == 4'hF) ? ((count == 4'h0) && (max_count == 1'b1))
                                       : ((count == $past(count) + 4'h1) && (max_count == 1'b0))
            )
    );

// Reset low forces count to 0 at each clock.
    check_count_reset_value: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

// If the previous cycle was in reset, count is 0 now.
    check_count_zero_after_prev_reset: assert property (
        @(posedge clk) $past(!rst, 1, 1'b0) |-> (count == 4'd0)
    );

// With reset high, current count can only be previous, previous+1, or 0.
    check_allowed_transitions_when_rst_high: assert property (
        @(posedge clk) disable iff (!rst)
            $past(1'b1) |-> ( (count == $past(count)) || (count == ($past(count) + 4'd1)) || (count == 4'd0) )
    );

// With en=0 and reset high, next count either holds or goes to 0 (if reset asserted between).
    check_next_when_en0_hold_or_reset: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(1'b1) && !en) |=> ( (count == $past(count)) || (count == 4'd0) )
    );

// With en=1 and reset high, next count is previous+1 or 0 (if reset asserted between).
    check_next_when_en1_inc_or_reset: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(1'b1) && en) |=> ( (count == ($past(count) + 4'd1)) || (count == 4'd0) )
    );

// With reset high, count never decreases except to 0 (wrap or reset).
    check_no_decrement_except_zero: assert property (
        @(posedge clk) disable iff (!rst)
            ($past(1'b1) && (count < $past(count))) |-> (count == 4'd0)
    );

// On any clock where reset is asserted, count is driven to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

// rst_out is 0 during active-low reset.
  check_reset_forces_rst_out_low: assert property (
    @(posedge clk) !reset |-> (rst_out == 1'b0)
  );

// rst_out mirrors internal bor_ff.
  check_rst_out_mirrors_bor_ff: assert property (
    @(posedge clk) disable iff (!reset) (rst_out == bor_ff)
  );

// With reset high in consecutive cycles, rst_out equals prior-cycle (Vin < Vth).
  check_registered_comparator_mapping: assert property (
    @(posedge clk) disable iff (!reset) $past(reset) |-> (rst_out == $past(Vin < Vth))
  );

// If prior-cycle (Vin < Vth) was true, rst_out is 1 now.
  check_prev_comp_true_sets_out: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(Vin < Vth)) |-> (rst_out == 1'b1)
  );

// If prior-cycle (Vin < Vth) was false, rst_out is 0 now.
  check_prev_comp_false_clears_out: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(Vin < Vth)) |-> (rst_out == 1'b0)
  );

// A rising edge on rst_out matches a 0->1 transition of (Vin < Vth) in the prior cycle.
  check_out_rise_matches_comp_rise: assert property (
    @(posedge clk) disable iff (!reset) $rose(rst_out) |-> ($past(reset,2) &&  $past(Vin < Vth,1) && !$past(Vin < Vth,2))
  );

// A falling edge on rst_out matches a 1->0 transition of (Vin < Vth) in the prior cycle.
  check_out_fall_matches_comp_fall: assert property (
    @(posedge clk) disable iff (!reset) $fell(rst_out) |-> ($past(reset,2) && !$past(Vin < Vth,1) &&  $past(Vin < Vth,2))
  );

// If (Vin < Vth) is unchanged over the last two cycles, rst_out is stable now.
  check_out_stable_when_comp_unchanged: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset,2) && ($past(Vin < Vth,1) == $past(Vin < Vth,2))) |-> $stable(rst_out)
  );

// On reset deassertion cycle, rst_out remains 0 (update occurs after sampling).
  check_out_zero_on_reset_rise_cycle: assert property (
    @(posedge clk) disable iff (!reset) $rose(reset) |-> (rst_out == 1'b0)
  );

///// Functional behavior /////
    // Next-cycle Y equals bitwise AND of current A and B.
    check_y_next_is_and_of_inputs: assert property (
        @(posedge clk) 1'b1 |=> (Y == $past(A & B))
    );

// If B is all ones, next-cycle Y equals previous A.
    check_y_next_eq_prevA_when_B_all1: assert property (
        @(posedge clk) (B == 8'hFF) |=> (Y == $past(A))
    );

// If A is all ones, next-cycle Y equals previous B.
    check_y_next_eq_prevB_when_A_all1: assert property (
        @(posedge clk) (A == 8'hFF) |=> (Y == $past(B))
    );

// If A is all zeros, next-cycle Y is zero.
    check_y_next_zero_when_A_zero: assert property (
        @(posedge clk) (A == 8'h00) |=> (Y == 8'h00)
    );

// If B is all zeros, next-cycle Y is zero.
    check_y_next_zero_when_B_zero: assert property (
        @(posedge clk) (B == 8'h00) |=> (Y == 8'h00)
    );

// While reset is asserted LOW at a clock edge, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

// If reset is LOW on two consecutive clock edges, count remains 0.
    check_zero_while_reset_low_consecutive: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (count == 4'd0)
    );

// On a sampled falling edge of reset, count is 0 at that clock edge.
    check_zero_on_reset_fall: assert property (
        @(posedge clk) $fell(rst) |-> (count == 4'd0)
    );

// On the first clock edge after reset deasserts (LOW->HIGH), count is 1.
    check_first_count_after_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'd1)
    );

// When not in reset, count must be a known value (no X/Z).
    check_count_known_when_active: assert property (
        @(posedge clk) disable iff (!rst) !$isunknown(count)
    );

// Reset low forces Q to 0 at every clock.
    reset_low_forces_zero: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

// A falling edge on RESET_B clears Q to 0 by the next clock sample.
    reset_fall_clears_Q: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

// With SCE HIGH, Q captures D on the next clock.
    capture_on_sce_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) SCE |=> (Q == $past(D))
    );

// With SCE LOW, Q holds its previous value.
    hold_on_sce_low: assert property (
        @(posedge CLK) disable iff (!RESET_B) !SCE |=> (Q == $past(Q))
    );

// When SCE is LOW, SCD activity does not affect Q on the next clock.
    scd_change_no_effect_when_sce_low: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!SCE && $changed(SCD)) |=> (Q == $past(Q))
    );

// After reset deasserts and with SCE LOW, Q remains 0 on the next clock.
    post_reset_release_no_load_holds_zero: assert property (
        @(posedge CLK) ($rose(RESET_B) && !SCE) |=> (Q == 1'b0)
    );

// F must be 0 when A,B,C = 000.
    check_map_000: assert property (
        @(posedge CLK) ({A,B,C} === 3'b000) |-> (F == 1'b0)
    );

// F must be 1 when A,B,C = 001.
    check_map_001: assert property (
        @(posedge CLK) ({A,B,C} === 3'b001) |-> (F == 1'b1)
    );

// F must be 0 when A,B,C = 010.
    check_map_010: assert property (
        @(posedge CLK) ({A,B,C} === 3'b010) |-> (F == 1'b0)
    );

// F must be 1 when A,B,C = 011.
    check_map_011: assert property (
        @(posedge CLK) ({A,B,C} === 3'b011) |-> (F == 1'b1)
    );

// F must be 0 when A,B,C = 100.
    check_map_100: assert property (
        @(posedge CLK) ({A,B,C} === 3'b100) |-> (F == 1'b0)
    );

// F must be 1 when A,B,C = 101.
    check_map_101: assert property (
        @(posedge CLK) ({A,B,C} === 3'b101) |-> (F == 1'b1)
    );

// F must be 1 when A,B,C = 110.
    check_map_110: assert property (
        @(posedge CLK) ({A,B,C} === 3'b110) |-> (F == 1'b1)
    );

// F must be 0 when A,B,C = 111.
    check_map_111: assert property (
        @(posedge CLK) ({A,B,C} === 3'b111) |-> (F == 1'b0)
    );

// F equals C XOR (A AND B) for all known inputs.
    check_function_equivalence: assert property (
        @(posedge CLK) !($isunknown({A,B,C})) |-> (F == (C ^ (A & B)))
    );

// No clock/reset in RTL; combinational logic. Sample assertions on posedge of iEnable.

    // When inside box with enable/mask high, drive sprite color.
    sprite_when_inside_and_enabled: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount <= (SizeX + iPosX)) && (iColumnCount >= iPosX) &&
        (iRowCount    <= (SizeY + iPosY)) && (iRowCount    >= iPosY)
        |-> (oRGB == iColorSprite)
    );

// Left edge inclusive: at left boundary with other coords in range and enables high, sprite color.
    sprite_on_left_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount == iPosX) &&
        (iRowCount    >= iPosY) && (iRowCount <= (SizeY + iPosY)) &&
        (iColumnCount <= (SizeX + iPosX))
        |-> (oRGB == iColorSprite)
    );

// Right edge inclusive: at right boundary with other coords in range and enables high, sprite color.
    sprite_on_right_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount == (SizeX + iPosX)) &&
        (iRowCount    >= iPosY) && (iRowCount <= (SizeY + iPosY)) &&
        (iColumnCount >= iPosX)
        |-> (oRGB == iColorSprite)
    );

// Top edge inclusive: at top boundary with other coords in range and enables high, sprite color.
    sprite_on_top_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iRowCount == iPosY) &&
        (iColumnCount >= iPosX) && (iColumnCount <= (SizeX + iPosX)) &&
        (iRowCount   <= (SizeY + iPosY))
        |-> (oRGB == iColorSprite)
    );

// Bottom edge inclusive: at bottom boundary with other coords in range and enables high, sprite color.
    sprite_on_bottom_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iRowCount == (SizeY + iPosY)) &&
        (iColumnCount >= iPosX) && (iColumnCount <= (SizeX + iPosX)) &&
        (iRowCount   >= iPosY)
        |-> (oRGB == iColorSprite)
    );

// X equals AND of A1, A2, B1, VPWR, and VGND every cycle.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A1 & A2 & B1 & VPWR & VGND)
    );

// X high implies A1 is high.
    check_x_implies_a1: assert property (
        @(posedge CLK) X |-> A1
    );

// X high implies A2 is high.
    check_x_implies_a2: assert property (
        @(posedge CLK) X |-> A2
    );

// X high implies B1 is high.
    check_x_implies_b1: assert property (
        @(posedge CLK) X |-> B1
    );

// X high implies VPWR is high.
    check_x_implies_vpwr: assert property (
        @(posedge CLK) X |-> VPWR
    );

// X high implies VGND is high.
    check_x_implies_vgnd: assert property (
        @(posedge CLK) X |-> VGND
    );

// All inputs high implies X is high.
    check_all_high_implies_x: assert property (
        @(posedge CLK) (A1 & A2 & B1 & VPWR & VGND) |-> X
    );

// Any input low forces X low.
    check_any_low_forces_x_low: assert property (
        @(posedge CLK) (!A1 || !A2 || !B1 || !VPWR || !VGND) |-> (X == 1'b0)
    );

// A rising edge on X requires all inputs high.
    check_x_rise_requires_all_high: assert property (
        @(posedge CLK) $rose(X) |-> (A1 & A2 & B1 & VPWR & VGND)
    );

// y implements y = (a&b&c&d) | (!a & !b & !c & !d).
    check_y_functional_equivalence: assert property (
        @(posedge CLK) y == ((a & b & c & d) | (!a & !b & !c & !d))
    );

// If all inputs are 1, y must be 1.
    check_y_true_on_all_ones: assert property (
        @(posedge CLK) (a & b & c & d) |-> (y == 1'b1)
    );

// If all inputs are 0, y must be 1.
    check_y_true_on_all_zeros: assert property (
        @(posedge CLK) (!a & !b & !c & !d) |-> (y == 1'b1)
    );

// If inputs are mixed (not all 1s or all 0s), y must be 0.
    check_y_false_on_mixed: assert property (
        @(posedge CLK) (!((a & b & c & d) || (!a & !b & !c & !d))) |-> (y == 1'b0)
    );

// If y is 1, inputs must be all 1s or all 0s.
    check_y_one_implies_extremes: assert property (
        @(posedge CLK) (y == 1'b1) |-> ((a & b & c & d) || (!a & !b & !c & !d))
    );

// When reset is asserted, on the next cycle the registers (and hence q) are cleared
    reset_clears_next_cycle: assert property (
        @(posedge clk) reset |-> ##1 ((shift_reg == 4'b0000) && (counter == 4'b0000) && (q == 4'b0000))
    );

///// out1 = in1 & in2 & in3 /////
    // out1 equals bitwise AND of in1,in2,in3.
    check_out1_is_and: assert property (
        @(posedge CLK) out1 === (in1 & in2 & in3)
    );

// If out1 is 1 then all in1,in2,in3 are 1.
    check_out1_high_inputs_all_high: assert property (
        @(posedge CLK) (out1 == 1'b1) |-> ((in1 == 1'b1) && (in2 == 1'b1) && (in3 == 1'b1))
    );

// If in1 is 0 then out1 is 0.
    check_in1_zero_forces_out1_zero: assert property (
        @(posedge CLK) (in1 == 1'b0) |-> (out1 == 1'b0)
    );

// If in2 is 0 then out1 is 0.
    check_in2_zero_forces_out1_zero: assert property (
        @(posedge CLK) (in2 == 1'b0) |-> (out1 == 1'b0)
    );

// If in3 is 0 then out1 is 0.
    check_in3_zero_forces_out1_zero: assert property (
        @(posedge CLK) (in3 == 1'b0) |-> (out1 == 1'b0)
    );

///// out2 = in4 | in5 | in6 /////
    // out2 equals bitwise OR of in4,in5,in6.
    check_out2_is_or: assert property (
        @(posedge CLK) out2 === (in4 | in5 | in6)
    );

// If out2 is 0 then all in4,in5,in6 are 0.
    check_out2_low_inputs_all_low: assert property (
        @(posedge CLK) (out2 == 1'b0) |-> ((in4 == 1'b0) && (in5 == 1'b0) && (in6 == 1'b0))
    );

// If in4 is 1 then out2 is 1.
    check_in4_one_forces_out2_one: assert property (
        @(posedge CLK) (in4 == 1'b1) |-> (out2 == 1'b1)
    );

// If in5 is 1 then out2 is 1.
    check_in5_one_forces_out2_one: assert property (
        @(posedge CLK) (in5 == 1'b1) |-> (out2 == 1'b1)
    );

// If in6 is 1 then out2 is 1.
    check_in6_one_forces_out2_one: assert property (
        @(posedge CLK) (in6 == 1'b1) |-> (out2 == 1'b1)
    );

///// out3 = in7 ^ in8 /////
    // out3 equals bitwise XOR of in7,in8.
    check_out3_is_xor: assert property (
        @(posedge CLK) out3 === (in7 ^ in8)
    );

// If in7=0 and in8=0 then out3=0.
    check_xor_00_is_0: assert property (
        @(posedge CLK) ((in7 == 1'b0) && (in8 == 1'b0)) |-> (out3 == 1'b0)
    );

// If in7=1 and in8=1 then out3=0.
    check_xor_11_is_0: assert property (
        @(posedge CLK) ((in7 == 1'b1) && (in8 == 1'b1)) |-> (out3 == 1'b0)
    );

// If in7=1 and in8=0 then out3=1.
    check_xor_10_is_1: assert property (
        @(posedge CLK) ((in7 == 1'b1) && (in8 == 1'b0)) |-> (out3 == 1'b1)
    );

// If in7=0 and in8=1 then out3=1.
    check_xor_01_is_1: assert property (
        @(posedge CLK) ((in7 == 1'b0) && (in8 == 1'b1)) |-> (out3 == 1'b1)
    );

///// out4 = ~in1 /////
    // out4 equals bitwise NOT of in1.
    check_out4_is_not: assert property (
        @(posedge CLK) out4 === (~in1)
    );

// If in1 is 1 then out4 is 0.
    check_not_in1_1_out4_0: assert property (
        @(posedge CLK) (in1 == 1'b1) |-> (out4 == 1'b0)
    );

// If in1 is 0 then out4 is 1.
    check_not_in1_0_out4_1: assert property (
        @(posedge CLK) (in1 == 1'b0) |-> (out4 == 1'b1)
    );

// z1 equals rotl7(y0 + y3) XOR y1.
    check_z1_def: assert property (
        @(posedge y0[0]) z1 == (rotl7(y0 + y3) ^ y1)
    );

// z2 equals rotl9(z1 + y0) XOR y2.
    check_z2_def: assert property (
        @(posedge y0[0]) z2 == (rotl9(z1 + y0) ^ y2)
    );

// z3 equals rotl13(z2 + z1) XOR y3.
    check_z3_def: assert property (
        @(posedge y0[0]) z3 == (rotl13(z2 + z1) ^ y3)
    );

// z0 equals rotl18(z3 + z2) XOR y0.
    check_z0_def: assert property (
        @(posedge y0[0]) z0 == (rotl18(z3 + z2) ^ y0)
    );

// Inverse of z1 relation using right rotate.
    check_z1_inverse: assert property (
        @(posedge y0[0]) rotr7(z1 ^ y1) == (y0 + y3)
    );

// Inverse of z2 relation using right rotate.
    check_z2_inverse: assert property (
        @(posedge y0[0]) rotr9(z2 ^ y2) == (z1 + y0)
    );

// Inverse of z3 relation using right rotate.
    check_z3_inverse: assert property (
        @(posedge y0[0]) rotr13(z3 ^ y3) == (z2 + z1)
    );

// Inverse of z0 relation using right rotate.
    check_z0_inverse: assert property (
        @(posedge y0[0]) rotr18(z0 ^ y0) == (z3 + z2)
    );

// No clock/reset in DUT; pure combinational 2:1 mux: S[0] = ctrl ? D1[0] : D0[0].
    // Sample properties on input edges (ctrl, D0[0], D1[0]).

    // On ctrl rising edge, S must equal selected input.
    check_mux_equiv_on_ctrl_posedge: assert property (
        @(posedge ctrl) S[0] == (ctrl ? D1[0] : D0[0])
    );

// On ctrl falling edge, S must equal selected input.
    check_mux_equiv_on_ctrl_negedge: assert property (
        @(negedge ctrl) S[0] == (ctrl ? D1[0] : D0[0])
    );

// On D0 rising edge, S must equal selected input.
    check_mux_equiv_on_d0_posedge: assert property (
        @(posedge D0[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

// On D0 falling edge, S must equal selected input.
    check_mux_equiv_on_d0_negedge: assert property (
        @(negedge D0[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

// On D1 rising edge, S must equal selected input.
    check_mux_equiv_on_d1_posedge: assert property (
        @(posedge D1[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

// On D1 falling edge, S must equal selected input.
    check_mux_equiv_on_d1_negedge: assert property (
        @(negedge D1[0]) S[0] == (ctrl ? D1[0] : D0[0])
    );

// If inputs are equal, S must equal that value regardless of ctrl (sampled on ctrl rise).
    check_equal_inputs_ctrl_posedge: assert property (
        @(posedge ctrl) (D0[0] == D1[0]) |-> (S[0] == D0[0])
    );

///// C[1] behavior /////
    // C[1] equals (A[1] & ~B[1]) per (A[1] > B[1]).
    check_c1_definition: assert property (
        @(posedge clk) C[1] == (A[1] & ~B[1])
    );

// When MSBs are equal, C[1] must be 0.
    check_c1_zero_when_msbs_equal: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (C[1] == 1'b0)
    );

// When MSBs differ, C[1] equals A[1].
    check_c1_matches_a1_on_mismatch: assert property (
        @(posedge clk) (A[1] != B[1]) |-> (C[1] == A[1])
    );

///// C[0] behavior /////
    // When MSBs are equal, C[0] equals (A[0] >= B[0]).
    check_c0_when_msbs_equal: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (C[0] == (A[0] >= B[0]))
    );

// When MSBs differ, C[0] equals ~C[1].
    check_c0_complement_when_msbs_differ: assert property (
        @(posedge clk) (A[1] != B[1]) |-> (C[0] == ~C[1])
    );

///// Output coding /////
    // Output is never 2'b11.
    check_c_never_11: assert property (
        @(posedge clk) (C != 2'b11)
    );

// If A[1]=1 and B[1]=0, output must be 2'b10.
    check_case_msbs_10: assert property (
        @(posedge clk) (A[1] && !B[1]) |-> (C == 2'b10)
    );

// If A[1]=0 and B[1]=1, output must be 2'b01.
    check_case_msbs_01: assert property (
        @(posedge clk) (!A[1] && B[1]) |-> (C == 2'b01)
    );

// If A[1]=0 and B[1]=0, C = {1'b0, (A[0] >= B[0])}.
    check_case_msbs_00: assert property (
        @(posedge clk) (!A[1] && !B[1]) |-> (C == {1'b0, (A[0] >= B[0])})
    );

// If A[1]=1 and B[1]=1, C = {1'b0, (A[0] >= B[0])}.
    check_case_msbs_11: assert property (
        @(posedge clk) (A[1] && B[1]) |-> (C == {1'b0, (A[0] >= B[0])})
    );

///// Temporal sanity /////
    // Any rise of C[1] implies A[1]=1 and B[1]=0 at that time.
    check_c1_rise_condition: assert property (
        @(posedge clk) $rose(C[1]) |-> (A[1] && !B[1])
    );

// len must equal the exact combinational function of ir.
    check_len_exact_mapping: assert property (
        @(posedge clk) len == {
            (ir == 4'b0011),
            (ir == 4'b0010),
            (ir == 4'b0001),
            ((ir | 4'b0101) == 4'b1101) | ((ir | 4'b1100) == 4'b1100)
        }
    );

// len[3] is 1 iff ir == 4'b0011.
    check_len3_mapping: assert property (
        @(posedge clk) len[3] == (ir == 4'b0011)
    );

// len[2] is 1 iff ir == 4'b0010.
    check_len2_mapping: assert property (
        @(posedge clk) len[2] == (ir == 4'b0010)
    );

// len[1] is 1 iff ir == 4'b0001.
    check_len1_mapping: assert property (
        @(posedge clk) len[1] == (ir == 4'b0001)
    );

// len[0] matches the OR-of-comparisons expression.
    check_len0_mapping: assert property (
        @(posedge clk) len[0] == ( ((ir | 4'b0101) == 4'b1101) | ((ir | 4'b1100) == 4'b1100) )
    );

// len encoding is at most one-hot across all four bits.
    check_len_onehot0: assert property (
        @(posedge clk) $onehot0(len)
    );

// If ir[1:0]==2'b00 then len[0] must be 1 (covers (ir|4'b1100)==4'b1100 case).
    check_len0_when_low10: assert property (
        @(posedge clk) ((ir[1] == 1'b0) && (ir[0] == 1'b0)) |-> (len[0] == 1'b1)
    );

// If ir[3]==1 and ir[1]==0 then len[0] must be 1 (covers (ir|4'b0101)==4'b1101 case).
    check_len0_when_ir3_high_ir1_low: assert property (
        @(posedge clk) ((ir[3] == 1'b1) && (ir[1] == 1'b0)) |-> (len[0] == 1'b1)
    );

// Specific mapping: ir==3 -> len==4'b1000; ir==2 -> 0100; ir==1 -> 0010.
    check_ir_eq_3_maps_to_len_1000: assert property (
        @(posedge clk) (ir == 4'b0011) |-> (len == 4'b1000)
    );

check_ir_eq_2_maps_to_len_0100: assert property (
        @(posedge clk) (ir == 4'b0010) |-> (len == 4'b0100)
    );

check_ir_eq_1_maps_to_len_0010: assert property (
        @(posedge clk) (ir == 4'b0001) |-> (len == 4'b0010)
    );

// For all other ir values, len must be 4'b0000.
    check_len0000_else: assert property (
        @(posedge clk)
            !((ir == 4'b0011) || (ir == 4'b0010) || (ir == 4'b0001) ||
              ((ir | 4'b0101) == 4'b1101) || ((ir | 4'b1100) == 4'b1100))
            |-> (len == 4'b0000)
    );

// c matches exact concatenation: {abs(a-b), min(a,b)}
    check_exact_concat: assert property (
        @(posedge CLK) c == { ((a >= b) ? (a - b) : (b - a)), ((a >= b) ? b : a) }
    );

// When a >= b, upper byte equals a - b
    check_upper_when_ge: assert property (
        @(posedge CLK) (a >= b) |-> (c[15:8] == (a - b))
    );

// When a >= b, lower byte equals b
    check_lower_when_ge: assert property (
        @(posedge CLK) (a >= b) |-> (c[7:0] == b)
    );

// When a < b, upper byte equals b - a
    check_upper_when_lt: assert property (
        @(posedge CLK) (a < b) |-> (c[15:8] == (b - a))
    );

// When a < b, lower byte equals a
    check_lower_when_lt: assert property (
        @(posedge CLK) (a < b) |-> (c[7:0] == a)
    );

// If a == b, upper byte is 0 and lower byte equals a
    check_zero_when_equal: assert property (
        @(posedge CLK) (a == b) |-> (c == {8'h00, a})
    );

// Lower byte equals one of the inputs (min(a,b))
    check_lower_is_input: assert property (
        @(posedge CLK) (c[7:0] == a) || (c[7:0] == b)
    );

// Lower byte is less than or equal to both inputs
    check_lower_is_min_inequality: assert property (
        @(posedge CLK) (c[7:0] <= a) && (c[7:0] <= b)
    );

// Upper byte equals absolute difference |a - b|
    check_upper_is_absdiff: assert property (
        @(posedge CLK) c[15:8] == ((a >= b) ? (a - b) : (b - a))
    );

// Sum of upper and lower bytes equals max(a,b)
    check_sum_equals_max: assert property (
        @(posedge CLK) (c[15:8] + c[7:0]) == ((a >= b) ? a : b)
    );

// No reset in DUT; pure combinational logic; assertions sample on CLK.
    // Behavior: ctrl[3:0] selects left shift by 0..14; ctrl==15 forces zero.

    // ctrl==0: pass-through.
    check_ctrl0_passthrough: assert property (
        @(posedge CLK) (ctrl == 4'd0) |-> (data_out == (data_in << 0))
    );

// ctrl==1: shift left by 1, zero-fill.
    check_ctrl1_shift1: assert property (
        @(posedge CLK) (ctrl == 4'd1) |-> (data_out == (data_in << 1))
    );

// ctrl==2: shift left by 2, zero-fill.
    check_ctrl2_shift2: assert property (
        @(posedge CLK) (ctrl == 4'd2) |-> (data_out == (data_in << 2))
    );

// ctrl==3: shift left by 3, zero-fill.
    check_ctrl3_shift3: assert property (
        @(posedge CLK) (ctrl == 4'd3) |-> (data_out == (data_in << 3))
    );

// ctrl==4: shift left by 4, zero-fill.
    check_ctrl4_shift4: assert property (
        @(posedge CLK) (ctrl == 4'd4) |-> (data_out == (data_in << 4))
    );

// ctrl==5: shift left by 5, zero-fill.
    check_ctrl5_shift5: assert property (
        @(posedge CLK) (ctrl == 4'd5) |-> (data_out == (data_in << 5))
    );

// ctrl==6: shift left by 6, zero-fill.
    check_ctrl6_shift6: assert property (
        @(posedge CLK) (ctrl == 4'd6) |-> (data_out == (data_in << 6))
    );

// ctrl==7: shift left by 7, zero-fill.
    check_ctrl7_shift7: assert property (
        @(posedge CLK) (ctrl == 4'd7) |-> (data_out == (data_in << 7))
    );

// ctrl==8: shift left by 8, zero-fill.
    check_ctrl8_shift8: assert property (
        @(posedge CLK) (ctrl == 4'd8) |-> (data_out == (data_in << 8))
    );

// ctrl==9: shift left by 9, zero-fill.
    check_ctrl9_shift9: assert property (
        @(posedge CLK) (ctrl == 4'd9) |-> (data_out == (data_in << 9))
    );

// ctrl==10: shift left by 10, zero-fill.
    check_ctrl10_shift10: assert property (
        @(posedge CLK) (ctrl == 4'd10) |-> (data_out == (data_in << 10))
    );

// ctrl==11: shift left by 11, zero-fill.
    check_ctrl11_shift11: assert property (
        @(posedge CLK) (ctrl == 4'd11) |-> (data_out == (data_in << 11))
    );

// ctrl==12: shift left by 12, zero-fill.
    check_ctrl12_shift12: assert property (
        @(posedge CLK) (ctrl == 4'd12) |-> (data_out == (data_in << 12))
    );

// ctrl==13: shift left by 13, zero-fill.
    check_ctrl13_shift13: assert property (
        @(posedge CLK) (ctrl == 4'd13) |-> (data_out == (data_in << 13))
    );

// ctrl==14: shift left by 14, zero-fill.
    check_ctrl14_shift14: assert property (
        @(posedge CLK) (ctrl == 4'd14) |-> (data_out == (data_in << 14))
    );

// ctrl==15: force zero output (as coded).
    check_ctrl15_zero: assert property (
        @(posedge CLK) (ctrl == 4'd15) |-> (data_out == 16'h0000)
    );

// Analysis: no clock/reset in DUT; pure combinational; X = A | B | C | D.

    // X equals the bitwise OR of A,B,C,D every cycle.
    check_x_equals_or: assert property (
        @(posedge clk) X === (A | B | C | D)
    );

// All inputs 0 implies X is 0.
    check_all_zero_implies_x_zero: assert property (
        @(posedge clk) (A === 1'b0 && B === 1'b0 && C === 1'b0 && D === 1'b0) |-> (X === 1'b0)
    );

// A=1 drives X=1.
    check_a_one_implies_x_one: assert property (
        @(posedge clk) (A === 1'b1) |-> (X === 1'b1)
    );

// B=1 drives X=1.
    check_b_one_implies_x_one: assert property (
        @(posedge clk) (B === 1'b1) |-> (X === 1'b1)
    );

// C=1 drives X=1.
    check_c_one_implies_x_one: assert property (
        @(posedge clk) (C === 1'b1) |-> (X === 1'b1)
    );

// D=1 drives X=1.
    check_d_one_implies_x_one: assert property (
        @(posedge clk) (D === 1'b1) |-> (X === 1'b1)
    );

// X=0 implies all inputs are 0.
    check_x_zero_implies_all_zero: assert property (
        @(posedge clk) (X === 1'b0) |-> (A === 1'b0 && B === 1'b0 && C === 1'b0 && D === 1'b0)
    );

// X=1 implies at least one input is 1.
    check_x_one_implies_any_one: assert property (
        @(posedge clk) (X === 1'b1) |-> (A === 1'b1 || B === 1'b1 || C === 1'b1 || D === 1'b1)
    );

// Output equals in0 when sel1=0 and sel0=0.
    check_out_sel00: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel1 && !sel0) |-> (out == in0)
    );

// Output equals in1 when sel1=0 and sel0=1.
    check_out_sel01: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel1 && sel0) |-> (out == in1)
    );

// Output equals in2 when sel1=1 and sel0=0.
    check_out_sel10: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel1 && !sel0) |-> (out == in2)
    );

// Output equals in3 when sel1=1 and sel0=1.
    check_out_sel11: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel1 && sel0) |-> (out == in3)
    );

// Output matches the RTL ternary expression for all select combinations.
    check_out_expr_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn)
            out == ( (sel1 & sel0) ? in3
                  : (sel1 & ~sel0) ? in2
                  : (~sel1 & sel0) ? in1
                  : in0 )
    );

///// Output Y behavior w.r.t. D while in ABC_STATE (Y==1) /////
    // If Y is HIGH and D is LOW, Y stays HIGH next cycle.
    check_y_holds_when_D_low: assert property (
        @(posedge clk) (Y && (D == 1'b0)) |=> (Y == 1'b1)
    );

// If Y is HIGH and D is HIGH, Y goes LOW next cycle.
    check_y_clears_on_D_high: assert property (
        @(posedge clk) (Y && (D == 1'b1)) |=> (Y == 1'b0)
    );

///// Change constraints for Y /////
    // Y cannot fall unless D was HIGH in the prior cycle.
    check_y_no_fall_without_D: assert property (
        @(posedge clk) (D == 1'b0) |=> (!$fell(Y))
    );

// Y cannot rise unless C was HIGH in the prior cycle.
    check_y_no_rise_without_C: assert property (
        @(posedge clk) (C == 1'b0) |=> (!$rose(Y))
    );

// When both C and D are LOW, Y does not change next cycle.
    check_y_stable_when_C_D_low: assert property (
        @(posedge clk) ((C == 1'b0) && (D == 1'b0)) |=> $stable(Y)
    );

// If Y is LOW and C is LOW, it stays LOW next cycle (cannot enter ABC without C).
    check_y_low_holds_when_C_low: assert property (
        @(posedge clk) ((Y == 1'b0) && (C == 1'b0)) |=> (Y == 1'b0)
    );

// out_xor equals bitwise XOR of in1 and in2.
    check_out_xor_computation: assert property (
        @(posedge clk) out_xor == (in1 ^ in2)
    );

// out_and equals bitwise AND of in1, in2, and in3.
    check_out_and_computation: assert property (
        @(posedge clk) out_and == (in1 & in2 & in3)
    );

// out_final updates to prior-cycle (out_xor + out_and).
    check_out_final_pipeline_from_internal: assert property (
        @(posedge clk) 1'b1 |=> (out_final == $past(out_xor + out_and))
    );

// out_final updates to prior-cycle ((in1 ^ in2) + (in1 & in2 & in3)).
    check_out_final_pipeline_from_inputs: assert property (
        @(posedge clk) 1'b1 |=> (out_final == $past((in1 ^ in2) + (in1 & in2 & in3)))
    );

// out_and only has 1s where all inputs have 1s.
    check_out_and_subset_of_inputs: assert property (
        @(posedge clk) ((out_and & ~in1) == 8'h00) && ((out_and & ~in2) == 8'h00) && ((out_and & ~in3) == 8'h00)
    );

// If out_xor and out_and are zero, out_final becomes zero next cycle.
    check_out_final_zero_propagation: assert property (
        @(posedge clk) ((out_xor == 8'h00) && (out_and == 8'h00)) |=> (out_final == 8'h00)
    );

// Output matches the RTL's piecewise function for all input combinations.
    check_functional_spec: assert property (
        @(posedge clk)
        fifo_wrptr_inc == ( (ge3_free && (input_tm_cnt == 2'd3)) ? 4'd3 :
                            (ge2_free && (input_tm_cnt >= 2'd2)) ? 4'd2 :
                            (input_tm_cnt >= 2'd1)               ? 4'd1 :
                                                                     4'd0 )
    );

// Output is always in the set {0,1,2,3}.
    check_output_range: assert property (
        @(posedge clk) fifo_wrptr_inc inside {4'd0, 4'd1, 4'd2, 4'd3}
    );

// When input_tm_cnt is 0, increment is 0.
    check_tm_cnt0_zero: assert property (
        @(posedge clk) (input_tm_cnt == 2'd0) |-> (fifo_wrptr_inc == 4'd0)
    );

// When input_tm_cnt is 1, increment is 1 (independent of ge2_free/ge3_free).
    check_tm_cnt1_one: assert property (
        @(posedge clk) (input_tm_cnt == 2'd1) |-> (fifo_wrptr_inc == 4'd1)
    );

// When input_tm_cnt is 2 and ge2_free is true, increment is 2.
    check_tm_cnt2_ge2_true: assert property (
        @(posedge clk) (input_tm_cnt == 2'd2) && ge2_free |-> (fifo_wrptr_inc == 4'd2)
    );

// When input_tm_cnt is 2 and ge2_free is false, increment is 1.
    check_tm_cnt2_ge2_false: assert property (
        @(posedge clk) (input_tm_cnt == 2'd2) && !ge2_free |-> (fifo_wrptr_inc == 4'd1)
    );

// When input_tm_cnt is 3 and ge3_free is true, increment is 3 (highest priority).
    check_tm_cnt3_ge3_true: assert property (
        @(posedge clk) (input_tm_cnt == 2'd3) && ge3_free |-> (fifo_wrptr_inc == 4'd3)
    );

// When input_tm_cnt is 3, ge3_free is false, and ge2_free is true, increment is 2.
    check_tm_cnt3_ge2_only_yields_two: assert property (
        @(posedge clk) (input_tm_cnt == 2'd3) && !ge3_free && ge2_free |-> (fifo_wrptr_inc == 4'd2)
    );

// When input_tm_cnt is 3 and both ge3_free and ge2_free are false, increment is 1.
    check_tm_cnt3_no_free_yields_one: assert property (
        @(posedge clk) (input_tm_cnt == 2'd3) && !ge3_free && !ge2_free |-> (fifo_wrptr_inc == 4'd1)
    );

// S==2'b10 selects B to Y.
    check_s10_selects_B: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y == B)
    );

// S==2'b01 selects C to Y.
    check_s01_selects_C: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y == C)
    );

// When S bits are equal (00 or 11), Y equals D.
    check_equal_bits_select_D: assert property (
        @(posedge clk) (S[1] == S[0]) |-> (Y == D)
    );

// Y matches the combinational function implemented by the RTL.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((S == 2'b10) ? ((S == 2'b00) ? A : B) : ((S == 2'b01) ? C : D))
    );

// When S != 2'b10, Y follows (S==01)?C:D.
    check_not_10_branch: assert property (
        @(posedge clk) (S != 2'b10) |-> (Y == ((S == 2'b01) ? C : D))
    );

// When S == 2'b10, Y follows (S==00)?A:B (which simplifies to B).
    check_10_branch: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y == ((S == 2'b00) ? A : B))
    );

// sum[2] XOR sum[1] equals b[2].
    check_sum2_diff_b2: assert property (
        @(posedge clk) (sum[2] ^ sum[1]) == b[2]
    );

// sum[3] XOR sum[2] equals b[3].
    check_sum3_diff_b3: assert property (
        @(posedge clk) (sum[3] ^ sum[2]) == b[3]
    );

// When reset is asserted (low) at a clock edge, q must be zero.
    reset_forces_zero: assert property (
        @(posedge clk) (!rst) |-> (q == 4'd0)
    );

// On reset deassertion ($rose of rst), q becomes 1 (increment from 0).
    deassertion_sets_one: assert property (
        @(posedge clk) $rose(rst) |-> (q == 4'd1)
    );

// In non-reset, if q is 0 now, it must have wrapped from 15 last cycle.
    nonreset_zero_implies_wrap: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && (q == 4'd0)) |-> ($past(rst) && ($past(q) == 4'd15))
    );

// In non-reset, if q is 2..15 now, last q must be q-1.
    nonreset_mid_values_step: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && (q inside {[4'd2:4'd15]})) |-> ($past(rst) && ($past(q) == (q - 4'd1)))
    );

// In non-reset, if last q was 0, current q must be 1.
    nonreset_prev_zero_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && $past(rst) && ($past(q) == 4'd0)) |-> (q == 4'd1)
    );

// In non-reset, if last q was 15, current q is either 0 (wrap) or 1 (if async reset glitched between edges).
    nonreset_prev_fifteen_results_0_or_1: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && $past(rst) && ($past(q) == 4'd15)) |-> (q inside {4'd0, 4'd1})
    );

// Combinational DUT; assertions sample on CLK and are disabled when RESETn=0.

    // X equals A | B | ~C_N | ~D_N.
    check_or_function: assert property (
        @(posedge CLK) disable iff (!RESETn)
            X == (A | B | ~C_N | ~D_N)
    );

// In add mode, result equals A+B (4-bit modulo).
    function_add_if_mode0: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b0) |-> (result == (A + B))
    );

// In subtract mode, result equals A-B (4-bit modulo).
    function_sub_if_mode1: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b1) |-> (result == (A - B))
    );

// B==0 leaves result equal to A for both modes.
    identity_B_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 4'h0) |-> (result == A)
    );

// In add mode with A==0, result equals B.
    add_identity_A_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b0 && A == 4'h0) |-> (result == B)
    );

// In subtract mode with A==B, result is zero.
    sub_zero_when_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b1 && (A == B)) |-> (result == 4'h0)
    );

// In add mode with B==0xF, result is A-1 (mod 16).
    add_B_F_decrement: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b0 && B == 4'hF) |-> (result == (A - 4'h1))
    );

// In add mode, (result - B) equals A (mod 16).
    add_inverse_mod_check: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b0) |-> ((result - B) == A)
    );

// In subtract mode, (result + B) equals A (mod 16).
    sub_inverse_mod_check: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b1) |-> ((result + B) == A)
    );

// In subtract mode, result equals A + (~B + 1) (two's complement).
    twos_complement_equivalence_sub: assert property (
        @(posedge CLK) disable iff (!RESETn) (mode == 1'b1) |-> (result == (A + (~B + 4'b0001)))
    );

// Q equals D from the previous clock edge (1-cycle latency of DFF).
    check_q_captures_prev_d: assert property (
        @(posedge CLK) 1'b1 |=> (Q == $past(D))
    );

///// Reset behavior /////
    // While reset is HIGH on a clock edge, count is 0.
    reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// If reset stays HIGH across consecutive cycles, count remains 0.
    zero_held_during_continuous_reset: assert property (
        @(posedge clk) reset && $past(reset) |-> (count == 4'd0) && ($past(count) == 4'd0)
    );

// Functional equivalence for out_and to pairwise AND then combine.
    check_out_and_truth: assert property (
        @(posedge CLK) disable iff (!RESETn)
        out_and == ((in[0] & in[1]) & (in[2] & in[3]))
    );

// Functional equivalence for out_or to pairwise OR then combine.
    check_out_or_truth: assert property (
        @(posedge CLK) disable iff (!RESETn)
        out_or == ((in[0] | in[1]) | (in[2] | in[3]))
    );

// Functional equivalence for out_xor to pairwise XOR then combine.
    check_out_xor_truth: assert property (
        @(posedge CLK) disable iff (!RESETn)
        out_xor == ((in[0] ^ in[1]) ^ (in[2] ^ in[3]))
    );

// If all inputs are 1, out_and must be 1.
    check_all_ones_implies_and: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (&in) |-> (out_and == 1'b1)
    );

// If out_and is 1, all inputs must be 1.
    check_and_implies_all_ones: assert property (
        @(posedge CLK) disable iff (!RESETn)
        out_and |-> (&in)
    );

// If out_or is 0, all inputs must be 0.
    check_or_zero_implies_all_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (out_or == 1'b0) |-> (~|in)
    );

// If any input is 1, out_or must be 1.
    check_any_one_implies_or: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (|in) |-> (out_or == 1'b1)
    );

// out_and being 1 implies out_or is 1.
    check_and_implies_or: assert property (
        @(posedge CLK) disable iff (!RESETn)
        out_and |-> (out_or == 1'b1)
    );

// out_and being 1 implies out_xor is 0.
    check_and_implies_xor_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        out_and |-> (out_xor == 1'b0)
    );

// All zeros on input force all outputs to expected zeros.
    check_all_zero_outputs_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (in == 4'b0000) |-> (out_and == 1'b0 && out_or == 1'b0 && out_xor == 1'b0)
    );

///// Combinational function checks /////
    // Y equals the OR of A1,A2,A3,B[1],B[0].
    check_y_is_or_of_all: assert property (
        @(posedge CLK) Y == (A1 || A2 || A3 || B[1] || B[0])
    );

// When any A is 1, Y must be 1.
    check_y_one_when_any_A: assert property (
        @(posedge CLK) (A1 || A2 || A3) |-> (Y == 1'b1)
    );

// When all A are 0, Y equals OR of B.
    check_y_uses_B_when_As_zero: assert property (
        @(posedge CLK) (!A1 && !A2 && !A3) |-> (Y == (B[1] || B[0]))
    );

// Y is 0 only when all inputs are 0.
    check_y_zero_only_when_all_zero: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (!A1 && !A2 && !A3 && (B[1] == 1'b0) && (B[0] == 1'b0))
    );

// With all A=0 and B!=0, Y must be 1.
    check_y_one_when_B_nonzero_and_As_zero: assert property (
        @(posedge CLK) (!A1 && !A2 && !A3 && (B != 2'b00)) |-> (Y == 1'b1)
    );

// With all inputs 0, Y must be 0.
    check_y_zero_when_all_inputs_zero: assert property (
        @(posedge CLK) (!A1 && !A2 && !A3 && (B == 2'b00)) |-> (Y == 1'b0)
    );

// A1 high forces Y high.
    check_y_forced_one_by_A1: assert property (
        @(posedge CLK) A1 |-> (Y == 1'b1)
    );

// A2 high with A1 low forces Y high.
    check_y_forced_one_by_A2_when_A1_zero: assert property (
        @(posedge CLK) (A2 && !A1) |-> (Y == 1'b1)
    );

// A3 high with A1,A2 low forces Y high.
    check_y_forced_one_by_A3_when_A1_A2_zero: assert property (
        @(posedge CLK) (A3 && !A2 && !A1) |-> (Y == 1'b1)
    );

// If B==0 and Y==1, at least one A must be 1.
    check_y_one_with_b_zero_implies_some_A_one: assert property (
        @(posedge CLK) (Y && (B == 2'b00)) |-> (A1 || A2 || A3)
    );

// Exactly one of gt/lt/eq must be HIGH for any a,b.
    outputs_onehot: assert property (
        @(posedge CLK) disable iff (1'b0) $onehot({gt, lt, eq})
    );

// When a > b, outputs must be gt=1, lt=0, eq=0.
    a_gt_b_sets_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) (a > b) |-> (gt && !lt && !eq)
    );

// When a < b, outputs must be gt=0, lt=1, eq=0.
    a_lt_b_sets_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) (a < b) |-> (!gt && lt && !eq)
    );

// When a == b, outputs must be gt=0, lt=0, eq=1.
    a_eq_b_sets_outputs: assert property (
        @(posedge CLK) disable iff (1'b0) (a == b) |-> (!gt && !lt && eq)
    );

// If gt is HIGH, then a > b.
    gt_means_a_gt_b: assert property (
        @(posedge CLK) disable iff (1'b0) gt |-> (a > b)
    );

// If lt is HIGH, then a < b.
    lt_means_a_lt_b: assert property (
        @(posedge CLK) disable iff (1'b0) lt |-> (a < b)
    );

// If eq is HIGH, then a == b.
    eq_means_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) eq |-> (a == b)
    );

// When a >= b, lt must be LOW.
    no_lt_when_a_ge_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a >= b) |-> (!lt)
    );

// When a <= b, gt must be LOW.
    no_gt_when_a_le_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a <= b) |-> (!gt)
    );

// When a != b, eq must be LOW.
    no_eq_when_a_ne_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a != b) |-> (!eq)
    );

///// Button priority and LED pattern /////
    // If btn0 is high, next cycle LEDs are 0,1,1,1 (highest priority).
    check_btn0_sets_leds: assert property (
        @(posedge clk) (btn0 == 1'b1) |=> (led0 == 1'b0 && led1 == 1'b1 && led2 == 1'b1 && led3 == 1'b1)
    );

// If btn1 is high and btn0 is low, next cycle LEDs are 1,0,1,1.
    check_btn1_sets_leds_when_btn0_low: assert property (
        @(posedge clk) (btn0 == 1'b0 && btn1 == 1'b1) |=> (led0 == 1'b1 && led1 == 1'b0 && led2 == 1'b1 && led3 == 1'b1)
    );

// If btn2 is high and higher-priority buttons are low, next cycle LEDs are 1,1,0,1.
    check_btn2_sets_leds_when_higher_low: assert property (
        @(posedge clk) (btn0 == 1'b0 && btn1 == 1'b0 && btn2 == 1'b1) |=> (led0 == 1'b1 && led1 == 1'b1 && led2 == 1'b0 && led3 == 1'b1)
    );

// If btn3 is high and others are low, next cycle LEDs are 1,1,1,0.
    check_btn3_sets_leds_when_others_low: assert property (
        @(posedge clk) (btn0 == 1'b0 && btn1 == 1'b0 && btn2 == 1'b0 && btn3 == 1'b1) |=> (led0 == 1'b1 && led1 == 1'b1 && led2 == 1'b1 && led3 == 1'b0)
    );

