    );

// F=1 when ABCD=1101
    check_map_1101: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1101) |-> (F == 1'b1)
    );

// F=1 when ABCD=1110
    check_map_1110: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1110) |-> (F == 1'b1)
    );

// F=0 when ABCD=1111
    check_map_1111: assert property (
